}

MemoryManager* init_memory_manager(size_t record_count) {
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->total_memory_usage = sizeof(Record) * record_count;
    manager->max_record_count = record_count;
    manager->max_value_encountered = 0.0;

    size_t max_double_range = fetch_max_double_range_from_external_source();
    if (check_memory_limit(manager->total_memory_usage, MAX_MEMORY_USAGE)) {
        printf("Warning: Approaching memory usage limit!\n");
