    srand((unsigned)time(NULL));

    manager->records = malloc(sizeof(Record) * record_count);
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        manager->records[i].offset = rand() % 1000000L; // Dummy offset
        manager->records[i].key = rand() % 10000;       // Dummy key
        manager->records[i].value = (double)(rand() % ((int)max_double_range + 1));

        if (manager->records[i].value > manager->max_value_encountered) {
            manager->max_value_encountered = manager->records[i].value;
        }
    }

    return manager;
}

void serialize_records_to_file(MemoryManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&manager->max_record_count, sizeof(size_t), 1, file);
    fwrite(&manager->max_value_encountered, sizeof(double), 1, file);

    size_t record_size = sizeof(Record) * manager->max_record_count;
    if (fwrite(manager->records, record_size, 1, file) != 1) {
        perror("Failed to write records to file");
    }

    fclose(file);
}

void cleanup_memory_manager(MemoryManager* manager) {
    free(manager->records);
    free(manager);
}

int main() {
    size_t record_count = 1000;
    MemoryManager* manager = init_memory_manager(record_count);

    if (manager) {
        serialize_records_to_file(manager, "records.dat");
        cleanup_memory_manager(manager);
    }

    return 0;
}
