void print_usage() {
    printf("Usage: file_processor [options] <file1> [<file2> ...]\n"
           "Options:\n"
           "  -h          Display this help message and exit.\n"
           "  -m          Enable memory optimization mode.\n"
           "  -c          Count lines in each file.\n"
           "  -s <size>   Generate a summary of the given size from each file.\n"
           "  -o <file>   Output results to a specified file.\n");
}

void *process_file(void *arg) {
    FileData *data = (FileData *)arg;
    FILE *fp = fopen(data->filename, "rb");
    if (!fp) {
        log_message("Error opening file");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    size_t bytes_read;
    long line_count = 0;
    int word_freq[256] = {0};
    size_t summary_size = data->summary_size;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, fp)) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') line_count++;
            if (isalpha(buffer[i])) word_freq[toupper(buffer[i])]++;
        }
    }

    fclose(fp);

    data->line_count = line_count;
    memcpy(data->word_freq, word_freq, sizeof(word_freq));

    return NULL;
}

void summarize_file(const char *filename, size_t summary_size) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        log_message("Error opening file for summarization");
        return;
    }

    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    size_t bytes_to_read = (filesize < summary_size * BUFFER_SIZE) ? filesize : summary_size * BUFFER_SIZE;
    char buffer[bytes_to_read];

    fread(buffer, 1, bytes_to_read, fp);
    fwrite(buffer, 1, bytes_to_read, stdout);

    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;
    int count_lines = 0;
    size_t summary_size = 1024;
    const char *output_file = NULL;

    while ((opt = getopt(argc, argv, "hmc:s:o:")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return 0;
            case 'm':
                // Memory optimization mode
                break;
            case 'c':
                count_lines = 1;
                break;
            case 's':
                summary_size = atol(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                print_usage();
                return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Expected argument after options\n");
        print_usage();
        return 1;
    }

    pthread_t threads[argc - optind];
    FileData file_data[argc - optind];

    for (int i = 0; i < argc - optind; ++i) {
        file_data[i].filename = argv[optind + i];
        file_data[i].summary_size = summary_size;
        pthread_create(&threads[i], NULL, process_file, &file_data[i]);
    }

    for (int i = 0; i < argc - optind; ++i) {
        pthread_join(threads[i], NULL);
        if (count_lines) {
            printf("File: %s, Lines: %ld\n", file_data[i].filename, file_data[i].line_count);
        }
    }

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            log_message("Error opening output file");
            return 1;
        }
        for (int i = 0; i < argc - optind; ++i) {
            fprintf(out, "File: %s\n", file_data[i].filename);
            for (int j = 0; j < 256; ++j) {
                if (file_data[i].word_freq[j]) {
                    fprintf(out, "%c: %d\n", j, file_data[i].word_freq[j]);
                }
            }
        }
        fclose(out);
    }

    return 0;
}
