// Define internal DNS mapping (simulate)
const char* dns_map[] = {
    "localhost", "127.0.0.1",
    // Add more host mappings as needed
};

char* resolve_dns(const char *hostname) {
    static const int map_size = sizeof(dns_map) / sizeof(dns_map[0]);
    for (int i = 0; i < map_size; i += 2) {
        if (strcmp(hostname, dns_map[i]) == 0)
            return strdup(dns_map[i + 1]);
    }
    return NULL;
}

// Check if file path is within allowed directories
int is_path_allowed(const char *path) {
    // Define allowed paths (e.g., only allow local files in a specific directory)
    const char* allowed_prefix = "./configurations/";
    return strncmp(path, allowed_prefix, strlen(allowed_prefix)) == 0;
}

// Read file and compute average of last two numbers
void process_file(const char *filepath) {
    if (!is_path_allowed(filepath)) {
        fprintf(stderr, "Error: Unauthorized access to file path.\n");
        exit(EXIT_FAILURE);
    }

    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        size_t len = strlen(line);
        if (line[len - 1] == '\n') {
            line[--len] = '\0'; // Remove newline character
        }

        // Allocate memory for the modified line
        char *processed_line = malloc(len + sizeof(double) * 10); // Extra space for average and possible spaces.
        if (!processed_line) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        strcpy(processed_line, line);

        int num_count = 0;
        double last_two[2] = {0.0};
        char *token = strtok(line, " ");
        while (token != NULL) {
            if (num_count >= 2) {
                free(last_two);
                last_two = malloc(sizeof(double) * 2);
                if (!last_two) {
                    perror("Memory allocation failed");
                    exit(EXIT_FAILURE);
                }
            }
            double num = atof(token);
            if (num_count > 0 && num_count <= 2)
                last_two[num_count - 1] = num;
            token = strtok(NULL, " ");
            num_count++;
        }

        if (num_count >= 2) {
            double average = (last_two[0] + last_two[1]) / 2.0;
            char avg_str[32];
            snprintf(avg_str, sizeof(avg_str), " %.2f", average);

            strcat(processed_line, avg_str);

            free(last_two);
        }

        printf("%s\n", processed_line); // Print CSV line
        free(processed_line); // Free the allocated memory for processed line
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_file(argv[1]);

    // Example of DNS resolution
    char *ip_address = resolve_dns("localhost");
    if (ip_address) {
        printf("Resolved IP Address for localhost: %s\n", ip_address);
        free(ip_address); // Free the allocated memory from strdup
    } else {
        fprintf(stderr, "Error resolving DNS.\n");
    }

    return EXIT_SUCCESS;
}
