#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *array;
    size_t used;
    size_t capacity;
    int largest;
    double sum;
} IntStreamProcessor;

void initIntStreamProcessor(IntStreamProcessor *processor) {
    processor->capacity = 10; // Initial capacity
    processor->used = 0;
    processor->sum = 0.0;
    processor->largest = INT_MIN; // Smallest possible integer

    processor->array = (int *)malloc(processor->capacity * sizeof(int));
    if (!processor->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void resizeArray(IntStreamProcessor *processor) {
    size_t new_capacity = processor->capacity * 2;
    int *new_array = (int *)realloc(processor->array, new_capacity * sizeof(int));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(processor->array);
        exit(EXIT_FAILURE);
    }
    processor->array = new_array;
    processor->capacity = new_capacity;
}

void processIntStream() {
    IntStreamProcessor processor;
    initIntStreamProcessor(&processor);

    int input;
    while (scanf("%d", &input) == 1 || getchar() != '\n') { // Handle spaces and multiple inputs
        if (getchar() == 'q' && input == 0) break; // End of stream

        processor.sum += input;

        if (processor.used == processor.capacity) {
            resizeArray(&processor);
        }

        processor.array[processor.used++] = input;

        if (input > processor.largest) {
            processor.largest = input;
        }
    }

    double average = processor.used ? processor.sum / processor.used : 0.0;

    printf("Largest: %d\n", processor.largest);
    printf("Average: %.2f\n", average);

    free(processor.array);
}

int main() {
    processIntStream();
    return 0;
}
