#define MAX_LOG_SIZE 1024
#define RATE_LIMIT_MESSAGES 10

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    char *message;
    LogLevel level;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    pthread_mutex_t lock;
    LogEntry *head;
    int message_count;
    time_t last_reset_time;
} NodeLogQueue;

NodeLogQueue* create_log_queue() {
    NodeLogQueue *queue = (NodeLogQueue *)malloc(sizeof(NodeLogQueue));
    if (!queue) return NULL;

    pthread_mutex_init(&queue->lock, NULL);
    queue->head = NULL;
    queue->message_count = 0;
    queue->last_reset_time = time(NULL);

    return queue;
}

void destroy_log_queue(NodeLogQueue *queue) {
    LogEntry *current = queue->head;
    while (current) {
        LogEntry *next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

void log_message(NodeLogQueue *queue, LogLevel level, const char *format, ...) {
    if (!queue) return;

    time_t now = time(NULL);
    pthread_mutex_lock(&queue->lock);

    // Rate limiting
    if (now - queue->last_reset_time > 1) {
        queue->message_count = 0;
        queue->last_reset_time = now;
    }

    if (queue->message_count >= RATE_LIMIT_MESSAGES) {
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) {
        pthread_mutex_unlock(&queue->lock);
        return;
    }

    va_list args;
    va_start(args, format);
    entry->message = (char *)malloc(MAX_LOG_SIZE);
    vsnprintf(entry->message, MAX_LOG_SIZE, format, args);
    va_end(args);

    entry->timestamp = now;
    entry->level = level;
    entry->next = queue->head;
    queue->head = entry;

    // Simulate sending to external logging service
    if (send_to_logging_service(level, entry->message)) {
        // Successfully sent, remove from queue
        LogEntry *temp = queue->head;
        queue->head = temp->next;
        free(temp->message);
        free(temp);
    } else {
        // Handle retry logic or failure case
    }

    queue->message_count++;
    pthread_mutex_unlock(&queue->lock);
}

int send_to_logging_service(LogLevel level, const char *message) {
