['Below is a modular C library designed to manage named semaphores for resource locking in a multi-threaded application:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <unistd.h>

#define MAX_SEMAPHORES 1024
#define LOG_FILE "semaphores.log"

typedef struct {
    sem_t *sem;
    char name[256];
} NamedSemaphore;

typedef struct {
    NamedSemaphore semaphores[MAX_SEMAPHORES];
    int count;
    pthread_mutex_t lock;
} SemaphoreManager;

// Function Prototypes
void init_semaphore_manager(SemaphoreManager *manager);
int add_semaphore(SemaphoreManager *manager, const char *name, unsigned int initial_value);
int remove_semaphore(SemaphoreManager *manager, const char *name);
int acquire_semaphore(NamedSemaphore *sem, int blocking);
int release_semaphore(NamedSemaphore *sem);
void cleanup_semaphore_manager(SemaphoreManager *manager);
void log_message(const char *message);

// Function Implementations
void init_semaphore_manager(SemaphoreManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
}

int add_semaphore(SemaphoreManager *manager, const char *name, unsigned int initial_value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SEMAPHORES) {
        log_message("Maximum semaphores reached.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(manager->semaphores[i].name, name) == 0) {
            log_message("Semaphore already exists.");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    NamedSemaphore *new_sem = &manager->semaphores[manager->count++];
    sem_init(new_sem->sem, 0, initial_value);
    strncpy(new_sem->name, name, sizeof(new_sem->name) - 1);

    log_message("Semaphore added.");
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_semaphore(SemaphoreManager *manager, const char *name) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(manager->semaphores[i].name, name) == 0) {
            sem_destroy(manager->semaphores[i].sem);
            memmove(&manager->semaphores[i], &manager->semaphores[i + 1],
                    (manager->count - i - 1) * sizeof(NamedSemaphore));
            manager->count--;
            log_message("Semaphore removed.");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    log_message("Semaphore not found.");
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int acquire_semaphore(NamedSemaphore *sem, int blocking) {
    if (blocking) {
        sem_wait(sem->sem);
    } else {
        if (sem_trywait(sem->sem) != 0) {
            log_message("Failed to acquire semaphore.");
            return -1;
        }
    }
    return 0;
}

int release_semaphore(NamedSemaphore *sem) {
    sem_post(sem->sem);
    return 0;
}

void cleanup_semaphore_manager(SemaphoreManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        sem_destroy(manager->semaphores[i].sem);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Example usage
int main() {
    SemaphoreManager manager;
    init_semaphore_manager(&manager);

    add_semaphore(&manager, "resource1", 1);
    NamedSemaphore *sem = &manager.semaphores[0];

    acquire_semaphore(sem, 1); // Blocking acquisition
    release_semaphore(sem);

    remove_semaphore(&manager, "resource1");
    cleanup_semaphore_manager(&manager);

    return 0;
}
```

### Key Features:
- **Initialization**: Initializes a semaphore manager to handle semaphores.
- **Dynamic Management**: Supports adding and removing semaphores at runtime.
- **Thread Safety**: Uses mutexes for thread-safe operations on the semaphore list.
- **Resource Cleanup**: Destroys semaphores upon removal or during cleanup.
- **Logging**: Logs actions to a file for debugging and monitoring.
- **Scalability**: Designed to manage up to `MAX_SEMAPHORES` efficiently. Adjust this value based on system constraints.

### Considerations:
- Ensure that the semaphore manager is initialized at application startup.
- Handle errors gracefully, especially during dynamic operations like adding/removing semaphores.
- Integrate with external configuration systems as needed for dynamic settings loading.']

