#[derive(Debug)]
enum ParseError {
    Io(std::io::Error),
    InvalidFormat(String),
}

impl From<std::io::Error> for ParseError {
    fn from(error: std::io::Error) -> Self {
        ParseError::Io(error)
    }
}

// Caching layer
struct ConfigCache {
    cache: Mutex<HashMap<String, Arc<Config>>>,
    seen_versions: Mutex<HashSet<String>>,
}

impl ConfigCache {
    fn new() -> Self {
        Self { 
            cache: Mutex::new(HashMap::new()), 
            seen_versions: Mutex::new(HashSet::new()) 
        }
    }

    fn get_or_update(&self, path: &str) -> Result<Arc<Config>, ParseError> {
        let mut cache = self.cache.lock().unwrap();
        let config_path = format!("{}.json", path);

        if let Some(config) = cache.get(&config_path.to_string()) {
