#include <forward_list>
#include <chrono>
#include <mutex>

std::mutex mtx; // Mutex to ensure thread safety

void updateOrAppend(std::forward_list<int>& flist, int target, int replacement, int maxTimeMs) {
    auto startTime = std::chrono::high_resolution_clock::now();
    bool found = false;

    {
        std::lock_guard<std::mutex> lock(mtx); // Lock to ensure thread safety
        for (auto it = flist.begin(); it != flist.end() && !found; ++it) {
            if (std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::high_resolution_clock::now() - startTime)
                .count() >= maxTimeMs) {
                // Time limit reached, exit loop
                break;
            }
            if (*it == target) {
                *it = replacement;
                found = true;
            }
        }

        if (!found) {
            flist.push_front(replacement);
        }
    } // Mutex is automatically released here

    // Note: The above code handles the time constraint within the loop.
    // It also ensures thread safety by using a mutex lock when accessing
    // and modifying the forward list. This prevents race conditions where 
    // multiple threads might modify the list concurrently.
}
