using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;
using System.Xml.XPath;

public static class ConfigurationUtility
{
    private static readonly string ConfigFilePath = "config.xml";

    public static Dictionary<string, string> LoadConfiguration()
    {
        var configSettings = new Dictionary<string, string>();

        try
        {
            if (File.Exists(ConfigFilePath))
            {
                XDocument doc = XDocument.Load(ConfigFilePath);

                foreach (var element in doc.XPathSelectElements("/configuration/settings/setting"))
                {
                    var key = element.Attribute("name")?.Value;
                    var value = element.Value;

                    if (!string.IsNullOrWhiteSpace(key) && !configSettings.ContainsKey(key))
                        configSettings[key] = Environment.GetEnvironmentVariable(value) ?? value;
                }
            }

            // Load environment variables that are not in the XML
            foreach (var envVar in Environment.GetEnvironmentVariables())
            {
                var key = envVar.Key as string;
                if (!string.IsNullOrWhiteSpace(key) && !configSettings.ContainsKey(key))
                    configSettings[key] = envVar.Value as string;
            }
        }
        catch (Exception ex)
        {
            LogError("Failed to load configuration", ex);
        }

        return configSettings;
    }

    public static bool ValidateConfiguration(Dictionary<string, string> configSettings)
    {
        // Example validation: check if log directory exists
        if (!configSettings.TryGetValue("LogDirectory", out var logDir) || !Directory.Exists(logDir))
            return false;

        return true;
    }

    public static void SaveConfiguration(Dictionary<string, string> updatedSettings)
    {
        try
        {
            XDocument doc = XDocument.Load(ConfigFilePath);

            foreach (var setting in doc.XPathSelectElements("/configuration/settings/setting"))
            {
                var key = setting.Attribute("name")?.Value;

                if (key != null && updatedSettings.ContainsKey(key))
                    setting.Value = updatedSettings[key];
            }

            // Add any new settings
            foreach (var setting in updatedSettings)
            {
                if (!doc.XPathSelectElements($"/configuration/settings/setting[@name='{setting.Key}']").Any())
                {
                    doc.Root.Add(
                        new XElement("setting", 
                            new XAttribute("name", setting.Key), 
                            new XCData(setting.Value))
                    );
                }
            }

            doc.Save(ConfigFilePath);
        }
        catch (Exception ex)
        {
            LogError("Failed to save configuration", ex);
        }
    }

    public static void EnsureLogDirectory()
    {
        if (!LoadConfiguration().TryGetValue("LogDirectory", out var logDir) || string.IsNullOrWhiteSpace(logDir))
        {
            logDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "logs");

            try
            {
                Directory.CreateDirectory(logDir);
                SaveConfiguration(new Dictionary<string, string> { { "LogDirectory", logDir } });
            }
            catch (Exception ex)
            {
                LogError("Failed to create log directory", ex);
            }
        }

        // Check if the path is unique and handle race conditions
        var lockFilePath = Path.Combine(logDir, ".lock");

        try
        {
            using (var mutex = new Mutex(true, $"Global\\{Path.GetFileNameWithoutExtension(lockFilePath)}"))
            {
                if (!File.Exists(lockFilePath))
                    File.WriteAllText(lockFilePath, "locked");

                // Perform logging operations here safely

                // Remove lock file after use
                if (File.Exists(lockFilePath))
                    File.Delete(lockFilePath);
            }
        }
        catch (Exception ex)
        {
            LogError("Failed to ensure log directory uniqueness", ex);
        }
    }

    private static void LogError(string message, Exception ex)
    {
        // Implement logging logic here
        Console.WriteLine($"{message}: {ex.Message}");
    }

    public static void MonitorConfigurationChanges()
    {
        FileSystemWatcher watcher = new FileSystemWatcher(Path.GetDirectoryName(ConfigFilePath))
        {
            Filter = Path.GetFileName(ConfigFilePath),
            NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.FileName
        };

        watcher.Changed += (sender, args) => LoadConfiguration();

        watcher.EnableRaisingEvents = true;
    }
}
