void refreshDialogFields(std::forward_list<std::string>& fields, const std::string& resourceID, const std::string& url) {
    if (fields.empty()) return;

    const std::vector<std::string> fieldNamesToRefresh = {"Name", "Email", "Phone", "Address"};
    auto it = fields.begin();

    bool firstStringMatched = false;

    for (const auto& fieldName : fieldNamesToRefresh) {
        if (*it == fieldName) {
            std::string updatedValue;
            bool updateSuccessful = requestUpdateFromParent(fieldName, resourceID, url, updatedValue);

            if (updateSuccessful && it != fields.before_begin()) {
                *it = updatedValue;  // Update the field in place
                firstStringMatched = true;
            }
        }

        ++it; // Move to the next element in the list
    }

    // If the first string doesn't match any known field names, append second argument
    if (!firstStringMatched && !fields.front().empty()) {
        fields.push_back(url);
    }
}
