const { Transform, pipeline } = require('stream');
const { promisify } = require('util');
const os = require('os');

// Promisified pipeline for async/await usage
const pipelineAsync = promisify(pipeline);

class DynamicBuffer extends Transform {
    constructor(options) {
        super({ objectMode: true, ...options });
        this.bufferSize = 1024 * 1024; // Initial buffer size in bytes
        this.memoryUsageThreshold = os.totalmem() * 0.8;
    }

    _transform(chunk, encoding, callback) {
        const currentMemoryUsage = process.memoryUsage().heapUsed;

        // Dynamically adjust the buffer size based on memory usage
        if (currentMemoryUsage > this.memoryUsageThreshold) {
            this.bufferSize = Math.max(this.bufferSize / 2, 1024 * 256); // Minimum buffer size
        } else {
            this.bufferSize = Math.min(this.bufferSize * 1.5, 1024 * 1024 * 10); // Maximum buffer size
        }

        // Buffer management logic
        if (Buffer.concat([this._readableState.buffer, chunk]).length > this.bufferSize) {
            callback(new Error('Buffer overflow'));
            return;
        }

        this.push(chunk);
        callback();
    }
}

class FailoverStream extends Transform {
    constructor(options) {
        super({ objectMode: true, ...options });
        this.retryCount = 0;
    }

    _transform(chunk, encoding, callback) {
        try {
            // Simulate processing and failover logic
            if (this.shouldFail()) {
                throw new Error('Simulated stream failure');
            }
            this.retryCount = 0; // Reset on success
            this.push(chunk);
        } catch (error) {
            if (this.retryCount < 3) {
                this.retryCount++;
                console.log(`Retrying... Attempt ${this.retryCount}`);
                this._transform(chunk, encoding, callback); // Retry logic
            } else {
                console.error('Stream failed after retries:', error);
                callback(error);
            }
        } finally {
            callback();
        }
    }

    shouldFail() {
        return Math.random() < 0.1; // Simulate a 10% failure rate
    }
}

// Metrics monitoring
class MetricsTracker extends Transform {
    constructor(options) {
        super({ objectMode: true, ...options });
        this.processedBytes = 0;
    }

    _transform(chunk, encoding, callback) {
        this.processedBytes += chunk.length;
        console.log(`Processed bytes: ${this.processedBytes}`);
        this.push(chunk);
        callback();
    }
}

async function processStreams(inputStreams) {
    try {
        for (const stream of inputStreams) {
            await pipelineAsync(
                stream,
                new DynamicBuffer(),
                new FailoverStream(),
                new MetricsTracker(),
                process.stdout // Output the final result
            );
        }
    } catch (error) {
        console.error('Pipeline failed:', error);
    }
}

// Example usage with dummy data streams
const { Readable } = require('stream');
const inputStreams = [
    Readable.from([Buffer.from('Stream 1 data'), Buffer.from('More stream 1 data')]),
    Readable.from(['Stream 2 text', 'More stream 2 text'])
];

processStreams(inputStreams);
```

