(function() {
    const loadScript = (url) => {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = url;
            script.async = true;

            script.onload = () => resolve(url);
            script.onerror = () => reject(new Error(`Failed to load script: ${url}`));

            document.head.appendChild(script);
        });
    };

    const modifyFilename = (filename, digitSeq) => {
        const parts = filename.split('.');
        const baseName = parts[0];
        const ext = parts[1] || '';

        return `${baseName}-${digitSeq}.${ext}`;
    };

    const fetchAndExecuteScripts = async (scriptUrls) => {
        const results = [];
        for (let url of scriptUrls) {
            try {
                const response = await fetch(url, { mode: 'no-cors' });
                if (!response.ok) throw new Error(`Failed to fetch: ${url}`);

                const blob = await response.blob();
                const reader = new FileReader();

                reader.onloadend = () => {
                    const scriptBlobUrl = URL.createObjectURL(blob);
                    loadScript(scriptBlobUrl)
                        .then(() => {
                            console.log(`Successfully executed: ${scriptBlobUrl}`);
                            URL.revokeObjectURL(scriptBlobUrl);
                        })
                        .catch(err => console.error(`Error executing script: ${err.message}`));
                };

                reader.onerror = () => {
                    console.error(`Failed to read file from blob: ${url}`);
                };

                reader.readAsText(blob);
            } catch (error) {
                console.error(error.message);
            }
        }
    };

    const loadScriptsWithSequencing = async (urls, importanceOrder) => {
        const sortedUrls = urls.sort((a, b) => 
            importanceOrder.indexOf(b.split('/').pop()) - importanceOrder.indexOf(a.split('/').pop())
        );

        let digitSeq = 1;
        for (let url of sortedUrls) {
            const newFilename = modifyFilename(url.split('/').pop(), digitSeq);
            digitSeq++;
            await fetchAndExecuteScripts([`${url}?v=${newFilename}`]);
        }
    };

    // Example usage
    const scriptUrls = [
        'https://example.com/script1.js',
        'https://example.com/script2.js',
        // Add more URLs as needed
    ];

    const importanceOrder = ['script1.js', 'script2.js'];  // Define order of importance

    loadScriptsWithSequencing(scriptUrls, importanceOrder)
        .catch(err => console.error('Script loading failed:', err.message));
})();
