import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class FileMetadata {
    private final Path path;
    private final boolean isExecutable;
    private final long lastAccessTime;

    public FileMetadata(Path path, boolean isExecutable, long lastAccessTime) {
        this.path = path;
        this.isExecutable = isExecutable;
        this.lastAccessTime = lastAccessTime;
    }

    public Path getPath() { return path; }
    public boolean isExecutable() { return isExecutable; }
    public long getLastAccessTime() { return lastAccessTime; }
}

class FileCache {
    private final Map<Path, FileMetadata> cache = new ConcurrentHashMap<>();
    private final int maxEntries;

    public FileCache(int maxEntries) {
        this.maxEntries = maxEntries;
    }

    public Optional<FileMetadata> get(Path path) {
        return Optional.ofNullable(cache.get(path));
    }

    public void put(FileMetadata metadata) {
        if (cache.size() >= maxEntries) {
            cache.values().stream()
                .min(Comparator.comparingLong(FileMetadata::getLastAccessTime))
                .ifPresent(evicted -> cache.remove(evicted.getPath()));
        }
        cache.put(metadata.getPath(), metadata);
    }
}

class RemoteConfigService {
    public List<Path> getFilePaths() throws IOException, ServiceUnavailableException {
        // Simulate fetching file paths from a remote service
        return Arrays.asList(
            Paths.get("/path/to/executable1"),
            Paths.get("/path/to/nonexecutable"),
            Paths.get("/another/path/to/invalidfile")
        );
    }
}

class ServiceUnavailableException extends Exception {}

public class FilePathProcessor {

    private final RemoteConfigService configService;
    private final FileCache fileCache;

    public FilePathProcessor(RemoteConfigService configService, int cacheSize) {
        this.configService = configService;
        this.fileCache = new FileCache(cacheSize);
    }

    public Map<String, Object> processExecutablePaths() {
        long startTime = System.currentTimeMillis();
        List<Path> filePaths = Collections.emptyList();
        int validCount = 0;
        int invalidCount = 0;
        int networkCalls = 0;

        try {
            filePaths = configService.getFilePaths();
        } catch (IOException | ServiceUnavailableException e) {
            logError("Failed to fetch file paths", e);
        }

        for (Path path : filePaths) {
            long validationStart = System.currentTimeMillis();

            FileMetadata metadata = fileCache.get(path)
                .orElseGet(() -> fetchFileMetadata(path));

            if (metadata != null) {
                try {
                    if (metadata.isExecutable()) validCount++;
                    else invalidCount++;
                } catch (SecurityException e) {
                    logError("Permission issue for path: " + path, e);
                    invalidCount++;
                }
            }

            long validationTime = System.currentTimeMillis() - validationStart;
            logInfo("Validation time for " + path + ": " + validationTime + " ms");
        }

        long totalTime = System.currentTimeMillis() - startTime;
        Map<String, Object> summary = new HashMap<>();
        summary.put("validExecutableCount", validCount);
        summary.put("invalidExecutableCount", invalidCount);
        summary.put("networkCallsMade", networkCalls);
        summary.put("totalProcessingTimeMs", totalTime);

        return summary;
    }

    private FileMetadata fetchFileMetadata(Path path) {
        long lastAccessTime = 0L;

        try {
            lastAccessTime = Files.getLastModifiedTime(path).toMillis();
            boolean isExecutable = Files.isReadable(path) &&
                                   PosixFilePermissions.toString(Files.getPosixFilePermissions(path))
                                       .contains("x");
            FileMetadata metadata = new FileMetadata(path, isExecutable, lastAccessTime);
            fileCache.put(metadata);
            return metadata;
        } catch (IOException e) {
            logError("Failed to fetch metadata for path: " + path, e);
            return null;
        }
    }

    private void logInfo(String message) {
        System.out.println(message);
    }

    private void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
    }
}
