import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.inject.Inject;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
@EnableScheduling
public class ServiceLifecycleManager {

    private static final Logger LOGGER = Logger.getLogger(ServiceLifecycleManager.class.getName());

    @Autowired
    private NotificationService notificationService;

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    private ExecutorService executorService;
    private ScheduledExecutorService scheduledExecutorService;

    public static void main(String[] args) {
        SpringApplication.run(ServiceLifecycleManager.class, args);
    }

    @PostConstruct
    public void init() {
        int corePoolSize = Runtime.getRuntime().availableProcessors();
        executorService = Executors.newFixedThreadPool(corePoolSize);
        scheduledExecutorService = Executors.newScheduledThreadPool(corePoolSize);

        LOGGER.log(Level.INFO, "Service Lifecycle Manager Initialized");
    }

    public void startService(Runnable serviceTask) {
        executorService.submit(serviceTask);
        LOGGER.log(Level.INFO, "Service Started");
    }

    public void stopService() throws InterruptedException {
        scheduledExecutorService.schedule(() -> {
            notificationService.notifyStop();
            LOGGER.log(Level.INFO, "Service Stopped");
        }, 0, TimeUnit.MILLISECONDS);

        // Implement graceful shutdown
        executorService.shutdown();
        if (!executorService.awaitTermination(10, TimeUnit.SECONDS)) {
            executorService.shutdownNow();
            if (!executorService.awaitTermination(5, TimeUnit.SECONDS))
                LOGGER.log(Level.SEVERE, "Executor service did not terminate");
        }
    }

    public void scheduleTask(Runnable task, long delay, TimeUnit unit) {
        scheduledExecutorService.schedule(task, delay, unit);
    }

    @Component
    static class NotificationService {

        private final RestTemplate restTemplate;

        @Inject
        public NotificationService(RestTemplate restTemplate) {
            this.restTemplate = restTemplate;
        }

        public void notifyStop() {
            try {
                // Assume 'brokerUrl' is configured externally
                String brokerUrl = "http://example-broker-url";
                restTemplate.postForObject(brokerUrl + "/notify", null, String.class);
                LOGGER.log(Level.INFO, "Notification Sent");
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Failed to send notification", e);
            }
        }
    }

    @Component
    static class ConfigService {

        // Load configuration dynamically; placeholder for implementation

        public void updateConfig() {
            // Logic to refresh config
            LOGGER.log(Level.INFO, "Configuration Updated");
        }
    }

    // Placeholder for third-party logging integration
    @Component
    static class LoggingService {

        public void log(String message) {
            // Integration with an external logging service (e.g., ELK, Splunk)
            LOGGER.log(Level.INFO, message);
        }
    }
}
```

### Explanation:
- **Executor Service**: Manages concurrent tasks using a fixed thread pool for both start and stop operations to ensure efficient resource utilization.
- **Scheduled Executor Service**: Used for scheduling repeated service lifecycle events with configurable delays.
- **NotificationService**: Integrates with an external messaging broker, handling notification sending upon stop events.
- **ConfigService & LoggingService**: Represent placeholders for dynamic configuration updates and third-party logging integration.
- **Spring Boot Annotations**: `@SpringBootApplication`, `@EnableScheduling` are used to simplify application setup and scheduling tasks. 
- The design assumes integration with external services (e.g., messaging brokers, logging) through REST templates or similar APIs.

This code is modular, allowing for easy updates and maintenance while providing a framework that can be expanded upon for more complex requirements like load balancing and fault tolerance as needed.']

