use Symfony\Component\Yaml\Yaml;
use JsonSchema\Validator;
use JsonSchema\SchemaLoader;

function loadConfig($filePath) {
    $config = [];
    if (file_exists($filePath)) {
        $ext = pathinfo($filePath, PATHINFO_EXTENSION);
        if ($ext === 'json') {
            $config = json_decode(file_get_contents($filePath), true);
        } elseif ($ext === 'yaml' || $ext === 'yml') {
            $config = Yaml::parseFile($filePath);
        }
    }
    return $config;
}

function validateConfig($data, $schema) {
    $validator = new Validator();
    $validator->validate($data, (new SchemaLoader())->load(json_decode(file_get_contents($schema))));
    if (!$validator->isValid()) {
        throw new Exception('Configuration validation failed: ' . json_encode($validator->getErrors()));
    }
}

