import requests
import time
from functools import lru_cache
import logging
import json

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

CACHE_UPDATE_INTERVAL = 3600  # seconds
RETRY_LIMIT = 5
BACKOFF_FACTOR = 1.5

def exponential_backoff(retry_count):
    return BACKOFF_FACTOR ** retry_count

@lru_cache(maxsize=128)
def get_cached_product_details(cache_key, last_update_time):
    current_time = time.time()
    if (current_time - last_update_time) > CACHE_UPDATE_INTERVAL:
        cache.clear()
    return cache.get(cache_key)

def set_cached_product_details(cache_key, data):
    cache[cache_key] = {
        'data': data,
        'timestamp': time.time(),
    }

class APIClient:
    BASE_URL = "https://api.onlinestore.com/products"

    def __init__(self):
        self.session = requests.Session()

    def fetch_product_details(self, category=None, brand=None, min_stock=0):
        params = {}
        if category:
            params['category'] = category
        if brand:
            params['brand'] = brand
        if min_stock > 0:
            params['minStock'] = min_stock

        for attempt in range(RETRY_LIMIT):
            try:
                response = self.session.get(self.BASE_URL, params=params)
                response.raise_for_status()

                # Check API response format and handle anomalies
                data = response.json()
                if 'products' not in data:
                    logger.error("Unexpected response structure: %s", json.dumps(data))
                    continue

                products = [
                    product for product in data['products']
                    if product.get('stock', 0) >= min_stock
                ]

                return products

            except requests.exceptions.HTTPError as e:
                logger.error("HTTP error occurred: %s", str(e))
                time.sleep(exponential_backoff(attempt))

            except requests.exceptions.RequestException as e:
                logger.error("Request exception: %s", str(e))
                if attempt < RETRY_LIMIT - 1:
                    time.sleep(exponential_backoff(attempt))
                else:
                    raise

def get_product_details(category=None, brand=None, min_stock=0):
    api_client = APIClient()

    cache_key = (category, brand, min_stock)
    last_update_time = get_cached_product_details(cache_key, 0)['timestamp']

    products = get_cached_product_details(cache_key, last_update_time)

    if not products:
        try:
            products = api_client.fetch_product_details(category, brand, min_stock)
            set_cached_product_details(cache_key, products)

        except Exception as e:
            logger.error("Failed to fetch product details: %s", str(e))
            return []

    return products

# Cache storage
cache = {}

