["```javascript
const axios = require('axios');
const fs = require('fs');
const { Transform } = require('stream');

class Pauser extends Transform {
  constructor(options) {
    super({ ...options, readableObjectMode: true });
    this.paused = false;
    this.queue = [];
  }

  _transform(chunk, encoding, callback) {
    if (this.paused) {
      this.queue.push(callback);
      return;
    }

    process.nextTick(() => callback(null, chunk));
  }

  pauseStream() {
    this.paused = true;
  }

  resumeStream() {
    this.paused = false;
    while (this.queue.length > 0 && !this.paused) {
      const cb = this.queue.shift();
      process.nextTick(cb);
    }
  }
}

async function getPrivateKeyAndCertificate(oAuthToken, scope) {
  try {
    const endpointResponse = await axios.post('https://api.example.com/get-endpoint', { token: oAuthToken, scope });
    const endpoint = endpointResponse.data.endpoint;

    const credentialsResponse = await axios.get(endpoint, { headers: { Authorization: `Bearer ${oAuthToken}` } });
    const privateKeyPem = credentialsResponse.data.privateKey;
    const certificatePem = credentialsResponse.data.certificate;

    return {
      privateKeyPem,
      certificatePem
    };
  } catch (error) {
    console.error('Error fetching private key and certificate:', error);
    throw error;
  }
}

async function processAndCacheData(oAuthToken, scope, dataUrl) {
  const { privateKeyPem, certificatePem } = await getPrivateKeyAndCertificate(oAuthToken, scope);

  const cacheFile = './cache.pem';
  fs.writeFileSync(cacheFile, `${privateKeyPem}\n${certificatePem}`);

  const pauser = new Pauser();

  const responseStream = axios({
    method: 'get',
    url: dataUrl,
    responseType: 'stream'
  }).data;

  responseStream.pipe(pauser);

  pauser.on('data', (chunk) => {
    console.log(`Processing chunk of size ${chunk.length}`);
    // Process the chunk if needed
  });

  pauser.on('end', () => {
    console.log('All data processed');
  });

  return {
    pauseStream: () => pauser.pauseStream(),
    resumeStream: () => pauser.resumeStream()
  };
}

module.exports = { processAndCacheData };
