<?php
session_start();

function authenticateUserWithOAuth($clientId, $clientSecret, $authUrl, $tokenUrl, $userInfoEndpoint) {
    if (isset($_SESSION['access_token']) && $_SESSION['expires_at'] > time()) {
        return fetchUserInfo($_SESSION['access_token'], $userInfoEndpoint);
    }

    try {
        $authResponse = file_get_contents($authUrl . "?response_type=code&client_id=" . urlencode($clientId));
        parse_str(parse_url($authResponse, PHP_URL_QUERY), $queryParams);

        if (isset($queryParams['code'])) {
            $tokenPayload = [
                'grant_type' => 'authorization_code',
                'code' => $queryParams['code'],
                'redirect_uri' => 'YOUR_REDIRECT_URI', // Replace with your redirect URI
                'client_id' => $clientId,
                'client_secret' => $clientSecret
            ];

            $ch = curl_init($tokenUrl);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($tokenPayload));
            $response = curl_exec($ch);

            if ($response === false) {
                throw new Exception('Curl error: ' . curl_error($ch));
            }

            $data = json_decode($response, true);

            $_SESSION['access_token'] = $data['access_token'];
            $_SESSION['expires_at'] = time() + $data['expires_in'];

            return fetchUserInfo($_SESSION['access_token'], $userInfoEndpoint);
        }
    } catch (Exception $e) {
        // Handle network timeouts or other exceptions
        error_log('OAuth Error: ' . $e->getMessage());
        return null;
    }

    return false;
}

function fetchUserInfo($accessToken, $userInfoEndpoint) {
    try {
        $ch = curl_init($userInfoEndpoint);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_HTTPHEADER, ['Authorization: Bearer ' . $accessToken]);

        $response = curl_exec($ch);

        if ($response === false) {
            throw new Exception('Curl error fetching user info: ' . curl_error($ch));
        }

        return json_decode($response, true);
    } catch (Exception $e) {
        // Handle network timeouts or other exceptions
        error_log('UserInfo Fetch Error: ' . $e->getMessage());
        return null;
    }
}
?>
