### C Function: DNS Resolution

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_RETRIES 3
#define IP_BUFFER_SIZE 16 // Enough for IPv4

u_char* resolveHostname(const char *hostname, int retries) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ipBuffer[IP_BUFFER_SIZE];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use AF_INET6 for IPv6
    hints.ai_socktype = SOCK_STREAM;

    retries = (retries > MAX_RETRIES) ? MAX_RETRIES : retries;

    while (retries-- > 0) {
        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                void *addr = &((struct sockaddr_in *)p->ai_addr)->sin_addr;

                if (inet_ntop(p->ai_family, addr, ipBuffer, IP_BUFFER_SIZE) != NULL) {
                    freeaddrinfo(res);
                    return strdup(ipBuffer); // Duplicate string for safety
                }
            }
        }

        freeaddrinfo(res);
    }

    fprintf(stderr, "DNS resolution failed for %s\n", hostname);
    return NULL;
}

int main() {
    const char *hostname = "example.com";
    u_char* ipAddr = resolveHostname(hostname, 3);

    if (ipAddr) {
        printf("IP Address: %s\n", ipAddr);
        free(ipAddr); // Free the allocated memory
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
```

**Notes:**
- The PHP function includes session handling, error logging, and network operations using cURL.
- The C function performs DNS resolution with retry logic and uses `inet_ntop` for IP address conversion.']

