struct OctreeNode {
    bool isLeaf;
    int featureSize;
    std::unique_ptr<OctreeNode> children[8];
};

class Octree {
public:
    static constexpr size_t MAX_MEMORY_THRESHOLD = 1024 * 1024 * 512; // Example: 512 MB

    Octree(int featureSize, int numLeafNodes, size_t dataCapacity)
        : root_(nullptr), featureSize_(featureSize), numLeafNodes_(numLeafNodes),
          dataCapacity_(dataCapacity) {

        if (featureSize <= 0) throw std::invalid_argument("Feature size must be positive.");
        if (numLeafNodes <= 0) throw std::invalid_argument("Number of leaf nodes must be positive.");

        try {
            root_ = new OctreeNode();
            initializeOctree(root_, featureSize, numLeafNodes);
        } catch (...) {
            delete root_;
            root_ = nullptr;
            throw std::runtime_error("Failed to allocate memory for octree.");
        }
    }

    ~Octree() {
        deleteNode(root_);
    }

    void insertData(const std::vector<float>& data) {
        if (data.size() != featureSize_) throw std::invalid_argument("Invalid data size.");

        std::lock_guard<std::mutex> lock(mutex_); // Ensures thread safety
        insertRecursive(root_, data, 0);
    }

private:
    OctreeNode* root_;
    int featureSize_;
    int numLeafNodes_;
    size_t dataCapacity_;
    std::mutex mutex_;

    void initializeOctree(OctreeNode*& node, int depth, int remainingNodes) {
        if (depth == 0 || remainingNodes <= 1) {
            node->isLeaf = true;
            return;
        }

        node->isLeaf = false;
        for (int i = 0; i < 8; ++i) {
            node->children[i] = std::make_unique<OctreeNode>();
            initializeOctree(node->children.get() + i, depth - 1, remainingNodes / 8);
        }
    }

    void insertRecursive(OctreeNode* node, const std::vector<float>& data, int depth) {
        if (node->isLeaf || depth == featureSize_) return;

        // Determine which child to descend into
        int index = 0;
        for (int i = 0; i < featureSize_; ++i) {
            if (data[i] >= threshold(depth)) { // Define `threshold` as needed
                index |= 1 << i;
            }
        }

        insertRecursive(node->children[index].get(), data, depth + 1);
    }

    void deleteNode(OctreeNode* node) {
        if (!node) return;
        for (auto& child : node->children) {
            deleteNode(child.get());
        }
    }

    bool checkMemoryUsage() const {
        // Implement a function to estimate current memory usage and compare with MAX_MEMORY_THRESHOLD
        size_t estimatedUsage = 0; // Calculate based on nodes and data structures
        return estimatedUsage <= MAX_MEMORY_THRESHOLD;
    }

    float threshold(int depth) const {
        // Define your threshold logic here, possibly using featureSize_ or other parameters.
        return 0.5f;
    }
};

int main() {
    try {
        Octree octree(3, 1000, 1024); // Example usage
        std::vector<float> data = {0.1f, 0.2f, 0.3f};
        octree.insertData(data);
        std::cout << "Octree initialized and data inserted successfully." << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
