    std::mutex attackMutex;
    int lastAttackTime[3] = {-9, -7, -12};  // Initial cooldown times to allow immediate use

    struct AttackMetrics {
        int damage;
        float accuracy;
    };

    AttackMetrics metrics[] = {
        {100, 0.75},   // Metrics for ATTACK_A
        {80, 0.85},    // Metrics for ATTACK_B
        {120, 0.65}    // Metrics for ATTACK_C
    };

public:
    void selectAttack() {
        std::lock_guard<std::mutex> lock(attackMutex);

        auto currentTime = getCurrentTimeInSeconds();
        int cooldowns[] = {9, 7, 12};

        AttackType bestAttack = ATTACK_A;
        double highestScore = -1.0;

        for (int i = 0; i < 3; ++i) {
            if (currentTime >= lastAttackTime[i] + cooldowns[i]) {
                double score = calculateAttackScore(metrics[i]);
                if (score > highestScore) {
                    highestScore = score;
                    bestAttack = static_cast<AttackType>(i);
                }
            }
        }

        performAttack(bestAttack);
    }

private:
    int getCurrentTimeInSeconds() {
        using namespace std::chrono;
        return duration_cast<seconds>(
            system_clock::now().time_since_epoch()
        ).count();
    }

    double calculateAttackScore(const AttackMetrics& metric) {
        // Example scoring mechanism: prioritize damage but consider accuracy
        return metric.damage * metric.accuracy;
    }

    void performAttack(AttackType attack) {
        std::cout << "Performing attack type: " << attack << "\n";
        lastAttackTime[attack] = getCurrentTimeInSeconds();

        // Simulate performing the attack (e.g., applying damage)
    }
};

int main() {
