public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private static readonly HttpClient client = new HttpClient();

    public RandomValueGenerator()
    {
        InitializeRangeFromAPI().Wait();
    }

    private async Task InitializeRangeFromAPI()
    {
        try
        {
            string responseString = await client.GetStringAsync("https://example.com/api/range"); // Replace with actual API endpoint
            var json = JObject.Parse(responseString);
            minValue = (float)json["min"];
            maxValue = (float)json["max"];

            if (minValue > maxValue)
            {
                throw new ArgumentException("minValue cannot be greater than maxValue.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error initializing range: {ex.Message}");
            // Handle initialization error, e.g., set default values or rethrow
            minValue = 0.0f;
            maxValue = 1.0f; // Default fallback values
        }
    }

    public float GetRandomFloatInclusive()
    {
        if (minValue == maxValue)
            return minValue;

        Random rand = new Random();
        float range = maxValue - minValue;
        return minValue + (float)rand.NextDouble() * range;
    }

    public float GetRandomFloatExclusive()
    {
        if (minValue >= maxValue)
            throw new InvalidOperationException("Range is invalid for exclusive random generation.");

        Random rand = new Random();
        float range = maxValue - minValue;
        return minValue + (float)(rand.NextDouble() * range) + 0.0001f; // Ensure exclusivity
    }

    public int GetRandomIntInclusive()
    {
        int minInt = Mathf.FloorToInt(minValue);
        int maxInt = Mathf.FloorToInt(maxValue);

        if (minInt > maxInt)
            throw new InvalidOperationException("Integer range is invalid.");

        Random rand = new Random();
        return rand.Next(minInt, maxInt + 1);
    }

    public int GetRandomIntExclusive()
    {
        int minInt = Mathf.CeilToInt(minValue); // Ensure exclusivity
        int maxInt = Mathf.FloorToInt(maxValue);

        if (minInt >= maxInt)
            throw new InvalidOperationException("Integer range is invalid for exclusive generation.");

        Random rand = new Random();
        return rand.Next(minInt + 1, maxInt);
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }
}
```

