async function customReduce(array, callback, seed = null) {
    // Helper function to flatten the array recursively
    function* flattenArray(arr) {
        for (const item of arr) {
            if (Array.isArray(item)) {
                yield* flattenArray(item);
            } else {
                yield item;
            }
        }
    }

    // Helper function to filter numeric values and handle division by zero
    async function processElement(currentValue, element) {
        try {
            if (typeof element === 'number' && !isNaN(element)) {
                return await callback(currentValue, element);
            } else {
                console.error(`Non-numeric value filtered out: ${element}`);
                return currentValue;
            }
        } catch (error) {
            console.error(`Error processing element ${element}:`, error);
            return currentValue;
        }
    }

    // Flatten the input array
    const flattenedArray = Array.from(flattenArray(array));

    // Reduce logic
    let result = seed !== null ? seed : 0; // Initialize with seed or default to zero

    for (const element of flattenedArray) {
        if (result !== undefined) { // Ensure we have a valid starting point
            result = await processElement(result, element);
        }
    }

    return result;
}

// Example callback function
async function asyncCallback(accumulator, currentValue) {
    // Simulate asynchronous operation with a delay
    return new Promise((resolve) => {
        setTimeout(() => {
            if (currentValue === 0 && accumulator !== 0) { // Division by zero check
                resolve(0);
            } else {
                resolve(accumulator + currentValue); // Example reduction logic
            }
        }, Math.random() * 100); // Random delay for demonstration
    });
}

// Test cases to validate the function
(async () => {
    const testArray1 = [1, [2, [3, 'a', [4]], 'b'], 5];
    const testArray2 = [[], [0, [undefined, null, []]]];
    const testArray3 = [['x', 'y', ['z']], 10];

    console.log(await customReduce(testArray1, asyncCallback, 0)); // Expected: 15
    console.log(await customReduce(testArray2, asyncCallback, 10)); // Expected: 10 (only zero is filtered)
    console.log(await customReduce(testArray3, asyncCallback));     // Expected: 10 (default seed 0 + 10)
})();
