    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct Collection {
    LinkedList* listArray;
    size_t count;
    pthread_mutex_t lock;
} Collection;

typedef struct ErrorLog {
    char* message;
    struct ErrorLog* next;
} ErrorLog;

Collection* create_collection(size_t initial_size) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->listArray = calloc(initial_size, sizeof(LinkedList));
    if (!collection->listArray) {
        free(collection);
        return NULL;
    }

    collection->count = initial_size;
    pthread_mutex_init(&collection->lock, NULL);

    for (size_t i = 0; i < initial_size; i++) {
        pthread_mutex_init(&collection->listArray[i].lock, NULL);
        collection->listArray[i].head = NULL;
    }

    return collection;
}

ErrorLog* create_error_log(const char* message) {
    ErrorLog* log = malloc(sizeof(ErrorLog));
    if (!log) return NULL;

    log->message = strdup(message);
    log->next = NULL;
    return log;
}

void add_to_error_log(Collection* collection, const char* message) {
    pthread_mutex_lock(&collection->lock);

    ErrorLog* new_log = create_error_log(message);
    if (new_log) {
        new_log->next = collection->error_head;
        collection->error_head = new_log;
    }

    pthread_mutex_unlock(&collection->lock);
}

void load_data_from_file(Collection* collection, const char* filename, size_t index) {
