void iterate_and_process(Collection* collection, void (*process)(Node*)) {
    for (size_t i = 0; i < collection->count; i++) {
        pthread_mutex_lock(&collection->listArray[i].lock);

        Node* current = collection->listArray[i].head;
        while (current) {
            process(current);
            current = current->next;
        }

        pthread_mutex_unlock(&collection->listArray[i].lock);
    }
}

void free_collection(Collection** collection) {
    if (!collection || !*collection) return;

    for (size_t i = 0; i < (*collection)->count; i++) {
        pthread_mutex_lock(&(*collection)->listArray[i].lock);

        Node* current = (*collection)->listArray[i].head;
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&(*collection)->listArray[i].lock);
        pthread_mutex_destroy(&(*collection)->listArray[i].lock);
    }

    free((*collection)->listArray);
    pthread_mutex_destroy(&(*collection)->lock);

    ErrorLog* current_log = (*collection)->error_head;
    while (current_log) {
        ErrorLog* temp_log = current_log;
        current_log = current_log->next;
        free(temp_log->message);
        free(temp_log);
    }

    free(*collection);
    *collection = NULL;
}

