unsigned char* compute_md5_hash(const char *input_string, unsigned int *output_length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input_string, strlen(input_string), (unsigned char*)&digest);

    *output_length = MD5_DIGEST_LENGTH;
    unsigned char *hash_output = malloc(MD5_DIGEST_LENGTH);
    if (!hash_output) return NULL;

    memcpy(hash_output, digest, MD5_DIGEST_LENGTH);

    // Convert binary hash to hexadecimal string
    static char hex_output[MD5_DIGEST_LENGTH*2 + 1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hex_output[i * 2], "%02x", (unsigned int)digest[i]);
    }

    return strdup(hex_output);
}

