#define MAX_PATH_LENGTH 2048
#define MAX_EXTENSION_LENGTH 16
#define MAX_BASE_NAME_LENGTH 255

// Helper function to count vowels in a string
int count_vowels(const char *str) {
    int vowel_count = 0;
    while (*str) {
        if (strchr("aeiouAEIOU", *str)) {
            vowel_count++;
        }
        str++;
    }
    return vowel_count;
}

// Helper function to replace special characters with underscores
void sanitize_basename(char *basename, size_t length) {
    for (size_t i = 0; i < length; i++) {
        if (!isalnum(basename[i])) {
            basename[i] = '_';
        }
    }
}

char* modify_file_extension(const char *file_path) {
    DIR *dir;
    struct dirent *entry;
    char base_name[MAX_BASE_NAME_LENGTH + 1];
    char directory_path[MAX_PATH_LENGTH + 1];
    char extension[9]; // Max 8 chars + null terminator
    int dir_index = strlen(file_path);

    // Find the last occurrence of '/' to separate directory and file name
    while (dir_index > 0 && file_path[dir_index - 1] != '/') {
        --dir_index;
    }

    if (dir_index == 0) return NULL; // No directory found

    // Extract directory path and base filename
    strncpy(directory_path, file_path, dir_index);
    directory_path[dir_index] = '\0';
    strcpy(base_name, file_path + dir_index);

    // Find the last occurrence of '.' to separate base name and extension
    int dot_index = strlen(base_name) - 1;
    while (dot_index > 0 && base_name[dot_index] != '.') {
        --dot_index;
    }

    if (dot_index == 0 || dot_index == strlen(base_name) - 1) {
        // No valid extension found
        strcpy(extension, "newext");
    } else {
        strncpy(extension, base_name + dot_index + 1, 8);
        extension[8] = '\0';
    }

    // Handle the base name length and special characters
    int basename_length = strlen(base_name);
    if (basename_length > MAX_BASE_NAME_LENGTH) {
        basename_length = MAX_BASE_NAME_LENGTH;
    }

    sanitize_basename(base_name, basename_length);

    // Count vowels in the sanitized base name
    int vowel_count = count_vowels(base_name);

    // Construct new extension based on directory content and vowel count
    char new_extension[MAX_EXTENSION_LENGTH + 1];
    snprintf(new_extension, sizeof(new_extension), "ext%d", vowel_count % MAX_EXTENSION_LENGTH);

    // Ensure the new extension is not too long
    if (strlen(new_extension) > MAX_EXTENSION_LENGTH) {
        strncpy(new_extension, "ext", MAX_EXTENSION_LENGTH);
    }

    // Allocate memory for the new file path
    char *new_file_path = malloc(strlen(directory_path) + basename_length + strlen(new_extension) + 2); // +2 for '/' and '\0'
    if (!new_file_path) return NULL;

    // Construct the new file path
    snprintf(new_file_path, strlen(directory_path) + basename_length + strlen(new_extension) + 1,
             "%s/%.*s.%s", directory_path, (int)basename_length, base_name, new_extension);

    return new_file_path;
}

// Example usage
int main() {
    const char *file_path = "/path/to/directory/some_file.txt";
    char *new_path = modify_file_extension(file_path);

    if (new_path) {
        printf("Modified file path: %s\n", new_path);
        free(new_path);
    } else {
        printf("Failed to modify file extension.\n");
    }

    return 0;
}
