#include <openssl/evp.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdio.h>

// Define a mutex for ensuring thread safety when adding ciphers and digests
static pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_crypto() {
    // Logging function
    void log_operation(const char *message) {
        printf("%s\n", message);
    }

    // Helper function to safely add primitives with logging and mutex protection
    int safe_add_primitive(int (*add_func)(const EVP_CIPHER *ciph, const char *name, int blocksize, int ivlen), 
                           const EVP_CIPHER *cipher, const char *name) {
        if (pthread_mutex_lock(&crypto_mutex) != 0) {
            log_operation("Failed to lock mutex");
            return 0;
        }

        int result = add_func(cipher, name, EVP_CIPHER_iv_length(cipher), EVP_CIPHER_block_size(cipher));

        pthread_mutex_unlock(&crypto_mutex);

        if (result == 1) {
            log_operation("Successfully added primitive: ");
            log_operation(name);
        } else {
            log_operation("Failed to add primitive: ");
            log_operation(name);
        }

        return result;
    }

    // Add AES and Camellia block ciphers
    safe_add_primitive(EVP_add_cipher, EVP_aes_128_cbc(), "AES-128-CBC");
    safe_add_primitive(EVP_add_cipher, EVP_aes_256_gcm(), "AES-256-GCM");
    safe_add_primitive(EVP_add_cipher, EVP_camellia_128_cfb8(), "Camellia-128-CFB8");

    // Add MD5 and SHA digests
    safe_add_primitive(EVP_add_digest, EVP_md5(), "MD5");
    safe_add_primitive(EVP_add_digest, EVP_sha1(), "SHA1");
    safe_add_primitive(EVP_add_digest, EVP_sha256(), "SHA256");

    // Add RSA with SHA1
    int rsa = RSA_get_default_method();
    if (rsa == NULL) {
        log_operation("Failed to get default RSA method");
        return;
    }

    const unsigned char *rsa_md5_pss = OBJ_nid2sn(NID_md5WithRSAEncryption);
    if (!EVP_PKEY_assign_RSA(EVP_PKEY_RSA, rsa)) {
        log_operation("Failed to assign RSA");
        return;
    }

    safe_add_primitive(EVP_add_digest, EVP_sha1(), "SHA1");

    // Clean up resources
    pthread_mutex_destroy(&crypto_mutex);
}
```

### Design Decisions:
1. **Thread Safety**: Utilized `pthread_mutex_t` for synchronizing access to the shared OpenSSL context when adding ciphers and digests to prevent race conditions.
2. **Logging**: Implemented a basic logging mechanism using standard output for tracking success or failure of each cryptographic primitive addition.
3. **Performance Optimization**: Minimized overhead by locking only during the critical section where OpenSSL functions are called, reducing contention among threads.
4. **Resource Management**: Ensured proper initialization and cleanup of mutexes to prevent resource leaks.

### Trade-offs:
- **Memory Consumption vs Execution Speed**: The use of a mutex introduces minimal memory usage but can potentially impact execution speed in highly concurrent environments. However, it ensures correctness when adding primitives concurrently.
- **Thread Safety vs Complexity**: Adding thread safety increases code complexity slightly but is necessary for correctness under multi-threaded conditions.

This design focuses on integrating cryptographic primitives into an existing framework while maintaining performance and ensuring safe operation across threads.']

