#define KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} AESContext;

AESContext* init_aes_cipher(const char *password) {
    if (!password || strlen(password) == 0) return NULL;

    unsigned char key[KEY_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);

    AESContext *aes_ctx = (AESContext *)malloc(sizeof(AESContext));
    if (!aes_ctx) return NULL;

    pthread_mutex_init(&aes_ctx->lock, NULL);
    aes_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!aes_ctx->ctx) {
        free(aes_ctx);
        return NULL;
    }

    unsigned char iv[IV_LENGTH];
    if (1 != RAND_bytes(iv, IV_LENGTH)) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(aes_ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
        return NULL;
    }

    return aes_ctx;
}

void cleanup_aes_cipher(AESContext *aes_ctx) {
    if (aes_ctx) {
        pthread_mutex_destroy(&aes_ctx->lock);
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
    }
}

