import java.io.ObjectOutputStream;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DeserializationHelper {
    private static final Logger LOGGER = Logger.getLogger(DeserializationHelper.class.getName());

    public static <T> T loadContentFromSerializedData(byte[] data, Class<T> clazz) {
        if (data == null || clazz == null) return null;

        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInput in = new ObjectInputStream(bis)) {

            // Use a custom stream to handle class version changes
            CustomObjectInputStream cosi = new CustomObjectInputStream(in, clazz);

            @SuppressWarnings("unchecked")
            T result = (T) cosi.readObject();

            return result;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Deserialization failed", e);
            return null;
        }
    }

    private static class CustomObjectInputStream extends ObjectInputStream {

        private final Class<?> expectedClass;

        public CustomObjectInputStream(ObjectInput in, Class<?> expectedClass) throws Exception {
            super(in);
            this.expectedClass = expectedClass;
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc)
                throws IOException, ClassNotFoundException {
            // Check if the class version is compatible
            if (desc.getName().equals(expectedClass.getName())) {
                return expectedClass;
            }
            return super.resolveClass(desc);
        }
    }
}
