#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <fcntl.h>

#define MAX_COMMANDS 10
#define MAX_CONCURRENT_PROCESSES 3
#define LOG_BUFFER_SIZE 4096

volatile sig_atomic_t terminate = 0;

void handle_sigterm(int sig) {
    terminate = 1;
}

void log_message(const char *log_file, const char *message) {
    int fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        return;
    }

    write(fd, message, strlen(message));
    write(fd, "\n", 1);

    close(fd);
}

void execute_command(const char *command, const char *log_file) {
    int pipe_fd[2];
    if (pipe(pipe_fd) == -1) {
        perror("Pipe failed");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();
    if (pid == 0) { // Child process
        close(pipe_fd[0]);

        dup2(pipe_fd[1], STDOUT_FILENO);
        dup2(pipe_fd[1], STDERR_FILENO);
        close(pipe_fd[1]);

        char *args[] = { "/bin/sh", "-c", strdup(command), NULL };
        execvp(args[0], args);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else if (pid > 0) { // Parent process
        close(pipe_fd[1]);

        char buffer[LOG_BUFFER_SIZE];
        ssize_t bytes_read;
        while ((bytes_read = read(pipe_fd[0], buffer, sizeof(buffer) - 1)) > 0) {
            buffer[bytes_read] = '\0';
            log_message(log_file, buffer);
        }
        close(pipe_fd[0]);

        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            char failure_msg[256];
            snprintf(failure_msg, sizeof(failure_msg), "Command failed: %s", command);
            log_message(log_file, failure_msg);
        }
    } else {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    }
}

void manage_commands(const char *commands, const char *log_file) {
    signal(SIGTERM, handle_sigterm);

    char *command_str = strdup(commands);
    if (!command_str) {
        perror("Failed to allocate memory for command string");
        return;
    }

    pid_t pids[MAX_CONCURRENT_PROCESSES] = {0};
    int active_processes = 0;

    char *token = strtok(command_str, ";");
    while (token && !terminate) {
        while (active_processes >= MAX_CONCURRENT_PROCESSES) {
            for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
                if (pids[i] > 0 && waitpid(pids[i], NULL, WNOHANG) > 0) {
                    pids[i] = 0;
                    --active_processes;
                }
            }
        }

        for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
            if (pids[i] == 0) {
                pid_t pid = fork();
                if (pid == 0) { // Child process
                    execute_command(token, log_file);
                    exit(EXIT_SUCCESS);
                } else if (pid > 0) { // Parent process
                    pids[i] = pid;
                    ++active_processes;
                    break;
                } else {
                    perror("Fork failed");
                    free(command_str);
                    return;
                }
            }
        }

        token = strtok(NULL, ";");
    }

    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; ++i) {
        if (pids[i] > 0) {
            kill(pids[i], SIGTERM);
            waitpid(pids[i], NULL, 0);
        }
    }

    free(command_str);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s \"<commands>\" <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    manage_commands(argv[1], argv[2]);

    return EXIT_SUCCESS;
}
