using System.Security.AccessControl;
using System.Security.Principal;

public class WebsiteManager
{
    private readonly ILogger _logger; // Assume an existing logging framework

    public WebsiteManager(ILogger logger)
    {
        _logger = logger;
    }

    public string AddAndStartWebsite(string directoryPath, string siteName)
    {
        if (!IsDirectoryWritable(directoryPath))
        {
            _logger.LogError($"Directory {directoryPath} is not writable.");
            return null;
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigPath) || new FileInfo(webConfigPath).Length == 0)
        {
            _logger.LogError("web.config file does not exist or is empty.");
            return null;
        }

        try
        {
            StartWebsiteProcess(directoryPath, siteName);
            _logger.LogInformation($"Successfully started website '{siteName}' at '{directoryPath}'.");
            return "Site started successfully.";
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to start website '{siteName}': {ex.Message}");
            return $"Error: {ex.Message}";
        }
    }

    private bool IsDirectoryWritable(string directoryPath)
    {
        try
        {
            var tempFilePath = Path.Combine(directoryPath, Guid.NewGuid().ToString());
            File.WriteAllText(tempFilePath, "test");
            File.Delete(tempFilePath);
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error checking write permission for directory '{directoryPath}'. Attempting to modify permissions.");

            var attempts = 0;
            while (attempts < 3)
            {
                try
                {
                    DirectorySecurity security = new DirectorySecurity(directoryPath, AccessControlSections.Access);
                    security.AddAccessRule(new FileSystemAccessRule(
                        WindowsIdentity.GetCurrent().Name,
                        FileSystemRights.Write,
                        InheritanceFlags.ContainerInherit | InheritanceFlags.ObjectInherit,
                        PropagationFlags.None,
                        AccessControlType.Allow));

                    File.WriteAllText(Path.Combine(directoryPath, Guid.NewGuid().ToString()), "test");
                    File.Delete(Path.Combine(directoryPath, Guid.NewGuid().ToString()));
                    return true;
                }
                catch
                {
                    attempts++;
                }
            }

            _logger.LogError($"Failed to acquire write permission for directory '{directoryPath}' after 3 attempts.");
            return false;
        }
    }

    private void StartWebsiteProcess(string directoryPath, string siteName)
    {
        var startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c iisreset /start {siteName}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process())
        {
            process.StartInfo = startInfo;
            try
            {
                process.Start();
                process.WaitForExit();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to start the website process for '{siteName}': {ex.Message}");
                throw; // Re-throwing to be caught by the outer try-catch block in AddAndStartWebsite
            }
        }
    }
}

public interface ILogger
{
    void LogError(Exception exception, string message);
    void LogError(string message);
    void LogInformation(string message);
}
