import java.io.*;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class DynamicJarLoader {

    private static final Logger logger = Logger.getLogger(DynamicJarLoader.class.getName());
    private static URLClassLoader urlClassLoader;

    public static void main(String[] args) {
        if (args.length < 3) {
            System.err.println("Usage: java -jar your_program.jar <JAR_PATH> <CHECKSUM> <LOG_DIRECTORY>");
            return;
        }

        String jarPath = args[0];
        String expectedChecksum = args[1];
        String logDirectory = args[2];

        if (!verifyChecksum(jarPath, expectedChecksum)) {
            downloadJar(jarPath);
            if (!verifyChecksum(jarPath, expectedChecksum)) {
                System.err.println("Failed to verify JAR checksum after download.");
                return;
            }
        }

        try {
            loadAndExecuteMethod(jarPath, "com.example.MyClass", "myMethod");
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error executing method from JAR", e);
        } finally {
            if (urlClassLoader != null) {
                urlClassLoader.close();
                System.gc(); // Suggest garbage collection for unloading the class loader
            }
        }
    }

    private static boolean verifyChecksum(String filePath, String expectedChecksum) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] fileBytes = Files.readAllBytes(Paths.get(filePath));
            byte[] digest = md.digest(fileBytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString().equals(expectedChecksum);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error verifying checksum", e);
            return false;
        }
    }

    private static void downloadJar(String jarPath) {
        String url = "https://example.com/path/to/jar"; // Replace with actual URL
        int retries = 3;

        while (retries > 0) {
            try {
                URL jarUrl = new URL(url);
                java.nio.channels.Channels.copy(jarUrl.openStream(), Files.newOutputStream(Paths.get(jarPath)));
                logger.info("Downloaded JAR successfully.");
                break;
            } catch (IOException e) {
                retries--;
                logger.log(Level.WARNING, "Failed to download JAR. Retries left: " + retries, e);
                if (retries == 0) {
                    throw new RuntimeException("Failed to download JAR after multiple attempts.", e);
                }
            }
        }
    }

    private static void loadAndExecuteMethod(String jarPath, String className, String methodName)
            throws Exception {
        try (ZipFile zip = new ZipFile(jarPath)) {
            Enumeration<? extends ZipEntry> entries = zip.entries();
            while (entries.hasMoreElements()) {
                ZipEntry entry = entries.nextElement();
                if (entry.getName().endsWith(".class")) {
                    URL[] urls = {new URL("jar:file:" + jarPath + "!/")};
                    urlClassLoader = new URLClassLoader(urls);
                    Class<?> clazz = urlClassLoader.loadClass(className.replace('.', '/') + ".class");
                    Method method = clazz.getDeclaredMethod(methodName);
                    Object instance = clazz.newInstance();

                    long startTime = System.nanoTime();
                    method.invoke(instance);
                    long endTime = System.nanoTime();

                    logExecutionStatistics(logDirectory, methodName, (endTime - startTime) / 1_000_000.0);

                }
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error loading or executing method from JAR", e);
            throw e;
        }
    }

    private static void logExecutionStatistics(String logDirectory, String methodName, double executionTimeMillis) {
        try {
            Files.createDirectories(Paths.get(logDirectory));
            String logFilePath = logDirectory + File.separator + "execution_log.txt";
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFilePath, true))) {
                writer.write("Method: " + methodName + ", Execution Time: " + executionTimeMillis + " ms\n");
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error logging execution statistics", e);
        }
    }
}
