#define MAX_SCOPE_LENGTH 256

// Structure to hold configuration data
typedef struct {
    char *issuer_url;
    char *client_id;
    char *client_secret;
    char *scopes; // Optional
    int token_expiration_window; // Optional, default to -1 if not set
    int retry_attempts; // Optional, default to 0 if not set
} AuthConfig;

// Callback for writing data during curl operations
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

// Function to validate the configuration
bool validate_auth_config(AuthConfig config) {
    // Check for required fields
    if (!config.issuer_url || !*config.issuer_url ||
        !config.client_id || !*config.client_id ||
        !config.client_secret || !*config.client_secret) {
        return false;
    }

    // Validate client_id and client_secret as non-empty strings
    if (strlen(config.client_id) == 0 || strlen(config.client_secret) == 0) {
        return false;
    }

    // Initialize CURL for issuer_url validation
    CURL *curl = curl_easy_init();
    if (!curl) {
        return false;
    }

    std::string response_string;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");

    // Retry logic with exponential backoff
    int attempts = 0;
    bool success = false;
    while (attempts <= config.retry_attempts) {
        if (attempts > 0) {
            struct timespec ts = {1 << attempts, 0}; // Exponential backoff
            nanosleep(&ts, NULL);
        }

        curl_easy_setopt(curl, CURLOPT_URL, config.issuer_url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response_string);

        CURLcode res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                success = true;
                break;
            }
        }

        attempts++;
    }

    // Clean up CURL resources
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (!success) {
        return false;
    }

    // Validate optional fields
    if (config.scopes && strlen(config.scopes) > 0) {
        char *token = strtok((char *)config.scopes, ",");
        while (token != NULL) {
            if (strlen(token) >= MAX_SCOPE_LENGTH) {
                return false; // Invalid scope length
            }
            token = strtok(NULL, ",");
        }
    }

    if (config.token_expiration_window > 0 && config.token_expiration_window < INT_MAX) {
        // Valid positive integer check is done implicitly by the condition
    } else {
        return false;
    }

    if (config.retry_attempts >= 0) { 
        // Non-negative integer check is done implicitly by the condition
    } else {
        return false;
    }

    return true;
}

// Example main function for testing
