using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public class MessageProcessor
{
    private const string Delimiter = "|";
    private readonly Func<string, string> _decryptFunction; // Assume a decrypt function is passed in

    public MessageProcessor(Func<string, string> decryptFunction)
    {
        _decryptFunction = decryptFunction ?? throw new ArgumentNullException(nameof(decryptFunction));
    }

    public Dictionary<string, string> ProcessMessages(string concatenatedMessages)
    {
        var messageDictionary = new Dictionary<string, string>();
        var duplicateIds = new HashSet<string>();

        // Split messages by delimiter
        var rawMessages = concatenatedMessages.Split(Delimiter);

        foreach (var rawMessage in rawMessages)
        {
            try
            {
                // Regex to extract messageId and encrypted content based on expected format "id|timestamp|message"
                var match = Regex.Match(rawMessage, @"^(\w+)\|\d+\|\s*(.*)$");
                if (!match.Success) throw new FormatException("Invalid message format");

                var messageId = match.Groups[1].Value;
                var encryptedContent = match.Groups[2].Value;

                // Handle duplicate IDs
                if (duplicateIds.Contains(messageId))
                {
                    LogDuplicateMessageId(messageId);
                    continue;
                }

                duplicateIds.Add(messageId);

                // Validate and Decrypt
                var decryptedMessage = DecryptAndValidate(encryptedContent, messageId);

                // Store in dictionary
                messageDictionary[messageId] = decryptedMessage;
            }
            catch (Exception ex)
            {
                LogError($"Failed to process message: {rawMessage}. Error: {ex.Message}");
            }
        }

        return messageDictionary;
    }

    private string DecryptAndValidate(string encryptedContent, string messageId)
    {
        try
        {
            // Decode Base64
            var base64EncodedBytes = Convert.FromBase64String(encryptedContent);
            var jsonString = Encoding.UTF8.GetString(base64EncodedBytes);

            // Decrypt the message using provided decryption function
            var decryptedJson = _decryptFunction(jsonString);

            // Validate against schema (pseudo-code)
            if (!ValidateSchema(decryptedJson))
                throw new FormatException("Decrypted message does not conform to expected schema");

            return decryptedJson;
        }
        catch (FormatException fe) when (fe.Message.Contains("invalid length for a Base-64 char array"))
        {
            LogError($"Invalid Base64 encoding in message ID {messageId}");
        }
        catch (Exception ex)
        {
            LogError($"Decryption or validation failed for message ID {messageId}. Error: {ex.Message}");
        }

        return null;
    }

    private bool ValidateSchema(string decryptedJson)
    {
        // Pseudo-validation logic, replace with actual schema validation
        try
        {
            var json = Newtonsoft.Json.Linq.JObject.Parse(decryptedJson);
            return json["requiredField"] != null;  // Example condition
        }
        catch (Exception)
        {
            return false;
        }
    }

    private void LogError(string message) => Console.WriteLine($"ERROR: {message}"); // Use proper logging

    private void LogDuplicateMessageId(string messageId) => Console.WriteLine($"DUPLICATE ID: {messageId}");
}

// Sample usage
public class Program
{
