public class FileHashProcessor
{
    public Dictionary<string, string> ComputeFileHashes(IEnumerable<string> filePaths)
    {
        var hashDictionary = new ConcurrentDictionary<string, string>();
        Parallel.ForEach(filePaths, filePath =>
        {
            try
            {
                if (!File.Exists(filePath))
                {
                    LogError($"File not found: {filePath}");
                    return;
                }

                using (var sha256 = SHA256.Create())
                {
                    var relativePath = GetRelativeFilePath(filePath);
                    byte[] fileBytes = File.ReadAllBytes(filePath);
                    var hashBytes = sha256.ComputeHash(fileBytes);
                    string hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

                    if (!hashDictionary.TryAdd(relativePath, hashString))
                    {
                        LogError($"Duplicate entry for: {relativePath}");
                    }
                }
            }
            catch (UnauthorizedAccessException ex)
            {
                LogError($"Access denied to file {filePath}: {ex.Message}");
            }
            catch (IOException ex) when (ex.HResult == -2147024864) // ERROR_SHARING_VIOLATION
            {
                LogWarning($"File is being used by another process: {filePath}");
            }
            catch (Exception ex)
            {
                LogError($"An error occurred processing file {filePath}: {ex.Message}");
            }
        });

        return new Dictionary<string, string>(hashDictionary);
    }

    private string GetRelativeFilePath(string filePath)
    {
        // Assuming base path is the current directory for simplicity.
        // Adjust as needed to your application's context.
        var relativePath = Path.GetRelativePath(Environment.CurrentDirectory, filePath);
        if (relativePath.StartsWith(".."))
            throw new InvalidOperationException("File path is outside of the allowed directory.");

        return relativePath;
    }

    private void LogError(string message)
    {
        // Implement logging according to your application's logging framework.
        Console.Error.WriteLine(message);
    }

    private void LogWarning(string message)
    {
        // Implement logging according to your application's logging framework.
        Console.WriteLine(message);
    }
}

