using System;
using System.IO;
using System.Security.Cryptography;

public class CiphertextDecryptor
{
    private readonly byte[] _key; // Encryption key
    private readonly byte[] _ivOrNonce; // Initialization vector or nonce, based on the mode

    public CiphertextDecryptor(byte[] key, byte[] ivOrNonce)
    {
        if (key == null || key.Length != 32) // AES-256 requires a 32-byte key
            throw new ArgumentException("Invalid key length.");

        if (ivOrNonce == null || (ivOrNonce.Length < 16 || ivOrNonce.Length > 32))
            throw new ArgumentException("Invalid IV/nonce length."); 

        _key = key;
        _ivOrNonce = ivOrNonce;
    }

    public byte[] Decrypt(string ciphertext, string mode)
    {
        if (string.IsNullOrWhiteSpace(ciphertext) || 
            (_mode == CipherMode.CBC && ciphertext.Length % 16 != 0))
        {
            throw new ArgumentException("Invalid ciphertext.");
        }

        using var aes = Aes.Create();
        aes.Key = _key;

        try
        {
            switch (mode.ToUpper())
            {
                case "AES-CBC":
                    return DecryptCbc(ciphertext);

                case "AES-GCM":
                    return DecryptGcm(ciphertext);

                default:
                    throw new ArgumentException("Unsupported mode specified.");
            }
        }
        catch (CryptographicException ex)
        {
            // Handle corrupted or incomplete ciphertext
            LogError(ex); // Example error handling function
            return null;
        }
    }

    private byte[] DecryptCbc(string base64Ciphertext)
    {
        var cipherBytes = Convert.FromBase64String(base64Ciphertext);

        if (cipherBytes.Length < 16) 
            throw new ArgumentException("Cipher text too short for AES-CBC.");

        using var aes = Aes.Create();
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        using var decryptor = aes.CreateDecryptor(_key, _ivOrNonce);
        using var msDecrypt = new MemoryStream(cipherBytes);

        try
        {
            using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using var sbDecrypt = new MemoryStream();

            const int bufferSize = 4096;
            byte[] buffer = new byte[bufferSize];
            int bytesRead;

            while ((bytesRead = csDecrypt.Read(buffer, 0, bufferSize)) > 0)
                sbDecrypt.Write(buffer, 0, bytesRead);

            return sbDecrypt.ToArray();
        }
        catch (Exception ex) when (ex is CryptographicException || ex is IOException)
        {
            // Handle potential exceptions
            LogError(ex);
            throw;
        }
    }

    private byte[] DecryptGcm(string base64CiphertextWithTag)
    {
        var components = base64CiphertextWithTag.Split(',');

        if (components.Length != 2)
            throw new ArgumentException("Invalid GCM format.");

        var cipherTextBase64 = components[0];
        var tagBase64 = components[1];

        var cipherBytes = Convert.FromBase64String(cipherTextBase64);
        var tagBytes = Convert.FromBase64String(tagBase64);

        using var aes = Aes.Create();
        aes.Mode = CipherMode.GCM;
        aes.KeySize = 256;

        using var decryptor = aes.CreateDecryptor(_key, _ivOrNonce);

        try
        {
            using var msDecrypt = new MemoryStream(cipherBytes);
            using var csDecrypt = new GcmStream(msDecrypt, decryptor, tagBytes, leaveOpen: true);

            using var sbDecrypt = new MemoryStream();
            const int bufferSize = 4096;
            byte[] buffer = new byte[bufferSize];
            int bytesRead;

            while ((bytesRead = csDecrypt.Read(buffer, 0, bufferSize)) > 0)
                sbDecrypt.Write(buffer, 0, bytesRead);

            return sbDecrypt.ToArray();
        }
        catch (CryptographicException ex) when (ex.Message.Contains("authentication"))
        {
            // Handle authentication tag verification failure
            LogError(ex);
            throw new InvalidOperationException("Decryption failed due to invalid authentication tag.");
        }
    }

    private void LogError(Exception ex)
    {
        // Implement logging mechanism appropriate for your application's needs
        Console.WriteLine($"Error: {ex.Message}");
    }
}
```

**Notes:**
- The function is designed to handle both AES-CBC and AES-GCM modes, with error handling in place.
- It uses a chunking strategy when reading from the `CryptoStream`, which helps manage large ciphertexts efficiently.
- Exception handling captures specific cryptographic exceptions for better resilience against corrupted data.
- This code assumes that session keys and IV/nonce are managed securely within your application environment.']

