import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.concurrent.*;
import java.util.HashMap;
import java.util.Map;

public class DeserializerUtil {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Map<Class<?>, Cache<String, Object>> cacheMap = new HashMap<>();

    public <T> T deserialize(byte[] data, Class<T> interfaceClass, long timeoutMillis) {
        try {
            return CompletableFuture.supplyAsync(() -> doDeserialize(data, interfaceClass))
                    .orTimeout(timeoutMillis, TimeUnit.MILLISECONDS)
                    .exceptionally(ex -> handleDeserializationFailure(interfaceClass, ex))
                    .join();
        } catch (TimeoutException | ExecutionException e) {
            // Handle timeout or deserialization failure
            return null;
        }
    }

    private <T> T doDeserialize(byte[] data, Class<T> interfaceClass) throws IOException, ClassNotFoundException {
        Cache<String, Object> cache = getCacheForInterface(interfaceClass);
        String key = generateKey(data);

        Object cachedObject = cache.get(key);
        if (cachedObject != null && interfaceClass.isInstance(cachedObject)) {
            return interfaceClass.cast(cachedObject);
        }

        try (ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
             ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream)) {

            Object obj = objectInputStream.readObject();

            if (interfaceClass.isInstance(obj)) {
                cache.put(key, obj);
                return interfaceClass.cast(obj);
            } else {
                // Attempt fallback deserialization logic
                for (Class<?> fallbackInterface : getFallbackInterfaces(interfaceClass)) {
                    if (fallbackInterface.isInstance(obj)) {
                        cache.put(key, obj);
                        return (T) obj;
                    }
                }

                throw new ClassNotFoundException("Deserialized object does not implement any expected interfaces.");
            }
        }
    }

    private <T> T handleDeserializationFailure(Class<T> interfaceClass, Throwable ex) {
        System.err.println("Deserialization failed for " + interfaceClass.getName() + ": " + ex.getMessage());
        return null;
    }

    private Cache<String, Object> getCacheForInterface(Class<?> interfaceClass) {
        cacheMap.computeIfAbsent(interfaceClass, k -> new SimpleCache<>(100)); // Adjust size as needed
        return cacheMap.get(interfaceClass);
    }

    private String generateKey(byte[] data) {
        return Integer.toHexString(data.hashCode());
    }

    private Class<?>[] getFallbackInterfaces(Class<?> primaryInterface) {
        // Define fallback interface logic or strategy here
        return new Class[0]; // Replace with actual fallback interfaces
    }

    public void shutdown() {
        executor.shutdown();
    }

    private static class SimpleCache<K, V> extends LinkedHashMap<K, V> {
        private final int maxSize;

        public SimpleCache(int maxSize) {
            this.maxSize = maxSize;
            super(maxSize + 1, 0.75f, true);
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > maxSize;
        }
    }

    public static void main(String[] args) {
        // Example usage
        DeserializerUtil deserializer = new DeserializerUtil();
        byte[] data = {}; // Byte array representing serialized object
        MyInterface obj = deserializer.deserialize(data, MyInterface.class, 5000);

        if (obj != null) {
            // Use the deserialized object
        }

        deserializer.shutdown();
    }
}
