        std::uniform_int_distribution<> dis(0, 10);

        for (int i = 0; i < 5; ++i) {
            GraphVertex vertex{i, {{"name", "vertex" + std::to_string(i)}}};
            graphDB.AddVertex(vertex);

            if (i > 0) {
                int to = dis(gen);
                graphDB.AddEdge(i - 1, to);
            }
        }

    } catch (const std::exception& e) {
        LogError(e.what());
    }

    return 0;
}
