```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for network interface statistics
typedef struct {
    char if_name[32];
    unsigned long bytes_received;
    unsigned int packets_dropped;
} InterfaceStats;

// Logging function (stub implementation)
void log_interface_stats(InterfaceStats *stats, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("Interface: %s, Bytes Received: %lu, Packets Dropped: %u\n",
               stats[i].if_name, stats[i].bytes_received, stats[i].packets_dropped);
    }
}

// Function to initialize and manage the dynamic list
void *manage_interface_stats(void *arg) {
    size_t num_interfaces = *((size_t *)arg);
    InterfaceStats **interface_list = malloc(num_interfaces * sizeof(InterfaceStats *));

    // Initialize interfaces with mock data
    for (size_t i = 0; i < num_interfaces; ++i) {
        interface_list[i] = malloc(sizeof(InterfaceStats));
        snprintf(interface_list[i]->if_name, sizeof(interface_list[i]->if_name), "eth%d", (int)i);
        interface_list[i]->bytes_received = rand() % 100000;
        interface_list[i]->packets_dropped = rand() % 1000;

        // Log initial stats
        log_interface_stats(*interface_list, num_interfaces);
    }

    unsigned long threshold_bytes = 50000; // Threshold for filtering
    pthread_mutex_t update_lock = PTHREAD_MUTEX_INITIALIZER;

    // Periodic updates with real-time data simulation
    while (1) {
        sleep(5); // Simulate periodic update frequency

        pthread_mutex_lock(&update_lock);

        for (size_t i = 0; i < num_interfaces; ++i) {
            // Mock update of stats
            interface_list[i]->bytes_received += rand() % 50000;
            interface_list[i]->packets_dropped += rand() % 100;

            // Filter out low throughput interfaces based on threshold
            if (interface_list[i]->bytes_received < threshold_bytes) {
                free(interface_list[i]);
                interface_list[i] = NULL;
            }
        }

        pthread_mutex_unlock(&update_lock);

        // Log updated stats, excluding filtered interfaces
        log_interface_stats(*interface_list, num_interfaces);
    }

    return NULL;
}

int main() {
    size_t num_interfaces = 10; // Example number of interfaces

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_interface_stats, &num_interfaces)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);

    return 0;
}
```

### Key Points:
- **Dynamic Memory Management**: Allocates memory dynamically for each network interface.
- **Mock Data Generation**: Populates structures with mock data to simulate real-world usage.
- **Filtering Mechanism**: Filters out interfaces based on a configurable bytes received threshold.
- **Periodic Updates**: Simulated periodic updates with sleep intervals; can be modified for actual integration.
- **Logging and Synchronization**: Includes basic logging functionality and mutex locks for thread safety during updates.

This code is optimized to demonstrate concepts of dynamic memory management, filtering, synchronization, and periodic updates in a network monitoring context. Adjust thresholds, update frequency, and logging details based on specific system performance requirements and resource constraints.']

