// Global variables and thread safety mechanisms
NetInterfaceStats *stats_list = NULL;
size_t num_interfaces = 0;
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

#define MIN_THROUGHPUT_PERCENTAGE 10

// Function prototypes
void initialize_stats(size_t count);
void fetch_and_update_stats();
void filter_low_throughput();
