    NetInterfaceStats *interface_data;

    pthread_mutex_lock(&stats_lock);

    // Establish connection to the Java Channel (stubbed function)
    interface_data = establish_java_channel_connection();

    if (!interface_data) {
        log_error("Failed to connect to remote server");
        pthread_mutex_unlock(&stats_lock);
        return;
    }

    // Simulate fetching data
    for (size_t i = 0; i < num_interfaces; ++i) {
        stats_list[i].bytes_sent = interface_data[i].bytes_sent;
        stats_list[i].bytes_received = interface_data[i].bytes_received;
    }

    pthread_mutex_unlock(&stats_lock);
}

// Filter out interfaces with low throughput
void filter_low_throughput() {
    unsigned long total_sent = 0, total_recv = 0;
    size_t valid_count = 0;

    for (size_t i = 0; i < num_interfaces; ++i) {
        total_sent += stats_list[i].bytes_sent;
        total_recv += stats_list[i].bytes_received;
    }

    double avg_throughput = ((double)(total_sent + total_recv)) / num_interfaces;
    double threshold = avg_throughput * (MIN_THROUGHPUT_PERCENTAGE / 100.0);

    for (size_t i = 0; i < num_interfaces; ++i) {
        if ((stats_list[i].bytes_sent + stats_list[i].bytes_received) >= threshold) {
            valid_count++;
        }
    }

    // Allocate memory only for interfaces with sufficient throughput
    NetInterfaceStats *filtered_stats = (NetInterfaceStats *)malloc(valid_count * sizeof(NetInterfaceStats));

    size_t index = 0;
    for (size_t i = 0; i < num_interfaces; ++i) {
        if ((stats_list[i].bytes_sent + stats_list[i].bytes_received) >= threshold) {
            filtered_stats[index++] = stats_list[i];
        }
    }

    // Free the old list and replace it with the new one
    free(stats_list);
    stats_list = filtered_stats;
    num_interfaces = valid_count;
}

// Log error messages for debugging purposes
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

