```rust
use reqwest::{Client, Response, Error};
use std::time::Duration;

// Function to construct an HTTP client for a specified URL with custom headers, timeouts, and retry logic.
pub async fn create_http_client(
    url: &str,
    headers: Option<reqwest::header::HeaderMap>,
    timeout_secs: u64,
    disable_tls_verify: bool,
) -> Result<Client, Error> {
    let mut client_builder = Client::builder()
        .timeout(Duration::from_secs(timeout_secs))
        .redirect(reqwest::RedirectPolicy::none()) // Disable redirect to handle it manually if needed.
        .danger_accept_invalid_certs(disable_tls_verify);

    if let Some(custom_headers) = headers {
        client_builder = client_builder.default_headers(custom_headers);
    }

    let client = client_builder.build()?;

    Ok(client)
}

// Example usage of the client with retry logic
pub async fn perform_request_with_retries(
    url: &str,
    client: Client,
    retries: u32,
) -> Result<Response, String> {
    for attempt in 0..=retries {
        match client.get(url).send().await {
            Ok(response) => return Ok(response),
            Err(e) if attempt < retries => eprintln!("Request failed (attempt {}): {:?}. Retrying...", attempt + 1, e),
            Err(e) => return Err(format!("Request failed after {} attempts: {:?}", retries, e)),
        }
    }

    // Should never be reached
    unreachable!()
}
```

### Assumptions:

- **C Function**: Assumes you have a mechanism to initialize `RX_UE_INFORMATION_TAG` and generate or retrieve an RNTI value.
