#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Union-Find data structure with path compression and union by rank.
typedef struct {
    int parent;
    int rank;
} Subset;

Subset* createSubsets(int n) {
    Subset *subsets = (Subset *)malloc(n * sizeof(Subset));
    if (!subsets) return NULL;

    for (int i = 0; i < n; ++i) {
        subsets[i].parent = i;
        subsets[i].rank = 0;
    }
    return subsets;
}

void freeSubsets(Subset* subsets, int n) {
    free(subsets);
}

int find(Subset subsets[], int i) {
    if (subsets[i].parent != i)
        subsets[i].parent = find(subsets, subsets[i].parent);
    return subsets[i].parent;
}

void unionSets(Subset subsets[], int xroot, int yroot) {
    if (subsets[xroot].rank < subsets[yroot].rank)
        subsets[xroot].parent = yroot;
    else if (subsets[xroot].rank > subsets[yroot].rank)
        subsets[yroot].parent = xroot;
    else {
        subsets[yroot].parent = xroot;
        ++subsets[xroot].rank;
    }
}

void processNfaIndications(NFAPI_CRC_INDICATION_PDU_T* array, size_t size) {
    clock_t start, end;
    double cpu_time_used;

    start = clock();

    Subset *subsets = createSubsets(size);
    if (!subsets) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        uint16_t rnti = array[i].CRC_INDICATION_REL8_TAG.RNTI;
        uint16_t rx_tag = array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG;

        // Randomly set CRCFLAG for demonstration purposes
        array[i].CRCFLAG = rand() % 2; 

        int rnti_root = find(subsets, (int)rnti);
        int rx_tag_root = find(subsets, (int)rx_tag);

        if (rnti_root != rx_tag_root)
            unionSets(subsets, rnti_root, rx_tag_root);
    }

    end = clock();
    cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC * 1000;

    printf("Execution time: %.2f ms\n", cpu_time_used);

    freeSubsets(subsets, size);
}
