#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int MEASUREMENT_ID;
    int RX_POWER_LEVEL; // in dBm
    double CENTER_FREQUENCY; // in MHz
    int CHANNEL_BANDWIDTH; // in kHz
} RF_RX_MEASUREMENT_PDU_T;

#define MAX_MEASUREMENTS 1000

void populateMeasurements(RF_RX_MEASUREMENT_PDU_T *measurements, size_t num_measurements) {
    srand(time(NULL));
    for (size_t i = 0; i < num_measurements; ++i) {
        measurements[i].MEASUREMENT_ID = i + 1;
        // Simulate realistic distribution patterns for RX_POWER_LEVEL and CENTER_FREQUENCY
        measurements[i].RX_POWER_LEVEL = rand() % (-100 - (-130)) + (-130); // Range: [-130, -100] dBm
        measurements[i].CENTER_FREQUENCY = (rand() % (4000 - 700) + 700) + ((double)rand() / RAND_MAX * 3300); // Range: [700, 4300] MHz
        measurements[i].CHANNEL_BANDWIDTH = rand() % (100 - 5) + 5; // Range: [5, 100] kHz
    }
}

void processRadioMeasurements(RF_RX_MEASUREMENT_PDU_T *measurements, size_t num_measurements, int **overlapping_ids, size_t *num_overlaps) {
    if (!measurements || num_measurements == 0) {
        *overlapping_ids = NULL;
        *num_overlaps = 0;
        return;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    populateMeasurements(measurements, num_measurements);

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    printf("Time taken to populate measurements: %.3f ms\n", elapsed_time * 1000);

    size_t capacity = num_measurements;
    *overlapping_ids = malloc(capacity * sizeof(int));
    if (!*overlapping_ids) {
        perror("Failed to allocate memory for overlapping IDs");
        exit(EXIT_FAILURE);
    }

    *num_overlaps = 0;

    for (size_t i = 0; i < num_measurements; ++i) {
        double start_freq_i = measurements[i].CENTER_FREQUENCY - (measurements[i].CHANNEL_BANDWIDTH / 2.0);
        double end_freq_i = measurements[i].CENTER_FREQUENCY + (measurements[i].CHANNEL_BANDWIDTH / 2.0);

        for (size_t j = i + 1; j < num_measurements; ++j) {
            double start_freq_j = measurements[j].CENTER_FREQUENCY - (measurements[j].CHANNEL_BANDWIDTH / 2.0);
            double end_freq_j = measurements[j].CENTER_FREQUENCY + (measurements[j].CHANNEL_BANDWIDTH / 2.0);

            if ((start_freq_i < end_freq_j && start_freq_j < end_freq_i) ||
                (start_freq_j < end_freq_i && start_freq_i < end_freq_j)) {
                (*overlapping_ids)[(*num_overlaps)++] = measurements[i].MEASUREMENT_ID;
                (*overlapping_ids)[(*num_overlaps)++] = measurements[j].MEASUREMENT_ID;

                if (*num_overlaps >= capacity) {
                    capacity *= 2;
                    int *new_array = realloc(*overlapping_ids, capacity * sizeof(int));
                    if (!new_array) {
                        perror("Failed to reallocate memory for overlapping IDs");
                        free(*overlapping_ids);
                        exit(EXIT_FAILURE);
                    }
                    *overlapping_ids = new_array;
                }
            }
        }
    }

    // Remove duplicates
    size_t unique_index = 0;
    for (size_t i = 0; i < *num_overlaps; ++i) {
        if (i == 0 || (*overlapping_ids)[i] != (*overlapping_ids)[unique_index - 1]) {
            (*overlapping_ids)[unique_index++] = (*overlapping_ids)[i];
        }
    }
    *num_overlaps = unique_index;
}

int main() {
    size_t num_measurements = 100; // Example number of measurements
    RF_RX_MEASUREMENT_PDU_T *measurements = malloc(num_measurements * sizeof(RF_RX_MEASUREMENT_PDU_T));
    if (!measurements) {
        perror("Failed to allocate memory for measurements");
        return EXIT_FAILURE;
    }

    int *overlapping_ids = NULL;
    size_t num_overlaps = 0;

    processRadioMeasurements(measurements, num_measurements, &overlapping_ids, &num_overlaps);

    printf("Overlapping MEASUREMENT_IDs:\n");
    for (size_t i = 0; i < num_overlaps; ++i) {
        printf("%d ", overlapping_ids[i]);
    }
    printf("\n");

    free(overlapping_ids);
    free(measurements);
    return EXIT_SUCCESS;
}
```']

