} RX_UE_INFORMATION_TAG_T;

typedef struct {
    uint8_t crcflag; // Assuming CRCFLAG is a single byte, adjust as needed
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    uint16_t rnti; // Assuming RNTI is a 16-bit value, adjust if necessary
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototype
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t num_elements);

// Helper function to generate a random number in a range
uint32_t rand_range(uint32_t min, uint32_t max) {
    return (rand() % (max - min + 1)) + min;
}

// Function definition
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_list(size_t num_elements) {
    if (num_elements == 0) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Handle allocation failure gracefully
        perror("Failed to allocate memory");
        return NULL;
    }

    srand(time(NULL));  // Seed random number generator

    for (size_t i = 0; i < num_elements; ++i) {
        list[i].rx_ue_information_tag.rx_ue_information_tag = rand_range(1, UINT32_MAX);
        list[i].rnti = rand_range(1, UINT16_MAX); // Ensure RNTI is non-zero if required
        list[i].crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        // Validate the integrity of the CRC_INDICATION_REL8_TAG
        pthread_mutex_lock(&lock);
        if (list[i].crc_indication_rel8_tag.crcflag != 0 && list[i].rnti <= 0) {
            fprintf(stderr, "Validation failed for element %zu\n", i);
            free(list);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        pthread_mutex_unlock(&lock);
    }

    // Clean up
    pthread_mutex_destroy(&lock);

    return list;
}

// Example usage (not part of the function itself)
int main() {
    size_t num_elements = 10; // Example number of elements to create

    NFAPI_CRC_INDICATION_PDU_T *list = create_nfa_pi_list(num_elements);

    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    // Use the list...

    // Free allocated memory
    free(list);

    return EXIT_SUCCESS;
}
