<?php

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
    // Configuration for database connection
    $config = [
        'dsn' => getenv('DB_DSN'),
        'username' => getenv('DB_USERNAME'),
        'password' => getenv('DB_PASSWORD'),
        'options' => [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        ]
    ];

    // Input validation
    if (!filter_var($clinicId, FILTER_VALIDATE_INT)) {
        return json_encode(['error' => 'Invalid clinic ID.']);
    }

    if (filter_var($lastModifiedIp, FILTER_VALIDATE_IP) === false) {
        return json_encode(['error' => 'Invalid IP address format.']);
    }

    // Rate limiting: Example using Redis for simplicity
    $rateLimitKey = "clinic_update_rate_limit_{$lastModifiedIp}";
    $redis = new Redis();
    $redis->connect('127.0.0.1', 6379);

    if ($redis->get($rateLimitKey) >= 5) { // Allow max 5 requests per minute
        return json_encode(['error' => 'Rate limit exceeded. Try again later.']);
    }
    $redis->incr($rateLimitKey);
    $redis->expire($rateLimitKey, 60);

    // Retry mechanism for database connection failures
    $attempts = 0;
    do {
        try {
            $pdo = new PDO($config['dsn'], $config['username'], $config['password'], $config['options']);
            break; // Exit loop if successful
        } catch (PDOException $e) {
            $attempts++;
            sleep(1); // Wait before retrying
        }
    } while ($attempts < 3);

    if ($attempts == 3) {
        return json_encode(['error' => 'Database connection failed after multiple attempts.']);
    }

    try {
        // Begin transaction
        $pdo->beginTransaction();

        // Update clinic status
        $stmt = $pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :clinicId");
        $stmt->execute([':status' => $newStatus, ':ip' => $lastModifiedIp, ':clinicId' => $clinicId]);

        if ($stmt->rowCount() === 0) {
            $pdo->rollBack();
            return json_encode(['error' => 'Clinic ID not found or no update needed.']);
        }

        // Log the update attempt
        $logStmt = $pdo->prepare("INSERT INTO audit_log (clinic_id, modified_ip, timestamp) VALUES (:clinicId, :ip, NOW())");
        $logStmt->execute([':clinicId' => $clinicId, ':ip' => $lastModifiedIp]);

        // Commit transaction
        $pdo->commit();

        return json_encode(['success' => 'Clinic status updated successfully.']);
    } catch (Exception $e) {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
        }
        return json_encode(['error' => 'Failed to update clinic status: ' . $e->getMessage()]);
    }
}

// Example of integrating into an API endpoint
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Sample input data from request body (assuming JSON)
    $data = json_decode(file_get_contents('php://input'), true);

    if (!isset($data['clinicId'], $data['newStatus'], $data['lastModifiedIp'])) {
        header('HTTP/1.1 400 Bad Request');
        echo json_encode(['error' => 'Missing required parameters']);
        exit;
    }

    $response = updateClinicStatus(
        $data['clinicId'],
        $data['newStatus'],
        $data['lastModifiedIp']
    );

    header('Content-Type: application/json');
    echo $response;

    // For asynchronous handling, consider using a job queue system or similar
}

