// Define the structure for a node in the linked list
typedef struct StateNode {
    int state;
    struct StateNode* next;
} StateNode;

// Function to dynamically create a linked list from a given finite state automaton (FSA)
StateNode* createStateList(int* states, int numStates, void* fsa, int lastState) {
    if (!states || numStates <= 0) {
        return NULL; // Invalid input
    }

    StateNode* head = NULL;
    StateNode* current = NULL;

    for (int i = 0; i < numStates; ++i) {
        StateNode* newNode = (StateNode*)malloc(sizeof(StateNode));
        if (!newNode) {
            // Free all previously allocated nodes before returning
            while (head != NULL) {
                StateNode* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL; // Insufficient memory
        }

        newNode->state = states[i];
        newNode->next = NULL;

        if (!head) {
            head = newNode; // First node
        } else {
            current->next = newNode; // Link the new node
        }

        current = newNode;
    }

    // Validate integrity of the linked list
    StateNode* validationCurrent = head;
    StateNode* seenNodes[10000] = {NULL}; // Adjust size as needed for your application

    while (validationCurrent) {
        for (int i = 0; i < numStates; ++i) {
            if (seenNodes[i] == validationCurrent) {
                // Cycle detected
                while (head != NULL) {
                    StateNode* temp = head;
                    head = head->next;
                    free(temp);
                }
                return NULL;
            }
        }

        seenNodes[validationCurrent - &states[0]] = validationCurrent; // Use state index for marking
        validationCurrent = validationCurrent->next;
    }

    // Validate last node if necessary (e.g., if lastState is a specific check)
    if (current && current->state != lastState) {
        while (head != NULL) {
            StateNode* temp = head;
            head = head->next;
            free(temp);
        }
        return NULL; // Last state doesn't match
    }

    return head;
}

// Example usage
int main() {
    int states[] = {0, 1, 2, 3}; // Example states
    int numStates = sizeof(states) / sizeof(states[0]);
    void* fsa = NULL; // Placeholder for FSA structure if needed
    int lastState = 3;

    StateNode* stateList = createStateList(states, numStates, fsa, lastState);

    if (stateList) {
        printf("Linked list created successfully.\n");
        // Traverse and print the linked list
        while (stateList != NULL) {
            printf("%d -> ", stateList->state);
            StateNode* temp = stateList;
            stateList = stateList->next;
            free(temp); // Free each node after use
        }
    } else {
        printf("Failed to create linked list.\n");
    }

    return 0;
}
