['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000000
#define WINDOW_SIZE 100
#define TOP_N 3

typedef struct {
    int id;
    time_t timestamp;
    double amount;
    char tags[64];
    char description[256];
} Transaction;

typedef struct Node {
    Transaction* data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} TransactionQueue;

typedef struct {
    double weightedSum;
    int transactionCount;
    double averageAmount;
    double maxTransactionAmount;
    Transaction topTransactions[TOP_N];
} Metrics;

typedef struct {
    char tags[64];
    char description[256];
    Metrics metrics;
    TransactionQueue queue;
} TagDescMetrics;

#define MAX_TAGS 100
TagDescMetrics tagDescMetrics[MAX_TAGS];

void initializeQueue(TransactionQueue* queue) {
    queue->head = NULL;
    queue->count = 0;
}

int addTransaction(TransactionQueue* queue, Transaction* transaction) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->data = transaction;
    newNode->next = queue->head;
    queue->head = newNode;
    queue->count++;

    if (queue->count > WINDOW_SIZE) {
        Node* temp = queue->head;
        queue->head = queue->head->next;
        free(temp->data);
        free(temp);
        queue->count--;
    }
    return 0;
}

void removeTransaction(TransactionQueue* queue, int transactionId) {
    Node *current = queue->head, *prev = NULL;
    while (current != NULL && current->data->id != transactionId) {
        prev = current;
        current = current->next;
    }

    if (!current) return;

    if (prev == NULL)
        queue->head = current->next;
    else
        prev->next = current->next;

    free(current->data);
    free(current);
    queue->count--;
}

void updateMetrics(TransactionQueue* queue, Metrics* metrics) {
    double sumAmount = 0.0, maxAmount = 0.0;
    size_t count = 0;
    Node* current = queue->head;

    while (current != NULL) {
        Transaction* trans = current->data;
        time_t now = time(NULL);
        int ageInSeconds = difftime(now, trans->timestamp);

        double weight = 1 / (ageInSeconds + 1); // Simplified weight calculation
        sumAmount += trans->amount * weight;

        if (trans->amount > maxAmount) {
            maxAmount = trans->amount;
        }

        count++;
        current = current->next;
    }

    metrics->weightedSum = sumAmount;
    metrics->transactionCount = count;
    metrics->averageAmount = (count == 0) ? 0 : sumAmount / count;
    metrics->maxTransactionAmount = maxAmount;
}

void processTransaction(Transaction* transaction) {
    // Hash function to map tag and description to an index in tagDescMetrics array
    int index = (hashFunction(transaction->tags, transaction->description)) % MAX_TAGS;

    TagDescMetrics* tdm = &tagDescMetrics[index];

    if (addTransaction(&tdm->queue, transaction) < 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    updateMetrics(&tdm->queue, &tdm->metrics);
}

void getTopTransactions(TagDescMetrics* tdm, Transaction topTransactions[TOP_N]) {
    Node* current = tdm->queue.head;
    while (current != NULL) {
        for (int i = 0; i < TOP_N; ++i) {
            if ((tdm->metrics.topTransactions[i].id == 0 || 
                 tdm->metrics.weightedSum > tdm->metrics.topTransactions[i].weightedSum)) {

                // Shift elements down
                for (int j = TOP_N - 1; j > i; --j) {
                    tdm->metrics.topTransactions[j] = tdm->metrics.topTransactions[j - 1];
                }

                // Insert new transaction at the right place
                Transaction* trans = current->data;
                trans->weightedSum = tdm->metrics.weightedSum;
                memcpy(&tdm->metrics.topTransactions[i], trans, sizeof(Transaction));
                break;
            }
        }
        current = current->next;
    }

    for (int i = 0; i < TOP_N; ++i) {
        topTransactions[i] = tdm->metrics.topTransactions[i];
    }
}

// Dummy hash function
unsigned int hashFunction(const char* tags, const char* description) {
    unsigned long hash = 5381;
    int c;

    while ((c = *tags++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    while ((c = *description++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

void processStream(Transaction* transactions, size_t numTransactions) {
    for (size_t i = 0; i < numTransactions; ++i) {
        processTransaction(&transactions[i]);
    }
}

int main() {
    // Example usage
    Transaction transactions[MAX_TRANSACTIONS];

    // Initialize and populate the transaction array with dummy data

    processStream(transactions, MAX_TRANSACTIONS);

    return 0;
}
```

This code implements a simplified version of your requirements. It maintains a sliding window for each tag-description combination, calculates weighted sums, updates metrics, handles duplicates by removing older transactions from the queue if necessary, and returns top transactions based on their weighted sum.

The actual implementation of dynamic criteria fetching, importance level calculation, and real-time handling would require additional infrastructure not covered in this code. Moreover, scaling to handle millions of transactions per second efficiently may involve using more advanced data structures and possibly parallel processing or distributed computing techniques, which are beyond the scope of a single function in C.']

