using System;
using System.Collections.Generic;
using UnityEngine;

public class DynamicValueGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicValueGenerator(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot exceed maximum value.");

        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInteger()
    {
        // Convert the range to integers for inclusive behavior
        int minInt = (int)minValue;
        int maxInt = (int)maxValue;

        if (minValue == minInt && maxValue == maxInt)
            return UnityEngine.Random.Range(minInt, maxInt + 1);

        float randomFloat = UnityEngine.Random.Range(minValue, maxValue);
        return (int)Math.Round(randomFloat);
    }

    public override string ToString()
    {
        return $"Current range: [{minValue}, {maxValue}]";
    }

    public void ReadAndAnalyzeValues()
    {
        List<int> validIntegers = new List<int>();

        Console.WriteLine("Enter integers separated by spaces (press Enter to finish):");
        string input = Console.ReadLine();

        if (!string.IsNullOrWhiteSpace(input))
        {
            string[] inputs = input.Split(' ');

            foreach (var item in inputs)
            {
                if (int.TryParse(item, out int number) && number >= minValue && number <= maxValue)
                {
                    validIntegers.Add(number);
                }
            }

            int largestValue = FindLargest(validIntegers);

            if (largestValue != int.MinValue)
            {
                Console.WriteLine($"The largest integer within the range is: {largestValue}");
            }
            else
            {
                Console.WriteLine("No valid integers were provided within the configured range.");
            }
        }
    }

    private int FindLargest(List<int> numbers)
    {
        if (numbers.Count == 0) return int.MinValue;

        int largest = int.MinValue;
        foreach (int num in numbers)
        {
            if (num > largest)
                largest = num;
        }
        return largest;
    }
}
