#include <signal.h>
#include <time.h>

volatile sig_atomic_t interrupted = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        interrupted = 1;
    }
}

double compute_average(double a, double b) {
    return (a + b) / 2.0;
}

void process_file(const char *input_path, const char *output_dir) {
    FILE *file_in = fopen(input_path, "r");
    if (!file_in) {
        fprintf(stderr, "Error opening file: %s\n", input_path);
        return;
    }

    size_t line_len = 0;
    ssize_t read;
    char *line = NULL;

    char output_filename[256];
    snprintf(output_filename, sizeof(output_filename), "%s/%s.processed", output_dir,
             strrchr(input_path, '/') ? strrchr(input_path, '/') + 1 : input_path);

    FILE *file_out = fopen(output_filename, "w");
    if (!file_out) {
        fprintf(stderr, "Error creating output file: %s\n", output_filename);
        fclose(file_in);
        return;
    }

    while ((read = getline(&line, &line_len, file_in)) != -1 && !interrupted) {
        char *fields[100];  // Arbitrary large number of expected fields
        int field_count = 0;

        char *token = strtok(line, " \t\n");
        while (token) {
            fields[field_count++] = token;
            token = strtok(NULL, " \t\n");
        }

        if (field_count >= 2 && fields[field_count - 1] && fields[field_count - 2]) {
            double last_num1 = atof(fields[field_count - 1]);
            double last_num2 = atof(fields[field_count - 2]);
            double avg = compute_average(last_num1, last_num2);

            fprintf(file_out, "%s", line);
            fprintf(file_out, " %f\n", avg);
        } else {
            fprintf(file_out, "%s", line);  // Write unchanged if not enough fields
        }
    }

    free(line);
    fclose(file_in);
    fclose(file_out);
}

void log_entry(const char *message) {
    FILE *log_file = fopen("process_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

void process_directory(const char *input_dir, const char *output_dir) {
    DIR *dir = opendir(input_dir);
    if (!dir) {
        log_entry("Error opening directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) && !interrupted) {
        if (entry->d_type == DT_REG) {
            char input_path[256];
            snprintf(input_path, sizeof(input_path), "%s/%s", input_dir, entry->d_name);

            log_entry("Processing file");
            process_file(input_path, output_dir);
            log_entry("File processed successfully");
        }
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input_directory> <output_directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_entry("Program started");

    process_directory(argv[1], argv[2]);

    if (interrupted) {
        log_entry("Process interrupted by user");
    } else {
        log_entry("Processing completed successfully");
    }

    return EXIT_SUCCESS;
}
