['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 255

char* generate_new_filename(const char *input_filename) {
    if (!input_filename || strlen(input_filename) == 0) {
        return NULL;
    }

    // Determine the extension of the input filename
    const char *dot = strrchr(input_filename, '.');
    size_t base_length, ext_length;
    if (dot && dot != input_filename) { // There's a valid extension
        base_length = dot - input_filename;
        ext_length = strlen(dot);
    } else {
        base_length = strlen(input_filename);
        ext_length = 0; // No extension found
    }

    size_t original_length = strlen(input_filename);

    // Calculate the number of digits for the new extension
    int num_digits = (int)(original_length / 2);

    // Define file types
    const char *file_types[] = { "jpg", "png", "mp3", "zip", "txt", "doc", "pdf" };
    size_t num_file_types = sizeof(file_types) / sizeof(file_types[0]);

    // Generate a new extension based on original filename characteristics
    char *new_extension = (char *)malloc(num_digits + 4); // Digits + dot + file type length + null terminator
    if (!new_extension) {
        return NULL; // Memory allocation failed
    }

    snprintf(new_extension, num_digits + 4, ".%0*d", num_digits, original_length);

    // Choose a file type based on some characteristic of the filename
    const char *chosen_file_type = "txt"; // Default to txt for simplicity

    // Concatenate base name with new extension and chosen file type
    size_t new_name_length = base_length + 1 + num_digits + 3; // base + dot + digits + file type length
    if (new_name_length > MAX_FILENAME_LENGTH) {
        new_name_length = MAX_FILENAME_LENGTH - strlen(chosen_file_type) - 1;
    }

    char *new_filename = (char *)malloc(new_name_length + 4); // Plus space for dot and null terminator
    if (!new_filename) {
        free(new_extension);
        return NULL; // Memory allocation failed
    }

    snprintf(new_filename, new_name_length + 4, "%.*s%s%s", 
             (int)new_name_length, input_filename, new_extension, chosen_file_type);

    free(new_extension);
    return new_filename;
}

// Example usage
int main() {
    const char *filename = "example_document.pdf";
    char *new_filename = generate_new_filename(filename);

    if (new_filename) {
        printf("New filename: %s\n", new_filename);
        free(new_filename);
    } else {
        printf("Failed to generate a new filename.\n");
    }

    return 0;
}
```']

['Below is a modular C library design that integrates cryptographic primitives using OpenSSL. This implementation includes dynamic loading and configuration for AES encryption, RSA signatures, SHA-256 hashing, and ECDSA signatures.

```c
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/bn.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <openssl/ecdsa.h>
#include <pthread.h>
#include <stdio.h>
import <stdlib.h>

// Error handling and logging utility
#define LOG_ERROR(msg) fprintf(stderr, "ERROR: %s\n", msg)
#define LOG_INFO(msg) printf("INFO: %s\n", msg)

typedef struct {
    EVP_CIPHER_CTX *ctx;
} aes_ctx_t;

typedef struct {
    pthread_mutex_t lock;
    EVP_PKEY *pkey_cache[10]; // Simple cache for RSA and ECDSA keys
} crypto_context_t;

crypto_context_t ctx = { .lock = PTHREAD_MUTEX_INITIALIZER };

// Function to dynamically load AES with configuration
aes_ctx_t* aes_init(const char *cipher_name, const unsigned char *key, size_t key_len, int block_size) {
    if (!cipher_name || !key || !block_size) return NULL;

    aes_ctx_t *aes_ctx = malloc(sizeof(aes_ctx_t));
    if (!aes_ctx) return NULL;

    EVP_CIPHER_CTX_init(aes_ctx->ctx = EVP_CIPHER_CTX_new());
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher || !EVP_EncryptInit_ex(aes_ctx->ctx, cipher, NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
        LOG_ERROR("AES initialization failed");
        return NULL;
    }

    // Set padding and other configurations here if needed
    if (!EVP_EncryptInit_ex(aes_ctx->ctx, cipher, NULL, key, "PKCS7Padding")) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        free(aes_ctx);
        LOG_ERROR("AES padding configuration failed");
        return NULL;
    }

    return aes_ctx;
}

// Function to hash data using SHA-256
int sha256_hash(const unsigned char *data, size_t len, unsigned char *hash_out) {
    if (!data || !len || !hash_out) return 0;

    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) <= 0 ||
        EVP_DigestUpdate(mdctx, data, len) <= 0 ||
        EVP_DigestFinal_ex(mdctx, hash_out, NULL) <= 0) {
        EVP_MD_CTX_free(mdctx);
        LOG_ERROR("SHA-256 hashing failed");
        return 0;
    }

    EVP_MD_CTX_free(mdctx);
    return 1;
}

// Function to sign data using RSA or ECDSA
int crypto_sign(const unsigned char *data, size_t len, const char *key_id, unsigned char *sig_out, size_t *sig_len) {
    pthread_mutex_lock(&ctx.lock);

    EVP_PKEY *pkey = ctx.pkey_cache[atoi(key_id)]; // Simple retrieval from cache
    if (!pkey) {
        LOG_ERROR("Key not found in cache");
        pthread_mutex_unlock(&ctx.lock);
        return 0;
    }

    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (EVP_SignInit_ex(mdctx, EVP_sha256(), NULL) <= 0 ||
        EVP_SignUpdate(mdctx, data, len) <= 0 ||
        EVP_SignFinal(mdctx, sig_out, sig_len, pkey) <= 0) {
        EVP_MD_CTX_free(mdctx);
        pthread_mutex_unlock(&ctx.lock);
        LOG_ERROR("Signing failed");
        return 0;
    }

    EVP_MD_CTX_free(mdctx);
    pthread_mutex_unlock(&ctx.lock);
    return 1;
}

// Function to load and cache keys
int load_key(const char *key_path, const char *format) {
    pthread_mutex_lock(&ctx.lock);

    FILE *fp = fopen(key_path, "r");
    if (!fp) {
        LOG_ERROR("Failed to open key file");
        pthread_mutex_unlock(&ctx.lock);
        return 0;
    }

    EVP_PKEY *pkey = NULL;
    if (strcmp(format, "PEM") == 0)
        pkey = PEM_read_PrivateKey(fp, NULL, NULL, NULL);
    else if (strcmp(format, "DER") == 0)
        pkey = d2i_PKCS8_PRIV_KEY_INFO_fp(fp, NULL);

    fclose(fp);
    if (!pkey) {
        LOG_ERROR("Failed to load key");
        pthread_mutex_unlock(&ctx.lock);
        return 0;
    }

    // Cache the key (simple caching strategy here)
    for (int i = 0; i < 10; ++i) {
        if (!ctx.pkey_cache[i]) {
            ctx.pkey_cache[i] = pkey;
            pthread_mutex_unlock(&ctx.lock);
            return 1;
        }
    }

    EVP_PKEY_free(pkey);
    LOG_ERROR("Key cache is full");
    pthread_mutex_unlock(&ctx.lock);
    return 0;
}

// Clean up resources
void cleanup() {
    for (int i = 0; i < 10; ++i) {
        if (ctx.pkey_cache[i]) EVP_PKEY_free(ctx.pkey_cache[i]);
    }
    pthread_mutex_destroy(&ctx.lock);
}
```

### Key Features:
- **AES Initialization**: Supports dynamic selection of cipher modes and padding schemes.
- **SHA-256 Hashing**: Efficient hashing function using OpenSSL's SHA-256.
- **Signing Functionality**: Supports RSA and ECDSA signatures with caching for performance optimization.
- **Key Management**: Implements a simple key cache to balance memory usage and performance.
- **Thread Safety**: Uses mutexes to ensure thread safety in shared resources.
- **Error Handling and Logging**: Provides basic logging for error tracking and debugging.

This code is designed to be modular and expandable, allowing for future enhancements and integration with external systems.']

["Here's a C code implementation for an AES-256-GCM encryption suite that addresses the outlined challenges:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define IV_SIZE 12

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_SIZE];
    pthread_mutex_t mutex;
} AES256GCM_Context;

// Key derivation using PBKDF2-HMAC-SHA256
int derive_key(const char *password, const unsigned char *salt, int salt_len, unsigned char *key, int key_len) {
    return PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_len, 10000, EVP_sha256(), key_len, key);
}

// Initialize AES-256-GCM context
AES256GCM_Context* aes_init(const char *password, const unsigned char *salt, int salt_len) {
    AES256GCM_Context *ctx = (AES256GCM_Context*)malloc(sizeof(AES256GCM_Context));
    if (!ctx || pthread_mutex_init(&ctx->mutex, NULL) != 0) return NULL;

    if (derive_key(password, salt, salt_len, ctx->key, KEY_SIZE) <= 0) {
        free(ctx);
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        pthread_mutex_destroy(&ctx->mutex);
        free(ctx);
        return NULL;
    }

    return ctx;
}

// Encrypt data
int aes_encrypt(AES256GCM_Context *ctx, const unsigned char *plaintext, int plaintext_len,
                unsigned char *ciphertext, int *ciphertext_len, unsigned char *iv) {
    pthread_mutex_lock(&ctx->mutex);

    if (!RAND_bytes(iv, IV_SIZE)) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, iv) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }

    int len;
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    *ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    *ciphertext_len += len;

    unsigned char tag[EVP_MAX_BLOCK_LENGTH];
    int tag_len = EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, sizeof(tag), tag);

    memcpy(ciphertext + *ciphertext_len, iv, IV_SIZE);
    memcpy(ciphertext + *ciphertext_len + IV_SIZE, tag, tag_len);

    *ciphertext_len += (IV_SIZE + tag_len);

    pthread_mutex_unlock(&ctx->mutex);
    return 0;
}

// Decrypt data
int aes_decrypt(AES256GCM_Context *ctx, const unsigned char *ciphertext, int ciphertext_len,
                unsigned char *plaintext, int *plaintext_len) {
    pthread_mutex_lock(&ctx->mutex);

    unsigned char iv[IV_SIZE];
    memcpy(iv, ciphertext + (ciphertext_len - IV_SIZE - EVP_MAX_BLOCK_LENGTH), IV_SIZE);
    unsigned char tag[EVP_MAX_BLOCK_LENGTH];
    memcpy(tag, ciphertext + (ciphertext_len - EVP_MAX_BLOCK_LENGTH), EVP_MAX_BLOCK_LENGTH);

    if (EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, iv) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }

    int len;
    if (EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len - IV_SIZE - EVP_MAX_BLOCK_LENGTH) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    *plaintext_len = len;

    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, sizeof(tag), tag) <= 0 ||
        EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len) <= 0) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    *plaintext_len += len;

    pthread_mutex_unlock(&ctx->mutex);
    return 0;
}

// Cleanup AES-256-GCM context
void aes_cleanup(AES256GCM_Context *ctx) {
    if (ctx) {
        pthread_mutex_lock(&ctx->mutex);
        EVP_CIPHER_CTX_free(ctx->ctx);
        pthread_mutex_unlock(&ctx->mutex);
        pthread_mutex_destroy(&ctx->mutex);
        free(ctx);
    }
}
```

### Key Points:
- **Key Derivation**: Uses `PKCS5_PBKDF2_HMAC` for secure key derivation.
- **Thread Safety**: Uses mutexes to ensure thread-safe operations on the cipher context.
- **IV Management**: Generates a unique IV for each encryption operation using `RAND_bytes`.
- **Resource Cleanup**: Properly frees resources and handles exceptions with mutex locks.
- **Scalability**: Designed for efficient multi-threaded use, suitable for cloud environments.
- **Usability**: Provides an intuitive API for initializing, encrypting, decrypting, and cleaning up."]

