    int ACK;
    unsigned short checksum;
} TCP_SEGMENT;

unsigned short generate_checksum() {
    return (rand() % 65536);
}

void calculate_average(float *array, size_t count) {
    if (count == 0) {
        printf("Average: N/A\n");
        return;
    }
    float sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += array[i];
    }
    printf("Average: %.2f\n", sum / count);
}

int process_network_data(int socket_fd) {
    float *data_array = NULL;
    size_t data_count = 0;
    TCP_SEGMENT *segments = NULL;
    size_t segment_count = 0;

    char buffer[BUFFER_SIZE];
    int bytes_received;

    while ((bytes_received = recv(socket_fd, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';

        if (strcmp(buffer, "END") == 0) {
            break; // End-of-stream signal received
        }

        float new_number;
        char *token = strtok(buffer, ",");

        while (token != NULL) {
            sscanf(token, "%f", &new_number);

            data_array = realloc(data_array, (data_count + 1) * sizeof(float));
            if (!data_array) {
                perror("Failed to allocate memory");
                return -1;
            }
            data_array[data_count++] = new_number;

            segments = realloc(segments, (segment_count + 1) * sizeof(TCP_SEGMENT));
            if (!segments) {
                perror("Failed to allocate memory");
                return -1;
            }

            segments[segment_count].PSN = segment_count; // Packet Sequence Number
            segments[segment_count].ACK = data_count;    // Acknowledgment Number
            segments[segment_count].checksum = generate_checksum();

            token = strtok(NULL, ",");
            segment_count++;
        }
    }

    if (bytes_received < 0) {
        perror("Error receiving data");
        free(data_array);
        free(segments);
        return -1;
    }

    // Calculate and print the average of received numbers
    calculate_average(data_array, data_count);

    // Simulate packet loss detection and retransmission handling
    for (size_t i = 0; i < segment_count; ++i) {
        if ((rand() % 10) == 0) { // Randomly simulate packet loss
            printf("Retransmitting packet with PSN: %d\n", segments[i].PSN);
        }
    }

    free(data_array);
    free(segments);

    return 0;
}
