// Function to perform exponential backoff retry mechanism
int fetchDataWithRetries(int *range, int max_retries) {
    const int base_delay_ms = 100; // Starting delay in milliseconds
    for (int attempt = 0; attempt < max_retries; ++attempt) {
        // Simulate fetching data from an external source
        if ((rand() % 2) == 0) { // Simulating a failure/success scenario
            *range = rand() % 100 + 1; // Set range to some random value between 1 and 100
            return 1;
        }
        int delay_ms = base_delay_ms * (1 << attempt); // Exponential backoff
        printf("Retrying in %d ms...\n", delay_ms);
        usleep(delay_ms * 1000); // usleep takes microseconds
    }
    return 0; // Failed to fetch data after max_retries
}

// Function to manage memory allocation and initialization
