    *data_count = numRecords;

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    double* values = (double*)malloc(numRecords * sizeof(double));
    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    if (!offsets || !keys || !values || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(values);
        free(records);
        return -1;
    }

    // Initialize data structures
    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand() % 1000;
        values[i] = ((double)(rand() / (RAND_MAX + 1.0))) * INIT_RANGE;

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];

        if (records[i].value > maxValue) {
            maxValue = records[i].value;
        }
    }

    totalRecords += numRecords;

    // Example: write to a binary file
    FILE* file = fopen("records.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        free(offsets);
        free(keys);
        free(values);
        free(records);
        return -1;
    }

    fwrite(records, sizeof(Record), numRecords, file);

    fclose(file);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(values);
    free(records);

    return 0; // Success
}

// Entry point for demonstration purposes
int main() {
    srand(time(NULL)); // Seed random number generator

    int max_size = 10000;
    int data_count;

    if (manageMemoryAndInitialize(max_size, &data_count) == 0) {
        printf("Initialization successful. Total records: %ld, Max value in 'double': %.2f\n", totalRecords, maxValue);
    } else {
        fprintf(stderr, "Failed to initialize.\n");
    }

    return 0;
}
```

### Key Points:
- **Exponential Backoff**: Implemented a retry mechanism with exponential backoff for fetching range data from an external source.
- **Memory Management**: Dynamically allocated memory for arrays and records with proper error checking.
- **Data Initialization**: Initialized arrays with random values while respecting resource constraints.
- **File Operations**: Serialized record structures into a binary file for storage, optimizing I/O operations. 
- **Error Handling**: Comprehensive checks for failures in data fetching, allocation, or file operations to ensure robustness.

