        printf("Retrying... attempt %d\n", retries + 1);
        sleep(sleep_time);
        retries++;
    }

    handle_error("Failed to get dynamic range after multiple attempts.");
    return -1; // This should not be reached due to error handling
}

// Main function for managing dynamic data structures
void manage_dynamic_data(size_t max_size) {
    int *int_array = NULL;
    NFAPI_CRC_INDICATION_PDU_T **pdu_list = NULL;
    size_t current_int_count = 0, pdu_count = 0;
