        int_array = realloc(int_array, (current_int_count + 1) * sizeof(int));
        if (!int_array) {
            handle_error("Failed to allocate memory for integer array");
        }
        int_array[current_int_count++] = value;

        pdu_list = realloc(pdu_list, (pdu_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!pdu_list) {
            free(int_array);
            handle_error("Failed to allocate memory for PDU list");
        }
        pdu_list[pdu_count++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list[pdu_count - 1]) {
            while (pdu_count > 0) {
                free(pdu_list[--pdu_count]);
            }
            free(int_array);
            handle_error("Failed to allocate memory for PDU structure");
        }
        *pdu_list[pdu_count - 1] = new_pdu;

        pthread_mutex_unlock(&lock);

        // Simulated condition to break the loop
