        phy_info_buffer[i].error_rate = (float)rand() / RAND_MAX;
        phy_info_buffer[i].timestamp = time(NULL); // Example timestamp
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int validate_frames(int num_frames) {
    for (int i = 0; i < num_frames; ++i) {
        if (frame_pool[i].RX_FRAME_PDU_TAG == 0 || frame_pool[i].RNTI == 0 ||
            frame_pool[i].PHY_FRAME_INFO_TAG == 0) {
            return -1;
        }
    }
    return 0;
}

void cleanup_memory() {
    pthread_mutex_lock(&mutex);
    if (frame_pool) free(frame_pool);
    if (phy_info_buffer) free(phy_info_buffer);
    pthread_mutex_unlock(&mutex);

    frame_pool = NULL;
    phy_info_buffer = NULL;
}

int main(int argc, char *argv[]) {
