        fprintf(stderr, "Usage: %s <number_of_frames>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_frames = atoi(argv[1]);

    initialize_memory();

    if (configure_frames(num_frames) == -1) {
        cleanup_memory();
        return EXIT_FAILURE;
    }

    if (validate_frames(total_frames) == -1) {
        fprintf(stderr, "Validation failed for one or more frames.\n");
        cleanup_memory();
        return EXIT_FAILURE;
    }

    printf("Frames successfully configured and validated.\n");

    // Simulate processing...

    cleanup_memory();

    return EXIT_SUCCESS;
}
