    time_t timestamp;
    PayloadType payload;
} DataPacket;

#define TIME_WINDOW 60 // Time window in seconds

// Hash table for managing unique packet IDs
#define HASH_TABLE_SIZE 1024
typedef struct Node {
    int packetId;
    time_t timestamp;
    struct Node *next;
} Node;

Node *hashTable[HASH_TABLE_SIZE];
pthread_mutex_t hashMutexes[HASH_TABLE_SIZE];

unsigned int hashFunction(int packetId) {
    return packetId % HASH_TABLE_SIZE;
}

int isPacketIdAvailable(int packetId, time_t current_time) {
    unsigned int index = hashFunction(packetId);
    pthread_mutex_lock(&hashMutexes[index]);

    Node *current = hashTable[index];
    while (current != NULL) {
        if (current->packetId == packetId && 
            (current_time - current->timestamp < TIME_WINDOW)) {
            pthread_mutex_unlock(&hashMutexes[index]);
            return 0; // Packet ID is not available
        }
        current = current->next;
    }

    pthread_mutex_unlock(&hashMutexes[index]);
    return 1; // Packet ID is available
}

void addPacketId(int packetId, time_t timestamp) {
    unsigned int index = hashFunction(packetId);
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->packetId = packetId;
    newNode->timestamp = timestamp;
    newNode->next = NULL;

    pthread_mutex_lock(&hashMutexes[index]);

    // Insert at the head of the linked list
    newNode->next = hashTable[index];
    hashTable[index] = newNode;

    pthread_mutex_unlock(&hashMutexes[index]);
}

void removeStalePacketIds(time_t current_time) {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&hashMutexes[i]);

        Node *current = hashTable[i];
        Node *prev = NULL;
        while (current != NULL) {
            if (current_time - current->timestamp >= TIME_WINDOW) {
                if (prev == NULL) {
                    // Remove head
                    hashTable[i] = current->next;
                } else {
                    prev->next = current->next;
                }
                Node *toDelete = current;
                current = current->next;
                free(toDelete);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&hashMutexes[i]);
    }
}

DataPacket* createDataPacket(int packetId, PayloadType payload) {
    time_t current_time = time(NULL);

    if (!isPacketIdAvailable(packetId, current_time)) {
        return NULL; // Packet ID is not available
    }

    DataPacket *packet = (DataPacket *)malloc(sizeof(DataPacket));
    packet->packetId = packetId;
    packet->timestamp = current_time;
    packet->payload.size = payload.size;
    packet->payload.data = malloc(payload.size);

    if (packet->payload.data != NULL) {
        memcpy(packet->payload.data, payload.data, payload.size);
    }

    addPacketId(packetId, current_time);

    return packet;
}

void freeDataPacket(DataPacket *packet) {
    if (packet) {
        free(packet->payload.data);
        free(packet);
    }
}

// Initialization function for hash table and mutexes
void initializeSystem() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hashTable[i] = NULL;
        pthread_mutex_init(&hashMutexes[i], NULL);
    }
}

// Cleanup function to free resources
void cleanupSystem() {
    time_t current_time = time(NULL);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        removeStalePacketIds(current_time);

        Node *current = hashTable[i];
        while (current != NULL) {
            Node *toDelete = current;
            current = current->next;
            free(toDelete);
        }

        pthread_mutex_destroy(&hashMutexes[i]);
    }
}

// Example of using the system in a multi-threaded environment
void* packetHandler(void *arg) {
    PayloadType payload = {.size = 128, .data = "example_payload"};
    DataPacket *packet = createDataPacket(rand() % 10000, payload);

    if (packet != NULL) {
        // Process the packet...

        freeDataPacket(packet);
    }

    return NULL;
}

int main() {
    initializeSystem();

    const int NUM_THREADS = 10;
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, packetHandler, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanupSystem();

    return 0;
}
```']

