['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int transactionID;
    char sourceIP[16];
    char destinationIP[16];
    size_t payloadSize;
    int status; // 0 for failure, 1 for success
} DataTransferObject;

int isTransactionIDUnique(DataTransferObject *array, int count, int id) {
    for (int i = 0; i < count; i++) {
        if (array[i].transactionID == id) {
            return 0;
        }
    }
    return 1;
}

DataTransferObject* initializeTransactions(int maxEntries, int defaultStatusOnFailure, int *failedAllocationCount, int *failedTransactionIDs[], int failedTransactionIDsSize) {
    DataTransferObject *transactions = (DataTransferObject *)malloc(maxEntries * sizeof(DataTransferObject));
    if (!transactions) {
        *failedAllocationCount = 1;
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    int transactionCount = 0;

    while (transactionCount < maxEntries) {
        DataTransferObject newTransaction;

        newTransaction.transactionID = rand() % 100000 + 1; // Generate a unique ID between 1 and 100000

        if (!isTransactionIDUnique(transactions, transactionCount, newTransaction.transactionID)) {
            continue;
        }

        snprintf(newTransaction.sourceIP, sizeof(newTransaction.sourceIP), "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(newTransaction.destinationIP, sizeof(newTransaction.destinationIP), "10.0.%d.%d", rand() % 256, rand() % 256);

        newTransaction.payloadSize = (size_t)(rand() % 1024 + 1); // Random payload size between 1 and 1024
        newTransaction.status = 1; // Assume success initially

        transactions[transactionCount] = newTransaction;
        transactionCount++;

        if (transactionCount == maxEntries) {
            break;
        }
    }

    if (transactionCount < maxEntries) {
        *failedAllocationCount = maxEntries - transactionCount;

        for (int i = 0; i < failedTransactionIDsSize && i < *failedAllocationCount; i++) {
            failedTransactionIDs[i] = &transactions[transactionCount + i].transactionID;
        }

        if (*failedAllocationCount > 0) {
            // Set default status for transactions that couldn't be added
            for (int i = transactionCount; i < maxEntries; i++) {
                transactions[i].status = defaultStatusOnFailure;
            }
        }
    } else {
        *failedAllocationCount = 0;
    }

    return transactions;
}

void freeTransactions(DataTransferObject *transactions) {
    if (transactions) {
        free(transactions);
    }
}
```

