#define MAX_INTS 100000

void readIntegers(int **numbers, int *count) {
    char buffer[256];
    int num;
    *count = 0;

    while (*count < MAX_INTS) {
        if (fgets(buffer, sizeof(buffer), stdin) == NULL) break;

        // Attempt to parse an integer from the input
        if (sscanf(buffer, "%d", &num) != 1) {
            printf("Invalid input. Please enter a valid integer: ");
            continue; // Prompt user again for valid input
        }

        *numbers = realloc(*numbers, (*count + 1) * sizeof(int));
        if (*numbers == NULL) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        (*numbers)[*count] = num;
        (*count)++;
    }
}

void calculateLargestAndAverage(int *numbers, int count) {
    long long sum = 0; // Use a larger integer type to prevent overflow
    int largest = INT_MIN;

    for (int i = 0; i < count; ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
        sum += numbers[i];
    }

    double average = (double)sum / count;
    printf("Largest integer: %d\n", largest);
    printf("Average: %.2f\n", average);

    if (average > 50.0) {
        printf("Above Average\n");
    } else {
        printf("Below Average\n");
    }
}

int main() {
    int *numbers = NULL;
    int count;

    readIntegers(&numbers, &count);

    if (count == 0) {
        printf("No valid integers were entered.\n");
        return EXIT_FAILURE;
    }

    calculateLargestAndAverage(numbers, count);

    free(numbers); // Clean up dynamically allocated memory
    return EXIT_SUCCESS;
}
