#include <curl/curl.h>

#define MAX_PACKETS 10000
#define TIMESTAMP_MIN 0
#define TIMESTAMP_MAX INT64_MAX
#define BYTE_COUNT_MAX INT32_MAX

typedef struct {
    char SRC_IP[16];
    char DST_IP[16];
    int64_t PACKET_TIMESTAMP;
    int32_t BYTE_COUNT;
} TRAFFIC_PACKET_T;

typedef struct {
    size_t length;
    size_t capacity;
    TRAFFIC_PACKET_T *packets;
} PacketArray;

typedef void (*ResourceAlertCallback)(const char* message);

typedef struct {
    size_t key_hash;
    char SRC_IP[16];
    char DST_IP[16];
    int64_t total_bytes;
    pthread_mutex_t lock;
} NetworkFlowEntry;

#define HASH_MAP_SIZE 1024

// Function prototypes
void processAndAnalyzeTrafficPackets(ResourceAlertCallback alert_callback, int top_n);
int is_valid_packet(const TRAFFIC_PACKET_T *packet);
int populate_data(PacketArray *array);
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata);
void analyze_traffic(PacketArray *array, int top_n);
NetworkFlowEntry* get_network_flow(NetworkFlowEntry hash_map[], const char* src_ip, const char* dst_ip);
int add_packet_to_array(PacketArray *array, TRAFFIC_PACKET_T packet);

// Global variables for monitoring
pthread_mutex_t resource_lock = PTHREAD_MUTEX_INITIALIZER;
double cpu_usage_threshold = 80.0; // Percent
size_t memory_usage_threshold = 1000000; // Bytes

void processAndAnalyzeTrafficPackets(ResourceAlertCallback alert_callback, int top_n) {
    PacketArray packet_array = { .length = 0, .capacity = 10, .packets = malloc(sizeof(TRAFFIC_PACKET_T) * 10) };

    if (!populate_data(&packet_array)) {
        free(packet_array.packets);
        return;
    }

    analyze_traffic(&packet_array, top_n);

    for (size_t i = 0; i < packet_array.length; ++i) {
        free(packet_array.packets[i].SRC_IP);
        free(packet_array.packets[i].DST_IP);
    }

    free(packet_array.packets);
}

int is_valid_packet(const TRAFFIC_PACKET_T *packet) {
    return (packet->PACKET_TIMESTAMP >= TIMESTAMP_MIN && packet->PACKET_TIMESTAMP <= TIMESTAMP_MAX &&
            packet->BYTE_COUNT >= 0 && packet->BYTE_COUNT <= BYTE_COUNT_MAX);
}

int populate_data(PacketArray *array) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/traffic-packets");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, array);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return 0;
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }

    // Validate and add packets to array
    TRAFFIC_PACKET_T *packet = NULL; 
    for (size_t i = 0; i < array->length; ++i) {
        packet = &array->packets[i];

        if (!is_valid_packet(packet)) {
            continue;
        }

        // Check uniqueness of SRC_IP and DST_IP
        int unique = 1;
        for (size_t j = 0; j < i; ++j) {
            if ((strcmp(packet->SRC_IP, array->packets[j].SRC_IP) == 0 && strcmp(packet->DST_IP, array->packets[j].DST_IP) == 0) ||
                (strcmp(packet->SRC_IP, array->packets[j].DST_IP) == 0 && strcmp(packet->DST_IP, array->packets[j].SRC_IP) == 0)) {
                unique = 0;
                break;
            }
        }

        if (unique) {
            add_packet_to_array(array, *packet);
        }
    }

    return 1;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    PacketArray *array = userdata;
    size_t real_size = size * nmemb;

    if (array->length + real_size > array->capacity) {
        while (array->length + real_size > array->capacity) {
            array->capacity *= 2;
        }
        array->packets = realloc(array->packets, sizeof(TRAFFIC_PACKET_T) * array->capacity);
    }

    // Simulate packet extraction from the JSON data
    memcpy(&array->packets[array->length], ptr, real_size);
    array->length += real_size / sizeof(TRAFFIC_PACKET_T);

    return real_size;
}

void analyze_traffic(PacketArray *array, int top_n) {
    NetworkFlowEntry hash_map[HASH_MAP_SIZE] = {0};

    for (size_t i = 0; i < array->length; ++i) {
        TRAFFIC_PACKET_T *packet = &array->packets[i];

        NetworkFlowEntry *entry = get_network_flow(hash_map, packet->SRC_IP, packet->DST_IP);
        if (entry) {
            pthread_mutex_lock(&entry->lock);
            entry->total_bytes += packet->BYTE_COUNT;
            pthread_mutex_unlock(&entry->lock);
        }
    }

    // Find top N busiest flows
    NetworkFlowEntry *top_flows = malloc(sizeof(NetworkFlowEntry) * top_n);
    for (size_t i = 0; i < HASH_MAP_SIZE; ++i) {
        if (hash_map[i].total_bytes > 0) {
            int j;
            for (j = 0; j < top_n && top_flows[j].total_bytes != 0; ++j);

            if (j < top_n) {
                pthread_mutex_lock(&hash_map[i].lock);
                top_flows[j] = hash_map[i];
                pthread_mutex_unlock(&hash_map[i].lock);

                // Sort top flows array
                for (int k = j + 1; k > 0 && top_flows[k - 1].total_bytes < top_flows[k].total_bytes; --k) {
                    NetworkFlowEntry temp = top_flows[k];
                    top_flows[k] = top_flows[k - 1];
                    top_flows[k - 1] = temp;
                }
            }
        }
    }

    printf("Top %d busiest network flows:\n", top_n);
    for (int i = 0; i < top_n && top_flows[i].total_bytes != 0; ++i) {
        printf("Flow from %s to %s with total bytes: %ld\n",
               top_flows[i].SRC_IP, top_flows[i].DST_IP, top_flows[i].total_bytes);
    }

    free(top_flows);
}

NetworkFlowEntry* get_network_flow(NetworkFlowEntry hash_map[], const char* src_ip, const char* dst_ip) {
    size_t key_hash = 0;

    for (size_t i = 0; src_ip[i] != '\0'; ++i) {
        key_hash = key_hash * 31 + src_ip[i];
    }

    for (size_t i = 0; dst_ip[i] != '\0'; ++i) {
        key_hash = key_hash * 31 + dst_ip[i];
    }

    size_t index = key_hash % HASH_MAP_SIZE;

    if (hash_map[index].key_hash == 0 || 
        (strcmp(hash_map[index].SRC_IP, src_ip) == 0 && strcmp(hash_map[index].DST_IP, dst_ip) == 0)) {

        pthread_mutex_lock(&resource_lock);
        if (hash_map[index].key_hash == 0) {
            snprintf(hash_map[index].SRC_IP, sizeof(hash_map[index].SRC_IP), "%s", src_ip);
            snprintf(hash_map[index].DST_IP, sizeof(hash_map[index].DST_IP), "%s", dst_ip);
            pthread_mutex_init(&hash_map[index].lock, NULL);
        }
        hash_map[index].key_hash = key_hash;
        pthread_mutex_unlock(&resource_lock);

        return &hash_map[index];
    }

    return NULL;
}

int add_packet_to_array(PacketArray *array, TRAFFIC_PACKET_T packet) {
    pthread_mutex_lock(&resource_lock);
    if (array->length >= array->capacity) {
        array->capacity *= 2;
        array->packets = realloc(array->packets, sizeof(TRAFFIC_PACKET_T) * array->capacity);
    }

    array->packets[array->length++] = packet;
    pthread_mutex_unlock(&resource_lock);

    return 1;
}
