    *ptr = NULL; // Terminate the linked list

    pthread_mutex_unlock(&list_mutex);
    return head;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
