    size_t list_size = *(size_t*)arg;

    NFAPI_CRC_INDICATION_PDU_T* crc_list = create_crc_list(list_size);
    if (crc_list == NULL) {
        fprintf(stderr, "Failed to create CRC list\n");
        return NULL;
