#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RNTI_MIN 0x0001FFFF
#define RNTI_MAX 0x0010FFFF

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    size_t current_usage;
} MemoryPool;

void initialize_memory_pool(MemoryPool *mp, size_t initial_size) {
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(64, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mp->pool_size = initial_size;
    mp->current_usage = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void free_memory_pool(MemoryPool *mp) {
    aligned_free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

void manage_nfa_list(size_t num_elements, MemoryPool *mp) {
    if (num_elements > mp->pool_size) {
        size_t new_size = num_elements;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(64, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            perror("Failed to reallocate memory pool");
            exit(EXIT_FAILURE);
        }
        memcpy(new_pool, mp->pool, mp->current_usage * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        aligned_free(mp->pool);
        mp->pool = new_pool;
        mp->pool_size = new_size;
    }

    pthread_mutex_lock(&mp->lock);

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &mp->pool[mp->current_usage++];

        pdu->RX_UE_INFORMATION_TAG = rand(); // Simulate a valid tag
        pdu->RNTI = rand() % (RNTI_MAX + 1);

        if (pdu->RNTI < RNTI_MIN || pdu->RNTI > RNTI_MAX) {
            printf("Error: Invalid RNTI value %u\n", pdu->RNTI);
            continue;
        }

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Random CRCFLAG
    }

    pthread_mutex_unlock(&mp->lock);

    // Monitor memory usage (for demonstration purposes)
    printf("Memory pool current usage: %zu/%zu\n", mp->current_usage, mp->pool_size);
}

int main() {
    srand(time(NULL));

    MemoryPool mp;
    initialize_memory_pool(&mp, 1000); // Start with a pool of 1000 elements

    manage_nfa_list(5000, &mp); // Manage list with 5000 elements

    free_memory_pool(&mp);

    return 0;
}
