    // Add other frame types as needed.
} FRAME_TYPE;

typedef struct LTE_PHY_FRAME_INFO {
    FRAME_TYPE frame_type;
    int tx_power;
    int time_slot;
    struct LTE_PHY_FRAME_INFO *prev;
    struct LTE_PHY_FRAME_INFO *next;
};

typedef struct {
    struct LTE_PHY_FRAME_INFO *head;
    struct LTE_PHY_FRAME_INFO *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList *list) {
    struct LTE_PHY_FRAME_INFO* current = list->head;
    while (current != NULL) {
        struct LTE_PHY_FRAME_INFO* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_frame(DoublyLinkedList *list, FRAME_TYPE frame_type, int tx_power, int time_slot) {
    if (!list || frame_type < 0 || tx_power < -100 || tx_power > 100 || time_slot < 0) {
        return -1;
    }

    struct LTE_PHY_FRAME_INFO* new_node = (struct LTE_PHY_FRAME_INFO*)malloc(sizeof(struct LTE_PHY_FRAME_INFO));
    if (!new_node) return -1;

    new_node->frame_type = frame_type;
    new_node->tx_power = tx_power;
    new_node->time_slot = time_slot;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_frame(DoublyLinkedList *list, int time_slot) {
    if (!list || time_slot < 0) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    struct LTE_PHY_FRAME_INFO* current = list->head;
    while (current != NULL && current->time_slot != time_slot) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void process_frames(DoublyLinkedList *list) {
