    struct LTE_PHY_FRAME_INFO* current = list->head;

    while (current != NULL) {
        // Process the frame based on FRAME_TYPE, TX_POWER, and TIME_SLOT
        // Placeholder for processing logic

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

