#include <stdio.h>
#include <stdlib.h>
import sys
import socket
from queue import Queue
from threading import Thread, Lock

# Constants
MAX_INT = 1000
BUFFER_SIZE = 1024

class NetworkProcessor:
    def __init__(self):
        self.lock = Lock()
        self.data_queue = Queue()

    def process_stream(self, sock):
        while True:
            try:
                data = sock.recv(BUFFER_SIZE)
                if not data:
                    break

                numbers = map(int, data.decode().split())
                for number in numbers:
                    self.validate_and_store(number)

            except socket.timeout:
                print("Network timeout occurred.")
            except Exception as e:
                print(f"Error: {str(e)}")

        self.print_largest_valid_integer()

    def validate_and_store(self, number):
        if 0 <= number <= MAX_INT:
            with self.lock:
                self.data_queue.put(number)
        else:
            print(f"Invalid integer received: {number}")

    def find_largest_in_queue(self):
        largest = None
        while not self.data_queue.empty():
            num = self.data_queue.get()
            if largest is None or num > largest:
                largest = num
        return largest

    def print_largest_valid_integer(self):
        with self.lock:
            largest = self.find_largest_in_queue()
            if largest is not None:
                print(f"Largest valid integer: {largest}")
            else:
                print("No valid integers found")

def handle_client_connection(client_socket, processor):
    client_socket.settimeout(5)  # Set timeout for network operations
    processor.process_stream(client_socket)
    client_socket.close()

def main():
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.bind(('0.0.0.0', 12345))
    server.listen(10)

    processor = NetworkProcessor()

    try:
        while True:
            client_sock, addr = server.accept()
            print(f"Accepted connection from {addr}")
            client_thread = Thread(target=handle_client_connection, args=(client_sock, processor))
            client_thread.start()

    except KeyboardInterrupt:
        print("Server shutting down.")
    finally:
        server.close()

if __name__ == "__main__":
    main()
