typedef struct {
    unsigned int ip_address;
    unsigned short port_number;
    int syn_flag;
    unsigned long sequence_number;  // Unique sequence number for each connection request
} TCP_CONNECTION_REQUEST;

typedef struct Node {
    TCP_CONNECTION_REQUEST data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;            // Mutex for thread-safe access
    unsigned long current_sequence;  // To generate unique sequence numbers
} DynamicQueue;

// Initialize the dynamic queue
DynamicQueue* create_queue() {
    DynamicQueue* queue = (DynamicQueue*)malloc(sizeof(DynamicQueue));
    if (!queue) return NULL;

    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->current_sequence = 0;

    return queue;
}

// Add a new connection request to the queue
int enqueue_request(DynamicQueue* queue, unsigned int ip_address, unsigned short port_number, int syn_flag) {
    if (!queue) return -1;

    pthread_mutex_lock(&queue->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    // Assign unique sequence number
    new_node->data.sequence_number = queue->current_sequence++;
    new_node->data.ip_address = ip_address;
    new_node->data.port_number = port_number;
    new_node->data.syn_flag = syn_flag;

    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

// Remove and return a connection request from the front of the queue
int dequeue_request(DynamicQueue* queue, TCP_CONNECTION_REQUEST* out_request) {
    if (!queue || !out_request) return -1;

    pthread_mutex_lock(&queue->lock);

    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }

    Node* temp_node = queue->head;
    *out_request = temp_node->data;
    queue->head = queue->head->next;

    if (!queue->head) {
        queue->tail = NULL;
    }

    free(temp_node);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

// Clean up the dynamic queue
void destroy_queue(DynamicQueue* queue) {
    if (!queue) return;

    pthread_mutex_lock(&queue->lock);

    Node* current = queue->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&queue->lock);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

// Example usage
int main() {
    DynamicQueue* queue = create_queue();

    enqueue_request(queue, 0xC0A80101, 8080, 1); // Sample IP and port
    TCP_CONNECTION_REQUEST request;

    if (dequeue_request(queue, &request) == 0) {
        printf("Dequeued Request: IP=%u, Port=%hu, SYN=%d, SeqNum=%lu\n",
               request.ip_address, request.port_number, request.syn_flag, request.sequence_number);
    }

    destroy_queue(queue);

    return 0;
}
```

