        if (!new_bitmaps) exit(EXIT_FAILURE);
        cache->bitmaps = new_bitmaps;
        for (size_t i = cache->count; i < cache->capacity * 2; ++i) {
            cache->bitmaps[i] = NULL;
        }
        cache->capacity *= 2;
    }

