    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    return 0;
}

int validate_context(const LTE_UE_Context* context) {
    if (!context || context->ue_id <= 0) return 0; // Invalid UE ID
    for (int i = 0; i < 3; ++i) {
        if (context->measurement_results[i] == 0.0f) return 0; // Corrupted data check
    }
    if (context->dci_message[0] == '\0') return 0; // Invalid DCI message
    return 1;
}

LTE_UE_Context create_default_context(int ue_id) {
    LTE_UE_Context context = { .ue_id = ue_id, .measurement_results = { -100.0f, -10.0f, 5.0f }, .dci_message = "Default-DCI" };
    return context;
}

Node* initialize_ue_context_list(size_t num_ue, const LTE_UE_Context** data_sources, size_t data_source_count) {
    Node* head = NULL;
    Node* tail = NULL;

    for (size_t i = 0; i < num_ue; ++i) {
        // Simulating rapid updates with minimal latency
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            return head;
        }

        LTE_UE_Context context;

        // Randomly choose a source or use default if none valid
        int random_source_index = rand() % data_source_count;
        const LTE_UE_Context* chosen_source = data_sources[random_source_index];

        if (validate_context(chosen_source)) {
            context = *chosen_source;  // Copy from a valid data source
        } else {
            context = create_default_context(i + 1);  // Use default for corrupted or missing data
        }

        new_node->context = context;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}
