NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t n, size_t budget) {
    // Ensure thread-safe access with mutex lock
    pthread_mutex_lock(&nfa_lock);

    if (budget < sizeof(NFAPI_CRC_INDICATION_PDU_T) * n) {
        log_error("Memory allocation failed due to insufficient budget.");
        pthread_mutex_unlock(&nfa_lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(budget);

    if (!pdu_list) {
        log_error("Memory allocation error occurred.");
        pthread_mutex_unlock(&nfa_lock);
        return NULL;
