#include <iostream>
#include <string>
#include <random>
#include <chrono>
#include <mutex>
#include <thread>
#include <curl/curl.h>

namespace ResourceHandler {

class ResourceController {
public:
    ResourceController() : rng(std::random_device{}()) {}

    ~ResourceController() {
        // Destructor for cleanup if needed
    }

    std::string updateResource(const std::string& resourceId, const std::string& requestBody) {
        std::lock_guard<std::mutex> lock(httpMutex);

        CURL* curl = curl_easy_init();
        if(curl) {
            std::string url = "http://example.com/resource/" + resourceId;
            struct curl_slist* headers = nullptr;
            headers = curl_slist_append(headers, "Content-Type: application/json");

            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "PUT");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, requestBody.c_str());

            CURLcode res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << '\n';
            }

            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

            // Assume the updated resource is returned in JSON format
            std::string updatedResource = "Updated Resource Data for ID " + resourceId;

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);

            return updatedResource;
        }

        return "";
    }

    bool deleteResource(const std::string& resourceId) {
        std::lock_guard<std::mutex> lock(httpMutex);

        CURL* curl = curl_easy_init();
        if(curl) {
            std::string url = "http://example.com/resource/" + resourceId;

            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "DELETE");

            CURLcode res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << '\n';
            }

            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

            bool success = (response_code == 200 || response_code == 204);

            curl_easy_cleanup(curl);

            return success;
        }

        return false;
    }

    int generateRandomNumber() {
        std::lock_guard<std::mutex> lock(rngMutex);
        return rng();
    }

private:
    std::mt19937 rng;
    static std::mutex httpMutex;
    static std::mutex rngMutex;
};

std::mutex ResourceController::httpMutex;
std::mutex ResourceController::rngMutex;

} // namespace ResourceHandler

int main() {
    ResourceHandler::ResourceController controller;

    std::string resourceId = "12345";
    std::string requestBody = R"({"name": "UpdatedName"})";

    auto updatedResource = controller.updateResource(resourceId, requestBody);
    std::cout << "Updated Resource: " << updatedResource << '\n';

    bool isDeleted = controller.deleteResource(resourceId);
    std::cout << "Resource Deleted: " << (isDeleted ? "Yes" : "No") << '\n';

    int randomValue = controller.generateRandomNumber();
    std::cout << "Random Number Generated: " << randomValue << '\n';

    return 0;
}
```

### Key Points:
