void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int validate_struct(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu == NULL || pdu->RNTI <= 0) {
        return 0; // Invalid
    }
    return 1; // Valid
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T **list, int size) {
    for (int i = 0; i < size; ++i) {
        free(list[i]);
    }
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T** manage_linked_list(int requested_size, int* error_code) {
    *error_code = 0;

    if (requested_size > MAX_STRUCTURES) {
        log_error("Requested size exceeds maximum limit.");
        return NULL;
    }

    AllocationType allocation_type = get_allocation_type();
    NFAPI_CRC_INDICATION_PDU_T **list = NULL;

    if (allocation_type == HEAP_ALLOCATION) {
        list = malloc(requested_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) {
            log_error("Memory allocation failed for heap.");
            *error_code = 1;
            return NULL;
        }

        for (int i = 0; i < requested_size; ++i) {
            list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!list[i]) {
                log_error("Memory allocation failed for heap-based structures.");
                free_resources(list, i);
                *error_code = 1;
                return NULL;
            }

            // Initialize structure with random RNTI and CRCFLAG
            list[i]->RNTI = rand() % (MAX_STRUCTURES + 1); // Ensure positive non-zero value
            list[i]->CRCFLAG = rand() % 2; // Randomly set to 0 or 1

            if (!validate_struct(list[i])) {
                free_resources(list, i + 1);
                *error_code = 1;
                return NULL;
            }
        }

    } else { // STACK_ALLOCATION
        NFAPI_CRC_INDICATION_PDU_T stack_list[MAX_STRUCTURES];

        for (int i = 0; i < requested_size; ++i) {
            list[i] = &stack_list[i];

            // Initialize structure with random RNTI and CRCFLAG
            list[i]->RNTI = rand() % (MAX_STRUCTURES + 1); // Ensure positive non-zero value
            list[i]->CRCFLAG = rand() % 2; // Randomly set to 0 or 1

            if (!validate_struct(list[i])) {
                *error_code = 1;
                return NULL;
            }
        }
    }

    // Sort the list based on RNTI in ascending order
    for (int i = 0; i < requested_size - 1; ++i) {
        for (int j = i + 1; j < requested_size; ++j) {
            if (list[i]->RNTI > list[j]->RNTI) {
                NFAPI_CRC_INDICATION_PDU_T* temp = list[i];
                list[i] = list[j];
                list[j] = temp;
            }
        }
    }

    // Ensure unique RNTI values
    for (int i = 0; i < requested_size - 1; ++i) {
        if (list[i]->RNTI == list[i + 1]->RNTI) {
            log_error("Duplicate RNTI found in the list.");
            free_resources(list, requested_size);
            *error_code = 1;
            return NULL;
        }
    }

    return list;
}
