// Function prototypes
int initialize_measurement_manager(MeasurementManager *manager);
void finalize_measurement_manager(MeasurementManager *manager);
int add_measurement_report(MeasurementManager *manager, int result, int retry_count);

int acquire_data_with_retries(int *result, int max_attempts) {
    // Simulate data acquisition with retries
    for (int attempt = 0; attempt < max_attempts; ++attempt) {
        // Replace this logic with actual data acquisition code
        if (rand() % 2 == 0) {  // Simulating a 50% chance of success
            *result = rand() % (MAX_MEASUREMENT_RESULT + 1);
            return 1;
        }
    }
    return 0;  // Failed to acquire data
}

int initialize_measurement_manager(MeasurementManager *manager) {
    if (!manager) return -1;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->reports = (NFAPI_RRC_MEASUREMENT_REPORT_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_T));
    if (!manager->reports) {
        perror("Failed to allocate memory");
        return -1;
    }
    manager->count = 0;

    return 0;
}

void finalize_measurement_manager(MeasurementManager *manager) {
    if (manager && manager->reports) {
        free(manager->reports);
        pthread_mutex_destroy(&manager->mutex);
    }
}

int add_measurement_report(MeasurementManager *manager, int result, int retry_count) {
    if (!manager || manager->count >= MAX_STRUCTURES) return -1;

    pthread_mutex_lock(&manager->mutex);

    NFAPI_RRC_MEASUREMENT_REPORT_T new_report;
    new_report.MEASUREMENT_ID = manager->count + 1;
    new_report.RRC_MEASUREMENT_TAG = rand() % 1000;  // Simulating tag generation

    if (acquire_data_with_retries(&result, retry_count)) {
        if (result < MIN_MEASUREMENT_RESULT || result > MAX_MEASUREMENT_RESULT) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        new_report.MEASUREMENT_RESULT = result;
        manager->reports[manager->count++] = new_report;
    } else {
        fprintf(stderr, "Failed to acquire measurement data after retries.\n");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void iterate_measurement_reports(const MeasurementManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        printf("ID: %d, Tag: %d, Result: %d\n",
               manager->reports[i].MEASUREMENT_ID,
               manager->reports[i].RRC_MEASUREMENT_TAG,
               manager->reports[i].MEASUREMENT_RESULT);
    }

    pthread_mutex_unlock(&manager->mutex);
}

int main() {
    MeasurementManager manager;

    if (initialize_measurement_manager(&manager) != 0) {
        fprintf(stderr, "Failed to initialize measurement manager.\n");
        return -1;
    }

    for (int i = 0; i < 10; ++i) {
        if (add_measurement_report(&manager, -1, 3) != 0) {
            fprintf(stderr, "Failed to add a measurement report.\n");
        }
    }

    iterate_measurement_reports(&manager);
    finalize_measurement_manager(&manager);

    return 0;
}
