Collection* initialize_collection(size_t num_records, int min_key, int max_key) {
    if (num_records == 0 || min_key >= max_key) return NULL;

    Collection* collection = malloc(sizeof(Collection));
    if (!collection) {
        fprintf(stderr, "Failed to allocate memory for the collection.\n");
        return NULL;
    }

    collection->records = malloc(num_records * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        fprintf(stderr, "Failed to allocate memory for records array.\n");
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);
    collection->num_records = num_records;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for a record.\n");
            // Clean up previously allocated records
            while (--i > 0) free(collection->records[i]);
            free(collection->records);
            free(collection);
            return NULL;
        }

        collection->records[i] = record;
        record->key = min_key + rand() % (max_key - min_key + 1);

        snprintf(record->name, MAX_NAME_LENGTH + 1, "Record_%d", i); // Example name

        // Simulate fetching offset data from an external source
        int num_offsets = rand() % 10; // Random number of offsets for demonstration

        OffsetNode* head = NULL;
        OffsetNode** current = &head;

        for (int j = 0; j < num_offsets; ++j) {
            OffsetNode* node = malloc(sizeof(OffsetNode));
            if (!node) {
                fprintf(stderr, "Failed to allocate memory for an offset node.\n");
                // Free previously allocated offset nodes
                while (*current) {
                    OffsetNode* temp = *current;
                    *current = (*current)->next;
                    free(temp);
                }
                free(record); // Free the record
                continue;     // Attempt next record
            }

            node->offset = rand() % 1000; // Random offset value
            node->next = NULL;
            *current = node;
            current = &(*current)->next;
        }

        record->offsets = head;
    }

    return collection;
}

void free_collection(Collection* collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->num_records; ++i) {
        Record* record = collection->records[i];
        OffsetNode* offset_node = record->offsets;

        while (offset_node) {
            OffsetNode* temp = offset_node;
            offset_node = offset_node->next;
            free(temp);
        }

        free(record);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Example of logging failure
void log_failure(const char* message) {
    // You can expand this function to log errors more comprehensively if needed.
    fprintf(stderr, "%s\n", message);
}
