['Below is a C code implementation that addresses your requirements for managing a dynamic list of LTE UE context structures using a custom memory pool with thread safety and efficient management:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_UE_CONTEXTS 1000
#define CONTEXT_POOL_SIZE 200

typedef struct {
    int ue_id;
    float measurement_results[10];
    char dci_message[256];
} UEContext;

typedef struct MemoryBlock {
    UEContext data;
    struct MemoryBlock* next;
} MemoryBlock;

typedef struct {
    MemoryBlock* free_list_head;
    pthread_mutex_t lock;
    int active_count;
} UEMemoryPool;

UEMemoryPool pool = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

// Function to initialize the memory pool
void init_memory_pool() {
    for (int i = 0; i < CONTEXT_POOL_SIZE; ++i) {
        MemoryBlock* block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
        if (!block) {
            fprintf(stderr, "Failed to allocate memory for UE context\n");
            exit(EXIT_FAILURE);
        }
        block->next = pool.free_list_head;
        pool.free_list_head = block;
    }
}

// Function to get a UEContext from the pool
UEContext* get_ue_context(int ue_id) {
    pthread_mutex_lock(&pool.lock);

    if (pool.active_count >= MAX_UE_CONTEXTS) {
        fprintf(stderr, "Maximum number of active UE contexts reached\n");
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    MemoryBlock* block = pool.free_list_head;
    if (!block) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    // Remove from free list
    pool.free_list_head = block->next;

    UEContext* context = &block->data;
    memset(context, 0, sizeof(UEContext));
    context->ue_id = ue_id;
    pool.active_count++;

    pthread_mutex_unlock(&pool.lock);
    return context;
}

// Function to release a UEContext back to the pool
void release_ue_context(UEContext* context) {
    if (!context) return;

    pthread_mutex_lock(&pool.lock);

    MemoryBlock* block = (MemoryBlock*)(((char*)context) - offsetof(MemoryBlock, data));
    block->next = pool.free_list_head;
    pool.free_list_head = block;
    pool.active_count--;

    pthread_mutex_unlock(&pool.lock);
}

// Periodic cleanup function for inactive UE contexts
void* periodic_cleanup(void* arg) {
    while (1) {
        sleep(60); // Run every 60 seconds

        pthread_mutex_lock(&pool.lock);

        // Example logic to remove inactive contexts
        // Here we just print the active count for simplicity
        printf("Active UE contexts: %d\n", pool.active_count);

        pthread_mutex_unlock(&pool.lock);
    }
    return NULL;
}

// Main function demonstrating usage
int main() {
    init_memory_pool();

    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, periodic_cleanup, NULL) != 0) {
        fprintf(stderr, "Failed to create cleanup thread\n");
        exit(EXIT_FAILURE);
    }

    UEContext* context = get_ue_context(1234);
    if (context) {
        printf("UE Context acquired for UE ID: %d\n", context->ue_id);
        // Use the context...

        release_ue_context(context);
    }

    pthread_join(cleanup_thread, NULL);

    return 0;
}
```

### Key Points:
- **Custom Memory Pool**: The memory pool is initialized with a fixed number of `MemoryBlock` structures to minimize fragmentation and improve allocation efficiency.
- **Thread Safety**: A mutex (`pthread_mutex_t`) ensures thread-safe access to the memory pool.
- **Active Context Limitation**: There's a limit on the maximum number of active UE contexts to prevent resource exhaustion.
- **Periodic Cleanup**: A separate thread periodically checks for inactive contexts (currently just prints active count as an example).
- **Error Handling**: Includes checks and error messages for allocation failures and reaching the maximum context limit.

This code provides a scalable and efficient way to manage UE contexts in a multi-threaded environment, with considerations for memory usage and performance.']

