#include <string.h>

typedef struct {
    int ue_id;
    double measurement_results;
    char dci_message[256];
} LTE_UE_Context;

typedef struct Node {
    LTE_UE_Context *context;
    struct Node* next;
} Node;

Node* create_node(LTE_UE_Context *context) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->context = context;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->context);
        free(current);
        current = next;
    }
    *head = NULL;
}

int add_ue_context(Node **head, int ue_id, double measurement_results, const char *dci_message) {
    LTE_UE_Context *context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_CONTEXT));
    if (!context) return -1;

    context->ue_id = ue_id;
    context->measurement_results = measurement_results ? measurement_results : 0.0;
    strncpy(context->dci_message, dci_message ? dci_message : "Default DCI Message", sizeof(context->dci_message));

    Node *new_node = create_node(context);
    if (!new_node) {
        free(context);
        return -1;
    }

    new_node->next = *head;
    *head = new_node;

    return 0; // Success
}

void initialize_ue_context_list(Node **head, int num_ues) {
