#include <string.h>
#include <pthread.h>

#define LOG_FORMAT "Timestamp: %ld, UE_ID: %u, Message: %s\n"
#define DEFAULT_BUFFER_SIZE 1024

typedef struct {
    uint32_t ue_id;
    char *decoded_data_buffer;
    int64_t timestamp; // Use a suitable type for timestamps
} NFAPI_UL_RX_FRAME_PDU_T;

typedef struct {
    size_t buffer_size;
    size_t pool_size;
    char **buffers;
    pthread_mutex_t lock;
} BufferPool;

BufferPool* create_buffer_pool(size_t buffer_size, size_t pool_size) {
    BufferPool *pool = (BufferPool *)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pool->buffer_size = buffer_size;
    pool->pool_size = pool_size;
    pool->buffers = (char **)malloc(pool_size * sizeof(char *));
    if (!pool->buffers) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < pool_size; ++i) {
        pool->buffers[i] = (char *)malloc(buffer_size);
        if (!pool->buffers[i]) {
            while (--i >= 0) free(pool->buffers[i]);
            free(pool->buffers);
            free(pool);
            return NULL;
        }
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_buffer_pool(BufferPool *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->pool_size; ++i) {
        free(pool->buffers[i]);
    }
    free(pool->buffers);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_UL_RX_FRAME_PDU_T* initialize_nfaapi_ul_rx_frame_pdu_array(size_t num_frames, uint32_t (*get_ue_id)(size_t), int64_t (*get_timestamp)(void)) {
    if (!num_frames || !get_ue_id || !get_timestamp) return NULL;

    NFAPI_UL_RX_FRAME_PDU_T *array = (NFAPI_UL_RX_FRAME_PDU_T *)calloc(num_frames, sizeof(NFAPI_UL_RX_FRAME_PDU_T));
    if (!array) {
        fprintf(stderr, LOG_FORMAT, get_timestamp(), 0, "Failed to allocate memory for frame array\n");
        return NULL;
    }

    BufferPool *pool = create_buffer_pool(DEFAULT_BUFFER_SIZE, num_frames);
    if (!pool) {
        free(array);
        fprintf(stderr, LOG_FORMAT, get_timestamp(), 0, "Failed to initialize buffer pool\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < num_frames; ++i) {
        array[i].ue_id = get_ue_id(i);
        if (i >= pool->pool_size) {
            fprintf(stderr, LOG_FORMAT, get_timestamp(), array[i].ue_id, "Out of buffer space\n");
            pthread_mutex_unlock(&pool->lock);
            destroy_buffer_pool(pool);
            free(array);
            return NULL;
        }
        array[i].decoded_data_buffer = pool->buffers[i];
        array[i].timestamp = get_timestamp();
    }

    pthread_mutex_unlock(&pool->lock);

    return array;
}

void log_message(int64_t timestamp, uint32_t ue_id, const char *message) {
    fprintf(stdout, LOG_FORMAT, timestamp, ue_id, message);
}

// Unit tests
void test_initialize_nfaapi_ul_rx_frame_pdu_array() {
