#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int is_full(const List* list, size_t M) {
    return list->size >= M;
}

NFAPI_CRC_INDICATION_PDU_T create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Initialize with some values or logic
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand();
    pdu.CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    return pdu;
}

void evict_oldest(List* list) {
    if (list->head == NULL) return;

    Node* temp = list->head;
    list->head = list->head->next;
    free(temp);
    list->size--;

    if (list->head == NULL) {
        list->tail = NULL;
    }
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu, size_t M) {
    pthread_mutex_lock(&list->mutex);

    if (is_full(list, M)) {
        evict_oldest(list);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->data = pdu;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    }

    list->tail = new_node;

    if (list->head == NULL) {
        list->head = new_node;
    }

    list->size++;

    // Log the capacity usage
    printf("List size: %zu/%zu\n", list->size, M);

    pthread_mutex_unlock(&list->mutex);
}

void get_statistics(const List* list) {
    if (list->size == 0) return;

    time_t now = time(NULL);
    double total_age = 0;
    double max_age = 0;

    Node* current = list->head;
    while (current != NULL) {
        double age = difftime(now, current->timestamp);
        total_age += age;
        if (age > max_age) {
            max_age = age;
        }
        current = current->next;
    }

    double average_age = total_age / list->size;

    // Log the statistics
    printf("Average age: %.2f seconds\n", average_age);
    printf("Max age: %.2f seconds\n", max_age);
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
}
```

This code provides a thread-safe implementation for managing a dynamically sized list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes logic to maintain the list size within a configurable limit and evicts the oldest elements when necessary. The function also logs capacity usage and statistics on element ages, optimizing for efficient memory and CPU utilization in high throughput scenarios.']

['Below is a C# implementation for handling HTTP POST, PUT, and DELETE requests in an ASP.NET Core Web API. This example assumes the use of a service layer, caching, and unit tests using xUnit.

### Controller Implementation

```csharp
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

[ApiController]
[Route("api/[controller]")]
public class PageElementController : ControllerBase
{
    private readonly IPageElementService _pageElementService;
    private readonly ICacheService _cacheService;

    public PageElementController(IPageElementService pageElementService, ICacheService cacheService)
    {
        _pageElementService = pageElementService;
        _cacheService = cacheService;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElementAsync([FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        await _pageElementService.UpdateElementContentAsync(request.PageSectionId, request.ElementId, request.HtmlContent);
        _cacheService.ClearCacheForKey(request.ElementId);

        return Ok(new { message = "Page should be refreshed" });
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResourceAsync(string id, [FromBody] ResourceUpdateRequest updateRequest)
    {
        if (!ModelState.IsValid || string.IsNullOrEmpty(id))
            return BadRequest(ModelState);

        var resource = await _pageElementService.GetResourceByIdAsync(id);

        if (resource == null)
            return NotFound();

        if (resource.Version != updateRequest.Version)
            return Conflict("Version conflict detected.");

        var updatedResource = await _pageElementService.UpdateResourceAsync(id, updateRequest.Data);

        _cacheService.ClearCacheForKey(id);

        return Ok(new { resource = updatedResource, changesSummary = "Updated successfully" });
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResourceAsync(string id)
    {
        if (string.IsNullOrEmpty(id))
            return BadRequest("Invalid identifier.");

        var deletedResource = await _pageElementService.DeleteResourceAsync(id);

        _cacheService.ClearCacheForKey(id);

        return Ok(new { deletedResource = new DefaultResource(), versionHistory = "Deleted successfully" });
    }
}
```

