['```java
import java.io.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class MoSTStateCache {

    private static final Logger logger = Logger.getLogger(MoSTStateCache.class.getName());
    private final ConcurrentHashMap<String, CacheEntry> cache;
    private final int maxCacheSize;
    private final long expirationTimeMillis;

    public MoSTStateCache(int maxCacheSize, long expirationTimeMillis) {
        this.maxCacheSize = maxCacheSize;
        this.expirationTimeMillis = expirationTimeMillis;
        this.cache = new ConcurrentHashMap<>();
    }

    public Object loadMoSTStateFromFile(String filePath) {
        if (cache.size() >= maxCacheSize) {
            cache.entrySet().removeIf(entry -> 
                System.currentTimeMillis() - entry.getValue().timestamp > expirationTimeMillis);
        }

        CacheEntry entry = cache.get(filePath);

        if (entry != null && System.currentTimeMillis() - entry.timestamp <= expirationTimeMillis) {
            return entry.state;
        }

        ObjectInputStream ois = null;
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                logger.warning("File not found: " + filePath);
                return null;
            }

            ois = new ObjectInputStream(new FileInputStream(file));
            Object object = ois.readObject();
            if (object instanceof MoSTState) {
                entry = new CacheEntry((MoSTState) object, System.currentTimeMillis());
                cache.put(filePath, entry);
                return object;
            } else {
                logger.warning("Loaded object is not an instance of MoSTState: " + filePath);
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Error loading state from file: " + filePath + " - " + e.getMessage());
        } finally {
            try {
                if (ois != null) {
                    ois.close();
                }
            } catch (IOException e) {
                logger.warning("Failed to close ObjectInputStream for file: " + filePath);
            }
        }

        return null;
    }

    private static class CacheEntry {
        final MoSTState state;
        final long timestamp;

        CacheEntry(MoSTState state, long timestamp) {
            this.state = state;
            this.timestamp = timestamp;
        }
    }
}

class MoSTState implements Serializable {
    // Placeholder for the actual implementation of the MoSTState class
}
```

### Explanation:
- **Cache Implementation**: A `ConcurrentHashMap` is used to manage a thread-safe cache. Each entry holds a `MoSTState` object and a timestamp for expiration.
- **Expiration Policy**: Entries are evicted if they exceed the specified `expirationTimeMillis`.
- **Concurrency Handling**: The cache supports high-concurrency scenarios using `ConcurrentHashMap`.
- **Exception Management**: Ensures that resources such as `ObjectInputStream` are closed properly, even if an exception occurs.
- **Logging**: Provides detailed logging for troubleshooting and monitoring purposes.']

['```rust
use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use rand::{thread_rng, Rng};
use chrono::Utc;

#[derive(Debug)]
struct Record {
    value: i32,
}

fn initialize_records_and_directory(num_offsets: usize, num_keys: usize, record_count: usize, min_value: i32, max_value: i32) -> Result<(), Box<dyn std::error::Error>> {
    // Allocate memory for offset values and keys
    let mut offsets: Vec<i64> = vec![0; num_offsets];
    let mut keys: Vec<i32> = vec![0; num_keys];

    // Initialize records with random values within the specified range
    let mut rng = thread_rng();
    let records: Vec<Record> = (0..record_count)
        .map(|_| Record {
            value: rng.gen_range(min_value..=max_value),
        })
        .collect();

    // Manage directory creation and configuration
    let dir_path = Arc::new(Mutex::new(get_or_create_directory()?));

    Ok(())
}

fn get_or_create_directory() -> Result<String, Box<dyn std::error::Error>> {
    let existing_dir = env::var("DIR_PATH").ok();

    if let Some(dir) = existing_dir {
        // Check if the directory exists
        if PathBuf::from(&dir).exists() {
            return Ok(dir);
        }
    }

    // Create a new directory with a unique name based on current date and time
    let dir_name = format!("records_{}", Utc::now().to_rfc3339());
    let new_dir_path = env::current_dir()?.join(&dir_name);

    // Attempt to create the directory, handling race conditions
    match fs::create_dir_all(&new_dir_path) {
        Ok(_) => {
            // Set the DIR_PATH environment variable
            env::set_var("DIR_PATH", new_dir_path.to_str().ok_or_else(|| "Failed to set DIR_PATH")?.to_string());
            Ok(new_dir_path.to_str().ok_or_else(|| "Failed to get directory path")?.to_string())
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            // If the directory was created by another process, use it
            env::set_var("DIR_PATH", new_dir_path.to_str().ok_or_else(|| "Failed to set DIR_PATH")?.to_string());
            Ok(new_dir_path.to_str().ok_or_else(|| "Failed to get directory path")?.to_string())
        }
        Err(e) => Err(Box::new(e)),
    }
}
```

This Rust function demonstrates how to handle memory allocation for arrays and structures, random value assignment within a range, environment variable management, and safe directory creation with consideration for race conditions. The use of `Arc` and `Mutex` ensures thread safety when accessing the directory path across multiple threads in a larger application.']

