        stop_ = true;
        cv.notify_all();
        for (auto& thread : workers_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void add_packet(const NFAPI_CRC_INDICATION_PDU_T& packet) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (packets_.size() < max_entries_) {
            packets_.push_back(packet);
