        packets_.erase(
            std::remove_if(packets_.begin(), packets_.end(),
                           [rnti](const NFAPI_CRC_INDICATION_PDU_T& packet) { 
                               return packet.rnti == rnti; 
                           }),
            packets_.end());
    }

    void update_crc_flag(RNTI rnti, bool crc_validity) {
        std::lock_guard<std::mutex> lock(mutex_);
