public class ServiceManager {

    private static final int MAX_SERVICE_OPERATIONS = 5;
    private static int serviceOperationsCount = 0;
    private static final Random random = new Random();

    public static void main(String[] args) {
        String csvFilePath = "path/to/your/file.csv";

        try {
            List<Integer> numbers = readIntegersFromCSV(csvFilePath);
            if (!numbers.isEmpty()) {
                int largestNumber = findLargestInteger(numbers);
                System.out.println("The largest integer is: " + largestNumber);
            } else {
                System.out.println("No valid integers found in the file.");
            }
        } catch (IOException e) {
            System.err.println("Error reading CSV file: " + e.getMessage());
        }

        simulateService();
    }

    private static List<Integer> readIntegersFromCSV(String filePath) throws IOException {
        List<Integer> numbers = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                try {
                    int number = Integer.parseInt(line.trim());
                    numbers.add(number);
                } catch (NumberFormatException e) {
                    // Ignore malformed entries
                }
            }
        }
        return numbers;
    }

    /**
     * Finds the largest integer in a list of integers.
     *
     * @param numbers List of integers to search through. Can be empty or contain negative numbers.
     * @return The largest integer found, or Integer.MIN_VALUE if the list is empty.
     */
    private static int findLargestInteger(List<Integer> numbers) {
        if (numbers.isEmpty()) return Integer.MIN_VALUE;

        int largest = Integer.MIN_VALUE;
        for (int number : numbers) {
            if (number > largest) {
                largest = number;
            }
        }
        return largest;
    }

    private static void simulateService() {
        while (serviceOperationsCount < MAX_SERVICE_OPERATIONS) {
            startService();
            stopService();
        }
    }

    private static void startService() {
        try {
            System.out.println("Starting service...");
            // Simulate a delay for starting the service
            Thread.sleep(random.nextInt(1000) + 500); // Delay between 500ms to 1500ms
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static void stopService() {
        try {
            System.out.println("Stopping service...");
            sendStopMessageToBroker();

            // Simulate a delay for stopping the service
            Thread.sleep(random.nextInt(1000) + 500); // Delay between 500ms to 1500ms

            serviceOperationsCount++;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static void sendStopMessageToBroker() {
        try {
            // Simulate network latency
            Thread.sleep(random.nextInt(300) + 200); // Delay between 200ms to 500ms

            System.out.println("Sent stop message to broker.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
