// Define the structure for CRC indication PDU
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function pointer types for cryptographic operations
typedef EVP_CIPHER *(*create_cipher_fn)(const char *name, const unsigned char *key, const unsigned char *iv);
typedef EVP_MD_CTX *(*create_md_ctx_fn)();
typedef int (*init_crypto_fn)(EVP_CIPHER_CTX **ctx, create_cipher_fn cipher_fn, void *args1, void *args2);
typedef int (*perform_operation_fn)(void *ctx);

// Module structure
typedef struct {
    void *handle;
    create_cipher_fn create_cipher;
    create_md_ctx_fn create_md_ctx;
    init_crypto_fn init_crypto;
    perform_operation_fn perform_op;
} CryptoModule;

// Global module registry
#define MAX_MODULES 5
CryptoModule crypto_modules[MAX_MODULES];
int module_count = 0;
pthread_mutex_t modules_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to load a cryptographic module dynamically
void load_module(const char *lib_path) {
    pthread_mutex_lock(&modules_lock);

    void *handle = dlopen(lib_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        pthread_mutex_unlock(&modules_lock);
        return;
    }

    create_cipher_fn create_cipher = (create_cipher_fn)dlsym(handle, "create_cipher");
    create_md_ctx_fn create_md_ctx = (create_md_ctx_fn)dlsym(handle, "create_md_ctx");
    init_crypto_fn init_crypto = (init_crypto_fn)dlsym(handle, "init_crypto");
    perform_operation_fn perform_op = (perform_operation_fn)dlsym(handle, "perform_operation");

    if (!create_cipher || !create_md_ctx || !init_crypto || !perform_op) {
        fprintf(stderr, "Failed to load symbols: %s\n", dlerror());
        dlclose(handle);
        pthread_mutex_unlock(&modules_lock);
        return;
    }

    crypto_modules[module_count].handle = handle;
    crypto_modules[module_count].create_cipher = create_cipher;
    crypto_modules[module_count].create_md_ctx = create_md_ctx;
    crypto_modules[module_count].init_crypto = init_crypto;
    crypto_modules[module_count].perform_op = perform_op;

    module_count++;
    pthread_mutex_unlock(&modules_lock);
}

// Function to initialize a cryptographic operation
int initialize_crypto_operation(EVP_CIPHER_CTX **ctx, const char *cipher_name, const unsigned char *key, const unsigned char *iv) {
    for (int i = 0; i < module_count; ++i) {
        if (crypto_modules[i].create_cipher(cipher_name, key, iv)) {
            crypto_modules[i].init_crypto(ctx, crypto_modules[i].create_cipher, key, iv);
            return 1;
        }
    }
    return 0;
}

// Function to perform a cryptographic operation
int perform_crypto_operation(EVP_CIPHER_CTX *ctx) {
    for (int i = 0; i < module_count; ++i) {
        if (crypto_modules[i].perform_op(ctx)) {
            return 1;
        }
    }
    return 0;
}

// Function to handle a cryptographic request
void handle_request(NFAPI_CRC_INDICATION_PDU_T *pdu, const char *cipher_name, const unsigned char *key, const size_t key_len) {
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX *ctx = NULL;
    if (!initialize_crypto_operation(&ctx, cipher_name, key, iv)) {
        fprintf(stderr, "Failed to initialize cryptographic operation.\n");
        return;
    }

    if (!perform_crypto_operation(ctx)) {
        fprintf(stderr, "Cryptographic operation failed.\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
