extern "C" {
    #include <openssl/evp.h>
}

class CryptoManager {
public:
    enum Algorithm { DES_ECB, DES_EDE_CBC, DES_EDE3_CBC, DES_CFB };
    struct Config {
        Algorithm algo;
        bool encrypt_enabled;
        std::vector<unsigned char> key;
        std::vector<unsigned char> iv;
    };

private:
    std::map<Algorithm, const EVP_CIPHER*> cipherMap = {
        {DES_ECB, EVP_des_ecb()},
        {DES_EDE_CBC, EVP_des_ede3_cbc()},
        {DES_CFB, EVP_des_cfb64()}
    };

    Config currentConfig;
    bool initialized = false;

    void initialize() {
        if (!initialized) {
            // Lazy initialization of resources
            OpenSSL_add_all_algorithms();
            ERR_load_crypto_strings();
            initialized = true;
        }
    }

public:
    CryptoManager(const Config& config)
        : currentConfig(config) {}

    ~CryptoManager() {
        EVP_cleanup();
        ERR_free_strings();
    }

    void serializeToFile(const std::string& filename) {
        initialize();

        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Unable to open file for serialization.");
        }

        // Write metadata
        int algo = currentConfig.algo;
        bool encrypt_enabled = currentConfig.encrypt_enabled;

        file.write(reinterpret_cast<char*>(&algo), sizeof(algo));
        file.write(reinterpret_cast<char*>(&encrypt_enabled), sizeof(encrypt_enabled));

        // Write key and iv size
        size_t key_size = currentConfig.key.size();
        size_t iv_size = currentConfig.iv.size();

        file.write(reinterpret_cast<char*>(&key_size), sizeof(key_size));
        file.write(reinterpret_cast<char*>(&iv_size), sizeof(iv_size));

        // Write actual data
        file.write(reinterpret_cast<const char*>(currentConfig.key.data()), key_size);
        file.write(reinterpret_cast<const char*>(currentConfig.iv.data()), iv_size);

        file.close();
    }

    void deserializeFromFile(const std::string& filename) {
        initialize();

        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Unable to open file for deserialization.");
        }

        // Read metadata
        int algo;
        bool encrypt_enabled;

        file.read(reinterpret_cast<char*>(&algo), sizeof(algo));
        file.read(reinterpret_cast<char*>(&encrypt_enabled), sizeof(encrypt_enabled));

        size_t key_size, iv_size;
        file.read(reinterpret_cast<char*>(&key_size), sizeof(key_size));
        file.read(reinterpret_cast<char*>(&iv_size), sizeof(iv_size));

        std::vector<unsigned char> key(key_size);
        std::vector<unsigned char> iv(iv_size);

        // Read actual data
        file.read(reinterpret_cast<char*>(key.data()), key_size);
        file.read(reinterpret_cast<char*>(iv.data()), iv_size);

        if (!file) {
            throw std::runtime_error("File read error or corrupted.");
        }

        currentConfig = {static_cast<Algorithm>(algo), encrypt_enabled, key, iv};
    }

    bool isEncryptionEnabled() const {
        return currentConfig.encrypt_enabled;
    }

    // Example encryption method
    std::vector<unsigned char> encrypt(const std::vector<unsigned char>& plaintext) {
        if (!isEncryptionEnabled()) {
            throw std::runtime_error("Encryption not enabled.");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        std::unique_ptr<EVP_CIPHER_CTX, decltype(&EVP_CIPHER_CTX_free)> context_guard(ctx, &EVP_CIPHER_CTX_free);

        if (!context_guard) {
            throw std::runtime_error("Failed to create encryption context.");
        }

        int len;
        int ciphertext_len;

        if (1 != EVP_EncryptInit_ex(context_guard.get(), cipherMap[currentConfig.algo], NULL, currentConfig.key.data(), currentConfig.iv.data())) {
            throw std::runtime_error("Encryption initialization failed.");
        }

        std::vector<unsigned char> ciphertext(plaintext.size() + EVP_MAX_BLOCK_LENGTH);
        if (1 != EVP_EncryptUpdate(context_guard.get(), ciphertext.data(), &len, plaintext.data(), plaintext.size())) {
            throw std::runtime_error("Encryption update failed.");
        }
        ciphertext_len = len;

        if (1 != EVP_EncryptFinal_ex(context_guard.get(), ciphertext.data() + len, &len)) {
            throw std::runtime_error("Encryption finalization failed.");
        }
        ciphertext_len += len;

        ciphertext.resize(ciphertext_len);
        return ciphertext;
    }

    // Example decryption method
    std::vector<unsigned char> decrypt(const std::vector<unsigned char>& ciphertext) {
        if (!isEncryptionEnabled()) {
            throw std::runtime_error("Decryption not enabled.");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        std::unique_ptr<EVP_CIPHER_CTX, decltype(&EVP_CIPHER_CTX_free)> context_guard(ctx, &EVP_CIPHER_CTX_free);

        if (!context_guard) {
            throw std::runtime_error("Failed to create decryption context.");
        }

        int len;
        int plaintext_len;

        if (1 != EVP_DecryptInit_ex(context_guard.get(), cipherMap[currentConfig.algo], NULL, currentConfig.key.data(), currentConfig.iv.data())) {
            throw std::runtime_error("Decryption initialization failed.");
        }

        std::vector<unsigned char> plaintext(ciphertext.size());
        if (1 != EVP_DecryptUpdate(context_guard.get(), plaintext.data(), &len, ciphertext.data(), ciphertext.size())) {
            throw std::runtime_error("Decryption update failed.");
        }
        plaintext_len = len;

        if (1 != EVP_DecryptFinal_ex(context_guard.get(), plaintext.data() + len, &len)) {
            throw std::runtime_error("Decryption finalization failed.");
        }
        plaintext_len += len;

        plaintext.resize(plaintext_len);
        return plaintext;
    }

    // Fallback mechanism during deserialization
    void recoverFromCorruption(const std::string& filename) {
        try {
            deserializeFromFile(filename);
        } catch (const std::exception& e) {
            std::cerr << "Deserialization error: " << e.what() << "\n";
            // Handle fallback, e.g., load defaults or notify
            currentConfig = Config{DES_ECB, false, {}, {}};
        }
    }
};

int main() {
    CryptoManager::Config config = {CryptoManager::DES_CBC, true, {0x01, 0x23, 0x45, 0x67, 0x89, 0xAB, 0xCD, 0xEF}, {0xFE, 0xDC, 0xBA, 0x98, 0x76, 0x54, 0x32, 0x10}};
    CryptoManager manager(config);

    // Serialization example
    manager.serializeToFile("crypto_config.bin");

    // Deserialization example with fallback mechanism
    try {
        manager.deserializeFromFile("crypto_config.bin");
    } catch (const std::exception& e) {
        std::cerr << "Error during deserialization, recovering: " << e.what() << "\n";
        manager.recoverFromCorruption("crypto_config.bin");
    }

    // Example usage
    if (manager.isEncryptionEnabled()) {
        auto plaintext = std::vector<unsigned char>{'H', 'e', 'l', 'l', 'o'};
        auto ciphertext = manager.encrypt(plaintext);
        auto decryptedtext = manager.decrypt(ciphertext);

        for (auto c : decryptedtext) {
            std::cout << c;
        }
    }

    return 0;
}
