NetworkStats *stats_list = NULL;
size_t num_interfaces = 0;
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize the network statistics structures
void init_network_stats(size_t count) {
    pthread_mutex_lock(&stats_lock);

    if (stats_list != NULL) {
        free(stats_list);
    }
    num_interfaces = count;
    stats_list = malloc(sizeof(NetworkStats) * num_interfaces);

    if (stats_list == NULL) {
        perror("Failed to allocate memory for network statistics");
        exit(EXIT_FAILURE);
    }

