    for (size_t i = 0; i < num_interfaces; ++i) {
        snprintf(stats_list[i].name, sizeof(stats_list[i].name), "Interface%d", i + 1);
        stats_list[i].bytes_received = rand() % 100000;
        stats_list[i].packets_dropped = rand() % 5000;
        stats_list[i].is_active = true; // All interfaces are active initially
    }

    pthread_mutex_unlock(&stats_lock);
}

// Function to update statistics periodically (mock implementation)
void *update_stats(void *arg) {
    while (true) {
        sleep(5); // Update every 5 seconds

        pthread_mutex_lock(&stats_lock);

        for (size_t i = 0; i < num_interfaces; ++i) {
            stats_list[i].bytes_received += rand() % 10000;
            stats_list[i].packets_dropped += rand() % 100;
        }

        pthread_mutex_unlock(&stats_lock);
    }
    return NULL;
}

// Function to filter out interfaces with low throughput
void filter_low_throughput(double threshold) {
    pthread_mutex_lock(&stats_lock);

    for (size_t i = 0; i < num_interfaces; ++i) {
        if (stats_list[i].bytes_received < threshold) {
            stats_list[i].is_active = false;
        }
    }

    pthread_mutex_unlock(&stats_lock);
}

// Function to serialize network statistics
void serialize_stats(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&stats_lock);

    size_t size = sizeof(NetworkStats) * num_interfaces;
    fwrite(stats_list, 1, size, file);

    fclose(file);
    pthread_mutex_unlock(&stats_lock);
}

// Function to deserialize network statistics
void deserialize_stats(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    pthread_mutex_lock(&stats_lock);

    size_t size = sizeof(NetworkStats) * num_interfaces;
    fread(stats_list, 1, size, file);

    fclose(file);
    pthread_mutex_unlock(&stats_lock);
}

// Function to simulate sending data to an external monitoring system
void send_to_monitoring_system() {
    pthread_mutex_lock(&stats_lock);

    for (size_t i = 0; i < num_interfaces; ++i) {
        if (stats_list[i].is_active) {
            // Simulate sending data
            printf("Sending stats of %s to monitoring system\n", stats_list[i].name);
        }
    }

    pthread_mutex_unlock(&stats_lock);
}

int main() {
    init_network_stats(5);

    // Start a thread to update statistics periodically
    pthread_t updater_thread;
    if (pthread_create(&updater_thread, NULL, update_stats, NULL) != 0) {
        perror("Failed to create stats update thread");
        return EXIT_FAILURE;
    }

    filter_low_throughput(20000.0); // Threshold for low throughput

    send_to_monitoring_system();

    serialize_stats("network_stats.dat");
    deserialize_stats("network_stats.dat");

    pthread_cancel(updater_thread);
    pthread_join(updater_thread, NULL);

    free(stats_list);
    return EXIT_SUCCESS;
}
