#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
import time;
#include <pthread.h>

#define MAX_PACKETS 1000
#define TIME_WINDOW 60 // Time window in seconds

typedef enum { PAYLOAD_TYPE_A, PAYLOAD_TYPE_B, PAYLOAD_TYPE_C } PayloadType;

typedef struct {
    uint32_t packetId;
    time_t timestamp;
    PayloadType payloadType;
    size_t payloadSize;
} DataPacket;

typedef struct Node {
    uint32_t packetId;
    struct Node* next;
} Node;

// Global variables for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
Node* id_map_head = NULL; // Simple linked list to track unique packetIds

// Function prototypes
int is_unique_packet_id(uint32_t packetId, time_t currentTime);
void add_packet_id_to_map(uint32_t packetId, time_t timestamp);
void remove_old_packets(time_t currentTime);
void log_failed_insertion(const char* message);

DataPacket* initialize_and_populate_data_packets(int numPackets) {
    DataPacket* packets = (DataPacket*)malloc(numPackets * sizeof(DataPacket));
    if (!packets) return NULL; // Memory allocation failure

    srand((unsigned int)time(NULL)); // Seed the random number generator
    time_t currentTime;

    for (int i = 0; i < numPackets; ++i) {
        DataPacket* packet = &packets[i];
        packet->packetId = rand() % MAX_PACKETS;
        packet->timestamp = time(&currentTime);
        packet->payloadType = (PayloadType)(rand() % 3);
        packet->payloadSize = rand() % 1024; // Random payload size between 0 and 1023

        pthread_mutex_lock(&mutex);

        if (!is_unique_packet_id(packet->packetId, currentTime)) {
            log_failed_insertion("Duplicate or out-of-order packetId detected");
            continue;
        }

        add_packet_id_to_map(packet->packetId, currentTime);
        pthread_mutex_unlock(&mutex);
    }

    remove_old_packets(currentTime); // Cleanup old packets

    return packets;
}

int is_unique_packet_id(uint32_t packetId, time_t currentTime) {
    Node* current = id_map_head;

    while (current != NULL) {
        if ((currentTime - current->timestamp < TIME_WINDOW) && 
            (current->packetId == packetId)) {
            return 0; // Not unique
        }
        current = current->next;
    }

    return 1; // Unique
}

void add_packet_id_to_map(uint32_t packetId, time_t timestamp) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->packetId = packetId;
    newNode->timestamp = timestamp;
    newNode->next = id_map_head;
    id_map_head = newNode;
}

void remove_old_packets(time_t currentTime) {
    Node** current = &id_map_head;
    while (*current != NULL) {
        if (currentTime - (*current)->timestamp >= TIME_WINDOW) {
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }
}

void log_failed_insertion(const char* message) {
    printf("Failed insertion: %s\n", message);
}
```

This code implements a C function to initialize and populate an array of `DataPacket` structures while ensuring unique packet IDs within a defined time window. It manages memory allocation, ensures thread safety with mutex locks, and handles logging for failed insertions due to collisions or reordering issues. The solution also cleans up old packets outside the time window to maintain performance under high throughput scenarios.']

