// C Function: Manage TCP Connection Requests Queue

#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_BATCH_SIZE 500

typedef struct {
    char ip[16];      // IPv4 addresses are stored as strings (e.g., "192.168.0.1")
    int port;
    int timeout;      // in milliseconds
} TCPRequest;

typedef struct Node {
    TCPRequest request;
    struct Node* next;
} Node;

typedef struct Queue {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    size_t length;
} Queue;

void initQueue(Queue* q) {
    q->head = q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    q->length = 0;
}

void destroyNode(Node* node) {
    free(node);
}

void enqueue(Queue* q, TCPRequest req) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Handle allocation failure
    newNode->request = req;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);
    if (q->tail) {
        q->tail->next = newNode;
    } else {
        q->head = newNode;
    }
    q->tail = newNode;
    q->length++;
    pthread_mutex_unlock(&q->lock);
}

int dequeueBatch(Queue* q, TCPRequest* batch, size_t batchSize) {
    pthread_mutex_lock(&q->lock);

    int count = 0;
    while (q->head && count < batchSize) {
        Node* temp = q->head;
        q->head = q->head->next;

        if (!q->head) {
            q->tail = NULL;
        }

        batch[count++] = temp->request;
        destroyNode(temp);
        q->length--;
    }

    pthread_mutex_unlock(&q->lock);

    return count;
}

void processQueue(Queue* q) {
    TCPRequest batch[MAX_BATCH_SIZE];

    while (1) { // This loop should be managed based on application lifecycle
        int processed = dequeueBatch(q, batch, MAX_BATCH_SIZE);

        if (processed > 0) {
            for (int i = 0; i < processed; ++i) {
                // Process each TCPRequest here
                // For example: integrate with network stack or send to handler
            }
        }

        // Implement logic to sleep or yield in case of no requests
    }
}
