        records[i].value = random_value + i;  // Example logic
        records[i].offset_ptr = &offsets[keys[i] % offset_size];  // Ensure valid index
    }

    free(offsets);
    free(keys);

    *error_code = 0;
    return records;
}

// Mutex for thread-safe access (for future threading support)
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void manage_dynamic_memory(const char *config_file) {
    size_t offset_size, key_size;
    int error_code;

    if (read_config(config_file, &offset_size, &key_size) != 0) {
        fprintf(stderr, "Failed to read configuration\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    Record *records = initialize_records(offset_size, key_size, &error_code);
    pthread_mutex_unlock(&mutex);

    if (error_code != 0 || !records) {
        fprintf(stderr, "Record initialization failed with error code: %d\n", error_code);
        return;
    }

    // Example usage of records
    for (size_t i = 0; i < key_size && records[i].value >= 0; ++i) {
        printf("Record %zu: value=%d, offset=%ld\n", i, records[i].value, records[i].offset_ptr->offset);
    }

    free(records);  // Clean up allocated memory
}

int main() {
    manage_dynamic_memory("config.json");
    return 0;
}
