    int activeThreads = 0;

    for (size_t i = 0; i < queryCount; ++i) {
        if (activeThreads >= M) {
            // Wait for any thread to finish
            pthread_join(threads[0], NULL);
            memmove(&threads[0], &threads[1], sizeof(pthread_t) * (--M));
            activeThreads--;
