            handleDatabaseError(errorCallback, "Failed to create thread for query execution");
            free(queryStr);
            continue;
        }

        activeThreads++;
        memmove(&threads[M + 1], &threads[M], sizeof(pthread_t) * (M - M));
    }

    // Wait for remaining threads to finish
    for (int i = 0; i < activeThreads; ++i) {
        pthread_join(threads[i], NULL);
    }
