#define MAX_STRUCTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Helper function to generate a random number within a range
uint16_t generate_random_rnti() {
    return rand() % 0xFFFF; // Assuming RNTI is a 16-bit value
}

// Function to dynamically allocate and initialize the array
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(size_t num_structs) {
    if (num_structs > MAX_STRUCTS) {
        fprintf(stderr, "Requested number of structs exceeds maximum limit.\n");
        return NULL;
    }

    // Allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize a hash map to track unique RNTI values
    uint16_t rnti_map[MAX_STRUCTS] = {0};
    int unique_count = 0;

    for (size_t i = 0; i < num_structs; ++i) {
        do {
            array[i].RX_UE_INFORMATION_TAG = rand(); // Random initialization
            array[i].RNTI = generate_random_rnti();
        } while (rnti_map[array[i].RNTI] != 0);

        rnti_map[array[i].RNTI] = 1; // Mark RNTI as used
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag

        unique_count++;
    }

    printf("Successfully allocated and initialized %d structures.\n", unique_count);
    return array;
}

// Function to free the allocated memory
void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}

int main() {
    srand((unsigned int)time(NULL)); // Seed random number generator

    size_t num_structs = 10000; // Example load
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = create_crc_indication_pdu_array(num_structs);

    if (pdu_array) {
        // Use the array as needed...

        // Free the allocated memory when done
        free_crc_indication_pdu_array(pdu_array);
    }

    return 0;
}
```

### Key Points:

- **Memory Allocation**: The function allocates memory for up to `MAX_STRUCTS` (10,000) structures. It checks if the requested number exceeds this limit.

- **Unique RNTI Values**: A simple hash map (`rnti_map`) is used to ensure each `RNTI` is unique within the array.

- **Random Initialization**: Each structure's fields are initialized with random values. The `CRCFLAG` is set randomly to either 0 or 1.

- **Error Handling**: If memory allocation fails, an error message is printed, and the function returns `NULL`.

- **Memory Management**: A helper function (`free_crc_indication_pdu_array`) is provided to free allocated memory when no longer needed.

This implementation balances between performance and resource usage while ensuring unique RNTI values.']

