#define MIN_RNTI 1
#define MAX_RNTI 65535

void log_invalid_rnti(uint32_t rnti) {
    fprintf(stderr, "Invalid RNTI: %u\n", rnti);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t count) {
    if (count <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    uint32_t last_rnti = 0;
    for (size_t i = 0; i < count; ++i) {
        uint32_t rnti;

        do {
            rnti = rand() % MAX_RNTI + MIN_RNTI;
        } while (rnti == last_rnti || rnti < MIN_RNTI || rnti > MAX_RNTI);

        if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
            log_invalid_rnti(rnti);
            free(list);
            return NULL;
        }

        list[i].ue_info_tag.rnti = rnti;
        list[i].ue_info_tag.crc_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
        last_rnti = rnti;
    }

    return list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
    }
}
