```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_KEYS 1000
#define VALUE_RANGE 100

typedef struct {
    int key;
    long offset;
} Offset;

typedef struct {
    int value;
    Offset *offset_ptr;
} Record;

typedef struct {
    int *keys;
    long *offsets;
    size_t size;
    pthread_mutex_t mutex;
} DataArrays;

typedef struct HashNode {
    int key;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t capacity;
    pthread_mutex_t mutex;
} HashTable;

int hash_function(int key, size_t capacity) {
    return key % capacity;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->buckets = calloc(capacity, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = capacity;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

int hash_table_insert(HashTable *table, int key) {
    size_t index = hash_function(key, table->capacity);
    HashNode *node = malloc(sizeof(HashNode));
    if (!node) return -1;

    node->key = key;
    pthread_mutex_lock(&table->mutex);
    node->next = table->buckets[index];
    table->buckets[index] = node;
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

int hash_table_contains(HashTable *table, int key) {
    size_t index = hash_function(key, table->capacity);
    HashNode *node = NULL;

    pthread_mutex_lock(&table->mutex);
    for (node = table->buckets[index]; node != NULL; node = node->next) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

void free_hash_table(HashTable *table) {
    HashNode *node, *tmp;
    for (size_t i = 0; i < table->capacity; ++i) {
        node = table->buckets[i];
        while (node) {
            tmp = node;
            node = node->next;
            free(tmp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

DataArrays* initialize_data_arrays(const char *filename, size_t *record_count) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    int keys[MAX_KEYS];
    long offsets[MAX_KEYS];
    size_t count = 0;
    while (fscanf(file, "%d %ld", &keys[count], &offsets[count]) == 2 && count < MAX_KEYS) {
        ++count;
    }
    fclose(file);

    *record_count = count;

    DataArrays *data_arrays = malloc(sizeof(DataArrays));
    if (!data_arrays) return NULL;

    data_arrays->keys = malloc(count * sizeof(int));
    data_arrays->offsets = malloc(count * sizeof(long));
    if (!data_arrays->keys || !data_arrays->offsets) {
        free(data_arrays);
        return NULL;
    }

    memcpy(data_arrays->keys, keys, count * sizeof(int));
    memcpy(data_arrays->offsets, offsets, count * sizeof(long));
    data_arrays->size = count;

    pthread_mutex_init(&data_arrays->mutex, NULL);

    return data_arrays;
}

Record* initialize_records(DataArrays *data_arrays, HashTable *hash_table) {
    if (!data_arrays || !hash_table) return NULL;

    Record *records = malloc(data_arrays->size * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < data_arrays->size; ++i) {
        int key = data_arrays->keys[i];
        if (hash_table_contains(hash_table, key)) continue;

        if (hash_table_insert(hash_table, key) != 0) {
            free(records);
            return NULL;
        }

        Offset *offset = malloc(sizeof(Offset));
        if (!offset) {
            free(records);
            return NULL;
        }
        offset->key = key;
        offset->offset = data_arrays->offsets[i];

        records[i].value = rand() % VALUE_RANGE + 1;
        records[i].offset_ptr = offset;
    }

    return records;
}

void cleanup(DataArrays *data_arrays, Record *records, HashTable *hash_table) {
    if (data_arrays) {
        pthread_mutex_destroy(&data_arrays->mutex);
        free(data_arrays->keys);
        free(data_arrays->offsets);
        free(data_arrays);
    }
    for (size_t i = 0; records && i < data_arrays->size; ++i) {
        free(records[i].offset_ptr);
    }
    if (records) free(records);
    free_hash_table(hash_table);
}

void process_file_and_initialize(const char *filename) {
    size_t record_count;
    DataArrays *data_arrays = initialize_data_arrays(filename, &record_count);
    if (!data_arrays) {
        fprintf(stderr, "Failed to initialize data arrays.\n");
        return;
    }

    HashTable *hash_table = create_hash_table(100); // Example capacity
    if (!hash_table) {
        fprintf(stderr, "Failed to create hash table.\n");
        cleanup(data_arrays, NULL, NULL);
        return;
    }

    Record *records = initialize_records(data_arrays, hash_table);
    if (!records) {
        fprintf(stderr, "Failed to initialize records.\n");
        cleanup(data_arrays, NULL, hash_table);
        return;
    }

    // Further processing...

    cleanup(data_arrays, records, hash_table);
}

int main() {
    srand(time(NULL));
    process_file_and_initialize("data.txt");
    return 0;
}
```

### Key Points:

