#include <string.h>
#include <pthread.h>
#include "uthash.h"  // A simple hash map implementation from Doug Lea's lib

// Structure definition (assuming the structures are defined as follows)
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; 
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash map structure for unique RNTI values
typedef struct {
    uint16_t rnti;
    UT_hash_handle hh;  // Makes this structure hashable
} RNTI_MAP;

#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 10000

// Thread-safe dynamic array management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    RNTI_MAP *rnti_map;
    pthread_mutex_t mutex;
} CRC_ARRAY_MANAGER;

void initialize_crc_array_manager(CRC_ARRAY_MANAGER *manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        exit(EXIT_FAILURE);
    }
    memset(manager->array, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    HASHMAP_INIT(manager->rnti_map);  // Initialize hash map
    pthread_mutex_init(&manager->mutex, NULL);
}

void free_crc_array_manager(CRC_ARRAY_MANAGER *manager) {
    if (manager->array) {
        for (size_t i = 0; i < manager->count; ++i) {
            RNTI_MAP *rnti_entry;
            HASHMAP_FIND(manager->rnti_map, &manager->array[i].RNTI, rnti_entry);
            if (rnti_entry)
                HASHMAP_DELETE(rnti_map, rnti_entry);  // Free hash map entry
        }
        free(manager->array);
    }
    HASHMAP_CLEAR(manager->rnti_map);  // Clear the hash map
    pthread_mutex_destroy(&manager->mutex);
}

void resize_crc_array_manager(CRC_ARRAY_MANAGER *manager) {
    size_t new_capacity = manager->capacity < MAX_CAPACITY ? manager->capacity * 2 : MAX_CAPACITY;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array && manager->capacity != MAX_CAPACITY) {
        fprintf(stderr, "Failed to reallocate memory during resizing\n");
        return;
    }

    pthread_mutex_lock(&manager->mutex);
    manager->array = new_array;
    manager->capacity = new_capacity;
    pthread_mutex_unlock(&manager->mutex);

    if (new_array)
        memset((void *)((char *)new_array + manager->count * sizeof(NFAPI_CRC_INDICATION_PDU_T)), 0,
               (new_capacity - manager->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

int add_crc_pdu(CRC_ARRAY_MANAGER *manager, uint32_t rx_tag, uint16_t rnti) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity)
        resize_crc_array_manager(manager);

    RNTI_MAP *rnti_entry;
    HASHMAP_FIND(manager->rnti_map, &rnti, rnti_entry);  // Check for existing RNTI

    if (rnti_entry) {  // Duplicate RNTI found
        pthread_mutex_unlock(&manager->mutex);
        return -1;  // Indicate failure
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;  // Random CRCFLAG

    RNTI_MAP *new_rnti_entry = malloc(sizeof(RNTI_MAP));
    if (!new_rnti_entry) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;  // Indicate failure
    }

    new_rnti_entry->rnti = rnti;
    HASHMAP_ADD(manager->rnti_map, new_rnti_entry);  // Add to hash map

    pthread_mutex_unlock(&manager->mutex);

    return 0;  // Success
}

// Example of unsafe code (for illustration purposes)
void unsafe_add_crc_pdu(CRC_ARRAY_MANAGER *manager, uint32_t rx_tag, uint16_t rnti) {
    if (manager->count >= manager->capacity) {
        printf("Capacity exceeded! Not resizing.\n");
        return;  // This is unsafe and can lead to buffer overflow
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;  // No check for unique RNTI

    // Note: This does not lock the mutex, risking race conditions
}

// Demonstrative example usage
int main() {
    CRC_ARRAY_MANAGER manager;
    initialize_crc_array_manager(&manager);

    for (uint16_t i = 0; i < 10500; ++i) {  // Attempt to add more than capacity
        if (add_crc_pdu(&manager, rand(), i % MAX_CAPACITY) != 0)
            printf("Duplicate RNTI or memory failure at iteration %u\n", i);
    }

    free_crc_array_manager(&manager);

    return 0;
}
```

### Key Considerations:
