void *mallocPayload(size_t size) {
    void *payload = malloc(size);
    if (!payload) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return payload;
}

int addDataPacket(uint32_t packetId, time_t timestamp, PayloadType type, size_t payloadSize) {
    pthread_mutex_lock(&lock);

    // Ensure no duplicate packetId within the time window
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (packets[i].packetId == packetId || packets[i].timestamp >= timestamp - 60) {  // 1-minute window example
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (!packets[i].packetId) {
            packets[i].packetId = packetIdCounter++;
            packets[i].timestamp = timestamp;
            packets[i].type = type;
            packets[i].payloadSize = payloadSize;

            // Allocate and assign the payload
            packets[i].payload = mallocPayload(payloadSize);
            memset(packets[i].payload, 0, payloadSize);  // Initialize payload

            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&lock);
    return -1;  // Array full
}

void cleanupPackets() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (packets[i].payload) {
            free(packets[i].payload);
            packets[i].packetId = 0;
        }
    }
    pthread_mutex_unlock(&lock);
}

typedef struct {
    int tileSizes[3];
    float worldDimensions[2];
    float cameraSpeed;
} Config;

int loadConfig(const char *filePath, Config *config) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open config file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = (char *)malloc(length + 1);
    fread(data, 1, length, file);
    fclose(file);

    data[length] = '\0';
    cJSON *json = cJSON_Parse(data);
    free(data);

    if (!json) {
        fprintf(stderr, "Failed to parse JSON\n");
        return -1;
    }

    cJSON *tileSizes = cJSON_GetObjectItemCaseSensitive(json, "tileSizes");
    cJSON *worldDimensions = cJSON_GetObjectItemCaseSensitive(json, "worldDimensions");
    cJSON *cameraSpeed = cJSON_GetObjectItemCaseSensitive(json, "cameraSpeed");

    if (cJSON_IsArray(tileSizes) && tileSizes->valuecount == 3) {
        for (int i = 0; i < 3; ++i)
            config->tileSizes[i] = cJSON_GetArrayItem(tileSizes, i)->valueint;
    } else {
        fprintf(stderr, "Invalid or missing tileSizes\n");
        return -1;
    }

    if (cJSON_IsArray(worldDimensions) && worldDimensions->valuecount == 2) {
        for (int i = 0; i < 2; ++i)
            config->worldDimensions[i] = cJSON_GetArrayItem(worldDimensions, i)->valuedouble;
    } else {
        fprintf(stderr, "Invalid or missing worldDimensions\n");
        return -1;
    }

    if (cJSON_IsNumber(cameraSpeed))
        config->cameraSpeed = cameraSpeed->valuedouble;
    else {
        fprintf(stderr, "Invalid or missing cameraSpeed\n");
        return -1;
    }

    cJSON_Delete(json);
    return 0;
}
```

### Explanation:
