// Initialize the dynamic list
int initializeProcessList(ProcessList *list, size_t initial_capacity) {
    list->processes = (ProcessMetrics *)malloc(initial_capacity * sizeof(ProcessMetrics));
    if (!list->processes) return -1; // Memory allocation failed

    list->capacity = initial_capacity;
    list->count = 0;
    return 0;
