// Update the metrics for all processes
int updateProcessList(ProcessList *list, float (*get_cpu_usage)(int), float (*get_memory_usage)(int)) {
    if (!list || !list->processes) return -1;

    // Example: Gather data with network latency simulation and consistency checks
    for (size_t i = 0; i < list->count; i++) {
        ProcessMetrics *metric = &list->processes[i];

        time_sleep(0.01); // Simulate network delay

        metric->cpu_usage = get_cpu_usage(metric->pid);
        if (isnan(metric->cpu_usage)) return -1; // Consistency check failed

        metric->memory_usage = get_memory_usage(metric->pid);
        if (isnan(metric->memory_usage)) return -1; // Consistency check failed
    }
    return 0;
}

// Filter processes based on resource thresholds
void filterProcesses(ProcessList *list, float cpu_threshold, float memory_threshold) {
    if (!list || !list->processes) return;

    size_t i = 0;
    while (i < list->count) {
        ProcessMetrics *metric = &list->processes[i];

        if (metric->cpu_usage > cpu_threshold || metric->memory_usage > memory_threshold) {
            // Remove the process by shifting elements
            memmove(&list->processes[i], &list->processes[i + 1],
                    (--list->count - i) * sizeof(ProcessMetrics));
        } else {
            i++;
        }
    }
}

// Resize the dynamic list if needed
int resizeProcessList(ProcessList *list, size_t new_capacity) {
    ProcessMetrics *new_processes = (ProcessMetrics *)realloc(list->processes,
                                                              new_capacity * sizeof(ProcessMetrics));
    if (!new_processes) return -1;

    list->processes = new_processes;
    list->capacity = new_capacity;
    return 0;
}

// Add a process to the dynamic list
int addProcess(ProcessList *list, int pid) {
    if (!list || !list->processes) return -1;

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2; // Double capacity
        if (resizeProcessList(list, new_capacity)) return -1;
    }

    ProcessMetrics *metric = &list->processes[list->count++];
    metric->pid = pid;
    metric->cpu_usage = 0.0f;
    metric->memory_usage = 0.0f;

    return 0;
}

// Free the allocated memory for the process list
void freeProcessList(ProcessList *list) {
    if (list && list->processes) {
        free(list->processes);
        list->processes = NULL;
        list->capacity = 0;
        list->count = 0;
    }
}

