MemoryManager* initialize_memory_manager(int n, int min, int max) {
    if (n <= 0 || min > max) return NULL;

    MemoryManager *manager = custom_alloc(sizeof(MemoryManager));
    manager->num_offsets = n;
    manager->num_keys = n / 2;
    manager->num_records = manager->num_offsets + manager->num_keys;

