void quicksort_records(record** records, int left, int right) {
    if (left >= right) return;

    record* pivot = records[(left + right) / 2];
    int i = left;
    int j = right;

    while (i <= j) {
        while (records[i]->value < pivot->value) i++;
        while (records[j]->value > pivot->value) j--;
        if (i <= j) {
            record* temp = records[i];
            records[i] = records[j];
            records[j] = temp;
            i++;
            j--;
        }
    }

    if (left < j)
        quicksort_records(records, left, j);
    if (i < right)
        quicksort_records(records, i, right);
}

void sort_manager_records(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);
    quicksort_records(manager->records, 0, manager->num_records - 1);
