typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t active_elements;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void init_dynamic_array(DynamicArray *da) {
    da->capacity = 4; // Initial small capacity for efficiency
    da->active_elements = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&da->lock, NULL);
}

// Resize the dynamic array
void resize_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        da->array = new_array;
        da->capacity = new_capacity;
    }
    pthread_mutex_unlock(&da->lock);
}

// Add an element to the dynamic array
int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T elem) {
    pthread_mutex_lock(&da->lock);

    if (da->active_elements == da->capacity) {
        resize_dynamic_array(da);
    }

    da->array[da->active_elements] = elem;
    da->active_elements++;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Remove an element at a specific index
int remove_element(DynamicArray *da, size_t index) {
    if (index >= da->active_elements) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&da->lock);
    memmove(&da->array[index], &da->array[index + 1], 
            (da->active_elements - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->active_elements--;
    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Update an element at a specific index
int update_element(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T elem) {
    if (index >= da->active_elements) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&da->lock);
    da->array[index] = elem;
    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Free the dynamic array resources
void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    da->active_elements = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

