```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>

#define MAX_IV_LENGTH 8

typedef enum {
    MODE_ECB,
    MODE_EDE,
    MODE_EDE3,
    MODE_CFB
} CipherMode;

typedef struct {
    DES_key_schedule ks1, ks2, ks3;
    int num_rounds;
} DESContext;

void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

int validate_and_truncate_key(unsigned char *key, size_t key_len, size_t *truncated_key_len) {
    if (key_len < 8 || key_len > 24) {
        handle_error("Invalid DES key length");
    }
    *truncated_key_len = (key_len <= 8) ? 8 : ((key_len <= 16) ? 16 : 24);
    return (*truncated_key_len == 8) ? 1 : ((*truncated_key_len == 16) ? 2 : 3);
}

void set_des_context(DESContext *ctx, unsigned char *key, size_t key_len) {
    int num_rounds = validate_and_truncate_key(key, key_len, &key_len);
    ctx->num_rounds = num_rounds;
    if (num_rounds == 1) {
        DES_set_key_unchecked((const_DES_cblock *)key, &ctx->ks1);
    } else if (num_rounds == 2) {
        DES_set_odd_parity((DES_cblock *)key);
        DES_set_key_unchecked((const_DES_cblock *)key, &ctx->ks1);
        DES_set_key_unchecked((const_DES_cblock *)(key + 8), &ctx->ks2);
    } else if (num_rounds == 3) {
        DES_set_odd_parity((DES_cblock *)key);
        DES_set_key_unchecked((const_DES_cblock *)key, &ctx->ks1);
        DES_set_key_unchecked((const_DES_cblock *)(key + 8), &ctx->ks2);
        DES_set_key_unchecked((const_DES_cblock *)(key + 16), &ctx->ks3);
    }
}

void encrypt_des_ecb(DESContext *ctx, unsigned char *input, size_t input_len, unsigned char *output) {
    for (size_t i = 0; i < input_len; i += 8) {
        DES_ecb_encrypt((const_DES_cblock *)(input + i), (DES_cblock *)(output + i), &ctx->ks1, DES_ENCRYPT);
    }
}

void encrypt_des_ede(DESContext *ctx, unsigned char *input, size_t input_len, unsigned char *output) {
    for (size_t i = 0; i < input_len; i += 8) {
        DES_ecb3_encrypt((const_DES_cblock *)(input + i), (DES_cblock *)(output + i), &ctx->ks1, &ctx->ks2, &ctx->ks1, ctx->num_rounds, DES_ENCRYPT);
    }
}

void encrypt_des_ede3(DESContext *ctx, unsigned char *input, size_t input_len, unsigned char *output) {
    for (size_t i = 0; i < input_len; i += 8) {
        DES_ecb3_encrypt((const_DES_cblock *)(input + i), (DES_cblock *)(output + i), &ctx->ks1, &ctx->ks2, &ctx->ks3, ctx->num_rounds, DES_ENCRYPT);
    }
}

void encrypt_des_cfb(DESContext *ctx, unsigned char *iv, size_t iv_len, unsigned char *input, size_t input_len, unsigned char *output) {
    DES_cblock des_iv;
    memcpy(des_iv, iv, iv_len > MAX_IV_LENGTH ? MAX_IV_LENGTH : iv_len);

    for (size_t i = 0; i < input_len; ++i) {
        DES_encrypt((const_DES_cblock *)&des_iv, &des_iv, ctx->num_rounds == 1 ? &ctx->ks1 : ctx->num_rounds == 2 ? &ctx->ks1 : &ctx->ks1);
        output[i] = input[i] ^ des_iv[0];
    }
}

void encrypt_data(CipherMode mode, DESContext *ctx, unsigned char *key, size_t key_len, unsigned char *iv, size_t iv_len, unsigned char *input, size_t input_len, unsigned char *output) {
    set_des_context(ctx, key, key_len);
    switch (mode) {
        case MODE_ECB:
            encrypt_des_ecb(ctx, input, input_len, output);
            break;
        case MODE_EDE:
            encrypt_des_ede(ctx, input, input_len, output);
            break;
        case MODE_EDE3:
            encrypt_des_ede3(ctx, input, input_len, output);
            break;
        case MODE_CFB:
            encrypt_des_cfb(ctx, iv, iv_len, input, input_len, output);
            break;
        default:
            handle_error("Unsupported cipher mode");
    }
}

int main() {
    // Example usage
    unsigned char key[24] = { /* Key bytes */ };
    unsigned char iv[MAX_IV_LENGTH] = { /* IV bytes */ };
    unsigned char data[] = "Hello, World!";
    size_t data_len = strlen((char *)data);
    unsigned char encrypted[data_len];

    DESContext ctx;
    encrypt_data(MODE_CFB, &ctx, key, sizeof(key), iv, sizeof(iv), data, data_len, encrypted);

    printf("Encrypted Data: ");
    for (size_t i = 0; i < data_len; ++i) {
        printf("%02x", encrypted[i]);
    }
    printf("\n");

    return 0;
}
```

### Key Points:
- **Key Handling**: Validates and truncates keys to valid DES lengths.
- **IV Handling**: Supports arbitrary IV length, truncated as needed.
- **Error Handling**: Graceful error management with `handle_error`.
- **Extensibility**: Structured for easy addition of new modes or algorithms.
- **Memory Management**: Uses OpenSSL's memory-safe functions.

### Considerations:
- Ensure OpenSSL is linked during compilation: `-lssl -ldes`
- This code assumes a basic understanding of DES and CFB mode operations.
- For production, consider more robust error handling and security practices.']

