    int size;
    pthread_mutex_t lock;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void log_resource_constraint() {
    fprintf(stderr, "Resource constraint: Unable to create new structure.\n");
}

int list_full(List* list) {
    return list->size >= MAX_ELEMENTS;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
