class ScriptLoader {
    constructor(scripts, metadataApiUrl) {
        this.scripts = scripts;
        this.metadataApiUrl = metadataApiUrl;
        this.globalState = {};
        this.callbacks = [];
        this.loadingPaused = false;
        this.loadTimeout = 5000; // milliseconds
        this.maxRetries = 3;
    }

    async loadScripts() {
        const metadataPromises = this.scripts.map(script => 
            fetch(`${this.metadataApiUrl}/${script.name}`)
                .then(response => response.json())
                .catch(error => console.error('Metadata API Error:', error))
        );

        const metadataArray = await Promise.all(metadataPromises);

        for (const [index, script] of this.scripts.entries()) {
            if (metadataArray[index]) {
                const { version, lastModified } = metadataArray[index];
                // Conditional loading based on metadata
                if (this.shouldLoadScript(script, version, lastModified)) {
                    await this.loadScriptWithRetries(script.src);
                }
            } else {
                console.warn(`Metadata not available for ${script.name}, skipping.`);
            }
        }

        this.executeCallbacks();
    }

    shouldLoadScript(script, version, lastModified) {
        // Implement logic to decide whether the script should be loaded based on metadata
        return true;
    }

    async loadScriptWithRetries(src) {
        let attempts = 0;

        const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

        while (attempts < this.maxRetries) {
            try {
                if (!this.loadingPaused) {
                    await this.loadAndExecuteScript(src);
                    return;
                } else {
                    console.log('Loading paused. Waiting to resume...');
                    await delay(1000); // Check every second
                }
            } catch (error) {
                attempts++;
                const backoffTime = Math.pow(2, attempts) * 500; // Exponential backoff
                console.error(`Failed to load ${src}. Attempt ${attempts} of ${this.maxRetries}:`, error);
                await delay(backoffTime);
            }
        }

        throw new Error(`Failed to load script after ${this.maxRetries} attempts: ${src}`);
    }

    async loadAndExecuteScript(src) {
        return new Promise((resolve, reject) => {
            const scriptTag = document.createElement('script');
            scriptTag.src = src;

            // Set timeout
            const timeoutId = setTimeout(() => {
                scriptTag.remove();
                reject(new Error(`Script ${src} exceeded the time limit`));
            }, this.loadTimeout);

            scriptTag.onload = () => {
                clearTimeout(timeoutId);
                resolve();
            };

            scriptTag.onerror = (error) => {
                clearTimeout(timeoutId);
                reject(error);
            };

            document.head.appendChild(scriptTag);
        });
    }

    executeCallbacks() {
        for (const callback of this.callbacks) {
            try {
                callback(this.globalState);
            } catch (error) {
                console.error('Callback execution error:', error);
            }
        }
    }

    registerCallback(callback) {
        if (typeof callback === 'function') {
            this.callbacks.push(callback);
        } else {
            throw new Error('Registered callback is not a function');
        }
    }

    pauseLoading() {
        this.loadingPaused = true;
    }

    resumeLoading() {
        this.loadingPaused = false;
        this.loadScripts();
    }
}

// Usage
const scripts = [
    { name: 'script1', src: 'https://example.com/script1.js' },
    { name: 'script2', src: 'https://example.com/script2.js' },
];

const loader = new ScriptLoader(scripts, 'https://api.example.com/metadata');

loader.registerCallback(globalState => {
    console.log('All scripts loaded. Global state:', globalState);
});

loader.loadScripts();
```

This code provides a `ScriptLoader` class that handles loading and executing JavaScript files according to the specified requirements. It includes features such as retries with exponential backoff, conditional loading based on metadata, handling cross-origin requests, logging errors, pausing/resuming the loading process, and managing script execution order by ensuring scripts are loaded sequentially while respecting dependencies.

Please note that for a complete implementation, additional considerations like CORS headers management, cache optimizations, and modular updates/rollbacks may require further integrations with server configurations or more complex client-side logic."]

