#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    size_t successful_allocations;
} DynamicList;

DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    list->successful_allocations = 0;
    return list;
}

void resize_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

int add_crc_indication(DynamicList *list, int rx_ue_tag, int rnti, int crc_rel8_tag) {
    pthread_mutex_lock(&list->lock);
    if (rnti < 1 || rnti > MAX_RNTI) {
        printf("Error: Invalid RNTI %d\n", rnti);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    if (list->size == list->capacity) {
        resize_dynamic_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[list->size];
    element->RX_UE_INFORMATION_TAG = rx_ue_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    list->size++;
    list->successful_allocations++;

    printf("Successful allocation: %zu\n", list->successful_allocations);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(const DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("File opening failed");
        return;
    }
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    fclose(file);
}

void deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("File opening failed");
        return;
    }
    size_t new_size = fread(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->capacity, file);
    list->size = new_size;
    fclose(file);
}

