```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_ENTRIES 10000

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pduArray;
    size_t maxPduCount;
    size_t currentCount;
    pthread_mutex_t lock;
    FILE *logFile;
    int logEntryCount;
    char logFileName[256];
} PduManager;

// Memory pool for efficient allocation
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t poolSize;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

PduManager pduManager;
MemoryPool memoryPool;

void initPduManager(size_t maxPduCount) {
    pthread_mutex_init(&pduManager.lock, NULL);
    pduManager.pduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxPduCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduManager.pduArray) {
        perror("Failed to allocate memory for PDU array");
        exit(EXIT_FAILURE);
    }
    pduManager.maxPduCount = maxPduCount;
    pduManager.currentCount = 0;
    snprintf(pduManager.logFileName, sizeof(pduManager.logFileName), "pdu_log_%d.txt", (int)time(NULL));
    pduManager.logFile = fopen(pduManager.logFileName, "w");
    if (!pduManager.logFile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pduManager.logEntryCount = 0;
}

void initMemoryPool(size_t poolSize) {
    pthread_mutex_init(&memoryPool.mutex, NULL);
    memoryPool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(poolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!memoryPool.pool) {
        perror("Failed to allocate memory for the pool");
        exit(EXIT_FAILURE);
    }
    memoryPool.poolSize = poolSize;
    memoryPool.used = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocateFromMemoryPool() {
    pthread_mutex_lock(&memoryPool.mutex);
    if (memoryPool.used >= memoryPool.poolSize) {
        pthread_mutex_unlock(&memoryPool.mutex);
        fprintf(stderr, "Out of memory in pool\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &memoryPool.pool[memoryPool.used++];
    pthread_mutex_unlock(&memoryPool.mutex);
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 1000;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

void logPdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(pduManager.logFile, "[%s] RX_UE_INFORMATION_TAG: %lu, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %u\n",
            timestamp, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
    fflush(pduManager.logFile);

    if (++pduManager.logEntryCount >= MAX_ENTRIES) {
        fclose(pduManager.logFile);
        snprintf(pduManager.logFileName, sizeof(pduManager.logFileName), "pdu_log_%d.txt", (int)time(NULL));
        pduManager.logFile = fopen(pduManager.logFileName, "w");
        if (!pduManager.logFile) {
            perror("Failed to open new log file");
            exit(EXIT_FAILURE);
        }
        pduManager.logEntryCount = 0;
    }
}

void addPdu() {
    pthread_mutex_lock(&pduManager.lock);
    if (pduManager.currentCount >= pduManager.maxPduCount) {
        fprintf(stderr, "Maximum PDU count reached\n");
        pthread_mutex_unlock(&pduManager.lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocateFromMemoryPool();
    if (!pdu) {
        pthread_mutex_unlock(&pduManager.lock);
        return;
    }
    pduManager.pduArray[pduManager.currentCount++] = *pdu;

    logPdu(pdu);

    pthread_mutex_unlock(&pduManager.lock);
}

void cleanup() {
    pthread_mutex_destroy(&pduManager.lock);
    free(pduManager.pduArray);
    fclose(pduManager.logFile);

    pthread_mutex_lock(&memoryPool.mutex);
    free(memoryPool.pool);
    pthread_mutex_unlock(&memoryPool.mutex);
    pthread_mutex_destroy(&memoryPool.mutex);
}

void* monitorPerformance(void *arg) {
    while (1) {
        sleep(60); // Monitor every minute
        FILE *procStatus = fopen("/proc/self/stat", "r");
        if (!procStatus) continue;

        char buffer[256];
        fgets(buffer, sizeof(buffer), procStatus);
        fclose(procStatus);

        long rss;
        sscanf(buffer, "%*d %*s %*c %*d %*d %*d %*u %*u %*u %*lu %*lu %ld", &rss);
        size_t memoryUsage = rss * 4; // Assuming 4 bytes per page
        printf("Memory Usage: %zu KB\n", memoryUsage);

        // Add CPU usage monitoring as needed
    }
    return NULL;
}

int main() {
    initPduManager(1000); // Example maxPduCount
    initMemoryPool(2000); // Example pool size

    pthread_t monitorThread;
    pthread_create(&monitorThread, NULL, monitorPerformance, NULL);

    for (int i = 0; i < 1500; ++i) { // Example usage
        addPdu();
    }

    cleanup();
    pthread_cancel(monitorThread);
    pthread_join(monitorThread, NULL);

    return 0;
}
```

