    return true;
}

// Clean up the dynamic list to prevent memory leaks
void freeDynamicNFAPIList(DynamicNFAPIList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    if (list->data) {
        free(list->data);
        list->data = NULL;
    }

    list->capacity = 0;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
