typedef struct QosParameters {
    int priorityLevel;
    // Add other fields as needed
} QosParameters;

typedef struct RntiInfo {
    time_t lastActivityTimestamp;
    int hasDataToProcess;
    int qosPriorityLevel;
    struct RntiInfo* prev;
    struct RntiInfo* next;
} RntiInfo;

typedef struct UeSessionInfo {
    int ueId;
    RntiInfo rntiListHead;
    QosParameters qosParameters;
    pthread_mutex_t mutex;
} UeSessionInfo;

// Function prototypes
UeSessionInfo* initializeSessions(int numUsers);
void destroySessions(UeSessionInfo* sessions, int numUsers);
int addRntiTag(UeSessionInfo* session);

UeSessionInfo* initializeSessions(int numUsers) {
    if (numUsers > MAX_USERS || numUsers <= 0) return NULL;

    UeSessionInfo* sessions = (UeSessionInfo*)malloc(numUsers * sizeof(UeSessionInfo));
    if (!sessions) return NULL;

    for (int i = 0; i < numUsers; ++i) {
        sessions[i].ueId = i;
        sessions[i].rntiListHead.prev = &sessions[i].rntiListHead;
        sessions[i].rntiListHead.next = &sessions[i].rntiListHead;
        pthread_mutex_init(&sessions[i].mutex, NULL);
        // Initialize QoS parameters
        sessions[i].qosParameters.priorityLevel = rand() % 10; // Example initialization
    }

    return sessions;
}

void destroySessions(UeSessionInfo* sessions, int numUsers) {
    if (!sessions) return;

    for (int i = 0; i < numUsers; ++i) {
        pthread_mutex_lock(&sessions[i].mutex);

        RntiInfo* current = sessions[i].rntiListHead.next;
        while (current != &sessions[i].rntiListHead) {
            RntiInfo* next = current->next;
            free(current);
            current = next;
        }

        pthread_mutex_unlock(&sessions[i].mutex);
        pthread_mutex_destroy(&sessions[i].mutex);
    }

    free(sessions);
}

int addRntiTag(UeSessionInfo* session) {
    if (!session) return -1;

    pthread_mutex_lock(&session->mutex);

    int count = 0;
    RntiInfo* current = session->rntiListHead.next;
    while (current != &session->rntiListHead && count < MAX_RNTI_TAGS) {
        ++count;
        current = current->next;
    }

    if (count >= MAX_RNTI_TAGS) {
        pthread_mutex_unlock(&session->mutex);
        return -1; // Limit reached
    }

    RntiInfo* newRntiTag = (RntiInfo*)malloc(sizeof(RntiInfo));
    if (!newRntiTag) {
        pthread_mutex_unlock(&session->mutex);
        return -2; // Memory allocation failed
    }

    newRntiTag->lastActivityTimestamp = time(NULL);
    newRntiTag->hasDataToProcess = 0;
    newRntiTag->qosPriorityLevel = rand() % 10; // Random QoS priority level

    RntiInfo* prev = session->rntiListHead.prev;
    newRntiTag->next = &session->rntiListHead;
    newRntiTag->prev = prev;
    prev->next = newRntiTag;
    session->rntiListHead.prev = newRntiTag;

    pthread_mutex_unlock(&session->mutex);
    return 0; // Success
}
```

This code initializes and manages a dynamically allocated array of `UeSessionInfo` structures. Each structure contains a circular doubly-linked list for managing `RntiInfo` tags, ensuring thread-safe operations using mutexes. The function also handles memory allocation and deallocation safely, with constraints on the number of active `RntiInfo` tags per session.']

