#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    int max_sema_count;
    int initial_value;
} semaphore_config;

typedef struct {
    sem_t sema;
    pthread_mutex_t lock;
} semaphore;

static semaphore *sema_pool = NULL;
static size_t current_sema_count = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

int configure_max_semaphores(size_t max_count) {
    if (max_count > MAX_SEMAPHORES || max_count == 0) return -1;
    sema_pool = realloc(sema_pool, sizeof(semaphore) * max_count);
    current_sema_count = max_count;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (size_t i = 0; i < max_count; ++i) {
        sema_pool[i].sema = SEM_FAILED;
        pthread_mutex_init(&sema_pool[i].lock, &attr);
    }

    pthread_mutexattr_destroy(&attr);
    return 0;
}

semaphore* create_semaphore(semaphore_config *config) {
    if (!config || current_sema_count == 0 || config->initial_value < 1)
        return NULL;

    int ret;
    pthread_mutex_lock(&pool_lock);

    for (size_t i = 0; i < current_sema_count; ++i) {
        if (sema_pool[i].sema == SEM_FAILED) {
            ret = sem_init(&sema_pool[i].sema, 0, config->initial_value);
            if (ret != 0) {
                pthread_mutex_unlock(&pool_lock);
                return NULL;
            }
            pthread_mutex_unlock(&pool_lock);
            return &sema_pool[i];
        }
    }

    pthread_mutex_unlock(&pool_lock);
    return NULL; // No available semaphores
}

int delete_semaphore(semaphore *sema) {
    if (!sema || !pthread_mutex_trylock(&sema->lock))
        return -1;

    int ret = sem_destroy(&sema->sema);
    pthread_mutex_unlock(&sema->lock);

    if (ret != 0)
        return -2;

    pthread_mutex_lock(&pool_lock);
    sema->sema = SEM_FAILED; // Mark as available
    pthread_mutex_unlock(&pool_lock);

    return 0;
}

int perform_operation(semaphore *sem1, semaphore *sem2) {
    if (!sem1 || !sem2)
        return -1;

    int ret1 = sem_wait(&sem1->sema);
    if (ret1 != 0) return -2;

    int ret2 = sem_wait(&sem2->sema);
    if (ret2 != 0) {
        sem_post(&sem1->sema); // Release the first semaphore
        return -3;
    }

    // Perform some critical operation here

    sem_post(&sem1->sema);
    sem_post(&sem2->sema);

    return 0;
}

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}
