#define MAX_BATCH_SIZE 1000

typedef struct {
    int transactionID;
    char sourceIP[16];
    char destinationIP[16];
    size_t payloadSize;
    int status; // 0 for failure, 1 for success
} DataTransferObject;

typedef struct {
    DataTransferObject* transfers;
    size_t count;
    pthread_mutex_t lock;
} Batch;

Batch* createBatch(size_t initialCapacity) {
    Batch* batch = malloc(sizeof(Batch));
    if (!batch) return NULL;

    batch->transfers = calloc(initialCapacity, sizeof(DataTransferObject));
    if (!batch->transfers) {
        free(batch);
        return NULL;
    }

    pthread_mutex_init(&batch->lock, NULL);
    batch->count = 0;
    return batch;
}

void destroyBatch(Batch* batch) {
    if (batch) {
        pthread_mutex_lock(&batch->lock);
        free(batch->transfers);
        pthread_mutex_unlock(&batch->lock);

        pthread_mutex_destroy(&batch->lock);
        free(batch);
    }
}

int addTransferObject(Batch* batch, DataTransferObject dto) {
    pthread_mutex_lock(&batch->lock);

    if (batch->count >= MAX_BATCH_SIZE) {
        pthread_mutex_unlock(&batch->lock);
        return -1; // Batch full
    }

    for (size_t i = 0; i < batch->count; ++i) {
        if (batch->transfers[i].transactionID == dto.transactionID) {
            pthread_mutex_unlock(&batch->lock);
            return -2; // Duplicate transactionID
        }
    }

    if (batch->count >= MAX_BATCH_SIZE / 2 && realloc(batch->transfers, (MAX_BATCH_SIZE + MAX_BATCH_SIZE / 2) * sizeof(DataTransferObject)) == NULL) {
        pthread_mutex_unlock(&batch->lock);
        return -3; // Memory allocation failed
    }

    batch->transfers[batch->count++] = dto;
    pthread_mutex_unlock(&batch->lock);
    return 0; // Success
}

void* processBatch(void* arg) {
    Batch* batch = (Batch*)arg;

    for (size_t i = 0; i < batch->count; ++i) {
        // Simulate processing the transfer object
        printf("Processing transactionID: %d from %s to %s\n", 
               batch->transfers[i].transactionID, 
               batch->transfers[i].sourceIP,
               batch->transfers[i].destinationIP);

        // Randomly simulate success or failure for demonstration purposes
        batch->transfers[i].status = rand() % 2;
    }

    return NULL;
}

void initializeTransfers(Batch* batches[3]) {
    pthread_t threads[3];

    for (int i = 0; i < 3; ++i) {
        if (!batches[i]) {
            fprintf(stderr, "Batch initialization failed\n");
            continue;
        }

        if (pthread_create(&threads[i], NULL, processBatch, batches[i])) {
            perror("Failed to create thread");
            destroyBatch(batches[i]);
            batches[i] = NULL;
            continue;
        }
    }

    for (int i = 0; i < 3; ++i) {
        if (batches[i]) {
            pthread_join(threads[i], NULL);
            destroyBatch(batches[i]);
            batches[i] = NULL;
        }
    }
}

int main() {
    Batch* batches[3];

    for (int i = 0; i < 3; ++i) {
        batches[i] = createBatch(10); // Initial capacity
        if (!batches[i]) {
            fprintf(stderr, "Failed to create batch %d\n", i);
            break;
        }
    }

    DataTransferObject dto1 = {1, "192.168.0.1", "192.168.0.2", 1024, 0};
    addTransferObject(batches[0], dto1);

    DataTransferObject dto2 = {2, "192.168.0.3", "192.168.0.4", 2048, 0};
    addTransferObject(batches[1], dto2);

    initializeTransfers(batches);

    return 0;
}
