} NFAPI_RX_FRAME_INFO;

typedef struct {
    NFAPI_RX_FRAME_INFO **items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_RX_FRAME_LIST;

#define INITIAL_CAPACITY 4
#define MAX_ENTRIES 1024 // Adjust based on system resource limits.

// Function to initialize the list.
NFAPI_RX_FRAME_LIST* nfa_rx_frame_list_init() {
    NFAPI_RX_FRAME_LIST *list = malloc(sizeof(NFAPI_RX_FRAME_LIST));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for NFAPI_RX_FRAME_LIST.\n");
        return NULL;
    }

    list->items = calloc(INITIAL_CAPACITY, sizeof(NFAPI_RX_FRAME_INFO*));
    if (!list->items) {
        fprintf(stderr, "Failed to allocate memory for initial capacity.\n");
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to safely add an item to the list.
int nfa_rx_frame_list_add(NFAPI_RX_FRAME_LIST *list, unsigned long ue_id, unsigned int rrc_tag) {
    if (!list || list->count >= MAX_ENTRIES) {
        fprintf(stderr, "List is full or invalid.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Resize if necessary.
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;  // Doubling strategy for dynamic growth.
        NFAPI_RX_FRAME_INFO **new_items = realloc(list->items, new_capacity * sizeof(NFAPI_RX_FRAME_INFO*));

        if (!new_items) {
            fprintf(stderr, "Failed to resize the item array.\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->items = new_items;
        list->capacity = new_capacity;
    }

    NFAPI_RX_FRAME_INFO *frame_info = malloc(sizeof(NFAPI_RX_FRAME_INFO));
    if (!frame_info) {
        fprintf(stderr, "Failed to allocate memory for NFAPI_RX_FRAME_INFO.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    frame_info->ue_id = ue_id;
    frame_info->rrc_connection_reconfig_tag = rrc_tag;

    // Initialize RRC_CONFIG.
    frame_info->rrc_config = malloc(sizeof(RRC_CONFIG));
    if (!frame_info->rrc_config) {
        fprintf(stderr, "Failed to allocate memory for RRC_CONFIG.\n");
        free(frame_info);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Populate and validate RRC_CONFIG.
    frame_info->rrc_config->some_field = 0;  // Example initialization.
    frame_info->rrc_config->timestamp = time(NULL);  // Set timestamp.

    list->items[list->count++] = frame_info;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to safely delete the entire list and free all resources.
void nfa_rx_frame_list_destroy(NFAPI_RX_FRAME_LIST *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i]->rrc_config);
        free(list->items[i]);
    }

    free(list->items);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    free(list);
}

// Safe iterator function.
int nfa_rx_frame_list_iterate(const NFAPI_RX_FRAME_LIST *list, void (*callback)(const NFAPI_RX_FRAME_INFO*)) {
    if (!list || !callback) return -1;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        callback(list->items[i]);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return 0;
}
```

This implementation provides a dynamically resizable array with thread safety using `pthread_mutex`, handles memory allocation and deallocation efficiently, respects resource limits with maximum entry constraints, and offers a safe iterator mechanism. Adjustments can be made for specific application requirements such as additional fields in `RRC_CONFIG`.']

