#define ALLOC_BLOCK_SIZE 1024 // Adjust based on system requirements

typedef struct {
    int UE_ID;
    uint32_t RRC_CONNECTION_RECONFIGURATION_TAG;
    void* rrc_config_ptr; // Pointer to the dynamically allocated RRC_CONFIG structure
