// Global variables for memory management
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_RX_FRAME_INFO* frame_list = NULL;
static size_t frame_count = 0;
static char* memory_pool = NULL;
static size_t pool_size = 0;

// Function prototypes
int validate_rrc_config(RRC_CONFIG* config);
void log_issue(const char* message);

// Memory management functions
void* allocate_from_pool(size_t size) {
    static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&pool_lock);

    if (pool_size < size) {
        void* new_block = malloc(ALLOC_BLOCK_SIZE);
        if (!new_block) {
            log_issue("Memory allocation failed");
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
        pool_size += ALLOC_BLOCK_SIZE;
        memory_pool = realloc(memory_pool, pool_size);
        if (!memory_pool) {
            free(new_block);
            log_issue("Memory reallocation failed");
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
    }

    void* ptr = memory_pool + (pool_size - size);
    pool_size -= size;
    pthread_mutex_unlock(&pool_lock);

    return ptr;
}

void free_memory_pool() {
    free(memory_pool);
    memory_pool = NULL;
    pool_size = 0;
}

// Function to initialize list of NFAPI_RX_FRAME_INFO structures
int init_nfa_rx_frame_info_list(size_t n, RRC_CONFIG** configs) {
    pthread_mutex_lock(&list_lock);

    // Ensure the memory pool is initialized only once
    if (!memory_pool) {
        memory_pool = malloc(ALLOC_BLOCK_SIZE);
        if (!memory_pool) {
            log_issue("Initial memory allocation failed");
            pthread_mutex_unlock(&list_lock);
            return -1;
        }
        pool_size = ALLOC_BLOCK_SIZE;
    }

    frame_list = realloc(frame_list, (frame_count + n) * sizeof(NFAPI_RX_FRAME_INFO));
    if (!frame_list) {
        log_issue("Frame list reallocation failed");
        pthread_mutex_unlock(&list_lock);
        return -1;
    }

    for (size_t i = 0; i < n; ++i) {
        NFAPI_RX_FRAME_INFO* frame_info = &frame_list[frame_count + i];

        // Validate RRC_CONFIG
        if (!validate_rrc_config(configs[i])) {
            log_issue("Invalid RRC_CONFIG encountered");
            pthread_mutex_unlock(&list_lock);
            return -1;
        }

        // Allocate memory for RRC_CONFIG structure
        frame_info->rrc_config_ptr = allocate_from_pool(RRC_CONFIG_SIZE);
        if (!frame_info->rrc_config_ptr) {
            log_issue("Failed to allocate RRC_CONFIG");
            pthread_mutex_unlock(&list_lock);
            return -1;
        }

        // Copy the configuration data
        memcpy(frame_info->rrc_config_ptr, configs[i], RRC_CONFIG_SIZE);

        frame_info->UE_ID = i; // Assigning a dummy UE_ID for demonstration
        frame_info->RRC_CONNECTION_RECONFIGURATION_TAG = rand(); // Random tag assignment

    }

    frame_count += n;
    pthread_mutex_unlock(&list_lock);
    return 0;
}

// Validation function for RRC_CONFIG structure
int validate_rrc_config(RRC_CONFIG* config) {
    if (config == NULL || !config->is_complete) {
        log_issue("RRC_CONFIG validation failed");
        return 0; // Invalid configuration
    }
    return 1; // Valid configuration
}

// Logging function for issues encountered during initialization
void log_issue(const char* message) {
    printf("Log: %s\n", message);
}

// Function to free all allocated resources
void cleanup_nfa_rx_frame_info_list() {
    pthread_mutex_lock(&list_lock);

    if (frame_list) {
        for (size_t i = 0; i < frame_count; ++i) {
            free(frame_list[i].rrc_config_ptr); // Free each RRC_CONFIG structure
        }
        free(frame_list);
        frame_list = NULL;
        frame_count = 0;
    }

    free_memory_pool();

    pthread_mutex_unlock(&list_lock);
}

// Periodic revalidation function (simplified version)
void* periodic_revalidate(void* arg) {
    while (1) {
        sleep(10); // Revalidate every 10 seconds
        pthread_mutex_lock(&list_lock);

        for (size_t i = 0; i < frame_count; ++i) {
            RRC_CONFIG* config = (RRC_CONFIG*)frame_list[i].rrc_config_ptr;
            if (!validate_rrc_config(config)) {
                log_issue("Revalidation failed for a frame");
                // Handle revalidation failure
            }
        }

        pthread_mutex_unlock(&list_lock);
    }
    return NULL;
}

int main() {
    // Example usage of the function
    size_t num_frames = 5;
    RRC_CONFIG* configs[num_frames];

    // Initialize configs with dummy data for demonstration
    for (size_t i = 0; i < num_frames; ++i) {
        configs[i] = malloc(RRC_CONFIG_SIZE);
        if (!configs[i]) {
            log_issue("Failed to allocate config");
            return -1;
        }
        // Fill in the necessary fields of RRC_CONFIG
    }

    init_nfa_rx_frame_info_list(num_frames, configs);

    // Start periodic revalidation thread
    pthread_t revalidate_thread;
    if (pthread_create(&revalidate_thread, NULL, periodic_revalidate, NULL) != 0) {
        log_issue("Failed to create revalidation thread");
        cleanup_nfa_rx_frame_info_list();
        return -1;
    }

    // Simulate some operations...

    // Cleanup
