    struct HashTableEntry* next;
} HashTableEntry;

HashTableEntry* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_table_locks[HASH_TABLE_SIZE];

uint32_t hash_function(uint16_t tag) {
    return tag % HASH_TABLE_SIZE;
}

void initialize_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_table_locks[i], NULL);
    }
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry* entry = hash_table[i];
        while (entry != NULL) {
            HashTableEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
        pthread_mutex_destroy(&hash_table_locks[i]);
    }
}

void insert_into_hash_table(uint16_t tag, NFAPI_CRC_INDICATION_PDU_T* data) {
    uint32_t index = hash_function(tag);
    pthread_mutex_lock(&hash_table_locks[index]);

    HashTableEntry* new_entry = malloc(sizeof(HashTableEntry));
    new_entry->rx_ue_information_tag = tag;
    new_entry->data = data;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;

    pthread_mutex_unlock(&hash_table_locks[index]);
}

NFAPI_CRC_INDICATION_PDU_T* find_in_hash_table(uint16_t tag) {
    uint32_t index = hash_function(tag);
    pthread_mutex_lock(&hash_table_locks[index]);

    HashTableEntry* entry = hash_table[index];
    while (entry != NULL) {
        if (entry->rx_ue_information_tag == tag) {
            pthread_mutex_unlock(&hash_table_locks[index]);
            return entry->data;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&hash_table_locks[index]);
    return NULL;
}

