int read_from_file(const char *filename, Configuration **configs) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    size_t capacity = 10;
    *configs = malloc(capacity * sizeof(Configuration));
    if (!*configs) {
        fclose(file);
        return -2;
    }

    int count = 0;
    while (fscanf(file, "%d", &((*configs)[count].setting)) == 1) {
        count++;
        if (count >= capacity) {
            capacity *= 2;
            *configs = realloc(*configs, capacity * sizeof(Configuration));
            if (!*configs) {
                fclose(file);
                return -3;
            }
        }
    }

    fclose(file);
    return count;
}

int read_from_env(const char *env_var, Configuration **configs) {
    const char *value = getenv(env_var);
    if (!value) return 0;

    size_t capacity = 10;
    *configs = malloc(capacity * sizeof(Configuration));
    if (!*configs) return -1;

    int count = 0;
    char *token = strtok((char *)value, ",");
    while (token) {
        int setting = atoi(token);
        (*configs)[count].setting = setting;
        count++;
        token = strtok(NULL, ",");

        if (count >= capacity) {
            capacity *= 2;
            *configs = realloc(*configs, capacity * sizeof(Configuration));
            if (!*configs) return -2;
        }
    }

    return count;
}

