    return 0;
}

int find_smallest(int *array, int size) {
    if (size <= 0) return INT_MAX;

    int smallest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] < smallest) {
            smallest = array[i];
        }
    }
    return smallest;
}

int get_configuration(const char *filename, const char *env_var, int default_value, Configuration **configs, int *smallest) {
