    int file_count = read_from_file(filename, &file_configs);

    if (file_count < 0) {
        printf("Error reading from file: %d\n", file_count);
        return -1;
    }

    Configuration *env_configs = NULL;
    int env_count = read_from_env(env_var, &env_configs);

    if (env_count < 0) {
        printf("Error reading from environment variable: %n\n");
        free(file_configs);
        return -2;
    }

    size_t total_capacity = file_count + env_count + 1; // Plus one for default value
    *configs = malloc(total_capacity * sizeof(Configuration));
    if (!*configs) {
        free(file_configs);
        free(env_configs);
        return -3;
    }

    int valid_count = 0;

    if (file_count > 0) {
        memcpy(*configs, file_configs, file_count * sizeof(Configuration));
        valid_count += file_count;
    }

    if (env_count > 0) {
        memcpy(*configs + valid_count, env_configs, env_count * sizeof(Configuration));
        valid_count += env_count;
    }

    if (valid_count == 0) {
        (*configs)[0].setting = default_value;
        valid_count++;
    } else {
        int validation_status = validate_configurations(*configs, valid_count);
        if (validation_status < 0) {
            printf("Validation error in configurations\n");
            free(file_configs);
            free(env_configs);
            free(*configs);
            return -4;
        }
    }

    int settings[valid_count];
    for (int i = 0; i < valid_count; i++) {
        settings[i] = (*configs)[i].setting;
    }

    *smallest = find_smallest(settings, valid_count);

    free(file_configs);
    free(env_configs);
    return valid_count;
}

