typedef struct {
    RRC_UE_CONTEXT ue_context;
    PHY_TRANSPORT_CHANNEL_CONFIG channel_config;
} LTE_DL_FRAMEINFO;

typedef struct {
    LTE_DL_FRAMEINFO *array;
    size_t capacity;
    size_t count;
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray *da) {
    da->capacity = 10; // Initial capacity
    da->count = 0;
    da->array = (LTE_DL_FRAMEINFO *)malloc(da->capacity * sizeof(LTE_DL_FRAMEINFO));
}

// Resize the dynamic array if needed
static void resizeIfNeeded(DynamicArray *da) {
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        LTE_DL_FRAMEINFO *new_array = realloc(da->array, new_capacity * sizeof(LTE_DL_FRAMEINFO));
        if (new_array != NULL) {
            da->array = new_array;
            da->capacity = new_capacity;
        } else {
            fprintf(stderr, "Memory allocation failed during resize.\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Add a new entry to the dynamic array
void addEntry(DynamicArray *da, int id, const char *rrc_context_data, int bwp_id, float bandwidth_kHz) {
    resizeIfNeeded(da);

    da->array[da->count].ue_context.id = id;
    strncpy(da->array[da->count].ue_context.rrc_context_data, rrc_context_data, sizeof(da->array[da->count].ue_context.rrc_context_data));
    da->array[da->count].channel_config.bwp_id = bwp_id;
    da->array[da->count].channel_config.bandwidth_kHz = bandwidth_kHz;

    ++da->count;
}

// Update BWP configuration for a specific UE
void updateBWPConfig(DynamicArray *da, int id, int new_bwp_id, float new_bandwidth_kHz) {
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].ue_context.id == id) {
            da->array[i].channel_config.bwp_id = new_bwp_id;
            da->array[i].channel_config.bandwidth_kHz = new_bandwidth_kHz;
            return;
        }
    }
    fprintf(stderr, "UE with ID %d not found.\n", id);
}

// Iterate over the dynamic array
void iterateEntries(DynamicArray *da) {
    for (size_t i = 0; i < da->count; ++i) {
        printf("ID: %d, BWP ID: %d, Bandwidth: %.2f kHz\n",
               da->array[i].ue_context.id,
               da->array[i].channel_config.bwp_id,
               da->array[i].channel_config.bandwidth_kHz);
    }
}

// Free the dynamic array
void freeDynamicArray(DynamicArray *da) {
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->count = 0;
}

// Example of handling external updates (stub function)
void handleExternalUpdates(DynamicArray *da) {
    // Simulate receiving data from an external source
    int new_id = rand() % 100; // Random ID for demonstration
    const char *new_rrc_context_data = "New context data";
    int new_bwp_id = rand() % 10;
    float new_bandwidth_kHz = (rand() % 100) + 1.0;

    addEntry(da, new_id, new_rrc_context_data, new_bwp_id, new_bandwidth_kHz);
}

int main() {
    DynamicArray da;
    initDynamicArray(&da);

    // Example usage
    addEntry(&da, 1, "Initial context data", 2, 20.5);
    iterateEntries(&da);

    updateBWPConfig(&da, 1, 3, 25.0);
    iterateEntries(&da);

    handleExternalUpdates(&da); // Simulate external updates
    iterateEntries(&da);

    freeDynamicArray(&da);
    return 0;
}
