            int cipher_id = EVP_get_cipherbyname(cipher_name);
            if (!cipher_id || !EVP_CIPHER_CTX_init(config->cipher_ctx)) {
                fprintf(stderr, "Error: Invalid or unsupported cipher\n");
                goto cleanup;
