        } else if (strncmp(line, "key=", 4) == 0) {
            const char *key_path = line + 4;
            pkey = PEM_read_PrivateKey(fp, NULL, NULL, NULL);
            if (!pkey || strcmp(key_path, PEM_get_header_line(pkey)) != 0) {
                fprintf(stderr, "Error: Failed to load private key\n");
                goto cleanup;
            }
        }
    }

    config->certificate = cert;
    config->private_key = pkey;

cleanup:
    fclose(fp);
    if (!config->cipher_ctx || !cert || !pkey) {
        free_crypto_config(config);
        return NULL;
    }
    return config;
}

void free_crypto_config(CryptoConfig *config) {
    if (config) {
        EVP_CIPHER_CTX_free(config->cipher_ctx);
        X509_free(config->certificate);
        EVP_PKEY_free(config->private_key);
        free(config);
    }
}
```

### Key Points:
- **Error Handling**: The function checks for errors at each step and cleans up resources if any error occurs.
- **Resource Management**: Memory is allocated dynamically, and all resources are freed in case of failure.
- **File Parsing**: The configuration file is read line by line to extract cipher, certificate, and key information.
- **OpenSSL Integration**: Uses OpenSSL functions for handling cryptographic operations.

This code provides a basic framework that can be expanded upon to meet specific requirements such as more complex parsing or additional error handling.']

