typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

// Function prototypes
List* create_list();
void destroy_list(List* list);
int insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int validate_rnti(int rnti);
NFAPI_CRC_INDICATION_PDU_T generate_pdu();
void log_message(const char* message);

// Create a new list
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free resources
void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Insert a node into the list if RNTI is unique and valid
int insert_node(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_rnti(pdu.RNTI)) {
        log_message("Invalid RNTI value.");
        return 0;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            log_message("Duplicate RNTI value encountered.");
            return 0;
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_message("Memory allocation failed.");
        return 0;
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

// Validate RNTI is within the specified range
int validate_rnti(int rnti) {
    return (rnti >= 0 && rnti <= MAX_RNTI);
}

