    return pdu;
}

// Log messages for debugging and error tracking
void log_message(const char* message) {
    printf("LOG: %s\n", message);
}

// Example function to populate list concurrently
void* populate_list(void* arg) {
    List* list = (List*)arg;
    const int num_pdus = 100; // Number of PDUs to generate

    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_pdu();
        insert_node(list, pdu);
    }

    return NULL;
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL)); // Seed random number generator

    List* list = create_list();
    if (!list) {
        log_message("Failed to create list.");
        return 1;
    }

    const int num_threads = 4; // Number of threads for concurrent access
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, populate_list, list)) {
            log_message("Failed to create thread.");
            destroy_list(list);
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
