    MIB_BLOCK* mibs; // Dynamically allocated array of MIB blocks
} LTE_RRC_MESSAGE;

typedef struct Node {
    LTE_RRC_MESSAGE message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_messages;
} MessageList;

// Function prototypes
void initialize_message_list(MessageList* list, int max_size);
void add_rrc_message(MessageList* list);
void cleanup_expired_messages(MessageList* list);
void free_message_list(MessageList* list);

MessageList message_list;

void initialize_message_list(MessageList* list, int max_size) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->max_messages = max_size;
}

Node* create_node(LTE_RRC_MESSAGE msg) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        exit(EXIT_FAILURE);
    }
    new_node->message = msg;
    new_node->next = NULL;
    return new_node;
}

void add_rrc_message(MessageList* list) {
    pthread_mutex_lock(&list->lock);

    // Generate unique UE_ID and MIBs
    unsigned long ue_id = rand();  // Replace with a more sophisticated ID generator if needed.
    LTE_RRC_MESSAGE msg;
    msg.ue_id = ue_id;
    time(&(msg.last_used));

    int mib_count = 5; // Example count, replace with actual logic to determine MIBs
    msg.mibs = (MIB_BLOCK*)malloc(mib_count * sizeof(MIB_BLOCK));
    if (!msg.mibs) {
        fprintf(stderr, "Memory allocation failed for MIB blocks.\n");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }

    Node* new_node = create_node(msg);

    // Insert at head
    new_node->next = list->head;
    list->head = new_node;

    cleanup_expired_messages(list);  // Ensure we don't exceed max messages

    pthread_mutex_unlock(&list->lock);
}

void cleanup_expired_messages(MessageList* list) {
    time_t now = time(NULL);
    Node **current = &list->head, *to_delete = NULL;
    int count = 0;

    while (*current && count < list->max_messages) {
        if (difftime(now, (*current)->message.last_used) > 3600) { // Example expiry time
            to_delete = *current;
            *current = (*current)->next;
            free(to_delete->message.mibs);
            free(to_delete);
        } else {
            current = &(*current)->next;
            count++;
        }
    }

    while (list->head && count >= list->max_messages) {
        to_delete = list->head;
        list->head = list->head->next;
        free(to_delete->message.mibs);
        free(to_delete);
        count--;
    }
}

void free_message_list(MessageList* list) {
    Node *current = list->head, *temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp->message.mibs);
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
}

int main() {
    initialize_message_list(&message_list, MAX_MESSAGES);

    for (int i = 0; i < 150; ++i) {  // Simulate adding messages
        add_rrc_message(&message_list);
    }

    free_message_list(&message_list);

    return 0;
}
