public class XmlTransactionProcessor
{
    private readonly ILogger<XmlTransactionProcessor> _logger;
    private readonly XsdSchemaValidator _xsdValidator;
    private readonly int _maxConcurrentThreads;

    public XmlTransactionProcessor(ILogger<XmlTransactionProcessor> logger, string xsdPath, int maxConcurrentThreads = 50)
    {
        _logger = logger;
        _xsdValidator = new XsdSchemaValidator(xsdPath);
        _maxConcurrentThreads = Math.Min(maxConcurrentThreads, Environment.ProcessorCount * 2); // Limit based on system resources
    }

    public async Task ProcessXmlFilesAsync(IEnumerable<string> xmlFilePaths)
    {
        var tasks = xmlFilePaths.Select(filePath => ProcessFileAsync(filePath));

        using (var throttler = new SemaphoreSlim(_maxConcurrentThreads))
        {
            var results = await Task.WhenAll(tasks.Select(async task =>
            {
                await throttler.WaitAsync();
                try
                {
                    return await task;
                }
                finally
                {
                    throttler.Release();
                }
            }));

            foreach (var result in results)
            {
                if (!result.Item2) _logger.LogError(result.Item1);
            }
        }
    }

    private async Task<(string, bool)> ProcessFileAsync(string filePath)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();
        try
        {
            _logger.LogInformation($"Processing file: {filePath} started.");

            if (!_xsdValidator.Validate(filePath))
            {
                _logger.LogError($"Validation failed for file: {filePath}");
                return (filePath, false);
