            return (filePath, true);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error processing file: {filePath}");
            return (filePath, false);
        }
        finally
        {
            stopwatch.Stop();
            _logger.LogInformation($"Processing time for file: {filePath} was {stopwatch.ElapsedMilliseconds}ms.");
        }
    }

