public static class RetryPolicy
{
    public static async Task ExecuteAsync(Func<Task> action, int maxRetries = 5)
    {
        int retryCount = 0;
        var delay = TimeSpan.FromSeconds(1);

        while (retryCount < maxRetries)
        {
            try
            {
                await action();
                break;  // Exit loop if successful.
            }
            catch (Exception ex) when (IsTransient(ex))
            {
                retryCount++;
                _logger.LogWarning($"Retry {retryCount} for transient failure: {ex.Message}");
                await Task.Delay(delay);
                delay = TimeSpan.FromSeconds(Math.Pow(2, retryCount));  // Exponential backoff
            }
        }
    }

    private static bool IsTransient(Exception ex)
    {
