// Assuming these types are defined elsewhere
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; // 0 or 1 for REL8_TAG
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
};

// Function to create a new node with random values, aligned for cache performance
struct ListNode* create_node(uint16_t min_rnti, uint16_t max_rnti) {
    // Alignment size typically depends on the architecture; 64 bytes is common for L1 cache line
    struct ListNode* node = (struct ListNode*) _aligned_malloc(sizeof(struct ListNode), 64);
    if (!node) return NULL;

    node->data.RX_UE_INFORMATION_TAG = rand() % 65536; // Random 16-bit value

    do {
        node->data.RNTI = rand() % (max_rnti - min_rnti + 1) + min_rnti;
    } while (node->data.RNTI < min_rnti || node->data.RNTI > max_rnti);

    // Randomly set CRCFLAG to 0 or 1
    node->data.CRCFLAG = rand() % 2;

    node->next = NULL;
    return node;
}

// Function to populate the linked list with N nodes
struct ListNode* populate_linked_list(size_t n, uint16_t min_rnti, uint16_t max_rnti) {
    if (n == 0 || min_rnti > max_rnti) return NULL;

    struct ListNode* head = NULL;
    struct ListNode** current = &head;

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        struct ListNode* new_node = create_node(min_rnti, max_rnti);
        if (!new_node) {
            // Free all previously allocated nodes
            struct ListNode* temp;
            while (*current) {
                temp = (*current)->next;
                _aligned_free(*current);
                *current = temp;
            }
            return NULL; // Allocation failure
        }

        *current = new_node;
        current = &new_node->next;
    }

    return head;
}

// Function to free the linked list memory
void free_linked_list(struct ListNode* head) {
    struct ListNode* temp;
    while (head) {
        temp = head->next;
        _aligned_free(head);
        head = temp;
    }
}
