#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_RX_FRAME_INFO_T;

typedef struct Node {
    NFAPI_RX_FRAME_INFO_T frameInfo;
    float snr;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    float totalSnr;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->head = NULL;
    array->count = 0;
    array->totalSnr = 0.0f;
    return array;
}

int addFrame(DynamicArray* array, NFAPI_RX_FRAME_INFO_T frameInfo, float snr) {
    if (array == NULL || frameInfo.RNTI == 0) return 0;

    Node* current = array->head;
    while (current != NULL) {
        if (current->frameInfo.RNTI == frameInfo.RNTI) return 0; // Duplicate RNTI
        current = current->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return 0;

    newNode->frameInfo = frameInfo;
    newNode->snr = snr;
    newNode->next = array->head;
    array->head = newNode;
    array->count++;
    array->totalSnr += snr;

    return 1; // Frame added successfully
}

float calculateAverageSNR(DynamicArray* array) {
    if (array == NULL || array->count == 0) return 0.0f;
    return array->totalSnr / array->count;
}

void freeDynamicArray(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(array);
}

// Placeholder function to simulate external data processing service
float getRealTimeSNRUpdate() {
    // Simulate SNR update from an external service
    return 10.0f; // Example value
}

void processFramesWithExternalService(DynamicArray* array) {
    if (array == NULL) return;

    Node* current = array->head;
    while (current != NULL) {
        float updatedSNR = getRealTimeSNRUpdate();
        array->totalSnr -= current->snr;
        current->snr = updatedSNR;
        array->totalSnr += updatedSNR;
        current = current->next;
    }
}

int main() {
    DynamicArray* frameArray = createDynamicArray();

    NFAPI_RX_FRAME_INFO_T frame1 = {1, 1001, 2};
    addFrame(frameArray, frame1, 15.0f);

    NFAPI_RX_FRAME_INFO_T frame2 = {2, 1002, 3};
    addFrame(frameArray, frame2, 20.0f);

    printf("Average SNR: %f\n", calculateAverageSNR(frameArray));

    processFramesWithExternalService(frameArray);
    printf("Updated Average SNR: %f\n", calculateAverageSNR(frameArray));

    freeDynamicArray(frameArray);
    return 0;
}
