#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <resolv.h>
#include <errno.h>
#include <time.h>

typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG[10];
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    unsigned char IP_ADDRESS[16]; // IPv6 address
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread safety during DNS resolution
pthread_mutex_t dns_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to resolve hostname and return the first IP address found
int resolve_hostname(const char *hostname, unsigned char *ip_address) {
    struct hostent *host;
    int err;

    pthread_mutex_lock(&dns_lock);

    if ((host = gethostbyname(hostname)) == NULL) {
        err = h_errno;
        pthread_mutex_unlock(&dns_lock);
        return -1; // DNS resolution failed
    }

    if (host->h_addrtype != AF_INET6) {
        pthread_mutex_unlock(&dns_lock);
        return -2; // Unsupported address type
    }

    memcpy(ip_address, host->h_addr_list[0], host->h_length);

    pthread_mutex_unlock(&dns_lock);

    return 0; // Success
}

// Function to generate random CRCFLAG
unsigned char generate_random_crcflag() {
    srand(time(NULL) ^ (pthread_self() & 0xFFFF));
    return rand() % 2;
}

// Main function to create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
int create_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T **nfa_pi_list, size_t n, const char *hostname) {
    if (nfa_pi_list == NULL || hostname == NULL) {
        return -1; // Invalid input parameters
    }

    *nfa_pi_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfa_pi_list == NULL) {
        return -2; // Memory allocation failed
    }

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*nfa_pi_list)[i];

        pdu->RNTI = rand() % UINT_MAX;
        memset(pdu->RX_UE_INFORMATION_TAG, rand() % 256, sizeof(pdu->RX_UE_INFORMATION_TAG));

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

        if (resolve_hostname(hostname, pdu->IP_ADDRESS) != 0) {
            free(*nfa_pi_list);
            *nfa_pi_list = NULL;
            return -3; // DNS resolution failed
        }
    }

    return 0; // Success
}

// Example usage
int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int status;

    status = create_nfa_pi_list(&list, 10, "example.com");

    if (status != 0) {
        fprintf(stderr, "Error: %d\n", status);
        return status;
    }

    // Print the populated list
    for (size_t i = 0; i < 10; ++i) {
        printf("RNTI: %u, IP Address: ", list[i].RNTI);
        for (int j = 0; j < 16; ++j) {
            printf("%02x", list[i].IP_ADDRESS[j]);
            if ((j + 1) % 2 == 0 && j != 15) printf(":");
        }
        printf("\n");
    }

    free(list);
    return 0;
}
