        perror("Failed to allocate memory for array elements");
        return NULL;
    }

    dyn_array->size = 0;
    dyn_array->capacity = initial_capacity;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

void destroy_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        free(dyn_array->array);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
    }
}

int add_element(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity == 0 ? 1 : dyn_array->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1; // Cannot grow beyond max capacity
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*) realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1; // Failed to allocate memory
        }

        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    dyn_array->array[dyn_array->size++] = element;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

int remove_element(DynamicArray *dyn_array, size_t index) {
    pthread_mutex_lock(&dyn_array->lock);

    if (index >= dyn_array->size) {
        pthread_mutex_unlock(&dyn_array->lock);
        return -1; // Out of bounds
    }

    memmove(&dyn_array->array[index], &dyn_array->array[index + 1], (dyn_array->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dyn_array->size--;

    pthread_mutex_unlock(&dyn_array->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *dyn_array, size_t index) {
    if (index >= dyn_array->size) {
        return NULL; // Out of bounds
    }

    return &dyn_array->array[index];
}
```

### Key Points:
- **Concurrency**: Uses `pthread_mutex` for synchronization to ensure thread safety.
- **Dynamic Resizing**: The array doubles its capacity when full, up to a maximum of 10,000 elements.
- **Memory Management**: Proper allocation and deallocation using `malloc`, `realloc`, and `free`.
- **Error Handling**: Checks for out-of-bounds access and memory allocation failures.
- **Performance Considerations**: Balances between cache locality and heap usage by doubling the array size on demand.

This design ensures efficient handling of up to 10,000 elements while maintaining responsiveness under potential network or hardware constraints.']

