void insertAfterFirstOccurrence(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& ueList, 
                               const std::string& targetRNTIString, 
                               const NFAPI_CRC_INDICATION_PDU_T& newEntry) {
    static std::mutex mtx;  // Mutex for thread safety

    std::lock_guard<std::mutex> lock(mtx);  // Ensure thread-safe access
    bool found = false;

    for (auto it = ueList.begin(); it != ueList.end(); ++it) {
        if (std::to_string(it->RNTI) == targetRNTIString) {
            ueList.insert_after(it, newEntry);
            found = true;
            break;
        }
    }

    // If the target RNTI is not found, append to the end of the list
    if (!found) {
        ueList.push_front(newEntry);  // Insert at front, then rotate to back for O(1)
        std::rotate(ueList.begin(), --ueList.end(), ueList.end());
    }
}

