NFAPI_CRC_INDICATION_PDU_T* manage_nfa_crc_indication_list(unsigned int N) {
    if (N == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;

    srand(time(NULL)); // Seed random number generator

    for (unsigned int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
