        new_node->RNTI = rand() % 1000000; // Random RNTI for demonstration
        new_node->crcIndicationRel8.CRCFLAG = rand() % 2;
        new_node->next = NULL;

        pthread_mutex_lock(&list_mutex);
        head = insert_sorted(&head, new_node);
        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

NFAPI_CRC_INDICATION_PDU_T* insert_sorted(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    if (!(*head) || (*head)->RNTI > new_node->RNTI) {
        new_node->next = *head;
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        while (current->next && current->next->RNTI <= new_node->RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    return *head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
}

int compare_rnti(const void *a, const void *b) {
    unsigned long rnti_a = ((NFAPI_CRC_INDICATION_PDU_T *)a)->RNTI;
    unsigned long rnti_b = ((NFAPI_CRC_INDICATION_PDU_T *)b)->RNTI;
    return (rnti_a > rnti_b) - (rnti_a < rnti_b);
}

