    atomic_uint64_t crc_count;
    atomic_uint64_t success_count;
} RealTimeAnalytics;

DynamicArray* dynamic_array_create() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->array = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }

    arr->size = 0;
    atomic_store(&arr->count, 0);
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void dynamic_array_destroy(DynamicArray *arr) {
    if (arr) {
        free(arr->array);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

int dynamic_array_add(NFAPI_CRC_INDICATION_PDU_T item, DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);

    size_t current_count = atomic_load(&arr->count);
    if (current_count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Array is full
    }

    arr->array[current_count] = item;
    atomic_fetch_add(&arr->count, 1);

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int dynamic_array_get(DynamicArray *arr, size_t index, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&arr->lock);

    if (index >= atomic_load(&arr->count)) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // Index out of bounds
    }

    *item = arr->array[index];

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

