    uint64_t current_time = time(NULL);
    if (current_time - analytics->last_update_time >= 60) {
        // Calculate average CRC indication rate over the last minute
        pthread_mutex_lock(&arr->lock);
        double avg_rate = (double)atomic_load(&analytics->crc_count) / 60.0;
        atomic_store(&analytics->crc_count, 0); // Reset count for next minute
        pthread_mutex_unlock(&arr->lock);

        analytics->crc_rate_avg_last_minute = avg_rate;

        // Calculate success percentage over the last 10 seconds
        double success_percentage = (double)atomic_load(&analytics->success_count) / 
                                    ((double)(current_time - analytics->last_update_time >= 10 ? current_time - analytics->last_update_time - 10 : 1)) * 100.0;

        atomic_store(&analytics->success_count, 0); // Reset count for next period

        analytics->success_percentage_last_10_sec = success_percentage;

        analytics->last_update_time = current_time;
    }
}

void report_error(const char *message) {
