    pthread_exit((void *)0);
}

int manage_and_populate_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_pdus) {
    if (num_pdus > MAX_STRUCTS) return -1;

    pthread_t threads[num_pdus];
