        void *thread_result;
        pthread_join(threads[i], &thread_result);
        if ((intptr_t)thread_result == 1) {
            result = -1;
        }
    }

    return result;
}

void cleanup_cache(LRUCache *cache) {
    CacheEntry *current = cache->head;
    while (current != NULL) {
        CacheEntry *next = current->next;
        free(current);
        current = next;
    }
    free(cache);
}
