        'RNTI' => $user['RNTI'],
        'CRC_INDICATION_REL8_TAG' => ['CRCFLAG' => $crcFlag]
    ];
}

function synchronizeThreads($callback) {
    static $mutex;
    if (!$mutex) {
        $mutex = new \Mutex();
    }
    \Mutex::lock($mutex);
    try {
        call_user_func($callback);
    } finally {
        \Mutex::unlock($mutex);
    }
}

function retryWithExponentialBackoff($callable, $maxRetries = 5) {
    $attempt = 0;
    while ($attempt < $maxRetries) {
        try {
            return $callable();
        } catch (\Exception $e) {
            if (++$attempt >= $maxRetries) throw $e;

            // Exponential backoff delay
            usleep(pow(2, $attempt) * 100000);
        }
    }
}

function logError($message) {
    error_log($message); // Log error message for debugging and monitoring
}
