bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Implement validation logic
    return pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0;
}

void log_message(int level, const char *message) {
    // Implement logging based on environment variable configuration
    printf("Log [%d]: %s\n", level, message);
}

// Configuration
#define MAX_LIST_SIZE 1000

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node *head;
    size_t size;
    pthread_mutex_t lock;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool add_pdu_to_list(PduList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (validate_pdu(&pdu)) {
        srand(time(NULL)); // Seed for randomness
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

        pthread_mutex_lock(&list->lock);

        if (list->size >= MAX_LIST_SIZE) {
            log_message(1, "Maximum list size reached, cannot add new PDU.");
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        Node *new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            log_message(2, "Memory allocation failed for new PDU node.");
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        new_node->data = pdu;
        new_node->next = list->head;
        list->head = new_node;
        list->size++;

        pthread_mutex_unlock(&list->lock);
        log_message(3, "PDU added successfully.");
        return true;
    } else {
        log_message(4, "Validation failed for PDU.");
        return false;
    }
}

void clear_pdu_list(PduList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    log_message(3, "PDU list cleared.");
}

void destroy_pdu_list(PduList **list) {
    if (list && *list) {
        clear_pdu_list(*list);
        pthread_mutex_destroy(&(*list)->lock);
        free(*list);
        *list = NULL;
    }
}

// Usage
int main() {
    PduList *pdu_list = create_pdu_list();

    // Example of adding PDUs to the list in a thread-safe manner
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    add_pdu_to_list(pdu_list, pdu);

    // Clear and destroy the list when done
    clear_pdu_list(pdu_list);
    destroy_pdu_list(&pdu_list);

    return 0;
}
