#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    ALLOCATION_SUCCESS,
    ALLOCATION_PARTIAL,
    ALLOCATION_FAILURE
} AllocationStatus;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CRCList;

void log_allocation_details(const char* message) {
    // Placeholder for logging mechanism
    printf("%s\n", message);
}

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    log_allocation_details("CRCList created.");
    return list;
}

void resize_crc_list(CRCList* list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        log_allocation_details("Memory reallocation failed.");
        return;
    }

    list->capacity = new_capacity;
    for (size_t i = list->size; i < new_capacity; ++i) {
        new_data[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        new_data[i].RNTI = rand() % 1000;
        new_data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    list->data = new_data;

    pthread_mutex_unlock(&list->lock);
    log_allocation_details("CRCList resized.");
}

AllocationStatus allocate_crc_list(CRCList** list, size_t N) {
    if (N <= 0) return ALLOCATION_SUCCESS;

    *list = create_crc_list();
    if (!*list) return ALLOCATION_FAILURE;

    pthread_mutex_lock(&(*list)->lock);

    while ((*list)->size < N && (*list)->size < (*list)->capacity) {
        srand(time(NULL) + (*list)->size);
        (*list)->data[(*list)->size].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*list)->data[(*list)->size].RNTI = rand() % 1000;
        (*list)->data[(*list)->size].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        ++(*list)->size;
    }

    if ((*list)->size < N) {
        size_t new_capacity = (*list)->capacity * 2;
        resize_crc_list(*list, new_capacity);
    }

    pthread_mutex_unlock(&(*list)->lock);

    if ((*list)->size == N)
        return ALLOCATION_SUCCESS;
    else
        return ALLOCATION_PARTIAL;
}

void deallocate_crc_list(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
    log_allocation_details("CRCList deallocated.");
}

void bulk_insert(CRCList* list, size_t count) {
    if (!list || count == 0) return;

    pthread_mutex_lock(&list->lock);

    if (list->size + count > list->capacity) {
        while (list->size + count > list->capacity) {
            resize_crc_list(list, list->capacity * 2);
        }
    }

    for (size_t i = 0; i < count; ++i) {
        srand(time(NULL) + list->size + i);
        list->data[list->size].RX_UE_INFORMATION_TAG = rand() % 1000;
        list->data[list->size].RNTI = rand() % 1000;
        list->data[list->size].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        ++list->size;
    }

    pthread_mutex_unlock(&list->lock);
}

void bulk_delete(CRCList* list, size_t count) {
    if (!list || count == 0) return;

    pthread_mutex_lock(&list->lock);

    if (count > list->size) count = list->size;

    memmove(list->data, list->data + count, (list->size - count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size -= count;

    pthread_mutex_unlock(&list->lock);
}

int main() {
    CRCList* my_list;
    AllocationStatus status = allocate_crc_list(&my_list, 15);

    if (status == ALLOCATION_FAILURE) {
        printf("Allocation failed.\n");
        return 1;
    } else if (status == ALLOCATION_PARTIAL) {
        printf("Partial allocation. Some elements were not allocated due to resource constraints.\n");
    }

    bulk_insert(my_list, 5);
    bulk_delete(my_list, 3);

    deallocate_crc_list(my_list);
    return 0;
}
