### Rust Code: HTTP Client with Retry and Timeout

```rust
use reqwest::{Client, Error as ReqError};
use std::time::Duration;
use log::{info, error};
use tokio::time::timeout;

struct HttpClient {
    client: Client,
}

impl HttpClient {
    fn new() -> Self {
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert("User-Agent", "MyClient/1.0".parse().unwrap());

        HttpClient {
            client: Client::builder()
                .default_headers(headers)
                .timeout(Duration::from_secs(10))
                .build()
                .expect("Failed to build HTTP client"),
        }
    }

    async fn fetch(&self, url: &str) -> Result<String, ReqError> {
        for _ in 0..3 { // Retry mechanism
            match timeout(Duration::from_secs(5), self.client.get(url).send()).await {
                Ok(result) => match result {
                    Ok(response) if response.status().is_success() => {
                        let body = response.text().await?;
                        return Ok(body);
                    }
                    Ok(response) => error!("Request failed with status: {}", response.status()),
                    Err(e) => error!("Network error: {:?}", e),
                },
                Err(_) => error!("Request timed out"),
            };
        }

        Err(ReqError::new(reqwest::StatusCode::REQUEST_TIMEOUT, "All retries failed"))
    }
}

#[tokio::main]
async fn main() {
    env_logger::init(); // Setup logger

    let client = HttpClient::new();
    match client.fetch("https://example.com").await {
        Ok(response) => info!("Response: {}", response),
        Err(e) => error!("Failed to fetch data: {:?}", e),
    }
}
```

