    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // 0 or 1, randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (pthread_mutex_lock(&list->lock) != 0) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_element(LinkedList* list) {
    if (pthread_mutex_lock(&list->lock) != 0) return -1;

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    Node* temp = list->head;
    list->head = list->head->next;
    free(temp);
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(LinkedList* list) {
    if (!list) return;

    while (remove_element(list) == -3);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Garbage collection function to manage memory efficiently
void garbage_collect(LinkedList* list) {
    if (!list || list->size < 1000) return; // Threshold for triggering GC

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        // Reallocate or consolidate memory if necessary
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to initialize and test the linked list
void test_linked_list() {
    LinkedList* list = create_list();
    if (!list) return;

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { .RX_UE_INFORMATION_TAG = i, 
                                              .RNTI = i * 2,
                                              .CRC_INDICATION_REL8_TAG = i * 3,
                                              .CRCFLAG = rand() % 2 };

        if (add_element(list, element) != 0) {
            fprintf(stderr, "Error adding element\n");
        }
    }

    for (int i = 0; i < 5000; ++i) {
        remove_element(list);
    }

    garbage_collect(list);

    free_list(list);
}

// Example usage
int main() {
    test_linked_list();
    return 0;
}
```

### Key Points:
