    int packet_id;
    time_t timestamp;
    Status status;
    struct DataPacket* next;
} DataPacket;

typedef struct {
    DataPacket* head;
    pthread_mutex_t lock;
} PacketList;

// Function to initialize the linked list
void init_packet_list(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Thread-safe function to add a new packet
void add_packet(PacketList* list, int packet_id, time_t timestamp, Status status) {
    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) {
        perror("Failed to allocate memory for new packet");
        return;
    }
    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->status = status;

    pthread_mutex_lock(&list->lock);

    // Add the new packet at the beginning of the list
    new_packet->next = list->head;
    list->head = new_packet;

    pthread_mutex_unlock(&list->lock);
}

// Function to clean up expired packets periodically
void* cleanup_expired_packets(void* arg) {
    PacketList* list = (PacketList*)arg;
    time_t current_time, timeout_value;

    // Set the expiration timeout value in seconds
    timeout_value = 60;  // Example: 1 minute

    while (1) {
        sleep(timeout_value);

        pthread_mutex_lock(&list->lock);

        DataPacket* current = list->head;
        DataPacket* prev = NULL;

        current_time = time(NULL);

        while (current != NULL) {
            if (difftime(current_time, current->timestamp) > timeout_value) {
                if (prev == NULL) {
                    // Remove the head packet
                    list->head = current->next;
                    free(current);
                    current = list->head;
                } else {
                    prev->next = current->next;
                    free(current);
                    current = prev->next;
                }
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
    }
}

// Example function to simulate packet addition and cleanup
int main() {
    PacketList list;
    init_packet_list(&list);

    // Start the cleanup thread
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_expired_packets, &list) != 0) {
        perror("Failed to create cleanup thread");
        return EXIT_FAILURE;
    }

    // Simulate adding packets
    for (int i = 0; i < 10; ++i) {
        add_packet(&list, i, time(NULL), INTEGRITY_OK);
        sleep(2);  // Add a delay between packet additions
    }

    // Join the cleanup thread before exiting
    pthread_join(cleanup_thread, NULL);

    return EXIT_SUCCESS;
}
