    Node* current = list->head;
    while (current) {
        if (current->data.rnti == pdu->rnti) {
            pthread_rwlock_unlock(&list->lock);
            return 0; // Not unique
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);
    return 1; // Unique
}

void add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!is_rnti_unique(pdu, list)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    pthread_rwlock_wrlock(&list->lock);
    new_node->data = *pdu;
