    json_object_object_add(jobj, "rnti", json_object_new_int(pdu->rnti));
    // Add other fields...
    *json_str = strdup(json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY));
    json_object_put(jobj);
}

void free_list(List* list) {
    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    list->head = NULL;
    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
}

