#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG[16]; // 128-bit flag for uniqueness
} NFAPI_CRC_INDICATION_PDU_T;

EVP_CIPHER* createAndEncryptNFAPduList(int num_pdus, const EVP_CIPHER *cipher_type) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, EVP_CIPHER_iv_length(cipher_type));

    for (int i = 0; i < num_pdus; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand();
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand();

        // Generate a unique CRCFLAG using a cryptographic hash
        EVP_MD_CTX *mdctx;
        const EVP_MD *md = EVP_sha256();
        unsigned char md_value[EVP_MAX_MD_SIZE];
        if (EVP_DigestInit_ex(mdctx, md, NULL) <= 0) {
            fprintf(stderr, "Digest Init failed\n");
            free(pdu_list);
            return NULL;
        }

        if (EVP_DigestUpdate(mdctx, &pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T)) <= 0) {
            fprintf(stderr, "Digest Update failed\n");
            EVP_MD_CTX_destroy(mdctx);
            free(pdu_list);
            return NULL;
        }

        unsigned int md_len;
        if (EVP_DigestFinal_ex(mdctx, md_value, &md_len) <= 0) {
            fprintf(stderr, "Digest Final failed\n");
            EVP_MD_CTX_destroy(mdctx);
            free(pdu_list);
            return NULL;
        }

        EVP_MD_CTX_destroy(mdctx);

        memcpy(pdu_list[i].CRCFLAG, md_value, sizeof(pdu_list[i].CRCFLAG));
    }

    // Encrypt the list using selected cipher
    int len, ciphertext_len;
    unsigned char *ciphertext = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T) + EVP_MAX_BLOCK_LENGTH);
    if (!ciphertext) {
        fprintf(stderr, "Memory allocation for ciphertext failed\n");
        free(pdu_list);
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "EVP_CIPHER_CTX creation failed\n");
        free(ciphertext);
        free(pdu_list);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher_type, NULL, NULL, iv)) {
        fprintf(stderr, "Encryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        free(pdu_list);
        return NULL;
    }

    for (int i = 0; i < num_pdus; ++i) {
        if (1 != EVP_EncryptUpdate(ctx, ciphertext + len, &len, 
                                   (unsigned char *)&pdu_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            fprintf(stderr, "Encryption update failed\n");
            EVP_CIPHER_CTX_free(ctx);
            free(ciphertext);
            free(pdu_list);
            return NULL;
        }
    }

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ciphertext);
        free(pdu_list);
        return NULL;
    }
    ciphertext_len = len;

    memcpy(pdu_list, ciphertext, num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    EVP_CIPHER_CTX_free(ctx);
    free(ciphertext);

    return cipher_type; // Return the selected cipher mode
}
