// Custom allocator structure for memory pooling
typedef struct {
    size_t block_size;
    void* free_list;
    void** allocated_blocks;
    size_t total_blocks;
    size_t available_blocks;
} MemoryPool;

MemoryPool pool;

void initialize_pool(size_t element_count) {
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pool.block_size = block_size;
    pool.total_blocks = element_count;
    pool.available_blocks = element_count;

    pool.free_list = malloc(element_count * block_size);
    if (!pool.free_list) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        exit(EXIT_FAILURE);
    }

    memset(pool.free_list, 0, element_count * block_size);

    // Create an array of pointers for managing allocated blocks
    pool.allocated_blocks = malloc(element_count * sizeof(void*));
    if (!pool.allocated_blocks) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        free(pool.free_list);
        exit(EXIT_FAILURE);
    }

    void* current_ptr = pool.free_list;
    for (size_t i = 0; i < element_count - 1; ++i) {
        *(void**)((char*)current_ptr + block_size - sizeof(void*)) = (void*)((char*)current_ptr + block_size);
        current_ptr = *(void**)((char*)current_ptr + block_size - sizeof(void*));
    }
    *(void**)((char*)current_ptr + block_size - sizeof(void*)) = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool() {
    if (pool.available_blocks == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* block = (NFAPI_CRC_INDICATION_PDU_T*)pool.free_list;
    pool.free_list = *(void**)((char*)block + sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --pool.available_blocks;

    return block;
}

void deallocate_to_pool(NFAPI_CRC_INDICATION_PDU_T* block) {
    if (!block) return;

    *(void**)((char*)block + sizeof(NFAPI_CRC_INDICATION_PDU_T)) = pool.free_list;
    pool.free_list = (void*)block;
    ++pool.available_blocks;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_pdu_list(int max_retries, int* success_count) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for PDUs.\n");
        return NULL;
    }

    initialize_pool(MAX_ELEMENTS);

    int attempts = 0;
    int conflicts = 0;
    *success_count = 0;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool();
        if (!pdu) {
            fprintf(stderr, "Failed to allocate PDU from pool.\n");
            break;
        }

        int retry_count = 0;
        while (retry_count < max_retries) {
            pdu->RX_UE_INFORMATION_TAG = rand(); // Replace with actual function call
            pdu->RNTI = rand() % 100000; // Replace with logic to ensure uniqueness
            pdu->CRC_INDICATION_REL8_TAG = rand();
            pdu->CRCFLAG = rand() & 0x01;

            if (verify_structure(pdu)) { // Implement verification based on system requirements
                pdus[*success_count] = *pdu;
                (*success_count)++;
                break;
            }

            retry_count++;
            conflicts++;

            if (retry_count < max_retries) {
                deallocate_to_pool(pdu);
                pdu = allocate_from_pool();
            }
        }

        if (retry_count == max_retries) {
            fprintf(stderr, "Failed to create valid PDU after %d retries.\n", retry_count);
            deallocate_to_pool(pdu);
            break;
        }

        attempts++;
    }

    log_allocation_report(attempts, *success_count, conflicts);

    return pdus;
}

