// Define a structure to manage dynamic array operations
typedef struct {
    double *data;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
bool resize_dynamic_array(DynamicArray *arr, size_t new_capacity);
double calculate_average(const DynamicArray *arr);
void free_dynamic_array(DynamicArray *arr);

// Main function to process data from a network stream
double process_network_stream() {
    // Initial setup for the dynamic array
    const size_t initial_capacity = 1024;
    DynamicArray *numbers = create_dynamic_array(initial_capacity);
    if (!numbers) return -1.0; // Error handling

    double num;
    bool is_end_of_data = false;

    while (!is_end_of_data) {
        // Simulate reading a floating-point number from the network
        int read_result = scanf("%lf", &num);

        if (read_result != 1) { 
            // Handle end of data or input error
            char c;
            if ((c = getchar()) == '\n') {
                is_end_of_data = true; // End of stream detected
            } else {
                printf("Error reading number from network stream.\n");
                free_dynamic_array(numbers);
                return -1.0; // Error handling
            }
        } else {
            // Add the number to the dynamic array
            if (numbers->count == numbers->capacity) {
                // Resize the array if capacity is exceeded
                if (!resize_dynamic_array(numbers, numbers->capacity * 2)) {
                    free_dynamic_array(numbers);
                    return -1.0; // Error handling for memory allocation failure
                }
            }
            numbers->data[numbers->count++] = num;
        }
    }

    double average = calculate_average(numbers);

    // Cleanup
    free_dynamic_array(numbers);

    return average;
}

// Function implementations

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->data = malloc(initial_capacity * sizeof(double));
    if (!arr->data) {
        free(arr);
        return NULL;
    }

    arr->capacity = initial_capacity;
    arr->count = 0;

    return arr;
}

bool resize_dynamic_array(DynamicArray *arr, size_t new_capacity) {
    double *new_data = realloc(arr->data, new_capacity * sizeof(double));
    if (!new_data) return false;

    arr->data = new_data;
    arr->capacity = new_capacity;

    return true;
}

double calculate_average(const DynamicArray *arr) {
    if (arr->count == 0) return 0.0;

    double sum = 0.0;
    for (size_t i = 0; i < arr->count; ++i) {
        sum += arr->data[i];
    }

    return sum / arr->count;
}

void free_dynamic_array(DynamicArray *arr) {
    if (arr) {
        free(arr->data);
        free(arr);
    }
}
