// Utility function to implement exponential backoff with retries for transient failures.
int retryOperation(int (*operation)(void), int maxRetries, unsigned long baseDelay) {
    for (int attempt = 0; attempt < maxRetries; ++attempt) {
        if (operation() == 0) return 0;
        usleep(baseDelay * (1 << attempt) * 1000); // Exponential backoff
    }
    return -1;
}

