// Union-Find data structure for disjoint set operations.
typedef struct {
    int parent;
} UnionFindNode;

void unionFindInit(int n, UnionFindNode* uf) {
    for (int i = 0; i < n; ++i)
        uf[i].parent = i;
}

int findParent(int x, UnionFindNode* uf) {
    if (uf[x].parent != x)
        uf[x].parent = findParent(uf[x].parent, uf);
    return uf[x].parent;
}

void unionSets(int x, int y, UnionFindNode* uf) {
    int rootX = findParent(x, uf);
    int rootY = findParent(y, uf);
    if (rootX != rootY)
        uf[rootY].parent = rootX;
}

int areDisjoint(int a, int b, UnionFindNode* uf) {
    return findParent(a, uf) != findParent(b, uf);
}

// Main function to update page content and populate NFAPI_CRC_INDICATION_PDU_T structures.
