                       RETRY_DELAY_BASE)) {
        fprintf(stderr, "Failed to update page content after retries.\n");
        return;
    }
    end = clock();
    updateTime = ((double)(end - start) / CLOCKS_PER_SEC);

    // Fetch external data and populate NFAPI_CRC_INDICATION_PDU_T structures.
    start = clock();
    int rxUETag, rnti;
    if (fetchRXUEAndRNTI(&rxUETag, &rnti)) {
        fprintf(stderr, "Failed to fetch RX_UE_INFORMATION_TAG or RNTI.\n");
        return;
    }

    size_t pduCount = rand() % 10 + 1; // Random number of structures
    *arraySize = pduCount;
    *pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pduCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduArray) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (size_t i = 0; i < pduCount; ++i) {
        (*pduArray)[i].RX_UE_INFORMATION_TAG = rxUETag + i;
        (*pduArray)[i].RNTI = rnti + i;
        (*pduArray)[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        (*pduArray)[i].CRCFLAG = rand() % 2;
    }
    end = clock();
    processingTime = ((double)(end - start) / CLOCKS_PER_SEC);

    // Union-Find setup and disjoint check.
    UnionFindNode* uf = (UnionFindNode*)malloc(pduCount * sizeof(UnionFindNode));
    if (!uf) {
        fprintf(stderr, "Memory allocation failed for Union-Find.\n");
        free(*pduArray);
        return;
    }

    unionFindInit(pduCount, uf);

    // Example: Check disjointness between first two elements
    if (pduCount > 1 && areDisjoint(0, 1, uf)) {
        printf("Elements 0 and 1 are disjoint.\n");
    } else {
        printf("Elements 0 and 1 are not disjoint.\n");
    }

    free(uf);
    printf("Update Time: %.2f seconds\n", updateTime);
    printf("Processing Time: %.2f seconds\n", processingTime);
}
