        while (!isUnique) {
            isUnique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (dataObjects[j].transactionID == dataObjects[i].transactionID) {
                    dataObjects[i].transactionID = rand() % 100000 + 1;
                    isUnique = 0;
                    break;
