<?php

require 'vendor/autoload.php';

class ConfigLoader {
    private $config = [];

    public function __construct($configFile) {
        if (file_exists($configFile)) {
            $this->config = parse_ini_file($configFile);
        } else {
            throw new Exception("Configuration file not found.");
        }
    }

    public function get($key, $default = null) {
        return isset($this->config[$key]) ? $this->config[$key] : $default;
    }
}

class EnvironmentManager {
    private $envVars = [];

    public function __construct() {
        foreach ($_SERVER as $key => $value) {
            if (strpos($key, 'HTTP_') === 0) {
                $this->envVars[str_replace('HTTP_', '', strtoupper($key))] = urldecode($value);
            } else {
                $this->envVars[$key] = $value;
            }
        }
    }

    public function get($key, $default = null) {
        return isset($this->envVars[$key]) ? $this->envVars[$key] : getenv($key) ?: $default;
    }
}

try {
    $configLoader = new ConfigLoader(__DIR__ . '/config.ini');
    $environmentManager = new EnvironmentManager();

    // Example usage
    echo "Config Value: " . $configLoader->get('someKey') . "\n";
    echo "Environment Variable: " . $environmentManager->get('SOME_ENV_VAR') . "\n";

} catch (Exception $e) {
    error_log($e->getMessage());
}
