// Thread-safe memory allocation for the array of structures
NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_api_crc_array(size_t n, size_t budget_kb, int threshold, int* success_count) {
    const size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    const size_t max_structures = (budget_kb * 1024) / structure_size;

    if (n > max_structures) {
        log_error("Requested number of structures exceeds memory budget.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * structure_size);
    if (!array) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread safety
    int valid_count = 0;

    for (size_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand(); // Unique tag generation
        array[i].RNTI = rand() % 1024;           // Random RNTI

        int crcflag = rand() % 2; // Simulate random CRCFLAG (0 or 1)
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        if (!validate_crc_indication(crcflag, threshold)) {
            log_error("CRC indication validation failed for structure index.");
            continue;
        }

        pthread_mutex_lock(&lock);
        valid_count++;
        pthread_mutex_unlock(&lock);
    }

    *success_count = valid_count; // Return the number of successfully validated structures

    // Free memory if not all validations succeeded
    if (valid_count < n) {
        free(array);
        return NULL;
    }

    return array;  // Return the pointer to the allocated and populated array
}

// Example usage of the function
