['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int load_resource_bundle(const char* file_path, DynamicList** list) {
    FILE* file = fopen(file_path, "r");
    if (!file) return -1;

    int RX_UE_INFORMATION_TAG, RNTI;
    *list = create_list();
    if (!(*list)) {
        fclose(file);
        return -2;
    }

    while (fscanf(file, "%d %d", &RX_UE_INFORMATION_TAG, &RNTI) == 2) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu.RNTI = RNTI;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (add_pdu(*list, pdu) != 0) {
            destroy_list(*list);
            fclose(file);
            return -3;
        }
    }

    fclose(file);
    return count_items(*list);
}

int count_items(DynamicList* list) {
    if (!list) return -1;

    int count = 0;
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return count;
}
