typedef enum {
    ALLOCATOR_TYPE_SIMPLE,
    // Additional allocator types...
} AllocatorType;

typedef struct {
    size_t size;
    void* (*allocate)(size_t);
    void (*deallocate)(void*);
} MemoryPoolAllocator;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static volatile bool timeout_expired = false;
struct timespec start_time, end_time;

static MemoryPoolAllocator allocators[] = {
    { .size = sizeof(void*), .allocate = malloc, .deallocate = free },
    // Define other allocator types here...
};

void* get_allocator(AllocatorType type) {
    return &allocators[type];
}

bool check_timeout(long timeout_seconds) {
    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
    if (elapsed > timeout_seconds) {
        timeout_expired = true;
        return true;
    }
    return false;

void log_allocation_state(const char* state_message, NFAPI_CRC_INDICATION_PDU_T* array, size_t count) {
    printf("%s: Allocated %zu structures\n", state_message, count);
    for (size_t i = 0; i < count && i < MAX_STRUCTURES; ++i) {
        printf("Structure %zu - RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %d\n",
               i, array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

void notify_reallocation(const char* module_name, size_t new_size) {
    printf("Module '%s': Reallocated memory to %zu elements\n", module_name, new_size);
}

NFAPI_CRC_INDICATION_PDU_T* initialize_structures(size_t initial_count, AllocatorType allocator_type) {
    MemoryPoolAllocator allocator = *get_allocator(allocator_type);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)allocator.allocate(initial_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (size_t i = 0; i < initial_count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
    }

    log_allocation_state("Initial allocation", array, initial_count);
    return array;
}

void remove_duplicates(NFAPI_CRC_INDICATION_PDU_T* array, size_t* count) {
    if (!array || *count < 2) return;

    MemoryPoolAllocator allocator = *get_allocator(ALLOCATOR_TYPE_SIMPLE);

    for (size_t i = 0; i < *count - 1; ++i) {
        for (size_t j = i + 1; j < *count;) {
            if (array[i].RNTI == array[j].RNTI) {
                memmove(&array[j], &array[j + 1], (*count - j - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                --*count;
            } else {
                ++j;
            }
        }
    }

    size_t new_size = *count;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)allocator.allocate(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_array) {
        memcpy(new_array, array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        allocator.deallocate(array);
        array = new_array;
    }

    notify_reallocation("RNTI Deduplication", new_size);
}

void run_test_module(const char* module_name, void (*test_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    printf("Loading test module: %s\n", module_name);

    if (timeout_expired) return;

    test_func();

    printf("Resetting mocking library 'blueslip'\n");
    // Reset blueslip here...

    printf("Test function '%s' executed in module '%s'\n", __func__, module_name);
}

void manage_dynamic_array(AllocatorType allocator_type, long timeout_seconds) {
    pthread_mutex_lock(&lock);

    if (check_timeout(timeout_seconds)) return;

    size_t count = 1000; // Initial capacity
    NFAPI_CRC_INDICATION_PDU_T* array = initialize_structures(count, allocator_type);

    if (!array) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&lock);
        return;
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (count < MAX_STRUCTURES && !timeout_expired) {
        count += 1000; // Increase capacity

        if (check_timeout(timeout_seconds)) break;

        NFAPI_CRC_INDICATION_PDU_T* resized_array = 
            (NFAPI_CRC_INDICATION_PDU_T*)get_allocator(allocator_type)->allocate(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!resized_array) {
            perror("Failed to reallocate memory");
            break;
        }

        memcpy(resized_array, array, (count - 1000) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        remove_duplicates(resized_array, &count);

        get_allocator(allocator_type)->deallocate(array);
        array = resized_array;

        log_allocation_state("After reallocation", array, count);

        run_test_module("ExampleModule", (void (*)(NFAPI_CRC_INDICATION_PDU_T*))[](NFAPI_CRC_INDICATION_PDU_T* data) {
            // Example test function
        });
    }

    get_allocator(allocator_type)->deallocate(array);
    pthread_mutex_unlock(&lock);
}

int main() {
    manage_dynamic_array(ALLOCATOR_TYPE_SIMPLE, 10); // Timeout set to 10 seconds

    return 0;
}
