#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

// Structure definitions
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
    int RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG tag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Doubly-linked list node
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
};

typedef struct Node Node;

// List structure
typedef struct {
    Node* head;
    Node* tail;
} CRCList;

// Error codes
#define SUCCESS 0
#define MEM_ALLOC_FAIL -1
#define DUPLICATE_RNTI -2
#define RETRY_LIMIT_EXCEEDED -3
#define TIMEOUT_ERROR -4

// Function prototypes
CRCList* create_list();
int insert_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_pdu(CRCList* list, unsigned int rnti);
void cleanup_old_pdus(CRCList* list, time_t cutoff_time);
int fetch_and_insert_pdu(CRCList* list);
int validate_no_duplicates(CRCList* list);
void log_message(const char* message);

// Function implementations

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        log_message("Memory allocation failed for list");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    return list;
}

int insert_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for node");
        return MEM_ALLOC_FAIL;
    }

    new_node->data = pdu;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head != NULL) {
        list->head->prev = new_node;
    } else {
        list->tail = new_node;
    }

    list->head = new_node;
    return SUCCESS;
}

int remove_pdu(CRCList* list, unsigned int rnti) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }

            free(current);
            return SUCCESS;
        }
        current = current->next;
    }

    log_message("RNTI not found for removal");
    return -1; // RNTI not found
}

void cleanup_old_pdus(CRCList* list, time_t cutoff_time) {
    Node *current = list->head, *temp;

    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > cutoff_time) {
            temp = current;
            current = current->next;

            if (temp->prev != NULL) {
                temp->prev->next = temp->next;
            } else {
                list->head = temp->next;
            }

            if (temp->next != NULL) {
                temp->next->prev = temp->prev;
            } else {
                list->tail = temp->prev;
            }

            free(temp);
        } else {
            current = current->next;
        }
    }
}

int fetch_and_insert_pdu(CRCList* list) {
    // Simulate data fetching and retry mechanism
    int retries = 0;
    while (retries < 3) { // Retry up to 3 times
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Fetch data (simulate with random values)
        pdu.RNTI = rand() % 10000; // Random RNTI
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.tag.CRCFLAG = rand() % 2;
        pdu.timestamp = time(NULL);

        if (validate_no_duplicates(list, &pdu)) {
            return insert_pdu(list, pdu);
        }

        retries++;
    }

    log_message("Failed to fetch and insert PDU after retries");
    return RETRY_LIMIT_EXCEEDED;
}

int validate_no_duplicates(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* current = list->head;

    while (current != NULL) {
        if (current->data.RNTI == pdu->RNTI) {
            log_message("Duplicate RNTI detected");
            return DUPLICATE_RNTI;
        }
        current = current->next;
    }

    // Simulate external validation service call
    // Assuming it returns true for valid, false for duplicate
    bool is_valid = rand() % 2; // Randomly simulate validation result

    if (!is_valid) {
        log_message("External validation failed");
        return DUPLICATE_RNTI;
    }

    return SUCCESS;
}

void log_message(const char* message) {
    printf("%s\n", message);
}
