#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define ERROR_CODE_MEMORY (-1)
#define SUCCESS (0)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned char CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int cleanup_interval_minutes;
    time_t last_cleanup_time;
} DoublyLinkedList;

void log_event(const char *message) {
    printf("%s\n", message); // Simple logging mechanism
}

DoublyLinkedList* create_list(int cleanup_interval_minutes) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->cleanup_interval_minutes = cleanup_interval_minutes;
    time(&list->last_cleanup_time);

    log_event("List created successfully.");
    return list;
}

int insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    if (!list || !new_data) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_MEMORY;
    }

    Node** current = &list->head;

    while (*current && ((*current)->data.RNTI < new_data.RNTI)) {
        current = &(*current)->next;
    }

    if (*current && (*current)->data.RNTI == new_data.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_MEMORY; // RNTI already exists
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_MEMORY;
    }

    memcpy(new_node, &new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    time(&(new_node->data.timestamp));

    new_node->prev = *current;
    new_node->next = (*current)->next;

    if ((*current)) {
        (*current)->next = new_node;
    }

    if (!(*current)) {
        list->head = new_node; // Insert at head
    }

    log_event("Node inserted successfully.");
    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

int delete_node(DoublyLinkedList* list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    if (!list) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_MEMORY;
    }

    Node *current = list->head;

    while (current && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return ERROR_CODE_MEMORY; // Not found
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    }

    free(current);
    log_event("Node deleted successfully.");
    pthread_mutex_unlock(&list->lock);

    return SUCCESS;
}

void traverse_list(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) return;

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }
}

void cleanup_unused_nodes(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    time_t now, max_age;
    time(&now);
    max_age = now - (list->cleanup_interval_minutes * 60);

    Node **current = &list->head;
    while (*current) {
        if ((*current)->data.timestamp < max_age) {
            Node* to_delete = *current;
            *current = (*current)->next;

            if ((*current)) {
                (*current)->prev = to_delete->prev;
            }

            free(to_delete);
            log_event("Node cleaned up due to age.");
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void* periodic_cleanup(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;

    while (1) {
        sleep(60); // Check every minute
        cleanup_unused_nodes(list);
    }

    return NULL;
}

int save_list_to_file(DoublyLinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return ERROR_CODE_MEMORY;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    log_event("List saved to file.");
    return SUCCESS;
}

int load_list_from_file(DoublyLinkedList* list, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return ERROR_CODE_MEMORY;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T data;

    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insert_node(list, data);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);

    log_event("List loaded from file.");
    return SUCCESS;
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);

    log_event("List destroyed.");
}

int main() {
    DoublyLinkedList* list = create_list(10); // Cleanup every 10 minutes
    if (!list) return ERROR_CODE_MEMORY;

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, (void*)list);

    NFAPI_CRC_INDICATION_PDU_T data1 = {0x01, 1001, {0xde, 0xad, 0xbe, 0xef}, 1};
    insert_node(list, data1);

    save_list_to_file(list, "nfaapi_crc_list.bin");
    load_list_from_file(list, "nfaapi_crc_list.bin");

    destroy_list(list);
    pthread_join(cleanup_thread, NULL);

    return 0;
}
