// Helper function to find the largest integer in an array
int findLargest(int *array, int size) {
    if (size <= 0) return INT_MIN;
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// C function to process and query data
void processAndQueryData() {
    int *numbers = NULL;
    int capacity = 10;
    numbers = malloc(capacity * sizeof(int));

    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int size = 0;
    int number;
    printf("Enter integers (non-integer to stop): ");

    while (scanf("%d", &number) == 1) {
        if (size >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        numbers[size++] = number;
    }

    printf("Largest integer: %d\n", findLargest(numbers, size));

    free(numbers);
}
