using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DatabaseHelper
{
    private Dictionary<string, IDataReader> _cache = new Dictionary<string, IDataReader>();

    public IDataReader ExecuteParameterizedQuery(List<int> parameters, string connectionString, string sqlCommand)
    {
        var cacheKey = $"{connectionString}:{sqlCommand}:{string.Join(",", parameters)}";

        if (_cache.ContainsKey(cacheKey))
        {
            return _cache[cacheKey];
        }

        using (var connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();

                using (var command = new SqlCommand(sqlCommand, connection))
                {
                    for (int i = 0; i < parameters.Count; i++)
                    {
                        command.Parameters.AddWithValue($"@param{i}", parameters[i]);
                    }

                    var dataReader = command.ExecuteReader(CommandBehavior.CloseConnection);

                    _cache[cacheKey] = dataReader;

                    return dataReader;
                }
            }
            catch (SqlException ex)
            {
                Console.WriteLine("SQL Exception: " + ex.Message);
                throw; // Re-throw the exception for further handling if needed
            }
        }
    }
}
