#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

// Define the PACKET_DATA_PDU_T structure
typedef struct {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    uint8_t PROTOCOL_TYPE;
    uint32_t PACKET_SIZE;
} PACKET_DATA_PDU_T;

// Define configuration flags and criteria
#define MAX_PACKETS 1000
#define LOGGING_ENABLED true

// Function prototypes
void processNetworkPackets(PACKET_DATA_PDU_T packets[], size_t count, 
                           uint8_t protocolType, char sourceIPStart[16], 
                           char sourceIPEnd[16], uint32_t minPacketSize, 
                           uint32_t maxPacketSize);

bool isIpInRange(const char *ip, const char *start, const char *end);
void calculateThroughput(PACKET_DATA_PDU_T packets[], size_t count,
                         uint8_t protocolType, char sourceIPStart[16], 
                         char sourceIPEnd[16], uint32_t minPacketSize, 
                         uint32_t maxPacketSize);

int main() {
    // Example usage
    PACKET_DATA_PDU_T packets[MAX_PACKETS] = {
        {"192.168.1.1", "10.0.0.1", 6, 1500},
        {"192.168.1.2", "10.0.0.2", 17, 500},
        // Add more packet data as needed
    };

    processNetworkPackets(packets, 2, 6, "192.168.1.0", "192.168.1.255", 100, 2000);
    return 0;
}

void processNetworkPackets(PACKET_DATA_PDU_T packets[], size_t count, 
                           uint8_t protocolType, char sourceIPStart[16], 
                           char sourceIPEnd[16], uint32_t minPacketSize, 
                           uint32_t maxPacketSize) {

    clock_t start = clock();
    calculateThroughput(packets, count, protocolType, sourceIPStart, 
                        sourceIPEnd, minPacketSize, maxPacketSize);
    clock_t end = clock();

    double duration = (double)(end - start) / CLOCKS_PER_SEC * 1000;
    printf("Processing took %.2f milliseconds\n", duration);
}

bool isIpInRange(const char *ip, const char *start, const char *end) {
    // Simple comparison function assuming valid IPs
    return strcmp(ip, start) >= 0 && strcmp(ip, end) <= 0;
}

void calculateThroughput(PACKET_DATA_PDU_T packets[], size_t count,
                         uint8_t protocolType, char sourceIPStart[16], 
                         char sourceIPEnd[16], uint32_t minPacketSize, 
                         uint32_t maxPacketSize) {

    if (LOGGING_ENABLED) printf("Starting throughput calculation...\n");

    // Structures to hold processed packets and their counts
    typedef struct {
        char DESTINATION_IP[16];
        uint64_t totalThroughput;
    } ThroughputData;

    ThroughputData *throughputData = malloc(count * sizeof(ThroughputData));
    size_t throughputCount = 0;

    // Track unique packets based on SOURCE_IP, DESTINATION_IP, PROTOCOL_TYPE
    typedef struct {
        char sourceIP[16];
        char destIP[16];
        uint8_t protocol;
        bool used;
    } UniquePacketKey;

    UniquePacketKey *uniqueKeys = malloc(count * sizeof(UniquePacketKey));
    size_t uniqueCount = 0;

    for (size_t i = 0; i < count; ++i) {
        PACKET_DATA_PDU_T packet = packets[i];

        // Filter by protocol type, source IP range, and packet size
        if (packet.PROTOCOL_TYPE == protocolType &&
            isIpInRange(packet.SOURCE_IP, sourceIPStart, sourceIPEnd) &&
            packet.PACKET_SIZE >= minPacketSize && 
            packet.PACKET_SIZE <= maxPacketSize) {

            bool isDuplicate = false;

            // Check for duplicates
            for (size_t j = 0; j < uniqueCount; ++j) {
                if (!strcmp(uniqueKeys[j].sourceIP, packet.SOURCE_IP) &&
                    !strcmp(uniqueKeys[j].destIP, packet.DESTINATION_IP) &&
                    uniqueKeys[j].protocol == packet.PROTOCOL_TYPE) {

                    isDuplicate = true;
                    break;
                }
            }

            // If not a duplicate, process the packet
            if (!isDuplicate) {
                bool found = false;

                for (size_t j = 0; j < throughputCount; ++j) {
                    if (!strcmp(throughputData[j].DESTINATION_IP, packet.DESTINATION_IP)) {
                        throughputData[j].totalThroughput += packet.PACKET_SIZE;
                        found = true;
                        break;
                    }
                }

                if (!found) {
                    strcpy(throughputData[throughputCount].DESTINATION_IP, packet.DESTINATION_IP);
                    throughputData[throughputCount].totalThroughput = packet.PACKET_SIZE;
                    throughputCount++;
                }

                // Track the unique packet
                strcpy(uniqueKeys[uniqueCount].sourceIP, packet.SOURCE_IP);
                strcpy(uniqueKeys[uniqueCount].destIP, packet.DESTINATION_IP);
                uniqueKeys[uniqueCount].protocol = packet.PROTOCOL_TYPE;
                uniqueCount++;

                if (LOGGING_ENABLED) {
                    printf("Processed packet from %s to %s\n", 
                           packet.SOURCE_IP, packet.DESTINATION_IP);
                }
            }
        }
    }

    // Print throughput results
    for (size_t i = 0; i < throughputCount; ++i) {
        printf("Destination IP: %s, Total Throughput: %llu bytes\n",
               throughputData[i].DESTINATION_IP, throughputData[i].totalThroughput);
    }

    free(throughputData);
    free(uniqueKeys);
}
