#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI_VALUE 65535 // Define max RNTI value based on target system specifications
#define RATE_LIMIT_MAX_ITEMS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to either 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe memory allocation and logging
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging function
void log_error(const char *message) {
    pthread_mutex_lock(&mutex);
    fprintf(stderr, "ERROR: %s\n", message);
    pthread_mutex_unlock(&mutex);
}

// Function to generate a random RNTI within the valid range
unsigned short generate_valid_rnti() {
    return rand() % (MAX_RNTI_VALUE + 1);
}

// Function to create and populate an NFAPI_CRC_INDICATION_PDU_T list
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_ind_list(int n, int *allocated_count) {
    if (n > RATE_LIMIT_MAX_ITEMS) {
        log_error("Requested size exceeds rate limit.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand(); // Simulated tag
        list[i].RNTI = generate_valid_rnti();
        list[i].CRC_INDICATION_REL8_TAG = rand() % 1024; // Simulated CRC indication
        list[i].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    *allocated_count = n;

    pthread_mutex_unlock(&mutex);
    return list;
}

// Function to free the allocated NFAPI_CRC_INDICATION_PDU_T list
void free_nfa_crc_ind_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list != NULL) {
        free(list);
    }
}
