int findLargestInteger(int* arr, int size) {
    if (size == 0) return INT_MIN;

    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void readIntegersAndFindLargest() {
    char buffer[256];
    int *array = NULL;
    size_t arraySize = 0;
    const size_t increment = 100;

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (arraySize + increment > MAX_SIZE || 
            (array == NULL ? 0 : ((long)arraySize * sizeof(int) + increment * sizeof(int))) > MEMORY_LIMIT) {
            printf("No integers provided\n");
            free(array);
            return;
        }

        int tempArray[increment];
        char *token = strtok(buffer, " \n");

        for (int i = 0; i < increment && token != NULL; i++) {
            char* endPtr;
            long value = strtol(token, &endPtr, 10);

            if (*endPtr == '\0' && value <= INT_MAX && value >= INT_MIN) {
                tempArray[i] = (int)value;
                arraySize++;
            }

            token = strtok(NULL, " \n");
        }

        int* newArray = realloc(array, arraySize * sizeof(int));
        if (!newArray) {
            free(array);
            printf("No integers provided\n");
            return;
        }

        array = newArray;

        for (int i = 0; i < increment && arraySize > i; i++) {
            array[arraySize - increment + i] = tempArray[i];
        }

        if (token == NULL) break; // No more data to read
    }

    int largest = findLargestInteger(array, arraySize);

    if (largest == INT_MIN) {
        printf("No integers provided\n");
    } else {
        printf("%d\n", largest);
    }

    free(array);
}

int main() {
    readIntegersAndFindLargest();
    return 0;
}
