#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_RNTI 65536

typedef struct {
    unsigned int rx_ue_information_tag;
    unsigned short rnti;
    struct {
        unsigned char crcflag:1; // Randomly set CRC flag
    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    pthread_rwlock_t lock;
} PduList;

// Function to create a new PduList
PduList* create_pdu_list() {
    PduList *list = (PduList *)malloc(sizeof(PduList));
    list->items = NULL;
    list->count = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

// Function to add a new item to the PduList
int add_pdu_item(PduList *list) {
    pthread_rwlock_wrlock(&list->lock);

    size_t new_count = list->count + 1;
    NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->items, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_items) {
        pthread_rwlock_unlock(&list->lock);
        return -1; // Memory allocation error
    }

    new_items[list->count].rx_ue_information_tag = rand(); // Example value
    new_items[list->count].rnti = (unsigned short)(rand() % MAX_RNTI); // Random RNTI
    new_items[list->count].crc_indication_rel8_tag.crcflag = rand() & 1; // Set CRC flag randomly

    list->items = new_items;
    list->count = new_count;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Function to free the PduList
void destroy_pdu_list(PduList *list) {
    if (list) {
        pthread_rwlock_wrlock(&list->lock);
        free(list->items);
        pthread_rwlock_unlock(&list->lock);
        pthread_rwlock_destroy(&list->lock);
        free(list);
    }
}

// Function to load configuration from a file
int load_config(const char *file_path, PduList *list) {
    FILE *file = fopen(file_path, "r");
    if (!file) return -1;

    int items_to_add;
    fscanf(file, "%d", &items_to_add);

    for (int i = 0; i < items_to_add; ++i) {
        add_pdu_item(list);
    }

    fclose(file);
    return 0;
}

// Function to perform DNS resolution
int resolve_hostname(const char *hostname, u_char ip_address[4]) {
    struct hostent *host_info = gethostbyname(hostname);
    if (!host_info) return -1;

    memcpy(ip_address, host_info->h_addr_list[0], sizeof(u_char) * 4);
    return 0;
}

// Function to limit process capabilities (platform-specific, example for Linux)
int limit_capabilities() {
#ifdef __linux__
    // Example: Drop root privileges if needed
    if (getuid() == 0) {
        if (setuid(geteuid()) != 0) return -1;
    }
#endif
    return 0;
}

// Main function demonstrating usage
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file_path> <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    PduList *pdu_list = create_pdu_list();
    if (load_config(argv[1], pdu_list) != 0) {
        fprintf(stderr, "Error loading configuration\n");
        destroy_pdu_list(pdu_list);
        return EXIT_FAILURE;
    }

    u_char ip_address[4];
    if (resolve_hostname(argv[2], ip_address) != 0) {
        fprintf(stderr, "DNS resolution failed for hostname: %s\n", argv[2]);
        destroy_pdu_list(pdu_list);
        return EXIT_FAILURE;
    }

    printf("Resolved IP: %.3u.%.3u.%.3u.%.3u\n",
           ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    if (limit_capabilities() != 0) {
        fprintf(stderr, "Failed to limit process capabilities\n");
        destroy_pdu_list(pdu_list);
        return EXIT_FAILURE;
    }

    printf("Total items in bundle: %zu\n", pdu_list->count);

    destroy_pdu_list(pdu_list);
    return EXIT_SUCCESS;
}
