    PDCP_CONTEXT context;
} LTE_PDCP_RX_PDU;

typedef struct {
    LTE_PDCP_RX_PDU *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize the dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->pdus = (LTE_PDCP_RX_PDU*)malloc(MAX_PDUS * sizeof(LTE_PDCP_RX_PDU));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = MAX_PDUS;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Function to add a PDU to the dynamic array
int add_pdu(DynamicArray *array, LTE_PDCP_RX_PDU pdu) {
    if (pthread_mutex_lock(&array->lock) != 0) return -1;

    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Array is full
    }

    array->pdus[array->count++] = pdu;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to iterate and print PDUs
void print_pdus(const DynamicArray *array) {
    if (pthread_mutex_lock((pthread_mutex_t*)&array->lock) != 0) return;

    for (size_t i = 0; i < array->count; ++i) {
        printf("PDU %zu - Header: %u, SN: %u, RLC Status SN: %u\n",
               i,
               array->pdus[i].header.some_field,
               array->pdus[i].pdcp_sn,
               array->pdus[i].context.sn);
    }

    pthread_mutex_unlock((pthread_mutex_t*)&array->lock);
}

// Function to free the dynamic array
void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    pthread_mutex_destroy(&array->lock);
    free(array->pdus);
    free(array);
}

