void log_message(const char* message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

INTERFACE_CONFIG* initialize_interfaces(int count) {
    if (count <= 0 || count > MAX_INTERFACES) {
        log_message("Invalid number of interfaces requested.");
        return NULL;
    }

    INTERFACE_CONFIG* configs = malloc(count * sizeof(INTERFACE_CONFIG));
    if (!configs) {
        log_message("Memory allocation failed for interface configurations.");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        configs[i].id = i + 1;
        configs[i].buffer_size = INITIAL_BUFFER_SIZE;
        pthread_mutex_init(&configs[i].lock, NULL);
    }

    log_message("Interface configurations initialized successfully.");
    return configs;
}

void adjust_buffer_sizes(INTERFACE_CONFIG* configs, int count, size_t new_size) {
    if (!configs) return;

    for (int i = 0; i < count; ++i) {
        pthread_mutex_lock(&configs[i].lock);
        configs[i].buffer_size = new_size;
        pthread_mutex_unlock(&configs[i].lock);
        log_message("Buffer size adjusted for interface.");
    }
}

void monitor_and_adjust(INTERFACE_CONFIG* configs, int count) {
