    }
}

void free_interfaces(INTERFACE_CONFIG* configs, int count) {
    if (!configs) return;

    for (int i = 0; i < count; ++i) {
        pthread_mutex_destroy(&configs[i].lock);
    }

    free(configs);
    log_message("Interface configurations freed.");
}

// Example of external API integration
