    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
    unsigned int crcFlagCount;
} CRCIndicatorManager;

CRCIndicatorManager* create_crc_indicator_manager(size_t initialCapacity) {
    CRCIndicatorManager *manager = (CRCIndicatorManager*)malloc(sizeof(CRCIndicatorManager));
    if (!manager) return NULL; // Graceful degradation

    manager->array = NULL;
    manager->used = 0;
    manager->capacity = initialCapacity;

    if (initialCapacity > 0) {
        manager->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initialCapacity);
        if (!manager->array) { // Handle allocation failure
            free(manager);
            return NULL;
        }
    }

    manager->crcFlagCount = 0;

    srand((unsigned int)time(NULL)); // Seed random number generator

    return manager;
}

void insert_crc_indicator(CRCIndicatorManager *manager, uint32_t rxInfoTag, int rnti) {
    if (manager->used == manager->capacity) {
        size_t newCapacity = manager->capacity == 0 ? 1 : manager->capacity * 2; // Double the capacity
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (!newArray) {
            printf("Memory allocation failed\n"); // Log failure
            return;
        }
        manager->array = newArray;
        manager->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {rnti, rxInfoTag, {rand() % 2}}; // Randomly set CRCFLAG

    manager->array[manager->used++] = pdu;

    if (pdu.crcIndicationRel8Tag.CRCFLAG) {
        manager->crcFlagCount++;
    }
}

unsigned int get_crc_flag_count(CRCIndicatorManager *manager) {
    return manager->crcFlagCount;
}

void free_crc_indicator_manager(CRCIndicatorManager *manager) {
    if (!manager) return;

    free(manager->array);
    free(manager);
}
