    timestamp_t *timestamps = malloc(max_log_messages * sizeof(timestamp_t));
    log_level_t *levels = malloc(max_log_messages * sizeof(log_level_t));
    log_message_t *log_queue = calloc(max_log_messages, sizeof(log_message_t));

    if (!timestamps || !levels || !log_queue) {
