} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_REQUESTS 10
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

typedef struct {
    long *offsets;
    int size_offsets;
    int *keys;
    int size_keys;
    struct record_t {
        int value;
    } *records;
    int size_records;
} data_struct;

pthread_mutex_t request_lock = PTHREAD_MUTEX_INITIALIZER;
int current_requests = 0;

void init_openssl() {
    EVP_add_cipher(&aes_128_cbc);
    EVP_add_digest(&md5);
    EVP_add_cipher(&camellia_256_ecb);
    EVP_add_digest(&sha256);
    EVP_add_signctx(&rsa_pss, &sha256);
}

data_struct* initialize_data(int size) {
    data_struct *ds = (data_struct *)malloc(sizeof(data_struct));
    if (!ds) return NULL;

    ds->offsets = (long*)malloc(size * sizeof(long));
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->records = (struct record_t*)malloc(size * sizeof(struct record_t));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->size_offsets = size;
    ds->size_keys = size;
    ds->size_records = size;

    for (int i = 0; i < size; ++i) {
        ds->offsets[i] = rand() % 100;
        ds->keys[i] = rand() % 256;
        ds->records[i].value = RANDOM_RANGE_MIN + rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1);
    }

    return ds;
}

void cleanup_data(data_struct *ds) {
    if (!ds) return;

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(int num_pdus, int* error) {
    if (num_pdus <= 0) {
        *error = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        *error = -2;
        return NULL;
    }

    for (int i = 0; i < num_pdus; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdu_list[i].RNTI = rand() % 256;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 10;
        RAND_bytes(&pdu_list[i].CRCFLAG, sizeof(pdu_list[i].CRCFLAG));
    }

    *error = 0;
    return pdu_list;
}

void process_requests(data_struct* ds, NFAPI_CRC_INDICATION_PDU_T** pdus, int num_pdus) {
    pthread_mutex_lock(&request_lock);

    if (current_requests >= MAX_REQUESTS) {
        printf("Max requests reached.\n");
        pthread_mutex_unlock(&request_lock);
        return;
    }

    current_requests++;

    for (int i = 0; i < num_pdus; ++i) {
        // Simulate processing
        pdus[i]->RX_UE_INFORMATION_TAG += ds->keys[i % ds->size_keys];
        printf("Processing PDU: RX_TAG=%d, RNTI=%d\n", pdus[i]->RX_UE_INFORMATION_TAG, pdus[i]->RNTI);
    }

    current_requests--;
    pthread_mutex_unlock(&request_lock);
}

int main() {
    int error;
    data_struct *ds = initialize_data(100);
    if (!ds) {
        fprintf(stderr, "Failed to allocate memory for data structures.\n");
        return 1;
    }

    init_openssl();

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_pdu_list(10, &error);
    if (error != 0 || !pdu_list) {
        fprintf(stderr, "Failed to create PDU list.\n");
        cleanup_data(ds);
        return 1;
    }

    process_requests(ds, pdu_list, 10);

    free(pdu_list);
    cleanup_data(ds);

    return 0;
}
