    clock_t end_time = clock();
    double elapsed_time = ((double)(end_time - metrics->start_time)) / CLOCKS_PER_SEC;
    printf("%s | Time: %.2f seconds | Memory Usage: %zu bytes | Errors: %d\n", message, elapsed_time, metrics->memory_usage, metrics->error_count);
