#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define the UEState structure
typedef struct {
    int ue_id;
    time_t timestamp;
    int status_flag;
} UEState;

// Logging levels
enum { DEBUG, INFO, ERROR };

// External logging function (stub for demonstration)
void log_message(enum { DEBUG, INFO, ERROR } level, const char *message) {
    // Placeholder for actual logging implementation
    printf("[%d] %s\n", level, message);
}

// Define the dynamic array structure with a mutex for thread safety
typedef struct {
    UEState **entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray *array) {
    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->entries = malloc(array->capacity * sizeof(UEState *));
    if (!array->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->entries[i]);
    }
    free(array->entries);
    pthread_mutex_destroy(&array->lock);
}

// Function to add or update an entry
void add_or_update_entry(DynamicArray *array, int ue_id, time_t timestamp, int status_flag, enum { DEBUG, INFO, ERROR } log_level) {
    pthread_mutex_lock(&array->lock);

    // Check if UE ID already exists and update
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i]->ue_id == ue_id) {
            array->entries[i]->timestamp = timestamp;
            array->entries[i]->status_flag = status_flag;
            log_message(log_level, "Updated UEState");
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    // If not found, add a new entry
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->entries = realloc(array->entries, array->capacity * sizeof(UEState *));
        if (!array->entries) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&array->lock);
            exit(EXIT_FAILURE);
        }
    }

    UEState *new_entry = malloc(sizeof(UEState));
    new_entry->ue_id = ue_id;
    new_entry->timestamp = timestamp;
    new_entry->status_flag = status_flag;
    array->entries[array->count++] = new_entry;

    log_message(log_level, "Added UEState");
    pthread_mutex_unlock(&array->lock);
}

// Function to retrieve the latest state for a given UE ID
UEState *get_latest_state(DynamicArray *array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i]->ue_id == ue_id) {
            UEState *result = array->entries[i];
            pthread_mutex_unlock(&array->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return NULL;
}

// Example usage
int main() {
    DynamicArray array;
    init_dynamic_array(&array);

    add_or_update_entry(&array, 1, time(NULL), 0, INFO);
    UEState *state = get_latest_state(&array, 1);
    if (state) {
        printf("UE ID: %d, Timestamp: %ld, Status Flag: %d\n", state->ue_id, state->timestamp, state->status_flag);
    }

    free_dynamic_array(&array);
    return 0;
}
```

