['```java
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final ConcurrentHashMap<String, ServiceInstance> instances = new ConcurrentHashMap<>();
    private final LoadMonitor loadMonitor;
    private final ConfigurationStore configStore;

    public ServiceManager(LoadMonitor loadMonitor, ConfigurationStore configStore) {
        this.loadMonitor = loadMonitor;
        this.configStore = configStore;
    }

    public void start() {
        scheduler.scheduleAtFixedRate(this::adjustServiceInstances, 0, 10, TimeUnit.SECONDS);
    }

    private void adjustServiceInstances() {
        double currentLoad = loadMonitor.getCurrentLoad();
        int desiredInstanceCount = calculateDesiredInstanceCount(currentLoad);

        for (int i = 0; i < instances.size(); i++) {
            if (i >= desiredInstanceCount) {
                shutdownAndRemoveInstance(instances.keySet().toArray(new String[0])[i]);
            }
        }

        while (instances.size() < desiredInstanceCount) {
            String configKey = generateUniqueConfigKey();
            ServiceInstance newInstance = new ServiceInstance(configStore.loadConfiguration(configKey));
            instances.put(configKey, newInstance);
            startAndMonitorInstance(newInstance);
        }

        logger.info("Adjusted service instances to: " + desiredInstanceCount);
    }

    private int calculateDesiredInstanceCount(double load) {
        return (int) Math.ceil(load / 10.0); // Example scaling logic
    }

    private String generateUniqueConfigKey() {
        Random random = new Random();
        while (true) {
            String configKey = UUID.randomUUID().toString();
            if (!instances.containsKey(configKey)) {
                return configKey;
            }
        }
    }

    private void startAndMonitorInstance(ServiceInstance instance) {
        CompletableFuture.runAsync(() -> {
            try {
                instance.start();
                monitorInstance(instance);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Failed to start service instance", e);
                shutdownAndRemoveInstance(instance.getConfigKey());
            }
        });
    }

    private void monitorInstance(ServiceInstance instance) {
        ScheduledExecutorService monitoringScheduler = Executors.newSingleThreadScheduledExecutor();
        monitoringScheduler.scheduleAtFixedRate(() -> {
            if (!instance.isHealthy()) {
                logger.warning("Instance " + instance.getConfigKey() + " is unhealthy. Restarting...");
                shutdownAndRemoveInstance(instance.getConfigKey());
                startAndMonitorInstance(instance);
            }
        }, 0, 5, TimeUnit.SECONDS);
    }

    private void shutdownAndRemoveInstance(String configKey) {
        ServiceInstance instance = instances.remove(configKey);
        if (instance != null) {
            try {
                instance.stop();
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Failed to stop service instance", e);
            }
        }
    }

    public void shutdown() {
        scheduler.shutdownNow();
        for (ServiceInstance instance : instances.values()) {
            try {
                instance.stop();
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error stopping service instance during shutdown", e);
            }
        }
    }

    // Placeholder classes to illustrate the concept
    private static class LoadMonitor {
        public double getCurrentLoad() {
            // Simulate load retrieval
            return new Random().nextDouble() * 100;
        }
    }

    private static class ConfigurationStore {
        public Map<String, String> loadConfiguration(String configKey) {
            // Simulate configuration loading
            return Collections.singletonMap("config", "value");
        }
    }

    private static class ServiceInstance {
        private final String configKey;

        public ServiceInstance(Map<String, String> config) {
            this.configKey = UUID.randomUUID().toString();
        }

        public void start() throws Exception {
            // Simulate service startup
        }

        public boolean isHealthy() {
            // Simulate health check
            return new Random().nextBoolean();
        }

        public void stop() throws Exception {
            // Simulate service shutdown
        }

        public String getConfigKey() {
            return configKey;
        }
    }
}
```

