// Cargo.toml
[package]
name = "http_client_lib"
version = "0.1.0"
edition = "2021"

[dependencies]
reqwest = { version = "0.11", features = ["json", "stream"] }
tokio = { version = "1", features = ["full"] }
log = "0.4"
tracing = "0.1"
hyper = { version = "0.14", optional = true }
tower = "0.4"

[features]
http2 = ["reqwest/http2-support"]

# lib.rs
use log::{info, warn};
use std::time::Duration;
use reqwest::{Client as ReqwestClient, ClientBuilder, Error as ReqwestError, Response, Method};
use tracing::{instrument, Span};

pub struct HttpClient {
    client: ReqwestClient,
}

impl HttpClient {
    pub fn create_http_client(timeout: Option<Duration>, max_connections: usize) -> Self {
        let mut builder = ClientBuilder::new();

        if let Some(t) = timeout {
            builder = builder.timeout(t);
        }

        let client = builder
            .connection_limit(max_connections)
            .build()
            .expect("Failed to build Reqwest client");

        HttpClient { client }
    }

    #[instrument]
    pub async fn send_request(&self, method: Method, url: &str, headers: Option<Vec<(String, String)>>, body: Option<String>, query_params: Option<&[(String, String)]>) -> Result<Response, ReqwestError> {
        let mut request = self.client.request(method.clone(), url);

        if let Some(headers) = headers {
            for (key, value) in headers {
                request = request.header(key.as_str(), value);
            }
        }

        if let Some(params) = query_params {
            request = request.query_pairs(params);
        }

        if let Some(body_content) = body {
            request = request.body(body_content);
        }

        info!("Sending request to {}", url);

        let response = request.send().await?;

        trace!(Span::current(), "Received response with status: {}", response.status());

        Ok(response)
    }
}

#[cfg(feature = "http2")]
mod http2_support {
    use hyper::{Client, Body};

    pub struct Http2Client {
        client: Client<Body>,
    }

    impl Http2Client {
        pub fn create_http2_client() -> Self {
            let client = Client::new();
            Http2Client { client }
        }

        // Additional HTTP/2 specific methods
    }
}

// main.rs (for testing purposes)
#[tokio::main]
async fn main() {
    log::set_max_level(log::LevelFilter::Info);
    tracing_subscriber::fmt::init();

    let http_client = HttpClient::create_http_client(Some(Duration::from_secs(10)), 100);

    match http_client.send_request(Method::GET, "https://httpbin.org/get", None, None, Some(&[("key".to_string(), "value".to_string())])).await {
        Ok(response) => {
            let body = response.text().await.unwrap();
            println!("Response Body: {}", body);
        }
        Err(e) => warn!("Request failed with error: {:?}", e),
    }
}
```

This Rust library provides a modular HTTP client that supports both synchronous and asynchronous operations using `reqwest` and optional `hyper` for HTTP/2 support. It includes customizable settings, logging, and metrics via the `log` and `tracing` crates.']

