['Below is a C++ implementation that provides a modular system for dynamically selecting and executing character attacks with specified probabilities and a global cooldown mechanism.

```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <unordered_map>

class AttackManager {
public:
    enum AttackType { ATTACK_A, ATTACK_B };

private:
    std::mutex globalMutex;
    std::mutex attackMutex;
    bool isGlobalCooldown = false;
    const int cooldownDurationSeconds = 9;

    struct Character {
        float probabilityA;
        std::chrono::steady_clock::time_point lastAttackTime;

        Character(float probA = 0.7f) : probabilityA(probA), lastAttackTime(std::chrono::steady_clock::now() - 
            std::chrono::seconds(cooldownDurationSeconds + 1)) {}
    };

    std::unordered_map<int, Character> characterInstances;

public:
    AttackManager() {
        // Initialization can be expanded for more complex setups
    }

    void addCharacter(int characterId) {
        std::lock_guard<std::mutex> lock(attackMutex);
        characterInstances[characterId] = Character();
    }

    void executeAttack(int characterId) {
        std::unique_lock<std::mutex> globalLock(globalMutex);

        auto& character = characterInstances[characterId];

        // Global cooldown check
        if (isGlobalCooldown && 
            std::chrono::steady_clock::now() - character.lastAttackTime < std::chrono::seconds(cooldownDurationSeconds)) {
            return;
        }

        isGlobalCooldown = true;

        globalLock.unlock();  // Release the global lock to allow other characters to attempt attacks

        // Determine attack type based on probability
        float randValue = getRandomFloat();
        AttackType selectedAttack = (randValue < character.probabilityA) ? ATTACK_A : ATTACK_B;

        std::cout << "Character " << characterId << " executed " << 
            (selectedAttack == ATTACK_A ? "Attack A" : "Attack B") << std::endl;

        // Update last attack time
        character.lastAttackTime = std::chrono::steady_clock::now();

        // Reacquire global lock to reset cooldown
        globalLock.lock();
        isGlobalCooldown = false;
    }

private:
    float getRandomFloat() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_real_distribution<> dis(0, 1);
        return dis(gen);
    }
};

int main() {
    AttackManager manager;
    manager.addCharacter(1);
    manager.addCharacter(2);

    std::thread t1([&manager](){ manager.executeAttack(1); });
    std::thread t2([&manager](){ manager.executeAttack(2); });

    t1.join();
    t2.join();

    return 0;
}
```

This code provides a system for executing attacks with probability management and global cooldown synchronization. It uses mutexes to handle concurrency safely, ensuring that no two attacks from different characters happen simultaneously within the specified cooldown period. The design allows easy extension by adding more attack types or modifying character classes.']

