['Below is a C code example implementing the described symmetric encryption initialization using PBKDF2 for key derivation and HKDF for further key and IV extraction. We will use OpenSSL's EVP library to facilitate this.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>

#define SALT_SIZE 16
#define ITERATIONS 100000 // Default iterations, can be adjusted for security/performance trade-off
#define KEY_LENGTH 32     // AES-256 key length in bytes
#define IV_LENGTH 16      // AES block size for initialization vector

typedef struct {
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    size_t derived_key_len;
    unsigned char encryption_key[EVP_MAX_KEY_LENGTH];
    size_t encryption_key_len;
    unsigned char iv[IV_LENGTH];
} CipherContext;

int initialize_cipher(const char *passphrase, const unsigned char *salt, int salt_length, int iterations, CipherContext *ctx) {
    if (!ctx || !passphrase || salt_length > SALT_SIZE) return -1;

    // Allocate memory for derived key
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    size_t derived_key_len = EVP_MAX_KEY_LENGTH;

    // Use PBKDF2 with SHA-256 to derive a key from the passphrase and salt
    if (!PKCS5_PBKDF2_HMAC((const char *)passphrase, strlen(passphrase), 
                           salt, salt_length, iterations,
                           EVP_sha256(), derived_key_len, derived_key)) {
        fprintf(stderr, "Error in PBKDF2\n");
        return -1;
    }

    ctx->derived_key_len = derived_key_len;
    memcpy(ctx->derived_key, derived_key, derived_key_len);

    // Use HKDF to derive encryption key and IV
    const EVP_MD *md = EVP_sha256();
    if (EVP_PKEY_derive_init(&ctx->pkey_ctx) <= 0 ||
        EVP_PKEY_derive_set_peer(&ctx->pkey_ctx, &derived_pkey) <= 0 ||
        EVP_PKEY_derive(&ctx->pkey_ctx,
                        ctx->encryption_key, &ctx->encryption_key_len,
                        derived_key, derived_key_len,
                        md) <= 0) {
        fprintf(stderr, "Error in HKDF\n");
        return -1;
    }

    // Derive the IV
    if (RAND_bytes(ctx->iv, IV_LENGTH) != 1) {
        fprintf(stderr, "Random number generation error for IV\n");
        return -1;
    }

    return 0; // Success
}

void cleanup_cipher(CipherContext *ctx) {
    if (!ctx) return;

    // Zero out the sensitive data in memory to prevent leaks
    OPENSSL_cleanse(ctx->derived_key, ctx->derived_key_len);
    OPENSSL_cleanse(ctx->encryption_key, KEY_LENGTH);
    OPENSSL_cleanse(ctx->iv, IV_LENGTH);

    EVP_PKEY_CTX_free(ctx->pkey_ctx);
}

int main() {
    CipherContext ctx = {0};
    unsigned char salt[SALT_SIZE];
    if (RAND_bytes(salt, SALT_SIZE) != 1) {
        fprintf(stderr, "Failed to generate random salt\n");
        return -1;
    }

    const char *passphrase = "securepassword";

    // Initialize cipher
    if (initialize_cipher(passphrase, salt, SALT_SIZE, ITERATIONS, &ctx) != 0) {
        fprintf(stderr, "Cipher initialization failed\n");
        return -1;
    }

    printf("Encryption key and IV initialized successfully.\n");

    // Cleanup resources
    cleanup_cipher(&ctx);

    return 0;
}
```

### Key Points:
- **PBKDF2 with SHA-256**: Used for initial key derivation from the passphrase.
- **HKDF**: Further derives encryption key and IV using OpenSSL's EVP functions.
- **Memory Management**: Ensures no sensitive data remains in memory after usage. 
- **Error Handling**: Checks every step for errors and reports them appropriately.

Before running this code, ensure that you have linked against the appropriate OpenSSL libraries during compilation (e.g., `-lssl -lcrypto`). Adjust `ITERATIONS` based on performance/security requirements of your specific application context.']

