        nfapi_data.nfapi_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = *(uint8_t*)crcflag_ptr;
    }

    time_t end_time = time(NULL);
    nfapi_data.creation_time = difftime(end_time, start_time);

    return nfapi_data;
}

void free_nfa_api_list(NFAPIData* nfapi_data) {
