    size_t nfa_count = 1000000; // or any other number <= MAX_NFAPIS
    NFAPIData nfapi_data = create_nfa_api_list(nfa_count);

    log_metrics(&nfapi_data);

    free_nfa_api_list(&nfapi_data);
    return 0;
}
