import stdlib.h> // For qsort
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int version;
    int active; // 1 if active, 0 if inactive
    unsigned char RX_UE_INFORMATION_TAG[16];
    unsigned char RNTI[4];
    unsigned char CRC_INDICATION_REL8_TAG[2];
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t active_count;
    pthread_mutex_t lock;
    int compaction_interval;
    FILE *log_file;
} CRCListManager;

CRCListManager* create_crc_list_manager(int initial_capacity, int compaction_interval) {
    CRCListManager *manager = (CRCListManager*)malloc(sizeof(CRCListManager));
    if (!manager) return NULL;

    manager->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->elements) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->active_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->compaction_interval = compaction_interval;

    char log_filename[] = "crc_list_manager.log";
    manager->log_file = fopen(log_filename, "a");
    if (!manager->log_file) {
        free(manager->elements);
        free(manager);
        return NULL;
    }

    fprintf(manager->log_file, "CRC List Manager initialized with capacity %zu\n", initial_capacity);

    return manager;
}

void log_event(CRCListManager *manager, const char* event) {
    if (manager && manager->log_file) {
        time_t now = time(NULL);
        fprintf(manager->log_file, "[%s] %s\n", ctime(&now), event);
    }
}

int expand_capacity_if_needed(CRCListManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->active_count < manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    size_t new_capacity = manager->capacity == 0 ? MAX_ELEMENTS : manager->capacity * 2;

    if (new_capacity > MAX_ELEMENTS) {
        log_event(manager, "Reached maximum capacity. Cannot expand further.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(manager->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        log_event(manager, "Memory allocation failed during expansion.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->elements = new_elements;
    manager->capacity = new_capacity;
    log_event(manager, "List capacity expanded.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_element(CRCListManager *manager, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&manager->lock);

    if (expand_capacity_if_needed(manager) != 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->active_count; ++i) {
        if (!memcmp(element->RX_UE_INFORMATION_TAG, manager->elements[i].RX_UE_INFORMATION_TAG, sizeof(element->RX_UE_INFORMATION_TAG))) {
            log_event(manager, "Element with matching RX_UE_INFORMATION_TAG already exists. Update instead.");
            pthread_mutex_unlock(&manager->lock);
            return update_element(manager, element); // Assuming update_element is implemented
        }
    }

    memcpy(&manager->elements[manager->active_count], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->elements[manager->active_count].version = 1;
    manager->elements[manager->active_count].active = 1;

    ++manager->active_count;
    log_event(manager, "Element added.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_element(CRCListManager *manager, const unsigned char *RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->active_count; ++i) {
        if (!memcmp(RX_UE_INFORMATION_TAG, manager->elements[i].RX_UE_INFORMATION_TAG, sizeof(manager->elements[i].RX_UE_INFORMATION_TAG))) {
            manager->elements[i].active = 0;
            --manager->active_count;

            log_event(manager, "Element removed.");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    log_event(manager, "Element not found for removal.");
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int update_element(CRCListManager *manager, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->active_count; ++i) {
        if (!memcmp(element->RX_UE_INFORMATION_TAG, manager->elements[i].RX_UE_INFORMATION_TAG, sizeof(manager->elements[i].RX_UE_INFORMATION_TAG))) {
            memcpy(&manager->elements[i], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            log_event(manager, "Element updated.");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    log_event(manager, "Element not found for update. Adding as new element.");
    int result = add_element(manager, element);

    pthread_mutex_unlock(&manager->lock);
    return result;
}

void compact_list(CRCListManager *manager) {
    pthread_mutex_lock(&manager->lock);

    size_t write_index = 0;
    for (size_t read_index = 0; read_index < manager->active_count;) {
        if (manager->elements[read_index].active) {
            if (write_index != read_index) {
                memcpy(&manager->elements[write_index], &manager->elements[read_index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
            ++write_index;
        }
        ++read_index;
    }

    manager->active_count = write_index;

    log_event(manager, "List compacted.");

    pthread_mutex_unlock(&manager->lock);
}

void* periodic_compaction(void *arg) {
    CRCListManager *manager = (CRCListManager*)arg;
    while (1) {
        sleep(manager->compaction_interval);

        compact_list(manager);
    }
    return NULL;
}

int serialize_to_file(CRCListManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_event(manager, "Failed to open file for serialization.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fwrite(&manager->active_count, sizeof(size_t), 1, file);
    fwrite(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->active_count, file);

    fclose(file);
    log_event(manager, "List serialized to file.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int deserialize_from_file(CRCListManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_event(manager, "Failed to open file for deserialization.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t active_count;
    fread(&active_count, sizeof(size_t), 1, file);

    if (expand_capacity_if_needed(manager) != 0 || active_count > manager->capacity) {
        fclose(file);
        log_event(manager, "Deserialization failed due to insufficient capacity.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fread(manager->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), active_count, file);
    manager->active_count = active_count;

    fclose(file);
    log_event(manager, "List deserialized from file.");

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void destroy_crc_list_manager(CRCListManager *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);

        free(manager->elements);
        fclose(manager->log_file);

        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int main() {
    CRCListManager *manager = create_crc_list_manager(10, 60); // Initial capacity of 10, compaction every 60 seconds

    if (!manager) return -1;

    pthread_t compaction_thread;
    pthread_create(&compaction_thread, NULL, periodic_compaction, manager);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T element = {0};
    memcpy(element.RX_UE_INFORMATION_TAG, "example_tag", 16);
    add_element(manager, &element);

    serialize_to_file(manager, "crc_list.bin");
    deserialize_from_file(manager, "crc_list.bin");

    destroy_crc_list_manager(manager);
    pthread_cancel(compaction_thread);
    pthread_join(compaction_thread, NULL);

    return 0;
}
```

