    if (!list) {
        log_allocation_failure("Failed to allocate list");
        return NULL;
    }

    list->count = 0;
    memset(list->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_LIST_SIZE);
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu == NULL || pdu->RNTI < RNTI_MIN || pdu->RNTI > RNTI_MAX || !is_valid_RX_UE_INFORMATION_TAG(pdu->RX_UE_INFORMATION_TAG)) {
        log_allocation_failure("Invalid PDU");
        return 0;
    }
    return 1;
}

int add_pdu(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list == NULL || pdu == NULL) {
        log_allocation_failure("Null list or PDU");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        log_allocation_failure("List is full");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    if (!validate_pdu(pdu)) {
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    list->data[list->count++] = pdu;

    log_allocation_success(list->count);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list == NULL) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
