using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
import System.Xml.Linq;
using System.Threading.Tasks;
using System.Collections.Concurrent;
using System.Runtime.Caching;

public class SiteManager
{
    private static readonly string LogFilePath = "site_operations.log";
    private static readonly double MaxLogFileSizeMB = 5.0;
    private static MemoryCache ConfigurationCache = new MemoryCache("ConfigurationCache");

    public async Task<string> AddAndStartSiteAsync(string directoryPath, string siteName)
    {
        try
        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

            var files = Directory.GetFiles(directoryPath);
            if (files.Length <= 1) // At least one non-web.config file is expected
            {
                LogWarning($"The directory {directoryPath} contains insufficient files.");
                return null;
            }

            var webConfigFile = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigFile))
                throw new FileNotFoundException("web.config file not found.");

            if (!IsWebConfigValid(webConfigFile))
                throw new InvalidDataException("Invalid web.config structure.");

            LogOperation($"Starting site '{siteName}' from directory '{directoryPath}'.", true);

            var processStartInfo = new ProcessStartInfo
            {
                FileName = "cmd.exe",
                Arguments = $"/C iisexpress /path:{directoryPath}",
                CreateNoWindow = true,
                UseShellExecute = false
            };

            using (var process = new Process { StartInfo = processStartInfo })
            {
                await RetryAsync(() => Task.Run(process.Start), 3);
                return "Site started successfully.";
            }
        }
        catch (Exception ex)
        {
            LogOperation($"Error starting site '{siteName}': {ex.Message}", false);
            return null;
        }
    }

    private bool IsWebConfigValid(string path)
    {
        try
        {
            var doc = XDocument.Load(path);
            return doc.Root?.Element("system.web") != null;
        }
        catch (Exception ex)
        {
            LogOperation($"Error parsing web.config: {ex.Message}", false);
            return false;
        }
    }

    private async Task RetryAsync(Func<Task> operation, int maxRetries)
    {
        int retryCount = 0;
        double delay = 100; // Start with 100ms

        while (retryCount < maxRetries)
        {
            try
            {
                await operation();
                return;
            }
            catch (Exception ex) when (ex is InvalidOperationException || ex is ArgumentException)
            {
                retryCount++;
                LogOperation($"Retry {retryCount} for operation failed: {ex.Message}", false);
                if (retryCount >= maxRetries) throw;

                await Task.Delay((int)(delay * Math.Pow(2, retryCount)));
            }
        }
    }

    private void LogOperation(string message, bool success)
    {
        var logMessage = $"{DateTime.UtcNow}: {(success ? "SUCCESS" : "FAILURE")} - {message}\n";

        lock (LogFilePath) // Ensure thread safety
        {
            using (var streamWriter = new StreamWriter(LogFilePath, true))
            {
                streamWriter.WriteLine(logMessage);
            }

            if (new FileInfo(LogFilePath).Length / 1024.0 / 1024.0 > MaxLogFileSizeMB)
            {
                ArchiveLogFile();
            }
        }
    }

    private void ArchiveLogFile()
    {
        var timestamp = DateTime.UtcNow.ToString("yyyyMMddHHmmss");
        var archivedFileName = $"site_operations_{timestamp}.log";
        File.Move(LogFilePath, Path.Combine(Path.GetDirectoryName(LogFilePath), archivedFileName));
    }

    private void LogWarning(string message)
    {
        LogOperation($"WARNING: {message}", false);
    }
}
```']

