// Helper function to find and print the largest integer in an array.
void find_and_print_largest(int *arr, size_t size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }

    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to read integers from standard input, validate them, and store in a dynamically allocated array.
int* process_input(size_t *size) {
    int *array = NULL;
    size_t capacity = 10; // Initial capacity
    size_t count = 0;

    array = (int *)malloc(capacity * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    int value;
    while (scanf("%d", &value) == 1) {
        if (value < MIN_VAL || value > MAX_VAL) {
            printf("Invalid input: %d is out of range [%d, %d]\n", value, MIN_VAL, MAX_VAL);
            continue;
        }

        // Resize array if necessary
        if (count >= capacity) {
            capacity *= 2;
            int *temp = realloc(array, capacity * sizeof(int));
            if (!temp) {
                fprintf(stderr, "Memory reallocation failed.\n");
                free(array);
                return NULL;
            }
            array = temp;
        }

        array[count++] = value;

        // Example of pagination logic (threshold can be adjusted)
        if (count % 1000 == 0) {
            printf("Processed %zu integers so far...\n", count);
        }
    }

    *size = count;
    return array;
}

int main() {
    size_t size;
    int *numbers = process_input(&size);

    if (numbers) {
        find_and_print_largest(numbers, size);
        free(numbers);
    } else {
        fprintf(stderr, "Failed to process input.\n");
    }

    return 0;
}
