        snprintf(config->sessions[i].snssai, SNSSAI_SIZE, "SNSSAI%zu", i);
        snprintf(config->sessions[i].session_type, SESSION_TYPE_SIZE, "Type%zu", i);

        config->sessions[i].connection_status = rand() % 2; // Randomly set active/inactive
    }

