    fclose(output_file);

    return 0; // Success
}

void cleanup(NetworkConfig *config) {
    if (config && config->sessions) {
        free(config->sessions);
        config->sessions = NULL;
    }
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules>\n", argv[0]);
        return -1;
    }

