```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CIPHER_MODES 4

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB,
    NULL_MODE
} CipherMode;

typedef struct {
    unsigned char key[8]; // DES key size is 64 bits (8 bytes)
    unsigned char iv[8];  // Initialization vector
    pthread_mutex_t lock; // Mutex for thread safety
    int active;           // Flag indicating if the instance is active
    CipherMode mode;
} DES_CipherInstance;

typedef struct {
    DES_CipherInstance* instances[MAX_CIPHER_MODES];
    size_t count;
    pthread_rwlock_t list_lock;
} CipherManager;

// Function prototypes
void initialize_cipher_instance(DES_CipherInstance* instance, unsigned char key[8], unsigned char iv[8], CipherMode mode);
void update_key_and_iv(DES_CipherInstance* instance, unsigned char new_key[8], unsigned char new_iv[8]);
void cleanup_cipher_manager(CipherManager* manager);

CipherManager* create_cipher_manager() {
    CipherManager* manager = (CipherManager*)malloc(sizeof(CipherManager));
    if (!manager) return NULL;

    memset(manager->instances, 0, sizeof(manager->instances));
    manager->count = 0;
    pthread_rwlock_init(&manager->list_lock, NULL);

    return manager;
}

DES_CipherInstance* create_cipher_instance(unsigned char key[8], unsigned char iv[8], CipherMode mode) {
    DES_CipherInstance* instance = (DES_CipherInstance*)malloc(sizeof(DES_CipherInstance));
    if (!instance) return NULL;

    initialize_cipher_instance(instance, key, iv, mode);

    pthread_rwlock_wrlock(&manager->list_lock);
    manager->instances[mode] = instance;
    manager->count++;
    pthread_rwlock_unlock(&manager->list_lock);

    return instance;
}

void initialize_cipher_instance(DES_CipherInstance* instance, unsigned char key[8], unsigned char iv[8], CipherMode mode) {
    if (!instance) return;

    memcpy(instance->key, key, 8);
    memcpy(instance->iv, iv, 8);
    pthread_mutex_init(&instance->lock, NULL);
    instance->active = 1;
    instance->mode = mode;
}

void update_key_and_iv(DES_CipherInstance* instance, unsigned char new_key[8], unsigned char new_iv[8]) {
    if (!instance) return;

    pthread_mutex_lock(&instance->lock);
    memcpy(instance->key, new_key, 8);
    memcpy(instance->iv, new_iv, 8);
    pthread_mutex_unlock(&instance->lock);
}

void cleanup_cipher_manager(CipherManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < MAX_CIPHER_MODES; ++i) {
        pthread_rwlock_wrlock(&manager->list_lock);
        if (manager->instances[i]) {
            pthread_mutex_destroy(&manager->instances[i]->lock);
            free(manager->instances[i]);
            manager->instances[i] = NULL;
        }
        pthread_rwlock_unlock(&manager->list_lock);
    }

    pthread_rwlock_destroy(&manager->list_lock);
    free(manager);
}

void shutdown_cipher_manager(CipherManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < MAX_CIPHER_MODES; ++i) {
        pthread_mutex_lock(&manager->instances[i]->lock);
        manager->instances[i]->active = 0;
        pthread_mutex_unlock(&manager->instances[i]->lock);
    }

    cleanup_cipher_manager(manager);
}

// Example function to dynamically select cipher mode
CipherMode parse_mode(const char* config_str) {
    if (strcmp(config_str, "ECB") == 0) return ECB;
    if (strcmp(config_str, "EDE") == 0) return EDE;
    if (strcmp(config_str, "EDE3") == 0) return EDE3;
    if (strcmp(config_str, "CFB") == 0) return CFB;
    if (strcmp(config_str, "NULL_MODE") == 0) return NULL_MODE;

    fprintf(stderr, "Invalid cipher mode: %s\n", config_str);
    exit(EXIT_FAILURE); // Handle error appropriately in production
}

// Example usage
int main() {
    CipherManager* manager = create_cipher_manager();

    unsigned char key[8] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xAB, 0xCD, 0xEF};
    unsigned char iv[8] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77};

    CipherMode mode = parse_mode("ECB");
    DES_CipherInstance* instance = create_cipher_instance(key, iv, mode);

    // Update key and IV
    unsigned char new_key[8] = {0xFE, 0xDC, 0xBA, 0x98, 0x76, 0x54, 0x32, 0x10};
    update_key_and_iv(instance, new_key, iv);

    // Clean up and shutdown
    shutdown_cipher_manager(manager);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used for each cipher instance to ensure thread-safe updates.
- **Resource Management**: The `CipherManager` handles dynamic allocation and cleanup of cipher instances.
- **Error Handling**: Invalid configurations result in error messages and termination.
- **Modularity**: Functions are modular, allowing easy extension or modification.
- **Scalability**: Designed to manage multiple concurrent cipher instances efficiently.']

