    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535
#define MEMORY_FRAGMENTATION_THRESHOLD 0.2

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t current_memory_usage;
    size_t max_memory_allocation;
    double fragmentation_threshold;
    // Additional fields for logging and monitoring
} ListManager;

// Function prototypes
void log_operation(const char* operation, const NFAPI_CRC_INDICATION_PDU_T* data);
bool is_valid_rx_ue_information_tag(uint16_t tag);
bool validate_rnti_range(uint16_t rnti);
bool check_memory_fragmentation(size_t current_usage, size_t max_allocation, double threshold);
void self_check_routine(ListManager* manager);
void recover_from_error();

// Thread-safe add function
int list_manager_add_item(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!validate_rnti_range(item.RNTI)) return -1;

    pthread_mutex_lock(&manager->lock);

    // Check memory constraints and fragmentation
    if (check_memory_fragmentation(manager->current_memory_usage + sizeof(Node), manager->max_memory_allocation, manager->fragmentation_threshold)) {
        recover_from_error();
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        recover_from_error();
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_node->data = item;
    new_node->next = manager->head;
    manager->head = new_node;
    manager->current_memory_usage += sizeof(Node);

    log_operation("ADD", &item);
    pthread_mutex_unlock(&manager->lock);
    self_check_routine(manager);
    return 0;
}

// Helper functions
void log_operation(const char* operation, const NFAPI_CRC_INDICATION_PDU_T* data) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s | RX_UE_INFORMATION_TAG: %u | RNTI: %u | CRC_INDICATION_REL8_TAG: %u\n",
           ctime(&now), operation, data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG);
}

bool is_valid_rx_ue_information_tag(uint16_t tag) {
    // Implement your validation logic
    return true;
}

bool validate_rnti_range(uint16_t rnti) {
    return (rnti <= MAX_RNTI && rnti > 0);
}

bool check_memory_fragmentation(size_t current_usage, size_t max_allocation, double threshold) {
    // Implement your fragmentation checking logic
    double used_ratio = (double)current_usage / max_allocation;
    return (used_ratio > threshold);
}

void self_check_routine(ListManager* manager) {
    if (!manager) return;

    Node* current = manager->head;
    while (current != NULL) {
        if (!validate_rnti_range(current->data.RNTI)) {
            fprintf(stderr, "Inconsistency detected: Invalid RNTI value\n");
            // Handle inconsistency
        }
        current = current->next;
    }
}

void recover_from_error() {
    fprintf(stderr, "Recovering from error...\n");
    // Implement recovery mechanism
}

// Initialize ListManager
ListManager* initialize_list_manager(size_t max_memory_allocation) {
    ListManager* manager = malloc(sizeof(ListManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->current_memory_usage = 0;
    manager->max_memory_allocation = max_memory_allocation;
    manager->fragmentation_threshold = MEMORY_FRAGMENTATION_THRESHOLD;

    return manager;
}

// Destroy ListManager
void destroy_list_manager(ListManager* manager) {
    if (!manager) return;

    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
