    private static readonly Dictionary<string, string> Configurations = LoadConfigurations();
    private static DateTime _lastSelectionTime = DateTime.MinValue;

    // Method to load configurations (e.g., from environment variables or a config file)
    private static Dictionary<string, string> LoadConfigurations()
    {
        return new Dictionary<string, string>
        {
            { "CooldownSeconds", Environment.GetEnvironmentVariable("GAME_ACTION_COOLDOWN") ?? "9" }
        };
    }

    public async Task SelectGameActionAsync()
    {
        try
        {
            var actions = await LoadActionsFromFileAsync("game_actions.dat");

            if (actions == null || actions.Count == 0)
                throw new InvalidOperationException("No game actions available.");

            // Ensure thread-safe action selection with cooldown
            lock (_lock)
            {
                if ((DateTime.UtcNow - _lastSelectionTime).TotalSeconds < int.Parse(Configurations["CooldownSeconds"]))
                    return;

                var random = new Random();
                var selectedAction = actions[random.Next(actions.Count)];
                _lastSelectionTime = DateTime.UtcNow;

