#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>
#include <pthread.h>
#include <time.h>

// Define the structure for LTE RRC MIB Info
typedef struct {
    int sib_id;
    char *sib_content; // Assume content is a string
    _Atomic int crcflag; // Atomic for thread-safe updates and reads
} LTE_RRC_MIB_INFO;

// Structure to manage dynamic array of MIB info entries
typedef struct {
    LTE_RRC_MIB_INFO *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MIB_Manager;

// Initialize the MIB Manager
MIB_Manager* init_mib_manager(size_t initial_capacity) {
    MIB_Manager *manager = malloc(sizeof(MIB_Manager));
    if (!manager) return NULL;

    manager->array = malloc(initial_capacity * sizeof(LTE_RRC_MIB_INFO));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Function to add or update MIB information
int add_or_update_mib_info(MIB_Manager *manager, int sib_id, const char *sib_content) {
    if (!manager || !sib_content) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].sib_id == sib_id) {
            free(manager->array[i].sib_content);
            manager->array[i].sib_content = strdup(sib_content);
            atomic_store(&manager->array[i].crcflag, 1); // Example setting CRCFLAG
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_RRC_MIB_INFO *new_array = realloc(manager->array, new_capacity * sizeof(LTE_RRC_MIB_INFO));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    LTE_RRC_MIB_INFO new_info = { .sib_id = sib_id, .sib_content = strdup(sib_content), .crcflag = 0 };
    if (!new_info.sib_content) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->array[manager->count++] = new_info;
    atomic_store(&new_info.crcflag, 1); // Example setting CRCFLAG

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to retrieve the latest SIB content
char* get_latest_sib_content(MIB_Manager *manager, int sib_id) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].sib_id == sib_id) {
            char *content = strdup(manager->array[i].sib_content);
            pthread_mutex_unlock(&manager->lock);
            return content;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to free resources
void cleanup_mib_manager(MIB_Manager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i].sib_content);
    }

    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage of the MIB Manager
int main() {
    MIB_Manager *mib_manager = init_mib_manager(10);

    if (add_or_update_mib_info(mib_manager, 1, "Initial SIB Content")) {
        printf("Failed to add or update MIB info\n");
    }

    char *content = get_latest_sib_content(mib_manager, 1);
    if (content) {
        printf("Latest SIB Content: %s\n", content);
        free(content);
    } else {
        printf("SIB Info not found\n");
    }

    cleanup_mib_manager(mib_manager);

    return 0;
}
```

### Key Features:
