#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 5000
#define MIN_TRANSACTION_ID 1
#define MAX_TRANSACTION_ID 9999

typedef struct {
    int transactionID;
    char sourceIP[16];
    char destinationIP[16];
    size_t payloadSize;
    int status; // 0 for failure, 1 for success
} DataTransferObject;

typedef struct Node {
    DataTransferObject data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int capacity;
    FILE* logFile;
} TransactionManager;

TransactionManager* createManager();
void freeManager(TransactionManager* manager);
int addTransaction(TransactionManager* manager, const char* sourceIP, const char* destinationIP);
void resizeArray(TransactionManager* manager);
void logTransaction(const DataTransferObject* dto, FILE* logFile);
void rotateLogFile(FILE** logFile);

TransactionManager* createManager() {
    TransactionManager* manager = (TransactionManager*)malloc(sizeof(TransactionManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = INITIAL_CAPACITY;

    // Open or create a log file
    manager->logFile = fopen("transaction.log", "a");
    if (!manager->logFile) {
        perror("Failed to open log file");
        free(manager);
        return NULL;
    }

    return manager;
}

void freeManager(TransactionManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->logFile);
    free(manager);
}

int addTransaction(TransactionManager* manager, const char* sourceIP, const char* destinationIP) {
    if (!manager || !sourceIP || !destinationIP) return -1;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    int transactionID = MIN_TRANSACTION_ID;

    // Find the next available transaction ID
    while (current && transactionID <= MAX_TRANSACTION_ID) {
        if (transactionID == current->data.transactionID) {
            transactionID++;
        }
        current = current->next;
    }

    if (transactionID > MAX_TRANSACTION_ID) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No available transaction ID
    }

    // Create a new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    newNode->data.transactionID = transactionID;
    strncpy(newNode->data.sourceIP, sourceIP, sizeof(newNode->data.sourceIP) - 1);
    newNode->data.sourceIP[sizeof(newNode->data.sourceIP) - 1] = '\0';
    strncpy(newNode->data.destinationIP, destinationIP, sizeof(newNode->data.destinationIP) - 1);
    newNode->data.destinationIP[sizeof(newNode->data.destinationIP) - 1] = '\0';

    // Generate random payload size and status
    srand(time(NULL) + transactionID); // Seed with transaction ID for uniqueness
    newNode->data.payloadSize = rand() % (1024 * 1024); // Random size up to 1MB
    newNode->data.status = rand() % 2; // Random success or failure

    newNode->next = manager->head;
    manager->head = newNode;

    logTransaction(&newNode->data, manager->logFile);

    pthread_mutex_unlock(&manager->lock);
    return transactionID;
}

void resizeArray(TransactionManager* manager) {
    // Resize logic if needed
    // Currently not implemented as we use a linked list for dynamic growth
}

void logTransaction(const DataTransferObject* dto, FILE* logFile) {
    fprintf(logFile, "Transaction ID: %d, Source IP: %s, Destination IP: %s, Payload Size: %zu, Status: %d\n",
            dto->transactionID, dto->sourceIP, dto->destinationIP, dto->payloadSize, dto->status);

    // Rotate log file if it exceeds a certain size
    rotateLogFile(&logFile);
}

void rotateLogFile(FILE** logFile) {
    fseek(*logFile, 0, SEEK_END);
    long fileSize = ftell(*logFile);
    const long maxFileSize = 1024 * 1024; // 1MB

    if (fileSize > maxFileSize) {
        fclose(*logFile);
        char newFileName[256];
        snprintf(newFileName, sizeof(newFileName), "transaction_%ld.log", time(NULL));
        FILE* tempFile = fopen(newFileName, "w");
        if (!tempFile) {
            perror("Failed to create rotated log file");
            return;
        }
        fclose(tempFile);

        char command[512];
        snprintf(command, sizeof(command), "mv %s transaction_%ld.log", (*logFile)->_IO_file_name, time(NULL));
        system(command);

        *logFile = fopen((*logFile)->_IO_file_name, "a");
    }
}

int main() {
    TransactionManager* manager = createManager();
    if (!manager) return 1;

    for (int i = 0; i < MAX_CAPACITY; ++i) {
        char sourceIP[16] = "192.168.0.";
        sprintf(sourceIP + strlen(sourceIP), "%d", rand() % 255);
        char destinationIP[16] = "10.0.0.";
        sprintf(destinationIP + strlen(destinationIP), "%d", rand() % 255);

        if (addTransaction(manager, sourceIP, destinationIP) == -1) {
            printf("Failed to add transaction\n");
        }
    }

    freeManager(manager);
    return 0;
}
```

### Key Points:
