#define MAX_CAPACITY 5000

// Function to process integers from standard input and store in a dynamic array
int* process_integers(int* size) {
    int* numbers = (int*)malloc(MAX_CAPACITY * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    int count = 0;

    while (fgets(buffer, sizeof(buffer), stdin)) {
        char* token = strtok(buffer, " \n");

        while (token != NULL && count < MAX_CAPACITY) {
            char* endptr;
            long num = strtol(token, &endptr, 10);

            if (*endptr == '\0') { // Valid integer
                numbers[count++] = (int)num;
            } else { // Handle invalid input gracefully
                fprintf(stderr, "Invalid input encountered: '%s'. Ignoring...\n", token);
            }

            token = strtok(NULL, " \n");
        }

        if (count >= MAX_CAPACITY) {
            break; // Stop reading further as we reached capacity
        }
    }

    if (fgets(buffer, sizeof(buffer), stdin)) { // Check for overflow input
        fprintf(stderr, "Warning: Input exceeded maximum capacity of %d integers. Truncating excess.\n", MAX_CAPACITY);
    }

    *size = count;
    return numbers;
}

// Helper function to calculate and print the sum of all integers in the array
void print_sum(const int* numbers, size_t size) {
    long long sum = 0;
    for (size_t i = 0; i < size; ++i) {
        sum += numbers[i];
    }
    printf("Sum of integers: %lld\n", sum);
}

// Main function to demonstrate usage
int main() {
    int size;
    int* numbers = process_integers(&size);

    print_sum(numbers, (size_t)size);

    free(numbers); // Clean up allocated memory
    return 0;
}
