#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Define constants for thresholds and log levels
#define INITIAL_CAPACITY 1000
#define RESIZE_THRESHOLD_FACTOR 2.0
#define MAX_LOG_LEVEL 3

// Structure Definitions
typedef struct {
    unsigned int RNTI;
    unsigned char RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST;

// Logging utility
void log_message(int level, const char *format, ...) {
    if (level <= MAX_LOG_LEVEL) {
        va_list args;
        va_start(args, format);
        vprintf(format, args);
        printf("\n");
        va_end(args);
    }
}

// Function Prototypes
CRC_LIST* create_crc_list();
void free_crc_list(CRC_LIST *list);
int resize_crc_list_if_needed(CRC_LIST *list);
int add_to_crc_list(CRC_LIST *list, unsigned int RNTI, unsigned char RX_UE_INFORMATION_TAG);

// Main Functionality
CRC_LIST* create_crc_list() {
    CRC_LIST *list = (CRC_LIST*) malloc(sizeof(CRC_LIST));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*) calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;

    pthread_mutex_init(&list->lock, NULL);

    log_message(1, "CRC List created with initial capacity: %zu", list->capacity);
    return list;
}

void free_crc_list(CRC_LIST *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->elements);
        free(list);
        log_message(1, "CRC List freed");
    }
}

int resize_crc_list_if_needed(CRC_LIST *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = (size_t)(list->capacity * RESIZE_THRESHOLD_FACTOR);

        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) return -1;

        list->elements = new_elements;
        list->capacity = new_capacity;

        log_message(2, "CRC List resized to new capacity: %zu", list->capacity);
    }
    return 0;
}

int add_to_crc_list(CRC_LIST *list, unsigned int RNTI, unsigned char RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);

    if (resize_crc_list_if_needed(list) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    size_t index = list->count++;
    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[index];

    element->RNTI = RNTI;
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;

    // Randomly set CRCFLAG (assuming it's part of the structure)
    srand(time(NULL) + index);  // Simple RNG seeding for demonstration
    element->CRC_INDICATION_REL8_TAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
    log_message(3, "Added new element to CRC List: RNTI=%u, RX_UE_INFORMATION_TAG=%hhu", RNTI, RX_UE_INFORMATION_TAG);

    return 0;
}

// Example usage
int main() {
    // Configuration of logging level (1 = minimal, 2 = detailed, 3 = debug)
    int log_level = 3;

    CRC_LIST *crc_list = create_crc_list();
    if (!crc_list) return -1;

    for (unsigned int i = 0; i < 10000; ++i) {
        unsigned int RNTI = rand() % 65536;
        unsigned char RX_UE_INFORMATION_TAG = rand() % 256;

        if (add_to_crc_list(crc_list, RNTI, RX_UE_INFORMATION_TAG) != 0) {
            log_message(1, "Failed to add element to CRC List");
        }
    }

    free_crc_list(crc_list);
    return 0;
}
