#define INITIAL_BUFFER_SIZE 1024
#define MAX_BUFFER_SIZE 8192
#define BUFFER_INCREMENT 256
#define REALLOCATION_THRESHOLD 10
#define FRAME_COUNT_MAX 1000

typedef struct {
    size_t capacity;
    void* data;
} RX_BUFFER_T;

typedef struct {
    int frame_id; // Identifier for the frame
    RX_BUFFER_T buffer;
} RX_FRAME_T;

typedef struct {
    RX_FRAME_T frames[FRAME_COUNT_MAX];
    int reallocation_counts[FRAME_COUNT_MAX];
    bool paused;
} NFAPI_L2_RX_FRAME_ARRAY;

volatile sig_atomic_t pause_flag = 0;

void handle_signal(int signal) {
    if (signal == SIGUSR1) {
        pause_flag = !pause_flag; // Toggle the pause state
    }
}

int get_random_size() {
    return INITIAL_BUFFER_SIZE + rand() % (MAX_BUFFER_SIZE - INITIAL_BUFFER_SIZE);
}

bool initialize_frame(NFAPI_L2_RX_FRAME_ARRAY* array, int index, size_t buffer_size) {
    if (index < 0 || index >= FRAME_COUNT_MAX) return false;

    RX_BUFFER_T* buffer = &array->frames[index].buffer;
    void* new_data = realloc(buffer->data, buffer_size);

    if (!new_data) return false; // Memory allocation failed

    buffer->capacity = buffer_size;
    buffer->data = new_data;

    for (size_t i = 0; i < buffer_size; ++i) {
        ((unsigned char*)buffer->data)[i] = rand() % 256; // Initialize with random data
    }

    return true;
}

NFAPI_L2_RX_FRAME_ARRAY* initialize_nfa_rx_frame_array(int frame_count) {
    if (frame_count < 1 || frame_count > FRAME_COUNT_MAX) {
        fprintf(stderr, "Invalid number of frames.\n");
        return NULL;
    }

    NFAPI_L2_RX_FRAME_ARRAY* array = malloc(sizeof(NFAPI_L2_RX_FRAME_ARRAY));
    if (!array) {
        perror("Failed to allocate memory for frame array");
        return NULL;
    }

    signal(SIGUSR1, handle_signal);

    int total_reallocations = 0;

    for (int i = 0; i < frame_count; ++i) {
        size_t buffer_size = get_random_size();
        int reallocation_count = 0;

        while (!initialize_frame(array, i, buffer_size)) {
            if (++reallocation_count > REALLOCATION_THRESHOLD) {
                fprintf(stderr, "Warning: Exceeded reallocation threshold for frame %d.\n", i);
                // Reduce the target buffer size to avoid excessive memory use
                buffer_size -= BUFFER_INCREMENT;
                if (buffer_size < INITIAL_BUFFER_SIZE)
                    return NULL; // Failure condition
            }

            buffer_size += BUFFER_INCREMENT;
            if (buffer_size > MAX_BUFFER_SIZE) break; // Prevent exceeding max buffer size

            total_reallocations++;
        }

        array->reallocation_counts[i] = reallocation_count;

        if (total_reallocations > 1000) {
            fprintf(stderr, "Warning: Total reallocations exceeded safe limit.\n");
            return NULL;
        }

        while (pause_flag && !array->paused) {
            pause(); // Simulate pausing - replace with actual wait mechanism
        }

        array->paused = false; // Reset for next frame processing
    }

    return array;
}

void free_nfa_rx_frame_array(NFAPI_L2_RX_FRAME_ARRAY* array) {
    if (!array) return;

    for (int i = 0; i < FRAME_COUNT_MAX && array->frames[i].buffer.data != NULL; ++i) {
        free(array->frames[i].buffer.data);
    }

    free(array);
}

