#define MAX_FRAMES 10000
#define PAYLOAD_SIZE 256

typedef struct {
    int frame_id;
    time_t timestamp;
    uint8_t *data_payload;
} MAC_FRAME;

typedef struct {
    MAC_FRAME *frames[MAX_FRAMES];
    pthread_mutex_t lock;
    FILE *log_file;
} NetworkInterface;

void log_error(const char *message) {
    if (NetworkInterface.log_file) {
        fprintf(NetworkInterface.log_file, "ERROR: %s\n", message);
    }
}

int initialize_network_interface(NetworkInterface *netif) {
    int i;
    srand(time(NULL));

    pthread_mutex_init(&netif->lock, NULL);

    netif->log_file = fopen("network_log.txt", "a");
    if (!netif->log_file) {
        perror("Failed to open log file");
        return -1;
    }

    for (i = 0; i < MAX_FRAMES; ++i) {
        MAC_FRAME *frame = malloc(sizeof(MAC_FRAME));
        if (!frame) {
            log_error("Memory allocation failed for MAC_FRAME structure.");
            pthread_mutex_destroy(&netif->lock);
            fclose(netif->log_file);
            return -1;
        }

        frame->frame_id = rand() % 1000; // Example ID generation
        frame->timestamp = time(NULL);

        frame->data_payload = malloc(PAYLOAD_SIZE);
        if (!frame->data_payload) {
            log_error("Memory allocation failed for data payload.");
            free(frame);
            pthread_mutex_destroy(&netif->lock);
            fclose(netif->log_file);
            return -1;
        }

        for (int j = 0; j < PAYLOAD_SIZE; ++j) {
            frame->data_payload[j] = rand() % 256;
        }

        netif->frames[i] = frame;
    }

    return 0;
}

void cleanup_network_interface(NetworkInterface *netif) {
    int i;

    pthread_mutex_lock(&netif->lock);

    for (i = 0; i < MAX_FRAMES; ++i) {
        if (netif->frames[i]) {
            free(netif->frames[i]->data_payload);
            free(netif->frames[i]);
        }
    }

    pthread_mutex_unlock(&netif->lock);
    pthread_mutex_destroy(&netif->lock);

    if (netif->log_file) {
        fclose(netif->log_file);
    }
}

void update_frame_identifiers_and_timestamps(NetworkInterface *netif, int new_id[], time_t new_timestamp[]) {
    pthread_mutex_lock(&netif->lock);

