NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pi_list(size_t *allocated_size) {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    size_t list_size = 0;

    // Allocate initial memory
    while (list_size < MAX_UE_IDENTIFIERS) {
        size_t new_size = list_size + 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_list) {
            // Memory allocation failure
            free(list);
            log_error("Memory allocation failed");
            *allocated_size = 0;
            return NULL;
        }

        list = new_list;
        memset(&list[list_size], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list_size++;
    }

    // Validate uniqueness of RNTIs
    for (size_t i = 0; i < MAX_UE_IDENTIFIERS; ++i) {
        int rnti;
        bool success = false;

        for (int attempts = 0; attempts < 10 && !success; ++attempts) {
            success = fetch_rnti_from_db(&rnti, attempts);
            if (!success) {
                log_error("Failed to fetch RNTI from database");
                free(list);
                *allocated_size = 0;
                return NULL;
            }

            // Check for duplicates
            bool is_unique = true;
            for (size_t j = 0; j < i; ++j) {
                if (list[j].RNTI == rnti) {
                    is_unique = false;
                    break;
                }
            }

            if (is_unique) {
                list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
                list[i].RNTI = rnti;
                list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;
                break;
            }
        }

        if (!success) {
            log_error("Unable to find unique RNTI after multiple attempts");
            free(list);
            *allocated_size = 0;
            return NULL;
        }
    }

    *allocated_size = list_size;
    return list;
}

void cleanup_nfa_pi_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t allocated_size) {
    if (list != NULL && allocated_size > 0) {
        free(list);
    }
}
