typedef struct {
    int crcFlag; // Determines if CRC integrity check passed
} CRC_INDICATION_REL8_TAG;

// Thread-safe queue for handling RAN signaling data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} Queue;

Queue* create_queue(size_t capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->items = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->capacity = capacity;
    q->count = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void enqueue(Queue* q, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&q->lock);
    while (q->count == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    q->items[q->count++] = item;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(Queue* q) {
    pthread_mutex_lock(&q->lock);
    while (q->count == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    NFAPI_CRC_INDICATION_PDU_T item = q->items[0];
    memmove(&q->items[0], &q->items[1], --q->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return item;
}

void free_queue(Queue* q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q->items);
    free(q);
}

