["```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NFAPI_List;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Handle malloc failure
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to initialize the list
void init_list(NFAPI_List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to safely add a node ensuring no consecutive RNTI duplication
int safe_add_node(NFAPI_List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    int can_add = 1;

    if (current && current->data.RNTI == data.RNTI) {
        can_add = 0; // Cannot add due to RNTI duplication
    } else {
        while (current && current->next) {
            if (current->next->data.RNTI == data.RNTI) {
                can_add = 0;
                break;
            }
            current = current->next;
        }
        if (can_add && current) {
            can_add = (current->data.RNTI != data.RNTI);
        }
    }

    if (can_add) {
        Node* new_node = create_node(data);
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Handle malloc failure
        }
        if (!list->head || list->head->data.RNTI != data.RNTI) { // Head check for duplication
            new_node->next = list->head;
            list->head = new_node;
        } else {
            while (current && current->next) {
                current = current->next;
            }
            if (current->data.RNTI != data.RNTI) { // Check last node's RNTI
                current->next = new_node;
            } else {
                free(new_node);
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
    return can_add;
}

// Function to delete a node based on RNTI
int safe_delete_node(NFAPI_List* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) { // RNTI not found
        pthread_mutex_unlock(&list->lock);
        return 0; 
    }

    if (!prev) { // Head node is to be deleted
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 1;
}

// Function to cleanup the list and its resources
void destroy_list(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp;

    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

This code provides thread-safe operations for managing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring that no two consecutive nodes share the same RNTI. The use of mutex locks ensures safe concurrent access by multiple threads. Operations such as addition and deletion are protected against data races while maintaining efficient memory usage and CPU overhead."]

