```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000

typedef struct {
    time_t timestamp;
    char event_type[50];
    int unique_id;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventList;

// Simulated function to fetch initial metadata from an external data source
int fetch_initial_metadata(char* event_type, size_t max_length) {
    // Simulate latency and reliability issues
    if (rand() % 10 < 2) {  // 20% chance of failure
        return -1;
    }
    snprintf(event_type, max_length, "EventType_%d", rand() % 100);
    return 0;
}

// Function to initialize the event list
void init_event_list(EventList* list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->events = (NetworkEvent*)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!list->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
}

// Function to free the event list
void destroy_event_list(EventList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list->events);
}

// Thread-safe function to add an event to the list
int add_event(EventList* list, const NetworkEvent* new_event) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkEvent* new_events = (NetworkEvent*)realloc(list->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            perror("Failed to reallocate memory for events");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    memcpy(&list->events[list->count], new_event, sizeof(NetworkEvent));
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to populate the event list
void populate_events(EventList* list, size_t num_events) {
    char metadata[50];
    time_t last_timestamp = 0;

    for (size_t i = 0; i < num_events; ++i) {
        if (fetch_initial_metadata(metadata, sizeof(metadata)) != 0) {
            fprintf(stderr, "Failed to fetch initial metadata\n");
            continue;
        }

        NetworkEvent new_event;
        time(&new_event.timestamp);
        while (new_event.timestamp <= last_timestamp) {
            time(&new_event.timestamp); // Ensure monotonically increasing timestamps
        }
        last_timestamp = new_event.timestamp;

        snprintf(new_event.event_type, sizeof(new_event.event_type), "%s", metadata);
        new_event.unique_id = rand();  // Unique ID generation

        if (add_event(list, &new_event) != 0) {
            fprintf(stderr, "Failed to add event to list\n");
            break;
        }
    }
}

// Main function for testing
int main() {
    EventList list;
    init_event_list(&list, 10);

    populate_events(&list, MAX_EVENTS);

    // Display events (for demonstration purposes)
    pthread_mutex_lock(&list.lock);
    for (size_t i = 0; i < list.count; ++i) {
        printf("Event %zu: ID=%d, Type=%s, Timestamp=%ld\n", i + 1, 
               list.events[i].unique_id, list.events[i].event_type,
               list.events[i].timestamp);
    }
    pthread_mutex_unlock(&list.lock);

    destroy_event_list(&list);

    return 0;
}
