// Function to generate a unique session ID
void generate_session_id(char *session_id) {
    snprintf(session_id, 50, "SID-%ld", time(NULL) + rand());
}

// Function to populate the collection with sessions
void populate_sessions(SessionManager *manager, int num_sessions) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < num_sessions && manager->count < MAX_SESSIONS; ++i) {
        Session session;
        session.user_id = rand() % 1000 + 1;
        session.start_time = time(NULL) + (rand() % 3600);
        session.end_time = session.start_time + (rand() % 1800 + 600); // 10 to 30 minutes
        generate_session_id(session.session_id);

        strcpy(session.session_type, "default");
        strcpy(session.location, "unknown");

        manager->sessions[manager->count++] = session;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to simulate external API integration and handle network issues
int update_sessions_from_api(SessionManager *manager) {
    // Simulate network call
    printf("Updating sessions from external API...\n");

    int success = 0;
    int retries = 3;
    while (retries > 0 && !success) {
        if ((rand() % 10) < 8) { // Simulate intermittent connectivity
            printf("Network issue, retrying...\n");
            --retries;
            continue;
        }

        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            // Update session data based on API response
            printf("Session ID: %s - Updated\n", manager->sessions[i].session_id);
        }
        pthread_mutex_unlock(&manager->lock);

        success = 1;
    }

    return success ? 0 : -1;
}

// Function to initialize the SessionManager
void init_session_manager(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
}

int main() {
    srand(time(NULL));

    SessionManager manager;
    init_session_manager(&manager);

    populate_sessions(&manager, 100); // Populate with 100 sessions
    if (update_sessions_from_api(&manager) != 0) {
        fprintf(stderr, "Failed to update sessions from external API.\n");
    }

    return 0;
}
