#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int packetSequenceNumber;
    long long packetTimestamp; // Using a larger type to accommodate precise timestamps
} PacketMetadata;

typedef struct {
    int sessionID;
    char connectionState;
    PacketMetadata* packets;  // Dynamic array of PacketMetadata structures
} UserSessionData;

// Global mutex for thread safety during session creation and destruction
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

UserSessionData* initialize_sessions(size_t numSessions, size_t maxPacketsPerSession) {
    if (numSessions == 0 || maxPacketsPerSession == 0) {
        return NULL;
    }

    UserSessionData* sessions = malloc(numSessions * sizeof(UserSessionData));
    if (!sessions) {
        perror("Failed to allocate memory for sessions");
        return NULL;
    }

    pthread_mutex_lock(&session_mutex);

    for (size_t i = 0; i < numSessions; ++i) {
        sessions[i].sessionID = i + 1;  // Assigning unique session ID
        sessions[i].connectionState = 'I';  // Initializing connection state to 'Initialized'

        sessions[i].packets = malloc(maxPacketsPerSession * sizeof(PacketMetadata));
        if (!sessions[i].packets) {
            perror("Failed to allocate memory for packets");

            // Free previously allocated memory in case of error
            while (i > 0) { 
                free(sessions[--i].packets);
            }
            free(sessions);
            pthread_mutex_unlock(&session_mutex);
            return NULL;
        }

        for (size_t j = 0; j < maxPacketsPerSession; ++j) {
            sessions[i].packets[j].packetSequenceNumber = j + 1; // Assigning valid sequence number
            sessions[i].packets[j].packetTimestamp = 0; // Initializing timestamps to zero or a default value
        }
    }

    pthread_mutex_unlock(&session_mutex);
    return sessions;
}

void free_sessions(UserSessionData* sessions, size_t numSessions) {
    if (!sessions) return;

    pthread_mutex_lock(&session_mutex);

    for (size_t i = 0; i < numSessions; ++i) {
        free(sessions[i].packets); // Free each packet array
    }

    free(sessions); // Free the session array itself

    pthread_mutex_unlock(&session_mutex);
}

int main() {
    size_t numSessions = 100;
    size_t maxPacketsPerSession = 50;

    UserSessionData* sessions = initialize_sessions(numSessions, maxPacketsPerSession);
    if (sessions) {
        // Sessions are initialized successfully

        // Example of using the session data
        printf("Session %d has connection state: %c\n", sessions[0].sessionID, sessions[0].connectionState);

        free_sessions(sessions, numSessions); // Clean up when done
    }

    return 0;
}
```

### Key Points:
- **Memory Allocation**: Allocate memory for the session array and individual packet arrays dynamically.
- **Thread Safety**: Use a mutex to ensure thread-safe operations during initialization and deallocation of sessions.
- **Error Handling**: Check for `NULL` after every allocation, ensuring graceful cleanup if any part fails.
