#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>

typedef struct {
    int MeasurementIdentity;
    float RSRP;
    float RSRQ;
} CellMeasurementReport;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int gaussian_random(float mean, float stddev) {
    static double old_uniform = 0.0;
    if (old_uniform == 0.0) old_uniform = rand() / ((double)RAND_MAX + 1);
    static const double pi = 3.14159265358979323846;
    double u1, u2;
    do {
        u1 = rand() / ((double)RAND_MAX + 1);
        u2 = rand() / ((double)RAND_MAX + 1);
    } while (u1 <= old_uniform);

    double z0;
    z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * pi * u2);
    old_uniform = u2;

    return mean + stddev * z0;
}

int initialize_and_populate_reports(CellMeasurementReport* reports, size_t array_size, float mean, float stddev) {
    if (reports == NULL || mean <= 0 || stddev <= 0) {
        return -1; // Error: Invalid input parameters
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < array_size; ++i) {
        reports[i].MeasurementIdentity = i + 1;
        reports[i].RSRP = gaussian_random(mean, stddev);
        reports[i].RSRQ = (rand() % 31) - 15.5f; // Dummy RSRQ values between -15.5 and 15.5
    }

    pthread_mutex_unlock(&mutex);

    return 0; // Success
}
```

### Key Points:
- **Concurrency**: The function uses a mutex to ensure thread-safe access.
- **Gaussian Distribution**: Utilizes the Box-Muller transform for generating Gaussian-distributed RSRP values.
- **Error Handling**: Checks for invalid input parameters and returns an error code if any are detected.
- **Efficiency**: Minimizes memory allocations by directly populating the provided array.']

