#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct PacketMetadata {
    int packetSequenceNumber;
    time_t packetTimestamp;
    struct PacketMetadata* next;
} PacketMetadata;

typedef struct DynamicValueGenerator {
    float minFloat, maxFloat;
    int minInt, maxInt;

    void (*setRange)(struct DynamicValueGenerator*, float, float, int, int);
    float (*generateRandomFloatInclusive)(struct DynamicValueGenerator*);
    float (*generateRandomFloatExclusive)(struct DynamicValueGenerator*);
    int (*generateRandomIntInclusive)(struct DynamicValueGenerator*);
    int (*generateRandomIntExclusive)(struct DynamicValueGenerator*);
    void (*readAndAnalyzeValues)(struct DynamicValueGenerator*);
    const char* (*toString)(const struct DynamicValueGenerator*);

} DynamicValueGenerator;

void setRange(DynamicValueGenerator* generator, float minFloat, float maxFloat, int minInt, int maxInt) {
    if (minFloat >= maxFloat || minInt >= maxInt) {
        fprintf(stderr, "Invalid range\n");
        exit(EXIT_FAILURE);
    }
    generator->minFloat = minFloat;
    generator->maxFloat = maxFloat;
    generator->minInt = minInt;
    generator->maxInt = maxInt;
}

float generateRandomFloatInclusive(DynamicValueGenerator* generator) {
    return (generator->minFloat + ((float)rand() / RAND_MAX) * (generator->maxFloat - generator->minFloat));
}

float generateRandomFloatExclusive(DynamicValueGenerator* generator) {
    float value = generateRandomFloatInclusive(generator);
    if (value == generator->maxFloat)
        value -= 1.0f / (RAND_MAX + 1.0f);
    return value;
}

int generateRandomIntInclusive(DynamicValueGenerator* generator) {
    return generator->minInt + rand() % (generator->maxInt - generator->minInt + 1);
}

int generateRandomIntExclusive(DynamicValueGenerator* generator) {
    int range = generator->maxInt - generator->minInt;
    if (range <= 0) {
        fprintf(stderr, "Invalid integer range\n");
        exit(EXIT_FAILURE);
    }
    return generator->minInt + rand() % range;
}

void readAndAnalyzeValues(DynamicValueGenerator* generator) {
    int value, largestValid = generator->minInt - 1;
    printf("Enter integers (type 'end' to finish):\n");
    while (scanf("%d", &value) == 1) {
        if (value >= generator->minInt && value < generator->maxInt) {
            if (value > largestValid)
                largestValid = value;
        }
    }
    printf("Largest valid integer: %d\n", largestValid);
}

const char* toString(const DynamicValueGenerator* generator) {
    static char buffer[128];
    snprintf(buffer, sizeof(buffer), "Float range: [%f, %f], Int range: [%d, %d]", 
             generator->minFloat, generator->maxFloat, generator->minInt, generator->maxInt);
    return buffer;
}

typedef struct UserSessionData {
    unsigned int sessionID;
    char* connectionState;
    PacketMetadata* packetMetadataHead;
    DynamicValueGenerator valueGenerator;
} UserSessionData;

UserSessionData* initializeSessionData(unsigned int sessionId, const char* defaultConnectionState, 
                                       int maxPacketEntries, float minFloatRange, float maxFloatRange,
                                       int minIntRange, int maxIntRange) {

    if (maxPacketEntries <= 0 || minFloatRange >= maxFloatRange || minIntRange >= maxIntRange)
        return NULL;

    UserSessionData* session = (UserSessionData*)malloc(sizeof(UserSessionData));
    if (!session) return NULL;

    session->sessionID = sessionId;
    session->connectionState = strdup(defaultConnectionState);
    if (!session->connectionState) {
        free(session);
        return NULL;
    }

    session->packetMetadataHead = NULL;

    srand(time(NULL));  // Seed the random number generator

    DynamicValueGenerator* generator = &session->valueGenerator;
    generator->setRange = setRange;
    generator->generateRandomFloatInclusive = generateRandomFloatInclusive;
    generator->generateRandomFloatExclusive = generateRandomFloatExclusive;
    generator->generateRandomIntInclusive = generateRandomIntInclusive;
    generator->generateRandomIntExclusive = generateRandomIntExclusive;
    generator->readAndAnalyzeValues = readAndAnalyzeValues;
    generator->toString = toString;

    if (!generator->setRange(generator, minFloatRange, maxFloatRange, minIntRange, maxIntRange)) {
        free(session->connectionState);
        free(session);
        return NULL;
    }

    for (int i = 0; i < maxPacketEntries; ++i) {
        PacketMetadata* packetMeta = (PacketMetadata*)malloc(sizeof(PacketMetadata));
        if (!packetMeta) break;

        packetMeta->packetSequenceNumber = i + 1;
        packetMeta->packetTimestamp = time(NULL);
        packetMeta->next = session->packetMetadataHead;
        session->packetMetadataHead = packetMeta;
    }

    return session;
}

void freeSessionData(UserSessionData* session) {
    if (!session) return;

    PacketMetadata* current = session->packetMetadataHead;
    while (current) {
        PacketMetadata* temp = current;
        current = current->next;
        free(temp);
    }

    free(session->connectionState);
    free(session);
}
