#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define MAX_PACKETS_PER_SESSION 100

typedef struct {
    int packetSequenceNumber;
    time_t packetTimestamp;
} PacketMetadata;

typedef struct {
    int sessionID;
    char connectionState; // 'U' for Up, 'D' for Down (default)
    PacketMetadata *packetList[MAX_PACKETS_PER_SESSION];
} UserSessionData;

typedef struct {
    UserSessionData *sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} SessionManager;

static int nextSessionID = 0;
pthread_mutex_t idLock;

void initializePacketMetadata(PacketMetadata *metadata, int sequenceNumber) {
    metadata->packetSequenceNumber = sequenceNumber;
    metadata->packetTimestamp = time(NULL);
}

UserSessionData* allocateUserSessionData() {
    UserSessionData *session = (UserSessionData*)malloc(sizeof(UserSessionData));
    if (!session) return NULL;

    pthread_mutex_lock(&idLock);
    session->sessionID = nextSessionID++;
    pthread_mutex_unlock(&idLock);

    session->connectionState = 'U'; // Default connection state

    for (int i = 0; i < MAX_PACKETS_PER_SESSION; ++i) {
        session->packetList[i] = NULL;
    }

    return session;
}

void freeUserSessionData(UserSessionData *session) {
    if (!session) return;

    for (int i = 0; i < MAX_PACKETS_PER_SESSION; ++i) {
        if (session->packetList[i]) {
            free(session->packetList[i]);
        }
    }

    free(session);
}

void initializeSessionManager(SessionManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        manager->sessions[i] = NULL;
    }
}

UserSessionData* createSession(SessionManager *manager) {
    UserSessionData *session = allocateUserSessionData();
    if (!session) return NULL;

    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] == NULL) {
            manager->sessions[i] = session;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    return session;
}

void deleteSession(SessionManager *manager, int sessionID) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->sessionID == sessionID) {
            freeUserSessionData(manager->sessions[i]);
            manager->sessions[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void addPacketMetadata(UserSessionData *session, int packetSequenceNumber) {
    if (!session) return;

    for (int i = 0; i < MAX_PACKETS_PER_SESSION; ++i) {
        if (session->packetList[i] == NULL) {
            session->packetList[i] = (PacketMetadata*)malloc(sizeof(PacketMetadata));
            if (session->packetList[i]) {
                initializePacketMetadata(session->packetList[i], packetSequenceNumber);
            }
            break;
        }
    }
}

void cleanupSessionManager(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (manager->sessions[i]) {
            freeUserSessionData(manager->sessions[i]);
            manager->sessions[i] = NULL;
        }
    }
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

int main() {
    SessionManager manager;
    initializeSessionManager(&manager);

    UserSessionData *session1 = createSession(&manager);
    if (session1) {
        addPacketMetadata(session1, 1);
        printf("Created session %d\n", session1->sessionID);
    }

    deleteSession(&manager, session1->sessionID);
    cleanupSessionManager(&manager);

    return 0;
}
