    PacketNode* packetListHead;
    UserSessionData userData;
} SessionData;

SessionData* initializeSessionData(unsigned int maxPackets) {
    SessionData* session = (SessionData*)malloc(sizeof(SessionData));
    if (!session) {
        perror("Failed to allocate memory for session");
        exit(EXIT_FAILURE);
    }

    session->sessionID = rand();  // Random unique ID
    session->connectionState = 'INIT';  // Default state

    session->packetListHead = NULL;

    setDynamicValueGenerator(&session->userData, 0.0f, 100.0f, 0, 100);

    srand(time(NULL));

    for (unsigned int i = 0; i < maxPackets; ++i) {
        PacketNode* newNode = (PacketNode*)malloc(sizeof(PacketNode));
        if (!newNode) {
            perror("Failed to allocate memory for packet node");
            // Cleanup allocated nodes before exiting
            while (session->packetListHead != NULL) {
                PacketNode* temp = session->packetListHead;
                session->packetListHead = session->packetListHead->next;
                free(temp);
            }
            free(session);
            exit(EXIT_FAILURE);
        }

        newNode->data.packetSequenceNumber = i + 1;
        newNode->data.packetTimestamp = time(NULL);

        // Link the new node
        newNode->next = session->packetListHead;
        session->packetListHead = newNode;
    }

    return session;
}

void freeSessionData(SessionData* session) {
    PacketNode* current = session->packetListHead;
    while (current != NULL) {
        PacketNode* temp = current;
        current = current->next;
        free(temp);
    }
    free(session);
}
```

This implementation provides a robust setup for managing user sessions and packet metadata in a high-performance network application. The code includes error handling, dynamic memory allocation, and ensures efficient management of resources while allowing flexible configuration of value ranges through `DynamicValueGenerator`.']

