// Define a structure for Network Parameter.
typedef struct NetworkParameter {
    char* parameterName;
    double parameterValue;
    char* parameterUnit;
    unsigned int crcChecksum;
    struct NetworkParameter* next;
} NetworkParameter;

// Define the Dynamic Value Validator with methods.
typedef struct {
    double minValue;
    double maxValue;
    int inclusive;

    void (*validateAndSet)(double value, double* out_value);
    void (*AnalyzeNetworkData)(const double* data_array, size_t length, double* out_average);
    char* (*ToString)(void* validator);
} DynamicValueValidator;

// Validate and set the parameter value within defined range.
void validateAndSet(double value, double *out_value) {
    // Example validation logic
    if (value >= minValue && (inclusive || value > minValue)) &&
       (value <= maxValue && (inclusive || value < maxValue))) {
        *out_value = value;
    } else {
        fprintf(stderr, "Value %f is out of range.\n", value);
    }
}

// Analyze and process network data to calculate the average.
void analyzeNetworkData(const double* data_array, size_t length, double* out_average) {
    double sum = 0.0;
    size_t valid_count = 0;

    for (size_t i = 0; i < length; ++i) {
        if (data_array[i] >= minValue && (inclusive || data_array[i] > minValue)) &&
           (data_array[i] <= maxValue && (inclusive || data_array[i] < maxValue))) {
            sum += data_array[i];
            valid_count++;
        }
    }

    *out_average = valid_count ? sum / valid_count : 0.0;
}

// Convert validator settings to a string representation.
char* toString(void* validator) {
    DynamicValueValidator* val = (DynamicValueValidator*)validator;
    char buffer[256];

    snprintf(buffer, sizeof(buffer), "Min: %f, Max: %f, Inclusive: %d",
             val->minValue, val->maxValue, val->inclusive);

    char* result = strdup(buffer);
    if (!result) {
        fprintf(stderr, "Failed to allocate memory for ToString.\n");
    }
    return result;
}

// Define the Network Config structure.
typedef struct {
    char* deviceID;
    char networkMode[32];
    DynamicValueValidator dynamicValidator;

    // Linked list head for network parameters
    NetworkParameter *parameterListHead;
} NetworkConfig;

// Function to create and configure a new NetworkConfig instance.
NetworkConfig* configureNetworkSettings(const char* deviceID, unsigned int maxParameters) {
    if (deviceID == NULL || strlen(deviceID) > 255) {
        fprintf(stderr, "Invalid device ID provided.\n");
        return NULL;
    }

    NetworkConfig *config = (NetworkConfig *)malloc(sizeof(NetworkConfig));
    if (!config) {
        perror("Failed to allocate memory for NetworkConfig");
        return NULL;
    }

    config->deviceID = strdup(deviceID);
    if (!config->deviceID) {
        free(config);
        perror("Failed to allocate memory for device ID");
        return NULL;
    }

    snprintf(config->networkMode, sizeof(config->networkMode), "DEFAULT_MODE");

    // Initialize Dynamic Value Validator
    config->dynamicValidator.minValue = 0.0;   // Set default min value
    config->dynamicValidator.maxValue = 100.0; // Set default max value
    config->dynamicValidator.inclusive = 1;

    config->dynamicValidator.validateAndSet = validateAndSet;
    config->dynamicValidator.AnalyzeNetworkData = analyzeNetworkData;
    config->dynamicValidator.ToString = toString;

    // Initialize parameter list head to NULL.
    config->parameterListHead = NULL;

    // Allow for dynamic addition of parameters
    size_t count = 0;
    while (count < maxParameters) {
        NetworkParameter* param = (NetworkParameter *)malloc(sizeof(NetworkParameter));
        if (!param) {
            perror("Failed to allocate memory for Network Parameter");
            break; // Exit loop on allocation failure.
        }

        // Default initialization
        param->parameterName = NULL;
        param->parameterValue = 0.0;
        param->parameterUnit = NULL;
        param->crcChecksum = 0;
        param->next = config->parameterListHead;

        config->parameterListHead = param; // Add to head of list.
        count++;
    }

    if (count < maxParameters) {
        fprintf(stderr, "Memory allocation issue: Only %zu parameters could be added.\n", count);
    }

    return config;
}
