    return sessionData;
}

int generateRandomInteger(DynamicValueGenerator* generator) {
    if (generator->minInt > generator->maxInt)
        return -1; // Indicating error
    return rand() % (generator->maxInt - generator->minInt + 1) + generator->minInt;
}

float generateRandomFloat(DynamicValueGenerator* generator) {
    float scale = generator->maxFloat - generator->minFloat;
    float random_float = (rand() / (RAND_MAX + 1.0)) * scale + generator->minFloat;
    return random_float;
}
