#define LOG_BUFFER_SIZE 1024

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    static char log_buffer[LOG_BUFFER_SIZE];
    pthread_mutex_lock(&mutex);
    snprintf(log_buffer, sizeof(log_buffer), "%s\n", message);
    printf("%s", log_buffer);  // Replace with actual logging mechanism
    pthread_mutex_unlock(&mutex);
}

int validate_frame(const RadioFrame *frame) {
    if (!frame) return 0;
    // Add validation logic here (e.g., check CRC, signal strength)
    return 1;  // Return 1 if valid, 0 otherwise
}

void process_frame(RadioFrame *frame) {
    pthread_mutex_lock(&mutex);
    if (!validate_frame(frame)) {
        log_message("Invalid frame detected");
        pthread_mutex_unlock(&mutex);
        free(frame);  // Cleanup on invalid frame
        return;
    }
    // Process the frame (e.g., further CRC checks, data extraction)
    log_message("Frame processed successfully");

    // Example of processing logic...

    pthread_mutex_unlock(&mutex);
}

void cleanup_memory(RadioFrame *frame) {
    if (frame) free(frame);
}

RadioFrame* allocate_frame() {
    RadioFrame *frame = malloc(sizeof(RadioFrame));
    if (!frame) {
        log_message("Memory allocation failed");
        return NULL;
    }
    memset(frame, 0, sizeof(RadioFrame));  // Initialize the frame
    return frame;
}

void processing_pipeline(int num_frames, int async_mode) {
    for (int i = 0; i < num_frames; ++i) {
        RadioFrame *frame = allocate_frame();
        if (!frame) continue;

        pthread_t thread_id;
        if (async_mode) {
            // Asynchronous mode: create a new thread to process each frame
            if (pthread_create(&thread_id, NULL, (void*(*)(void*))process_frame, (void*)frame)) {
                log_message("Thread creation failed");
                cleanup_memory(frame);
                continue;
            }
            pthread_detach(thread_id);  // Detach the thread for independent processing
        } else {
            // Synchronous mode: process frame in main thread
            process_frame(frame);
        }

        // Periodic memory cleanup logic can be implemented here...
    }
}

int main() {
    int num_frames = 10;  // Example number of frames to process
    int async_mode = 1;   // Set to 0 for synchronous, 1 for asynchronous

    processing_pipeline(num_frames, async_mode);

    return 0;
}
