import threading

typedef struct NL_PDU {
    char *source_address;
    char *destination_address;
    char *payload;
    unsigned int payload_length;
    unsigned int checksum;
    struct NL_PDU *next;
} NL_PDU;

// Function to calculate checksum (simple example, replace with actual algorithm)
unsigned int calculate_checksum(const char *data, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

// Function to initialize and populate the linked list
NL_PDU* init_nlpdu_list(int M, const char *predefined_checksum_value) {
    NL_PDU *head = NULL;
    NL_PDU **current = &head;

    // Mutex for thread safety
    threading.Lock lock

    for (int i = 0; i < M; ++i) {
        // Allocate memory for a new NL_PDU
        NL_PDU *new_pdu = malloc(sizeof(NL_PDU));
        if (!new_pdu) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Example data (replace with actual network layer data)
        char *src_addr = strdup("192.168.1.1");  // Replace with dynamic source address
        char *dst_addr = strdup("10.0.0.1");     // Replace with dynamic destination address
        size_t payload_length = rand() % 256;    // Example variable length, replace as needed
        char *payload = malloc(payload_length);

        if (!src_addr || !dst_addr || !payload) {
            free(new_pdu);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // Copy and generate payload data (example)
        for (size_t j = 0; j < payload_length; ++j) {
            payload[j] = rand() % 256;  // Random data for example
        }

        // Calculate checksum of the payload
        unsigned int calculated_checksum = calculate_checksum(payload, payload_length);

        lock.acquire()
        try:
            new_pdu->source_address = src_addr;
            new_pdu->destination_address = dst_addr;
            new_pdu->payload = payload;
            new_pdu->payload_length = (unsigned int)payload_length;
            new_pdu->checksum = calculated_checksum;
            new_pdu->next = NULL;

            // Verify integrity of the payload
            if (calculated_checksum != strtoul(predefined_checksum_value, NULL, 10)) {
                fprintf(stderr, "Checksum mismatch\n");
                free(new_pdu);
                continue;  // Skip adding this NL_PDU to the list
            }

            *current = new_pdu;
            current = &new_pdu->next;
        finally:
            lock.release()
    }

    return head;
}
```

This code initializes a linked list of `NL_PDU` structures, dynamically allocating memory for each and ensuring that payloads are validated with checksums before insertion. The function uses thread-safe operations to ensure concurrent access is handled properly in multithreaded environments.']

