// Initialize the dynamic array with N elements
int initialize_dynamic_array(DynamicArray *dynArr, size_t N, int seed) {
    dynArr->max_capacity = N > 0 ? N : 1; // Avoid zero allocation
    dynArr->current_size = 0;
    dynArr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(dynArr->max_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!dynArr->array) {
        return -1; // Allocation failed
    }

    srand(seed);
    for (size_t i = 0; i < N; ++i) {
        dynArr->array[i].RX_UE_INFORMATION_TAG = seed + i;
        dynArr->array[i].RNTI = rand() % 100000;
    }

    return 0; // Success
}

// Populate elements with unique RX_UE_INFORMATION_TAG and RNTI, set CRCFLAG randomly
void populate_dynamic_array(DynamicArray *dynArr) {
    int crc_flag_count = 0;
    for (size_t i = 0; i < dynArr->current_size; ++i) {
        dynArr->array[i].RNTI = rand() % 100000;
        if ((rand() % 2 == 1 && crc_flag_count * 2 <= dynArr->current_size) ||
