['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>

#define INITIAL_CAPACITY 1000
#define MAX_TRANSACTIONS 5000

typedef struct {
    uint64_t frameID;
    time_t timestamp;
    char* payload;
} MAC_FRAME;

typedef enum {
    STATUS_SUCCESS,
    STATUS_FAILURE
} TransactionStatus;

typedef struct {
    uint32_t transactionID;
    char sourceIP[16];
    char destinationIP[16];
    size_t payloadSize;
    TransactionStatus status;
    MAC_FRAME *macFrame;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} TransactionPool;

// Forward declarations for helper functions
int validate_transactionID(Transaction *pool, uint32_t id);
void rotate_log_file(const char* log_filename);

TransactionPool* initialize_pool() {
    TransactionPool* pool = (TransactionPool*)malloc(sizeof(TransactionPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->mutex, NULL);
    pool->transactions = (Transaction*)malloc(INITIAL_CAPACITY * sizeof(Transaction));
    if (!pool->transactions) {
        free(pool);
        return NULL;
    }
    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;

    // Initialize logging
    FILE* log_file = fopen("transaction_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fclose(log_file);

    return pool;
}

int add_transaction(TransactionPool *pool, uint32_t transactionID,
                    const char *sourceIP, const char *destinationIP,
                    TransactionStatus status) {
    pthread_mutex_lock(&pool->mutex);

    if (validate_transactionID(pool, transactionID)) {
        fprintf(stderr, "Invalid or duplicate transaction ID\n");
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        if (new_capacity > MAX_TRANSACTIONS) new_capacity = MAX_TRANSACTIONS;

        Transaction* new_transactions = (Transaction*)realloc(pool->transactions, new_capacity * sizeof(Transaction));
        if (!new_transactions) {
            pthread_mutex_unlock(&pool->mutex);
            return -1; // Memory allocation failed
        }

        pool->transactions = new_transactions;
        pool->capacity = new_capacity;
    }

    Transaction* transaction = &pool->transactions[pool->count];
    transaction->transactionID = transactionID;
    strncpy(transaction->sourceIP, sourceIP, sizeof(transaction->sourceIP) - 1);
    strncpy(transaction->destinationIP, destinationIP, sizeof(transaction->destinationIP) - 1);

    transaction->payloadSize = rand() % (1024 * 1024); // Random payload size up to 1MB
    transaction->macFrame = (MAC_FRAME*)malloc(sizeof(MAC_FRAME));
    if (!transaction->macFrame) {
        pthread_mutex_unlock(&pool->mutex);
        return -2; // Memory allocation failed for MAC_FRAME
    }

    transaction->macFrame->frameID = rand();
    gettimeofday((struct timeval*)&transaction->macFrame->timestamp, NULL);

    transaction->macFrame->payload = (char*)malloc(transaction->payloadSize);
    if (!transaction->macFrame->payload) {
        free(transaction->macFrame);
        pthread_mutex_unlock(&pool->mutex);
        return -3; // Memory allocation failed for payload
    }

    memset(transaction->macFrame->payload, rand() % 256, transaction->payloadSize);

    transaction->status = status;
    pool->count++;

    pthread_mutex_unlock(&pool->mutex);

    // Log the new transaction
    FILE* log_file = fopen("transaction_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "Transaction ID: %u, Source IP: %s, Destination IP: %s, Status: %d\n",
                transactionID, sourceIP, destinationIP, status);
        fclose(log_file);

        // Check log file size and rotate if necessary
        struct stat st;
        stat("transaction_log.txt", &st);
        if (st.st_size > 10 * 1024 * 1024) { // Rotate if larger than 10MB
            rotate_log_file("transaction_log.txt");
        }
    }

    return 0; // Success
}

int validate_transactionID(Transaction *transactions, size_t count, uint32_t id) {
    for (size_t i = 0; i < count; ++i) {
        if (transactions[i].transactionID == id) {
            return 1; // Duplicate ID found
        }
    }
    return id <= 0 || id > UINT32_MAX ? 1 : 0; // Invalid ID check
}

void rotate_log_file(const char* log_filename) {
    char new_name[256];
    time_t now = time(NULL);
    snprintf(new_name, sizeof(new_name), "%s.%ld", log_filename, now);

    rename(log_filename, new_name);

    FILE* log_file = fopen(log_filename, "w");
    if (log_file) fclose(log_file);
}

void destroy_pool(TransactionPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->transactions[i].macFrame->payload);
        free(pool->transactions[i].macFrame);
    }
    free(pool->transactions);
    pthread_mutex_unlock(&pool->mutex);

    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

// Example usage (should be wrapped in appropriate threading logic for real use)
int main() {
    TransactionPool *pool = initialize_pool();
    if (!pool) return EXIT_FAILURE;

    // Simulate adding transactions
    for (uint32_t i = 1; i <= 5000; ++i) {
        char sourceIP[16] = "192.168.0.1";
        char destinationIP[16] = "192.168.0.2";

        int result = add_transaction(pool, i, sourceIP, destinationIP, STATUS_SUCCESS);
        if (result != 0) break;
    }

    destroy_pool(pool);
    return EXIT_SUCCESS;
}
```

This code defines a `TransactionPool` to manage transactions efficiently in a multi-threaded application. It handles memory allocation dynamically and ensures thread safety with mutex locks. The logging mechanism rotates log files when they exceed a specified size, preventing bottlenecks. This solution considers typical and peak workloads for optimal performance and maintainability.']

