#define MAX_ARRAY_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int valid_RX_UE_INFORMATION_TAG; // Just a flag for simplicity
    int valid_RNTI;                   // Just a flag for simplicity
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    INVALID_INPUT,
    ALLOCATION_FAILURE,
    THREAD_SYNC_ERROR,
    MEMORY_CLEANUP_ERROR
} ErrorCode;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int allocation_count = 0;
static int failure_count = 0;

void log_message(const char* message) {
    printf("%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(int num_elements, int *out_count, ErrorCode *error_code) {
    if (num_elements <= 0 || num_elements > MAX_ARRAY_SIZE) {
        *error_code = INVALID_INPUT;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = ALLOCATION_FAILURE;
        failure_count++;
        log_message("Memory allocation failed.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_elements; ++i) {
        array[i].valid_RX_UE_INFORMATION_TAG = rand() % 2; // Randomly set as valid or invalid
        array[i].valid_RNTI = rand() % 2;

        if (!array[i].valid_RX_UE_INFORMATION_TAG || !array[i].valid_RNTI) {
            for (int j = 0; j < i; ++j) {
                free(&array[j]);
            }
            free(array);
            *error_code = INVALID_INPUT;
            failure_count++;
            pthread_mutex_unlock(&mutex);
            log_message("Invalid input detected during allocation.");
            return NULL;
        }

        array[i].crc_tag.RX_UE_INFORMATION_TAG = rand();
        array[i].crc_tag.RNTI = rand();
        array[i].crc_tag.crc_flag = rand() % 2; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&mutex);

    *out_count = num_elements;
    allocation_count++;
    log_message("Allocation successful.");
    *error_code = SUCCESS;

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    if (array != NULL) {
        free(array);
        log_message("Memory freed successfully.");
    } else {
        log_message("Attempted to free a NULL pointer.");
    }
}
