#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int NR_RX_UE_INFO_TAG;
    int RNTI;
    int CRC_INDICATION_TAG;
    int CRC_flag;
} NR_PDU_T;

// Pool for managing memory allocations
typedef struct {
    size_t item_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock; // Mutex for thread safety
} MemoryPool;

// Function to initialize the memory pool
void initMemoryPool(MemoryPool *mp, size_t item_size, size_t pool_size) {
    mp->item_size = item_size;
    mp->pool_size = pool_size;
    mp->pool = malloc(pool_size);
    pthread_mutex_init(&mp->lock, NULL);
}

// Function to free the memory pool
void freeMemoryPool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

// Thread-safe function for allocating a block from the pool
void* allocateFromPool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->pool_size >= mp->item_size) {
        void *ptr = (char*)mp->pool + (mp->pool_size - mp->item_size);
        mp->pool_size -= mp->item_size;
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Out of memory
}

NR_PDU_T* initializeAndPopulatePDUArray(size_t num_pdus, MemoryPool *mp) {
    if (!num_pdus || !mp) {
        return NULL; // Invalid input parameters
    }

    NR_PDU_T *pdu_array = malloc(num_pdus * sizeof(NR_PDU_T));
    if (!pdu_array) {
        return NULL; // Out of memory
    }

    size_t i;
    for (i = 0; i < num_pdus; ++i) {
        NR_PDU_T *new_pdu = (NR_PDU_T*)allocateFromPool(mp);
        if (!new_pdu) {
            break; // Stop on allocation failure, partial completion allowed
        }

        new_pdu->NR_RX_UE_INFO_TAG = rand() % 1000;
        new_pdu->RNTI = rand() % 5000;
        new_pdu->CRC_INDICATION_TAG = (rand() % 2) ? 1 : 0; // Random CRC flag
        pdu_array[i] = *new_pdu;
    }

    return i == num_pdus ? pdu_array : realloc(pdu_array, i * sizeof(NR_PDU_T));
}

// Example usage:
int main() {
    MemoryPool mp;
    initMemoryPool(&mp, sizeof(NR_PDU_T), 1024 * sizeof(NR_PDU_T)); // Pool for 1024 NR_PDU_T items

    size_t num_pdus = 100; // Example: allocate space for 100 PDUs
    NR_PDU_T* pdu_array = initializeAndPopulatePDUArray(num_pdus, &mp);

    if (pdu_array) {
        printf("Successfully allocated %zu PDUs\n", (size_t)(sizeof(pdu_array) / sizeof(NR_PDU_T)));
    } else {
        printf("Failed to allocate PDUs\n");
    }

    freeMemoryPool(&mp);
    free(pdu_array); // Free the allocated array
    return 0;
}
