// Structure for linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function declarations
bool create_linked_list(size_t num_structures, Node** head);
void insert_sorted(Node** head, NFAPI_CRC_INDICATION_PDU_T new_data);
bool is_rnti_unique(Node* head, uint16_t rnti);
void free_list(Node* head);
