// Main function to create and manage the list
bool create_linked_list(size_t num_structures, Node** head) {
    if (num_structures > MAX_STRUCTURES) {
        log_error("Requested number of structures exceeds limit.");
        return false;
    }

    // Initialize head as NULL
    *head = NULL;

    for (size_t i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T new_data;

        // Simulate valid RX_UE_INFORMATION_TAG and RNTI generation
        new_data.RX_UE_INFORMATION_TAG = rand() % 10000; // Example range for demonstration
        do {
            new_data.RNTI = (uint16_t)(rand() % MAX_STRUCTURES); // Ensure unique RNTI in the given context
        } while (!is_rnti_unique(*head, new_data.RNTI));

        // Randomly set CRCFLAG
        new_data.CRCFLAG = rand() % 2;

        insert_sorted(head, new_data);
    }

    return true;
}

// Insert node into linked list in sorted order by RNTI
void insert_sorted(Node** head, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for a new node.");
        free_list(*head);
        exit(EXIT_FAILURE); // Exit if unable to allocate memory
    }

    new_node->data = new_data;
    new_node->next = NULL;

    if (*head == NULL || (*head)->data.RNTI > new_data.RNTI) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->data.RNTI < new_data.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

// Check if an RNTI value is unique within the list
bool is_rnti_unique(Node* head, uint16_t rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return false;
        current = current->next;
    }
    return true;
}

// Free all nodes in the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Log error messages to stderr or a logging system
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
