AssociationList* create_association_list() {
    AssociationList* list = (AssociationList*)malloc(sizeof(AssociationList));
    if (!list) return NULL;

    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    return list;
}

void destroy_association_list(AssociationList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.channelQualities);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_association_request(AssociationList* list, WIFI_AP_ASSOCIATION_REQUEST req) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    memcpy(&new_node->data, &req, sizeof(WIFI_AP_ASSOCIATION_REQUEST));

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void remove_association_request(AssociationList* list, ASSOC_REQ_INFO assocReqInfo) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (memcmp(&(current->data.assocReqInfo), &assocReqInfo, sizeof(ASSOC_REQ_INFO)) == 0) {
            if (prev == NULL)
                list->head = current->next;
            else
                prev->next = current->next;

            free(current->data.channelQualities);
            free(current);

            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void update_channel_status(AssociationList* list, ASSOC_REQ_INFO assocReqInfo, AP_CHANNEL_STATUS newStatus) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (memcmp(&(current->data.assocReqInfo), &assocReqInfo, sizeof(ASSOC_REQ_INFO)) == 0) {
            memcpy(&(current->data.channelStatus), &newStatus, sizeof(AP_CHANNEL_STATUS));
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

