        list.pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        list.pdu_list[i].RNTI = rand() % 65536;
        list.pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;
    }

    int dns_result = resolve_dns_non_blocking(hostname, ip_array);
    if (dns_result != 0) {
        fprintf(stderr, "DNS resolution failed\n");
        free(list.pdu_list);
        return (NFAPICRCIndicationList){NULL, 0};
    }

    list.count = n;
    pthread_join(dns_thread, NULL);

    printf("Resolved IP: %d.%d.%d.%d\n", ip_array[0], ip_array[1], ip_array[2], ip_array[3]);
    return list;
}

int resolve_dns_non_blocking(const char *hostname, u_char *ip_array) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *h = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(h->sin_addr), ip_array, sizeof(ip_array));
        break;
    }

    freeaddrinfo(res);
    return 0;
}

void *dns_resolution_thread(void *arg) {
    const char *hostname = (const char *)arg;
    u_char ip_array[4] = {0};
    if (resolve_dns_non_blocking(hostname, ip_array) != 0) {
        fprintf(stderr, "DNS resolution failed in thread\n");
    }
    return NULL;
}
