    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    // Write the number of records first
    fwrite(&n, sizeof(size_t), 1, file);

    // Serialize each structure into the file
    size_t written = fwrite(pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU_T), n, file);
    if (written != n) {
        perror("Failed to write all data to file");
        fclose(file);
        return -1;
    }

