    char hostname[MAX_HOSTNAME_LENGTH];
    unsigned char ip_address[4];  // IPv4 address
    int status;                   // -1: unresolved, 0: resolved, 1: error
} HostnameResolutionResult;

static void on_resolve(uv_getaddrinfo_t *resolver_req, int status, struct addrinfo *res);
static void free_addr_info(struct addrinfo *ai);
static void log_error(const char *message);

void configure_dns_resolver(DNSResolverContext *context, uv_loop_t *loop) {
    context->loop = loop;
    pthread_mutex_init(&context->resolver_lock, NULL);
    for (int i = 0; i < MAX_CONCURRENT_RESOLVES; ++i) {
        context->resolver_reqs[i] = malloc(sizeof(*context->resolver_reqs[i]));
        uv_getaddrinfo_t *req = context->resolver_reqs[i];
        req->data = (void*)(intptr_t)i;
    }
}

void start_dns_resolution(DNSResolverContext *ctx, const char *hostname) {
    pthread_mutex_lock(&ctx->resolver_lock);

    int resolver_index = -1;
    for (int i = 0; i < MAX_CONCURRENT_RESOLVES; ++i) {
        if (!ctx->resolver_reqs[i]->handle.data) {  // Find an available slot
            resolver_index = i;
            break;
        }
    }

    if (resolver_index == -1) {
        log_error("Max concurrent DNS resolutions reached");
        pthread_mutex_unlock(&ctx->resolver_lock);
        return;
    }

    uv_getaddrinfo_t *req = ctx->resolver_reqs[resolver_index];
    struct addrinfo hints = {0};
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    req->data = (void*)(intptr_t)resolver_index;
    int r = uv_getaddrinfo(ctx->loop, req, on_resolve,
                           hostname, "http", &hints);

    if (r) {
        log_error("getaddrinfo() failed");
    }

    pthread_mutex_unlock(&ctx->resolver_lock);
}

static void on_resolve(uv_getaddrinfo_t *resolver_req, int status, struct addrinfo *res) {
    int index = (int)(intptr_t)resolver_req->data;
    DNSResolverContext *ctx = resolver_req->handle.data;

    if (status == 0) {
        // Resolve was successful
        if (res != NULL && res->ai_addr != NULL) {
            struct sockaddr_in *addr = (struct sockaddr_in *)res->ai_addr;
            memcpy(ctx->resolver_reqs[index]->data, &addr->sin_addr.s_addr, sizeof(addr->sin_addr.s_addr));
            ((HostnameResolutionResult*)ctx->resolver_reqs[index]->data)->status = 0; // resolved
        } else {
            log_error("Address resolution returned no address");
        }
    } else {
        // Resolve failed
        ((HostnameResolutionResult*)ctx->resolver_reqs[index]->data)->status = 1;
    }

    free_addr_info(res);
}

static void free_addr_info(struct addrinfo *ai) {
    if (ai != NULL) uv_freeaddrinfo(ai);
}

static void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void cleanup_dns_resolver(DNSResolverContext *context) {
    pthread_mutex_lock(&context->resolver_lock);

    for (int i = 0; i < MAX_CONCURRENT_RESOLVES; ++i) {
        if (context->resolver_reqs[i] != NULL) {
            uv_free(context->resolver_reqs[i]);
            context->resolver_reqs[i] = NULL;
        }
    }

    pthread_mutex_unlock(&context->resolver_lock);
    pthread_mutex_destroy(&context->resolver_lock);
}

int main() {
    uv_loop_t *loop = malloc(sizeof(*loop));
    DNSResolverContext resolver_ctx;

    configure_dns_resolver(&resolver_ctx, loop);

    // Example: Start resolving hostnames
    start_dns_resolution(&resolver_ctx, "example.com");

    uv_run(loop, UV_RUN_DEFAULT);

    cleanup_dns_resolver(&resolver_ctx);
    free(loop);

    return 0;
}
```

### Key Considerations:
- **Concurrency**: The `DNSResolverContext` structure manages up to `MAX_CONCURRENT_RESOLVES` DNS requests.
- **Non-blocking I/O**: Uses libuv for asynchronous operations, allowing DNS resolution without blocking other tasks.
- **Error Handling & Logging**: Logs errors when exceeding maximum concurrent resolutions or failing to resolve a hostname.
- **Resource Management**: Allocates and cleans up resources properly to avoid leaks.

### Configuration Options:
- `MAX_CONCURRENT_RESOLVES` can be adjusted based on deployment needs.
- Timeout settings would typically be handled by configuring libuv's default options (`uv_default_loop_init`, etc.).

This code provides a starting point, but further enhancements could include DNS server configuration, IPv6 support, and more detailed logging/metrics.']

