#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct for TD Measurements
typedef struct {
    float timestamp;
    float power_level;
} TDM;

// Define a struct for LTE PHY layer measurement results
typedef struct {
    int valid_cell_identity; // CI
    int signal_quality_indicator; // SQI
    size_t td_measurements_count;
    TDM *td_measurements;
} LTE_Phy_Measurement;

// Function to initialize the dynamic array of measurements
LTE_Phy_Measurement* init_measurement_array(size_t initial_size) {
    if (initial_size == 0) {
        return NULL;
    }

    LTE_Phy_Measurement *measurements = (LTE_Phy_Measurement*) malloc(initial_size * sizeof(LTE_Phy_Measurement));
    if (!measurements) {
        fprintf(stderr, "Memory allocation failed for measurements array.\n");
        return NULL;
    }

    memset(measurements, 0, initial_size * sizeof(LTE_Phy_Measurement));
    return measurements;
}

// Function to resize the dynamic array of measurements
int resize_measurement_array(LTE_Phy_Measurement **measurements, size_t current_size, size_t new_size) {
    if (new_size == 0 || !measurements) {
        return -1; // Invalid input
    }

    LTE_Phy_Measurement *temp = (LTE_Phy_Measurement*) realloc(*measurements, new_size * sizeof(LTE_Phy_Measurement));
    if (!temp) {
        fprintf(stderr, "Memory reallocation failed for measurements array.\n");
        return -1;
    }

    *measurements = temp;
    memset((*measurements) + current_size, 0, (new_size - current_size) * sizeof(LTE_Phy_Measurement));
    return 0;
}

// Function to add or update a measurement result
int add_or_update_measurement(LTE_Phy_Measurement **measurements, size_t *size, int index, 
                              int ci, int sqi, TDM *td_measurements, size_t td_count) {
    if (!measurements || !(*measurements) || index < 0 || index >= *size) {
        return -1; // Invalid input
    }

    if (index == *size) { // Add new measurement
        if (resize_measurement_array(measurements, *size, (*size) + 1)) {
            return -1;
        }
    }

    LTE_Phy_Measurement *measurement = &(*measurements)[index];
    measurement->valid_cell_identity = ci;
    measurement->signal_quality_indicator = sqi;

    if (measurement->td_measurements) {
        free(measurement->td_measurements);
    }

    measurement->td_measurements_count = td_count;
    measurement->td_measurements = (TDM*) malloc(td_count * sizeof(TDM));

    if (!measurement->td_measurements) {
        fprintf(stderr, "Memory allocation failed for TD measurements.\n");
        return -1;
    }

    memcpy(measurement->td_measurements, td_measurements, td_count * sizeof(TDM));

    return 0;
}

// Function to retrieve a measurement result
int get_measurement(LTE_Phy_Measurement *measurements, size_t size, int index,
                    int *ci, int *sqi, TDM **td_measurements, size_t *td_count) {
    if (!measurements || index < 0 || index >= size || !ci || !sqi || !td_measurements || !td_count) {
        return -1; // Invalid input
    }

    LTE_Phy_Measurement measurement = measurements[index];

    *ci = measurement.valid_cell_identity;
    *sqi = measurement.signal_quality_indicator;

    if (measurement.td_measurements_count == 0) {
        *td_measurements = NULL;
        *td_count = 0;
    } else {
        *td_measurements = measurement.td_measurements;
        *td_count = measurement.td_measurements_count;
    }

    return 0;
}

// Function to clean up and free allocated memory
void cleanup_measurement_array(LTE_Phy_Measurement *measurements, size_t size) {
    if (!measurements) {
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        if (measurements[i].td_measurements) {
            free(measurements[i].td_measurements);
        }
    }

    free(measurements);
}

// Example usage
int main() {
    size_t initial_size = 10;
    LTE_Phy_Measurement *measurements = init_measurement_array(initial_size);
    if (!measurements) {
        return -1; // Failed to initialize measurements array
    }

    TDM td_data[] = {{1.0, -50.0}, {2.0, -45.0}};
    add_or_update_measurement(&measurements, &initial_size, 0, 123456789, 30,
                              td_data, sizeof(td_data) / sizeof(TDM));

    int ci, sqi;
    TDM *td_measurements = NULL;
    size_t td_count;

    get_measurement(measurements, initial_size, 0, &ci, &sqi, &td_measurements, &td_count);

    printf("CI: %d, SQI: %d\n", ci, sqi);

    for (size_t i = 0; i < td_count; ++i) {
        printf("Timestamp: %.2f, Power Level: %.2f\n", td_measurements[i].timestamp, td_measurements[i].power_level);
    }

    cleanup_measurement_array(measurements, initial_size);

    return 0;
}
```']

