        if (cached_RX_TAG == -1 || cached_RNTI == -1) {
            array[i].RX_UE_INFORMATION_TAG = get_RX_UE_INFORMATION_TAG();
            array[i].RNTI = get_RNTI();

            // Cache the values for future use
            cached_RX_TAG = array[i].RX_UE_INFORMATION_TAG;
            cached_RNTI = array[i].RNTI;
        } else {
            // Use cached data
            array[i].RX_UE_INFORMATION_TAG = cached_RX_TAG;
            array[i].RNTI = cached_RNTI;
