        pthread_mutex_unlock(&cache_lock);

        // Random CRC flag generation
        array[i].CRC_TAG.crc_flag = rand() % 2;  // Assume a binary flag for simplicity

        // Validate data (simple validation example)
        if (array[i].RX_UE_INFORMATION_TAG <= 0 || array[i].RNTI <= 0) {
            free(array);
            log_warning("Invalid UE information or RNTI.");
            return NULL;
        }
    }

