```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>

typedef struct {
    uint32_t RNTI;
    uint8_t CRCFLAG; // Assume this is a byte for simplicity
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    bool marked_for_deletion;
    struct Entry* next;
} Entry;

typedef struct {
    Entry* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t count;
} ThreadSafeList;

ThreadSafeList active_list = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};
ThreadSafeList pending_delete_list = {NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};

void list_lock(ThreadSafeList* list) {
    pthread_mutex_lock(&list->lock);
}

void list_unlock(ThreadSafeList* list) {
    pthread_mutex_unlock(&list->lock);
}

Entry* create_entry(NFAPI_CRC_INDICATION_PDU_T data) {
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return NULL;

    new_entry->data = data;
    new_entry->marked_for_deletion = false;
    new_entry->next = NULL;
    return new_entry;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T data) {
    list_lock(&active_list);
    Entry* new_entry = create_entry(data);

    if (new_entry) {
        new_entry->next = active_list.head;
        active_list.head = new_entry;
        active_list.count++;
    }

    list_unlock(&active_list);
}

NFAPI_CRC_INDICATION_PDU_T* get_entry_by_rnti(uint32_t rnti) {
    list_lock(&active_list);

    Entry* current = active_list.head;
    while (current) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* result = &current->data;
            list_unlock(&active_list);
            return result;
        }
        current = current->next;
    }

    list_unlock(&active_list);
    return NULL;
}

void mark_entry_for_deletion(uint32_t rnti) {
    list_lock(&active_list);

    Entry** curr = &active_list.head;
    while (*curr) {
        if ((*curr)->data.RNTI == rnti) {
            (*curr)->marked_for_deletion = true;

            // Move to pending delete list
            Entry* marked_entry = *curr;
            *curr = (*curr)->next;

            list_lock(&pending_delete_list);
            marked_entry->next = pending_delete_list.head;
            pending_delete_list.head = marked_entry;
            pending_delete_list.count++;
            list_unlock(&pending_delete_list);

            active_list.count--;
            break;
        }
        curr = &(*curr)->next;
    }

    list_unlock(&active_list);
}

void remove_entry_by_rnti(uint32_t rnti) {
    mark_entry_for_deletion(rnti);
}

void* cleanup_thread_func(void* arg) {
    while (1) {
        sleep(5); // Cleanup interval

        pthread_mutex_lock(&pending_delete_list.lock);

        Entry** curr = &pending_delete_list.head;
        while (*curr) {
            if ((*curr)->marked_for_deletion) {
                Entry* to_free = *curr;
                *curr = (*curr)->next;

                free(to_free);
                pending_delete_list.count--;
            } else {
                curr = &(*curr)->next;
            }
        }

        pthread_mutex_unlock(&pending_delete_list.lock);
    }
    return NULL;
}

void start_cleanup_thread() {
    pthread_t cleanup_thread_id;
    pthread_create(&cleanup_thread_id, NULL, cleanup_thread_func, NULL);
}

int main() {
    start_cleanup_thread();

    // Add a few test entries
    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1001, .tag = {.CRCFLAG = 0x01} };
    add_entry(pdu1);

    NFAPI_CRC_INDICATION_PDU_T* found_pdu = get_entry_by_rnti(1001);
    if (found_pdu) {
        printf("Found PDU with RNTI: %u\n", found_pdu->RNTI);
    }

    remove_entry_by_rnti(1001);

    return 0;
}
```

### Explanation:
- The `active_list` and `pending_delete_list` are used to manage active entries and those marked for deletion.
- The `add_entry`, `get_entry_by_rnti`, `mark_entry_for_deletion`, and `remove_entry_by_rnti` functions handle the core operations on these lists, ensuring thread safety using mutex locks.
- A background thread (`cleanup_thread_func`) periodically cleans up entries in the `pending_delete_list`.
- The function `start_cleanup_thread` initializes this cleanup process.']

