#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    unsigned int CRCFLAG; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int valid_crc_count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->valid_crc_count = 0;
    return list;
}

void destroy_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;

    if (entry.CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
        list->valid_crc_count++;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_entry(DynamicList* list, int RX_UE_INFORMATION_TAG, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            int old_crc_flag = current->data.CRC_INDICATION_REL8_TAG.CRCFLAG;
            current->data = new_data;

            if (new_data.CRC_INDICATION_REL8_TAG.CRCFLAG != 0 && old_crc_flag == 0) {
                list->valid_crc_count++;
            } else if (new_data.CRC_INDICATION_REL8_TAG.CRCFLAG == 0 && old_crc_flag != 0) {
                list->valid_crc_count--;
            }

            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

int remove_entry(DynamicList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }

            if (current->data.CRC_INDICATION_REL8_TAG.CRCFLAG != 0) {
                list->valid_crc_count--;
            }

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Entry not found
}

int get_valid_crc_count(DynamicList* list) {
    int count;
    pthread_mutex_lock(&list->lock);
    count = list->valid_crc_count;
    pthread_mutex_unlock(&list->lock);
    return count;
}
