    return 1; // Assume valid for this example
}

void add_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!validate_data(data)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
        new_node->next = NULL;
        new_node->prev = NULL;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        new_node->next = NULL;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *to_delete = NULL;

    while (current) {
        if (memcmp(&current->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            to_delete = current;
            break;
        }
        current = current->next;
    }

    if (to_delete) {
        if (to_delete->prev) to_delete->prev->next = to_delete->next;
        else list->head = to_delete->next;

        if (to_delete->next) to_delete->next->prev = to_delete->prev;
        else list->tail = to_delete->prev;

        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DoublyLinkedList* list, const char* filename, int compression_level) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;
    uLongf compressed_size = 0;

    // Prepare buffer for data
    while (current) {
        compressed_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    unsigned char *buffer = malloc(compressed_size);
    if (!buffer) return;

    size_t offset = 0;
    current = list->head;

    // Fill buffer with data
    while (current) {
        memcpy(buffer + offset, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    // Compress the buffer
    unsigned char *compressed_data = malloc(compressed_size);
    if (!compressed_data) {
        free(buffer);
        fclose(file);
        return;
    }

    compress2(compressed_data, &compressed_size, buffer, offset, compression_level);

    fwrite(compressed_size, sizeof(uLongf), 1, file);
    fwrite(compressed_data, compressed_size, 1, file);

    free(buffer);
    free(compressed_data);
    fclose(file);
}

void destroy_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
