}

// Function to add a node to the linked list
int add_to_list(NFAPI_RRC_PDU_T **head, unsigned int ue_id, pdu_type_t pdu_type) {
    pthread_mutex_lock(&list_mutex);

    if (!create_node(ue_id, pdu_type)) {
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    NFAPI_RRC_PDU_T *new_node = create_node(ue_id, pdu_type);
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

// Function to remove stale nodes
void cleanup_list(NFAPI_RRC_PDU_T **head, unsigned int threshold) {
    pthread_mutex_lock(&list_mutex);

    NFAPI_RRC_PDU_T **current = head;
    while (*current) {
        if ((*current)->RRC_PDU->flag < threshold) {
            NFAPI_RRC_PDU_T *to_free = *current;
            *current = (*current)->next;
            free(to_free->RRC_PDU);
            free(to_free);
        } else {
            current = &((*current)->next);
        }
    }

    pthread_mutex_unlock(&list_mutex);
