    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function prototypes
Node* initialize_node(NFAPI_CRC_INDICATION_PDU_T pdu);
void free_list(Node** head);
int read_binary_file(const char* filename, uint8_t** buffer, size_t* size);
size_t parse_data(uint8_t* buffer, size_t size, Node** list, int* valid_count, int* invalid_count);
Node* filter_by_rnti_range(Node* head, uint16_t rnti_min, uint16_t rnti_max);
void sort_list(Node** head);

// Function to manage NFAPI CRC indications
int process_nfaapi_crc_indications(const char* filename, Node** list, int valid_count, int invalid_count, uint16_t rnti_min, uint16_t rnti_max) {
    uint8_t* buffer = NULL;
    size_t buffer_size = 0;

    // Read binary file
    if (read_binary_file(filename, &buffer, &buffer_size) != 0) {
        fprintf(stderr, "Error reading file\n");
        return -1;
    }

    // Parse data from buffer
    *valid_count = 0;
    *invalid_count = 0;
    parse_data(buffer, buffer_size, list, valid_count, invalid_count);

    free(buffer); // Free the buffer after parsing

    // Filter by RNTI range if specified
    if (rnti_min != UINT16_MAX || rnti_max != UINT16_MAX) {
        *list = filter_by_rnti_range(*list, rnti_min, rnti_max);
    }

    // Sort the list by RNTI
    sort_list(list);

    return 0;
}

Node* initialize_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int read_binary_file(const char* filename, uint8_t** buffer, size_t* size) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    rewind(file);

    *buffer = (uint8_t*)malloc(*size);
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return -1;
    }

    size_t read_size = fread(*buffer, 1, *size, file);
    if (read_size != *size) {
        free(*buffer);
        fclose(file);
        perror("Failed to read file");
        return -1;
    }

    fclose(file);
    return 0;
}

size_t parse_data(uint8_t* buffer, size_t size, Node** list, int* valid_count, int* invalid_count) {
    *list = NULL;
    Node** tail = list;

    for (size_t i = 0; i < size;) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (i + sizeof(pdu) > size) break;

        memcpy(&pdu, &buffer[i], sizeof(pdu));

        // Validate RNTI
        if (pdu.RNTI == 0 || pdu.RNTI >= UINT16_MAX) {
            (*invalid_count)++;
        } else {
            Node* new_node = initialize_node(pdu);
            *tail = new_node;
            tail = &new_node->next;
            (*valid_count)++;
        }

        i += sizeof(pdu);
    }

    return *valid_count + *invalid_count;
}

Node* filter_by_rnti_range(Node* head, uint16_t rnti_min, uint16_t rnti_max) {
    Node dummy = {0};
    Node* filtered_tail = &dummy;
    Node* current = head;

    while (current != NULL) {
        if ((rnti_min <= UINT16_MAX && current->data.RNTI < rnti_min) ||
            (rnti_max >= 0 && current->data.RNTI > rnti_max)) {
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            filtered_tail->next = current;
            filtered_tail = current;
            current = current->next;
            filtered_tail->next = NULL;
        }
    }

    return dummy.next;
}

void sort_list(Node** head) {
    if (!head || !*head) return;

    Node* sorted = NULL;

    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        if (!sorted || sorted->data.RNTI >= current->data.RNTI) {
            current->next = sorted;
            sorted = current;
        } else {
            Node* temp = sorted;
            while (temp->next && temp->next->data.RNTI < current->data.RNTI) {
                temp = temp->next;
            }
            current->next = temp->next;
            temp->next = current;
        }
        current = next;
    }

    *head = sorted;
}
