CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *crc_list = (CRCList *)malloc(sizeof(CRCList));
    if (!crc_list) return NULL;

    crc_list->capacity = initial_capacity;
    crc_list->size = 0;

    crc_list->list = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list->list) {
        free(crc_list);
        return NULL;
    }

    return crc_list;
