void destroy_crc_list(CRCList *crc_list) {
    if (crc_list) {
        free(crc_list->list);
        free(crc_list);
    }
}

int add_to_crc_list(CRCList *crc_list, const NFAPI_CRC_INDICATION_PDU_T *item) {
    if (!crc_list || !item) return -1;

    if (crc_list->size >= crc_list->capacity) {
        size_t new_capacity = crc_list->capacity == 0 ? 1 : crc_list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) return -1;

        crc_list->list = new_list;
        crc_list->capacity = new_capacity;
    }

    memcpy(&crc_list->list[crc_list->size], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_list->size++;

    return 0;
}

int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *item_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *item_b = (NFAPI_CRC_INDICATION_PDU_T *)b;

