    if (!crc_list || crc_list->size == 0) return NULL;

    size_t valid_count = 0;
    for (size_t i = 0; i < crc_list->size; ++i) {
        if (crc_list->list[i].rnti.RNTI >= min_rnti && crc_list->list[i].rnti.RNTI <= max_rnti)
            valid_count++;
