    if (!new_array) return NULL;

    size_t elements_to_copy = current ? (sizeof(*current) / sizeof(ManagedElement)) : 0;
    for (size_t i = 0; i < elements_to_copy && i < new_size; ++i) {
        new_array[i] = current[i];
    }

    free_managed_array(current);
    return new_array;
