        exit(EXIT_FAILURE);
    }

    // Initialize RX_FRAME_PDU structures
    for (size_t i = 0; i < num_frames; ++i) {
        pthread_mutex_lock(&lock);
        (*rx_frame_pdu)[i].RX_FRAME_PDU_TAG = rand();
        (*rx_frame_pdu)[i].RNTI = rand() % MAX_FRAMES;
        (*rx_frame_pdu)[i].PHY_FRAME_INFO_TAG = i;
