        (*phy_frame_info)[i].signal_strength = (float)(rand() % 100) / 10.0f;
        (*phy_frame_info)[i].error_rate = (float)(rand() % 100) / 1000.0f;
        (*phy_frame_info)[i].timestamp = time(NULL);
