    if (*crc_indications == NULL) {
        fprintf(stderr, "Memory allocation failed for CRC_INDICATION\n");
        exit(EXIT_FAILURE);
    }

    int rnti_set[MAX_FRAMES] = {0};

    for (size_t i = 0; i < num_structures; ++i) {
        pthread_mutex_lock(&lock);

        int rnti;
        do {
            rnti = rand() % MAX_FRAMES;
        } while (rnti_set[rnti]);

        (*crc_indications)[i].RX_UE_INFORMATION_TAG = rand();
        (*crc_indications)[i].RNTI = rnti;
