        (*crc_indications)[i].crc_indication_rel8.CRC_INDICATION_REL8_TAG = rand();
        (*crc_indications)[i].crc_indication_rel8.CRCFLAG = rand() % 2;

        pthread_mutex_unlock(&lock);
    }
}

void cleanup(NFAPI_RX_FRAME_PDU_T *rx_frame_pdu, PHY_FRAME_INFO_T *phy_frame_info, NFAPI_CRC_INDICATION_PDU_T *crc_indications) {
    free(rx_frame_pdu);
    free(phy_frame_info);
