#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>

#define MAX_LIST_SIZE 1024
#define DNS_TIMEOUT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    u_char IP_ADDRESS[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t list_size;
    char dns_cache[256][256];
    int cache_index;
    pthread_rwlock_t dns_lock;
} ListManager;

ListManager manager = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, {}, 0, PTHREAD_RWLOCK_INITIALIZER};

int is_valid(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0;
}

u_char* resolve_hostname(const char* hostname) {
    struct hostent *he;
    u_char* ip_addr = NULL;

    pthread_rwlock_rdlock(&manager.dns_lock);
    for (int i = 0; i < manager.cache_index; ++i) {
        if (strcmp(manager.dns_cache[i], hostname) == 0) {
            memcpy(ip_addr, inet_aton(manager.dns_cache[i + 1]), 4);
            pthread_rwlock_unlock(&manager.dns_lock);
            return ip_addr;
        }
    }
    pthread_rwlock_unlock(&manager.dns_lock);

    int retries = 3;
    while (retries--) {
        struct timeval timeout = {DNS_TIMEOUT, 0};
        setsockopt(0, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));

        he = gethostbyname(hostname);
        if (he && he->h_addr_list[0]) {
            ip_addr = malloc(4);
            memcpy(ip_addr, he->h_addr_list[0], 4);

            pthread_rwlock_wrlock(&manager.dns_lock);
            strncpy(manager.dns_cache[manager.cache_index++], hostname, sizeof(manager.dns_cache[0]));
            inet_ntop(AF_INET, ip_addr, manager.dns_cache[manager.cache_index++], sizeof(manager.dns_cache[0]));
            pthread_rwlock_unlock(&manager.dns_lock);

            break;
        }
    }

    return ip_addr;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!is_valid(pdu)) {
        fprintf(stderr, "Invalid PDU structure.\n");
        return;
    }

    u_char* ip = resolve_hostname("example.com"); // Replace with actual hostname
    if (ip) {
        memcpy(pdu->IP_ADDRESS, ip, 4);
        free(ip);
    } else {
        fprintf(stderr, "DNS resolution failed.\n");
        memset(pdu->IP_ADDRESS, 0, 4); // Default or error handling IP
    }

    pthread_mutex_lock(&manager.lock);
    if (manager.list_size < MAX_LIST_SIZE) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            pthread_mutex_unlock(&manager.lock);
            return;
        }

        memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = manager.head;
        manager.head = new_node;
        manager.list_size++;
    } else {
        fprintf(stderr, "Maximum list size reached.\n");
    }
    pthread_mutex_unlock(&manager.lock);
}

void clear_list() {
    pthread_mutex_lock(&manager.lock);

    Node* current = manager.head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    manager.head = NULL;
    manager.list_size = 0;

    pthread_mutex_unlock(&manager.lock);
}

void free_manager() {
    clear_list();
    pthread_mutex_destroy(&manager.lock);
    pthread_rwlock_destroy(&manager.dns_lock);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234, 0x01};
    add_pdu(&pdu);

    // Ensure proper cleanup at the end
    free_manager();

    return 0;
}
