#include <string.h>

typedef struct {
    int rx_antennas;
    int sfn;
    int nrsfn;
    int cqi; // Channel Quality Indicator
} PHY_RXINFO;

typedef struct {
    PHY_RXINFO phy_rxinfo;
    // Other LTE_DL_FRAMEINFO fields can be added here as needed
} LTE_DL_FRAMEINFO;

// Pseudo-random noise sequence generator (simple linear congruential generator)
int generate_pseudo_random() {
    static unsigned int seed = 1; // Initialize with a non-zero value
    const unsigned int a = 1103515245;
    const unsigned int c = 12345;
    const unsigned int m = 2147483648; // 2^31
    seed = (a * seed + c) % m;
    return seed;
}

// Function to initialize and populate dynamic array of LTE_DL_FRAMEINFO structures
LTE_DL_FRAMEINFO* init_lte_dl_frameinfo_array(int num_frames, size_t frame_info_size) {
    if (num_frames <= 0 || frame_info_size == 0) {
        return NULL; // Invalid parameters
    }

    LTE_DL_FRAMEINFO *frameArray = malloc(num_frames * frame_info_size);
    if (!frameArray) {
        perror("Failed to allocate memory for frame array");
        return NULL;
    }

    for (int i = 0; i < num_frames; ++i) {
        PHY_RXINFO &phy_rxinfo = frameArray[i].phy_rxinfo;

        // Simulate external data source integration with potential delays
        // For example, fetch `rx_antennas`, `sfn`, and `nrsfn` from a hypothetical function
        phy_rxinfo.rx_antennas = i % 4 + 1; // Example logic for rx antennas (1-4)
        phy_rxinfo.sfn = i % 10;           // Example logic for sfn (0-9)
        phy_rxinfo.nrsfn = (i / 10) % 1024; // Example logic for nrsfn (0-1023)

        // Compute CQI based on a pseudo-random noise sequence
        phy_rxinfo.cqi = generate_pseudo_random() % 15; // CQI typically ranges from 0 to 14

        // Additional initialization and configuration can be added here
    }

    return frameArray;
}

// Example usage of the function
int main() {
    int num_frames = 100; // Number of frames to initialize
    size_t frame_info_size = sizeof(LTE_DL_FRAMEINFO);

    LTE_DL_FRAMEINFO *frames = init_lte_dl_frameinfo_array(num_frames, frame_info_size);
    if (!frames) {
        fprintf(stderr, "Failed to initialize frame array.\n");
        return EXIT_FAILURE;
    }

    // Example: Print initialized CQI values
    for (int i = 0; i < num_frames; ++i) {
        printf("Frame %d - CQI: %d\n", i, frames[i].phy_rxinfo.cqi);
    }

    free(frames); // Clean up dynamically allocated memory
    return EXIT_SUCCESS;
}
```

