#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structures for MAC_HEADER and VLAN_TAG
typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
} MAC_HEADER;

typedef struct {
    uint16_t vlan_id;
    uint8_t priority;
    uint8_t cfi; // Canonical Format Indicator
} VLAN_TAG;

// Define the NICP Frame structure
typedef struct {
    MAC_HEADER mac_header;
    VLAN_TAG vlan_tag;
    void *payload;
    size_t payload_size;
} NICP_FRAME;

// Node for a dynamic list of NICP frames
typedef struct NicpNode {
    NICP_FRAME frame;
    struct NicpNode* next;
} NICP_NODE;

// List structure to manage the NICP nodes
typedef struct {
    NICP_NODE* head;
    size_t count;
} NICP_LIST;

// Function prototypes
NICP_LIST* initializeNicpList();
int appendNicpFrame(NICP_LIST* list, const MAC_HEADER* mac_header, const VLAN_TAG* vlan_tag, const void* payload, size_t payload_size);
void freeNicpList(NICP_LIST* list);

// Initialize the NICP list
NICP_LIST* initializeNicpList() {
    NICP_LIST* list = (NICP_LIST*)malloc(sizeof(NICP_LIST));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for NICP_LIST\n");
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    return list;
}

// Append a new NICP frame to the list
int appendNicpFrame(NICP_LIST* list, const MAC_HEADER* mac_header, const VLAN_TAG* vlan_tag, const void* payload, size_t payload_size) {
    if (!list || !mac_header || !vlan_tag || !payload) {
        return -1; // Invalid arguments
    }

    NICP_NODE* new_node = (NICP_NODE*)malloc(sizeof(NICP_NODE));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for NICP_NODE\n");
        return -1;
    }

    memcpy(&new_node->frame.mac_header, mac_header, sizeof(MAC_HEADER));
    memcpy(&new_node->frame.vlan_tag, vlan_tag, sizeof(VLAN_TAG));

    new_node->frame.payload = malloc(payload_size);
    if (!new_node->frame.payload) {
        fprintf(stderr, "Memory allocation failed for payload\n");
        free(new_node);
        return -1;
    }

    memcpy(new_node->frame.payload, payload, payload_size);
    new_node->frame.payload_size = payload_size;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    return 0; // Success
}

// Free the NICP list and all associated resources
void freeNicpList(NICP_LIST* list) {
    if (!list) return;

    NICP_NODE* current = list->head;
    while (current) {
        NICP_NODE* next_node = current->next;
        free(current->frame.payload);
        free(current);
        current = next_node;
    }

    free(list);
}

int main() {
    // Example usage
    NICP_LIST* nicp_list = initializeNicpList();
    if (!nicp_list) return EXIT_FAILURE;

    MAC_HEADER mac_header = {{0x00, 0x11, 0x22, 0x33, 0x44, 0x55}, {0x66, 0x77, 0x88, 0x99, 0xAA, 0xBB}};
    VLAN_TAG vlan_tag = {100, 1, 0};
    char payload[] = "Hello, NICP!";

    if (appendNicpFrame(nicp_list, &mac_header, &vlan_tag, payload, sizeof(payload)) != 0) {
        fprintf(stderr, "Failed to append NICP frame\n");
        freeNicpList(nicp_list);
        return EXIT_FAILURE;
    }

    // Clean up
    freeNicpList(nicp_list);

    return EXIT_SUCCESS;
}
```

