    if (pthread_mutex_lock(&mutex)) {
        log_error("Failed to lock mutex");
        return -1;
    }

    *frames = malloc(NUM_FRAMES * sizeof(MAC_FRAME));
    if (*frames == NULL) {
        log_error("Memory allocation failed for frames");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < NUM_FRAMES; ++i) {
