        (*frames)[i].timestamp = time(NULL); // Current timestamp

        (*frames)[i].data_payload = malloc(FRAME_SIZE);
        if ((*frames)[i].data_payload == NULL) {
            log_error("Memory allocation failed for data payload");
            for (int j = 0; j < i; ++j) {
                free((*frames)[j].data_payload);
            }
            free(*frames);
            *frames = NULL;
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Fill the payload with random bytes
        for (size_t k = 0; k < FRAME_SIZE; ++k) {
            (*frames)[i].data_payload[k] = rand() % 256;
