#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure as given in your description.
typedef struct {
    int RX_UE_INFORMATION_TAG; // Placeholder type, replace with actual type if different.
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for managing the array.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // Mutex to handle concurrent access
    const size_t MAX_CAPACITY; // Maximum allowable capacity
} ArrayManager;

// Function prototypes
void initArrayManager(ArrayManager *manager, size_t initialCapacity, size_t maxCapacity);
int addElementToArray(ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element);
void clearAndFreeArray(ArrayManager *manager);

// Initialize the array manager.
void initArrayManager(ArrayManager *manager, size_t initialCapacity, size_t maxCapacity) {
    if (initialCapacity == 0 || initialCapacity > maxCapacity) {
        fprintf(stderr, "Invalid initial capacity.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->MAX_CAPACITY = maxCapacity;
    manager->capacity = initialCapacity;
    manager->size = 0;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Add an element to the array.
int addElementToArray(ArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->MAX_CAPACITY) {
        fprintf(stderr, "Reached maximum capacity.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Double the size if needed.
    if (manager->size == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        if (newCapacity > manager->MAX_CAPACITY) {
            newCapacity = manager->MAX_CAPACITY;
        }

        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(manager->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) {
            fprintf(stderr, "Memory reallocation failed.\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        manager->array = newArray;
        manager->capacity = newCapacity;
    }

    // Assign a random value to CRCFLAG.
    srand(time(NULL));
    element.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    // Set the element in array and increase size.
    manager->array[manager->size++] = element;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Clear and free all resources associated with the array.
void clearAndFreeArray(ArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->array) {
        free(manager->array);
        manager->array = NULL;
    }

    manager->size = 0;
    manager->capacity = 0;

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
