#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structures as per your description
typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a cache structure for frequently accessed elements
typedef struct CacheElement {
    void *data;
    size_t data_size;
    struct CacheElement *next;
} CacheElement;

typedef struct {
    CacheElement *head;
    pthread_mutex_t lock;
} ElementCache;

// Function declarations
void initCache(ElementCache *cache);
void freeCache(ElementCache *cache);
void addToCache(ElementCache *cache, void *data, size_t data_size);
void* getFromCache(ElementCache *cache, size_t data_size);

void processNFADomElements(const char *dom_tree, int num_elements, 
                           NFAPI_CRC_INDICATION_PDU_T **output_array, 
                           int (*filterFunc)(const char *element), 
                           void (*logFunc)(const char *message));

// Utility function to generate a random CRCFLAG
unsigned int getRandomCRCFlag() {
    return rand() % 2;
}

// Initialize the cache
void initCache(ElementCache *cache) {
    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

// Free the cache
void freeCache(ElementCache *cache) {
    CacheElement *current = cache->head;
    while (current != NULL) {
        CacheElement *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    pthread_mutex_destroy(&cache->lock);
}

// Add an element to the cache
void addToCache(ElementCache *cache, void *data, size_t data_size) {
    CacheElement *new_element = malloc(sizeof(CacheElement));
    new_element->data = malloc(data_size);
    memcpy(new_element->data, data, data_size);
    new_element->data_size = data_size;
    new_element->next = NULL;

    pthread_mutex_lock(&cache->lock);
    new_element->next = cache->head;
    cache->head = new_element;
    pthread_mutex_unlock(&cache->lock);
}

// Get an element from the cache
void* getFromCache(ElementCache *cache, size_t data_size) {
    pthread_mutex_lock(&cache->lock);
    CacheElement *current = cache->head;
    while (current != NULL) {
        if (current->data_size == data_size) {
            void *data_copy = malloc(data_size);
            memcpy(data_copy, current->data, data_size);
            pthread_mutex_unlock(&cache->lock);
            return data_copy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL; // Cache miss
}

// Process the DOM tree and populate the output array
void processNFADomElements(const char *dom_tree, int num_elements, 
                           NFAPI_CRC_INDICATION_PDU_T **output_array, 
                           int (*filterFunc)(const char *element), 
                           void (*logFunc)(const char *message)) {
    if (!dom_tree || !num_elements || !output_array || !filterFunc) {
        logFunc("Invalid input parameters.");
        return;
    }

    ElementCache cache;
    initCache(&cache);

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_elements; ++i) {
        const char *element = getFromCache(&cache, sizeof(const char *));
        if (!element) {
            element = dom_tree + (rand() % strlen(dom_tree)); // Simulate DOM traversal
            addToCache(&cache, &element, sizeof(const char *));
        }

        if (filterFunc(element)) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu) {
                logFunc("Memory allocation failed.");
                continue;
            }

            pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Simulate a tag
            pdu->RNTI = rand() % 1000; // Simulate an RNTI
            pdu->CRC_INDICATION.CRCFLAG = getRandomCRCFlag();

            (*output_array)[i] = *pdu;
        } else {
            logFunc("Element did not match filter criteria.");
        }
    }

    freeCache(&cache);
}

// Example logging function
void exampleLog(const char *message) {
    printf("%s\n", message);
}

// Example filter function
int exampleFilter(const char *element) {
    return strlen(element) > 0; // Dummy filter: accept all non-empty elements
}

int main() {
    const char *dom_tree = "<root><child>data</child></root>";
    int num_elements = 10;
    NFAPI_CRC_INDICATION_PDU_T *output_array[num_elements];

    processNFADomElements(dom_tree, num_elements, (NFAPI_CRC_INDICATION_PDU_T **)output_array,
                          exampleFilter, exampleLog);

    for (int i = 0; i < num_elements; ++i) {
        if (output_array[i].RX_UE_INFORMATION_TAG != 0) { // Check if the element was set
            printf("Element %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n",
                   i, output_array[i].RX_UE_INFORMATION_TAG, output_array[i].RNTI,
                   output_array[i].CRC_INDICATION.CRCFLAG);
        }
    }

    return 0;
}
