['Below is a C code snippet that implements a thread-safe dynamic list of `MAC_PDU_T` structures with concurrent access management, external message queue integration, error checking, and resource cleanup.

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_STRUCTURES 1000

typedef struct {
    int PREAMBLE_ID;
    int SEQUENCE_NUMBER;
} LAYER2_MESSAGE;

typedef struct MAC_PDU_T {
    LAYER2_MESSAGE message;
    struct MAC_PDU_T* next;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T* head;
    pthread_mutex_t mutex;
    size_t count;
} MAC_PDU_List;

MAC_PDU_List* create_mac_pdu_list() {
    MAC_PDU_List* list = (MAC_PDU_List*)malloc(sizeof(MAC_PDU_List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    return list;
}

int insert_mac_pdu(MAC_PDU_List* list, LAYER2_MESSAGE message) {
    if (list->count >= MAX_STRUCTURES) return -1;

    MAC_PDU_T* new_node = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
    if (!new_node) return -1;

    new_node->message = message;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    // Simulate offloading to an external queue
    // enqueue_message(message); 

    return 0;
}

int remove_mac_pdu(MAC_PDU_List* list, int preamble_id) {
    pthread_mutex_lock(&list->mutex);

    MAC_PDU_T *current = list->head, *prev = NULL;

    while (current != NULL && current->message.PREAMBLE_ID != preamble_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Not found
    }

    if (prev == NULL) { // Remove head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void clear_mac_pdu_list(MAC_PDU_List* list) {
    pthread_mutex_lock(&list->mutex);

    MAC_PDU_T *current = list->head, *next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);

    pthread_mutex_destroy(&list->mutex);
}

void free_mac_pdu_list(MAC_PDU_List* list) {
    clear_mac_pdu_list(list);
    free(list);
}
```

This code defines a `MAC_PDU_T` structure and a linked list to manage these structures with thread safety using mutexes. The functions handle insertion, removal, clearing, and freeing of resources, while also simulating integration with an external message queue. Error checking is included for memory allocation failures, and the maximum number of allowed structures is enforced.']

