    size_t count;
    pthread_mutex_t lock;
} CRC_Manager;

CRC_Manager* crc_manager_init() {
    CRC_Manager *manager = (CRC_Manager *)malloc(sizeof(CRC_Manager));
    if (!manager) return NULL;

    manager->array = NULL;
    manager->count = 0;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager);
        return NULL;
    }

    return manager;
}

void crc_manager_destroy(CRC_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i].RX_UE_INFORMATION_TAG);
        free(manager->array[i].RNTI);
        free(manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int crc_manager_add_entry(CRC_Manager *manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Maximum entries reached
    }

    size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((required_memory + manager->array == NULL ? 0 : manager->count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory usage exceeded
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->array, (manager->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Memory allocation failed
    }

    manager->array[manager->count] = entry;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    log_entry(entry);
    return 0;
}

void log_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    static int file_count = 0;
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%d.log", LOG_FILE_PATH, file_count);

    FILE *file = fopen(filename, "a");
