    size_t written = fwrite(&entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    fclose(file);

    if (written != 1) {
        // Handle partial write or error
    }

    // Rotate log file if threshold is exceeded
    struct stat st;
    if (stat(filename, &st) == 0 && st.st_size >= LOG_ROTATION_THRESHOLD) {
        file_count++;
    }
}

void validate_log_integrity() {
    // Implement a mechanism to periodically check the integrity of logged data.
    // This can involve checking file hashes or maintaining checksums.
}

int main() {
