    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for memory management
size_t max_memory_limit = 1024 * 1024; // Default upper limit of 1MB
pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
size_t current_memory_usage = 0;

// Function to log memory usage and errors
void log_message(const char* message) {
    printf("%s\n", message);
}

// Asynchronous notification function (stub)
void notify_external_system() {
    // Implementation for notifying external systems when memory limit is reached
    log_message("Memory allocation limit reached. Notifying external system...");
}

// Function to manage dynamic memory allocation
NFAPI_CRC_INDICATION_PDU_T* allocate_memory_for_pds(size_t num_pdus, size_t* allocated_size) {
    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t required_memory = num_pdus * pdu_size;

    pthread_mutex_lock(&mem_lock);

    if (current_memory_usage + required_memory > max_memory_limit) {
        log_message("Insufficient memory. Allocation failed.");
        pthread_mutex_unlock(&mem_lock);
        notify_external_system();
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(required_memory);
    if (!pdus) {
        log_message("Memory allocation error.");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }

    current_memory_usage += required_memory;
    *allocated_size = required_memory;

    // Initialize PDUs
    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].ue_info_tag.RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        pdus[i].rnti.RNTI = rand();
        pdus[i].crc_indication.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&mem_lock);
    log_message("Memory allocation successful.");
    return pdus;
}

// Function to free allocated memory
void free_memory(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t allocated_size) {
    if (pdus) {
        pthread_mutex_lock(&mem_lock);
        current_memory_usage -= allocated_size;
        free(pdus);
        pthread_mutex_unlock(&mem_lock);
        log_message("Memory deallocated.");
    }
}

// Function to update memory limit at runtime
void set_memory_limit(size_t new_limit) {
    pthread_mutex_lock(&mem_lock);
    max_memory_limit = new_limit;
    pthread_mutex_unlock(&mem_lock);
    log_message("Memory limit updated.");
}
