#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10000

typedef struct {
    char client_ip[16];
    int client_port;
    char server_ip[16];
    int status; // 0 for inactive, 1 for active
} Connection;

typedef struct {
    Connection *connections;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ConnectionArray;

void initConnectionArray(ConnectionArray *array, size_t initial_capacity) {
    array->size = 0;
    array->capacity = initial_capacity;
    array->connections = (Connection *)malloc(initial_capacity * sizeof(Connection));
    if (!array->connections) {
        perror("Failed to allocate memory for connections");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

void freeConnectionArray(ConnectionArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->connections);
    array->connections = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int addConnection(ConnectionArray *array, const char *client_ip, int client_port,
                  const char *server_ip, int status) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Connection *new_connections = realloc(array->connections, new_capacity * sizeof(Connection));
        if (!new_connections) {
            perror("Failed to reallocate memory for connections");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->connections = new_connections;
        array->capacity = new_capacity;
    }

    Connection conn;
    strncpy(conn.client_ip, client_ip, sizeof(conn.client_ip));
    conn.client_port = client_port;
    strncpy(conn.server_ip, server_ip, sizeof(conn.server_ip));
    conn.status = status;

    array->connections[array->size++] = conn;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int removeConnection(ConnectionArray *array, const char *client_ip, int client_port) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->connections[i].client_ip, client_ip) == 0 &&
            array->connections[i].client_port == client_port) {

            memmove(&array->connections[i], &array->connections[i + 1],
                    (--array->size - i) * sizeof(Connection));
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->lock);
    return -1;
}

void updateConnectionStatus(ConnectionArray *array, const char *client_ip,
                            int client_port, int status) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (strcmp(array->connections[i].client_ip, client_ip) == 0 &&
            array->connections[i].client_port == client_port) {

            array->connections[i].status = status;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void getStatistics(ConnectionArray *array, int *active_count, int *inactive_count) {
    pthread_mutex_lock(&array->lock);

    *active_count = 0;
    *inactive_count = 0;

    for (size_t i = 0; i < array->size; ++i) {
        if (array->connections[i].status == 1) {
            (*active_count)++;
        } else {
            (*inactive_count)++;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

int main() {
    ConnectionArray conn_array;
    initConnectionArray(&conn_array, 10);

    addConnection(&conn_array, "192.168.0.1", 12345, "192.168.0.100", 1);
    addConnection(&conn_array, "192.168.0.2", 54321, "192.168.0.101", 0);

    int active_count = 0;
    int inactive_count = 0;

    getStatistics(&conn_array, &active_count, &inactive_count);
    printf("Active connections: %d\n", active_count);
    printf("Inactive connections: %d\n", inactive_count);

    removeConnection(&conn_array, "192.168.0.1", 12345);

    freeConnectionArray(&conn_array);

    return 0;
}
