#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CRCFLAG 0xFF
#define LOG_FILE_PATH "operation_log.txt"
#define INITIAL_SIZE 10

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char *message) {
    pthread_mutex_lock(&log_mutex);
    FILE *file = fopen(LOG_FILE_PATH, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
    pthread_mutex_unlock(&log_mutex);
}

int is_crcflag_valid(uint8_t crcflag) {
    // Define performance-critical bounds for CRCFLAG
    return crcflag >= 0x20 && crcflag <= 0xE0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_array(size_t n, size_t *allocated_size) {
    size_t current_size = INITIAL_SIZE;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    while (current_size < n) {
        array = realloc(array, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array && current_size > 0) {
            // Allocation failed, attempt to reduce size
            current_size /= 2;
            free(array);
            array = NULL;
            continue;
        }
        if (array) break;

        // Initial allocation
        current_size *= 2;
    }

    if (!array) return NULL; // Failed to allocate memory

    *allocated_size = current_size;

    for (size_t i = 0; i < n; ++i) {
        array[i].tag.RX_UE_INFORMATION_TAG = rand() % 65536; // Example initialization
        array[i].tag.RNTI = rand() % 65536; // Example initialization

        uint8_t crcflag;
        do {
            crcflag = rand() % (MAX_CRCFLAG + 1);
        } while (!is_crcflag_valid(crcflag));

        array[i].CRCFLAG = crcflag;
    }

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated and initialized array with size: %zu", n);
    log_operation(log_message);

    return array;
}

void free_nfaapi_crc_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
```

### Key Points:
- **Dynamic Allocation**: The function dynamically allocates memory, doubling the size until it meets or exceeds `n`. It handles allocation failures by reducing the requested size.
- **Initialization**: Each structure is initialized with random values for `RX_UE_INFORMATION_TAG`, `RNTI`, and a valid `CRCFLAG`.
- **Validation**: Ensures `CRCFLAG` adheres to performance-critical bounds using `is_crcflag_valid()`.
- **Logging**: Logs operations to a file, ensuring thread safety with a mutex.
- **Thread Safety**: Uses a mutex for logging to prevent race conditions in multi-threaded environments.
- **Error Handling**: Gracefully handles memory allocation failures by attempting smaller allocations.']

