    size_t capacity;
    size_t size;
    int successfulCRCs;
    int failedCRCs;
} DynamicList;

// Function to check if RNTI is unique in the list
int isUniqueRNTI(DynamicList *list, unsigned int rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Function to initialize the dynamic list
DynamicList* createList(size_t initialCapacity) {
    DynamicList *list = (DynamicList*) malloc(sizeof(DynamicList));
    if (!list) {
        perror("Failed to allocate memory for list");
        exit(EXIT_FAILURE);
    }
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        perror("Failed to allocate memory for elements");
        exit(EXIT_FAILURE);
    }
    list->capacity = initialCapacity;
    list->size = 0;
    list->successfulCRCs = 0;
    list->failedCRCs = 0;
    return list;
}

// Function to resize the dynamic list
void resizeList(DynamicList *list) {
    size_t newCapacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newElements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElements) {
        perror("Failed to reallocate memory for elements");
        exit(EXIT_FAILURE);
    }
    list->elements = newElements;
    list->capacity = newCapacity;
}

// Function to add an element to the dynamic list
void addElement(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->size == list->capacity) {
        resizeList(list);
    }
    if (!isUniqueRNTI(list, element.RNTI)) {
        fprintf(stderr, "Duplicate RNTI detected: %u\n", element.RNTI);
        return;
    }

    list->elements[list->size] = element;

    // Randomly set CRCFLAG for demonstration
    list->elements[list->size].CRCFLAG = rand() % 2; // 0 or 1

    if (list->elements[list->size].CRCFLAG) {
        ++list->successfulCRCs;
    } else {
        ++list->failedCRCs;
    }

    ++list->size;
}

// Function to get the statistical summary of CRCFLAGS
void getCRCStats(const DynamicList *list, int *successful, int *failed) {
    if (successful && failed) {
        *successful = list->successfulCRCs;
        *failed = list->failedCRCs;
    }
}

// Function to free the dynamic list
void freeList(DynamicList *list) {
    if (list) {
        free(list->elements);
        free(list);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Seed random number generator

    DynamicList *list = createList(INITIAL_CAPACITY);

    for (unsigned int i = 0; i < 20; ++i) { // Add some elements
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = i + 1;
        element.RNTI = rand() % 100; // Random RNTI for demonstration

