```c
#include <stdio.h>
#include <stdlib.h>
import stdlib.h
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t mutex;
} EntryList;

// Function to initialize the entry list
void initEntryList(EntryList *list) {
    list->count = 0;
    for (int i = 0; i < MAX_ENTRIES; i++) {
        list->entries[i] = NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to create and populate a new entry
NFAPI_CRC_INDICATION_PDU_T* createEntry() {
    NFAPI_CRC_INDICATION_PDU_T *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    entry->RX_UE_INFORMATION_TAG = rand(); // Random valid data
    entry->RNTI = rand();
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRC flag (0 or 1)

    return entry;
}

// Function to add a new entry into the list
int addEntry(EntryList *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_ENTRIES) {
        free(list->entries[0]); // Free oldest entry to make space
        memmove(list->entries, list->entries + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (MAX_ENTRIES - 1));
    }

    NFAPI_CRC_INDICATION_PDU_T* newEntry = createEntry();
    if (!newEntry) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Allocation failed
    }

    list->entries[list->count++] = newEntry;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Unit tests for verification
void testAddEntries() {
    EntryList list;
    initEntryList(&list);

    for (int i = 0; i < MAX_ENTRIES * 2; i++) { // Simulate high-frequency calls
        if (addEntry(&list) == -1) {
            printf("Failed to add entry at iteration %d\n", i);
        }
    }

    printf("Final count of entries: %zu\n", list.count);

    for (size_t i = 0; i < list.count; ++i) {
        free(list.entries[i]); // Clean up
    }
}

int main() {
    testAddEntries();
    return 0;
}
```

### Explanation

- **Thread Safety**: A mutex is used to ensure that operations on the `EntryList` are thread-safe.
- **Memory Management**: The oldest entry in the list is freed and removed when adding a new entry once the maximum capacity is reached, maintaining only up to 10,000 entries at any time.
- **Error Handling**: Memory allocation failures are handled by checking if `malloc` returns `NULL`.
- **Random Data Generation**: The function generates random valid data for each field in the structure.

### Unit Test

The unit test simulates adding more than the maximum number of allowed entries to ensure that older entries are correctly removed, and memory is managed efficiently. Adjustments can be made for testing under peak traffic scenarios by modifying how often `addEntry` is called or altering its behavior based on input data rates.']

