CRCList* create_crc_list(size_t initial_capacity);
int add_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
void resize_crc_list(CRCList *list);
void free_crc_list(CRCList *list);
void log_error(const char *message);
