// Initialize a CRC list
CRCList* create_crc_list(size_t initial_capacity) {
    CRCList *list = (CRCList *)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    list->crc_success_count = 0;
    list->crc_failure_count = 0;

    return list;
}

// Add a new PDU to the CRC list
int add_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        resize_crc_list(list);
    }

    if (!is_unique_rnti(list, pdu.RNTI)) {
        log_error("Duplicate RNTI detected.");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    memcpy(&list->data[list->count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count++;

    if (pdu.CRC_INDICATION_REL8_TAG.CRCFLAG) {
        list->crc_success_count++;
    } else {
        list->crc_failure_count++;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Resize the CRC list
void resize_crc_list(CRCList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_error("Memory allocation failed during resize.");
        return;
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

// Free the CRC list
void free_crc_list(CRCList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->data);
    free(list);
}

// Log an error message
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Check if the RNTI is unique in the list
int is_unique_rnti(CRCList *list, unsigned int rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

// Example usage
int main() {
    CRCList *list = create_crc_list(INITIAL_CAPACITY);
    if (!list) {
        log_error("Failed to create CRC list.");
        return -1;
    }

    srand(time(NULL));

    for (unsigned int i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand(),
            .RNTI = rand() % 100,
            .CRC_INDICATION_REL8_TAG = {.CRCFLAG = rand() % 2}
        };

        add_pdu(list, pdu);
    }

    printf("Total CRC Success: %u\n", list->crc_success_count);
    printf("Total CRC Failure: %u\n", list->crc_failure_count);

    free_crc_list(list);
    return 0;
}
