#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_INTERFACES 1000
#define LOW_THROUGHPUT_THRESHOLD 10

typedef struct {
    uint32_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    volatile int is_paused;
    uint32_t update_frequency_ms;
    uint32_t low_throughput_count[MAX_INTERFACES];
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->is_paused = 0;
    list->update_frequency_ms = 100; // Default frequency
    memset(list->low_throughput_count, 0, sizeof(list->low_throughput_count));
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void pause_collection(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    list->is_paused = 1;
    pthread_mutex_unlock(&list->lock);
}

void resume_collection(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    list->is_paused = 0;
    pthread_mutex_unlock(&list->lock);
}

int is_low_throughput(uint32_t interface_index) {
    return (list->low_throughput_count[interface_index] < LOW_THROUGHPUT_THRESHOLD);
}

void update_frequency(DynamicList* list, uint32_t new_frequency_ms) {
    pthread_mutex_lock(&list->lock);
    list->update_frequency_ms = new_frequency_ms;
    pthread_mutex_unlock(&list->lock);
}

void add_pdu_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (pthread_mutex_trylock(&list->lock) != 0 || list->is_paused) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    // Randomly set CRCFLAG
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&list->lock);
}

void* data_collector(void* arg) {
    DynamicList* list = (DynamicList*)arg;
    while (1) {
        if (pthread_mutex_trylock(&list->lock) == 0 && !list->is_paused) {
            for (uint32_t i = 0; i < MAX_INTERFACES; ++i) {
                if (!is_low_throughput(i)) {
                    NFAPI_CRC_INDICATION_PDU_T pdu;
                    pdu.RNTI = rand(); // Simulated RNTI
                    pdu.RX_UE_INFORMATION_TAG = rand() % 256; // Simulated tag

                    add_pdu_to_list(list, pdu);
                }
            }
            pthread_mutex_unlock(&list->lock);
        }

        usleep(list->update_frequency_ms * 1000); // Adjust frequency dynamically
    }
    return NULL;
}

void adjust_update_frequency(DynamicList* list) {
    while (1) {
        sleep(5); // Check every 5 seconds

        pthread_mutex_lock(&list->lock);
        uint32_t load = rand() % 100; // Simulated system load

        if (load > 80) {
            list->update_frequency_ms *= 2;
        } else if (load < 20 && list->update_frequency_ms > 50) {
            list->update_frequency_ms /= 2;
        }

        pthread_mutex_unlock(&list->lock);
    }
}

int main() {
    srand(time(NULL));

    DynamicList* list = create_dynamic_list();
    pthread_t collector_thread, frequency_adjuster_thread;

    pthread_create(&collector_thread, NULL, data_collector, (void*)list);
    pthread_create(&frequency_adjuster_thread, NULL, adjust_update_frequency, (void*)list);

    pause_collection(list);
    sleep(2); // Simulate pause
    resume_collection(list);

    sleep(10); // Run for 10 seconds

    destroy_dynamic_list(list);
    pthread_join(collector_thread, NULL);
    pthread_join(frequency_adjuster_thread, NULL);

    return 0;
}
