#define MAX_INTERFACES 10

typedef struct {
    char name[32];
    unsigned long bytesSent;
    unsigned long bytesReceived;
    double latency; // in milliseconds
    int packetLossRate; // percentage
} NetworkInterfaceStats;

int initializeNetworkInterfaces(NetworkInterfaceStats **interfaces, size_t count) {
    if (count > MAX_INTERFACES || !interfaces) return -1;

    *interfaces = (NetworkInterfaceStats *)malloc(count * sizeof(NetworkInterfaceStats));
    if (!*interfaces) return -2; // Memory allocation failed

    for (size_t i = 0; i < count; ++i) {
        snprintf((*interfaces)[i].name, sizeof((*interfaces)[i].name), "eth%d", (int)i + 1);
        (*interfaces)[i].bytesSent = rand() % 1000000;
        (*interfaces)[i].bytesReceived = rand() % 1000000;
        (*interfaces)[i].latency = (rand() % 100) / 10.0; // Random latency between 0 and 10 ms
        (*interfaces)[i].packetLossRate = rand() % 5; // Packet loss rate between 0-4%
    }

    return 0;
}

void updateNetworkInterfaceStats(NetworkInterfaceStats *interfaces, size_t count) {
    if (!interfaces || count == 0) return;

    for (size_t i = 0; i < count; ++i) {
        interfaces[i].bytesSent += rand() % 10000; // Simulate data change
        interfaces[i].bytesReceived += rand() % 10000;
        interfaces[i].latency += ((rand() % 20) - 10) / 10.0; // Small random adjustment
        if (interfaces[i].latency < 0) interfaces[i].latency = 0;
    }
}

void simulatePeriodicUpdates(NetworkInterfaceStats *interfaces, size_t count) {
    while (1) {
        updateNetworkInterfaceStats(interfaces, count);
        sleep(5); // Update every 5 seconds
    }
}

int main() {
    NetworkInterfaceStats *interfaces = NULL;
    int result = initializeNetworkInterfaces(&interfaces, MAX_INTERFACES);

    if (result != 0) {
        fprintf(stderr, "Failed to initialize network interfaces: Error code %d\n", result);
        return EXIT_FAILURE;
    }

    // This should ideally be run in a separate thread or process
    simulatePeriodicUpdates(interfaces, MAX_INTERFACES);

    free(interfaces);
    return EXIT_SUCCESS;
}
