#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUEUE_SIZE 5000

typedef struct {
    // Assuming these are defined elsewhere
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct QueueNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} DynamicQueue;

void initQueue(DynamicQueue* q) {
    q->front = NULL;
    q->rear = NULL;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

int isFull(DynamicQueue* q) {
    return q->size == MAX_QUEUE_SIZE;
}

int isEmpty(DynamicQueue* q) {
    return q->size == 0;
}

void enqueue(DynamicQueue* q, NFAPI_CRC_INDICATION_PDU_T item) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) {
        perror("Failed to allocate memory for queue node");
        exit(EXIT_FAILURE);
    }
    newNode->data = item;
    newNode->next = NULL;

    pthread_mutex_lock(&q->lock);

    while (isFull(q)) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }

    if (isEmpty(q)) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->size++;

    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->not_empty);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(DynamicQueue* q) {
    pthread_mutex_lock(&q->lock);

    while (isEmpty(q)) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }

    QueueNode* temp = q->front;
    NFAPI_CRC_INDICATION_PDU_T item = temp->data;

    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    q->size--;

    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->not_full);

    return item;
}

void destroyQueue(DynamicQueue* q) {
    while (!isEmpty(q)) {
        dequeue(q);
    }
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
}

NFAPI_CRC_INDICATION_PDU_T createRandomPDU() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    return pdu;
}

void* producer(void* arg) {
    DynamicQueue* q = (DynamicQueue*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = createRandomPDU();
        enqueue(q, pdu);
    }
    return NULL;
}

void* consumer(void* arg) {
    DynamicQueue* q = (DynamicQueue*)arg;
    int processedCount = 0;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue(q);
        // Process the PDU
        processedCount++;
        printf("Processed: %d\n", processedCount);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    DynamicQueue queue;
    initQueue(&queue);

    pthread_t producerThread, consumerThread;

    pthread_create(&producerThread, NULL, producer, &queue);
    pthread_create(&consumerThread, NULL, consumer, &queue);

    pthread_join(producerThread, NULL);
    pthread_join(consumerThread, NULL);

    destroyQueue(&queue);

    return 0;
}
```

This code implements a thread-safe dynamic queue for managing `NFAPI_CRC_INDICATION_PDU_T` structures. It uses mutexes and condition variables to ensure safe concurrent access by multiple threads. The producer generates random PDUs, while the consumer processes them. The queue size is limited to 5000 to manage memory efficiently.']

