    pthread_mutex_t lock;
    NFAPI_RRC_CU_UP_RX_PDU_T *pool[MAX_MSGS];
    size_t pool_size;
} MemoryPool;

typedef struct {
    int enabled;
    FILE *log_file;
} LoggerConfig;

LoggerConfig logger = {0, NULL};

void log_message(const char *message) {
    if (logger.enabled && logger.log_file) {
        fprintf(logger.log_file, "%s: %s\n", time(NULL), message);
    }
}

int init_logger(const char *file_path, int enable_logging) {
    logger.enabled = enable_logging;
    if (enable_logging) {
        logger.log_file = fopen(file_path, "a");
        if (!logger.log_file) return -1;
    }
    return 0;
}

void free_logger() {
    if (logger.log_file) fclose(logger.log_file);
    logger.enabled = 0;
    logger.log_file = NULL;
}

MemoryPool *create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->pool_size = size;

    for (size_t i = 0; i < size; ++i) {
        pool->pool[i] = malloc(sizeof(NFAPI_RRC_CU_UP_RX_PDU_T));
        if (!pool->pool[i]) {
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }
    }

    log_message("Memory pool created successfully.");
    return pool;
}

NFAPI_RRC_CU_UP_RX_PDU_T *allocate_from_pool(MemoryPool *pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; ++i) {
        if (pool->pool[i]) {
            NFAPI_RRC_CU_UP_RX_PDU_T *pdu = pool->pool[i];
            pool->pool[i] = NULL;
            pthread_mutex_unlock(&pool->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    log_message("Memory pool allocation failed.");
    return NULL;
}

void deallocate_to_pool(MemoryPool *pool, NFAPI_RRC_CU_UP_RX_PDU_T *pdu) {
    if (!pool || !pdu) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; ++i) {
        if (!pool->pool[i]) {
            pool->pool[i] = pdu;
            pthread_mutex_unlock(&pool->lock);
            log_message("Memory deallocated back to pool.");
            return;
        }
    }

    free(pdu); // If no space available, free it
    pthread_mutex_unlock(&pool->lock);
}

void init_pdu(NFAPI_RRC_CU_UP_RX_PDU_T *pdu, int rrc_type, unsigned long ue_id) {
    if (!pdu) return;

    pdu->rrc_message_type = rrc_type;
    pdu->ue_id = ue_id;

    for (int i = 0; i < MAX_CONTEXT_TAGS; ++i) {
        pdu->context_tags[i] = NULL;
    }
}

void add_context_tag(NFAPI_RRC_CU_UP_RX_PDU_T *pdu, const char *tag) {
    if (!pdu || !tag) return;

    for (int i = 0; i < MAX_CONTEXT_TAGS; ++i) {
        if (!pdu->context_tags[i]) {
            pdu->context_tags[i] = strdup(tag);
            break;
        }
    }
}

void free_pdu(NFAPI_RRC_CU_UP_RX_PDU_T *pdu) {
    if (!pdu) return;

    for (int i = 0; i < MAX_CONTEXT_TAGS; ++i) {
        free(pdu->context_tags[i]);
        pdu->context_tags[i] = NULL;
    }
}

void destroy_memory_pool(MemoryPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; ++i) {
        free(pool->pool[i]);
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void simulate_external_data_source(MemoryPool *pool, LoggerConfig *logger_config);

int main() {
    if (init_logger("debug.log", 1) != 0) {
        fprintf(stderr, "Failed to initialize logger.\n");
        return EXIT_FAILURE;
    }

    MemoryPool *memory_pool = create_memory_pool(MAX_MSGS);
    if (!memory_pool) {
        free_logger();
        fprintf(stderr, "Failed to create memory pool.\n");
        return EXIT_FAILURE;
    }

    simulate_external_data_source(memory_pool, &logger);

    destroy_memory_pool(memory_pool);
    free_logger();

    return EXIT_SUCCESS;
}

void simulate_external_data_source(MemoryPool *pool, LoggerConfig *logger_config) {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, (void *(*)(void *))[]{
        while (1) {
            NFAPI_RRC_CU_UP_RX_PDU_T *pdu = allocate_from_pool(pool);
            if (!pdu) continue; // Simulate delay

            init_pdu(pdu, rand() % 10 + 1, rand());
            add_context_tag(pdu, "example_tag");

            deallocate_to_pool(pool, pdu);

            sleep(rand() % 3); // Simulate varying input rate
        }
    }, NULL)) {
        fprintf(stderr, "Failed to create simulation thread.\n");
        return;
    }

    pthread_join(thread_id, NULL);
}
