#define MAX_ELEMENTS 50000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_list(DynamicList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

int resize_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) return -1;

        list->data = new_data;
        list->capacity = new_capacity;
    }
    return 0;
}

int add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", pdu.RNTI);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    int result = resize_if_needed(list);
    if (result != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_list(const DynamicList *list, FILE *fp) {
    if (fwrite(&list->size, sizeof(size_t), 1, fp) != 1) return -1;

    for (size_t i = 0; i < list->size; ++i) {
        int written = fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        if (written != 1) return -1;
    }
    return 0;
}

int deserialize_list(DynamicList *list, FILE *fp) {
    size_t new_size;
    if (fread(&new_size, sizeof(size_t), 1, fp) != 1) return -1;

    int result = resize_if_needed(list);
    if (result != 0) return -1;

    list->size = new_size;
    for (size_t i = 0; i < list->size; ++i) {
        if (fread(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) return -1;
    }
    return 0;
}

void populate_list(DynamicList *list) {
    srand(time(NULL));
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.RNTI = rand() % 100000;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        if (add_pdu(list, pdu) != 0) {
            fprintf(stderr, "Failed to add PDU at index %zu\n", i);
        }
    }
}

void unit_tests() {
    DynamicList *list = create_list(10);
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1234, 5678, {1}};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {2345, 6789, {0}};

    assert(add_pdu(list, pdu1) == 0);
    assert(add_pdu(list, pdu2) == 0);

    FILE *fp = fopen("list.bin", "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing\n");
        destroy_list(list);
        return;
    }

    assert(serialize_list(list, fp) == 0);
    fclose(fp);

    DynamicList *new_list = create_list(10);
    if (!new_list) {
        fprintf(stderr, "Failed to create new list\n");
        destroy_list(list);
        return;
    }

    fp = fopen("list.bin", "rb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for reading\n");
        destroy_list(new_list);
        destroy_list(list);
        return;
    }

    assert(deserialize_list(new_list, fp) == 0);
    fclose(fp);

    printf("Unit tests passed!\n");

    destroy_list(list);
    destroy_list(new_list);
}

int main() {
    unit_tests();
    return 0;
}
