#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct L2PDU {
    unsigned char *data;
    size_t length;
    int priority; // Higher value means higher priority
} L2PDU;

typedef struct Context {
    L2PDU **pdus;
    size_t num_pdus;
    pthread_mutex_t lock; // Mutex for thread safety
} Context;

typedef struct MACContextManager {
    Context **contexts;
    size_t context_count;
    pthread_rwlock_t rwlock; // Read-write lock for managing contexts
} MACContextManager;

MACContextManager* initialize_mac_context_manager() {
    MACContextManager *manager = (MACContextManager *)malloc(sizeof(MACContextManager));
    if (!manager) return NULL;

    manager->contexts = NULL;
    manager->context_count = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

int add_context(MACContextManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);

    // Allocate memory for a new context
    Context **new_contexts = (Context **)realloc(manager->contexts, 
                                                 (manager->context_count + 1) * sizeof(Context *));
    if (!new_contexts) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -1; // Memory allocation failed
    }

    manager->contexts = new_contexts;
    Context *new_context = (Context *)malloc(sizeof(Context));
    if (!new_context) {
        free(manager->contexts); 
        manager->contexts = NULL;
        pthread_rwlock_unlock(&manager->rwlock);
        return -1; // Memory allocation failed
    }

    new_context->pdus = NULL;
    new_context->num_pdus = 0;
    pthread_mutex_init(&new_context->lock, NULL);

    manager->contexts[manager->context_count] = new_context;
    manager->context_count++;

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Success
}

int add_l2_pdu_to_context(MACContextManager *manager, size_t context_index, L2PDU *l2_pdu) {
    pthread_rwlock_rdlock(&manager->rwlock);

    if (context_index >= manager->context_count) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -1; // Invalid context index
    }

    Context *context = manager->contexts[context_index];
    pthread_mutex_lock(&context->lock);

    // Allocate memory for the new L2PDU pointer
    L2PDU **new_pdus = (L2PDU **)realloc(context->pdus, 
                                         (context->num_pdus + 1) * sizeof(L2PDU *));
    if (!new_pdus) {
        pthread_mutex_unlock(&context->lock);
        pthread_rwlock_unlock(&manager->rwlock);
        return -1; // Memory allocation failed
    }

    context->pdus = new_pdus;
    context->pdus[context->num_pdus] = l2_pdu;
    context->num_pdus++;

    pthread_mutex_unlock(&context->lock);
    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Success
}

void adaptive_buffer_sizing(MACContextManager *manager) {
    // Placeholder for buffer sizing logic based on network conditions
    // Adjust buffer sizes dynamically in response to changes in load
}

void cleanup_mac_context_manager(MACContextManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->context_count; i++) {
        Context *context = manager->contexts[i];
        pthread_mutex_lock(&context->lock);

        free(context->pdus); // Free all L2PDU pointers
        pthread_mutex_unlock(&context->lock);

        pthread_mutex_destroy(&context->lock);
        free(context);
    }

    free(manager->contexts);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

int main() {
    MACContextManager *manager = initialize_mac_context_manager();
    if (!manager) return -1;

    add_context(manager); // Add a context
    L2PDU pdu = { .data = (unsigned char *)malloc(128), .length = 128, .priority = 5 };

    add_l2_pdu_to_context(manager, 0, &pdu);
    adaptive_buffer_sizing(manager);

    cleanup_mac_context_manager(manager);
    return 0;
}
