#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define M 100 // Max unique RNTI values
#define NFAPI_CRC_INDICATION_PDU_T_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned char CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Utility function to generate a random RNTI and ensure uniqueness
unsigned int generate_unique_RNTI(unsigned int *rnti_pool, unsigned int rnti_count) {
    static const char charset[] = "0123456789ABCDEF";
    unsigned int new_rnti;
    do {
        new_rnti = 0;
        for (int i = 0; i < 4; ++i) {
            new_rnti <<= 4;
            new_rnti |= (rand() % 16);
        }
    } while (rnti_count && !strchr((char*)rnti_pool, new_rnti));

    if (rnti_count < M) { // If we still have space for unique RNTIs
        rnti_pool[rnti_count++] = new_rnti;
    }
    return new_rnti;
}

Node* create_linked_list(unsigned int N) {
    if (N <= 0) return NULL;

    Node *head = NULL, *tail = NULL;
    unsigned int rnti_pool[M];
    memset(rnti_pool, 0, sizeof(rnti_pool));
    unsigned int rnti_count = 0;

    srand(time(NULL));

    for (unsigned int i = 0; i < N; ++i) {
        Node *new_node = (Node*)malloc(sizeof(Node));

        new_node->data.RX_UE_INFORMATION_TAG = rand() % 10000;
        unsigned int rnti;

        do {
            rnti = generate_unique_RNTI(rnti_pool, rnti_count);
        } while (tail && tail->data.RNTI == rnti);

        new_node->data.RNTI = rnti;

        memset(new_node->data.CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(new_node->data.CRC_INDICATION_REL8_TAG));
        new_node->data.CRCFLAG = rand() % 2;

        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    return head;
}

void free_linked_list(Node *head) {
    Node *tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

// Example usage
int main() {
    unsigned int N = 1000; // Number of elements in the linked list
    Node* list = create_linked_list(N);

    // Use the list...

    // Free the list
    free_linked_list(list);

    return 0;
}
