#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <arpa/inet.h>  // For IP address manipulation

#define INITIAL_BUFFER_SIZE 1024
#define MAX_PACKETS 1000

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol_id; 
} PacketHeader;

typedef struct {
    PacketHeader *headers;
    size_t capacity;
    size_t count;
    size_t buffer_size;
} NetworkInterface;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_error("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void resize_buffer(NetworkInterface *netif, size_t new_size) {
    netif->buffer_size = new_size;
    netif->headers = realloc(netif->headers, new_size * sizeof(PacketHeader));
    if (!netif->headers) {
        log_error("Buffer resizing failed");
        exit(EXIT_FAILURE);
    }
}

void initialize_network_interface(NetworkInterface *netif) {
    netif->capacity = MAX_PACKETS;
    netif->count = 0;
    netif->buffer_size = INITIAL_BUFFER_SIZE;

    netif->headers = safe_malloc(netif->capacity * sizeof(PacketHeader));
}

void configure_packet_header(PacketHeader *header, const char *src_ip_str,
                             const char *dst_ip_str, uint16_t src_port,
                             uint16_t dst_port, uint8_t protocol_id) {
    header->src_ip = inet_addr(src_ip_str);
    header->dst_ip = inet_addr(dst_ip_str);
    header->src_port = htons(src_port);
    header->dst_port = htons(dst_port);
    header->protocol_id = protocol_id;
}

void adjust_buffer_size(NetworkInterface *netif, size_t incoming_rate, double latency) {
    // Simple heuristic to resize buffer: increase for high rate and latency
    if (incoming_rate > netif->buffer_size / 2 || latency > 0.1) {
        resize_buffer(netif, netif->buffer_size * 2);
    } else if (netif->count < netif->buffer_size / 4 && netif->buffer_size > INITIAL_BUFFER_SIZE) {
        // Shrink buffer if underutilized
        resize_buffer(netif, netif->buffer_size / 2);
    }
}

void process_packet(NetworkInterface *netif, const char *src_ip_str,
                    const char *dst_ip_str, uint16_t src_port,
                    uint16_t dst_port, uint8_t protocol_id) {
    if (netif->count >= netif->capacity) {
        log_error("Buffer overflow");
        return;
    }

    PacketHeader header;
    configure_packet_header(&header, src_ip_str, dst_ip_str, src_port, dst_port, protocol_id);

    netif->headers[netif->count++] = header;
}

// Example usage
int main() {
    NetworkInterface netif;
    initialize_network_interface(&netif);

    // Simulate packet processing
    process_packet(&netif, "192.168.1.1", "192.168.1.2", 12345, 80, 6);
    adjust_buffer_size(&netif, 200, 0.05);

    // Free allocated resources
    free(netif.headers);

    return 0;
}
```

This C code implements a basic network interface initialization and configuration function suitable for packet processing tasks with dynamic buffer resizing based on incoming rate and latency.']

