#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct {
    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} Element;

pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random RNTI
int generate_unique_rnti(int *existing_rntis, size_t count) {
    int new_rnti;
    srand(time(NULL)); // Seed for randomness
    do {
        new_rnti = rand() % 0xFFFF; // Random RNTI in range 0 to 65535
    } while (count > 0 && bsearch(&new_rnti, existing_rntis, count, sizeof(int), cmpfunc));
    return new_rnti;
}

// Comparison function for qsort and bsearch
int cmpfunc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Function to initialize an Element structure with random values
void init_element(Element *e, int rx_ue_information_tag) {
    e->RNTI = generate_unique_rnti(NULL, 0); // Initially assuming no existing RNTIs
    e->CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    e->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

// Function to check and reassign duplicate RNTI
void ensure_unique_rnti(Element *elements, size_t count) {
    int existing_rntis[MAX_ELEMENTS];
    for (size_t i = 0; i < count; ++i) {
        existing_rntis[i] = elements[i].RNTI;
    }

    qsort(existing_rntis, count, sizeof(int), cmpfunc);

    for (size_t i = 1; i < count; ++i) {
        if (existing_rntis[i] == existing_rntis[i - 1]) {
            elements[i].RNTI = generate_unique_rnti(existing_rntis, i); // Ensure unique
        }
    }
}

// Function to dynamically allocate and initialize array
Element* create_nfa_pdu_array(size_t initial_size) {
    if (initial_size > MAX_ELEMENTS) {
        printf("Error: Requested size exceeds maximum allowed limit.\n");
        return NULL;
    }

    Element *array = malloc(initial_size * sizeof(Element));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        init_element(&array[i], rand() % 100); // Placeholder for actual RX_UE_INFORMATION_TAG
    }

    ensure_unique_rnti(array, initial_size);

    return array;
}

// Function to resize the array dynamically
Element* resize_nfa_pdu_array(Element *old_array, size_t current_size, size_t new_size) {
    if (new_size > MAX_ELEMENTS) {
        printf("Error: Requested resize exceeds maximum allowed limit.\n");
        free(old_array);
        return NULL;
    }

    Element *new_array = realloc(old_array, new_size * sizeof(Element));
    if (!new_array) {
        perror("Memory reallocation failed");
        free(old_array);
        return NULL;
    }

    for (size_t i = current_size; i < new_size; ++i) {
        init_element(&new_array[i], rand() % 100); // Placeholder for actual RX_UE_INFORMATION_TAG
    }

    ensure_unique_rnti(new_array, new_size);

    return new_array;
}

// Function to free the allocated memory
void free_nfa_pdu_array(Element *array) {
    if (array) {
        free(array);
    }
}

int main() {
    size_t initial_size = 100; // Starting with 100 elements for example
    Element *nfa_pdu_array = create_nfa_pdu_array(initial_size);

    if (nfa_pdu_array == NULL) return EXIT_FAILURE;

    pthread_mutex_lock(&array_lock);
    nfa_pdu_array = resize_nfa_pdu_array(nfa_pdu_array, initial_size, 2000); // Example resizing
    pthread_mutex_unlock(&array_lock);

    if (nfa_pdu_array == NULL) {
        printf("Failed to resize array.\n");
        return EXIT_FAILURE;
    }

    free_nfa_pdu_array(nfa_pdu_array);

    return EXIT_SUCCESS;
}
