#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure Definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Assuming RNTI is a unique identifier like an unsigned long
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
    unsigned long CRC_INDICATION_REL8_TAG;
} CRC_INDICATION_REL8_TAG_T;

// Global variables and constants
#define MAX_RNTIS 10000
#define MEMORY_THRESHOLD (1024 * 1024) // 1MB for example
#define CHUNK_SIZE 1000

unsigned long rnti_counter = 1; // Starting from 1 assuming 0 is reserved
pthread_mutex_t rnti_lock;
pthread_mutex_t memory_usage_lock;

unsigned long total_memory_usage = 0;
const unsigned long memory_usage_limit = (10 * MEMORY_THRESHOLD); // Example limit
int max_unique_rntis = MAX_RNTIS;

// Function prototypes
void log_error(const char* message);
NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_array(size_t n, int* success);

// Helper functions
unsigned long generate_unique_rnti() {
    unsigned long rnti;
    pthread_mutex_lock(&rnti_lock);
    do {
        rnti = rnti_counter++;
    } while (rnti >= max_unique_rntis);
    pthread_mutex_unlock(&rnti_lock);
    return rnti;
}

int check_rnti_uniqueness(unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T* array, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (array[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void initialize_mutexes() {
    pthread_mutex_init(&rnti_lock, NULL);
    pthread_mutex_init(&memory_usage_lock, NULL);
}

void destroy_mutexes() {
    pthread_mutex_destroy(&rnti_lock);
    pthread_mutex_destroy(&memory_usage_lock);
}

// Core function
NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_array(size_t n, int* success) {
    *success = 1;
    if (n == 0 || rnti_counter >= max_unique_rntis) {
        log_error("Invalid size or RNTI limit reached");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    size_t allocated_size = 0;

    for (size_t i = 0; i < n; i += CHUNK_SIZE) {
        size_t current_chunk = (n - i < CHUNK_SIZE) ? (n - i) : CHUNK_SIZE;
        size_t chunk_memory = current_chunk * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        pthread_mutex_lock(&memory_usage_lock);
        if (total_memory_usage + chunk_memory > memory_usage_limit) {
            log_error("Memory usage limit exceeded");
            *success = 0;
            free(array);
            array = NULL;
            break;
        }
        total_memory_usage += chunk_memory;

        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(array, (allocated_size + current_chunk) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            log_error("Memory allocation failed");
            *success = 0;
            free(array);
            pthread_mutex_unlock(&memory_usage_lock);
            return NULL;
        }
        array = temp_array;

        for (size_t j = 0; j < current_chunk; ++j) {
            array[allocated_size + j].RX_UE_INFORMATION_TAG = rand(); // Example random tag
            do {
                array[allocated_size + j].RNTI = generate_unique_rnti();
            } while (!check_rnti_uniqueness(array[allocated_size + j].RNTI, array, allocated_size + j));
            CRC_INDICATION_REL8_TAG_T* crc_tag = &array[allocated_size + j].CRC_INDICATION_REL8_TAG;
            crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        }
        allocated_size += current_chunk;

        pthread_mutex_unlock(&memory_usage_lock);
    }

    return array;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Main function for demonstration (can be removed in actual implementation)
int main() {
    initialize_mutexes();

    int success = 0;
    size_t n = 5000; // Example array size
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_nfaapi_crc_array(n, &success);

    if (success) {
        printf("Array allocated successfully with %zu elements.\n", n);
    } else {
        printf("Failed to allocate array.\n");
    }

    free(pdu_array);
    destroy_mutexes();
    return 0;
}
