#include <pthread.h>

typedef struct {
    char SRC_IP[16];
    char DEST_IP[16];
    unsigned short PORT;
    char *PAYLOAD;
} UDP_PACKET_INFO_T;

#define INITIAL_SIZE 1024
#define MAX_RETRIES 5

// External data source simulation functions
void get_src_ip(char* dest) { strcpy(dest, "192.168.1.1"); }
char* get_payload() { return strdup("Sample payload"); }

// Logging mechanism
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
int reassignments_count = 0;

void log_event(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message); // For simplicity, using standard output as the logging mechanism.
    pthread_mutex_unlock(&log_mutex);
}

// Check for unique DEST_IP
int is_unique_dest_ip(UDP_PACKET_INFO_T* array, int count, const char* dest_ip) {
    for (int i = 0; i < count; ++i) {
        if (strcmp(array[i].DEST_IP, dest_ip) == 0) {
            return 0;
        }
    }
    return 1;
}

// Generate unique DEST_IP
void generate_unique_dest_ip(char* dest_ip) {
    sprintf(dest_ip, "10.0.%d.%d", rand() % 256, rand() % 256);
}

pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

UDP_PACKET_INFO_T* manage_udp_packet_array(int initial_count) {
    UDP_PACKET_INFO_T *array = NULL;
    int capacity = INITIAL_SIZE;
    int count = 0;
    pthread_mutex_lock(&array_mutex);

    while (count < initial_count) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (capacity <= count) {
                UDP_PACKET_INFO_T* temp_array = realloc(array, sizeof(UDP_PACKET_INFO_T) * capacity * 2);
                if (!temp_array) {
                    log_event("Memory allocation failed; retrying...");
                    retries++;
                    continue;
                }
                array = temp_array;
                capacity *= 2;
            }

            UDP_PACKET_INFO_T* new_packet = &array[count];
            get_src_ip(new_packet->SRC_IP);

            char dest_ip_template[16] = "10.0.0.%d";
            sprintf(new_packet->DEST_IP, dest_ip_template, count % 256);

            while (!is_unique_dest_ip(array, count, new_packet->DEST_IP)) {
                generate_unique_dest_ip(new_packet->DEST_IP);
                log_event("DEST_IP reassignment due to collision");
                pthread_mutex_lock(&log_mutex);
                reassignments_count++;
                pthread_mutex_unlock(&log_mutex);
            }

            new_packet->PORT = rand() % 65536;
            new_packet->PAYLOAD = get_payload();
            if (!new_packet->PAYLOAD) {
                log_event("Failed to allocate payload memory");
                break; // Handle failure appropriately
            }

            count++;
            retries = MAX_RETRIES; // Break out of retry loop on success
        }

        if (retries == MAX_RETRIES && array != NULL) {
            for (int i = 0; i < count; ++i) {
                free(array[i].PAYLOAD);
            }
            free(array);
            log_event("Allocation retries exceeded, rolling back.");
            pthread_mutex_unlock(&array_mutex);
            return NULL;
        }
    }

    pthread_mutex_unlock(&array_mutex);

    // Logging final capacity and reassignments
    char final_message[128];
    sprintf(final_message, "Array initialized with %d elements. Reassignments: %d", count, reassignments_count);
    log_event(final_message);

    return array;
}

void free_udp_packet_array(UDP_PACKET_INFO_T* array) {
    if (array) {
        for (int i = 0; array[i].PAYLOAD != NULL; ++i) {
            free(array[i].PAYLOAD);
        }
        free(array);
    }
}
