#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

typedef struct {
    int connectionStrength;
    int latency;
} ConnectionStatus;

typedef struct {
    char* IpAddress;
    int PortNumber;
    ConnectionStatus* connections;
    size_t numConnections;
} NetworkInterfaceStatus;

typedef struct {
    NetworkInterfaceStatus** interfaces;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray* array) {
    array->interfaces = NULL;
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void freeConnectionStatus(ConnectionStatus* connections, size_t numConnections) {
    if (connections != NULL) {
        free(connections);
    }
}

void freeNetworkInterfaceStatus(NetworkInterfaceStatus* interface) {
    if (interface != NULL) {
        free(interface->IpAddress);
        freeConnectionStatus(interface->connections, interface->numConnections);
        free(interface);
    }
}

int resizeDynamicArray(DynamicArray* array) {
    size_t newCapacity = array->capacity == 0 ? 4 : array->capacity * 2;
    NetworkInterfaceStatus** newArray = realloc(array->interfaces, newCapacity * sizeof(NetworkInterfaceStatus*));
    if (newArray == NULL) return -1;

    for (size_t i = array->count; i < newCapacity; ++i) {
        newArray[i] = NULL;
    }

    array->interfaces = newArray;
    array->capacity = newCapacity;
    return 0;
}

int addNetworkInterface(DynamicArray* array, NetworkInterfaceStatus* interface) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        if (resizeDynamicArray(array) != 0) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    array->interfaces[array->count++] = interface;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int updateNetworkInterface(DynamicArray* array, size_t index, NetworkInterfaceStatus* newInterface) {
    if (index >= array->count || newInterface == NULL) {
        return -1;
    }

    pthread_mutex_lock(&array->lock);
    freeNetworkInterfaceStatus(array->interfaces[index]);
    array->interfaces[index] = newInterface;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

int removeNetworkInterface(DynamicArray* array, size_t index) {
    if (index >= array->count) {
        return -1;
    }

    pthread_mutex_lock(&array->lock);
    freeNetworkInterfaceStatus(array->interfaces[index]);
    for (size_t i = index; i < array->count - 1; ++i) {
        array->interfaces[i] = array->interfaces[i + 1];
    }
    --array->count;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void freeDynamicArray(DynamicArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        freeNetworkInterfaceStatus(array->interfaces[i]);
    }
    free(array->interfaces);
    pthread_mutex_destroy(&array->lock);
}

void logChange(const char* message) {
    printf("Log: %s\n", message); // Simplified logging mechanism
}

int generateRandomConnectionMetrics(ConnectionStatus* connection, size_t numConnections) {
    if (connection == NULL || numConnections == 0) return -1;

    for (size_t i = 0; i < numConnections; ++i) {
        connection[i].connectionStrength = rand() % 100;
        connection[i].latency = rand() % 50;
    }

    return 0;
}

void handleFailedConnection(NetworkInterfaceStatus* interface, ConnectionStatus* failedConnection) {
