// Node for RNTI tracking
typedef struct RNTINode {
    int rnti;
    struct RNTINode* next;
} RNTINode;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for the linked list
pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex for RNTI tracking

// Function prototypes
void initialize_rnti_tracking(RNTINode** head);
int is_rnti_unique(RNTINode* head, int rnti);
void add_rnti(RNTINode** head, int rnti);
void remove_rnti(RNTINode** head, int rnti);
void free_rnti_tracking(RNTINode* head);

NFAPI_CRC_INDICATION_PDU* create_node(int rx_ue_tag, int rnti, int crc_ind_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) return NULL;

    new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->RNTI = rnti;
    new_node->CRC_INDICATION_REL8_TAG = crc_ind_rel8_tag;
    new_node->next = NULL;

    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU** head, NFAPI_CRC_INDICATION_PDU* node) {
    pthread_mutex_lock(&list_mutex);

    if (*head == NULL) {
        *head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_list(NFAPI_CRC_INDICATION_PDU* head) {
    NFAPI_CRC_INDICATION_PDU* temp;

    pthread_mutex_lock(&list_mutex);

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

void manage_nfa_linked_list(NFAPI_CRC_INDICATION_PDU** head, int num_elements) {
    RNTINode* rnti_head = NULL;

    initialize_rnti_tracking(&rnti_head);

    for (int i = 0; i < num_elements; ++i) {
        int rx_ue_tag = rand();               // Replace with actual logic
        int rnti = rand() % 10000 + 1;        // Replace with actual RNTI generation and range fetch logic
        int crc_ind_rel8_tag = rand();        // Replace with actual logic

        pthread_mutex_lock(&rnti_mutex);
        while (!is_rnti_unique(rnti_head, rnti)) {
            rnti = rand() % 10000 + 1;
        }
        add_rnti(&rnti_head, rnti);
        pthread_mutex_unlock(&rnti_mutex);

        NFAPI_CRC_INDICATION_PDU* new_node = create_node(rx_ue_tag, rnti, crc_ind_rel8_tag);
        if (new_node) {
            add_to_list(head, new_node);
        }
    }

    free_rnti_tracking(rnti_head);
}

void initialize_rnti_tracking(RNTINode** head) {
    *head = NULL;
}

int is_rnti_unique(RNTINode* head, int rnti) {
    RNTINode* current = head;
    while (current != NULL) {
        if (current->rnti == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void add_rnti(RNTINode** head, int rnti) {
    RNTINode* new_node = (RNTINode*)malloc(sizeof(RNTINode));
    if (!new_node) return;

    new_node->rnti = rnti;
    new_node->next = *head;
    *head = new_node;
}

void remove_rnti(RNTINode** head, int rnti) {
    RNTINode* current = *head;
    RNTINode* prev = NULL;

    while (current != NULL && current->rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}

void free_rnti_tracking(RNTINode* head) {
    RNTINode* temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
