#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 10000
#define MAX_RNTI_COUNT 500
#define MEMORY_THRESHOLD (50 * 1024 * 1024) // 50 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    unsigned int rnti;
    struct Node* next;
} RNTINode;

typedef struct {
    size_t total_size;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_capacity;
    RNTINode *rnti_list;
    pthread_mutex_t rnti_lock;
} CRCIndicationManager;

static void* thread_safe_malloc(size_t size, pthread_mutex_t *mutex) {
    void *ptr = malloc(size);
    if (ptr == NULL || ((CRCIndicationManager*)pthread_getspecific(NULL))->total_size + size > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation failed or threshold exceeded.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(mutex);
    ((CRCIndicationManager*)pthread_getspecific(NULL))->total_size += size;
    if (((CRCIndicationManager*)pthread_getspecific(NULL))->total_size > MEMORY_THRESHOLD - (size * 2)) {
        fprintf(stderr, "Warning: Approaching memory threshold.\n");
    }
    pthread_mutex_unlock(mutex);
    return ptr;
}

static void resize_pool(CRCIndicationManager *manager) {
    size_t new_capacity = manager->pool_capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)thread_safe_malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), &manager->lock);

    memcpy(new_pool, manager->pool, manager->pool_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(manager->pool);
    manager->pool = new_pool;
    manager->pool_capacity = new_capacity;
}

static int insert_rnti(CRCIndicationManager *manager, unsigned int rnti) {
    pthread_mutex_lock(&manager->rnti_lock);

    RNTINode *current = manager->rnti_list;
    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&manager->rnti_lock);
            return 0; // Already exists
        }
        current = current->next;
    }

    RNTINode *new_node = (RNTINode*)thread_safe_malloc(sizeof(RNTINode), &manager->lock);
    new_node->rnti = rnti;
    new_node->next = manager->rnti_list;
    manager->rnti_list = new_node;

    pthread_mutex_unlock(&manager->rnti_lock);
    return 1; // Successfully inserted
}

CRCIndicationManager* initialize_crc_indication_manager() {
    CRCIndicationManager *manager = (CRCIndicationManager*)thread_safe_malloc(sizeof(CRCIndicationManager), NULL);

    manager->total_size = sizeof(CRCIndicationManager);
    pthread_mutex_init(&manager->lock, NULL);
    pthread_mutex_init(&manager->rnti_lock, NULL);

    size_t initial_pool_memory = INITIAL_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *initial_pool = (NFAPI_CRC_INDICATION_PDU_T *)thread_safe_malloc(initial_pool_memory, &manager->lock);

    manager->pool = initial_pool;
    manager->pool_capacity = INITIAL_POOL_SIZE;
    manager->rnti_list = NULL;

    return manager;
}

void initialize_structures(CRCIndicationManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->pool_capacity; ++i) {
        if (insert_rnti(manager, rand() % MAX_RNTI_COUNT + 1)) { // Random RNTI
            NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pool[i];
            pdu->RX_UE_INFORMATION_TAG = i;
            pdu->RNTI = rand() % MAX_RNTI_COUNT + 1;
            pdu->CRC_INDICATION_REL8_TAG = rand();
            pdu->CRCFLAG = rand() % 2;
        } else {
            resize_pool(manager);
            --i; // Retry this index with new pool
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    srand(time(NULL));
    CRCIndicationManager *manager = initialize_crc_indication_manager();
    initialize_structures(manager);

    NFAPI_CRC_INDICATION_PDU_T* first_element = manager->pool;
    printf("First element initialized: RX_UE_INFORMATION_TAG=%d, RNTI=%u\n", first_element->RX_UE_INFORMATION_TAG, first_element->RNTI);

    // Free resources
    pthread_mutex_destroy(&manager->lock);
    pthread_mutex_destroy(&manager->rnti_lock);
    free(manager->pool); 
    free(manager);

    return 0;
}
