#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 100

typedef struct CRCNode {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int8_t CRC_INDICATION_REL8_TAG[10];
    uint8_t CRCFLAG;
    struct CRCNode *prev, *next;
} CRCNode;

typedef struct CacheItem {
    CRCNode* node;
    struct CacheItem* next;
    struct CacheItem* prev;
} CacheItem;

typedef struct LRUCache {
    CacheItem *head, *tail;
    int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {0};

void init_cache() {
    pthread_mutex_init(&cache.lock, NULL);
}

void cleanup_cache() {
    pthread_mutex_lock(&cache.lock);
    CacheItem* current = cache.head;
    while (current) {
        CacheItem* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&cache.lock);
    pthread_mutex_destroy(&cache.lock);
}

void cache_put(CRCNode *node) {
    pthread_mutex_lock(&cache.lock);

    if (cache.size >= MAX_CACHE_SIZE) {
        CacheItem* lru = cache.tail;
        cache.tail = lru->prev;
        if (cache.tail) cache.tail->next = NULL;

        if (lru == cache.head) cache.head = cache.tail;

        free(lru);
        cache.size--;
    }

    CacheItem *new_item = malloc(sizeof(CacheItem));
    new_item->node = node;
    new_item->next = cache.head;
    new_item->prev = NULL;

    if (cache.head) cache.head->prev = new_item;
    cache.head = new_item;

    if (!cache.tail) cache.tail = new_item;

    cache.size++;
    pthread_mutex_unlock(&cache.lock);
}

CRCNode* cache_get(CRCNode *node) {
    pthread_mutex_lock(&cache.lock);

    CacheItem *current = cache.head;
    while (current) {
        if (current->node == node) {
            if (current != cache.head) {
                if (current == cache.tail) {
                    cache.tail = current->prev;
                    if (cache.tail) cache.tail->next = NULL;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                }

                current->next = cache.head;
                current->prev = NULL;

                if (cache.head) cache.head->prev = current;
                cache.head = current;
            }

            pthread_mutex_unlock(&cache.lock);
            return node;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

typedef struct NodeList {
    CRCNode *head, *tail;
    pthread_rwlock_t lock;
} NodeList;

void init_node_list(NodeList *list) {
    list->head = list->tail = NULL;
    pthread_rwlock_init(&list->lock, NULL);
}

void cleanup_node_list(NodeList *list) {
    pthread_rwlock_wrlock(&list->lock);
    CRCNode *current = list->head;
    while (current) {
        CRCNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
}

int is_rnti_present(NodeList *list, uint16_t rnti) {
    pthread_rwlock_rdlock(&list->lock);

    CRCNode *current = list->head;
    while (current) {
        if (current->RNTI == rnti) {
            pthread_rwlock_unlock(&list->lock);
            return 1;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void insert_node(NodeList *list, CRCNode *node) {
    if (is_rnti_present(list, node->RNTI)) {
        free(node);
        return;
    }

    pthread_rwlock_wrlock(&list->lock);

    if (!list->head) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    cache_put(node);
    pthread_rwlock_unlock(&list->lock);
}

void remove_node(NodeList *list, uint16_t rnti) {
    pthread_rwlock_wrlock(&list->lock);

    CRCNode *current = list->head;
    while (current && current->RNTI != rnti) {
        current = current->next;
    }

    if (!current) {
        pthread_rwlock_unlock(&list->lock);
        return;
    }

    if (current->prev) current->prev->next = current->next;
    else list->head = current->next;

    if (current->next) current->next->prev = current->prev;
    else list->tail = current->prev;

    free(current);
    pthread_rwlock_unlock(&list->lock);
}

CRCNode* create_node(uint32_t tag, uint16_t rnti) {
    CRCNode *node = malloc(sizeof(CRCNode));
    if (!node) return NULL;

    node->RX_UE_INFORMATION_TAG = tag;
    node->RNTI = rnti;
    for (int i = 0; i < 10; ++i) node->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    node->CRCFLAG = rand() & 1;
    node->prev = node->next = NULL;

    return node;
}

void log_operation(const char *operation, CRCNode *node) {
    printf("%s: RNTI=%d\n", operation, node ? node->RNTI : -1);
}

int main() {
    init_cache();
    NodeList list;
    init_node_list(&list);

    // Example usage
    for (uint16_t rnti = 0; rnti < 100; ++rnti) {
        CRCNode *node = create_node(rand(), rnti);
        if (node) {
            insert_node(&list, node);
            log_operation("Inserted", node);
        }
    }

    remove_node(&list, 42); // Example removal
    log_operation("Removed", NULL);

    cleanup_node_list(&list);
    cleanup_cache();

    return 0;
}
```

