// Mockup structure definitions
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
};

struct CryptoConfig {
    bool enable_encryption;
    std::string algorithm;
};

// Global Mutex for thread-safety
std::mutex list_mutex;
std::unordered_set<uint16_t> rnti_global_set;

bool fetchRNTIRangesFromRemoteService(std::vector<uint16_t>& ranges);
bool fetchConflictResolutionFromLocalDB(uint16_t& rnti);

class CRCIndicationList {
public:
    struct Node {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> data;
        std::unique_ptr<Node> next;

        Node(NFAPI_CRC_INDICATION_PDU_T* pdu) : data(pdu), next(nullptr) {}
    };

private:
    std::unique_ptr<Node> head;
    uint32_t unique_tag_counter = 0;

public:
    void addEntry(const NFAPI_CRC_INDICATION_PDU_T& pdu);
    bool resolveRNTIConflict(uint16_t& rnti);

    // Custom serialization/deserialization
    bool serializeToFile(const std::string& filename);
    bool deserializeFromFile(const std::string& filename, CryptoConfig& config);

    void traverseList();
};

void CRCIndicationList::addEntry(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    auto new_pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu);

    // Ensure RNTI is globally unique
    uint16_t rnti = new_pdu->RNTI;
    if (rnti_global_set.find(rnti) != rnti_global_set.end()) {
        if (!resolveRNTIConflict(rnti)) {
            throw std::runtime_error("Failed to resolve RNTI conflict.");
        }
        new_pdu->RNTI = rnti;
    }

    // Add the entry to the list
    std::lock_guard<std::mutex> lock(list_mutex);
    auto* node = new Node(new_pdu.release());
    node->next = std::move(head);
    head.reset(node);

    // Mark as globally unique
    rnti_global_set.insert(rnti);
}

bool CRCIndicationList::resolveRNTIConflict(uint16_t& rnti) {
    if (!fetchConflictResolutionFromLocalDB(rnti)) {
        return false;
    }
    return true;
}

bool CRCIndicationList::serializeToFile(const std::string& filename) {
    // Example serialization implementation
    std::lock_guard<std::mutex> lock(list_mutex);
    std::ofstream ofs(filename, std::ios::binary);

    if (!ofs.is_open()) {
        return false;
    }

    for (auto* node = head.get(); node != nullptr; node = node->next.get()) {
        uint32_t tag_size = sizeof(node->data->RX_UE_INFORMATION_TAG);
        ofs.write(reinterpret_cast<char*>(&tag_size), sizeof(tag_size));
        ofs.write(reinterpret_cast<char*>(&node->data->RX_UE_INFORMATION_TAG), tag_size);

        uint16_t rnti_size = sizeof(node->data->RNTI);
        ofs.write(reinterpret_cast<char*>(&rnti_size), sizeof(rnti_size));
        ofs.write(reinterpret_cast<char*>(&node->data->RNTI), rnti_size);

        uint8_t crc_size[4] = {sizeof(node->data->CRC_INDICATION_REL8_TAG)};
        ofs.write(reinterpret_cast<char*>(crc_size), 4);
        ofs.write(reinterpret_cast<char*>(node->data->CRC_INDICATION_REL8_TAG), sizeof(node->data->CRC_INDICATION_REL8_TAG));
    }

    return true;
}

bool CRCIndicationList::deserializeFromFile(const std::string& filename, CryptoConfig& config) {
    // Example deserialization implementation
    std::ifstream ifs(filename, std::ios::binary);

    if (!ifs.is_open()) {
        return false;
    }

    while (ifs.good()) {
        uint32_t tag_size, rnti_size, crc_size[4];

        ifs.read(reinterpret_cast<char*>(&tag_size), sizeof(tag_size));
        NFAPI_CRC_INDICATION_PDU_T pdu;

        std::unique_ptr<uint8_t[]> buffer(new uint8_t[tag_size]);
        ifs.read(reinterpret_cast<char*>(buffer.get()), tag_size);
        memcpy(&pdu.RX_UE_INFORMATION_TAG, buffer.get(), tag_size);

        ifs.read(reinterpret_cast<char*>(&rnti_size), sizeof(rnti_size));
        std::unique_ptr<uint8_t[]> rntibuffer(new uint8_t[rnti_size]);
        ifs.read(reinterpret_cast<char*>(rntibuffer.get()), rnti_size);
        memcpy(&pdu.RNTI, rntibuffer.get(), rnti_size);

        ifs.read(reinterpret_cast<char*>(&crc_size), 4);
        std::unique_ptr<uint8_t[]> crcbuffer(new uint8_t[crc_size[0]]);
        ifs.read(reinterpret_cast<char*>(crcbuffer.get()), crc_size[0]);
        memcpy(pdu.CRC_INDICATION_REL8_TAG, crcbuffer.get(), crc_size[0]);

        addEntry(pdu);

        if (!ifs.good()) break;
    }

    return true;
}

void CRCIndicationList::traverseList() {
    std::lock_guard<std::mutex> lock(list_mutex);
    for (auto* node = head.get(); node != nullptr; node = node->next.get()) {
