#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024 // Define max buffer size based on system constraints

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO_TAG;

typedef struct {
    uint8_t CRCFLAG; // Assuming CRCFLAG is a single byte
} CRC_INDICATION_REL8_TAG;

typedef struct {
    UE_INFO_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    SUCCESS,
    FAILURE_INSUFFICIENT_BUFFER,
    FAILURE_MEMORY_ALLOCATION
} AllocationStatus;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function to check if structure is valid
bool is_valid_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    return pdu != NULL && 
           pdu->ue_info.RX_UE_INFORMATION_TAG > 0 &&
           pdu->crc_indication.CRCFLAG >= 0;
}

AllocationStatus allocate_nfaapi_crc_pdu(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    pthread_mutex_lock(&mutex); // Lock for thread safety

    if (num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_BUFFER_SIZE) {
        pthread_mutex_unlock(&mutex);
        return FAILURE_INSUFFICIENT_BUFFER;
    }

    NFAPI_CRC_INDICATION_PDU_T *allocated_pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (allocated_pdus == NULL) {
        pthread_mutex_unlock(&mutex);
        return FAILURE_MEMORY_ALLOCATION;
    }

    for (int i = 0; i < num_pdus; ++i) {
        allocated_pdus[i].ue_info.RX_UE_INFORMATION_TAG = (uint8_t)(rand() % 256); // Random valid tag
        allocated_pdus[i].ue_info.RNTI = (uint16_t)(rand() % 65536); // Random RNTI
        allocated_pdus[i].crc_indication.CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1

        if (!is_valid_pdu(&allocated_pdus[i])) {
            free(allocated_pdus);
            pthread_mutex_unlock(&mutex);
            return FAILURE_MEMORY_ALLOCATION;
        }
    }

    *pdus = allocated_pdus;
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
