    if (!validate_ip(src_ip) || !validate_ip(dest_ip)) {
        fprintf(stderr, "Invalid IP address\n");
        return -1;
    }

    if (!validate_port(src_port) || !validate_port(dest_port)) {
        fprintf(stderr, "Invalid port number\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_PACKETS) {
        fprintf(stderr, "Packet list is full\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NetworkPacket* packet = malloc(sizeof(NetworkPacket));
    if (!packet) {
        fprintf(stderr, "Failed to allocate memory for a new packet\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    strcpy(packet->header.source_ip, src_ip);
    strcpy(packet->header.destination_ip, dest_ip);
    packet->header.source_port = src_port;
    packet->header.destination_port = dest_port;
    packet->header.payload_size = payload_size;
    packet->sequence_number = rand();  // Example for sequence number
    packet->is_processed = 0;

    list->packets[list->count++] = packet;

    pthread_mutex_unlock(&list->lock);

    return 0;  // Success
}

