    size_t count;
    size_t capacity;
} MAC_Context;

typedef void (*PacketProcessingCallback)(L2PDU_Packet*);

typedef struct {
    MAC_Context **contexts;
    size_t context_count;
    PacketProcessingCallback processing_callback;
    pthread_mutex_t lock;
    int is_multi_threaded;
} NetworkManager;

void init_mac_context(MAC_Context *context, size_t initial_capacity) {
    context->packets = (L2PDU_Packet*)malloc(initial_capacity * sizeof(L2PDU_Packet));
    if (!context->packets) {
        perror("Failed to allocate memory for MAC context");
        exit(EXIT_FAILURE);
    }
    context->capacity = initial_capacity;
    context->count = 0;
}

void resize_mac_context(MAC_Context *context, size_t new_capacity) {
    L2PDU_Packet *new_packets = (L2PDU_Packet*)realloc(context->packets, new_capacity * sizeof(L2PDU_Packet));
    if (!new_packets) {
        perror("Failed to reallocate memory for MAC context");
        exit(EXIT_FAILURE);
    }
    context->packets = new_packets;
    context->capacity = new_capacity;
}

void process_packet_async(MAC_Context *context, L2PDU_Packet packet) {
    if (context->count >= context->capacity) {
        resize_mac_context(context, context->capacity * 2);
    }

    context->packets[context->count++] = packet;

    // Process the packet using a callback function
    for (size_t i = 0; i < context->count; ++i) {
        if (network_manager.processing_callback)
            network_manager.processing_callback(&context->packets[i]);
    }
}

void initialize_network_manager(size_t num_contexts, PacketProcessingCallback callback, int multi_threaded) {
    NetworkManager *manager = (NetworkManager*)malloc(sizeof(NetworkManager));

    manager->contexts = (MAC_Context**)malloc(num_contexts * sizeof(MAC_Context*));
    if (!manager->contexts) {
        perror("Failed to allocate memory for MAC contexts");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < num_contexts; ++i) {
        MAC_Context *context = (MAC_Context*)malloc(sizeof(MAC_Context));
        size_t initial_capacity = get_initial_packet_capacity(); // Hypothetical function
        init_mac_context(context, initial_capacity);
        manager->contexts[i] = context;
    }

    manager->context_count = num_contexts;
    manager->processing_callback = callback;
    manager->is_multi_threaded = multi_threaded;

    network_manager = *manager;  // Storing in a global variable for simplicity
}

void cleanup_network_manager() {
    for (size_t i = 0; i < network_manager.context_count; ++i) {
        free(network_manager.contexts[i]->packets);
        free(network_manager.contexts[i]);
    }
    free(network_manager.contexts);
    pthread_mutex_destroy(&network_manager.lock);
    free(&network_manager);
}

// Example usage
void packet_processing_callback(L2PDU_Packet* packet) {
    // Handle packet processing logic here, e.g., simulate sending or logging
    printf("Processing packet with size: %zu\n", packet->packet_size);
}

int main() {
