NFAPI_CRC_INDICATION_PDU_T** manage_crc_list(size_t n, uint8_t* log_stats) {
    if (n > N || T < sizeof(NFAPI_CRC_INDICATION_PDU_T) * n) {
        return NULL;
    }

    size_t total_memory_allocated = 0;
    bool success_allocations[N] = {false};
    size_t unique_rnti_count = 0;

    // Allocate memory for list
    NFAPI_CRC_INDICATION_PDU_T** crc_list = (NFAPI_CRC_INDICATION_PDU_T**)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_list) {
