        return NULL;
    }
    total_memory_allocated += n * sizeof(NFAPI_CRC_INDICATION_PDU_T*);

    uint16_t last_rnti = 0xFFFF; // Sentinel value
    srand(time(NULL)); // Seed for randomness

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu || total_memory_allocated + sizeof(NFAPI_CRC_INDICATION_PDU_T) > T) {
            log_memory_action("Failed allocation", sizeof(NFAPI_CRC_INDICATION_PDU_T));
            success_allocations[i] = false;
            break;
        }

        // Set fields
        pdu->RX_UE_INFORMATION_TAG = rand() % 256; // Assuming a valid range
        do {
            pdu->RNTI = rand() % get_band_specific_rnti_limit(rand() % 5); // Random band
        } while (pdu->RNTI == last_rnti);
        last_rnti = pdu->RNTI;

        if (!success_allocations[unique_rnti_count]) {
            success_allocations[unique_rnti_count] = true;
            unique_rnti_count++;
        }

        pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Assuming a valid range
        pdu->CRCFLAG = rand() % 2;

        crc_list[i] = pdu;
        total_memory_allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        log_memory_action("Allocated", sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    *log_stats = unique_rnti_count;
    return crc_list;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (list[i]) {
            free(list[i]);
            log_memory_action("Deallocated", sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
    free(list);
}

int main() {
