#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_INT_VALUE -1000
#define MAX_INT_VALUE 1000

typedef struct {
    int key;
    long offset;
} Offset;

typedef struct {
    int value;
    Offset *offset_ptr;
} Record;

typedef struct {
    uint32_t crc_flag;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int rnti;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int key;
    Offset *offset_ptr;
    struct Node *next;
} HashNode;

#define HASH_TABLE_SIZE 1009

HashNode *hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_locks[HASH_TABLE_SIZE];

unsigned int hash_function(int key) {
    return (unsigned int)(key % HASH_TABLE_SIZE);
}

void initialize_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_locks[i], NULL);
    }
}

void insert_into_hash(int key, Offset *offset_ptr) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&hash_locks[index]);

    HashNode *new_node = malloc(sizeof(HashNode));
    if (new_node == NULL) {
        perror("Failed to allocate memory for hash node");
        exit(EXIT_FAILURE);
    }

    new_node->key = key;
    new_node->offset_ptr = offset_ptr;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    pthread_mutex_unlock(&hash_locks[index]);
}

int check_hash(int key) {
    unsigned int index = hash_function(key);
    pthread_mutex_lock(&hash_locks[index]);

    HashNode *node = hash_table[index];
    while (node != NULL) {
        if (node->key == key) {
            pthread_mutex_unlock(&hash_locks[index]);
            return 1;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&hash_locks[index]);
    return 0;
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode *node = hash_table[i];
        while (node != NULL) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
        pthread_mutex_destroy(&hash_locks[i]);
    }
}

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int generate_unique_key() {
    int key;
    do {
        key = rand() % MAX_RECORDS;
    } while (check_hash(key));
    return key;
}

Record *initialize_records(int num_records, int *keys, long *offsets, size_t offset_count) {
    if (num_records <= 0 || keys == NULL || offsets == NULL || offset_count <= 0) {
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    initialize_hash_table();
    initialize_random();

    for (int i = 0; i < num_records; ++i) {
