        do {
            key = generate_unique_key();
        } while (key >= offset_count);

        int value = MIN_INT_VALUE + rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1);

        insert_into_hash(key, &((Offset){keys[key], offsets[key]}));

        records[i].value = value;
        records[i].offset_ptr = &((Offset){keys[key], offsets[key]});
    }

    return records;
}

NFAPI_CRC_INDICATION_PDU_T *initialize_nfa_pdu(int num_pdu) {
