/**
 * Function to dynamically manage and initialize memory for multiple data structures
 * under specified constraints. Ensures efficient and error-free operation in a 
 * high-throughput, concurrent environment.
 *
 * Design Decisions:
 * 1. Used dynamic allocation with realloc for flexibility in input size handling.
 * 2. Thread safety ensured through atomic operations and optional mutex locking.
 * 3. Memory allocation failure is gracefully handled by freeing allocated resources.
 * 4. Lock-free structures not utilized to maintain simplicity; further optimizations 
 *    could consider lock-free queues or stacks if contention becomes an issue.
 * 5. Trade-offs:
 *     - Realloc vs. pre-allocated fixed-size arrays: Flexibility vs. potential reallocation overhead.
 *     - Memory usage vs. speed: Dynamic memory management can introduce latency due to allocation delays.
 *
 */
void manage_memory_and_process() {
    int* array = NULL;
    size_t capacity = 10; // Initial capacity for integer array
    size_t count = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    size_t num_structs = 0;

    printf("Enter integers (Ctrl+D to end):\n");
    int value;
    while (scanf("%d", &value) == 1 && count < MAX_INPUT) {
        if (count >= capacity) {
            // Double the capacity
            capacity *= 2;
            array = realloc(array, capacity * sizeof(int));
            if (!array) {
                printf("Memory allocation failed. Exiting.\n");
                free_resources((int*)array, count, &list);
                return;
            }
        }
        array[count++] = value;

        // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
        pthread_mutex_lock(&lock);  // Lock for thread safety during list modification
        list = realloc(list, (num_structs + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list) {
            printf("Memory allocation failed. Exiting.\n");
            free_resources((int*)array, count, &list);
            return;
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[num_structs++];
        pdu->RX_UE_INFORMATION_TAG = (uint16_t)(rand() % 65536); // Random tag
        pdu->RNTI = (uint16_t)(rand() % 65536);                   // Random RNTI
        pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);    // Random CRC tag
        pdu->CRCFLAG = rand() % 2;                                // Random CRC flag

        pthread_mutex_unlock(&lock);
    }

    if (count > 0) {
        int largest = calculate_largest_int(array, count);
        printf("Largest integer: %d\n", largest);

        for (size_t i = 0; i < num_structs; ++i) {
            printf("PDU %zu - RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u, CRCFLAG: %d\n",
                   i, list[i].RX_UE_INFORMATION_TAG, list[i].RNTI,
                   list[i].CRC_INDICATION_REL8_TAG, list[i].CRCFLAG);
        }
    }

    // Free allocated resources
    free_resources(array, count, &list);
}

int calculate_largest_int(const int* array, size_t size) {
    atomic_thread_fence(memory_order_acquire); // Ensure memory visibility for concurrency

    int largest = INT32_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    atomic_thread_fence(memory_order_release);
    return largest;
}

void free_resources(int* array, size_t count, NFAPI_CRC_INDICATION_PDU_T** list) {
    free(array); 
    free(*list);
}
