    unsigned long result = rand();
    pthread_mutex_unlock(&lock);
    return result;
}

int isKeyUnique(int key) {
    int index = abs(key % HASH_TABLE_SIZE);
    Node* current = hashTable[index];

    while (current != NULL) {
        if (current->key == key) return 0; // Key not unique
        current = current->next;
    }
    return 1; // Key is unique
}

