#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Assuming these types are defined somewhere else in your codebase
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_indication(CRCList* list, int rx_ue_info_tag, int rnti, int crc_rel8_tag, int seed, int default_flag) {
    if (!list) return -1;

    srand(seed); // Seed for deterministic testing
    int crcflag = (rand() % 2) ? default_flag : default_flag ^ 0x01; // Randomly set CRCFLAG

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data.rx_ue_information_tag = rx_ue_info_tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication_rel8_tag = crc_rel8_tag;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_crc_indication(CRCList* list, int rnti) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Not found
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) { // Head node needs to be removed
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
}

void print_crc_list(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("RX UE Info Tag: %d, RNTI: %d, CRC Ind Rel8 Tag: %d\n",
               current->data.rx_ue_information_tag,
               current->data.rnti,
               current->data.crc_indication_rel8_tag);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Usage example
int main() {
    CRCList* list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to create CRC list.\n");
        return 1;
    }

    add_crc_indication(list, 1234, 5678, 91011, time(NULL), 0);
    print_crc_list(list);

    remove_crc_indication(list, 5678);
    print_crc_list(list);

    destroy_crc_list(list);
    return 0;
}
