void manage_dynamic_list(int (*get_external_data)(void), bool concurrent_mode) {
    Queue* queue = create_queue();
    if (!queue) return;

    int N = get_external_data();
    pthread_t threads[concurrent_mode ? 4 : 1];
    srand(time(NULL));

    for (int i = 0; i < (concurrent_mode ? 4 : 1); ++i) {
        pthread_create(&threads[i], NULL, ^(void* arg) {
            for (int j = 0; j < N / (concurrent_mode ? 4 : 1); ++j) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
                pdu.RNTI = rand() % 10000;
                pdu.CRC_INDICATION_REL8_TAG = rand() % 10000;
                pdu.CRCFLAG = rand() % 2 == 0;

                sem_wait(&queue->slots);
                sem_wait(&queue->mutex);

                if (enqueue(queue, pdu)) {
                    log_message("Enqueued successfully");
                } else {
                    log_message("Queue is full");
                }

                sem_post(&queue->mutex);
                sem_post(&queue->items);
            }
        }, NULL);
    }

    for (int i = 0; i < (concurrent_mode ? 4 : 1); ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_queue(queue);
}

Queue* create_queue() {
    Queue* queue = malloc(sizeof(Queue));
    if (!queue) return NULL;

    queue->front = queue->rear = NULL;
    queue->size = 0;
    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->slots, 0, MAX_QUEUE_SIZE);
    sem_init(&queue->items, 0, 0);

    return queue;
}

bool enqueue(Queue* queue, NFAPI_CRC_INDICATION_PDU_T item) {
    if (queue->size >= MAX_QUEUE_SIZE) return false;

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return false;

    newNode->data = item;
    newNode->next = NULL;

    sem_wait(&queue->mutex);
    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }
    queue->size++;
    sem_post(&queue->mutex);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T dequeue(Queue* queue) {
    NFAPI_CRC_INDICATION_PDU_T item;

    sem_wait(&queue->items);
    sem_wait(&queue->mutex);

    if (queue->front == NULL) {
        sem_post(&queue->mutex);
        return item; // Return default-initialized struct
    }

    Node* temp = queue->front;
    item = temp->data;
    queue->front = queue->front->next;

    if (queue->front == NULL) {
        queue->rear = NULL;
    }

    free(temp);
    queue->size--;

    sem_post(&queue->mutex);
    sem_post(&queue->slots);

    return item;
}

void destroy_queue(Queue* queue) {
    while (queue->size > 0) {
        dequeue(queue);
    }

    sem_destroy(&queue->mutex);
    sem_destroy(&queue->slots);
    sem_destroy(&queue->items);
    free(queue);
}

void initialize_logging(bool enable) {
    // Placeholder for initializing logging
}

void log_message(const char* message) {
    if (true) { // Assume logging is enabled
        printf("%s\n", message);
    }
}
