void init_request_queue(RequestQueue *rq, int initial_max_pending) {
    rq->head = 0;
    rq->tail = 0;
    rq->count = 0;
    pthread_mutex_init(&rq->lock, NULL);
    sem_init(&rq->full_slots, 0, 0);
    sem_init(&rq->empty_slots, 0, MAX_QUEUE_SIZE);

    // Dynamically adjust max_pending_connections based on system load
    rq->max_pending_connections = initial_max_pending;
}

void enqueue_connection(RequestQueue *rq, ConnectionRequest *request) {
    sem_wait(&rq->empty_slots);

    pthread_mutex_lock(&rq->lock);
    if (rq->count < MAX_QUEUE_SIZE) {
        rq->queue[rq->tail] = request;
        rq->tail = (rq->tail + 1) % MAX_QUEUE_SIZE;
        rq->count++;
    }
    pthread_mutex_unlock(&rq->lock);

    sem_post(&rq->full_slots);
}

ConnectionRequest* dequeue_connection(RequestQueue *rq) {
    ConnectionRequest *request = NULL;

    sem_wait(&rq->full_slots);

    pthread_mutex_lock(&rq->lock);
    if (rq->count > 0) {
        request = rq->queue[rq->head];
        rq->head = (rq->head + 1) % MAX_QUEUE_SIZE;
        rq->count--;
    }
    pthread_mutex_unlock(&rq->lock);

    sem_post(&rq->empty_slots);
    return request;
}

