        result = realloc(cache, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (result) break;

        log_message("Memory allocation failed, retrying with smaller chunk...");
        N /= 2;
        attempts++;

        if (is_memory_threshold_exceeded()) {
            log_message("Switching to custom allocator due to memory threshold");
            // Implement custom allocator strategy here
