        return NULL;
    }

    metrics.count_allocations++;
    for (int i = 0; i < N; ++i) {
        pthread_t thread_id = pthread_self();
        result[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        result[i].RNTI = ((uint16_t)thread_id & 0xFFFF) | (rand() & 0x1);
        result[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        result[i].CRCFLAG = rand() % 2;
    }

    return result;
}

void reset_allocation_metrics() {
    pthread_mutex_lock(&metrics_lock);
    memset(&metrics, 0, sizeof(AllocationMetrics));
    pthread_mutex_unlock(&metrics_lock);
}

void display_allocation_metrics() {
    pthread_mutex_lock(&metrics_lock);
    printf("Allocations: %zu\n", metrics.count_allocations);
    printf("Deallocations: %zu\n", metrics.count_deallocations);
    printf("Cache Hits: %zu\n", metrics.cache_hits);
    printf("Cache Misses: %zu\n", metrics.cache_misses);
    pthread_mutex_unlock(&metrics_lock);
}

// Usage example
int main() {
    int N = 10000;
    NFAPI_CRC_INDICATION_PDU_T *pdus = allocate_nfaapi_crc_indication_pdus(N);
    if (pdus) {
        display_allocation_metrics();
        free(pdus); // Deallocate and reset metrics for reuse
        metrics.count_deallocations++;
    }
    reset_allocation_metrics();  // Reset for subsequent operations

    return 0;
}
