#define MAX_ATTEMPTS 5
#define MIN_PAYLOAD_SIZE 50
#define MAX_PAYLOAD_SIZE 500

typedef struct {
    uint16_t MAC_PDCP_SN;
} MAC_PDCP_SN_T;

typedef struct {
    size_t payload_size;
    char *data;
} L1_TO_L2_MESSAGE_T;

typedef struct {
    int status;
} L2_TO_L1_MESSAGE_T;

typedef struct {
    MAC_PDCP_SN_T mac_pdc_counter;
    L1_TO_L2_MESSAGE_T l1_to_l2_message;
    L2_TO_L1_MESSAGE_T l2_to_l1_message;
} MAC_CONTEXT_T;

int reallocation_attempts = 0;
size_t total_memory_allocated = 0;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;

MAC_CONTEXT_T* allocate_mac_contexts(size_t N) {
    pthread_mutex_lock(&allocation_lock);

    size_t chunk_size = 256; // Start with a small chunk size
    MAC_CONTEXT_T *contexts = NULL;
    size_t current_size = 0;

    while (reallocation_attempts < MAX_ATTEMPTS) {
        size_t new_size = current_size + chunk_size;

        if ((contexts = realloc(contexts, new_size * sizeof(MAC_CONTEXT_T))) != NULL) {
            total_memory_allocated += chunk_size * sizeof(MAC_CONTEXT_T);
            current_size = new_size;

            for (size_t i = current_size - chunk_size; i < current_size && N > 0; ++i, --N) {
                // Initialize MAC_PDCP_SN with a wrap-around mechanism
                contexts[i].mac_pdc_counter.MAC_PDCP_SN = (i + 1) % 65536;

                // Random payload size between MIN_PAYLOAD_SIZE and MAX_PAYLOAD_SIZE
                size_t payload_size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1) + MIN_PAYLOAD_SIZE;
                contexts[i].l1_to_l2_message.payload_size = payload_size;

                if ((contexts[i].l1_to_l2_message.data = malloc(payload_size)) == NULL) {
                    // Handle memory allocation failure
                    free(contexts[i].l1_to_l2_message.data);
                    return NULL; // Unable to allocate required memory
                }

                memset(contexts[i].l1_to_l2_message.data, 0, payload_size); // Initialize with random data

                contexts[i].l2_to_l1_message.status = 0; // Default status
            }

            reallocation_attempts = 0; // Reset attempts on success
            if (N == 0) break; // All contexts are allocated
        } else {
            ++reallocation_attempts;
            chunk_size /= 2; // Reduce the chunk size and retry
        }
    }

    pthread_mutex_unlock(&allocation_lock);

    return contexts;
}

void free_mac_contexts(MAC_CONTEXT_T *contexts, size_t N) {
    if (contexts == NULL) return;

    for (size_t i = 0; i < N; ++i) {
        free(contexts[i].l1_to_l2_message.data);
    }

    free(contexts);
}

void log_allocation_details() {
    printf("Total memory allocated: %zu bytes\n", total_memory_allocated);
    printf("Reallocation attempts: %d\n", reallocation_attempts);
}
