    Request requests[MAX_REQUESTS];
    int count;
    pthread_mutex_t lock;
} RequestWindow;

typedef struct {
    double avg_payload_size;
    long max_latency_ms;
    int request_frequency;
} Metrics;

typedef struct {
    size_t payload_threshold;
    long latency_threshold_ms;
} Thresholds;

RequestWindow window = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};
Metrics metrics = {0};
Thresholds thresholds = {1024, 100}; // Default values

void load_config() {
    char *payload_env = getenv("PAYLOAD_THRESHOLD");
    char *latency_env = getenv("LATENCY_THRESHOLD");

    if (payload_env) thresholds.payload_threshold = strtoul(payload_env, NULL, 10);
    if (latency_env) thresholds.latency_threshold_ms = strtol(latency_env, NULL, 10);
}

void log_request(Request req) {
    pthread_mutex_lock(&window.lock);

    // Slide window
    memmove(window.requests, &window.requests[1], sizeof(Request) * (--window.count));
    window.requests[window.count++] = req;

    pthread_mutex_unlock(&window.lock);

    // Calculate metrics
    long now = time(NULL) * 1000;
    size_t total_size = 0;
    long max_latency = 0, freq = 0;

    for (int i = 0; i < window.count; ++i) {
        if ((now - window.requests[i].timestamp) <= INTERVAL_MS) {
            total_size += window.requests[i].payload_size;
            long latency = now - window.requests[i].timestamp;
            if (latency > max_latency) max_latency = latency;
            freq++;
        }
    }

    metrics.avg_payload_size = total_size / (double)window.count;
    metrics.max_latency_ms = max_latency;
    metrics.request_frequency = freq;

    // Log to external service
    if (freq > 0 && metrics.max_latency_ms > thresholds.latency_threshold_ms) {
        printf("Logging: Avg Size=%zu, Max Latency=%ld ms, Frequency=%d\n",
               metrics.avg_payload_size,
               metrics.max_latency_ms,
               metrics.request_frequency);
    }
}

void *handle_request(void *arg) {
    Request req = *(Request *)arg;
    log_request(req);
    free(arg);
    return NULL;
}

void process_requests(size_t payload_sizes[], int num_requests) {
    pthread_t threads[num_requests];

    for (int i = 0; i < num_requests; ++i) {
        Request *req = malloc(sizeof(Request));
        req->payload_size = payload_sizes[i];
        req->timestamp = time(NULL) * 1000;

        pthread_create(&threads[i], NULL, handle_request, req);
    }

    for (int i = 0; i < num_requests; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    load_config();

    size_t payload_sizes[] = {512, 2048, 1024, 4096}; // Example payloads
    int num_requests = sizeof(payload_sizes) / sizeof(payload_sizes[0]);

    process_requests(payload_sizes, num_requests);

    return 0;
}
```

### Key Components:

- **RequestWindow**: Manages a sliding window of the last 100 requests.
- **Metrics**: Stores calculated metrics for analysis.
- **Thresholds**: Holds configurable thresholds for payload size and latency.
- **Concurrency**: Uses pthreads for concurrent request handling and mutexes to ensure thread safety.

### Explanation:

1. **Configuration**: Loads dynamic thresholds from environment variables.
2. **Request Handling**: Each request is processed in a separate thread, ensuring concurrency.
3. **Sliding Window**: Efficiently manages requests using an array with a mutex lock for synchronization.
4. **Metrics Calculation**: Computes average payload size, maximum latency, and frequency within the last 50 ms.
5. **Logging**: Logs to an external service if certain conditions are met.

This implementation is designed to be efficient, scalable, and maintainable.']

