typedef struct {
    int ip_version;
    char source_ip[16];
    char destination_ip[16];
    unsigned short port_number;
} UDP_PACKET_T;

// Mutex for thread safety during allocation and deallocation.
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

UDP_PACKET_T* allocate_udp_packets(int N, const char *log_file) {
    if (N <= 0) {
        log_operation(log_file, "Error: Invalid number of elements requested.");
        return NULL;
    }

    UDP_PACKET_T *packets = NULL;

    pthread_mutex_lock(&lock);

    // Dynamically allocate memory for the array
    packets = (UDP_PACKET_T *)malloc(N * sizeof(UDP_PACKET_T));
    if (!packets) {
        log_operation(log_file, "Error: Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Seed random number generator once per process/thread
    static int is_seeded = 0;
    if (!is_seeded) {
        srand((unsigned int)time(NULL));
        is_seeded = 1;
    }

    for (int i = 0; i < N; ++i) {
        // Initialize each structure
        packets[i].ip_version = IP_VERSION_4;

        snprintf(packets[i].source_ip, sizeof(packets[i].source_ip), "192.168.1.%d", rand() % 255);
        snprintf(packets[i].destination_ip, sizeof(packets[i].destination_ip), "10.0.0.%d", rand() % 255);

        packets[i].port_number = PORT_MIN + (rand() % (PORT_MAX - PORT_MIN + 1));
    }

    pthread_mutex_unlock(&lock);

    log_operation(log_file, "Success: Memory allocated and initialized.");
    return packets;
}

void free_udp_packets(UDP_PACKET_T *packets) {
    if (!packets) return;

    pthread_mutex_lock(&lock);

    // Free the dynamically allocated memory
    free(packets);

    pthread_mutex_unlock(&lock);

    log_operation("operation.log", "Memory deallocated.");
}

void log_operation(const char *log_file, const char *message) {
    FILE *file = fopen(log_file, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}
