#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_THREADS 10
#define MAX_REQUESTS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int *long_array;
    int *key_array;
    long size;
} RecordArray;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int current_requests = 0;

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest(EVP_sha256());
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_crc_indication_pdu(int n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pfds = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pfds) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        pfds[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pfds[i].RNTI = rand() % 10000;

        unsigned char crcflag[1];
        if (!RAND_bytes(crcflag, sizeof(crcflag))) {
            fprintf(stderr, "Random number generation failed\n");
            free(pfds);
            return NULL;
        }
        memcpy(pfds[i].CRC_INDICATION_REL8_TAG, "\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0A\x0B\x0C\x0D\x0E\xFF", 15);
        pfds[i].CRC_INDICATION_REL8_TAG[15] = crcflag[0];
    }

    return pfds;
}

RecordArray* initialize_record_array(int size, int key_range) {
    RecordArray *record_array = malloc(sizeof(RecordArray));
    if (!record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    record_array->long_array = malloc(size * sizeof(long));
    record_array->key_array = malloc(size * sizeof(int));
    record_array->size = size;

    if (!record_array->long_array || !record_array->key_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(record_array);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        record_array->long_array[i] = rand() % 1000000;
        record_array->key_array[i] = rand() % key_range;
    }

    return record_array;
}

void log_operation(const char *operation, int status, const char *params) {
    printf("Operation: %s, Status: %d, Params: %s\n", operation, status, params);
}

void* handle_request(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;

    // Simulate processing
    usleep(1000);  // Simulated delay

    log_operation("Process Request", 1, "Success");

    pthread_mutex_lock(&mutex);
    current_requests--;
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void process_requests_concurrently(NFAPI_CRC_INDICATION_PDU_T* pfds, int n) {
    pthread_t threads[MAX_REQUESTS];

    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);
        if (current_requests >= MAX_THREADS) {
            log_operation("Process Request", 0, "Too many requests");
            continue;
        }
        current_requests++;
        pthread_mutex_unlock(&mutex);

        int rc = pthread_create(&threads[i], NULL, handle_request, &pfds[i]);
        if (rc) {
            fprintf(stderr, "Error: Unable to create thread %d\n", i);
            continue;
        }
    }

    for (int i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    initialize_crypto();

    int num_pdu = 5;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = generate_nfaapi_crc_indication_pdu(num_pdu);
    if (pdu_list == NULL) return EXIT_FAILURE;

    process_requests_concurrently(pdu_list, num_pdu);

    free(pdu_list);

    RecordArray *record_array = initialize_record_array(10, 1000);
    if (!record_array) {
        fprintf(stderr, "Failed to initialize record array\n");
        return EXIT_FAILURE;
    }

    // Use the record_array for further processing

    free(record_array->long_array);
    free(record_array->key_array);
    free(record_array);

    return EXIT_SUCCESS;
}
