<?php

use GuzzleHttp\Client;
use Predis\Client as RedisClient;

class OAuth2Authenticator {
    private $client_id;
    private $client_secret;
    private $redirect_uri;
    private $token_url;
    private $user_info_url;
    private $redis;
    private $httpClient;

    public function __construct($clientId, $clientSecret, $redirectUri, $tokenUrl, $userInfoUrl) {
        $this->client_id = $clientId;
        $this->client_secret = $clientSecret;
        $this->redirect_uri = $redirectUri;
        $this->token_url = $tokenUrl;
        $this->user_info_url = $userInfoUrl;

        // Use Redis for distributed caching
        $this->redis = new RedisClient([
            'scheme' => 'tcp',
            'host'   => '127.0.0.1',
            'port'   => 6379,
        ]);

        // HTTP Client to handle API requests
        $this->httpClient = new Client();
    }

    public function authenticate($code) {
        try {
            $tokenResponse = $this->exchangeCodeForToken($code);
            if (!$tokenResponse) {
                throw new Exception('Failed to obtain token');
            }

            // Store access and refresh tokens in Redis with atomic operations
            $userId = $this->getUserIdFromToken($tokenResponse['access_token']);
            $this->redis->multi();
            $this->redis->set("auth:{$userId}:access_token", json_encode($tokenResponse), 'EX', 3600); // 1 hour TTL
            if (isset($tokenResponse['refresh_token'])) {
                $this->redis->set("auth:{$userId}:refresh_token", $tokenResponse['refresh_token'], 'EX', 7200); // 2 hours TTL
            }
            $this->redis->exec();

            return $this->getUserInfo($userId);
        } catch (Exception $e) {
            error_log('Authentication Error: ' . $e->getMessage());
            return null;
        }
    }

    private function exchangeCodeForToken($code) {
        try {
            $response = $this->httpClient->post($this->token_url, [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'code' => $code,
                    'redirect_uri' => $this->redirect_uri,
                    'client_id' => $this->client_id,
                    'client_secret' => $this->client_secret
                ]
            ]);

            return json_decode($response->getBody(), true);
        } catch (Exception $e) {
            error_log('Error exchanging code for token: ' . $e->getMessage());
            return null;
        }
    }

    private function getUserIdFromToken($accessToken) {
        try {
            $tokenInfo = $this->redis->get("auth:{$accessToken}:user_id");
            if (!$tokenInfo) {
                // Retrieve user info from external API to get a unique identifier
                $response = $this->httpClient->get($this->user_info_url, [
                    'headers' => ['Authorization' => "Bearer {$accessToken}"]
                ]);

                $userInfo = json_decode($response->getBody(), true);
                $userId = $userInfo['id']; // Assume the external API returns a user ID

                // Store this mapping in Redis for future requests
                $this->redis->set("auth:{$accessToken}:user_id", $userId, 'EX', 3600); // TTL matches access token

                return $userId;
            }

            return json_decode($tokenInfo, true);
        } catch (Exception $e) {
            error_log('Error retrieving user ID from token: ' . $e->getMessage());
            return null;
        }
    }

    private function getUserInfo($userId) {
        try {
            $accessToken = $this->redis->get("auth:{$userId}:access_token");
            if (!$accessToken || !$this->isTokenValid(json_decode($accessToken, true))) {
                // Refresh token if necessary
                $refreshToken = $this->redis->get("auth:{$userId}:refresh_token");
                if ($refreshToken) {
                    return $this->refreshAccessToken($userId, $refreshToken);
                }
                return null;
            }

            // Retrieve user info from external API using valid access token
            $response = $this->httpClient->get($this->user_info_url, [
                'headers' => ['Authorization' => "Bearer " . json_decode($accessToken, true)['access_token']]
            ]);

            return json_decode($response->getBody(), true);
        } catch (Exception $e) {
            error_log('Error retrieving user info: ' . $e->getMessage());
            return null;
        }
    }

    private function isTokenValid($tokenData) {
        if (!isset($tokenData['expires_in'])) return false;
        // Check current time against expiration time
        return ($tokenData['created_at'] + $tokenData['expires_in']) > time();
    }

    private function refreshAccessToken($userId, $refreshToken) {
        try {
            $response = $this->httpClient->post($this->token_url, [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    'refresh_token' => $refreshToken,
                    'client_id' => $this->client_id,
                    'client_secret' => $this->client_secret
                ]
            ]);

            $newTokenData = json_decode($response->getBody(), true);
            if (!$newTokenData) {
                throw new Exception('Failed to refresh token');
            }

            // Update tokens in Redis with atomic operations
            $this->redis->multi();
            $this->redis->set("auth:{$userId}:access_token", json_encode($newTokenData), 'EX', 3600);
            if (isset($newTokenData['refresh_token'])) {
                $this->redis->set("auth:{$userId}:refresh_token", $newTokenData['refresh_token'], 'EX', 7200);
            }
            $this->redis->exec();

            return $this->getUserInfo($userId);
        } catch (Exception $e) {
            error_log('Error refreshing access token: ' . $e->getMessage());
            return null;
        }
    }
}
