// Assuming these are defined somewhere in your codebase:
#define RX_UE_INFORMATION_TAG_VALID 0x01 // example valid tag value
#define RNTI_MIN 0
#define RNTI_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Predefined limit for maximum memory usage (example: max 1MB)
#define MAX_MEMORY_LIMIT (1024 * 1024)

pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_array(size_t N) {
    if (N == 0) return NULL;

    // Calculate memory size and check against limit
    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > MAX_MEMORY_LIMIT) {
        printf("Warning: Allocated memory exceeds the predefined limit.\n");
        N = MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T); // Adjust N
        total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_lock(&allocation_mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(total_size);

    if (!array) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_VALID;

        // Generate random RNTI within valid range
        unsigned short rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        if (rnti < RNTI_MIN || rnti > RNTI_MAX) {
            printf("Error: Generated invalid RNTI value. Using default.\n");
            array[i].RNTI = 0; // Fallback to a safe default
        } else {
            array[i].RNTI = rnti;
        }

        array[i].CRC_INDICATION_REL8_TAG = (unsigned char)(rand() % 256);
        array[i].CRCFLAG = rand();
    }

    pthread_mutex_unlock(&allocation_mutex);

    return array;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t N = 1000; // Example usage
    NFAPI_CRC_INDICATION_PDU_T* crc_array = allocate_nfa_crc_array(N);

    if (crc_array) {
        printf("Array allocated successfully with %zu elements.\n", N);

        // Free the allocated memory when done
        free(crc_array);
    }

    return 0;
}
