// Define TrafficFlowStats structure
typedef struct {
    int flow_id;
    unsigned long packet_count;
    unsigned long byte_count;
    time_t timestamp;
    double avg_packet_size;  // Additional field for average packet size
} TrafficFlowStats;

// Function to initialize the array with random values and calculate averages
void manage_traffic_flow(TrafficFlowStats **traffic_flows, int num_flows) {
    *traffic_flows = (TrafficFlowStats *)malloc(num_flows * sizeof(TrafficFlowStats));

    if (*traffic_flows == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_flows; ++i) {
        TrafficFlowStats *flow = &((*traffic_flows)[i]);

        // Assign unique flow ID and random values for packet count and byte count
        flow->flow_id = i;
        flow->packet_count = rand() % 1001 + 1;  // Random value between 1 and 1000
        flow->byte_count = (rand() % 100001) * (flow->packet_count);  // Bytes in range of packet count
        flow->timestamp = time(NULL);

        // Calculate average packet size, handling potential data loss
        if (flow->packet_count > 0) {
            flow->avg_packet_size = (double)flow->byte_count / flow->packet_count;
        } else {
            flow->avg_packet_size = 0.0;  // Handle case with zero packets gracefully
        }
    }
}

// Function to simulate receiving updates from an external data source
void update_traffic_flow(TrafficFlowStats *traffic_flows, int num_flows) {
    for (int i = 0; i < num_flows; ++i) {
        TrafficFlowStats *flow = &traffic_flows[i];

        // Simulating a real-time packet and byte count increase
        flow->packet_count += rand() % 101;  // Randomly increment packets between 0 to 100
        flow->byte_count += (rand() % 10001) * (flow->packet_count);  // Increase bytes

        // Update timestamp with current time
        flow->timestamp = time(NULL);

        // Recalculate the average packet size considering new values
        if (flow->packet_count > 0) {
            flow->avg_packet_size = (double)flow->byte_count / flow->packet_count;
        } else {
            flow->avg_packet_size = 0.0;  // Maintain accuracy with no packets
        }
    }
}

// Function to free allocated memory
void free_traffic_flow(TrafficFlowStats **traffic_flows) {
    if (traffic_flows != NULL && *traffic_flows != NULL) {
        free(*traffic_flows);
        *traffic_flows = NULL;
    }
}

int main() {
    int num_flows = 10;  // Example number of flows
    TrafficFlowStats *traffic_flows = NULL;

    manage_traffic_flow(&traffic_flows, num_flows);

    // Simulate updates from an external data source periodically
