        update_traffic_flow(traffic_flows, num_flows);
        // Simulate delay to represent real-time updates
        time_t start = time(NULL);
        while ((time(NULL) - start) < 1);  // Wait for 1 second before next update
    }

    free_traffic_flow(&traffic_flows);

    return 0;
}
