    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for concurrency control
pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
} DynamicArray;

void initDynamicArray(DynamicArray *da) {
    da->array = NULL;
    da->size = 0;
}

int insertElement(DynamicArray *da, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&arrayMutex);

    if (da->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&arrayMutex);
        return -1; // Array is full
    }

    da->array = realloc(da->array, (da->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        pthread_mutex_unlock(&arrayMutex);
        return -2; // Memory allocation failed
    }

    memcpy(&da->array[da->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size++;

    pthread_mutex_unlock(&arrayMutex);
    return 0;
}

int deleteElement(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        return -1; // Invalid index
    }

    pthread_mutex_lock(&arrayMutex);

    memmove(&da->array[index], &da->array[index + 1],
            (da->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    da->array = realloc(da->array, (da->size--) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&arrayMutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getElement(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        return NULL; // Invalid index
    }

    pthread_mutex_lock(&arrayMutex);

    NFAPI_CRC_INDICATION_PDU_T *element = &da->array[index];

    pthread_mutex_unlock(&arrayMutex);
    return element;
}

void verifyCRCFlags(DynamicArray *da) {
    pthread_mutex_lock(&arrayMutex);

    for (size_t i = 0; i < da->size; ++i) {
        // Placeholder for CRC flag verification logic
        if (rand() % 10 == 0) { // Simulate occasional invalid flag
            printf("CRC flag verification failed at index %zu\n", i);
            da->array[i].CRCFLAG = rand() & 1; // Reset the CRC flag randomly
        }
    }

    pthread_mutex_unlock(&arrayMutex);
}

int loadAndCreateNfarb(const char *filePath, int N, long performanceBudget) {
    time_t start_time = time(NULL);

    FILE *file = fopen(filePath, "r");
    if (!file) return -1; // File open error

    DynamicArray da;
    initDynamicArray(&da);

    for (int i = 0; i < N && difftime(time(NULL), start_time) * 1000 < performanceBudget; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Simulate reading from file or external data source
        if (fscanf(file, "%d %d %hhu", &pdu.RX_UE_INFORMATION_TAG, &pdu.RNTI, &pdu.CRC_INDICATION_REL8_TAG) != 3)
            break; // End of file or read error

        pdu.CRCFLAG = rand() & 1; // Randomly set CRC flag

        if (insertElement(&da, &pdu) != 0) {
            free(da.array);
            fclose(file);
            return -2; // Insertion failed
        }
    }

    fclose(file);

    verifyCRCFlags(&da);

    printf("Loaded %zu items\n", da.size);

    // Cleanup and return the size of loaded data
    free(da.array);
    return (int) da.size;
}

// Example main function for testing purposes
int main() {
