#include <string.h>

#define MAX_TASKS 10
#define LOG_FILE "task_log.txt"
#define MAX_LOG_SIZE (1024 * 1024) // 1MB

typedef struct {
    char task_string[256];
} Task;

typedef struct TaskNode {
    Task task;
    struct TaskNode* next;
} TaskNode;

pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
TaskNode* head = NULL;
int active_tasks = 0;
int max_concurrent_tasks = MAX_TASKS;
FILE* log_file = NULL;

void log_message(const char* message) {
    pthread_mutex_lock(&queue_lock);
    if (log_file == NULL || ftell(log_file) >= MAX_LOG_SIZE) {
        fclose(log_file);
        log_file = fopen(LOG_FILE, "a");
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&queue_lock);
}

void rotate_logs() {
    char new_log_file[256];
    snprintf(new_log_file, sizeof(new_log_file), "%s.%ld", LOG_FILE, time(NULL));
    rename(LOG_FILE, new_log_file);
    log_file = fopen(LOG_FILE, "w");
}

void enqueue_task(Task task) {
    TaskNode* node = (TaskNode*)malloc(sizeof(TaskNode));
    if (!node) return;

    strcpy(node->task.task_string, task.task_string);
    node->next = NULL;

    pthread_mutex_lock(&queue_lock);

    if (head == NULL) {
        head = node;
    } else {
        TaskNode* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    pthread_cond_signal(&queue_cond);
    pthread_mutex_unlock(&queue_lock);
}

int validate_task(Task task) {
    // Add validation logic here
    return 1; // Assume valid for demonstration purposes
}

void* execute_tasks(void* arg) {
    while (1) {
        TaskNode* node = NULL;

        pthread_mutex_lock(&queue_lock);

        while (head == NULL && active_tasks < max_concurrent_tasks) {
            pthread_cond_wait(&queue_cond, &queue_lock);
        }

        if (active_tasks >= max_concurrent_tasks) {
            pthread_mutex_unlock(&queue_lock);
            continue;
        }

        node = head;
        if (node != NULL) {
            head = node->next;
        }
        active_tasks++;
        pthread_mutex_unlock(&queue_lock);

        if (node && validate_task(node->task)) {
            log_message("Executing task");
            // Execute the task
            sleep(1); // Simulate work
            free(node);
            active_tasks--;
        } else {
            log_message("Task validation failed or execution error");
        }
    }

    return NULL;
}

void adjust_max_concurrent_tasks() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    if (usage.ru_utime.tv_sec > 10) { // Example condition
        max_concurrent_tasks = MAX_TASKS / 2;
    } else {
        max_concurrent_tasks = MAX_TASKS;
    }
}

int enqueue_task_for_execution(Task task) {
    if (!validate_task(task)) {
        return 0;
    }

    pthread_mutex_lock(&queue_lock);
    enqueue_task(task);
    pthread_mutex_unlock(&queue_lock);

    adjust_max_concurrent_tasks();

    return 1;
}

void cleanup() {
    pthread_mutex_lock(&queue_lock);
    TaskNode* current = head;
    while (current != NULL) {
        TaskNode* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    active_tasks = 0;
    pthread_mutex_unlock(&queue_lock);

    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    pthread_t worker_thread;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (pthread_create(&worker_thread, NULL, execute_tasks, NULL) != 0) {
        perror("Failed to create thread");
        cleanup();
        return 1;
    }

    Task task = {.task_string = "Sample task"};
    enqueue_task_for_execution(task);

    pthread_join(worker_thread, NULL);
    cleanup();

    return 0;
}
```

