    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes
