NFAPI_CRC_INDICATION_PDU_T* get_pdu(DynamicArray* da, size_t index);
void update_all_crc_flags(DynamicArray* da);

// Random CRC flag generator
unsigned char generate_random_crc_flag() {
    return rand() % 2;
}

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    pthread_mutex_init(&da->lock, NULL);
    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

int resize_if_needed(DynamicArray* da) {
    if (da->size < da->capacity) return 0;

    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_or_update_pdu(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].ue_info.RX_UE_INFORMATION_TAG == pdu.ue_info.RX_UE_INFORMATION_TAG &&
            da->array[i].rnti == pdu.rnti) {
            da->array[i] = pdu;
            pthread_mutex_unlock(&da->lock);
            return 0; // Updated
        }
    }

    if (resize_if_needed(da)) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Memory allocation failed
    }

    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);
    return 1; // Added
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(DynamicArray* da, size_t index) {
    if (index >= da->size) return NULL;

    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &da->array[index];
    pthread_mutex_unlock(&da->lock);

    return pdu;
}

void update_all_crc_flags(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        da->array[i].crc_tag.CRC_flag = generate_random_crc_flag();
    }

    pthread_mutex_unlock(&da->lock);
}

void iterate_and_process(DynamicArray* da, void (*process)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        process(&da->array[i]);
    }

    pthread_mutex_unlock(&da->lock);
}

// Example processing function
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("UE Info: %u, RNTI: %u, CRC Flag: %d\n", 
           pdu->ue_info.RX_UE_INFORMATION_TAG, pdu->rnti, pdu->crc_tag.CRC_flag);
}

int main() {
    srand(time(NULL));

    DynamicArray* da = create_dynamic_array();
    if (!da) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.ue_info.RX_UE_INFORMATION_TAG = 1234;
    pdu.rnti = 5678;
    pdu.crc_tag.CRC_flag = generate_random_crc_flag();

    add_or_update_pdu(da, pdu);

    iterate_and_process(da, print_pdu);

    update_all_crc_flags(da);
    iterate_and_process(da, print_pdu);

    destroy_dynamic_array(da);

    return 0;
}
```

### Key Components:
- **DynamicArray**: Manages dynamic memory allocation and resizing for an array of `NFAPI_CRC_INDICATION_PDU_T` structures.
- **Thread Safety**: Uses a mutex to ensure thread-safe operations on the array.
- **Resizing Strategy**: Doubles capacity when needed, ensuring efficient reallocation.
- **Error Handling**: Checks for failed allocations and returns appropriate error codes.
- **Batch Processing Support**: Iterates over elements with minimal overhead using `iterate_and_process`.']

