        }
    }

    buffer_count = N;
    log_message("Buffers initialized successfully");
    return 0;
}

// Function to Resize Buffers
int resize_buffers(size_t new_size) {
    pthread_mutex_lock(&buffer_lock);

    if (new_size == buffer_count) {
        pthread_mutex_unlock(&buffer_lock);
        return 0; // No resizing needed
    }

    LTE_PHY_RX_BUFFER **new_buffers = realloc(buffers, new_size * sizeof(LTE_PHY_RX_BUFFER *));
    if (!new_buffers) {
        log_message("Reallocation failed during resize");
        pthread_mutex_unlock(&buffer_lock);
        return -1;
    }

    for (size_t i = buffer_count; i < new_size; ++i) {
        LTE_PHY_RX_BUFFER *buf = malloc(sizeof(LTE_PHY_RX_BUFFER));
        if (!buf) {
            log_message("Memory allocation failed during resize");
            for (size_t j = 0; j < i; ++j) free(new_buffers[j]);
            free(new_buffers);
            buffers = NULL;
            pthread_mutex_unlock(&buffer_lock);
            return -1;
        }
        new_buffers[i] = buf;

        RX_FRAME_INFO *info = &new_buffers[i]->frame_info;
        info->timestamp = time(NULL);
        info->RF_FRAME_ID = rand();
        info->PHY_FRAME_TYPE = 'T';
    }

    buffers = new_buffers;
    buffer_count = new_size;
    log_message("Buffers resized successfully");

    pthread_mutex_unlock(&buffer_lock);
    return 0;
}

// Function to Free Buffers
void free_buffers() {
    pthread_mutex_lock(&buffer_lock);

    for (size_t i = 0; i < buffer_count; ++i) {
        free(buffers[i]);
    }
    free(buffers);
    buffers = NULL;

    pthread_mutex_unlock(&buffer_lock);
    pthread_mutex_destroy(&buffer_lock);
    log_message("Buffers freed successfully");
}

// Main Function
int main() {
