    pdu->RX_UE_INFORMATION_TAG = fetch_RX_UE_INFORMATION_TAG();
    pdu->RNTI = fetch_RNTI();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Example value
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void manage_nfa_list(size_t new_elements) {
    pthread_mutex_lock(&list_mutex);

    if (current_size < MAX_ELEMENTS && current_size + new_elements <= MAX_ELEMENTS) {
        for (size_t i = current_size; i < current_size + new_elements; ++i) {
            populate_structure(&nfa_list[i]);
        }
        current_size += new_elements;
    } else {
        fprintf(stderr, "Cannot add more elements, maximum capacity reached.\n");
    }

    pthread_mutex_unlock(&list_mutex);
}

void cleanup() {
    pthread_mutex_destroy(&list_mutex);
    free(nfa_list);
}

int main() {
    srand(time(NULL));
    initialize_list(MAX_ELEMENTS);

    // Simulate concurrent modifications
    const size_t num_threads = 10;
    const size_t elements_per_thread = MAX_ELEMENTS / num_threads;

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, (void*)manage_nfa_list, (void*)(elements_per_thread));
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup();
    return 0;
}
