<?php

class ClinicStatusUpdater {

    private $db;
    private $apiEndpoint;

    public function __construct($config) {
        $this->connectDatabase($config['database']);
        $this->apiEndpoint = getenv('API_ENDPOINT');
    }

    private function connectDatabase($dbConfig) {
        try {
            if ($dbConfig['type'] === 'mysql') {
                $dsn = "mysql:host={$dbConfig['host']};dbname={$dbConfig['name']}";
                $options = [
                    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                ];
                $this->db = new PDO($dsn, $dbConfig['user'], $dbConfig['password'], $options);
            } elseif ($dbConfig['type'] === 'pgsql') {
                $dsn = "pgsql:host={$dbConfig['host']};dbname={$dbConfig['name']}";
                $options = [
                    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                ];
                $this->db = new PDO($dsn, $dbConfig['user'], $dbConfig['password'], $options);
            } else {
                throw new Exception("Unsupported database type");
            }
        } catch (PDOException $e) {
            die('Database connection failed: ' . $e->getMessage());
        }
    }

    public function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
        if (!$this->validateInputs($clinicId, $newStatus, $lastModifiedIp)) {
            return false;
        }

        try {
            $this->db->beginTransaction();

            $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
            $stmt->execute([$newStatus, $lastModifiedIp, $clinicId]);

            if ($stmt->rowCount() === 0) {
                throw new Exception('No rows updated.');
            }

            $this->logUpdate($clinicId);

            $this->db->commit();

            $this->notifyStakeholders($clinicId);
            return "Success: Clinic status updated.";
        } catch (Exception $e) {
            $this->db->rollBack();
            if ($this->isTransientError($e)) {
                sleep(1); // Exponential backoff can be enhanced here
                return $this->updateClinicStatusWithRetry($clinicId, $newStatus, $lastModifiedIp);
            }
            error_log("Update failed: " . $e->getMessage());
            return false;
        }
    }

    private function validateInputs($clinicId, $newStatus, $lastModifiedIp) {
        if (!is_string($clinicId) || strlen($clinicId) !== 36) {
            return false;
        }
        if (filter_var($lastModifiedIp, FILTER_VALIDATE_IP) === false) {
            return false;
        }
        // Additional validation for newStatus can be added here
        return true;
    }

    private function logUpdate($clinicId) {
        try {
            $stmt = $this->db->prepare("INSERT INTO update_logs (clinic_id, update_time) VALUES (?, NOW())");
            $stmt->execute([$clinicId]);
        } catch (Exception $e) {
            file_put_contents('update_log.txt', "Failed to log: {$e->getMessage()}\n", FILE_APPEND);
        }
    }

    private function notifyStakeholders($clinicId) {
        if (!$this->apiEndpoint) return;

        try {
            $ch = curl_init($this->apiEndpoint);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(['clinic_id' => $clinicId]));
            curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);
            $response = curl_exec($ch);

            if (curl_errno($ch)) {
                throw new Exception('API request failed: ' . curl_error($ch));
            }

            $httpCode = curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            if ($httpCode !== 200) {
                throw new Exception("Unexpected API response code: $httpCode");
            }

            curl_close($ch);
        } catch (Exception $e) {
            error_log("Notification failed: " . $e->getMessage());
        }
    }

    private function isTransientError($exception) {
        // Simplified check, can be enhanced with specific SQLSTATE codes
        return strpos($exception->getMessage(), 'connection') !== false;
    }

    private function updateClinicStatusWithRetry($clinicId, $newStatus, $lastModifiedIp) {
        static $attempts = 0;

        if ($attempts >= 3) {
            return false;
        }

        $attempts++;
        sleep(pow(2, $attempts)); // Exponential backoff
        return $this->updateClinicStatus($clinicId, $newStatus, $lastModifiedIp);
    }
}

// Usage example:
$config = [
    'database' => [
        'type' => 'mysql',  // or 'pgsql'
        'host' => 'localhost',
        'name' => 'clinic_db',
        'user' => 'root',
        'password' => 'password123'
    ]
];

$updater = new ClinicStatusUpdater($config);
echo $updater->updateClinicStatus('unique-uuid-1234', 'active', '192.168.1.1');
```

**Explanation:**
- **Database Connection**: Supports both MySQL and PostgreSQL using PDO.
- **Input Validation**: Checks for valid `clinicId` format and IP address.
- **Concurrency Management**: Uses transactions to manage concurrent updates.
- **Error Handling and Retries**: Implements a retry mechanism with exponential backoff for transient errors.
- **Logging and Auditing**: Logs updates in a separate table, with fallback to file logging if the database is unreachable.
- **External Integration**: Notifies stakeholders via an external API using cURL, configurable through environment variables.
- **Scalability**: Designed as a stateless class suitable for microservices architecture.']

['```rust
use postgres::{Client, NoTls};
use reqwest::blocking::{Client as HttpClient, Response};
use serde::Deserialize;
use std::collections::HashMap;
use log::{error, info};

#[derive(Deserialize)]
struct EmployeeApiDetails {
    phone_number: String,
    department_name: String,
}

fn fetchEmployeeDetails(
    connection_string: &str,
    supervisor_id: i32,
    api_url: &str,
    verify_tls: bool,
) -> Result<Vec<(String, String, String, String, String)>, Box<dyn std::error::Error>> {
    // Connect to the PostgreSQL database
    let client = Client::connect(connection_string, NoTls)?;

    // Prepare a parameterized query to fetch employee details from the 'Employees' table
    let rows = client.query(
        "SELECT name, city, address FROM Employees WHERE supervisor_id = $1",
        &[&supervisor_id],
    )?;

    // Create a new HTTP client instance with optional TLS verification setting
    let http_client = HttpClient::new().danger_accept_invalid_certs(!verify_tls);

    let mut employee_details = Vec::with_capacity(rows.len());

    for row in rows {
        let name: String = row.get(0);
        let city: String = row.get(1);
        let address: String = row.get(2);

        // Construct the URL with supervisor_id to fetch additional details
        let url = format!("{}/employee/{}", api_url, supervisor_id);

        // Perform the HTTP request and handle potential network delays gracefully
        match http_client.get(&url).send() {
            Ok(response) => match response.json::<EmployeeApiDetails>() {
                Ok(api_details) => {
                    let phone_number = api_details.phone_number;
                    let department_name = api_details.department_name;

                    employee_details.push((name, city, address, phone_number, department_name));
                }
                Err(err) => error!("Failed to parse JSON response: {:?}", err),
            },
            Err(err) => error!("HTTP request failed: {:?}", err),
        }
    }

    info!("Successfully fetched employee details for supervisor ID {}", supervisor_id);

    Ok(employee_details)
}
```

This Rust function `fetchEmployeeDetails` connects to a PostgreSQL database using the provided connection string, and queries the 'Employees' table for specific employees based on their supervisor ID. It then makes an HTTP request to fetch additional details like phone number and department name from an external API, handling possible network delays gracefully.

The function optimizes resource usage by efficiently managing database connections and HTTP client instances. It minimizes memory consumption using vectors with pre-allocated capacity and handles errors without exposing sensitive information through logging mechanisms. The TLS verification can be toggled for testing purposes.']

