<?php

class UserDAO {
    private $db;
    private $tableName = 'users';

    public function __construct($db) {
        $this->db = $db;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->validatePasswordRules($newPassword)) {
            return ['success' => false, 'message' => 'Password does not meet the complexity requirements.'];
        }

        if ($this->isCommonPassword($newPassword)) {
            return ['success' => false, 'message' => 'Password is too common. Please choose a more unique password.'];
        }

        if (!$this->isUniquePassword($userId, $newPassword)) {
            return ['success' => false, 'message' => 'Password has been used previously. Please use a new one.'];
        }

        $rateLimitExceeded = $this->checkRateLimit($userId);
        if ($rateLimitExceeded) {
            return ['success' => false, 'message' => 'Too many attempts. Please try again later.'];
        }

        $this->logFailedAttemptIfNecessary();

        $newPasswordHash = password_hash($newPassword, PASSWORD_BCRYPT);

        $query = "UPDATE {$this->tableName} SET password = ? WHERE id = ?";
        $stmt = $this->db->prepare($query);

        if ($stmt === false) {
            return ['success' => false, 'message' => 'Database error. Please try again later.'];
        }

        $success = $stmt->execute([$newPasswordHash, $userId]);

        if (!$success) {
            return ['success' => false, 'message' => 'Failed to update password due to a technical issue.'];
        }

        $this->resetRateLimit($userId);
        return ['success' => true, 'message' => 'Password updated successfully.'];

    }

    private function validatePasswordRules($password) {
        // Example rules: 8-64 characters long, at least one uppercase, lowercase, digit, special character
        if (strlen($password) < 8 || strlen($password) > 64) return false;
        if (!preg_match('/[A-Z]/', $password)) return false;
        if (!preg_match('/[a-z]/', $password)) return false;
        if (!preg_match('/\d/', $password)) return false;
        if (!preg_match('/[\W_]/', $password)) return false;

        return true;
    }

    private function isCommonPassword($password) {
        // Load common passwords from a predefined list
        $commonPasswords = ['123456', 'password', '123456789'];
        return in_array($password, $commonPasswords);
    }

    private function isUniquePassword($userId, $newPassword) {
        $query = "SELECT COUNT(*) FROM password_history WHERE user_id = ? AND password = ?";
        $stmt = $this->db->prepare($query);

        if ($stmt === false) return false;

        $stmt->execute([$userId, password_hash($newPassword, PASSWORD_BCRYPT)]);
        return $stmt->fetchColumn() == 0;
    }

    private function checkRateLimit($userId) {
        // Implement a basic rate limiting mechanism
        $query = "SELECT attempt_count, last_attempt FROM rate_limit WHERE user_id = ?";
        $stmt = $this->db->prepare($query);

        if ($stmt === false) return true;

        $stmt->execute([$userId]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$result) {
            // No record, insert a new one
            $insertQuery = "INSERT INTO rate_limit (user_id, attempt_count, last_attempt) VALUES (?, 1, NOW())";
            $this->db->prepare($insertQuery)->execute([$userId]);
            return false;
        }

        if ($result['attempt_count'] >= 5 && strtotime('now') - strtotime($result['last_attempt']) < 60) {
            return true; // Too many attempts within the last minute
        }

        $updateQuery = "UPDATE rate_limit SET attempt_count = attempt_count + 1, last_attempt = NOW() WHERE user_id = ?";
        $this->db->prepare($updateQuery)->execute([$userId]);

        return false;
    }

    private function resetRateLimit($userId) {
        $resetQuery = "UPDATE rate_limit SET attempt_count = 0 WHERE user_id = ?";
        $this->db->prepare($resetQuery)->execute([$userId]);
    }

    private function logFailedAttemptIfNecessary() {
        // Log failed attempts for auditing
        $logData = [
            'timestamp' => date('Y-m-d H:i:s'),
            'details' => 'A password update attempt failed. Reason: validation or rate limit.'
        ];

        // Example logging mechanism, could be improved with a dedicated logger
        file_put_contents('/path/to/logfile.log', json_encode($logData) . PHP_EOL, FILE_APPEND);
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password'); // or use PDO for PostgreSQL
$userDAO = new UserDAO($db);

$result = $userDAO->updatePassword(1, 'NewSecureP@ssw0rd!');
echo json_encode($result);
```

This implementation includes:

- Password validation against complexity rules and uniqueness.
- Checks for common passwords using a predefined list.
- Rate limiting to prevent abuse.
- Use of prepared statements to avoid SQL injection vulnerabilities.
- Logging mechanism for failed attempts.
- Efficient database operations with support for future extension to additional backends.']

