#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RETRIES 5
#define INITIAL_BACKOFF_MS 100

// Function prototypes
int asyncReduceArray(NFAPI_CRC_INDICATION_PDU_T **array, size_t n, int initialValue, 
                     int (*callback)(int acc, NFAPI_CRC_INDICATION_PDU_T *item));
static void *reduceWorker(void *arg);
static int fillAndValidateData(NFAPI_CRC_INDICATION_PDU_T **array, size_t n);

// Error codes
#define SUCCESS 0
#define MEMORY_ERROR -1
#define VALIDATION_ERROR -2

int asyncReduceArray(NFAPI_CRC_INDICATION_PDU_T **array, size_t n, int initialValue,
                     int (*callback)(int acc, NFAPI_CRC_INDICATION_PDU_T *item)) {
    if (!array || !callback) return MEMORY_ERROR;

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) return MEMORY_ERROR;

    // Fill and validate data with retries
    int status = fillAndValidateData(array, n);
    if (status != SUCCESS) {
        free(*array);
        return status;
    }

    atomic_int acc = initialValue;
    pthread_t threads[4]; // Example: using 4 threads for concurrency

    for (size_t i = 0; i < 4 && i * (n / 4) < n; ++i) {
        int thread_id = i;
        pthread_create(&threads[thread_id], NULL, reduceWorker, (void *)(intptr_t)((uintptr_t)array + i * (n / 4)));
    }

    for (size_t i = 0; i < 4 && i * (n / 4) < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(*array);
    return SUCCESS;
}

static void *reduceWorker(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *start = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    atomic_int local_acc = 0;

    for (size_t i = 0; start + i < &(*array)[n]; ++i) {
        int acc = atomic_load(&local_acc);
        NFAPI_CRC_INDICATION_PDU_T *item = start + i;
        int result = callback(acc, item);

        if (__atomic_compare_exchange_n(&local_acc, &acc, result, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {
            // Successfully updated local accumulator
        }
    }

    return NULL;
}

static int fillAndValidateData(NFAPI_CRC_INDICATION_PDU_T **array, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*array)[i].RNTI = rand() % 100;
        (*array)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Validation logic
        if ((*array)[i].RX_UE_INFORMATION_TAG < 0 || (*array)[i].RNTI < 0) {
            free(*array);
            return VALIDATION_ERROR;
        }
    }

    return SUCCESS;
}

int sampleCallback(int acc, NFAPI_CRC_INDICATION_PDU_T *item) {
    return acc + item->RX_UE_INFORMATION_TAG + item->RNTI + (item->CRC_INDICATION_REL8_TAG.CRCFLAG ? 10 : -10);
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int result = asyncReduceArray(&array, 1000, 0, sampleCallback);

    if (result == SUCCESS) {
        printf("Reduction successful.\n");
    } else {
        printf("Error in reduction: %d\n", result);
    }

    return 0;
}
