    while (1) {
        rnti = rand() % (MAX_RNTI + 1);
        if (!used_rntis[rnti]) {
            used_rntis[rnti] = 1;
            pthread_mutex_unlock(&rnti_pool_lock);
            return rnti;
        }
    }
}

void reset_rnti(unsigned int rnti) {
    pthread_mutex_lock(&rnti_pool_lock);
    used_rntis[rnti] = 0;
    pthread_mutex_unlock(&rnti_pool_lock);
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_crc_pdu_list(size_t num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) return NULL;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_pdus; ++i) {
        pdu_list[i].RNTI = generate_unique_rnti();
        // Initialize RX_UE_INFORMATION_TAG with some values
        for (int j = 0; j < 16; ++j) {
            pdu_list[i].RX_UE_INFORMATION_TAG[j] = rand() % 256;
        }
        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    }

    return pdu_list;
}

void free_nfa_pi_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t num_pdus) {
    if (pdu_list) {
        for (size_t i = 0; i < num_pdus; ++i) {
            reset_rnti(pdu_list[i].RNTI);
        }
        free(pdu_list);
    }
}
```

### Key Points:
- **Thread Safety**: Uses a mutex to protect access to the RNTI pool, ensuring unique assignment even in concurrent environments.
- **Randomness**: Utilizes `rand()` seeded with `time(NULL)` for generating random values. For better randomness in multi-threaded applications, consider using more robust libraries like `<random>` in C++ or thread-local storage of seeds.
- **Memory Management**: Allocates memory dynamically and ensures it is freed correctly to prevent leaks.
- **Graceful Handling**: Implements a retry mechanism for RNTI generation until a unique one is found.
- **Performance Considerations**: Balances between mutex lock usage and performance by minimizing the locked section to only necessary operations.']

