    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} NICArray;

// Utility functions
void generate_random_mac(char *mac) {
    const char *hex_digits = "0123456789ABCDEF";
    for (int i = 0; i < 17; i++) {
        if (i == 2 || i == 5 || i == 8 || i == 11) mac[i] = ':';
        else {
            mac[i] = hex_digits[rand() % 16];
        }
    }
    mac[17] = '\0';
}

void generate_random_ip(char *ip) {
    for (int i = 0; i < 15; i++) {
        if (i == 3 || i == 7 || i == 11) ip[i] = '.';
        else {
            ip[i] = '0' + rand() % 10;
        }
    }
    ip[15] = '\0';
}

void generate_random_port_statistics(PortStatistics *port_stats, size_t num_ports) {
    for (size_t i = 0; i < num_ports; i++) {
        port_stats[i].received_bytes = rand() % 10000;
        port_stats[i].transmitted_bytes = rand() % 10000;
        port_stats[i].packet_count = rand() % 1000;
        port_stats[i].error_rate = (float)rand() / RAND_MAX * 10.0;
    }
}

int validate_port_statistics(PortStatistics *port_stats, size_t num_ports) {
    for (size_t i = 0; i < num_ports; i++) {
        if ((port_stats[i].received_bytes + port_stats[i].transmitted_bytes) != port_stats[i].packet_count) {
            return 0;
        }
    }
    return 1;
}

NICStatistics *create_nic_statistics(size_t port_count) {
    NICStatistics *nic = malloc(sizeof(NICStatistics));
    if (!nic) return NULL;

    nic->ports = calloc(port_count, sizeof(PortStatistics));
    if (!nic->ports) {
        free(nic);
        return NULL;
    }

    generate_random_mac(nic->mac_address);
    generate_random_ip(nic->ip_address);

    generate_random_port_statistics(nic->ports, port_count);
    nic->port_count = port_count;

    return nic;
}

void resize_nic_array(NICArray *nic_array) {
    size_t new_capacity = nic_array->capacity * GROWTH_FACTOR;
    NICStatistics **new_array = realloc(nic_array->array, new_capacity * sizeof(NICStatistics *));
    if (!new_array) return;

    memset(new_array + nic_array->capacity, 0, (new_capacity - nic_array->capacity) * sizeof(NICStatistics *));
    nic_array->array = new_array;
    nic_array->capacity = new_capacity;
}

void init_nic_array(NICArray *nic_array, size_t initial_capacity) {
    pthread_mutex_init(&nic_array->lock, NULL);
    nic_array->array = calloc(initial_capacity, sizeof(NICStatistics *));
    if (!nic_array->array) exit(EXIT_FAILURE);
    nic_array->capacity = initial_capacity;
    nic_array->count = 0;
}

void add_nic_statistics(NICArray *nic_array, NICStatistics *nic_stats) {
    pthread_mutex_lock(&nic_array->lock);

    if (nic_array->count == nic_array->capacity) {
        resize_nic_array(nic_array);
    }

    nic_array->array[nic_array->count++] = nic_stats;

    pthread_mutex_unlock(&nic_array->lock);
}

void free_nic_statistics(NICStatistics *nic_stats) {
    free(nic_stats->ports);
    free(nic_stats);
}

void cleanup_nic_array(NICArray *nic_array) {
    for (size_t i = 0; i < nic_array->count; i++) {
        free_nic_statistics(nic_array->array[i]);
    }
    free(nic_array->array);
    pthread_mutex_destroy(&nic_array->lock);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Example function to simulate synchronization with an external system
int synchronize_with_external_system(NICStatistics *nic_stats) {
    // Simulate network issues and return 0 on failure
    if (rand() % 10 == 0) {
        log_error("Failed to synchronize with the external system.");
        return 0;
    }
    return 1;
}

void periodic_synchronization(NICArray *nic_array) {
    while (1) {
        pthread_mutex_lock(&nic_array->lock);

        for (size_t i = 0; i < nic_array->count; i++) {
            if (!synchronize_with_external_system(nic_array->array[i])) {
                log_error("Synchronization error detected.");
            }
        }

        pthread_mutex_unlock(&nic_array->lock);
        sleep(10); // Simulate periodic synchronization
    }
}

int main() {
    srand(time(NULL));

    NICArray nic_array;
    init_nic_array(&nic_array, INITIAL_CAPACITY);

    for (size_t i = 0; i < 20; i++) {
        size_t port_count = rand() % 5 + 1;
        NICStatistics *nic_stats = create_nic_statistics(port_count);
        if (!nic_stats) continue;

        add_nic_statistics(&nic_array, nic_stats);
    }

    pthread_t sync_thread;
    pthread_create(&sync_thread, NULL, (void *(*)(void *))periodic_synchronization, &nic_array);

    // Simulate other operations...

    pthread_cancel(sync_thread);
    pthread_join(sync_thread, NULL);

    cleanup_nic_array(&nic_array);

    return 0;
}
