['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NICS 10000
#define MAX_PORTS_PER_NIC 10

typedef struct {
    unsigned int received_bytes;
    unsigned int transmitted_bytes;
    unsigned int packet_count;
    float error_rate;
} PortStatistics;

typedef struct {
    char mac_address[18];
    char ip_address[16];
    PortStatistics ports[MAX_PORTS_PER_NIC];
    int port_count;
} NICStats;

typedef struct {
    NICStats nics[MAX_NICS];
    int nic_count;
    pthread_mutex_t lock;
} NICMonitor;

void initialize_nic_monitor(NICMonitor *monitor) {
    monitor->nic_count = 0;
    pthread_mutex_init(&monitor->lock, NULL);
}

int add_nic_statistics(NICMonitor *monitor, const char *mac, const char *ip) {
    pthread_mutex_lock(&monitor->lock);

    if (monitor->nic_count >= MAX_NICS) {
        pthread_mutex_unlock(&monitor->lock);
        return -1; // NIC limit reached
    }

    strncpy(monitor->nics[monitor->nic_count].mac_address, mac, sizeof(monitor->nics[0].mac_address));
    strncpy(monitor->nics[monitor->nic_count].ip_address, ip, sizeof(monitor->nics[0].ip_address));
    monitor->nics[monitor->nic_count].port_count = 0;

    pthread_mutex_unlock(&monitor->lock);
    return 0;
}

void update_port_statistics(NICMonitor *monitor, int nic_index, int port_index,
                            unsigned int recv_bytes, unsigned int trans_bytes,
                            unsigned int packets, float error_rate) {
    if (nic_index < 0 || nic_index >= monitor->nic_count ||
        port_index < 0 || port_index >= MAX_PORTS_PER_NIC) {
        return;
    }

    pthread_mutex_lock(&monitor->lock);

    PortStatistics *port_stats = &monitor->nics[nic_index].ports[port_index];

    port_stats->received_bytes += recv_bytes;
    port_stats->transmitted_bytes += trans_bytes;
    port_stats->packet_count += packets;
    port_stats->error_rate = error_rate;

    // Validate packet count
    if (recv_bytes + trans_bytes != packets) {
        printf("Packet mismatch detected on NIC %d, Port %d\n", nic_index, port_index);
    }

    pthread_mutex_unlock(&monitor->lock);
}

void update_nic_address(NICMonitor *monitor, int nic_index, const char *new_mac, const char *new_ip) {
    if (nic_index < 0 || nic_index >= monitor->nic_count) {
        return;
    }

    pthread_mutex_lock(&monitor->lock);

    strncpy(monitor->nics[nic_index].mac_address, new_mac, sizeof(monitor->nics[0].mac_address));
    strncpy(monitor->nics[nic_index].ip_address, new_ip, sizeof(monitor->nics[0].ip_address));

    pthread_mutex_unlock(&monitor->lock);
}

void handle_network_anomalies(NICMonitor *monitor) {
    for (int i = 0; i < monitor->nic_count; ++i) {
        for (int j = 0; j < MAX_PORTS_PER_NIC && monitor->nics[i].port_count > j; ++j) {
            PortStatistics *ps = &monitor->nics[i].ports[j];

            if (ps->error_rate > 0.1) { // Example threshold
                printf("High error rate detected on NIC %d, Port %d\n", i, j);
                // Trigger alert/logging here
            }
        }
    }
}

void monitor_performance(NICMonitor *monitor) {
    pthread_mutex_lock(&monitor->lock);

    for (int i = 0; i < monitor->nic_count; ++i) {
        printf("NIC %d: MAC: %s, IP: %s\n", i, monitor->nics[i].mac_address, monitor->nics[i].ip_address);
        for (int j = 0; j < MAX_PORTS_PER_NIC && monitor->nics[i].port_count > j; ++j) {
            PortStatistics *ps = &monitor->nics[i].ports[j];
            printf("Port %d: RX Bytes: %u, TX Bytes: %u, Packets: %u, Error Rate: %.2f\n",
                   j, ps->received_bytes, ps->transmitted_bytes, ps->packet_count, ps->error_rate);
        }
    }

    pthread_mutex_unlock(&monitor->lock);
}

void cleanup_nic_monitor(NICMonitor *monitor) {
    pthread_mutex_destroy(&monitor->lock);
}

int main() {
    NICMonitor monitor;
    initialize_nic_monitor(&monitor);

    add_nic_statistics(&monitor, "00:11:22:33:44:55", "192.168.0.1");
    update_port_statistics(&monitor, 0, 0, 1000, 2000, 3000, 0.05);

    handle_network_anomalies(&monitor);
    monitor_performance(&monitor);

    cleanup_nic_monitor(&monitor);
    return 0;
}
```

