    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and configure the list of frames
void init_frame_list(FrameList *frame_list) {
    pthread_mutex_init(&frame_list->mutex, NULL);
    frame_list->frame_count = 0;

    for (size_t i = 0; i < FRAME_COUNT; ++i) {
        NFAPI_RX_FRAME_PDU_PDU_T *frame = &frame_list->frames[i];

        // Initialize with valid tags and random CRCFLAG
        frame->RX_FRAME_PDU_TAG = rand() % 1000;
        frame->RNTI = rand() % MAX_RNTI + 1; // RNTI should be non-zero
        frame->PHY_FRAME_INFO_TAG = rand() % 100;

        CRC_INDICATION_REL8_TAG crc_tag;
        crc_tag.CRC_INDICATION_REL8_TAG = rand() % 1000;
        crc_tag.CRCFLAG = rand() % 2;

        // Log initialization
        printf("Initialized frame %zu with RNTI: %d\n", i, frame->RNTI);
    }
}

// Function to dynamically generate CRC indication structures
void* generate_crc_indications(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T *) arg;
    size_t list_size = sizeof(crc_list) / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    int used_rntis[MAX_RNTI] = {0};

    for (size_t i = 0; i < list_size; ++i) {
        do {
            crc_list[i].RNTI = rand() % MAX_RNTI + 1;
        } while (used_rntis[crc_list[i].RNTI - 1]);

        used_rntis[crc_list[i].RNTI - 1] = 1;

        crc_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;

        CRC_INDICATION_REL8_TAG *crc_tag = &crc_list[i].crc_indication;
        crc_tag->CRC_INDICATION_REL8_TAG = rand() % 1000;
        crc_tag->CRCFLAG = rand() % 2;

        // Log generation
        printf("Generated CRC indication for RNTI: %d\n", crc_list[i].RNTI);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    FrameList frame_list;
    init_frame_list(&frame_list);

    const size_t crc_indications_count = 50;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(crc_indications_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_indications) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, generate_crc_indications, crc_indications)) {
        fprintf(stderr, "Error creating thread\n");
        free(crc_indications);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    free(crc_indications);
    return 0;
}
