        fprintf(stderr, "Error: Number of elements cannot be zero.\n");
        return NULL;
    }

    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t max_elements_per_allocation = MAX_MEMORY_FOOTPRINT / element_size;

    if (max_elements_per_allocation == 0) {
