            ? max_elements_per_allocation
            : N - total_allocated_elements;

        NFAPI_CRC_INDICATION_PDU_T* new_block = realloc(array, 
                            (total_allocated_elements + elements_to_allocate) * element_size);

        if (!new_block) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            free(array); // Ensure no memory leak occurs on failure
            return NULL;
        }

        array = new_block;
        size_t start_index = total_allocated_elements;
        for (size_t i = start_index; i < start_index + elements_to_allocate; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random valid value
            array[i].RNTI = rand() % 10000;                 // Random valid value
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;
        }

        total_allocated_elements += elements_to_allocate;

