#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_HASH_TABLE_SIZE 64

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct BufferNode {
    void *buffer;
    size_t buffer_size;
    struct BufferNode* next;
} BufferNode;

typedef struct HashTableEntry {
    unsigned int RNTI;
    struct ListElement* list_head;
    struct HashTableEntry* next;
} HashTableEntry;

typedef struct ListElement {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    BufferNode* buffer_node;
    struct ListElement* next;
} ListElement;

typedef struct LinkedList {
    ListElement* head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct HashTable {
    HashTableEntry** table;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash_function(unsigned int RNTI, size_t table_size) {
    return RNTI % table_size;
}

HashTable* create_hash_table(size_t initial_size) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = calloc(initial_size, sizeof(HashTableEntry*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->size = initial_size;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

int hash_table_insert(HashTable* ht, unsigned int RNTI, ListElement* element) {
    if (!ht || !element) return -1;

    size_t index = hash_function(RNTI, ht->size);
    HashTableEntry** slot = &ht->table[index];

    pthread_mutex_lock(&ht->lock);

    while (*slot) {
        if ((*slot)->RNTI == RNTI) {
            element->next = (*slot)->list_head;
            (*slot)->list_head = element;
            pthread_mutex_unlock(&ht->lock);
            return 0;
        }
        slot = &(*slot)->next;
    }

    *slot = malloc(sizeof(HashTableEntry));
    if (!*slot) {
        pthread_mutex_unlock(&ht->lock);
        return -2; // Memory allocation failure
    }

    (*slot)->RNTI = RNTI;
    (*slot)->list_head = element;
    (*slot)->next = NULL;

    ht->count++;
    pthread_mutex_unlock(&ht->lock);

    if (ht->count > ht->size * 0.75) {
        // Resize hash table
        size_t new_size = ht->size * 2;
        HashTableEntry** new_table = calloc(new_size, sizeof(HashTableEntry*));
        if (!new_table) return -3;

        for (size_t i = 0; i < ht->size; ++i) {
            HashTableEntry* entry = ht->table[i];
            while (entry) {
                size_t new_index = hash_function(entry->RNTI, new_size);
                HashTableEntry** new_slot = &new_table[new_index];

                HashTableEntry* temp_entry = entry;
                entry = entry->next;

                temp_entry->next = *new_slot;
                *new_slot = temp_entry;
            }
        }

        free(ht->table);
        ht->table = new_table;
        ht->size = new_size;
    }

    return 0;
}

LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int insert_into_linked_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu,
                            size_t buffer_size, HashTable* ht) {
    if (!list || !ht) return -1;

    BufferNode* buffer_node = malloc(sizeof(BufferNode));
    if (!buffer_node) return -2;

    buffer_node->buffer = _aligned_malloc(buffer_size, 64);
    if (!buffer_node->buffer) {
        free(buffer_node);
        return -3; // Memory allocation failure
    }
    buffer_node->buffer_size = buffer_size;
    buffer_node->next = NULL;

    ListElement* element = malloc(sizeof(ListElement));
    if (!element) {
        _aligned_free(buffer_node->buffer);
        free(buffer_node);
        return -4;
    }

    element->pdu = pdu;
    element->buffer_node = buffer_node;
    element->next = NULL;

    int hash_insert_status = hash_table_insert(ht, pdu.RNTI, element);
    if (hash_insert_status != 0) {
        free(element);
        _aligned_free(buffer_node->buffer);
        free(buffer_node);
        return hash_insert_status;
    }

    pthread_mutex_lock(&list->lock);

    element->next = list->head;
    list->head = element;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void cleanup_linked_list(LinkedList* list) {
    if (!list) return;

    ListElement* current = list->head;
    while (current) {
        ListElement* next = current->next;

        _aligned_free(current->buffer_node->buffer);
        free(current->buffer_node);
        free(current);

        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void cleanup_hash_table(HashTable* ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->size; ++i) {
        HashTableEntry* entry = ht->table[i];
        while (entry) {
            HashTableEntry* temp_entry = entry;
            entry = entry->next;
            free(temp_entry);
        }
    }

    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for locking both the hash table and linked list to ensure thread-safe operations.
- **Memory Management**: Handles allocation failures gracefully, freeing any allocated resources before returning an error code.
- **Hash Table Resizing**: Dynamically resizes the hash table when load factor exceeds 0.75 to maintain performance.
- **Buffer Alignment**: Uses `_aligned_malloc` for buffer alignment to ensure proper memory access in multi-threaded environments.
- **Error Handling**: Returns specific error codes for different failure scenarios, aiding robustness and debugging.

This implementation provides a scalable and efficient solution for managing linked lists of `NFAPI_CRC_INDICATION_PDU_T` structures with concurrent updates.']

