typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    size_t capacity; // Maximum allowed size to handle overflow
} ThreadSafeList;

// Initialize the thread-safe list
void initThreadSafeList(ThreadSafeList* list, size_t capacity) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->size = 0;
    list->capacity = capacity;
}

// Function to generate a random CRCFLAG
uint8_t generateRandomCRCFlag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Add an element to the thread-safe list
int addElement(ThreadSafeList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    while (list->size >= list->capacity) {
        printf("Warning: Data overflow detected. Waiting for space...\n");
        pthread_cond_wait(&list->cond, &list->mutex);
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    printf("Added element with RX_UE_INFORMATION_TAG: %u, RNTI: %u\n", 
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);

    pthread_cond_broadcast(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Generate and add a random NFAPI_CRC_INDICATION_PDU_T element
