    ThreadSafeList list;
    initThreadSafeList(&list, 10); // Set capacity to 10

    for (int i = 0; i < 20; ++i) {
        generateAndAddElement(&list);
    }

    cleanupThreadSafeList(&list);

    return 0;
}
