        NFAPI_CRC_INDICATION_PDU_T *pB = (NFAPI_CRC_INDICATION_PDU_T *)b;
        if (pA->RNTI < pB->RNTI) return -1;
        if (pA->RNTI > pB->RNTI) return 1;
        return 0;
    });

    return info;
}

NFAPI_CRC_INDICATION_PDU_T *processTiffFiles(const char **filenames, size_t count, ImageInfo *info_array_out) {
    if (count == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = NULL;
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        ImageInfo info = parseTiffFile(filenames[i], &result);

        if (info.bits_per_sample == 0 && info.samples_per_pixel == 0) {
            // Handle error, clean up
            free(result);
            result = NULL;
            break;
        }

        if (i < count - 1) { // Only allocate on first successful read
            NFAPI_CRC_INDICATION_PDU_T *temp_result = realloc(result, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!temp_result) {
                free(result);
                result = NULL;
                break;
            }
            result = temp_result;
        }

        info_array_out[i] = info; // Store image info for each file
    }

    pthread_mutex_unlock(&mutex);

    return result;
}
