#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int cellId;
    double rscp;     // Reference Signal Received Power
    double ecio;     // Evolved Coverage Indicator
} LTE_PhyLayerStats;

typedef struct Node {
    LTE_PhyLayerStats stats;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CellStatsManager;

CellStatsManager* create_manager() {
    CellStatsManager* manager = malloc(sizeof(CellStatsManager));
    if (manager) {
        manager->head = NULL;
        pthread_mutex_init(&manager->lock, NULL);
    }
    return manager;
}

void destroy_manager(CellStatsManager* manager) {
    if (!manager) return;

    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void log_change(const char* message) {
    printf("LOG: %s\n", message);
}

Node* find_node(CellStatsManager* manager, int cellId) {
    Node* current = manager->head;
    while (current) {
        if (current->stats.cellId == cellId) return current;
        current = current->next;
    }
    return NULL;
}

void add_stats(CellStatsManager* manager, LTE_PhyLayerStats stats) {
    pthread_mutex_lock(&manager->lock);

    Node* node = find_node(manager, stats.cellId);
    if (node) {
        log_change("Updating existing cell statistics.");
        node->stats.rscp = stats.rscp;
        node->stats.ecio = stats.ecio;
    } else {
        log_change("Adding new cell statistics.");
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) return;

        *newNode = (Node){ .stats = stats, .next = manager->head };
        manager->head = newNode;
    }

    pthread_mutex_unlock(&manager->lock);
}

void get_stats(CellStatsManager* manager, int cellId, LTE_PhyLayerStats* outStats) {
    if (!outStats) return;

    pthread_mutex_lock(&manager->lock);

    Node* node = find_node(manager, cellId);
    if (node) {
        *outStats = node->stats;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    CellStatsManager* manager = create_manager();

    LTE_PhyLayerStats stats1 = { .cellId = 1, .rscp = -95.0, .ecio = -7.5 };
    add_stats(manager, stats1);

    LTE_PhyLayerStats retrieved;
    get_stats(manager, 1, &retrieved);
    printf("Retrieved Cell ID: %d, RSCP: %.2f, ECIO: %.2f\n", 
           retrieved.cellId, retrieved.rscp, retrieved.ecio);

    destroy_manager(manager);
    return 0;
}
