typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    size_t packetSize;
    time_t timestamp;
} NetworkPacket;

// Mock function to simulate external API call for retrieving IP addresses
int get_random_ip(char *ipBuffer, size_t bufferSize) {
    static const char digits[] = "0123456789";
    for (int i = 0; i < 3; ++i) {
        snprintf(ipBuffer + i * 3, 4, "%d.%d.", rand() % 256, rand() % 256);
    }
    snprintf(ipBuffer + 9, 7, "%d.%d", rand() % 256, rand() % 256);
    return 0; // Return 0 to indicate success
}

// Function to manage network packets
int create_network_packets(NetworkPacket **packets, size_t n, size_t minSize, size_t maxSize) {
    if (n == 0 || packets == NULL) return -1;

    *packets = malloc(n * sizeof(NetworkPacket));
    if (*packets == NULL) return -2; // Memory allocation failed

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        if (get_random_ip((*packets)[i].sourceIP, sizeof((*packets)[i].sourceIP)) != 0) {
            fprintf(stderr, "Failed to retrieve source IP address\n");
            free(*packets);
            return -3;
        }

        if (get_random_ip((*packets)[i].destinationIP, sizeof((*packets)[i].destinationIP)) != 0) {
            fprintf(stderr, "Failed to retrieve destination IP address\n");
            free(*packets);
            return -4;
        }

        (*packets)[i].packetSize = rand() % (maxSize - minSize + 1) + minSize;

        // Ensure monotonic timestamps
        if (i == 0) {
            (*packets)[i].timestamp = time(NULL);
        } else {
            do {
                (*packets)[i].timestamp = (*packets)[i-1].timestamp + rand() % 100;
            } while ((*packets)[i].timestamp <= (*packets)[i-1].timestamp);
        }
    }

    return 0; // Success
}

// Example usage
int main() {
    NetworkPacket *packets = NULL;
    size_t n = 10;
    size_t minSize = 50, maxSize = 1500;

    if (create_network_packets(&packets, n, minSize, maxSize) == 0) {
        for (size_t i = 0; i < n; ++i) {
            printf("Packet %zu: Source IP: %s, Destination IP: %s, Size: %zu, Timestamp: %ld\n",
                   i + 1, packets[i].sourceIP, packets[i].destinationIP,
                   packets[i].packetSize, packets[i].timestamp);
        }
    } else {
        fprintf(stderr, "Failed to create network packets\n");
    }

    free(packets); // Clean up
    return 0;
}
