            ThemeConfig *cached_theme = get_theme_from_cache(name);
            if (!cached_theme) {
                add_theme_to_cache(theme);
            } else {
                memcpy(cached_theme, &theme, sizeof(ThemeConfig));
            }
        }

        printf("%s,%d,%d,%d,%.2f,%.2f\n", theme.theme_name, theme.colors[0], theme.colors[1], theme.colors[2], theme.font_size, theme.average_value);
    }

    fclose(file);
}

unsigned char parse_color(const char *color_str) {
    return (unsigned char)(atoi(color_str) & 0xFF);
}

float calculate_average_value(unsigned char r, unsigned char g, unsigned char b, float font_size) {
    return ((r + g + b) / 3.0f + font_size) / 2.0f;
}

