```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ATTEMPTS 10

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_reallocations(int count) {
    printf("Number of reallocations performed: %d\n", count);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N, int *realloc_count) {
    if (N <= 0 || N > 10000) return NULL;

    size_t chunk_size = 1;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int attempts = 0;
    *realloc_count = 0;

    while (attempts < MAX_ATTEMPTS) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array != NULL) {
            array = new_array;
            for (size_t i = 0; i < chunk_size; ++i) {
                array[i].RX_UE_INFORMATION_TAG = rand() % 256; // Example initialization
                array[i].RNTI = rand() % 65536; // Example initialization
                array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG
            }

            if (chunk_size >= N) {
                return array;
            } else {
                *realloc_count += 1;
                chunk_size *= 2;
            }
        } else {
            attempts++;
        }
    }

    free(array);
    return NULL;
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    size_t N = 5000; // Example user input
    int realloc_count = 0;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_crc_pdu_array(N, &realloc_count);

    if (pdu_array != NULL) {
        printf("Array allocated successfully.\n");
        log_reallocations(realloc_count);
        // Use the array...

        free(pdu_array); // Free the allocated memory
    } else {
        fprintf(stderr, "Failed to allocate array after multiple attempts.\n");
    }

    return 0;
}
