#include <stdio.h>
#include <stdlib.h>
import time.h
#include <string.h>
#include <stdbool.h>

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int packetSize;
    time_t timestamp;
    char protocolType[10]; // e.g., TCP, UDP, ICMP
} NetworkPacket;

const char* protocolTypes[] = {"TCP", "UDP", "ICMP"};
const size_t numProtocols = 3;

bool isValidIP(const char* ip) {
    int parts = 0;
    for (int i = 0; ip[i]; ++i) {
        if (ip[i] == '.') {
            ++parts;
            if (parts > 3 || ip[i + 1] == '\0') return false;
        } else if (!isdigit(ip[i])) {
            return false;
        }
    }
    return parts == 3;
}

void initializePackets(NetworkPacket** packets, size_t N) {
    *packets = malloc(N * sizeof(NetworkPacket));
    if (*packets == NULL) {
        perror("Failed to allocate memory for packets");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        snprintf((*packets)[i].sourceIP, sizeof((*packets)[i].sourceIP), "192.168.1.%zu", rand() % 255 + 1);
        snprintf((*packets)[i].destinationIP, sizeof((*packets)[i].destinationIP), "10.0.%zu.%zu", rand() % 256, rand() % 256);

        if (!isValidIP((*packets)[i].sourceIP) || !isValidIP((*packets)[i].destinationIP)) {
            fprintf(stderr, "Invalid IP format\n");
            exit(EXIT_FAILURE);
        }

        (*packets)[i].packetSize = (rand() % 1500 + 64); // Ethernet frame size range: 64 - 1518 bytes
        (*packets)[i].timestamp = time(NULL) + i; // Monotonically increasing timestamps
        snprintf((*packets)[i].protocolType, sizeof((*packets)[i].protocolType), "%s", protocolTypes[rand() % numProtocols]);
    }
}

void addPacket(NetworkPacket** packets, size_t* count) {
    NetworkPacket newPacket;
    snprintf(newPacket.sourceIP, sizeof(newPacket.sourceIP), "192.168.1.%zu", rand() % 255 + 1);
    snprintf(newPacket.destinationIP, sizeof(newPacket.destinationIP), "10.0.%zu.%zu", rand() % 256, rand() % 256);

    if (!isValidIP(newPacket.sourceIP) || !isValidIP(newPacket.destinationIP)) {
        fprintf(stderr, "Invalid IP format\n");
        return;
    }

    newPacket.packetSize = (rand() % 1500 + 64);
    newPacket.timestamp = time(NULL) + *count; // Ensure monotonically increasing timestamp
    snprintf(newPacket.protocolType, sizeof(newPacket.protocolType), "%s", protocolTypes[rand() % numProtocols]);

    *packets = realloc(*packets, (*count + 1) * sizeof(NetworkPacket));
    if (*packets == NULL) {
        perror("Failed to reallocate memory for new packet");
        exit(EXIT_FAILURE);
    }
    (*packets)[*count] = newPacket;
    ++(*count);
}

void exportPacketsCSV(const NetworkPacket* packets, size_t count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing CSV");
        return;
    }

    fprintf(file, "SourceIP,DestinationIP,PacketSize,Timestamp,ProtocolType\n");
    for (size_t i = 0; i < count; ++i) {
        fprintf(file, "%s,%s,%d,%ld,%s\n", packets[i].sourceIP, packets[i].destinationIP, packets[i].packetSize, packets[i].timestamp, packets[i].protocolType);
    }
    fclose(file);
}

void exportPacketsJSON(const NetworkPacket* packets, size_t count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing JSON");
        return;
    }

    fprintf(file, "[\n");
    for (size_t i = 0; i < count; ++i) {
        fprintf(file, "  {\n"
                     "    \"SourceIP\": \"%s\",\n"
                     "    \"DestinationIP\": \"%s\",\n"
                     "    \"PacketSize\": %d,\n"
                     "    \"Timestamp\": %ld,\n"
                     "    \"ProtocolType\": \"%s\"\n",
                     packets[i].sourceIP, packets[i].destinationIP, packets[i].packetSize, packets[i].timestamp, packets[i].protocolType);
        if (i < count - 1) {
            fprintf(file, "  },\n");
        } else {
            fprintf(file, "  }\n");
        }
    }
    fprintf(file, "]");
    fclose(file);
}

int main() {
    NetworkPacket* packets = NULL;
    size_t packetCount = 5;

    initializePackets(&packets, packetCount);

    // Example of adding a new packet
    addPacket(&packets, &packetCount);

    // Export to CSV and JSON formats
    exportPacketsCSV(packets, packetCount, "packets.csv");
    exportPacketsJSON(packets, packetCount, "packets.json");

    free(packets);
    return 0;
}
