    // Simulate external API call for humidity measurement
    return (rand() % 50) + 20.0f; // Random humidity between 20% and 70%
}

// Function to calculate pressure based on a predefined formula
float calculate_pressure(float temperature, float humidity) {
    return 1013.25 * (1 - 0.0065 * temperature / (temperature + 273.15));
}

// Utility function for logging
void log_message(const char* message) {
    printf("%s\n", message);
}

SensorData* manage_sensor_data(int N, int* actual_count) {
    if (N <= 0) {
        *actual_count = 0;
        return NULL;
    }

    SensorData* data_array = (SensorData*)calloc(N, sizeof(SensorData));
    if (!data_array) {
        log_message("Memory allocation failed");
        *actual_count = 0;
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator
    time_t start_time = time(NULL);

    for (int i = 0; i < N; ++i) {
        // Retry mechanism with exponential backoff for API calls
        int retries = 5;
        while (retries > 0) {
            data_array[i].sensorID = get_sensor_id();
            if (data_array[i].sensorID != -1) break;

            log_message("Retrying sensor ID retrieval...");
            sleep(2); // Backoff strategy
            --retries;
        }

        retries = 5;
        while (retries > 0) {
            data_array[i].temperature = measure_temperature();
            if (data_array[i].temperature != -1.0f) break;

            log_message("Retrying temperature measurement...");
            sleep(2);
            --retries;
        }

        retries = 5;
        while (retries > 0) {
            data_array[i].humidity = measure_humidity();
            if (data_array[i].humidity != -1.0f) break;

            log_message("Retrying humidity measurement...");
            sleep(2);
            --retries;
        }

        // Calculate pressure based on temperature and humidity
        data_array[i].pressure = calculate_pressure(data_array[i].temperature, data_array[i].humidity);

        // Ensure monotonic timestamp generation
        data_array[i].timestamp = start_time + i;

        log_message("SensorData populated successfully");
    }

    *actual_count = N;
    return data_array;
}

int main() {
    int N = 10; // Number of sensor data points to generate
    int actual_count = 0;

    SensorData* sensor_data = manage_sensor_data(N, &actual_count);

    if (sensor_data) {
        for (int i = 0; i < actual_count; ++i) {
            printf("SensorID: %d, Temperature: %.2f, Humidity: %.2f, Pressure: %.2f, Timestamp: %ld\n",
                   sensor_data[i].sensorID,
                   sensor_data[i].temperature,
                   sensor_data[i].humidity,
                   sensor_data[i].pressure,
                   sensor_data[i].timestamp);
        }
        free(sensor_data); // Ensure memory is freed
    }

    return 0;
}
