    const int initialSize = 10;
    *list = malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initialSize; ++i) {
        (*list)[i].RNTI = rand() % 1000;
        (*list)[i].crcTag.CRCFLAG = rand() % 2;

        // Check for duplicates
        for (size_t j = 0; j < i; ++j) {
            if ((*list)[j].RNTI == (*list)[i].RNTI) {
                fprintf(stderr, "Duplicate RNTI found: %d\n", (*list)[i].RNTI);
                break;
            }
        }
    }

    *size = initialSize;

    // Implement resizing logic if needed
