int parseThemesFromFile(const char *filename, char ***outputLines, size_t *lineCount) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char *content = malloc(fileSize + 1);
    if (!content) {
        fclose(file);
        return EXIT_FAILURE;
    }

    fread(content, 1, fileSize, file);
    content[fileSize] = '\0';
    fclose(file);

    char *line = strtok(content, "\n");
    size_t initialCapacity = 10;
    *outputLines = malloc(initialCapacity * sizeof(char *));
    if (!*outputLines) {
        free(content);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; line != NULL && i < initialCapacity; ++i, line = strtok(NULL, "\n")) {
        char *processedLine = strdup(line);
        if (!processedLine) {
            // Free previously allocated lines
            while (i > 0) free((*outputLines)[--i]);
            free(*outputLines);
            free(content);
            return EXIT_FAILURE;
        }

        (*outputLines)[i] = processedLine;

        size_t wordCount = 0;
        char *word = strtok(line, ",");
        while (word != NULL) {
            ++wordCount;
            word = strtok(NULL, ",");
        }

        if (wordCount >= 2) {
            int lastTwoValues[2];
            sscanf(strtok(line, ","), "%*[^,],%*[^,],%d,%d", &lastTwoValues[0], &lastTwoValues[1]);
            double average = (lastTwoValues[0] + lastTwoValues[1]) / 2.0;
            char buffer[50];
            snprintf(buffer, sizeof(buffer), ",%.2f", average);
            strcat(processedLine, buffer);
        }
    }

    *lineCount = i;

    free(content);

    if (i == initialCapacity) {
        // If we've reached capacity, reallocate
        size_t newCapacity = initialCapacity * 2;
        char **newOutputLines = realloc(*outputLines, newCapacity * sizeof(char *));
        if (!newOutputLines) {
            // Free previously allocated lines
            while (i > 0) free((*outputLines)[--i]);
            free(*outputLines);
            return EXIT_FAILURE;
        }
        *outputLines = newOutputLines;
    } else {
        // Otherwise, shrink to fit exactly the used space
        char **newOutputLines = realloc(*outputLines, i * sizeof(char *));
        if (newOutputLines) {
            *outputLines = newOutputLines;
        }
    }

    return EXIT_SUCCESS;
}
