        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Insert a single node into the linked list
void insert_list(ListNode** head, ListNode* new_node) {
    pthread_mutex_lock(head ? &(*head)->mutex : NULL);

    if (*head == NULL) {
        *head = new_node;
    } else {
        ListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(head ? &(*head)->mutex : NULL);
}

// Batch insert multiple nodes into the linked list
void batch_insert(ListNode** head, NFAPI_CRC_INDICATION_PDU_T *data_array, size_t count) {
    ListNode* prev = NULL;

    for (size_t i = 0; i < count; ++i) {
        if (!is_unique_in_hash_table(&hash_table, data_array[i].RNTI)) {
