        ListNode* new_node = create_node(data_array[i]);
        insert_in_hash_table(&hash_table, data_array[i].RNTI);

        if (prev == NULL) {
            *head = new_node;
        } else {
            prev->next = new_node;
        }
        prev = new_node;

        pthread_mutex_unlock(prev ? &(*head)->mutex : NULL);
    }
}

// Compact the linked list by removing unused nodes
void compact_list(ListNode** head) {
    ListNode* current = *head;

    while (current != NULL) {
        if (current->data.ref_count == 0) {
            ListNode* to_delete = current;
            current = current->next;

            if (to_delete == *head) {
                *head = current;
            } else {
                // Find the previous node
                ListNode* temp = *head;
                while (temp && temp->next != to_delete) {
                    temp = temp->next;
                }
                if (temp) {
                    temp->next = current;
                }
            }

            free(to_delete);
        } else {
            current = current->next;
        }
    }
}

// Remove unused nodes from the list
void remove_unused_nodes(ListNode** head) {
    pthread_mutex_lock(&head_mutex);

    compact_list(head);

    pthread_mutex_unlock(&head_mutex);
}

// Free the entire linked list
void free_list(ListNode* head) {
