    pthread_mutex_lock(&ht->mutex);

    // Simple linear probing for collision resolution
    while (ht->table[index] != 0 && ht->table[index] != rnti) {
        index = (index + 1) % ht->size;
    }

    int is_unique = (ht->table[index] == 0);

    pthread_mutex_unlock(&ht->mutex);

    return is_unique;
}

