    pthread_mutex_lock(&ht->mutex);

    // Handle collision with linear probing
    while (ht->table[index] != 0 && ht->table[index] != rnti) {
        index = (index + 1) % ht->size;
    }

    if (ht->table[index] == 0 || ht->table[index] == rnti) {
        ht->table[index] = rnti;

