// Dynamically resize the hash table
void hash_table_resize(HashTable* ht) {
    size_t new_size = ht->size * 2;
    uint16_t* new_table = (uint16_t*)calloc(new_size, sizeof(uint16_t));

    for (size_t i = 0; i < ht->size; ++i) {
        if (ht->table[i] != 0) {
