['```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

#define TTL 300 // Time to live in seconds
#define HASH_TABLE_SIZE 1024

typedef struct Session {
    char sessid[256];
    void *metadata;
    time_t expiry_time;
} Session;

static Session *hash_table[HASH_TABLE_SIZE];
static pthread_rwlock_t locks[HASH_TABLE_SIZE];

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_rwlock_init(&locks[i], NULL);
    }
}

unsigned int hash_function(const char *sessid) {
    unsigned long hash = 5381;
    int c;

    while ((c = *sessid++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash % HASH_TABLE_SIZE;
}

void add_session(const char *sessid, void *metadata) {
    unsigned int index = hash_function(sessid);

    pthread_rwlock_wrlock(&locks[index]);
    for (Session *entry = hash_table[index]; entry != NULL; entry = entry->next) {
        if (strcmp(entry->sessid, sessid) == 0) {
            pthread_rwlock_unlock(&locks[index]);
            return; // Session already exists
        }
    }

    Session *new_session = malloc(sizeof(Session));
    strcpy(new_session->sessid, sessid);
    new_session->metadata = metadata;
    new_session->expiry_time = time(NULL) + TTL;
    new_session->next = hash_table[index];
    hash_table[index] = new_session;

    pthread_rwlock_unlock(&locks[index]);
}

void *get_metadata(const char *sessid) {
    unsigned int index = hash_function(sessid);

    pthread_rwlock_rdlock(&locks[index]);
    for (Session *entry = hash_table[index]; entry != NULL; entry = entry->next) {
        if (strcmp(entry->sessid, sessid) == 0 && time(NULL) < entry->expiry_time) {
            pthread_rwlock_unlock(&locks[index]);
            return entry->metadata;
        }
    }

    pthread_rwlock_unlock(&locks[index]);
    return NULL;
}

void remove_expired_sessions() {
    time_t current_time = time(NULL);

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_rwlock_wrlock(&locks[i]);

        Session **entry = &hash_table[i];
        while (*entry != NULL) {
            if ((*entry)->expiry_time <= current_time) {
                Session *expired_session = *entry;
                *entry = expired_session->next;
                free(expired_session);
            } else {
                entry = &(*entry)->next;
            }
        }

        pthread_rwlock_unlock(&locks[i]);
    }
}

void cleanup() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_rwlock_wrlock(&locks[i]);

        Session *entry = hash_table[i];
        while (entry != NULL) {
            Session *temp = entry;
            entry = entry->next;
            free(temp);
        }

        pthread_rwlock_unlock(&locks[i]);
        pthread_rwlock_destroy(&locks[i]);
    }
}

// Example usage
int main() {
    init_hash_table();

    // Add sessions, retrieve metadata, and clean up expired sessions in practice.
    char *metadata = "Sample Data";
    add_session("sessid123", (void *)metadata);
    void *retrieved_metadata = get_metadata("sessid123");

    if (retrieved_metadata) {
        printf("Metadata: %s\n", (char *)retrieved_metadata);
    } else {
        printf("Session not found or expired.\n");
    }

    // Clean up expired sessions periodically
    remove_expired_sessions();

    cleanup();
    return 0;
}
