        pdus[i].tag.CRCFLAG = rand() & 1; // Randomly set CRC flag (0 or 1)
        pdus[i].timestamp = current_time;
    }

    log_message(log_level, "CRC indications allocated and populated successfully.");

    pthread_mutex_unlock(&lock);

    return pdus;
}

void deallocate_crc_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
        log_message(1, "Memory deallocated for CRC indications.");
    }
}

int main() {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    size_t N = 500; // Example usage
    int log_level = 1;

    NFAPI_CRC_INDICATION_PDU_T *pdus = allocate_and_populate_crc_pdus(N, log_level);

    if (pdus != NULL) {
        // Use pdus...

        deallocate_crc_pdus(pdus);
    }

    return 0;
}
