#define MAX_FRAMES 10000

typedef struct {
    uint16_t RX_FRAME_PDU_TAG;
    uint32_t RNTI;
    uint8_t PHY_FRAME_INFO_TAG;
} NFAPI_RX_FRAME_PDU_PDU_T;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int valid;
    uint32_t UE_RNTI;
} RX_UE_INFORMATION_TAG;

// Frame structure
typedef struct {
    NFAPI_RX_FRAME_PDU_PDU_T pdu;
    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc;
} Frame;

// Global variables for thread management and logging
pthread_mutex_t frame_list_mutex = PTHREAD_MUTEX_INITIALIZER;
Frame* frame_list[MAX_FRAMES];
int current_frame_count = 0;

void hardware_init() {
    // Initialize hardware module here
}

uint32_t get_random_rnti() {
    return rand();
}

uint8_t get_random_crcflag() {
    return rand() % 2;
}

void* process_frames(void* arg) {
    Frame* frame = (Frame*)arg;

    pthread_mutex_lock(&frame_list_mutex);
    // Process the frame here
    printf("Processing frame with RNTI: %u\n", frame->pdu.RNTI);
    pthread_mutex_unlock(&frame_list_mutex);

    return NULL;
}

void cleanup_frames() {
    for (int i = 0; i < current_frame_count; ++i) {
        free(frame_list[i]);
    }
    current_frame_count = 0;
}

void initialize_frames(int num_frames) {
    srand(time(NULL));

    pthread_t threads[num_frames];
    hardware_init();

    for (int i = 0; i < num_frames; ++i) {
        frame_list[current_frame_count] = malloc(sizeof(Frame));

        if (!frame_list[current_frame_count]) {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup_frames();
            return;
        }

        // Initialize frame
        frame_list[current_frame_count]->pdu.RX_FRAME_PDU_TAG = i + 1;
        frame_list[current_frame_count]->pdu.RNTI = get_random_rnti();
        frame_list[current_frame_count]->pdu.PHY_FRAME_INFO_TAG = i % 256;

        frame_list[current_frame_count]->ue_info.valid = 1;
        frame_list[current_frame_count]->ue_info.UE_RNTI = frame_list[current_frame_count]->pdu.RNTI;

        frame_list[current_frame_count]->crc.CRCFLAG = get_random_crcflag();

        pthread_create(&threads[i], NULL, process_frames, (void*)frame_list[current_frame_count]);

        current_frame_count++;
    }

    for (int i = 0; i < num_frames; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    int num_frames_to_process = 100; // Example number, adjust as needed
    initialize_frames(num_frames_to_process);

    cleanup_frames();

    return 0;
}
