static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t current_size = 0;
static NFAPI_CRC_INDICATION_PDU_T *array = NULL;
static unsigned int rnti_reassignments = 0;
static unsigned int memory_events = 0;

// Logging function (basic implementation)
void log_event(const char *message) {
    printf("%s\n", message);
}

// Function to check and resolve duplicate RNTI
unsigned long generate_unique_rnti(unsigned long existing_rntis[], size_t count) {
    unsigned long rnti;
    srand((unsigned int)time(NULL));
    do {
        rnti = rand() % (1 << 16); // Assume RNTI is a 16-bit value
    } while (count > 0 && bsearch(&rnti, existing_rntis, count, sizeof(unsigned long), 
                                  (__compar_fn_t)strcmp));
    return rnti;
}

// Function to dynamically resize the array
NFAPI_CRC_INDICATION_PDU_T* resize_array(size_t new_size) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_event("Memory allocation failed during resizing.");
        free(array);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }
    array = new_array;
    memory_events++;
    return array;
}

// Thread-safe function to populate the structures
void* populate_structures(void *arg) {
    size_t n = *(size_t *)arg;
    unsigned long existing_rntis[MAX_ELEMENTS];

    pthread_mutex_lock(&lock);
    if (n > current_size) {
        if (!resize_array(n)) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        current_size = n;
    }
    pthread_mutex_unlock(&lock);

    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&lock);

        array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Simulate data retrieval
        unsigned long rnti = generate_unique_rnti(existing_rntis, current_size);
        if (bsearch(&rnti, existing_rntis, current_size, sizeof(unsigned long), 
                    (__compar_fn_t)strcmp)) {
            rnti_reassignments++;
            array[i].RNTI = generate_unique_rnti(existing_rntis, current_size);
        } else {
            array[i].RNTI = rnti;
        }

        existing_rntis[current_size - 1] = array[i].RNTI; // Update RNTIs
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

// Main function to demonstrate usage
int main() {
    size_t num_elements = 5000; // Example number of elements
    populate_structures(&num_elements);

    // Clean up
