#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MEMORY_BUDGET 2 * 1024 * 1024 // 2 MB
#define STRUCT_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)
#define MAX_STRUCTS (MEMORY_BUDGET / STRUCT_SIZE)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Random value between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

void serialize_data(const NFAPI_CRC_INDICATION_PDU_T* data, size_t count, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(data, STRUCT_SIZE, count, file);
    fclose(file);
}

void log_memory_usage(const char *log_filename, size_t used_memory, int append) {
    FILE *log_file = fopen(log_filename, append ? "a" : "w");
    if (log_file != NULL) {
        fprintf(log_file, "Memory Used: %zu bytes\n", used_memory);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

void create_and_populate_structures(size_t N, const char* bin_filename, const char* log_filename, int append) {
    if (N > MAX_STRUCTS) {
        fprintf(stderr, "Requested number of structures exceeds memory budget.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(N * STRUCT_SIZE);
    if (structures == NULL) {
        perror("Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array");
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < N; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = rand(); // Example valid value
        structures[i].RNTI = rand() % 10000; // Example RNTI range
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Example CRC tag range
        structures[i].CRCFLAG = rand() & 1;
    }

    serialize_data(structures, N, bin_filename);

    size_t used_memory = N * STRUCT_SIZE;
    log_memory_usage(log_filename, used_memory, append);

    free(structures);
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <N> <binary_file> <log_file> [append]\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t N = strtoul(argv[1], NULL, 10);
    const char* bin_filename = argv[2];
    const char* log_filename = argv[3];
    int append = (argc > 4 && strcmp(argv[4], "append") == 0);

    create_and_populate_structures(N, bin_filename, log_filename, append);

    return EXIT_SUCCESS;
}
