// Define a structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // This will be randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Maximum number of structures allowed
#define MAX_STRUCTURES 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)aligned_alloc(64, sizeof(DynamicList));
    if (!list) return NULL;

    list->data = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_structure(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Maximum limit reached
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Allocation failed
    }

    new_data->RX_UE_INFORMATION_TAG = rand();  // Assign random values for demonstration
    new_data->RNTI = rand();
    new_data->CRC_INDICATION_REL8_TAG = rand() % 256;
    new_data->CRCFLAG = rand() % 2;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count + 1));
    if (!list->data) {
        free(new_data);
        pthread_mutex_unlock(&list->lock);
        return -3; // Reallocation failed
    }

    list->data[list->count] = *new_data;
    list->count++;

    free(new_data); // Free the temporary allocation

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_dynamic_list(DynamicList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    if (list->data) {
        free(list->data);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    DynamicList *list = create_dynamic_list();
    if (!list) {
        fprintf(stderr, "Failed to create dynamic list\n");
        return 1;
    }

    for (int i = 0; i < MAX_STRUCTURES + 10; ++i) {
        int result = add_structure(list);
        if (result != 0) {
            fprintf(stderr, "Error adding structure: %d\n", result);
        }
    }

    free_dynamic_list(list);

    return 0;
}
```

