void validateStructures(CRCArray* arr, bool (*validate)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&arr->lock);

    Node* current = arr->head;
    while (current != NULL) {
        if (!validate(&(current->data))) {
            fprintf(stderr, "Validation error\n");
            exit(EXIT_FAILURE);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&arr->lock);
}

