pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_rnti(uint16_t rnti, const RNTI_LIST *rnti_list) {
    for (size_t i = 0; i < rnti_list->count; ++i) {
        if (rnti == rnti_list->rnti_values[i]) {
            return 1;
        }
    }
    return 0;
}

void fetch_rnti_list(RNTI_LIST *rnti_list, const char **field_names, size_t field_count) {
