#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define LOG_DEBUG 1
#define LOG_INFO 2
#define LOG_ERROR 3

typedef struct {
    uint32_t transactionID;
    char sourceIP[16];
    char destinationIP[16];
} Metadata_T;

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    union {
        struct {
            uint8_t CRCFLAG:1;
            uint8_t reserved:7;
        } CRC_INDICATION_REL8_TAG;
    };
    Metadata_T metadata;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t elementSize;
    size_t count;
    void *pool;
} MemoryPool;

MemoryPool pool = {sizeof(NFAPI_CRC_INDICATION_PDU_T), 0, NULL};

void initializeMemoryPool(MemoryPool* p, size_t elementSize, size_t totalElements) {
    p->elementSize = elementSize;
    p->count = totalElements;
    p->pool = malloc(elementSize * totalElements);
    if (!p->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void* allocateFromPool(MemoryPool* p) {
    if (p->count == 0) return NULL;
    void *ptr = p->pool + (--p->count) * p->elementSize;
    return ptr;
}

void freeMemoryPool(MemoryPool* p) {
    free(p->pool);
    p->pool = NULL;
}

int initializeAndPopulatePDUArray(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t numElements, int logLevel) {
    if (numElements > MAX_ENTRIES || !pdus) return -1;

    static uint32_t seed = time(NULL);
    initializeMemoryPool(&pool, sizeof(NFAPI_CRC_INDICATION_PDU_T), numElements);

    *pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdus) {
        fprintf(stderr, "Failed to allocate memory for PDUs\n");
        freeMemoryPool(&pool);
        return -1;
    }

    uint32_t transactionIDs[numElements];
    for (size_t i = 0; i < numElements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) allocateFromPool(&pool);
        if (!pdu) {
            fprintf(stderr, "Failed to allocate from memory pool\n");
            freeMemoryPool(&pool);
            free(*pdus);
            return -1;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 256;
        pdu->RNTI = rand() % 65536;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        do {
            pdu->metadata.transactionID = rand();
        } while (transactionIDs[i] == pdu->metadata.transactionID);
        transactionIDs[i] = pdu->metadata.transactionID;

        snprintf(pdu->metadata.sourceIP, sizeof(pdu->metadata.sourceIP), "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(pdu->metadata.destinationIP, sizeof(pdu->metadata.destinationIP), "10.0.%d.%d", rand() % 256, rand() % 256);

        if (logLevel >= LOG_DEBUG) {
            printf("Initialized PDU[%zu]: TXID=%u, SRC_IP=%s, DST_IP=%s\n",
                   i, pdu->metadata.transactionID,
                   pdu->metadata.sourceIP, pdu->metadata.destinationIP);
        }

        (*pdus)[i] = *pdu;
    }

    return 0; // Success
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;

    if (initializeAndPopulatePDUArray(&pdus, 10000, LOG_DEBUG) != 0) {
        fprintf(stderr, "Failed to initialize and populate PDUs\n");
        return EXIT_FAILURE;
    }

    // Usage of the populated array can go here

    free(pdus);
    freeMemoryPool(&pool);

    return EXIT_SUCCESS;
}
