#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_MESSAGES 10000

typedef struct {
    int id;
    size_t payload_length;
    time_t timestamp;
} MessageHeader;

typedef struct {
    MessageHeader header;
    void* payload;
} NetworkMessage;

typedef struct Node {
    NetworkMessage message;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_age; // seconds
} MessageList;

MessageList* create_message_list(int max_age) {
    MessageList* list = (MessageList*)malloc(sizeof(MessageList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_age = max_age;
    return list;
}

void destroy_message_list(MessageList* list) {
    Node *current, *next;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_message(MessageList* list, NetworkMessage message) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->message = message;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void remove_expired_messages(MessageList* list) {
    Node *current, *prev, *next;

    time_t now = time(NULL);
    int age_limit = now - list->max_age;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    prev = NULL;

    while (current != NULL) {
        next = current->next;

        if (current->message.header.timestamp < age_limit) {
            if (prev == NULL) { // Removing head
                list->head = next;
            } else {
                prev->next = next;
            }
            free(current);
        } else {
            prev = current;
        }
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
}

void process_messages(MessageList* list, void (*process_func)(NetworkMessage)) {
    Node *current;

    pthread_mutex_lock(&list->lock);

    for (current = list->head; current != NULL; current = current->next) {
        process_func(current->message);
    }

    pthread_mutex_unlock(&list->lock);
}

void message_broker_integration(NetworkMessage message, const char* status) {
    // Simulated integration with a message broker
    printf("Integrating with message broker: ID=%d, Status=%s\n", message.header.id, status);
}

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

// Example processing function
void example_process_func(NetworkMessage msg) {
    printf("Processing Message ID: %d\n", msg.header.id);

    // Simulate message broker integration
    message_broker_integration(msg, "Processed");
}

int main() {
    MessageList* list = create_message_list(60); // 1-minute timeout

    if (!list) {
        log_error("Failed to initialize message list.");
        return EXIT_FAILURE;
    }

    NetworkMessage msg = {{.id = 1, .payload_length = 128, .timestamp = time(NULL)}, NULL};

    add_message(list, msg);

    remove_expired_messages(list);
    process_messages(list, example_process_func);

    destroy_message_list(list);
    return EXIT_SUCCESS;
}
```

### Key Components:
- **MessageList**: A linked list to store messages with a mutex for thread safety.
- **add_message**, **remove_expired_messages**, and **process_messages**: Core operations ensuring concurrency control.
- **message_broker_integration** and **log_error**: Handle external integration and error reporting.
- The code is modular, supporting future enhancements while maintaining readability and scalability.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure to hold flow control parameters.
typedef struct {
    int threshold;
    int increment;
    // Add other configuration parameters as needed.
} FlowControlConfig;

// Define a structure for PDCP PDUs statistics.
typedef struct PDCPPDUSStats {
    unsigned long pduCount;
    // Add more statistics fields if necessary.
    struct PDCPPDUSStats *next;  // For linked list of PDU stats.
} PDCPPDUSStats;

// Define a structure for MAC entity state.
typedef struct MACEntityState {
    int macEntityID;
    PDCPPDUSStats *pduStatsHead;
    FlowControlConfig config;
    pthread_mutex_t lock;  // Mutex for thread-safe operations.
    struct MACEntityState *next;  // For linked list of entities.
} MACEntityState;

// Define the head of the global dynamic list and a mutex for it.
MACEntityState *globalListHead = NULL;
pthread_mutex_t globalListMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize flow control configuration.
void initFlowControlConfig(FlowControlConfig *config) {
    config->threshold = 10; // Example default values
    config->increment = 5;
}

// Function to create a new MAC entity state.
MACEntityState* createMacEntity(int macEntityID) {
    MACEntityState *newEntity = (MACEntityState*)malloc(sizeof(MACEntityState));
    if (!newEntity) return NULL;

    pthread_mutex_init(&newEntity->lock, NULL);
    newEntity->macEntityID = macEntityID;
    newEntity->pduStatsHead = NULL;
    initFlowControlConfig(&newEntity->config);
    newEntity->next = NULL;

    return newEntity;
}

// Function to add or update a MAC entity in the global list.
void addOrUpdateMacEntity(int macEntityID) {
    pthread_mutex_lock(&globalListMutex);

    MACEntityState *current = globalListHead, *prev = NULL;

    // Search for an existing MAC entity.
    while (current != NULL && current->macEntityID != macEntityID) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {  // If not found, create and add a new one.
        current = createMacEntity(macEntityID);
        if (prev == NULL) {
            globalListHead = current;  // It's the first entity in the list.
        } else {
            prev->next = current;
        }
    }

    pthread_mutex_unlock(&globalListMutex);
}

// Function to retrieve the latest PDCP PDU statistics for a given MAC entity ID.
PDCPPDUSStats* getLatestPduStatistics(int macEntityID) {
    pthread_mutex_lock(&globalListMutex);

    MACEntityState *entity = globalListHead;

    // Search for the MAC entity with the specified ID.
    while (entity != NULL && entity->macEntityID != macEntityID) {
        entity = entity->next;
    }

    PDCPPDUSStats *latestStats = NULL;
    if (entity != NULL) {
        pthread_mutex_lock(&entity->lock);  // Lock for thread safety within the specific MAC entity.

        latestStats = entity->pduStatsHead;  // Get the head of the statistics linked list.

        pthread_mutex_unlock(&entity->lock);
    }

    pthread_mutex_unlock(&globalListMutex);

    return latestStats;
}

// Function to update PDCP PDU statistics for a given MAC entity ID.
void updatePduStatistics(int macEntityID, unsigned long pduCountIncrement) {
    pthread_mutex_lock(&globalListMutex);

    MACEntityState *entity = globalListHead;

    while (entity != NULL && entity->macEntityID != macEntityID) {
        entity = entity->next;
    }

    if (entity != NULL) {
        pthread_mutex_lock(&entity->lock);  // Lock for thread safety within the specific MAC entity.

        PDCPPDUSStats *newStat = (PDCPPDUSStats*)malloc(sizeof(PDCPPDUSStats));
        if (!newStat) return;

        newStat->pduCount = pduCountIncrement;
        newStat->next = entity->pduStatsHead;  // Insert at the head of the linked list.
        entity->pduStatsHead = newStat;

        pthread_mutex_unlock(&entity->lock);
    }

    pthread_mutex_unlock(&globalListMutex);
}

// Function to clean up resources and free memory when shutting down.
void cleanup() {
    pthread_mutex_lock(&globalListMutex);

    MACEntityState *current = globalListHead, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;

        // Free the PDCP PDUs statistics linked list for each entity.
        PDCPPDUSStats *statsNode = temp->pduStatsHead;
        while (statsNode != NULL) {
            PDCPPDUSStats *toFree = statsNode;
            statsNode = statsNode->next;
            free(toFree);
        }

        // Destroy the mutex and free the MAC entity structure.
        pthread_mutex_destroy(&temp->lock);
        free(temp);
    }

    pthread_mutex_unlock(&globalListMutex);

    // Destroy the global list mutex.
    pthread_mutex_destroy(&globalListMutex);
}

int main() {
    // Example usage:

    addOrUpdateMacEntity(1);
    updatePduStatistics(1, 100);  // Update PDU statistics for MAC entity with ID 1.

    PDCPPDUSStats *stats = getLatestPduStatistics(1);
    if (stats) {
        printf("MAC Entity 1 - Latest PDU Count: %lu\n", stats->pduCount);
    }

    cleanup();  // Cleanup resources at the end.

    return 0;
}
