#define CACHE_LINE_SIZE 64
#define MAX_ELEMENTS 1000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    struct {
        uint8_t CRCFLAG; // Randomly set to 0 or 1
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logger for memory usage and errors
void log_memory_usage(size_t allocated_bytes) {
    printf("Memory Allocated: %zu bytes\n", allocated_bytes);
}

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // allocation failed
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(size_t num_elements) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Exceeds maximum allowed elements\n");
        return NULL;
    }

    size_t total_size = num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* list = aligned_malloc(total_size + CACHE_LINE_SIZE - 1,
                                                     CACHE_LINE_SIZE);

    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Align to the cache line
    char *aligned_ptr = (char *)(((size_t)(list) + CACHE_LINE_SIZE - 1)
                                 & ~(CACHE_LINE_SIZE - 1));

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)(aligned_ptr + i * sizeof(NFAPI_CRC_INDICATION_PDU_T));

