#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

ListNode* createNode(int RX_UE_INFORMATION_TAG, int RNTI) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return NULL;
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;
    return newNode;
}

ListNode* generateLinkedList(int N) {
    if (N <= 0) return NULL;

    ListNode* head = createNode(rand(), rand());
    if (!head) return NULL;

    ListNode* current = head;
    for (int i = 1; i < N; ++i) {
        ListNode* newNode = createNode(rand(), rand());
        if (!newNode) break;
        current->next = newNode;
        current = newNode;
    }
    return head;
}

void freeLinkedList(ListNode* head) {
    ListNode* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

typedef struct {
    char name[50];
    int color1, color2, font_size1, font_size2;
    double average;
} ThemeConfig;

typedef struct {
    ThemeConfig* config;
    unsigned char* bitmap; // Simulated bitmap
} ThemeCacheEntry;

#define CACHE_SIZE 10

ThemeCacheEntry themeCache[CACHE_SIZE];

unsigned char* getBitmap() {
    static unsigned char bitmap[64] = {0}; // Placeholder for a real bitmap
    return bitmap;
}

void initializeThemeCache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        themeCache[i].config = NULL;
        themeCache[i].bitmap = getBitmap();
    }
}

unsigned char* recycleBitmap(ThemeConfig* config) {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (themeCache[i].config == config || themeCache[i].bitmap == NULL) {
            return themeCache[i].bitmap;
        }
    }
    return NULL;
}

void parseThemesFromFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        ThemeConfig config;
        sscanf(line, "%49[^,],%d,%d,%d,%d",
               config.name,
               &config.color1,
               &config.color2,
               &config.font_size1,
               &config.font_size2);

        config.average = ((double)config.color2 + config.font_size2) / 2.0;

        unsigned char* bitmap = recycleBitmap(&config);
        if (!bitmap) {
            fprintf(stderr, "No available bitmap for recycling\n");
            continue;
        }

        printf("%s,%d,%d,%d,%d,%.1f\n",
               config.name,
               config.color1,
               config.color2,
               config.font_size1,
               config.font_size2,
               config.average);
    }
    fclose(file);
}

int main() {
    srand(time(NULL));

    // Example usage
    int N = 5; // Number of nodes in the linked list
    ListNode* head = generateLinkedList(N);

    // Free the linked list to prevent memory leaks
    freeLinkedList(head);

    // Parse themes from a file and print them
    parseThemesFromFile("themes.txt");

    return 0;
}
```

