    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
    CRCINDICATIONREL8_PDU_T pdu;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10
#define MAX_CAPACITY 1000
#define RETRY_LIMIT 3

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    int reallocations;
    double total_processing_time;
    pthread_mutex_t lock;
} GrowingList;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int validate_crc_tag(CRC_INDICATION_REL8_TAG tag) {
    // Placeholder for checksum verification logic
    return 1; // Assume always valid for demonstration purposes
}

size_t current_time_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (size_t)(ts.tv_sec * 1000000000 + ts.tv_nsec);
}

int grow_list_if_needed(GrowingList *list) {
    if (list->size >= list->capacity && list->capacity < MAX_CAPACITY) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_CAPACITY) {
            new_capacity = MAX_CAPACITY;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            log_error("Memory allocation failed during reallocation.");
            return 0;
        }
        list->data = new_data;
        list->capacity = new_capacity;
        list->reallocations++;
    }
    return 1;
}

void add_crc_indication(GrowingList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    size_t start_time = current_time_ns();

    for (int attempts = 0; attempts < RETRY_LIMIT; ++attempts) {
        if (!grow_list_if_needed(list)) {
            log_error("Failed to grow list after reaching max capacity.");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        if (validate_crc_tag(item.crc_tag)) {
            list->data[list->size++] = item;
            size_t end_time = current_time_ns();
            list->total_processing_time += (end_time - start_time) / 1e6; // Convert to milliseconds
            pthread_mutex_unlock(&list->lock);
            return;
        } else if (attempts < RETRY_LIMIT - 1) {
            log_error("CRC tag validation failed, retrying...");
        }
    }

    log_error("Failed to add item after maximum retry attempts.");
    pthread_mutex_unlock(&list->lock);
}

void initialize_list(GrowingList *list) {
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_CAPACITY);
    if (!list->data) {
        log_error("Initial memory allocation failed.");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->reallocations = 0;
    list->total_processing_time = 0.0;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(GrowingList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

// Callback function example
void on_threshold_approach(size_t current_size, size_t threshold) {
    if (current_size >= threshold) {
        printf("Approaching maximum capacity. Current: %zu\n", current_size);
    }
}

int main() {
    GrowingList list;
    initialize_list(&list);

    NFAPI_CRC_INDICATION_PDU_T item = {12345, 6789, {{0x01, 0x02, 0x03, 0x04}}, {42}};

    add_crc_indication(&list, item);
    on_threshold_approach(list.size, MAX_CAPACITY * 0.8);

    // Add more items as needed...

    free_list(&list);

    printf("Total reallocations: %d\n", list.reallocations);
    printf("Average processing time per element (ms): %.2f\n",
           list.total_processing_time / list.size);

    return 0;
}
