Node* create_linked_list(int num_records, NFPAPI_TX_POWER_LEVEL_RECORD_T *records) {
    if (num_records <= 0 || records == NULL) return NULL;

    Node *head = (Node *)malloc(sizeof(Node));
    if (!head) return NULL;

    head->data = records[0];
    head->next = NULL;
    Node *current = head;

    for (int i = 1; i < num_records; ++i) {
        Node *new_node = (Node *)malloc(sizeof(Node));
        if (!new_node) {
            // Free previously allocated nodes
            while (head != current) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            free(head);
            return NULL;  // Memory allocation failed
        }

        new_node->data = records[i];
        new_node->next = NULL;
        current->next = new_node;
        current = new_node;
    }

    return head;
}

