#define INITIAL_CAPACITY 10

typedef struct {
    int RNTI;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    size_t successful_allocations;
    size_t failed_allocations;
    pthread_mutex_t lock;
} PduList;

PduList* create_pdu_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->successful_allocations = 0;
    list->failed_allocations = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int resize_pdu_list(PduList* list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    list->data = new_data;
    list->capacity = new_capacity;
    return 0;
}

int add_pdu_to_list(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    if (list->size >= list->capacity) {
        int result = resize_pdu_list(list);
        if (result != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->data[list->size++] = pdu;
    list->successful_allocations++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void clean_up_pdu_list(PduList* list) {
    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int generate_random_crcflag() {
    srand(time(NULL));
    return rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int rx_ue_tag, int rnti) {
