#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <stdio.h>

// Define a structure for RX_UE_INFORMATION_TAG (dummy implementation)
typedef struct {
    uint32_t rnti;
} RX_UE_INFORMATION_TAG;

// Define the CRC_INDICATION_REL8_TAG structure
typedef struct {
    int crcFlag;  // Assume this is an integer value
} CRC_INDICATION_REL8_TAG;

// Define NFAPI_CRC_INDICATION_PDU_T structure with necessary fields
typedef struct NFAPI_CRC_INDICATION_PDU_T_ {
    RX_UE_INFORMATION_TAG ueInfo;
    uint32_t rnti;
    uint64_t packetId;
    time_t timestamp;
    CRC_INDICATION_REL8_TAG crcRel8Tag;
    struct NFAPI_CRC_INDICATION_PDU_T_* next;  // For linked list management
} NFAPI_CRC_INDICATION_PDU_T;

// Node for maintaining unique RNTI values using a set (using mutex here)
typedef struct {
    uint32_t rnti;
    struct Node* next;
} RntiNode;

typedef struct {
    RntiNode* head;
    pthread_mutex_t lock;
} RntiSet;

// Linked list header for dynamic NFAPI_CRC_INDICATION_PDU_T management
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_rwlock_t rwlock;  // Read-write lock for concurrent access
    RntiSet rntiset;
    uint64_t lastPacketIdTimeWindowStart;
} DynamicList;

// Function prototypes
void initDynamicList(DynamicList* list);
NFAPI_CRC_INDICATION_PDU_T* addOrUpdatePdu(DynamicList* list, RX_UE_INFORMATION_TAG ueInfo, uint32_t newRnti);
static int isUniqueRNTI(DynamicList* list, uint32_t rnti);
static NFAPI_CRC_INDICATION_PDU_T* findPacketById(DynamicList* list, uint64_t packetId);
static void freePduList(NFAPI_CRC_INDICATION_PDU_T* head);

// Initialize the dynamic list structure
void initDynamicList(DynamicList* list) {
    pthread_rwlock_init(&list->rwlock, NULL);
    list->head = NULL;

    // Initialize RNTI set
    list->rntiset.head = NULL;
    pthread_mutex_init(&list->rntiset.lock, NULL);

    // Set time window start (e.g., current time)
    time_t currentTime = time(NULL);
    list->lastPacketIdTimeWindowStart = currentTime - 60;  // e.g., last 60 seconds
}

// Add or update an NFAPI_CRC_INDICATION_PDU_T structure in the dynamic list
NFAPI_CRC_INDICATION_PDU_T* addOrUpdatePdu(DynamicList* list, RX_UE_INFORMATION_TAG ueInfo, uint32_t newRnti) {
    pthread_rwlock_wrlock(&list->rwlock);

    if (!isUniqueRNTI(list, newRnti)) {
        fprintf(stderr, "Error: Duplicate RNTI value detected.\n");
        pthread_rwlock_unlock(&list->rwlock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_rwlock_unlock(&list->rwlock);
        return NULL;
    }

    // Fill in the structure with provided data and additional fields
    pdu->ueInfo = ueInfo;
    pdu->rnti = newRnti;
    pdu->packetId = (uint64_t)time(NULL);  // For simplicity, using current time as packet ID
    pdu->timestamp = time(NULL);

    srand((unsigned int)pdu->timestamp);
    pdu->crcRel8Tag.crcFlag = rand() % 2;  // Randomly set CRCFLAG to 0 or 1

    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;

    while (current) {
        if (current->packetId == pdu->packetId && 
            current->timestamp >= list->lastPacketIdTimeWindowStart &&
            current->timestamp <= time(NULL)) {

            // Replace old node
            prev ? prev->next = pdu : list->head = pdu;
            free(current);
            pthread_rwlock_unlock(&list->rwlock);
            return pdu;
        }

        prev = current;
        current = current->next;
    }

    if (prev) {
        prev->next = pdu;  // Append to the end
    } else {
        list->head = pdu;  // If head is NULL, set new node as head
    }

    pthread_rwlock_unlock(&list->rwlock);

    return pdu;
}

// Check if RNTI is unique within the managed list using a simple linked list and mutex lock
static int isUniqueRNTI(DynamicList* list, uint32_t rnti) {
    pthread_mutex_lock(&list->rntiset.lock);

    RntiNode* current = list->rntiset.head;
    while (current) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->rntiset.lock);
            return 0;  // Not unique
        }
        current = current->next;
    }

    RntiNode* newNode = (RntiNode*)malloc(sizeof(RntiNode));
    if (!newNode) {
        fprintf(stderr, "Error: Memory allocation failed for RNTI node.\n");
        pthread_mutex_unlock(&list->rntiset.lock);
        return 0;  // Consider this as not unique due to failure
    }

    newNode->rnti = rnti;
    newNode->next = list->rntiset.head;
    list->rntiset.head = newNode;

    pthread_mutex_unlock(&list->rntiset.lock);

    return 1;  // Unique
}

// Find a PDU by packetId within the time window to ensure uniqueness
static NFAPI_CRC_INDICATION_PDU_T* findPacketById(DynamicList* list, uint64_t packetId) {
    pthread_rwlock_rdlock(&list->rwlock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        if (current->packetId == packetId &&
            current->timestamp >= list->lastPacketIdTimeWindowStart &&
            current->timestamp <= time(NULL)) {

            pthread_rwlock_unlock(&list->rwlock);
            return current;  // Found
        }

        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);

    return NULL;  // Not found
}

// Free the entire linked list of PDU structures
static void freePduList(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

// Function to clean up and free resources
void destroyDynamicList(DynamicList* list) {
    pthread_rwlock_wrlock(&list->rwlock);

    RntiNode* rntiCurrent = list->rntiset.head;

    while (rntiCurrent) {
        RntiNode* nextRNTI = rntiCurrent->next;
        free(rntiCurrent);
        rntiCurrent = nextRNTI;
    }

    pthread_mutex_destroy(&list->rntiset.lock);

    freePduList(list->head);
    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
}
