// Function prototypes
PhyRxStatsManager* create_manager(size_t initial_capacity);
void destroy_manager(PhyRxStatsManager* manager);
int add_stats_pdu(PhyRxStatsManager* manager, PHY_RX_STATS_PDU_T pdu);
int flush_stats_to_persistent_storage(PhyRxStatsManager* manager);
void report_system_health(const PhyRxStatsManager* manager);

// Function implementations
PhyRxStatsManager* create_manager(size_t initial_capacity) {
    PhyRxStatsManager* manager = (PhyRxStatsManager*)malloc(sizeof(PhyRxStatsManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->elements = (PHY_RX_STATS_PDU_T*)calloc(manager->capacity, sizeof(PHY_RX_STATS_PDU_T));

    return manager;
}

void destroy_manager(PhyRxStatsManager* manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->elements);
    free(manager);
}

int add_stats_pdu(PhyRxStatsManager* manager, PHY_RX_STATS_PDU_T pdu) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        PHY_RX_STATS_PDU_T* new_elements = (PHY_RX_STATS_PDU_T*)realloc(manager->elements, new_capacity * sizeof(PHY_RX_STATS_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }

        manager->capacity = new_capacity;
        manager->elements = new_elements;
    }

    manager->elements[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int flush_stats_to_persistent_storage(PhyRxStatsManager* manager) {
    // Simulate flushing to persistent storage and clearing the buffer.
    pthread_mutex_lock(&manager->lock);

