    unsigned char encryptedBuffer[4096 + EVP_MAX_BLOCK_LENGTH];
    int len;
    while (1) {
        size_t bytesRead = fread(buffer, 1, sizeof(buffer), inFile);
        if (bytesRead == 0) break;

        if (EVP_EncryptUpdate(ctx, encryptedBuffer, &len, buffer, bytesRead) != 1) {
            fclose(inFile);
            fclose(outFile);
            EVP_CIPHER_CTX_free(ctx);
            return 1;
        }
        fwrite(encryptedBuffer, 1, len, outFile);
    }

    int finalLen;
    if (EVP_EncryptFinal_ex(ctx, encryptedBuffer, &finalLen) != 1) {
        fclose(inFile);
        fclose(outFile);
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }
    fwrite(encryptedBuffer, 1, finalLen, outFile);

    fclose(inFile);
    fclose(outFile);
    EVP_CIPHER_CTX_free(ctx);

    return 0; // Success
}
