    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t last_compressed_size;
    unsigned long last_compression_time_ms;
} StatsManager;

static StatsManager stats_manager = {0};

void init_stats_manager() {
    stats_manager.records = (PHY_RX_STATS_RECORD_T *)aligned_alloc(CACHE_LINE_SIZE, sizeof(PHY_RX_STATS_RECORD_T) * MAX_ELEMENTS);
    if (!stats_manager.records) {
        fprintf(stderr, "Failed to allocate memory for statistics records\n");
        exit(EXIT_FAILURE);
    }
    stats_manager.capacity = MAX_ELEMENTS;
    stats_manager.count = 0;
    pthread_mutex_init(&stats_manager.lock, NULL);
}

void log_memory_usage() {
    size_t used_bytes = stats_manager.count * sizeof(PHY_RX_STATS_RECORD_T);
    printf("Memory Usage: %zu bytes / %zu bytes\n", used_bytes, stats_manager.capacity * sizeof(PHY_RX_STATS_RECORD_T));
}

void compress_records() {
    // Placeholder for compression logic
    pthread_mutex_lock(&stats_manager.lock);

    if (stats_manager.count > 0) {
        size_t new_size = (stats_manager.last_compressed_size + stats_manager.count) / 2;
        PHY_RX_STATS_RECORD_T *compressed_data = (PHY_RX_STATS_RECORD_T *)aligned_alloc(CACHE_LINE_SIZE, sizeof(PHY_RX_STATS_RECORD_T) * new_size);

        if (!compressed_data) {
            fprintf(stderr, "Compression memory allocation failed\n");
            pthread_mutex_unlock(&stats_manager.lock);
            return;
        }

        size_t records_to_compress = (new_size < stats_manager.count) ? new_size : stats_manager.count;
        memcpy(compressed_data, stats_manager.records, sizeof(PHY_RX_STATS_RECORD_T) * records_to_compress);

        free(stats_manager.records);
        stats_manager.records = compressed_data;
        stats_manager.capacity = new_size;
        stats_manager.count = records_to_compress;
        stats_manager.last_compressed_size = new_size;

        log_memory_usage();
    }

    pthread_mutex_unlock(&stats_manager.lock);
}

void add_record(PHY_RX_STATS_RECORD_T record) {
    if (stats_manager.count >= stats_manager.capacity) {
        fprintf(stderr, "Max capacity reached\n");
        return;
    }

    pthread_mutex_lock(&stats_manager.lock);

    stats_manager.records[stats_manager.count++] = record;

    unsigned long current_time_ms = 0; // Replace with actual time retrieval logic
    if (current_time_ms - stats_manager.last_compression_time_ms >= COMPRESSION_INTERVAL_MS) {
        compress_records();
        stats_manager.last_compression_time_ms = current_time_ms;
    }

    pthread_mutex_unlock(&stats_manager.lock);
}

void cleanup_stats_manager() {
    pthread_mutex_lock(&stats_manager.lock);
    if (stats_manager.records) {
        free(stats_manager.records);
        stats_manager.records = NULL;
    }
    pthread_mutex_unlock(&stats_manager.lock);
    pthread_mutex_destroy(&stats_manager.lock);
}

// Example usage in a multithreaded environment
void *process_frequency_band(void *arg) {
    // Simulate processing
    for (int i = 0; i < 100; ++i) {
        PHY_RX_STATS_RECORD_T record = { .signal_strength = i, .noise_level = i % 256 };
        add_record(record);
    }
    return NULL;
}

int main() {
    init_stats_manager();

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, process_frequency_band, NULL);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_stats_manager();
    return 0;
}
