// Adaptive buffer pool for managing memory efficiently
#define INITIAL_POOL_SIZE 10

typedef struct {
    size_t frame_size;
    unsigned char *buffer_pool[INITIAL_POOL_SIZE];
    size_t current_allocation;
} BUFFER_POOL;

BUFFER_POOL* create_buffer_pool(size_t initial_frame_size) {
    BUFFER_POOL *pool = malloc(sizeof(BUFFER_POOL));
    pool->frame_size = initial_frame_size;
    pool->current_allocation = 0;

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        pool->buffer_pool[i] = malloc(pool->frame_size);
        if (!pool->buffer_pool[i]) {
            // Handle allocation failure
            fprintf(stderr, "Buffer allocation failed\n");
            exit(1);
        }
    }

    return pool;
}

void free_buffer_pool(BUFFER_POOL *pool) {
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        if (pool->buffer_pool[i]) {
            free(pool->buffer_pool[i]);
        }
    }
    free(pool);
}

// Function to adjust the buffer pool size dynamically
void resize_buffer_pool(BUFFER_POOL *pool, size_t new_frame_size) {
    unsigned char **new_pool = realloc(pool->buffer_pool, sizeof(unsigned char*) * INITIAL_POOL_SIZE);

    if (!new_pool) {
        // Handle reallocation failure
        fprintf(stderr, "Buffer reallocation failed\n");
        exit(1);
    }

    pool->buffer_pool = new_pool;
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        if (pool->frame_size != new_frame_size) {
            unsigned char *new_buffer = realloc(pool->buffer_pool[i], new_frame_size);
            if (!new_buffer) {
                // Handle reallocation failure
                fprintf(stderr, "Buffer resizing failed\n");
                exit(1);
            }
            pool->buffer_pool[i] = new_buffer;
        }
    }

    pool->frame_size = new_frame_size;
}

// Function to initialize and configure MAC layer with frames
void init_mac_layer(MAC_FRAME *frames, size_t frame_count, BUFFER_POOL *pool) {
    for (size_t i = 0; i < frame_count; ++i) {
        // Configure header
        memset(&frames[i].header.dest_addr, 0xFF, sizeof(frames[i].header.dest_addr)); // Example: Broadcast address
        memcpy(&frames[i].header.src_addr, "\x00\x1A\x2B\x3C\x4D\x5E", sizeof(frames[i].header.src_addr)); // Example MAC address
        frames[i].header.ethertype = htons(0x0800); // Example Ethertype

        // Allocate payload from buffer pool
        if (pool->current_allocation < INITIAL_POOL_SIZE) {
            frames[i].payload.data = pool->buffer_pool[pool->current_allocation++];
            frames[i].payload.length = pool->frame_size;
        } else {
            fprintf(stderr, "Buffer pool exhausted\n");
            exit(1);
        }

        // Initialize L2 context
        frames[i].l2_context.context_id = i;  // Example context ID

        // Dynamic frame size adjustment logic (simplified example)
        if ((i % 5) == 0) { // Simulate a condition to resize buffers every 5 frames
            resize_buffer_pool(pool, pool->frame_size + 64); // Increase buffer size by 64 bytes as an example
        }
    }
}

// Example usage
int main() {
    MAC_FRAME *frames = malloc(20 * sizeof(MAC_FRAME)); // Allocate space for 20 frames
    BUFFER_POOL *pool = create_buffer_pool(128); // Initial frame size of 128 bytes

    init_mac_layer(frames, 20, pool);

    free_buffer_pool(pool);
    free(frames);

    return 0;
}
