#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MAX_RNTI 10000

typedef struct {
    uint8_t rnti;
    // Other MAC_HEADER fields...
} MAC_HEADER;

typedef struct {
    // MAC_PAYLOAD fields...
} MAC_PAYLOAD;

typedef struct {
    // L2_CONTEXT fields...
} L2_CONTEXT;

typedef struct mac_frame {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    L2_CONTEXT context;
    struct mac_frame *next;
} MAC_FRAME;

typedef enum { HEAP, STACK } AllocationType;

// Linked list head
MAC_FRAME* mac_list_head = NULL;

int validate_mac_frame(MAC_FRAME *frame) {
    // Perform validation logic on the frame
    if (frame == NULL || frame->header.rnti > MAX_RNTI) return 0;
    return 1;
}

void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

void log_warning(const char *message) {
    fprintf(stderr, "WARNING: %s\n", message);
}

MAC_FRAME* allocate_mac_frame(AllocationType type, MAC_HEADER header, MAC_PAYLOAD payload, L2_CONTEXT context) {
    if (type == HEAP) {
        return (MAC_FRAME*)malloc(sizeof(MAC_FRAME));
    } else { // STACK
        // Ensure stack allocation doesn't exceed typical limits; simulate with static or auto array
        MAC_FRAME frame;
        memcpy(&frame.header, &header, sizeof(header));
        memcpy(&frame.payload, &payload, sizeof(payload));
        memcpy(&frame.context, &context, sizeof(context));
        return &frame;
    }
}

void free_mac_list(MAC_FRAME *head) {
    while (head != NULL) {
        MAC_FRAME *temp = head;
        head = head->next;
        if (malloc_usable_size(temp) > 0) { // Check if heap allocated
            free(temp);
        }
    }
}

int insert_sorted_mac_frame(AllocationType type, MAC_HEADER header, MAC_PAYLOAD payload, L2_CONTEXT context) {
    MAC_FRAME *new_frame = allocate_mac_frame(type, header, payload, context);

    if (new_frame == NULL || !validate_mac_frame(new_frame)) {
        free_mac_list(mac_list_head);
        log_error("Invalid frame allocation or validation failed.");
        return -1;
    }

    // Check for RNTI uniqueness
    MAC_FRAME *current = mac_list_head;
    while (current != NULL) {
        if (current->header.rnti == new_frame->header.rnti) {
            free_mac_list(mac_list_head);
            log_error("Duplicate RNTI detected.");
            return -1;
        }
        current = current->next;
    }

    // Insert in sorted order
    MAC_FRAME **tracer = &mac_list_head;
    while (*tracer != NULL && (*tracer)->header.rnti < new_frame->header.rnti) {
        tracer = &(*tracer)->next;
    }

    new_frame->next = *tracer;
    *tracer = new_frame;

    return 0;
}

int initialize_mac_layer(int num_frames, AllocationType type) {
    if (num_frames > MAX_RNTI) {
        log_error("Requested number of structures exceeds the maximum limit.");
        return -1;
    }

    for (int i = 0; i < num_frames; ++i) {
        MAC_HEADER header = {.rnti = rand() % MAX_RNTI};
        MAC_PAYLOAD payload;
        L2_CONTEXT context;

        int status = insert_sorted_mac_frame(type, header, payload, context);
        if (status != 0) return -1;
    }

    return 0;
}

int main() {
    AllocationType type = HEAP; // or STACK based on configuration
    int num_frames = 5000;

    if (initialize_mac_layer(num_frames, type) != 0) {
        log_error("Failed to initialize MAC layer.");
    } else {
        printf("MAC Layer initialized successfully.\n");
    }

    free_mac_list(mac_list_head);
    return 0;
}
