// Initialize and configure network interfaces
void setup_network_interfaces(NetworkManager* manager) {
    for (int i = 0; i < manager->active_interfaces; ++i) {
        initialize_interface(&manager->interfaces[i], "00:11:22:33:44:55");
        adjust_buffer_size(&manager->interfaces[i]);
        apply_qos_requirements(&manager->interfaces[i]);

        if (pthread_create(&manager->threads[i], NULL, manage_traffic, &manager->interfaces[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }
}

void initialize_interface(NetworkInterface* interface, const char* mac_address) {
