#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <time.h>

// Define constants for maximum size and valid ranges.
#define MAX_ARRAY_SIZE 1000
#define VALID_RX_UE_TAG_MIN 1
#define VALID_RX_UE_TAG_MAX 1000
#define VALID_RNTI_MIN 1
#define VALID_RNTI_MAX 500

// Define the NFAPI_CRC_INDICATION_PDU_T structure.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG; // Randomly set during initialization.
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logger function to handle different verbosity levels.
void log_message(int level, const char* message) {
    static int current_log_level = 1;
    if (level <= current_log_level) {
        printf("LOG [%d]: %s\n", level, message);
    }
}

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T** manage_nfa_array(size_t *size);
void resize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *current_size, int new_size);
int validate_tag(int tag);
int validate_rnti(int rnti);

// Manage dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures.
NFAPI_CRC_INDICATION_PDU_T** manage_nfa_array(size_t *size) {
    if (size == NULL) return NULL;

    // Initial size and maximum size constraint.
    const int initial_size = 10;
    NFAPI_CRC_INDICATION_PDU_T **array = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        log_message(1, "Memory allocation failed for array.");
        return NULL;
    }

    *size = 0;

    // Initialize array with random values.
    srand(time(NULL)); // Seed the random number generator.

    for (int i = 0; i < initial_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_message(1, "Memory allocation failed for PDU.");
            // Free previously allocated PDUs.
            while (*size > 0) free(array[--(*size)]);
            free(array);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % (VALID_RX_UE_TAG_MAX - VALID_RX_UE_TAG_MIN + 1) + VALID_RX_UE_TAG_MIN;
        pdu->RNTI = rand() % (VALID_RNTI_MAX - VALID_RNTI_MIN + 1) + VALID_RNTI_MIN;

        if (!validate_tag(pdu->RX_UE_INFORMATION_TAG)) {
            log_message(2, "Invalid RX_UE_INFORMATION_TAG.");
            free(pdu);
            continue;
        }

        if (!validate_rnti(pdu->RNTI)) {
            log_message(2, "Invalid RNTI.");
            free(pdu);
            continue;
        }

        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        array[(*size)++] = pdu;

        // Check if we need to resize.
        if (*size >= initial_size) {
            int new_size = (initial_size < MAX_ARRAY_SIZE) ? initial_size * 2 : MAX_ARRAY_SIZE;
            resize_array(array, size, new_size);
            if (!array) return NULL; // Handle memory allocation failure in resizing.
        }
    }

    log_message(3, "Array initialized successfully.");
    return array;
}

// Resize the array dynamically.
void resize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *current_size, int new_size) {
    NFAPI_CRC_INDICATION_PDU_T** temp = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!temp && new_size > 0) {
        log_message(1, "Memory reallocation failed.");
        free(*array);
        *array = NULL;
    } else {
        *array = temp;
    }
}

// Validate RX_UE_INFORMATION_TAG value.
int validate_tag(int tag) {
    return (tag >= VALID_RX_UE_TAG_MIN && tag <= VALID_RX_UE_TAG_MAX);
}

// Validate RNTI value.
int validate_rnti(int rnti) {
    return (rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX);
}

// Function to serialize the array into a binary format.
void* serialize_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t size, size_t *serialized_size) {
    if (!array || !serialized_size) return NULL;

    // Calculate size required for serialization.
    size_t buf_size = sizeof(size_t); // Store array size first.
    for (size_t i = 0; i < size; ++i) {
        buf_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    char *buffer = malloc(buf_size);
    if (!buffer) {
        log_message(1, "Memory allocation failed for serialization buffer.");
        return NULL;
    }

    // Write array size.
    memcpy(buffer, &size, sizeof(size_t));

    // Write each PDU structure.
    char* offset_ptr = buffer + sizeof(size_t);
    for (size_t i = 0; i < size; ++i) {
        memcpy(offset_ptr, array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        offset_ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    *serialized_size = buf_size;
    log_message(3, "Serialization successful.");
    return buffer;
}

// Function to deserialize the binary format back into an array.
NFAPI_CRC_INDICATION_PDU_T** deserialize_array(const void* data, size_t *size) {
    if (!data || !size) return NULL;

    const char *buffer = (const char*)data;

    // Read array size.
    size_t buffer_size;
    memcpy(&buffer_size, buffer, sizeof(size_t));
    *size = buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    NFAPI_CRC_INDICATION_PDU_T** array = malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        log_message(1, "Memory allocation failed for deserialized array.");
        return NULL;
    }

    // Read each PDU structure.
    const char* offset_ptr = buffer + sizeof(size_t);
    for (size_t i = 0; i < *size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_message(1, "Memory allocation failed for deserialized PDU.");
            // Free previously allocated PDUs.
            while (i > 0) free(array[--i]);
            free(array);
            return NULL;
        }

        memcpy(pdu, offset_ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array[i] = pdu;

        offset_ptr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    log_message(3, "Deserialization successful.");
    return array;
}

// Main function to demonstrate usage.
int main() {
    size_t current_size;
    NFAPI_CRC_INDICATION_PDU_T** nfa_array = manage_nfa_array(&current_size);

    if (nfa_array) {
        size_t serialized_size;
        void* serialized_data = serialize_array(nfa_array, current_size, &serialized_size);

        if (serialized_data) {
            NFAPI_CRC_INDICATION_PDU_T** deserialized_array = deserialize_array(serialized_data, &current_size);

            // Cleanup
            free(serialized_data);
            for (size_t i = 0; i < current_size; ++i) {
                free(nfa_array[i]);
            }
            free(nfa_array);

            if (deserialized_array) {
                for (size_t i = 0; i < current_size; ++i) {
                    free(deserialized_array[i]);
                }
                free(deserialized_array);
            }
        }
    }

    return 0;
}
