// Function to allocate memory for the array
NFAPI_CRC_INDICATION_PDU_T* create_array(size_t *size) {
    if (*size > MAX_ELEMENTS) {
        fprintf(stderr, "Exceeded maximum number of elements.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }
    memset(array, 0, *size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return array;
}

// Function to add a new element
int add_element(NFAPI_CRC_INDICATION_PDU_T* array, size_t *current_size, unsigned int rx_tag, unsigned int rnti) {
    pthread_mutex_lock(&mutex);

    if (!validate_inputs(rx_tag, rnti)) {
        fprintf(stderr, "Invalid inputs.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (*current_size >= MAX_ELEMENTS) {
        fprintf(stderr, "Array is full.\n");
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    array[*current_size].RX_UE_INFORMATION_TAG = rx_tag;
    array[*current_size].RNTI = rnti;
    CRC_INDICATION_REL8_TAG* crc_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!crc_tag) {
        perror("Memory allocation failed for CRC tag");
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    srand(time(NULL)); // Seed random number generator
    crc_tag->CRCFLAG = rand() % 2; // Randomly set to 0 or 1

    array[*current_size].indication_rel8_tag = crc_tag;
    (*current_size)++;

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to serialize the array
size_t serialize_array(const NFAPI_CRC_INDICATION_PDU_T* array, size_t current_size, unsigned char **buffer) {
    size_t total_size = current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    *buffer = (unsigned char*)malloc(total_size);
    if (!*buffer) {
        perror("Memory allocation failed for serialization");
        return 0;
    }

    memcpy(*buffer, array, total_size);
    return total_size;
}

// Function to deserialize the buffer back into an array
NFAPI_CRC_INDICATION_PDU_T* deserialize_array(const unsigned char *buffer, size_t buffer_size, size_t *current_size) {
    NFAPI_CRC_INDICATION_PDU_T* array = create_array(current_size);
    if (!array) return NULL;

    memcpy(array, buffer, buffer_size);
    return array;
}

// Cleanup function to free allocated memory
void cleanup_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t current_size) {
    for (size_t i = 0; i < current_size; ++i) {
        if (array[i].indication_rel8_tag) {
            free(array[i].indication_rel8_tag);
        }
    }
    free(array);
}

int main() {
