        NFAPI_CRC_INDICATION_PDU_T* deserialized_array = deserialize_array(serialized_data, serialized_size, &current_size);

        cleanup_array(array, current_size);
        free(serialized_data);
        cleanup_array(deserialized_array, current_size);
    }

