// A function to manage the configuration directory based on a provided name and version.
fn manage_config_directory(config_name: &str, version: &str) -> Result<(), Box<dyn std::error::Error>> {
    let config_dir_var = "CONFIG_DIR";
    let mut config_path = env::var_os(config_dir_var).map(PathBuf::from);

    if config_path.is_none() || !config_path.as_ref().unwrap().exists() {
        let new_config_path = PathBuf::from(format!("./configs/{}", config_name));

        // Ensure the base config directory exists.
        fs::create_dir_all(&new_config_path)?;

        config_path = Some(new_config_path);
    }

    // Check for reserved paths
    if config_path.as_ref().unwrap().components().any(|c| c == std::path::Component::RootDir || c == std::path::Component::CurDir) {
        return Err("Invalid CONFIG_DIR path: reserved directory".into());
    }

    let versioned_dir = config_path.unwrap().join(format!("version_{}", version));

    if !versioned_dir.exists() {
        // Attempt to create the versioned subdirectory.
        fs::create_dir_all(&versioned_dir)?;
    }

    env::set_var(config_dir_var, config_path.as_ref().unwrap().to_str().unwrap());

    // Simulate fetching latest version info
    let cached_version = Arc::new(Mutex::new(fetch_latest_version()?));

    log_message(&format!("Config directory set to: {:?}", config_path.unwrap()));

    Ok(())
}

fn main() {
    match manage_config_directory("app_config", "1.0") {
        Ok(_) => println!("Configuration managed successfully."),
        Err(e) => eprintln!("Error managing configuration: {}", e),
    }
}
