bool is_valid_rx_ue_info(RX_UE_INFORMATION_TAG tag, RX_UE_INFORMATION_TAG* array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].valid_range_min <= tag.valid_range_min &&
            tag.valid_range_max <= array[i].valid_range_max) {
            return false;
        }
    }
    return true;
}

bool is_valid_rnti(RNTI rnti, RNTI* array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].rnti_value == rnti.rnti_value) {
