    if (rand() % 2 == 0) {
        *tag = (RX_UE_INFORMATION_TAG){.valid_range_min = rand() % 100, .valid_range_max = rand() % 200};
        return true;
    }
    return false;
}

void retry_fetch_rx_ue_info(RX_UE_INFORMATION_TAG* tag) {
    int retries = 0;
    while (retries < RETRY_LIMIT && !fetch_rx_ue_info_from_api(tag)) {
        log_message("API fetch failed, retrying...", 1);
        ++retries;
    }
}

void initialize_array_manager(NFAPI_ARRAY_MANAGER* manager) {
    manager->array = NULL;
    manager->size = 0;
    manager->capacity = 0;
}

bool resize_array(NFAPI_ARRAY_MANAGER* manager) {
    size_t new_capacity = manager->capacity == 0 ? 16 : manager->capacity * 2;
    if (new_capacity > MAX_ARRAY_SIZE) return false;

    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_message("Memory allocation failed during resize", 1);
        return false;
    }

    manager->array = new_array;
    manager->capacity = new_capacity;
    return true;
}

bool add_pdu_to_manager(NFAPI_ARRAY_MANAGER* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (manager->size == manager->capacity && !resize_array(manager)) {
        log_message("Failed to resize array", 1);
        return false;
    }

    RX_UE_INFORMATION_TAG* rx_ue_infos = malloc(manager->size * sizeof(RX_UE_INFORMATION_TAG));
    RNTI* rntis = malloc(manager->size * sizeof(RNTI));

    for (size_t i = 0; i < manager->size; ++i) {
        memcpy(&rx_ue_infos[i], &manager->array[i].rx_ue_info, sizeof(RX_UE_INFORMATION_TAG));
        rntis[i] = manager->array[i].rnti;
    }

    if (!is_valid_rx_ue_info(pdu.rx_ue_info, rx_ue_infos, manager->size) ||
        !is_valid_rnti(pdu.rnti, rntis, manager->size)) {
        free(rx_ue_infos);
        free(rntis);
        log_message("Validation failed for PDU", 1);
        return false;
    }

    free(rx_ue_infos);
    free(rntis);

    manager->array[manager->size++] = pdu;

    return true;
}

void serialize_array(const NFAPI_ARRAY_MANAGER* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization", 1);
        return;
    }

    fwrite(&manager->size, sizeof(size_t), 1, file);
    fwrite(manager->array, manager->size * sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);

    fclose(file);
}

bool deserialize_array(NFAPI_ARRAY_MANAGER* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization", 1);
        return false;
    }

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    if (resize_array(manager) && manager->capacity < size) {
        free(manager->array);
        manager->array = NULL;
        manager->size = 0;
        manager->capacity = 0;
        log_message("Deserialization failed due to insufficient capacity", 1);
        fclose(file);
        return false;
    }

    fread(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);

    manager->size = size;

    fclose(file);
    return true;
}

NFAPI_ARRAY_MANAGER* filter_array(const NFAPI_ARRAY_MANAGER* manager, bool (*filter_func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    NFAPI_ARRAY_MANAGER* filtered_manager = malloc(sizeof(NFAPI_ARRAY_MANAGER));
    initialize_array_manager(filtered_manager);

    for (size_t i = 0; i < manager->size; ++i) {
        if (filter_func(&manager->array[i])) {
            if (!add_pdu_to_manager(filtered_manager, manager->array[i])) {
                free(filtered_manager);
                log_message("Failed to add PDU to filtered array", 1);
                return NULL;
            }
        }
    }

    return filtered_manager;
}

bool filter_by_rnti(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    return pdu->rnti.rnti_value % 2 == 0; // Example filter
}

void free_array_manager(NFAPI_ARRAY_MANAGER* manager) {
    if (manager->array) {
        free(manager->array);
    }
    free(manager);
}

int main() {
    NFAPI_ARRAY_MANAGER manager;
    initialize_array_manager(&manager);

    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        retry_fetch_rx_ue_info(&pdu.rx_ue_info);
