// Custom allocator for efficient memory management in constrained environments
NFAPI_CRC_INDICATION_PDU_T* custom_allocate(size_t size) {
    pthread_mutex_lock(&memory_manager.lock);

    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_struct || memory_manager.used_memory + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_LIMIT) {
        log_message("Memory allocation failed or exceeded limit.");
        pthread_mutex_unlock(&memory_manager.lock);
        return NULL;
    }

    // Add new structure to the beginning of linked list
    new_struct->next = memory_manager.head;
    memory_manager.head = new_struct;

    memory_manager.used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&memory_manager.lock);
    log_message("Allocated a new NFAPI_CRC_INDICATION_PDU_T structure.");

    return new_struct;
}

// Custom deallocator
void custom_free(NFAPI_CRC_INDICATION_PDU_T *struct_to_free) {
    if (!struct_to_free) return;

    pthread_mutex_lock(&memory_manager.lock);

    // Remove the structure from linked list
    NFAPI_CRC_INDICATION_PDU_T **curr = &memory_manager.head;
    while (*curr && *curr != struct_to_free) {
        curr = &(*curr)->next;
    }
    if (*curr) {
        *curr = struct_to_free->next;
        memory_manager.used_memory -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        free(struct_to_free);
        log_message("Freed an NFAPI_CRC_INDICATION_PDU_T structure.");
    }

    pthread_mutex_unlock(&memory_manager.lock);
}

