        if ((clock() - start_time) > ts.tv_sec * CLOCKS_PER_SEC + ts.tv_nsec / (CLOCKS_PER_SEC/1000000)) {
            log_message("Exceeded maximum latency, yielding control.");
            sched_yield(); // Yield the processor to maintain real-time constraints
        }

        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

        array[i].timestamp = time(NULL);
    }

    return array;
}

// Function to free the allocated structures
void free_structures(NFAPI_CRC_INDICATION_PDU_T *array, size_t n) {
