void destroy_mac_rx_dynamic_array(MAC_RX_INDYNAMIC_ARRAY *dynamic_array);
int add_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, const MAC_RX_INDICATION *indication);
int remove_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, unsigned int PDCP_SN);
MAC_RX_INDICATION* find_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, unsigned int PDCP_SN);
void extend_dynamic_array(MAC_RX_INDYNAMIC_ARRAY *dynamic_array);
int filter_mac_rx_indications(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, 
                              void (*filter_func)(const MAC_RX_INDICATION*, int*), int *filtered_count);

// Function implementations
MAC_RX_INDYNAMIC_ARRAY* create_mac_rx_dynamic_array(CustomAllocator *allocator, size_t initial_capacity) {
    if (!allocator || initial_capacity == 0) return NULL;

    MAC_RX_INDYNAMIC_ARRAY *dynamic_array = (MAC_RX_INDYNAMIC_ARRAY *)malloc(sizeof(MAC_RX_INDYNAMIC_ARRAY));
    if (!dynamic_array) return NULL;

    dynamic_array->array = (MAC_RX_INDICATION*) allocator->memory_pool;
    dynamic_array->capacity = initial_capacity;
    dynamic_array->count = 0;
    pthread_rwlock_init(&dynamic_array->rwlock, NULL);
    dynamic_array->allocator = *allocator;
    dynamic_array->extra_fields = NULL;

    return dynamic_array;
}

void destroy_mac_rx_dynamic_array(MAC_RX_INDYNAMIC_ARRAY *dynamic_array) {
    if (!dynamic_array) return;

    pthread_rwlock_destroy(&dynamic_array->rwlock);
    free(dynamic_array);
}

int add_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, const MAC_RX_INDICATION *indication) {
    if (!dynamic_array || !indication) return -1;

    pthread_rwlock_wrlock(&dynamic_array->rwlock);

    if (dynamic_array->count == dynamic_array->capacity) {
        extend_dynamic_array(dynamic_array);
    }

    // Copy the indication into the array
    dynamic_array->array[dynamic_array->count] = *indication;
    dynamic_array->count++;

    pthread_rwlock_unlock(&dynamic_array->rwlock);

    return 0;  // Success
}

int remove_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, unsigned int PDCP_SN) {
    if (!dynamic_array) return -1;

    pthread_rwlock_wrlock(&dynamic_array->rwlock);

    for (size_t i = 0; i < dynamic_array->count; i++) {
        if (dynamic_array->array[i].PDCP_SN == PDCP_SN) {
            // Shift elements to fill the gap
            memmove(&dynamic_array->array[i], &dynamic_array->array[i + 1],
                    (dynamic_array->count - i - 1) * sizeof(MAC_RX_INDICATION));
            dynamic_array->count--;
            pthread_rwlock_unlock(&dynamic_array->rwlock);
            return 0; // Success
        }
    }

    pthread_rwlock_unlock(&dynamic_array->rwlock);

    return -1; // Not found
}

MAC_RX_INDICATION* find_mac_rx_indication(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, unsigned int PDCP_SN) {
    if (!dynamic_array) return NULL;

    pthread_rwlock_rdlock(&dynamic_array->rwlock);

    for (size_t i = 0; i < dynamic_array->count; i++) {
        if (dynamic_array->array[i].PDCP_SN == PDCP_SN) {
            pthread_rwlock_unlock(&dynamic_array->rwlock);
            return &dynamic_array->array[i];
        }
    }

    pthread_rwlock_unlock(&dynamic_array->rwlock);

    return NULL;
}

void extend_dynamic_array(MAC_RX_INDYNAMIC_ARRAY *dynamic_array) {
    size_t new_capacity = dynamic_array->capacity * 2 || 1; // Avoid zero
    MAC_RX_INDICATION* temp_array = realloc(dynamic_array->array, new_capacity * sizeof(MAC_RX_INDICATION));

    if (!temp_array) return; // Handle memory allocation failure gracefully

    dynamic_array->array = temp_array;
    dynamic_array->capacity = new_capacity;

    pthread_mutex_lock(&dynamic_array->allocator.lock);
    // Update allocator's state if necessary
    pthread_mutex_unlock(&dynamic_array->allocator.lock);
}

int filter_mac_rx_indications(MAC_RX_INDYNAMIC_ARRAY *dynamic_array, 
                              void (*filter_func)(const MAC_RX_INDICATION*, int*), int *filtered_count) {
    if (!dynamic_array || !filter_func || !filtered_count) return -1;

    pthread_rwlock_rdlock(&dynamic_array->rwlock);

    for (size_t i = 0; i < dynamic_array->count; i++) {
        int include = 1;
        filter_func(&dynamic_array->array[i], &include);
        if (include) (*filtered_count)++;
    }

    pthread_rwlock_unlock(&dynamic_array->rwlock);

    return 0; // Success
}

// Example of how to create and use a custom allocator (thread-safe)
CustomAllocator init_custom_allocator(size_t size) {
    CustomAllocator allocator;
    allocator.size = size;
    allocator.memory_pool = malloc(size);
    pthread_mutex_init(&allocator.lock, NULL);

    if (!allocator.memory_pool) {
        // Handle memory allocation failure
    }

    return allocator;
}

// Example filter function for filtering indications based on CRCFLAG
void crcflag_filter(const MAC_RX_INDICATION *indication, int *include) {
    if (indication->CRCFLAG == 1) {  // Arbitrary filter condition
        *include = 1;  // Include in filtered results
    } else {
        *include = 0;
    }
}

// Main function demonstrating usage
int main() {
    CustomAllocator allocator = init_custom_allocator(1024); // Initialize custom allocator

    MAC_RX_INDYNAMIC_ARRAY *dynamic_array = create_mac_rx_dynamic_array(&allocator, 10);

    // Add indications and perform operations...

    int filtered_count = 0;
    filter_mac_rx_indications(dynamic_array, crcflag_filter, &filtered_count);

    destroy_mac_rx_dynamic_array(dynamic_array);

    free(allocator.memory_pool);
    pthread_mutex_destroy(&allocator.lock);

    return 0;
}
```

### Key Features:

- **Custom Allocator**: Provides thread-safe memory allocation and minimizes fragmentation.

- **Thread Safety**: Uses read-write locks to allow concurrent reads and writes, minimizing lock contention.

- **Dynamic Array Management**: Automatically grows as needed to handle increasing data without frequent reallocations.

- **Filtering Capability**: Allows filtering indications based on custom criteria through a callback function.

- **Extensibility**: Supports runtime addition of fields by using an extra fields array (`void**`).

- **Graceful Error Handling**: Manages memory allocation failures and potential overflows gracefully.

This design aims to be efficient, scalable, and maintainable under high-throughput conditions."]

