// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_pdu_array(int N, int *result) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of users.\n");
        *result = -1;
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Calculate memory footprint per structure and attempt to allocate
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * struct_size);

    if (!pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_destroy(&lock);
        *result = -1;
        return NULL;
    }

    // Populate each structure
    for (int i = 0; i < N; ++i) {
        uint32_t ue_info;
        uint16_t rnti;

        clock_t start_time = clock();

        while (clock() - start_time < CLOCKS_PER_SEC * 0.01) { // Timeout of 10 ms
            if (fetch_external_data(&ue_info, &rnti)) {
                pthread_mutex_lock(&lock);
                pdus[i].RX_UE_INFORMATION_TAG = ue_info;
                pdus[i].RNTI = rnti;
                pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
                pthread_mutex_unlock(&lock);
                break;
            }
        }

        if (clock() - start_time >= CLOCKS_PER_SEC * 0.01) {
            fprintf(stderr, "Timeout fetching data for user index %d.\n", i);
            free(pdus);
            pthread_mutex_destroy(&lock);
            *result = -1;
            return NULL;
        }
    }

    pthread_mutex_destroy(&lock);
    *result = 0; // Success
    return pdus;
}
