['Below is a C implementation for managing a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures in a multi-threaded environment:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_Manager;

CRC_Indication_Manager* create_manager(size_t initial_capacity) {
    CRC_Indication_Manager* manager = malloc(sizeof(CRC_Indication_Manager));
    if (!manager) return NULL;

    manager->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int add_element(CRC_Indication_Manager* manager, int RX_TAG, int RNTI) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Out of memory
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = &manager->array[manager->size];
    element->RX_UE_INFORMATION_TAG = RX_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_element(CRC_Indication_Manager* manager, size_t index, int RX_TAG, int RNTI) {
    if (!manager || index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* element = &manager->array[index];
    element->RX_UE_INFORMATION_TAG = RX_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_element(CRC_Indication_Manager* manager, size_t index) {
    if (!manager || index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    memmove(&manager->array[index], &manager->array[index + 1], (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void destroy_manager(CRC_Indication_Manager* manager) {
    if (!manager) return;

    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Key Points:
- The `CRC_Indication_Manager` structure manages the array and includes a mutex for thread safety.
- Functions `add_element`, `update_element`, and `remove_element` are protected by mutex locks to ensure safe concurrent access.
- Dynamic resizing is handled during addition if the current capacity is exceeded.
- Memory allocation failures and invalid operations (like accessing out-of-bounds indices) return error codes. 
- The `destroy_manager` function ensures that allocated memory and resources are properly freed.']

