#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define INITIAL_SIZE 10

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    size_t peak_memory_usage;
} DynamicArray;

DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray* dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;
    pthread_mutex_init(&dyn_array->mutex, NULL);
    dyn_array->peak_memory_usage = 0;

    return dyn_array;
}

void free_dynamic_array(DynamicArray* dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_lock(&dyn_array->mutex);
    free(dyn_array->array);
    pthread_mutex_unlock(&dyn_array->mutex);

    pthread_mutex_destroy(&dyn_array->mutex);
    free(dyn_array);
}

void resize_if_needed(DynamicArray* dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);

    if (dyn_array->count >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->mutex);
            fprintf(stderr, "Failed to resize array\n");
            return;
        }

        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    pthread_mutex_unlock(&dyn_array->mutex);
}

void add_element(DynamicArray* dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);

    resize_if_needed(dyn_array);

    NFAPI_CRC_INDICATION_PDU_T new_elem = {
        .RX_UE_INFORMATION_TAG = rand(),
        .RNTI = rand(),
        .CRC_INDICATION_REL8_TAG = rand(),
        .CRCFLAG = rand() % 2
    };

    dyn_array->array[dyn_array->count++] = new_elem;

    size_t current_memory_usage = (dyn_array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (current_memory_usage > dyn_array->peak_memory_usage) {
        dyn_array->peak_memory_usage = current_memory_usage;
    }

    pthread_mutex_unlock(&dyn_array->mutex);
}

void update_element(DynamicArray* dyn_array, size_t index) {
    if (index >= dyn_array->count) return;

    pthread_mutex_lock(&dyn_array->mutex);

    NFAPI_CRC_INDICATION_PDU_T* elem = &dyn_array->array[index];
    elem->RX_UE_INFORMATION_TAG = rand();
    elem->RNTI = rand();
    elem->CRC_INDICATION_REL8_TAG = rand();
    elem->CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&dyn_array->mutex);
}

void remove_element(DynamicArray* dyn_array, size_t index) {
    if (index >= dyn_array->count) return;

    pthread_mutex_lock(&dyn_array->mutex);

    memmove(&dyn_array->array[index], &dyn_array->array[index + 1],
            (dyn_array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    dyn_array->count--;

    pthread_mutex_unlock(&dyn_array->mutex);
}

size_t get_valid_count(DynamicArray* dyn_array) {
    pthread_mutex_lock(&dyn_array->mutex);

    size_t count = dyn_array->count;

    pthread_mutex_unlock(&dyn_array->mutex);
    return count;
}

void batch_operations(DynamicArray* dyn_array, void (*operations[])(DynamicArray*, size_t), size_t indices[], size_t op_count) {
    pthread_mutex_lock(&dyn_array->mutex);

    for (size_t i = 0; i < op_count; i++) {
        operations[i](dyn_array, indices[i]);
    }

    pthread_mutex_unlock(&dyn_array->mutex);
}

void log_memory_usage(DynamicArray* dyn_array) {
    printf("Current memory usage: %zu bytes\n", (dyn_array->count * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    printf("Peak memory usage: %zu bytes\n", dyn_array->peak_memory_usage);
}
