        if (errorFlag || maxValue <= minValue + 1) return 0; // Graceful error handling
        return rand() % (maxValue - minValue) + minValue + 1;
    }

    // Method to generate random float inclusively within the range
    float GenerateFloatInclusive() {
        if (errorFlag) return 0.0f;
        float scale = (float)(rand()) / RAND_MAX;
        return minFloatValue + scale * (maxFloatValue - minFloatValue);
    }

    // Method to generate random float exclusively within the range
