    op_log.success_operations++;
    pthread_mutex_unlock(&list_mutex);
}

void log_failure() {
    pthread_mutex_lock(&list_mutex);
    op_log.failed_operations++;
    pthread_mutex_unlock(&list_mutex);
}

void report_metrics() {
    printf("Success Operations: %d\n", op_log.success_operations);
    printf("Failed Operations: %d\n", op_log.failed_operations);
}

// Function to manage the list
int add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list_mutex);

    while (list_count >= MAX_ENTRIES) {
        // Wait until there is space in the list
        pthread_cond_wait(&not_full, &list_mutex);
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (pdu_list[i] == NULL) {
            pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2;
            pdu_list[i] = pdu;
            list_count++;

            log_success();
            pthread_mutex_unlock(&list_mutex);
            return 0; // Success
        }
    }

    // This should not happen if the condition is correctly handled
    log_failure();
    pthread_mutex_unlock(&list_mutex);
    return -1; // Allocation failure or unexpected error
}

void remove_pdu_from_list() {
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (pdu_list[i] != NULL) {
            free(pdu_list[i]);
            pdu_list[i] = NULL;
            list_count--;

            // Notify any waiting threads that space is available
            pthread_cond_signal(&not_full);
            break;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

