typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRC_flag;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(int N) {
    if (N <= 0) return NULL;

    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    int null_insertion_chance = 10; // Chance to insert a null pointer (1 in 10)
    for (int i = 0; i < N; ++i) {
        if ((rand() % 100) < null_insertion_chance) {
            *(array + i) = (NFAPI_CRC_INDICATION_PDU_T){0}; // Insert null structure
            continue;
        }

        // Initialize with valid data
