typedef struct MessageNode {
    LTE_ENB_APINASMF_MESSAGE message;
    struct MessageNode* next;
} MessageNode;

typedef struct {
    MessageNode* head;
    pthread_mutex_t lock;
    size_t current_size;
} MessageList;

void initMessageList(MessageList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->current_size = 0;
}

LTE_ENB_APINASMF_MESSAGE* createMessage(unsigned int ENB_ID, unsigned short PDCP_SN, const char* payload_data, size_t payload_len) {
    LTE_ENB_APINASMF_MESSAGE* message = malloc(sizeof(LTE_ENB_APINASMF_MESSAGE));
    if (!message) return NULL;

    message->ENB_ID = ENB_ID;
    message->PDCP_SN = PDCP_SN;
    message->payload = malloc(payload_len);
    if (!message->payload) {
        free(message);
        return NULL;
    }
    memcpy(message->payload, payload_data, payload_len);

    return message;
}

void freeMessage(LTE_ENB_APINASMF_MESSAGE* message) {
    free(message->payload);
    free(message);
}

void addMessage(MessageList* list, LTE_ENB_APINASMF_MESSAGE* message) {
    pthread_mutex_lock(&list->lock);

    MessageNode* new_node = malloc(sizeof(MessageNode));
    if (!new_node) return;

    new_node->message = *message;
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);
}

void removeMessageByENBID(MessageList* list, unsigned int ENB_ID) {
    pthread_mutex_lock(&list->lock);

    MessageNode **indirect = &list->head;
    while (*indirect) {
        if ((*indirect)->message.ENB_ID == ENB_ID) {
            MessageNode *to_remove = *indirect;
            *indirect = to_remove->next;
            freeMessage(&(to_remove->message));
            free(to_remove);
            list->current_size--;
            break;
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void updateMessageState(MessageList* list, unsigned int ENB_ID, const char* new_payload_data, size_t payload_len) {
    pthread_mutex_lock(&list->lock);

    MessageNode *current = list->head;
    while (current) {
        if (current->message.ENB_ID == ENB_ID) {
            free(current->message.payload);
            current->message.payload = malloc(payload_len);
            memcpy(current->message.payload, new_payload_data, payload_len);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

