typedef struct {
    int metricID;
    double currentLoadFactor;
    long performanceCounter; // units per second
} SystemMetricsData;

typedef struct {
    SystemMetricsData *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MetricsManager;

typedef struct {
    double lowerThreshold;
    double upperThreshold;
} DynamicRangeAdjuster;

// Function prototypes
void configureAndMonitorSystemMetrics(MetricsManager *manager, size_t initialCapacity);
void adjustLoadFactor(SystemMetricsData *metric, DynamicRangeAdjuster *adjuster);
size_t resizeArray(SystemMetricsData **data, size_t currentCapacity);
void aggregateMetrics(const MetricsManager *manager);
void monitorAndReport(const MetricsManager *manager);
void displayMetrics(const SystemMetricsManager *manager);

// Function implementations
void configureAndMonitorSystemMetrics(MetricsManager *manager, size_t initialCapacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->data = (SystemMetricsData *)malloc(initialCapacity * sizeof(SystemMetricsData));
    if (!manager->data) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initialCapacity;
    manager->count = 0;

    // Simulation loop for dynamic metric management
    while (1) { 
        pthread_mutex_lock(&manager->lock);

        if (manager->count >= manager->capacity) {
            manager->data = (SystemMetricsData *)resizeArray(&manager->data, manager->capacity);
            if (!manager->data) {
                fprintf(stderr, "Failed to resize array\n");
                exit(EXIT_FAILURE);
            }
            manager->capacity *= 2; // Double the capacity
        }

        // Simulate adding a new metric
        SystemMetricsData *metric = &manager->data[manager->count++];
        metric->metricID = manager->count;
        metric->currentLoadFactor = (double)rand() / RAND_MAX; // Random load factor
        metric->performanceCounter = rand(); // Random performance counter

        DynamicRangeAdjuster adjuster = {0.2, 0.8};
        adjustLoadFactor(metric, &adjuster);

        pthread_mutex_unlock(&manager->lock);

        aggregateMetrics(manager);
        monitorAndReport(manager);

        // Sleep for a bit to simulate real-time monitoring
        usleep(100000); // 100 ms
    }
}

void adjustLoadFactor(SystemMetricsData *metric, DynamicRangeAdjuster *adjuster) {
    if (metric->currentLoadFactor < adjuster->lowerThreshold) {
        metric->currentLoadFactor += 0.1; // Increase load factor
    } else if (metric->currentLoadFactor > adjuster->upperThreshold) {
        metric->currentLoadFactor -= 0.1; // Decrease load factor
    }
}

size_t resizeArray(SystemMetricsData **data, size_t currentCapacity) {
    size_t newCapacity = currentCapacity * 2;
    SystemMetricsData *newData = (SystemMetricsData *)realloc(*data, newCapacity * sizeof(SystemMetricsData));
    if (!newData) {
        return 0; // Failed to allocate memory
    }
    *data = newData;
    return newCapacity;
}

void aggregateMetrics(const MetricsManager *manager) {
    double totalLoadFactor = 0.0;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        totalLoadFactor += manager->data[i].currentLoadFactor;
    }
    pthread_mutex_unlock(&manager->lock);

    double averageLoadFactor = totalLoadFactor / manager->count;
    printf("Average Load Factor: %.2f\n", averageLoadFactor);
}

void monitorAndReport(const MetricsManager *manager) {
    // Placeholder for monitoring and reporting logic
    printf("Monitoring system metrics...\n");
}

void displayMetrics(const MetricsManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        printf("Metric ID: %d, Load Factor: %.2f, Performance Counter: %ld\n",
               manager->data[i].metricID,
               manager->data[i].currentLoadFactor,
               manager->data[i].performanceCounter);
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    MetricsManager manager;
    configureAndMonitorSystemMetrics(&manager, 10);

    return 0;
}
