#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCT_COUNT 1000
#define UPPER_LIMIT_SIZE (MAX_STRUCT_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T))
#define ERROR_CODE_INSUFFICIENT_RESOURCES -1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    size_t count;
} INTERFACE_CONFIG;

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_interface_config(INTERFACE_CONFIG** interface_configs, int requested_count) {
    if (requested_count <= 0 || requested_count > MAX_STRUCT_COUNT) {
        return ERROR_CODE_INSUFFICIENT_RESOURCES;
    }

    pthread_mutex_lock(&config_lock);

    *interface_configs = (INTERFACE_CONFIG*)malloc(requested_count * sizeof(INTERFACE_CONFIG));
    if (*interface_configs == NULL) {
        pthread_mutex_unlock(&config_lock);
        return ERROR_CODE_INSUFFICIENT_RESOURCES; // Allocation failed
    }

    for (int i = 0; i < requested_count; ++i) {
        (*interface_configs)[i].pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(UPPER_LIMIT_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*interface_configs)[i].pdu_array == NULL) {
            // Free previously allocated memory in case of failure
            for (int j = 0; j < i; ++j) {
                free((*interface_configs)[j].pdu_array);
            }
            free(*interface_configs);
            pthread_mutex_unlock(&config_lock);
            return ERROR_CODE_INSUFFICIENT_RESOURCES;
        }

        (*interface_configs)[i].count = UPPER_LIMIT_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Populate each structure with random data
        for (size_t j = 0; j < (*interface_configs)[i].count; ++j) {
            (*interface_configs)[i].pdu_array[j].RX_UE_INFORMATION_TAG = rand() % 10000;
            (*interface_configs)[i].pdu_array[j].RNTI = rand() % 100000;
            srand(time(NULL) + j); // Seed with a different value for each entry
            (*interface_configs)[i].pdu_array[j].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG (0 or 1)
        }
    }

    pthread_mutex_unlock(&config_lock);
    return 0; // Success
}

void cleanup_interface_config(INTERFACE_CONFIG* interface_configs, int count) {
    if (!interface_configs) return;

    for (int i = 0; i < count; ++i) {
        free(interface_configs[i].pdu_array);
    }
    free(interface_configs);
}
```

### Explanation:

- **Thread Safety**: The function uses a `pthread_mutex_t` to ensure that the initialization process is thread-safe.
- **Dynamic Memory Allocation**: It allocates memory for an array of `INTERFACE_CONFIG` structures and each structure's associated PDU array. If allocation fails at any point, it cleans up previously allocated resources before returning an error code.
- **Random Data Initialization**: Each `NFAPI_CRC_INDICATION_PDU_T` structure is populated with random values using the C standard library functions for randomness (`rand()`).
- **Error Handling**: The function returns a specific error code if resource allocation fails, and it ensures that all allocated memory is freed in case of partial failures.
- **Performance Considerations**: The mutex lock minimizes overhead by only protecting critical sections. Memory fragmentation management is implicitly handled through contiguous allocations, which are typical for high-throughput environments.

This function provides a robust foundation for network interface configuration while considering the needs for thread safety and efficient resource usage."]

['```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http.Headers;
using System.Threading.Tasks;

public class PageService
{
    private readonly ConcurrentDictionary<string, (string Content, string ETag)> _pageElements = new();

    public Task<Response> UpdatePageElement(string pageSectionId, string elementId, string htmlContent, string etag)
    {
        var key = $"{pageSectionId}:{elementId}";
        return Task.Run(() =>
        {
            if (_pageElements.TryGetValue(key, out var currentData) && currentData.ETag != etag)
            {
                return new Response { Success = false, Message = "ETag mismatch: Update rejected to prevent stale data." };
            }

            try
            {
                ValidateHtmlContent(htmlContent);
                _pageElements[key] = (htmlContent, Guid.NewGuid().ToString());
                return new Response { Success = true, RefreshPage = true, Message = "Update successful. Page needs refresh." };
            }
            catch (Exception ex)
            {
                return new Response { Success = false, Message = $"Error updating element: {ex.Message}" };
            }
        });
    }

    private void ValidateHtmlContent(string htmlContent)
    {
        if (!htmlContent.Trim().EndsWith("</"))
        {
            throw new InvalidOperationException("HTML content seems incomplete. Possible unclosed tags.");
        }

        // Simple check for common structural issues
        int openTags = 0;
        int closeTags = 0;

        foreach (var word in htmlContent.Split(' '))
        {
            if (word.TrimEnd('/').StartsWith("<") && !word.EndsWith("/>"))
            {
                openTags++;
            }
            else if (word.StartsWith("</"))
            {
                closeTags++;
            }

            // Check for unclosed comment
            if (htmlContent.Contains("<!--") && !htmlContent.Contains("-->"))
            {
                throw new InvalidOperationException("HTML content has an unclosed comment.");
            }
        }

        if (openTags > closeTags)
        {
            throw new InvalidOperationException("Mismatch between opening and closing tags in HTML content.");
        }
    }
}

public class Response
{
    public bool Success { get; set; }
    public bool RefreshPage { get; set; } = false;
    public string Message { get; set; }
}
