#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    // Example structure for L2 PDCH PDU data, add actual fields here
    int id;
    unsigned char data[256];
} PDCH_PDU_T;

typedef struct {
    PDCH_PDU_T *pdu_array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_L2_PDU_LIST_T;

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

NFAPI_L2_PDU_LIST_T* init_nfa_l2_pdu_list() {
    NFAPI_L2_PDU_LIST_T *list = (NFAPI_L2_PDU_LIST_T *)malloc(sizeof(NFAPI_L2_PDU_LIST_T));
    if (!list) {
        log_error("Failed to allocate memory for list");
        return NULL;
    }
    list->pdu_array = (PDCH_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(PDCH_PDU_T));
    if (!list->pdu_array) {
        free(list);
        log_error("Failed to allocate memory for pdu array");
        return NULL;
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void resize_pdu_list(NFAPI_L2_PDU_LIST_T *list) {
    size_t new_capacity = list->capacity * 2;
    PDCH_PDU_T *new_array = (PDCH_PDU_T *)realloc(list->pdu_array, new_capacity * sizeof(PDCH_PDU_T));
    if (!new_array) {
        log_error("Failed to reallocate memory for pdu array");
        return;
    }
    list->pdu_array = new_array;
    list->capacity = new_capacity;
}

int add_pdu(NFAPI_L2_PDU_LIST_T *list, PDCH_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resize_pdu_list(list);
        if (list->size == list->capacity) {  // Check again after potential failed realloc
            pthread_mutex_unlock(&list->lock);
            log_error("Failed to resize pdu array");
            return -1;
        }
    }
    memcpy(&list->pdu_array[list->size], pdu, sizeof(PDCH_PDU_T));
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_pdu(NFAPI_L2_PDU_LIST_T *list, size_t index) {
    if (index >= list->size) {
        log_error("Index out of bounds");
        return -1;
    }
    pthread_mutex_lock(&list->lock);
    memmove(&list->pdu_array[index], &list->pdu_array[index + 1], 
            (list->size - index - 1) * sizeof(PDCH_PDU_T));
    list->size--;
    if (list->size < list->capacity / 4 && list->capacity > INITIAL_CAPACITY) {
        size_t new_capacity = list->capacity / 2;
        PDCH_PDU_T *new_array = (PDCH_PDU_T *)realloc(list->pdu_array, new_capacity * sizeof(PDCH_PDU_T));
        if (!new_array) {
            log_error("Failed to reallocate memory for pdu array");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->pdu_array = new_array;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

PDCH_PDU_T* get_pdu(NFAPI_L2_PDU_LIST_T *list, size_t index) {
    if (index >= list->size) {
        log_error("Index out of bounds");
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    PDCH_PDU_T *pdu = &list->pdu_array[index];
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

void cleanup_nfa_l2_pdu_list(NFAPI_L2_PDU_LIST_T *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pdu_array);
        free(list);
    }
}
```

### Explanation:

- **Dynamic Resizing**: The list automatically resizes as needed, doubling its capacity when full and halving it when a quarter of the space is unused.

- **Concurrency**: A mutex lock (`pthread_mutex_t`) ensures that concurrent accesses are thread-safe, preventing race conditions.

- **Error Handling**: Errors such as memory allocation failures are logged using `log_error`.

- **Memory Management**: Uses `realloc` for efficient resizing and ensures no buffer overflows occur by checking array bounds. 

- **Usability**: The API provides functions to initialize the list, add, remove, get PDCH_PDU structures, and clean up resources. This makes it easy to integrate into existing codebases.

Remember to link with `-lpthread` when compiling this program due to the use of POSIX threads for concurrency handling.']

