}

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Failed to allocate memory for DynamicArray");
        return NULL;
    }

    da->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        log_error("Failed to allocate memory for array");
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;

    if (pthread_mutex_init(&da->lock, NULL) != 0) {
        free(da->array);
        free(da);
        log_error("Mutex init failed");
        return NULL;
    }

    return da;
}

int add_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            log_error("Failed to reallocate memory for array");
            return -1;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&da->lock);
            return -1;  // RNTI already exists
        }
    }

    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);

    return 0;
}

int remove_pdu_by_rnti(DynamicArray *da, unsigned int rnti) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == rnti) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --da->size;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&da->lock);

    return -1; // RNTI not found
}

void iterate_and_print_rnti(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->size; ++i) {
        printf("RNTI: %u\n", da->array[i].RNTI);
    }

    pthread_mutex_unlock(&da->lock);
}

void free_dynamic_array(DynamicArray *da) {
    if (!da) return;

    pthread_mutex_destroy(&da->lock);
    free(da->array);
    free(da);
}

