        self.RX_UE_INFORMATION_TAG = rx_ue_info_tag
        self.RNTI = rnti
        self.CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag

class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)

        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1

def initialize_entities(num_entities):
