            crc_indication_rel8_tag=random.randint(1, 1000000)
        )
        entities.append(entity)
    return entities

def identify_disjoint_pairs(entities):
    uf = UnionFind()
    for entity in entities:
        uf.parent[entity.RNTI] = entity.RNTI
        if entity.RNTI not in uf.rank:
            uf.rank[entity.RNTI] = 0

    disjoint_pairs = []
    seen_rntis = set()

    for entity in entities:
        root = uf.find(entity.RNTI)
        if root in seen_rntis:
            continue
        for other_entity in entities:
            if other_entity.RNTI != entity.RNTI and uf.find(other_entity.RNTI) == root:
                disjoint_pairs.append((entity, other_entity))
                uf.union(entity.RNTI, other_entity.RNTI)
        seen_rntis.add(root)

    return disjoint_pairs

