    int PDCCH_Resource_Config_Info;
} RESOURCE_CONFIG_INFO_T;

typedef struct {
    int MAC_INSTANCE_ID;
    RESOURCE_CONFIG_INFO_T resource_config_info;
    DL_CCCH_MESSAGE_CONFIG_T dl_ccch_message_config;
} MAC_CONTEXT_T;

typedef struct Node {
    MAC_CONTEXT_T context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MAC_Context_List;

MAC_Context_List* create_context_list() {
    MAC_Context_List* list = (MAC_Context_List*)malloc(sizeof(MAC_Context_List));
    if (!list) {
        perror("Failed to allocate memory for context list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int generate_random_flag() {
    return rand() % 256; // Example random flag generation
}

void add_mac_context(MAC_Context_List* list, MAC_CONTEXT_T context) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && (*current)->context.MAC_INSTANCE_ID < context.MAC_INSTANCE_ID) {
        current = &((*current)->next);
    }

    if (*current && (*current)->context.MAC_INSTANCE_ID == context.MAC_INSTANCE_ID) {
        fprintf(stderr, "MAC_INSTANCE_ID %d already exists\n", context.MAC_INSTANCE_ID);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->context = context;
    new_node->next = *current;

    *current = new_node;
    pthread_mutex_unlock(&list->lock);
}

void remove_mac_context(MAC_Context_List* list, int mac_instance_id) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node** current = &(list->head);
    while (*current && (*current)->context.MAC_INSTANCE_ID != mac_instance_id) {
        current = &((*current)->next);
    }

    if (*current) {
        Node* to_free = *current;
        *current = (*current)->next;
        free(to_free);
    } else {
        fprintf(stderr, "MAC_INSTANCE_ID %d not found\n", mac_instance_id);
    }

    pthread_mutex_unlock(&list->lock);
}

void print_all_pdcch_resources(MAC_Context_List* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("PDCCH_Resource_Config_Info: %d\n", current->context.resource_config_info.PDCCH_Resource_Config_Info);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_context_list(MAC_Context_List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    srand(time(NULL));

    MAC_Context_List* context_list = create_context_list();
    if (!context_list) return EXIT_FAILURE;

    for (int i = 0; i < 10; ++i) {
        MAC_CONTEXT_T context;
        context.MAC_INSTANCE_ID = i;
        context.resource_config_info.PDCCH_Resource_Config_Info = rand() % 1000;
        context.dl_ccch_message_config.CCCH_Message_Flag = generate_random_flag();

        add_mac_context(context_list, context);
    }

    print_all_pdcch_resources(context_list);

    remove_mac_context(context_list, 5);
    print_all_pdcch_resources(context_list);

    destroy_context_list(context_list);
    return EXIT_SUCCESS;
}
```

