int initialize_manager(CRC_Indication_Manager *manager, size_t initial_capacity) {
    if (initial_capacity == 0)
        return -1;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array)
        return -1;

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return 0;
}

int add_entry(CRC_Indication_Manager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &manager->array[manager->size++];
    entry->RX_UE_INFORMATION_TAG = rand(); // Example valid tag
    entry->RNTI = (rand() % MAX_RNTI) + 1; // Ensure RNTI is in a valid range
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_entry(CRC_Indication_Manager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            memmove(&manager->array[i], &manager->array[i + 1],
                    (manager->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --manager->size;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void print_entries(const CRC_Indication_Manager *manager) {
    pthread_mutex_lock((CRC_Indication_Manager *)manager);

    for (size_t i = 0; i < manager->size; ++i) {
        printf("RNTI: %u, RX_UE_INFORMATION_TAG: %u, CRCFLAG: %d\n",
               manager->array[i].RNTI,
               manager->array[i].RX_UE_INFORMATION_TAG,
               manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    pthread_mutex_unlock((CRC_Indication_Manager *)manager);
}

void reset_crc_flags(CRC_Indication_Manager *manager) {
