    for (size_t i = 0; i < manager->size; ++i) {
        manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // Reset to default
    }

    pthread_mutex_unlock(&manager->lock);
}

void destroy_manager(CRC_Indication_Manager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
