['Here's a C-based implementation for managing a dynamic list of LTE UE Contexts using a doubly linked list and ensuring thread safety with mutexes:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the structure for CRC indication
typedef struct {
    int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int S_TMSI;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
    // Add additional fields for NAS messages if needed
} NFAPI_CRC_INDICATION_PDU_T;

// Define the UE Context structure
typedef struct UEContextNode {
    int UE_ID;
    NFAPI_CRC_INDICATION_PDU_T nasPdu;
    struct UEContextNode* prev;
    struct UEContextNode* next;
} UEContextNode;

// Define the doubly linked list and mutex for thread safety
typedef struct {
    UEContextNode* head;
    UEContextNode* tail;
    pthread_mutex_t lock;
} UELinkedList;

// Function to initialize the UE context list
void initUEList(UELinkedList* ueList) {
    ueList->head = NULL;
    ueList->tail = NULL;
    pthread_mutex_init(&ueList->lock, NULL);
}

// Function to generate a random CRCFLAG using a seed for reproducibility
unsigned char generateRandomCRCFlag(unsigned int seed) {
    srand(seed);
    return rand() % 2; // Randomly returns 0 or 1
}

// Function to create and insert a new UE context
void addUEContext(UELinkedList* ueList, int seed) {
    pthread_mutex_lock(&ueList->lock);

    UEContextNode* newNode = (UEContextNode*)malloc(sizeof(UEContextNode));
    if (!newNode) {
        perror("Failed to allocate memory for UE Context");
        pthread_mutex_unlock(&ueList->lock);
        return;
    }

    newNode->UE_ID = rand(); // Assign a random UE ID
    newNode->nasPdu.RX_UE_INFORMATION_TAG = rand();
    newNode->nasPdu.S_TMSI = rand();
    newNode->nasPdu.crcIndicationTag.RNTI = rand();
    newNode->nasPdu.crcIndicationTag.CRCFLAG = generateRandomCRCFlag(seed);

    newNode->prev = ueList->tail;
    newNode->next = NULL;

    if (ueList->tail) {
        ueList->tail->next = newNode;
    } else {
        ueList->head = newNode;
    }
    ueList->tail = newNode;

    pthread_mutex_unlock(&ueList->lock);
}

// Function to delete a UE context by ID
void removeUEContext(UELinkedList* ueList, int ueID) {
    pthread_mutex_lock(&ueList->lock);

    UEContextNode *current = ueList->head;
    while (current) {
        if (current->UE_ID == ueID) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                ueList->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                ueList->tail = current->prev;
            }

            free(current);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ueList->lock);
}

// Function to destroy the UE context list
void destroyUEList(UELinkedList* ueList) {
    pthread_mutex_lock(&ueList->lock);

    UEContextNode* current = ueList->head;
    while (current) {
        UEContextNode* next = current->next;
        free(current);
        current = next;
    }

    ueList->head = NULL;
    ueList->tail = NULL;

    pthread_mutex_unlock(&ueList->lock);
    pthread_mutex_destroy(&ueList->lock);
}

// Example usage
int main() {
    UELinkedList ueList;
    initUEList(&ueList);

    // Add UE contexts with a seed for reproducibility
    addUEContext(&ueList, 12345);
    addUEContext(&ueList, 67890);

    // Remove a UE context by ID (example)
    removeUEContext(&ueList, ueList.head->UE_ID);

    destroyUEList(&ueList);
    return 0;
}
```

This code provides a basic structure for managing LTE UE Contexts with thread safety using mutexes. It includes functions to initialize the list, add and remove contexts, and clean up resources. The CRCFLAG is generated deterministically using a seed value to ensure reproducibility in tests.']

