    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    int unique_entries = 0;
    pthread_t threads[10];
    int thread_count = 0;

    // Create worker threads
    for (int i = 0; i < 10 && i < MAX_ENTRIES; ++i) {
        pthread_create(&threads[i], NULL, generate_entries_worker, (void*)list);
        thread_count++;
    }

    // Join worker threads
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Determine how many unique entries were generated
    for (int i = 0; i < MAX_ENTRIES && list[i].ueInfo.RX_UE_INFORMATION_TAG != 0; ++i) {
        unique_entries++;
    }

    *count = unique_entries;
    return list;
}

void* generate_entries_worker(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)arg;

    for (int i = 0; i < MAX_ENTRIES / 10; ++i) {
        UE_INFO_T ueInfo;
        if (fetch_UE_information(&ueInfo) == 0) {
            pthread_mutex_lock(&logger.lock);
            int idx = rand() % MAX_ENTRIES;
            while (list[idx].ueInfo.RX_UE_INFORMATION_TAG != 0) {
                idx = (idx + 1) % MAX_ENTRIES; // Find next free slot
            }
            list[idx].ueInfo = ueInfo;
            list[idx].crcIndication.CRCFLAG = rand() & 1; // Randomly set CRC flag

            logger.success_count++;
            pthread_mutex_unlock(&logger.lock);
        } else {
            pthread_mutex_lock(&logger.lock);
            logger.failure_count++;
            pthread_mutex_unlock(&logger.lock);
        }
    }

    return NULL;
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) free(list);
}

int main() {
    srand(time(NULL));

    int count = 0;
    NFAPI_CRC_INDICATION_PDU_T* pduList = generate_nfa_crc_indication_pdu_list(&count);

    printf("Generated %d unique entries\n", count);
    printf("Success: %d, Failures: %d\n", logger.success_count, logger.failure_count);

    free_crc_indication_pdu_list(pduList);
    return 0;
}
