#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NICS 256

typedef struct {
    char mac_address[18];
    char ip_address[16];
    struct {
        int port;
        char state[10];
    } tcp_connections[10];
} NIC_Stats;

// Simulated external configuration management service
int fetch_network_settings(NIC_Stats *nic, size_t nic_count) {
    // Simulate a network call that may fail
    if (rand() % 5 == 0) { // Simulating failure with 20% chance
        return -1; // Error code for failure
    }

    for (size_t i = 0; i < nic_count; ++i) {
        snprintf(nic[i].mac_address, sizeof(nic[i].mac_address), "00:11:22:33:%02x:%02x", rand() % 256, rand() % 256);
        snprintf(nic[i].ip_address, sizeof(nic[i].ip_address), "192.168.0.%d", rand() % 255 + 1);

        for (int j = 0; j < 10; ++j) {
            nic[i].tcp_connections[j].port = rand() % 65535;
            snprintf(nic[i].tcp_connections[j].state, sizeof(nic[i].tcp_connections[j].state), "ESTABLISHED");
        }
    }

    return 0; // Success
}

// Mutex for thread safety
pthread_mutex_t nic_stats_lock;

NIC_Stats* initialize_nic_stats(size_t *nic_count_ptr) {
    if (fetch_network_settings == NULL) {
        fprintf(stderr, "Configuration management service not available.\n");
        return NULL;
    }

    pthread_mutex_init(&nic_stats_lock, NULL);

    NIC_Stats *nics = malloc(MAX_NICS * sizeof(NIC_Stats));
    if (!nics) {
        perror("Failed to allocate memory for NIC stats");
        return NULL;
    }

    size_t nic_count = *nic_count_ptr;
    if (nic_count > MAX_NICS) {
        fprintf(stderr, "Requested NIC count exceeds maximum allowed.\n");
        free(nics);
        pthread_mutex_destroy(&nic_stats_lock);
        return NULL;
    }

    int result = fetch_network_settings(nics, nic_count);
    if (result != 0) {
        fprintf(stderr, "Failed to fetch network settings from configuration management service.\n");

        // Fallback: Use default values
        for (size_t i = 0; i < nic_count; ++i) {
            snprintf(nics[i].mac_address, sizeof(nics[i].mac_address), "00:00:00:00:%02x:%02x", rand() % 256, rand() % 256);
            snprintf(nics[i].ip_address, sizeof(nics[i].ip_address), "192.168.0.%d", rand() % 255 + 1);

            for (int j = 0; j < 10; ++j) {
                nics[i].tcp_connections[j].port = rand() % 65535;
                snprintf(nics[i].tcp_connections[j].state, sizeof(nics[i].tcp_connections[j].state), "CLOSED");
            }
        }
    }

    *nic_count_ptr = nic_count;

    return nics;
}

void free_nic_stats(NIC_Stats *nics) {
    if (nics) {
        free(nics);
    }
    pthread_mutex_destroy(&nic_stats_lock);
}
```

### Key Points:
- The function initializes an array of `NIC_Stats` structures, ensuring thread safety using a mutex.
- It fetches network settings from an external service and handles potential failures by providing fallback default values.
- Memory allocations are minimized by defining a maximum number (`MAX_NICS`) for NIC statistics.
- Error handling is incorporated during memory allocation and when fetching configurations.
- The function design assumes that configuration management might be unavailable or fail intermittently, with appropriate fallback mechanisms.']

