        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    unsigned long seed;
    size_t memory_threshold; // in bytes
} CRC_PDU_Manager;

void update_memory_threshold(size_t new_threshold) {
    // Placeholder for updating the external data source's threshold value
}

int init_crc_pdu_manager(CRC_PDU_Manager *manager, size_t initial_capacity, unsigned long seed, size_t memory_threshold) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) return -1;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->seed = seed;
    manager->memory_threshold = memory_threshold;
    pthread_mutex_init(&manager->lock, NULL);
    srand(seed);

    return 0;
}

void cleanup_crc_pdu_manager(CRC_PDU_Manager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
}

int resize_crc_pdu_array(CRC_PDU_Manager *manager) {
    size_t new_capacity = manager->capacity * 2;

    // Calculate memory usage of the array
    size_t current_memory_usage = new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Check against the memory threshold
    if (current_memory_usage > manager->memory_threshold) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) return -1;

    manager->array = new_array;
    manager->capacity = new_capacity;
    return 0;
}

int add_crc_pdu(CRC_PDU_Manager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        int resize_result = resize_crc_pdu_array(manager);
        if (resize_result != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example assignment
    pdu->RNTI = rand() % 1000; // Example assignment
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void update_threshold_dynamically(CRC_PDU_Manager *manager) {
    size_t new_threshold = manager->memory_threshold + (rand() % 1024); // Simulating dynamic threshold updates
    update_memory_threshold(new_threshold);
    manager->memory_threshold = new_threshold;
}

int main() {
    CRC_PDU_Manager manager;
    if (init_crc_pdu_manager(&manager, 10, 42, 1048576) != 0) { // Initial capacity of 10, seed 42, threshold 1MB
        fprintf(stderr, "Failed to initialize manager\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
        if (add_crc_pdu(&manager) != 0) {
            fprintf(stderr, "Failed to add CRC PDU or memory threshold exceeded\n");
            break;
        }
    }

    update_threshold_dynamically(&manager);

    cleanup_crc_pdu_manager(&manager);
    return EXIT_SUCCESS;
}
