#include <time.h>

#define MAX_RNTI 1048575
#define RATE_LIMIT 100
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
int current_rate = 0;

bool validate_RNTI(uint32_t rnti) {
    // Simulate external data source validation
    return rnti > 0 && rnti <= MAX_RNTI;
}

void log_error(const char *message) {
    pthread_mutex_lock(&rate_limit_lock);
    printf("ERROR: %s\n", message);
    current_rate--;
    pthread_mutex_unlock(&rate_limit_lock);
}

bool check_rate_limit() {
    pthread_mutex_lock(&rate_limit_lock);
    if (current_rate >= RATE_LIMIT) {
        pthread_mutex_unlock(&rate_limit_lock);
        return false;
    }
    current_rate++;
    pthread_mutex_unlock(&rate_limit_lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_api_list(int count, int *result_count) {
