    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    void *ue_specific_info; // Dynamically allocated data field for UE-specific information
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure representing the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **entries;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} CRC_Indication_List;

// Function to initialize the CRC indication list
int init_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->entries = NULL;
    list->count = 0;
    return 0; // Return 0 for success
}

// Function to free resources associated with the CRC indication list
void destroy_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);
    if (list->entries != NULL) {
        for (size_t i = 0; i < list->count; ++i) {
            free(list->entries[i]->ue_specific_info);
            free(list->entries[i]);
        }
        free(list->entries);
        list->entries = NULL;
        list->count = 0;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Function to add an entry to the CRC indication list
int add_crc_indication_pdu(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *pdu, size_t max_data_size) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicate consecutive RNTI
    if (list->count > 0 && list->entries[list->count - 1]->RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Return error code for duplicate RNTI
    }

