#include <iostream>
#include <vector>
#include <random>
#include <fstream>
#include <mutex>
#include <memory>
#include <string>

struct RX_UE_INFORMATION_TAG {
    int id;
};

struct RNTI {
    uint16_t value;
};

struct CRC_INDICATION_REL8_TAG {
    bool CRCFLAG;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
