class CryptoManager {
public:
    enum class EncryptionAlgorithm { DES_ECB, DES_EDE, DES_EDE3, DES_CFB };

private:
    struct CryptoConfig {
        EncryptionAlgorithm algorithm;
        std::string key;
        std::vector<uint8_t> iv;
        bool enabled;
    };

    static const uint32_t KEY_SIZE = 8; // Assuming DES key size
    static const uint32_t IV_SIZE = 8;  // Assuming block size for DES

    CryptoConfig config_;
    std::mutex mtx_;

public:
    CryptoManager() : config_{EncryptionAlgorithm::DES_ECB, "", {}, false} {}

    void setConfiguration(EncryptionAlgorithm algorithm, const std::string& key, const std::vector<uint8_t>& iv, bool enabled) {
        std::lock_guard<std::mutex> lock(mtx_);
        config_ = {algorithm, key, iv, enabled};
    }

    CryptoConfig getConfig() {
        std::lock_guard<std::mutex> lock(mtx_);
        return config_;
    }

    void enableEncryption(bool enable) {
        std::lock_guard<std::mutex> lock(mtx_);
        config_.enabled = enable;
    }

    bool isEncryptionEnabled() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return config_.enabled;
    }
};

class NFAPIManager {
private:
    CryptoManager crypto_manager_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdu_list_;
    static constexpr size_t PDU_COUNT = 10;

public:
    NFAPIManager() {
        initializePDUs();
    }

    void initializePDUs() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);

        for (size_t i = 0; i < PDU_COUNT; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rx_ue_info.id = static_cast<int>(i);
            pdu.rnti.value = static_cast<uint16_t>(i * 100);
            pdu.crc_tag.CRCFLAG = dis(gen);
            pdu_list_.push_back(pdu);
        }
    }

    void serializeToFile(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);

        if (file.is_open()) {
            for (const auto& pdu : pdu_list_) {
                file.write(reinterpret_cast<const char*>(&pdu.rx_ue_info.id), sizeof(pdu.rx_ue_info.id));
                file.write(reinterpret_cast<const char*>(&pdu.rnti.value), sizeof(pdu.rnti.value));
                file.write(reinterpret_cast<const char*>(&pdu.crc_tag.CRCFLAG), sizeof(pdu.crc_tag.CRCFLAG));
            }
        }

        file.close();
    }

    void deserializeFromFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);

        if (file.is_open()) {
            pdu_list_.clear();
            NFAPI_CRC_INDICATION_PDU_T pdu;

            while (file.read(reinterpret_cast<char*>(&pdu.rx_ue_info.id), sizeof(pdu.rx_ue_info.id))) {
                file.read(reinterpret_cast<char*>(&pdu.rnti.value), sizeof(pdu.rnti.value));
                file.read(reinterpret_cast<char*>(&pdu.crc_tag.CRCFLAG), sizeof(pdu.crc_tag.CRCFLAG));
                pdu_list_.push_back(pdu);
            }
        }

        file.close();
    }

    void configureCrypto(CryptoManager::EncryptionAlgorithm algorithm, const std::string& key, const std::vector<uint8_t>& iv, bool enable) {
        crypto_manager_.setConfiguration(algorithm, key, iv, enable);
    }

    CryptoManager getConfig() {
        return crypto_manager_;
    }
};

int main() {
    NFAPIManager manager;

    // Example usage
    manager.configureCrypto(CryptoManager::EncryptionAlgorithm::DES_ECB, "0123456789ABCDEF", {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08}, true);

    manager.serializeToFile("pdus.bin");
    manager.deserializeFromFile("pdus.bin");

    return 0;
}
