typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
} ConfigStructure;

typedef struct {
    void *memory_pool;
    size_t pool_size;
    pthread_mutex_t pool_lock;
} MemoryPool;

void initialize_memory_pool(MemoryPool *pool, size_t pool_size) {
    pool->memory_pool = malloc(pool_size);
    pool->pool_size = pool_size;
    pthread_mutex_init(&pool->pool_lock, NULL);
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->pool_lock);
    if (size > pool->pool_size) {
        pthread_mutex_unlock(&pool->pool_lock);
        return NULL; // Not enough memory in the pool
    }
    void *ptr = pool->memory_pool;
    pool->memory_pool += size;
    pool->pool_size -= size;
    pthread_mutex_unlock(&pool->pool_lock);
    return ptr;
}

void initialize_config_structure(ConfigStructure *config, int num_sessions, MemoryPool *pool) {
    pthread_mutex_init(&config->lock, NULL);

    for (int i = 0; i < num_sessions; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *session = allocate_from_pool(pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!session) {
            fprintf(stderr, "Memory allocation failed for session %d\n", i);
            continue;
