        session->crcflag = rand() & 1;                   // Random CRCFLAG

        pthread_mutex_lock(&config->lock);
        config->sessions[i] = session;
        pthread_mutex_unlock(&config->lock);
    }
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->pool_lock);
}

void cleanup_config_structure(ConfigStructure *config, int num_sessions) {
    for (int i = 0; i < num_sessions; ++i) {
        if (config->sessions[i]) {
            // No explicit deallocation needed as memory is managed by the pool
            config->sessions[i] = NULL;
        }
