#define MAX_ENTRIES 10000

typedef struct {
    uint32_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    struct {
        uint8_t valid;
        int16_t ueIndex;
    } RX_UE_INFORMATION_TAG;
} ProtocolStack;

typedef struct {
    uint64_t rxBytes;
    uint64_t txBytes;
    uint32_t pktCount;
    float errorRate;
} PortStatistics;

typedef struct {
    ProtocolStack stackInfo;
    CRC_INDICATION_REL8_TAG crcTag;
    unsigned char macAddr[6];
    uint32_t ipAddress;
    PortStatistics portStats;
} NetworkEntry;

void initializeRandom() {
    srand((unsigned)time(NULL));
}

NetworkEntry* initializeEntries(size_t count, const char *inputFile, const char *outputFile) {
    if (count > MAX_ENTRIES) return NULL;

    NetworkEntry *entries = (NetworkEntry *)malloc(count * sizeof(NetworkEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    FILE *inStream = fopen(inputFile, "rb");
    if (!inStream) {
        free(entries);
        perror("Failed to open input file");
        return NULL;
    }

    fread(entries, sizeof(NetworkEntry), count, inStream);
    fclose(inStream);

    for (size_t i = 0; i < count; ++i) {
        entries[i].crcTag.crcflag = rand() & 1; // Random CRCFLAG
        entries[i].stackInfo.RX_UE_INFORMATION_TAG.valid = 1;
        entries[i].stackInfo.RX_UE_INFORMATION_TAG.ueIndex = i;

        // Generate random MAC address and IP for demonstration purposes
        for (int j = 0; j < 6; ++j) {
            entries[i].macAddr[j] = rand() & 0xFF;
        }
        entries[i].ipAddress = htonl(rand()); // Random IPv4 address

        // Simulate Port Statistics based on traffic data
        entries[i].portStats.rxBytes = (uint64_t)(rand() % 100000);
        entries[i].portStats.txBytes = (uint64_t)(rand() % 100000);
        entries[i].portStats.pktCount = rand() % 1000;
        entries[i].portStats.errorRate = ((float)rand() / RAND_MAX) * 5.0; // Random error rate up to 5%
    }

    FILE *outStream = fopen(outputFile, "wb");
    if (!outStream) {
        free(entries);
        perror("Failed to open output file");
        return NULL;
    }

    fwrite(entries, sizeof(NetworkEntry), count, outStream);
    fclose(outStream);

    free(entries); // Free memory after writing
    return NULL;   // No longer need the data structure after write operation
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <inputFile> <outputFile>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initializeRandom();
    size_t entryCount = MAX_ENTRIES; // Example: handle max entries
    NetworkEntry *entries = initializeEntries(entryCount, argv[1], argv[2]);

    if (entries) {
        free(entries);
    }

    return EXIT_SUCCESS;
}
