    bool crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t size;
    size_t capacity;
    size_t successful_crc_count;
    size_t failed_crc_count;
    pthread_mutex_t mutex;
} CRC_Indication_Manager;

void initialize_manager(CRC_Indication_Manager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(manager->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->successful_crc_count = 0;
    manager->failed_crc_count = 0;
}

void destroy_manager(CRC_Indication_Manager* manager) {
    free(manager->pdus);
    pthread_mutex_destroy(&manager->mutex);
}

bool resize_array(CRC_Indication_Manager* manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) return false;
    manager->pdus = new_pdus;
    manager->capacity = new_capacity;
    return true;
}

bool add_pdu(CRC_Indication_Manager* manager, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity && !resize_array(manager, manager->capacity * 2)) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    manager->pdus[manager->size++] = *pdu;

    if (pdu->crc_rel8_tag.crcflag) {
        manager->successful_crc_count++;
    } else {
        manager->failed_crc_count++;
    }

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

bool remove_pdu(CRC_Indication_Manager* manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->size) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    if (manager->pdus[index].crc_rel8_tag.crcflag) {
        manager->successful_crc_count--;
    } else {
        manager->failed_crc_count--;
    }

    memmove(&manager->pdus[index], &manager->pdus[index + 1], (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;

    if (manager->size > 0 && manager->size == manager->capacity / 4) {
        resize_array(manager, manager->capacity / 2);
    }

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

void get_crc_statistics(const CRC_Indication_Manager* manager, size_t* successful_count, size_t* failed_count) {
    pthread_mutex_lock((pthread_mutex_t*)&manager->mutex);

    *successful_count = manager->successful_crc_count;
    *failed_count = manager->failed_crc_count;

    pthread_mutex_unlock((pthread_mutex_t*)&manager->mutex);
}
