    free(manager->table);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_or_update_structure(NFAManager *manager, NFAPI_CRC_INDICATION_PDU_T structure) {
    unsigned int index = hash(structure.RNTI);

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->table[index];
    while (current != NULL) {
        if (current->data.RNTI == structure.RNTI) {
            current->data.crc_tag.CRC_FLAG = rand(); // Simulating random CRC flag generation
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }

    Node *new_node = malloc(sizeof(Node));
    new_node->data = structure;
    new_node->next = manager->table[index];
    manager->table[index] = new_node;

    pthread_mutex_unlock(&manager->lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_structure(NFAManager *manager, unsigned long rnti) {
    unsigned int index = hash(rnti);

    pthread_mutex_lock(&manager->lock);

    Node *current = manager->table[index];
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

int main() {
    NFAManager *manager = create_manager();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 100, .RNTI = 12345 };
    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 101, .RNTI = 67890 };

    add_or_update_structure(manager, pdu1);
    add_or_update_structure(manager, pdu2);

    NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = get_structure(manager, 12345);
    if (retrieved_pdu) {
        printf("Retrieved RNTI: %lu\n", retrieved_pdu->RNTI);
        free(retrieved_pdu);
    }

    destroy_manager(manager);

    return 0;
}
