}

bool validate_unique_rntis(NFAPI_CRC_INDICATION_PDU_T *array, size_t count) {
    bool hash_table[1000003] = { false };

    for (size_t i = 0; i < count; ++i) {
        unsigned int hashed_value = custom_hash(array[i].RNTI);
        if (hash_table[hashed_value]) {
            return false;
        }
        hash_table[hashed_value] = true;
    }

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_nfa(nsize_t n, int *error_code) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

