}

void log_operation(const char *operation) {
    printf("Operation: %s\n", operation);
}

void batch_add(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *batch, size_t count) {
    pthread_mutex_lock(&list->lock);
    if (list->size + count > list->capacity) {
        size_t new_capacity = list->capacity;
        while (new_capacity < list->size + count)
            new_capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle error
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    memcpy(list->data + list->size, batch, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size += count;

    if (list->size > COMPRESSION_THRESHOLD) {
        compress_data(list);
    }

    validate_integrity(list);
    adjust_compression_threshold(list);
    log_operation("Batch Add");
    pthread_mutex_unlock(&list->lock);
}

void batch_update(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *batch, size_t count) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < list->size; ++j) {
            if (list->data[j].RNTI == batch[i].RNTI) {
                list->data[j] = batch[i];
                break;
            }
        }
    }

    validate_integrity(list);
    adjust_compression_threshold(list);
    log_operation("Batch Update");

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_by_rnti(CRCList *list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->is_compressed) {
        decompress_data(list);
