    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *result = list->data[i];
            pthread_mutex_unlock(&list->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}
