#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_THREADS 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

// Initialize dynamic list
void init_dynamic_list(DynamicList *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

// Resize dynamic list
void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

// Add structure to the dynamic list
void add_to_dynamic_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        resize_dynamic_list(list, list->capacity * 2);
    }

    list->data[list->size++] = item;

    pthread_mutex_unlock(&list->lock);
}

// Serialize the dynamic list
int serialize_list(const DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Deserialize the dynamic list
int deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    size_t new_size = list->capacity;
    while (fread(list->data + list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        if (++list->size == new_size) {
            resize_dynamic_list(list, new_size * 2);
        }
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Cleanup dynamic list
void free_dynamic_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

// Worker function for concurrent access
void* worker(void *arg) {
    DynamicList *list = (DynamicList *)arg;
    NFAPI_CRC_INDICATION_PDU_T item;

    // Simulate random data
    item.RX_UE_INFORMATION_TAG = rand() % 100;
    item.RNTI = rand();
    for (int i = 0; i < 16; ++i) {
        item.CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }

    add_to_dynamic_list(list, item);
    return NULL;
}

// Main function
void manage_nfa_pdu_list(size_t N, size_t realloc_threshold, int threads) {
    if (threads > MAX_THREADS || threads < 1) {
        fprintf(stderr, "Invalid number of threads\n");
        return;
    }

    DynamicList list;
    init_dynamic_list(&list, 10);

    pthread_t thread_ids[threads];
    for (int i = 0; i < threads; ++i) {
        if (pthread_create(&thread_ids[i], NULL, worker, &list) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < threads; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    serialize_list(&list, "nfa_pdu_data.bin");

    free_dynamic_list(&list);
}

// Unit test example
void run_tests() {
    printf("Running tests...\n");

    // Test initialization and cleanup
    DynamicList list;
    init_dynamic_list(&list, 10);
    NFAPI_CRC_INDICATION_PDU_T item = {0};
    add_to_dynamic_list(&list, item);
    free_dynamic_list(&list);

    // More tests can be added here
}

int main() {
    run_tests();
    manage_nfa_pdu_list(100, 50, 4);
    return 0;
}
