#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000

typedef struct {
    int sequenceNumber;
    char payload[256];
    time_t timestamp;
} Packet;

typedef struct {
    Packet *packets[MAX_PACKETS];
    size_t count;
    pthread_mutex_t lock;
} TrafficFlow;

typedef struct {
    unsigned long sourceIP;
    unsigned long destinationIP;
    int protocolType;
    TrafficFlow flow;
} NetworkPacket;

void initializeTrafficFlow(TrafficFlow *flow, float dropProbability) {
    memset(flow->packets, 0, sizeof(flow->packets));
    flow->count = 0;
    pthread_mutex_init(&flow->lock, NULL);
    srand(time(NULL)); // Seed random number generator
}

int shouldDropPacket(float dropProbability) {
    return (rand() / (RAND_MAX + 1.0)) < dropProbability;
}

void addPacket(TrafficFlow *flow, Packet packet, float dropProbability) {
    pthread_mutex_lock(&flow->lock);

    if (flow->count >= MAX_PACKETS || shouldDropPacket(dropProbability)) {
        pthread_mutex_unlock(&flow->lock);
        return; // Drop the packet
    }

    flow->packets[flow->count] = malloc(sizeof(Packet));
    memcpy(flow->packets[flow->count], &packet, sizeof(Packet));
    flow->count++;

    pthread_mutex_unlock(&flow->lock);
}

Packet* getPacket(TrafficFlow *flow, size_t index) {
    pthread_mutex_lock(&flow->lock);

    Packet *pkt = (index < flow->count) ? flow->packets[index] : NULL;

    pthread_mutex_unlock(&flow->lock);
    return pkt;
}

void removePacket(TrafficFlow *flow, size_t index) {
    pthread_mutex_lock(&flow->lock);

    if (index < flow->count) {
        free(flow->packets[index]);
        for (size_t i = index; i < flow->count - 1; i++) {
            flow->packets[i] = flow->packets[i + 1];
        }
        flow->packets[--flow->count] = NULL;
    }

    pthread_mutex_unlock(&flow->lock);
}

void cleanupTrafficFlow(TrafficFlow *flow) {
    for (size_t i = 0; i < flow->count; i++) {
        free(flow->packets[i]);
    }
    pthread_mutex_destroy(&flow->lock);
}

NetworkPacket* initializeNetworkPacket(unsigned long sourceIP, unsigned long destinationIP, int protocolType, float dropProbability) {
    NetworkPacket *packet = malloc(sizeof(NetworkPacket));
    if (!packet) return NULL;

    packet->sourceIP = sourceIP;
    packet->destinationIP = destinationIP;
    packet->protocolType = protocolType;
    initializeTrafficFlow(&packet->flow, dropProbability);

    return packet;
}

void cleanupNetworkPacket(NetworkPacket *packet) {
    if (packet) {
        cleanupTrafficFlow(&packet->flow);
        free(packet);
    }
}
