    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    pthread_mutex_t mutex;
} CRCManager;

unsigned int hash(uint16_t RNTI) {
    return RNTI % TABLE_SIZE;
}

CRCManager* init_manager() {
    CRCManager* manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    manager->table = (HashNode**)calloc(TABLE_SIZE, sizeof(HashNode*));
    if (!manager->table) {
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_manager(CRCManager* manager) {
    if (!manager) return;

    for (int i = 0; i < TABLE_SIZE; i++) {
        HashNode* current = manager->table[i];
        while (current) {
            HashNode* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(manager->table);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_pdu(CRCManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!manager || !pdu) return -1;

    unsigned int index = hash(pdu->RNTI);

    pthread_mutex_lock(&manager->mutex);

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    new_node->data = *pdu;
    new_node->next = manager->table[index];
    manager->table[index] = new_node;

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

int update_pdu(CRCManager* manager, uint16_t RNTI, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!manager || !pdu) return -1;

    unsigned int index = hash(RNTI);

    pthread_mutex_lock(&manager->mutex);

    HashNode* current = manager->table[index];
    while (current) {
        if (current->data.RNTI == RNTI) {
            current->data = *pdu;
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->mutex);
    return -1; // Not found
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(CRCManager* manager, uint16_t RNTI) {
    if (!manager) return NULL;

    unsigned int index = hash(RNTI);

    pthread_mutex_lock(&manager->mutex);

    HashNode* current = manager->table[index];
    while (current) {
        if (current->data.RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* pdu_copy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu_copy) {
                pthread_mutex_unlock(&manager->mutex);
                return NULL;
            }
            *pdu_copy = current->data;
            pthread_mutex_unlock(&manager->mutex);
            return pdu_copy;
        }
        current = current->next;
    }

