        RX_UE_INFORMATION_TAG ue_info;
        ue_info.UE_identity = get_valid_ue_identity();

        int rnti = get_valid_rnti();
        if (rnti <= 0 || rnti > MAX_RNTI || rnti == last_rnti) {
            pthread_mutex_unlock(&mutex);
