        pdu_list[i].RNTI = rnti;
        pdu_list[i].crc_tag = crc_tag;

        pthread_mutex_unlock(&mutex);
        ++successes;
    }

    *success_count = successes;
    *failure_count = failures;

    log_deallocation(pdu_list, num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

