    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
} DynamicLinkedList;

// Function prototypes
DynamicLinkedList* createList();
void destroyList(DynamicLinkedList* list);
int addElement(DynamicLinkedList* list, NFAPI_CRC_INDICATION_PDU_T element);
int removeElementByRNTI(DynamicLinkedList* list, unsigned short rnti);
Node* findElementByRNTI(Node* head, unsigned short rnti);
void insertSorted(DynamicLinkedList* list, Node* newNode);
void batchAddElements(DynamicLinkedList* list, NFAPI_CRC_INDICATION_PDU_T elements[], size_t count);
void batchRemoveElementsByRNTI(DynamicLinkedList* list, unsigned short rntis[], size_t count);
void iterateForward(DynamicLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T));
void iterateReverse(DynamicLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T));

DynamicLinkedList* createList() {
    DynamicLinkedList* list = (DynamicLinkedList*)malloc(sizeof(DynamicLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

void destroyList(DynamicLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int addElement(DynamicLinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->data = element;
    newNode->next = NULL;
    insertSorted(list, newNode);
    list->size++;
    return 0;
}

int removeElementByRNTI(DynamicLinkedList* list, unsigned short rnti) {
    if (!list || !list->head) return -1;

    Node *current = list->head, *prev = NULL;
    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) return -1; // Not found

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->size--;
    return 0;
}

Node* findElementByRNTI(Node* head, unsigned short rnti) {
    while (head) {
        if (head->data.RNTI == rnti) return head;
        head = head->next;
    }
    return NULL;
}

void insertSorted(DynamicLinkedList* list, Node* newNode) {
    if (!list || !newNode) return;

    Node **tracer = &(list->head);
    while (*tracer && (*tracer)->data.RNTI < newNode->data.RNTI) {
        tracer = &((*tracer)->next);
    }

    newNode->next = *tracer;
    *tracer = newNode;
}

void batchAddElements(DynamicLinkedList* list, NFAPI_CRC_INDICATION_PDU_T elements[], size_t count) {
    if (!list || !elements) return;

    for (size_t i = 0; i < count; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) continue; // Skip on allocation failure

        newNode->data = elements[i];
        newNode->next = NULL;
        insertSorted(list, newNode);
    }
}

void batchRemoveElementsByRNTI(DynamicLinkedList* list, unsigned short rntis[], size_t count) {
    if (!list || !rntis) return;

    for (size_t i = 0; i < count; ++i) {
        removeElementByRNTI(list, rntis[i]);
    }
}

void iterateForward(DynamicLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return;

    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }
}

void iterateReverse(DynamicLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !callback) return;

    Node *stack[10000]; // Assuming max size 10,000 as per the problem statement
    int top = -1;
    Node* current = list->head;

    while (current) {
        stack[++top] = current;
        current = current->next;
    }

    while (top >= 0) {
        callback(stack[top--]->data);
    }
}

// Example usage of the callback function
void printElement(NFAPI_CRC_INDICATION_PDU_T data) {
    printf("RNTI: %u, RX_UE_INFORMATION_TAG: %d, CRCFLAG: %d\n",
           data.RNTI, data.RX_UE_INFORMATION_TAG, data.CRCFLAG);
}

int main() {
    DynamicLinkedList* list = createList();

    NFAPI_CRC_INDICATION_PDU_T elements[] = {
        {1, 100, 2, 1},
        {2, 200, 3, 0},
        {3, 150, 4, 1}
    };
    batchAddElements(list, elements, 3);

    iterateForward(list, printElement);
    printf("\n");
    iterateReverse(list, printElement);

    removeElementByRNTI(list, 200);
    iterateForward(list, printElement);

    destroyList(list);
    return 0;
}
```

