    manager->capacity = 10; // Initial capacity
    manager->array = malloc(manager->capacity * sizeof(LTE_RRC_MIB_INFO));
    if (!manager->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
