static void resize_array_if_needed(MIB_Manager *manager) {
    if (atomic_load(&manager->size) >= atomic_load(&manager->capacity)) {
        size_t new_capacity = atomic_load(&manager->capacity) * 2;
        LTE_RRC_MIB_INFO *new_array = realloc(manager->array, new_capacity * sizeof(LTE_RRC_MIB_INFO));
        if (!new_array) {
