    unsigned char RX_UE_INFORMATION_TAG[8];
    unsigned short CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pduA = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pduB = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return (int)pduA->RNTI - (int)puduB->RNTI;
}

void sort_linked_list(LinkedList* list) {
    if (!list || list->size < 2) return;

    Node** array = (Node**)malloc(list->size * sizeof(Node*));
    if (!array) return; // Handle allocation failure gracefully

    Node* current = list->head;
    for (int i = 0; i < list->size; i++) {
        array[i] = current;
        current = current->next;
    }

    qsort(array, list->size, sizeof(Node*), compare_rnti);

    for (int i = 0; i < list->size - 1; i++) {
        array[i]->next = array[i + 1];
        array[i + 1]->prev = array[i];
    }
    array[0]->prev = NULL;
    array[list->size - 1]->next = NULL;

    list->head = array[0];
    list->tail = array[list->size - 1];

    free(array);
}

int add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failure

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = new_node->prev = NULL;

    if (!list->head || list->head->data.RNTI > pdu.RNTI) {
        new_node->next = list->head;
        if (list->head) list->head->prev = new_node;
        list->head = new_node;
        if (!list->tail) list->tail = new_node;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.RNTI < pdu.RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
        if (!new_node->next) list->tail = new_node;
    }

    list->size++;
    return 0; // Success
}

int remove_pdu(LinkedList* list, unsigned int rnti) {
    if (!list || !list->head) return -1;

    Node* current = list->head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current) return -2; // PDU not found

    if (current->prev) current->prev->next = current->next;
    else list->head = current->next;

    if (current->next) current->next->prev = current->prev;
    else list->tail = current->prev;

    free(current);
    list->size--;
    return 0; // Success
}

void* get_node_by_rnti(LinkedList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current && current->data.RNTI != rnti) {
        current = current->next;
    }
    return current ? &current->data : NULL; // Return pointer to data or NULL
}

void iterate_reverse(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !list->tail || !callback) return;

    Node* current = list->tail;
    while (current) {
        callback(&current->data);
        current = current->prev;
    }
}

void log_performance(LinkedList* list, const char* message) {
    printf("Performance Log: %s - List Size: %d\n", message, list->size);
}

