    RX_UE_INFORMATION_TAG ue_info_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rnti, CRC_INDICATION_REL8_TAG crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_tag;
    pdu->next = NULL;
    return pdu;
}

void add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    pthread_mutex_lock(&list->lock);

    if (!new_pdu) return;

    NFAPI_CRC_INDICATION_PDU_T** current = &list->head;
    while (*current && (*current)->rnti < new_pdu->rnti) {
        current = &(*current)->next;
    }

    if (*current && (*current)->rnti == new_pdu->rnti) {
        // Handle duplicate RNTI: skip insertion
        free(new_pdu);
    } else {
        new_pdu->next = *current;
        *current = new_pdu;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T** current = &list->head;
    while (*current && (*current)->rnti != rnti) {
        current = &(*current)->next;
    }

    if (*current) {
        NFAPI_CRC_INDICATION_PDU_T* to_delete = *current;
        *current = (*current)->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
}

void batch_add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T** pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        add_pdu(list, pdus[i]);
    }
}

void batch_remove_pdu(DynamicList* list, int* rntis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        remove_pdu(list, rntis[i]);
    }
}

void iterate_list_forward(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list_reverse(DynamicList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // Reverse iteration requires a stack or similar data structure.
    // This is not trivial with a linked list and would require additional traversal.

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T** stack = NULL;
    size_t stack_size = 0;

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        stack = realloc(stack, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (stack_size + 1));
        if (!stack) break; // Handle memory allocation failure
        stack[stack_size++] = current;
        current = current->next;
    }

    for (size_t i = stack_size; i > 0; --i) {
        callback(stack[i - 1]);
    }

    free(stack);

    pthread_mutex_unlock(&list->lock);
}

// Database integration, error handling, logging, and other features would be implemented here.
```

