// Function to check if a file is corrupted or missing
int is_config_valid(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 0; // File not found

    // Check for corruption (simple validation: non-empty)
    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    rewind(file);

    char buffer[1];
    if (length == 0 || fread(buffer, 1, 1, file) != 1) {
        fclose(file);
        return 0;
    }

    fclose(file);
    return 1;
}

// Function to read configuration and populate data
int read_config(const char *filename, UE_CONFIG_INFO **config_list, size_t *num_entries) {
    if (!is_config_valid(filename)) {
        return -1; // File is corrupted or missing
    }

    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    // Assuming a simple CSV format for the config file
    char line[256];
    size_t capacity = 10;
    *config_list = malloc(capacity * sizeof(UE_CONFIG_INFO));
    size_t count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (count >= capacity) {
            capacity *= 2;
            *config_list = realloc(*config_list, capacity * sizeof(UE_CONFIG_INFO));
        }

        // Parse the line
        UE_CONFIG_INFO config;
        sscanf(line, "%31[^,],%u", config.RX_UE_INFORMATION_TAG, &config.RNTI);
        (*config_list)[count++] = config;
    }

    fclose(file);
    *num_entries = count;
    return 0; // Success
}

// Function to dynamically allocate and populate the array of structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(const char *filename, size_t N, int *error_code) {
    UE_CONFIG_INFO *config_list = NULL;
    size_t num_entries = 0;

    if (read_config(filename, &config_list, &num_entries)) {
        *error_code = -1; // Error in reading config
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        free(config_list);
        *error_code = -2; // Memory allocation error
        return NULL;
    }

    for (size_t i = 0; i < N && i < num_entries; ++i) {
        strcpy(pdu_array[i].crc_tag.crc_flag, config_list[i].RX_UE_INFORMATION_TAG);
        pdu_array[i].RNTI = config_list[i].RNTI;

        // Set CRCFLAG based on parity of RNTI
        if (pdu_array[i].RNTI % 2 == 0) {
            pdu_array[i].crc_tag.CRCFLAG = 1; // Example value for even RNTI
        } else {
            pdu_array[i].crc_tag.CRCFLAG = 0; // Example value for odd RNTI
        }
    }

    // Fill remaining structures with default values if N > num_entries
    for (size_t i = num_entries; i < N; ++i) {
        strcpy(pdu_array[i].crc_tag.crc_flag, "DEFAULT_RX_UE_INFO");
        pdu_array[i].RNTI = 0;
        pdu_array[i].crc_tag.CRCFLAG = 1; // Default CRCFLAG
    }

    free(config_list);
    *error_code = 0; // Success
    return pdu_array;
}

// Function to deallocate the array
void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}
