    if (*sessions == NULL) {
        fprintf(stderr, "Memory allocation failed for session events\n");
        exit(EXIT_FAILURE);
    }
    *size = 0;
}

// Add a new session event to the list
int addSessionEvent(SessionEvent **sessions, size_t *size, SessionEvent newEvent) {
