    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    return -1;
}

PDUList* create_pdu_list() {
    PDUList *list = malloc(sizeof(PDUList));
    if (!list) return NULL;

    list->pdus = malloc(MAX_PDUS * sizeof(PDU));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_pdu_to_list(PDUList *list, const PDU *pdu) {
    if (pthread_mutex_lock(&list->lock)) {
        log_error("Mutex lock failed");
        return -1;
    }

    if (list->count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Exceeded maximum PDUs
    }

    memcpy(&(list->pdus[list->count]), pdu, sizeof(PDU));
    list->count++;

    int success = pthread_mutex_unlock(&list->lock);
    if (success != 0) {
        log_error("Mutex unlock failed");
        return -1;
    }

    return 0; // Success
}

void cleanup_pdu_list(PDUList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    free(list->pdus);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
