        PDU pdu;
        snprintf(pdu.source_ip, sizeof(pdu.source_ip), "192.168.1.%zu", i);
        snprintf(pdu.dest_ip, sizeof(pdu.dest_ip), "10.0.0.%zu", i);
        pdu.src_port = 12345 + (unsigned short)i;
        pdu.dst_port = 80;
        pdu.packet_loss_status = (i % 5 == 0) ? 1 : 0;

        int result = add_pdu_to_list(pdu_list, &pdu);
        if (result < 0 && result != -2) {
            log_error("Error adding PDU to list");
            cleanup_pdu_list(pdu_list);
            return result;
        }
    }

    printf("Number of PDUs successfully created: %zu\n", pdu_list->count);

    // Integrate with external data source
    fetch_network_topology_data();

    cleanup_pdu_list(pdu_list);
    return 0;
}
