NetworkElementStatus* initializeNetworkElements(size_t num_elements, size_t measurement_points_per_element, int retries, FILE *log_file) {
    NetworkElementStatus *elements = NULL;
    size_t i;

    elements = (NetworkElementStatus *)calloc(num_elements, sizeof(NetworkElementStatus));
    if (!elements) {
        fprintf(log_file, "Memory allocation failed for network elements.\n");
        return NULL;
    }

    for (i = 0; i < num_elements; ++i) {
