        // Retry mechanism for fetching configuration
        for (int attempt = 0; attempt <= retries; ++attempt) {
            if (fetchConfig(&NodeID, &CellID) == 0) {
                break;
            }
            if (attempt < retries) {
                fprintf(log_file, "Fetch config failed, retrying... (%d/%d)\n", attempt + 1, retries);
            } else {
                fprintf(log_file, "Failed to fetch configuration after %d attempts.\n", retries + 1);
                elements[i].NodeID = -1;
                elements[i].CellID = -1;
                continue;
            }
        }

        elements[i].NodeID = NodeID;
        elements[i].CellID = CellID;

        // Allocate memory for measurement data
        elements[i].data.MeasurementData = (int *)calloc(measurement_points_per_element, sizeof(int));
        if (!elements[i].data.MeasurementData) {
            fprintf(log_file, "Memory allocation failed for MeasurementData at index %zu.\n", i);
            --i; // Adjust index to remove uninitialized element
            continue;
        }
        elements[i].data.measurement_count = measurement_points_per_element;

        // Example: Populate with dummy data (replace as needed)
        for (size_t j = 0; j < measurement_points_per_element; ++j) {
            elements[i].data.MeasurementData[j] = rand() % 100;
        }
    }

    return elements;
}

// Function to free allocated resources
void cleanupNetworkElements(NetworkElementStatus *elements, size_t num_elements) {
    if (elements) {
        for (size_t i = 0; i < num_elements; ++i) {
            if (elements[i].data.MeasurementData) {
                free(elements[i].data.MeasurementData);
            }
        }
        free(elements);
    }
}

