#define SECURITY_KEY_SIZE 16

typedef enum {
    RRC_DISCONNECTED,
    RRC_CONNECTED,
    // Add other statuses as needed
} RRCConnectionStatus;

typedef struct {
    uint8_t key[SECURITY_KEY_SIZE];
} SecurityContext;

typedef struct {
    int ueId;
    RRCConnectionStatus rrcStatus;
    SecurityContext securityContext;
} UESessionData;

// Define a dynamic array structure for UESessions
typedef struct {
    UESessionData *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex; // For thread-safe operations
} DynamicArrayUESessions;

// Function to initialize the dynamic array
DynamicArrayUESessions* initDynamicArray(size_t initialCapacity) {
    DynamicArrayUESessions *array = (DynamicArrayUESessions *)malloc(sizeof(DynamicArrayUESessions));
    if (!array) return NULL;

    array->data = (UESessionData *)calloc(initialCapacity, sizeof(UESessionData));
    array->size = 0;
    array->capacity = initialCapacity;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

// Function to add a new UESessionData
int addUESession(DynamicArrayUESessions *array, int ueId, RRCConnectionStatus rrcStatus) {
    if (pthread_mutex_lock(&array->mutex)) return -1;

    // Resize the array if necessary
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        UESessionData *newData = realloc(array->data, newCapacity * sizeof(UESessionData));
        if (!newData) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->data = newData;
        array->capacity = newCapacity;
    }

    // Add new session data
    UESessionData *session = &array->data[array->size++];
    session->ueId = ueId;
    session->rrcStatus = rrcStatus;

    // Generate a random security key (using rand for simplicity, replace with secure RNG)
    for (int i = 0; i < SECURITY_KEY_SIZE; ++i) {
        session->securityContext.key[i] = rand() % 256;
    }

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Function to update the security context of a UESessionData
int updateSecurityContext(DynamicArrayUESessions *array, int ueId) {
    if (pthread_mutex_lock(&array->mutex)) return -1;

    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].ueId == ueId) {
            // Update the security key
            for (int j = 0; j < SECURITY_KEY_SIZE; ++j) {
                array->data[i].securityContext.key[j] = rand() % 256;
            }
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1;
}

// Function to serialize UESessionData
size_t serializeUESession(const UESessionData *session, uint8_t **buffer) {
    size_t headerSize = sizeof(session->ueId) + sizeof(session->rrcStatus) + SECURITY_KEY_SIZE;
    *buffer = malloc(headerSize);
    if (!*buffer) return 0;

    memcpy(*buffer, &session->ueId, sizeof(session->ueId));
    memcpy(*buffer + sizeof(session->ueId), &session->rrcStatus, sizeof(session->rrcStatus));
    memcpy(*buffer + sizeof(session->ueId) + sizeof(session->rrcStatus), session->securityContext.key, SECURITY_KEY_SIZE);

    return headerSize;
}

// Function to deserialize UESessionData
int deserializeUESession(const uint8_t *buffer, size_t bufferSize, UESessionData *session) {
    if (bufferSize < sizeof(session->ueId) + sizeof(session->rrcStatus) + SECURITY_KEY_SIZE) return -1;

    memcpy(&session->ueId, buffer, sizeof(session->ueId));
    memcpy(&session->rrcStatus, buffer + sizeof(session->ueId), sizeof(session->rrcStatus));
    memcpy(session->securityContext.key, buffer + sizeof(session->ueId) + sizeof(session->rrcStatus), SECURITY_KEY_SIZE);

    return 0;
}

// Function to free the dynamic array
void freeDynamicArray(DynamicArrayUESessions *array) {
    if (array) {
        pthread_mutex_destroy(&array->mutex);
        free(array->data);
        free(array);
    }
}
