int load_resource_bundle(const char *file_path, int partial_loading, char **bundle_data, size_t *size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return 0;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    if (partial_loading && file_size > 1024) { // Example threshold for partial loading
        file_size = 1024; // Load only the first 1KB as an example
    }

    *size = file_size;
    *bundle_data = malloc(file_size);
    if (!*bundle_data) {
        fclose(file);
        return 0;
    }

    fread(*bundle_data, 1, file_size, file);
    fclose(file);

    return (int)(*size);
}

