typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG *crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFList;

NFList* create_list() {
    NFList *list = (NFList*)malloc(sizeof(NFList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_unique_rnti(NFList *list, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void add_pdu(NFList *list, int rx_ue_info_tag, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique_rnti(list, rnti)) {
        fprintf(stderr, "Error: Duplicate RNTI %u detected.\n", rnti);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_pdu->RNTI = rnti;
    new_pdu->crc_tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    srand(time(NULL)); // Seed for randomness
    new_pdu->crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    new_pdu->next = list->head;
    list->head = new_pdu;

    pthread_mutex_unlock(&list->lock);
}

void free_list(NFList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current->crc_tag);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void serialize_list(NFList *list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file %s for writing.\n", filename);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        fwrite(&(current->RX_UE_INFORMATION_TAG), sizeof(int), 1, file);
        fwrite(&(current->RNTI), sizeof(unsigned int), 1, file);
        fwrite(current->crc_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
}

void check_integrity(NFList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (!current->crc_tag) {
            fprintf(stderr, "Integrity Check Failed: Dangling pointer detected.\n");
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void resize_list(NFList *list, int new_capacity) {
    // This function can be expanded to handle dynamic resizing logic
    // Placeholder for future implementation
}

int main() {
    NFList *list = create_list();

    add_pdu(list, 1, 1001);
    add_pdu(list, 2, 1002);
    add_pdu(list, 3, 1001); // Duplicate RNTI test

    serialize_list(list, "nfa_list.bin");
    check_integrity(list);

    free_list(list);

    return 0;
}
