['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <string.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    double average_crc_rate_last_minute;
    double success_percentage_last_10_seconds;
    time_t last_update_time;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->average_crc_rate_last_minute = 0.0;
    da->success_percentage_last_10_seconds = 0.0;
    da->last_update_time = time(NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_destroy(&da->lock);
        free(da->array);
        free(da);
    }
}

bool resize_if_needed(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return false;
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    pthread_mutex_unlock(&da->lock);
    return true;
}

bool add_pdu(DynamicArray* da, uint16_t rnti) {
    if (!resize_if_needed(da)) return false;

    pthread_mutex_lock(&da->lock);

    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i].RNTI == rnti) {
            pthread_mutex_unlock(&da->lock);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &da->array[da->count++];
    pdu->RX_UE_INFORMATION_TAG = rand(); // Assume random unique
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = (rand() % 2 == 0);

    pthread_mutex_unlock(&da->lock);
    return true;
}

void update_real_time_metrics(DynamicArray* da) {
    time_t current_time = time(NULL);
    double elapsed_minutes = difftime(current_time, da->last_update_time) / 60.0;

    if (elapsed_minutes >= 1.0) {
        pthread_mutex_lock(&da->lock);

        // Calculate average CRC rate over the last minute
        size_t crc_count_last_minute = 0;
        for (size_t i = 0; i < da->count && difftime(current_time, da->array[i].timestamp) <= 60.0; ++i) {
            if (da->array[i].CRCFLAG) crc_count_last_minute++;
        }
        da->average_crc_rate_last_minute = (double)crc_count_last_minute / da->count;

        // Calculate success percentage over the last 10 seconds
        size_t total_copies_last_10_seconds = 0;
        size_t successful_copies_last_10_seconds = 0;
        for (size_t i = 0; i < da->count && difftime(current_time, da->array[i].timestamp) <= 10.0; ++i) {
            total_copies_last_10_seconds++;
            if (da->array[i].CRCFLAG) successful_copies_last_10_seconds++;
        }
        da->success_percentage_last_10_seconds = (total_copies_last_10_seconds > 0)
                                                  ? (double)(successful_copies_last_10_seconds * 100.0 / total_copies_last_10_seconds)
                                                  : 0.0;

        pthread_mutex_unlock(&da->lock);

        // Reset last update time
        da->last_update_time = current_time;
    }
}

void log_error(const char* message) {
    fprintf(stderr, "[%ld] ERROR: %s\n", (long)time(NULL), message);
}

int main() {
    DynamicArray* da = create_dynamic_array(1000);

    if (!da) {
        log_error("Failed to initialize dynamic array.");
        return 1;
    }

    for (uint16_t rnti = 1; rnti <= MAX_ELEMENTS; ++rnti) {
        if (!add_pdu(da, rnti)) {
            log_error("Failed to add PDU or duplicate RNTI detected.");
            break;
        }
    }

    while (true) {
        update_real_time_metrics(da);
        // Simulate processing delay
        usleep(1000); 
    }

    destroy_dynamic_array(da);
    return 0;
}
```

### Key Features:
- **Dynamic Array Management**: Efficiently resizes and manages a dynamic array.
- **Thread Safety**: Uses mutexes to ensure safe concurrent access.
- **Real-Time Metrics**: Computes average CRC rate over the last minute and success percentage for the past 10 seconds.
- **Error Handling**: Logs errors with timestamps for better monitoring.
- **Performance Considerations**: Resizes array as needed, ensuring efficient memory usage.

This implementation considers high-concurrency environments by using mutexes to manage thread safety. For lock-free data structures or more sophisticated concurrency controls, further exploration into libraries like `libcds` or advanced atomic operations might be required.']

