#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int create_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array, int *num_elements) {
    if (!array || !num_elements) return -1; // Invalid parameters

    int requested_size = 0; // This should be set by the user before calling this function
    int actual_size = (requested_size > MAX_ELEMENTS) ? MAX_ELEMENTS : requested_size;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    *array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(actual_size * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!*array) {
        pthread_mutex_unlock(&lock);
        pthread_mutex_destroy(&lock);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < actual_size; ++i) {
        (*array)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!(*array)[i]) {
            while (--i >= 0) free((*array)[i]);
            free(*array);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            return -2; // Memory allocation failed
        }

        // Simulate external data source with potential latency or failure
        int success = simulate_external_data_source(&(*array)[i]->RX_UE_INFORMATION_TAG, &(*array)[i]->RNTI);
        if (!success) {
            free((*array)[i]);
            (*array)[i] = NULL;
            continue; // Handle failure gracefully by skipping the element
        }

        (*array)[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    *num_elements = actual_size;
    return 0; // Success
}

void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array, int num_elements) {
    if (!array) return;

    for (int i = 0; i < num_elements; ++i) {
        if (*array && (*array)[i]) free((*array)[i]);
    }
    if (*array) free(*array);
}

// Simulated external data source function
int simulate_external_data_source(uint32_t *RX_UE_INFORMATION_TAG, uint16_t *RNTI) {
    // For demonstration purposes, assume a fixed success rate or introduce random failure
    if (rand() % 10 == 0) return 0; // 10% chance of failure

    *RX_UE_INFORMATION_TAG = rand();
    *RNTI = rand() & 0xFFFF;
    return 1; // Success
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    int num_elements = 0;

    if (create_dynamic_array(&array, &num_elements) == 0) {
        printf("Successfully created %d elements.\n", num_elements);
        free_dynamic_array(&array, num_elements);
    } else {
        printf("Failed to create dynamic array.\n");
    }

    return 0;
}
