Node* create_node(const NetworkInterfaceStatus* status) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    memcpy(&node->data, status, sizeof(NetworkInterfaceStatus));
    node->next = NULL;
    return node;
}

void add_status(InterfaceList* list, const NetworkInterfaceStatus* status) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = create_node(status);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new interface status.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;

    // Log the change
    printf("Status updated: %s is now %s\n", 
           status->status ? "up" : "down",
           status->interface_id);

    pthread_mutex_unlock(&list->lock);
}

void remove_status(InterfaceList* list, const char* interface_id) {
    pthread_mutex_lock(&list->lock);

    Node **curr = &list->head;
    while (*curr) {
        if (strcmp((*curr)->data.interface_id, interface_id) == 0) {
            Node *temp = *curr;
            *curr = temp->next;
            free(temp);
            printf("Interface %s removed from status list.\n", interface_id);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        curr = &(*curr)->next;
    }

    fprintf(stderr, "Interface ID not found: %s\n", interface_id);
    pthread_mutex_unlock(&list->lock);
}

void free_interface_list(InterfaceList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

