#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray *dyn_array = malloc(sizeof(DynamicArray));
    if (!dyn_array) return NULL;

    dyn_array->array = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->capacity = initial_capacity;
    dyn_array->size = 0;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

int is_valid(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Add validation logic for RX_UE_INFORMATION_TAG and RNTI
    return pdu && pdu->RX_UE_INFORMATION_TAG >= 0 && pdu->RNTI >= 0;
}

void add_pdu(DynamicArray *dyn_array, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!is_valid(pdu)) {
        fprintf(stderr, "Invalid PDU\n");
        return;
    }

    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size == dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dyn_array->lock);
            return; // Handle memory allocation failure
        }
        dyn_array->array = new_array;
        dyn_array->capacity = new_capacity;
    }

    dyn_array->array[dyn_array->size++] = *pdu;

    pthread_mutex_unlock(&dyn_array->lock);
}

void clear_dynamic_array(DynamicArray *dyn_array) {
    if (dyn_array) {
        pthread_mutex_lock(&dyn_array->lock);

        free(dyn_array->array);
        dyn_array->array = NULL;
        dyn_array->capacity = 0;
        dyn_array->size = 0;

        pthread_mutex_unlock(&dyn_array->lock);
        pthread_mutex_destroy(&dyn_array->lock);
        free(dyn_array);
    }
}

int serialize_dynamic_array(const DynamicArray *dyn_array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock((pthread_mutex_t*)&dyn_array->lock);

    size_t write_size = dyn_array->size;
    fwrite(&write_size, sizeof(size_t), 1, file);
    fwrite(dyn_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), dyn_array->size, file);

    pthread_mutex_unlock((pthread_mutex_t*)&dyn_array->lock);
    fclose(file);

    return 0;
}

int deserialize_dynamic_array(DynamicArray **dyn_array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t read_size;
    fread(&read_size, sizeof(size_t), 1, file);

    *dyn_array = create_dynamic_array(read_size);
    if (!*dyn_array) {
        fclose(file);
        return -1;
    }

    pthread_mutex_lock(&(*dyn_array)->lock);

    fread((*dyn_array)->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), read_size, file);

    (*dyn_array)->size = read_size;

    pthread_mutex_unlock(&(*dyn_array)->lock);
    fclose(file);

    return 0;
}

int main() {
    // Example usage
    DynamicArray *dyn_array = create_dynamic_array(10);
    if (!dyn_array) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = { .CRCFLAG = rand() % 256 } };
    add_pdu(dyn_array, &pdu);

    serialize_dynamic_array(dyn_array, "data.bin");

    DynamicArray *loaded_dyn_array;
    deserialize_dynamic_array(&loaded_dyn_array, "data.bin");

    clear_dynamic_array(loaded_dyn_array);
    return 0;
}
```

### Key Points:
- **Memory Management**: Uses `malloc`, `calloc`, and `realloc` for dynamic memory management.
- **Concurrency**: Utilizes `pthread_mutex_t` to ensure thread safety when modifying the array.
- **Serialization**: Supports binary serialization and deserialization.
- **Validation**: Includes basic validation logic for input data.
- **Extensibility**: Designed with future enhancements in mind, allowing easy addition of new features.']

