#include <stdio.h>
#include <stdlib.h>
import<stdint.h>

#define MAX_UES 10
#define MAX_SYMBOLS_PER_FRAME 1000
#define SYMBOL_SIZE 1024

typedef struct {
    int16_t real;
    int16_t imag;
} LTE_PHY_RX_SAMPLE_T;

typedef struct {
    LTE_PHY_RX_SAMPLE_T *samples;
    size_t num_samples;
    uint32_t checksum; // To store the calculated checksum for validation
} LTE_PHY_RX_SYMBOL_T;

typedef struct {
    int UE_INDEX;
    LTE_PHY_RX_SYMBOL_T symbols[MAX_SYMBOLS_PER_FRAME];
    size_t symbol_count; // Number of symbols in this frame
} LTE_PHY_RX_FRAME_T;

uint32_t calculate_checksum(LTE_PHY_RX_SYMBOL_T *symbols, size_t count) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < symbols[i].num_samples; ++j) {
            checksum += symbols[i].samples[j].real + symbols[i].samples[j].imag;
        }
    }
    return checksum;
}

void initialize_random_sample(LTE_PHY_RX_SAMPLE_T *sample) {
    sample->real = rand() % 256 - 128; // Random value between -128 and 127
    sample->imag = rand() % 256 - 128;
}

int init_lte_phy_rx_frames(
    LTE_PHY_RX_FRAME_T frames[MAX_UES],
    int num_frames,
    size_t symbols_per_frame,
    size_t samples_per_symbol) {

    if (num_frames > MAX_UES || symbols_per_frame > MAX_SYMBOLS_PER_FRAME) {
        return -1; // Invalid configuration
    }

    for (int i = 0; i < num_frames; ++i) {
        frames[i].UE_INDEX = i;
        frames[i].symbol_count = symbols_per_frame;

        for (size_t j = 0; j < symbols_per_frame; ++j) {
            LTE_PHY_RX_SYMBOL_T *symbol = &frames[i].symbols[j];
            symbol->samples = (LTE_PHY_RX_SAMPLE_T *)malloc(samples_per_symbol * sizeof(LTE_PHY_RX_SAMPLE_T));

            if (!symbol->samples) {
                // Memory allocation failed, handle gracefully
                frames[i].symbol_count = j; // Truncate the number of symbols processed
                for (size_t k = 0; k < j; ++k) {
                    free(frames[i].symbols[k].samples); // Free previously allocated memory
                }
                return -2;
            }

            symbol->num_samples = samples_per_symbol;

            for (size_t k = 0; k < samples_per_symbol; ++k) {
                initialize_random_sample(&symbol->samples[k]);
            }
        }

        frames[i].checksum = calculate_checksum(frames[i].symbols, symbols_per_frame);
    }

    return 0;
}

void cleanup_lte_phy_rx_frames(LTE_PHY_RX_FRAME_T *frames, int num_frames) {
    for (int i = 0; i < num_frames; ++i) {
        for (size_t j = 0; j < frames[i].symbol_count; ++j) {
            free(frames[i].symbols[j].samples);
        }
    }
}

int main() {
    LTE_PHY_RX_FRAME_T frames[MAX_UES];
    int num_frames = MAX_UES;
    size_t symbols_per_frame = 100; // Example value, should be configurable
    size_t samples_per_symbol = SYMBOL_SIZE; // Example value, should depend on MCS

    if (init_lte_phy_rx_frames(frames, num_frames, symbols_per_frame, samples_per_symbol) == 0) {
        printf("Frames initialized successfully.\n");
    } else {
        printf("Failed to initialize frames.\n");
    }

    cleanup_lte_phy_rx_frames(frames, num_frames);
    return 0;
}
