#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int timerID;
    time_t startTimestamp;
    time_t duration;
    time_t expirationTime;
} LTEPHYTIMER;

typedef struct Node {
    LTEPHYTIMER data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TimerList;

TimerList* initializeTimerList() {
    TimerList* list = malloc(sizeof(TimerList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int addTimer(TimerList* list, LTEPHYTIMER timer) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (timer.startTimestamp < current->data.expirationTime &&
            (timer.startTimestamp + timer.duration) > current->data.startTimestamp) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Overlap detected
        }
        current = current->next;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    newNode->data = timer;
    newNode->data.expirationTime = timer.startTimestamp + timer.duration;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int removeTimer(TimerList* list, int timerID) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.timerID == timerID) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Timer not found
}

void freeTimerList(TimerList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void populateTimers(TimerList* list, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        LTEPHYTIMER timer;
        timer.timerID = rand() % 10000 + 1;
        time(&timer.startTimestamp);
        timer.duration = (rand() % 10 + 1) * 60; // Random duration between 1 to 10 minutes

        addTimer(list, timer);
    }
}

int main() {
    TimerList* list = initializeTimerList();
    if (!list) {
        fprintf(stderr, "Failed to initialize timer list.\n");
        return -1;
    }

    populateTimers(list, 100);

    // Example: Remove a timer with ID 1234
    removeTimer(list, 1234);

    freeTimerList(list);
    return 0;
}
```

