void* memory_allocate() {
    pthread_mutex_lock(&lock);
    if (pool_index < MEMORY_POOL_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &memory_pool[pool_index++];
        pthread_mutex_unlock(&lock);
        return pdu;
    }
    pthread_mutex_unlock(&lock);
    return NULL;  // Pool exhausted
}

void memory_deallocate() {
    pthread_mutex_lock(&lock);
    if (pool_index > 0) pool_index--;
    pthread_mutex_unlock(&lock);
}

void* generate_pdu(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)memory_allocate();
