    int key_id;
    void* key_data;
} CryptoKey;

CryptoKey* get_crypto_key(int key_id);
void release_crypto_key(CryptoKey* key);

#define MAX_THREADS 16
pthread_t worker_threads[MAX_THREADS];
int active_threads = 0;
pthread_mutex_t thread_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t thread_condition = PTHREAD_COND_INITIALIZER;

// Thread function to handle processing of PDUs
void* process_pdu_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    int length = *(int*)pdu_list; // First element holds the number of PDUs.
    pdu_list++; // Move to start of data.

    for (int i = 0; i < length; ++i) {
        pthread_mutex_lock(&thread_mutex);
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[i];

        log_message("Processing PDU");

        int key_id = rand() % 5 + 1; // Randomly select a crypto module (AES, Camellia, etc.)
        load_crypto_module(key_id == 1 ? "AES" : key_id == 2 ? "Camellia" : 
                           key_id == 3 ? "MD5" : key_id == 4 ? "SHA" : "RSA_SHA1");

        CryptoKey* crypto_key = get_crypto_key(key_id);
        perform_crypto_operation(crypto_key->key_id, (const unsigned char*)&pdu->CRC_INDICATION_REL8_TAG,
                                 sizeof(pdu->CRC_INDICATION_REL8_TAG));

        release_crypto_key(crypto_key);

        pthread_mutex_unlock(&thread_mutex);
    }

    return NULL;
}

// Function to dynamically adjust worker threads
void adjust_worker_threads(int target_thread_count) {
    pthread_mutex_lock(&thread_mutex);
    if (target_thread_count > active_threads) {
        int new_threads = target_thread_count - active_threads;
        for (int i = 0; i < new_threads && active_threads < MAX_THREADS; ++i) {
            pthread_create(&worker_threads[active_threads++], NULL, process_pdu_thread, NULL);
        }
    } else if (target_thread_count < active_threads) {
        int threads_to_stop = active_threads - target_thread_count;
        for (int i = 0; i < threads_to_stop && active_threads > 0; ++i) {
            pthread_cancel(worker_threads[--active_threads]);
        }
    }
    pthread_mutex_unlock(&thread_mutex);
}

// Main function to generate and process PDUs
void generateAndProcessNFAPDUs(NFAPI_CRC_INDICATION_PDU_T** pdu_list, int num_pdus) {
    srand(time(NULL));

