    int current_load_threads = (num_pdus / 10) + 1; // Example heuristic for thread allocation.
    adjust_worker_threads(current_load_threads);

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(worker_threads[i], NULL);
    }
}

