#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define WIRELESS_SAMPLE_T int16_t
#define WIRELESS_SYMBOL_T WIRELESS_SAMPLE_T*
#define MAX_SAMPLES 1024

typedef struct {
    uint32_t cell_id;
    size_t num_symbols;
    WIRELESS_SYMBOL_T* symbols;
    uint64_t checksum;
} WIRELESS_CHANNEL_FRAME_T;

typedef struct {
    WIRELESS_CHANNEL_FRAME_T** frames;
    size_t frame_count;
    size_t capacity;
    pthread_mutex_t lock;
} FrameList;

uint64_t calculate_checksum(WIRELESS_SYMBOL_T symbol, size_t num_samples) {
    uint64_t checksum = 0;
    for (size_t i = 0; i < num_samples; ++i) {
        checksum += symbol[i];
    }
    return checksum;
}

void* populate_symbol(void* arg) {
    WIRELESS_CHANNEL_FRAME_T* frame = (WIRELESS_CHANNEL_FRAME_T*)arg;
    size_t num_samples = MAX_SAMPLES / frame->num_symbols;

    for (size_t i = 0; i < frame->num_symbols; ++i) {
        frame->symbols[i] = malloc(num_samples * sizeof(WIRELESS_SAMPLE_T));
        if (!frame->symbols[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < num_samples; ++j) {
            frame->symbols[i][j] = rand() % 1024 - 512;
        }

        uint64_t symbol_checksum = calculate_checksum(frame->symbols[i], num_samples);
        frame->checksum += symbol_checksum;
    }

    return NULL;
}

void initialize_frame_list(FrameList* list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);

    list->frames = malloc(initial_capacity * sizeof(WIRELESS_CHANNEL_FRAME_T*));
    if (!list->frames) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    list->frame_count = 0;
    list->capacity = initial_capacity;
}

void add_frame(FrameList* list, uint32_t cell_id, size_t num_symbols) {
    pthread_mutex_lock(&list->lock);

    if (list->frame_count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        WIRELESS_CHANNEL_FRAME_T** new_frames = realloc(list->frames, new_capacity * sizeof(WIRELESS_CHANNEL_FRAME_T*));
        if (!new_frames) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->frames = new_frames;
        list->capacity = new_capacity;
    }

    WIRELESS_CHANNEL_FRAME_T* frame = malloc(sizeof(WIRELESS_CHANNEL_FRAME_T));
    if (!frame) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }

    frame->cell_id = cell_id;
    frame->num_symbols = num_symbols;
    frame->symbols = malloc(num_symbols * sizeof(WIRELESS_SYMBOL_T));
    if (!frame->symbols) {
        fprintf(stderr, "Memory allocation failed\n");
        free(frame);
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }

    frame->checksum = 0;

    list->frames[list->frame_count++] = frame;
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, populate_symbol, (void*)frame);
    pthread_detach(thread_id);

    pthread_mutex_unlock(&list->lock);
}

void free_frame_list(FrameList* list) {
