typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Function to generate a random number within a range.
unsigned int rand_range(unsigned int min, unsigned int max) {
    return min + (rand() % (max - min + 1));
}

// Function to create and populate linked list of NFAPI_CRC_INDICATION_PDU_T structures.
ListNode* generate_crc_indication_list(int n) {
    if (n <= 0) return NULL;

    ListNode* head = NULL;
    ListNode* current = NULL;

    for (int i = 0; i < n; ++i) {
        // Allocate memory for new node
        ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }

        // Populate data with random values
        newNode->data.RX_UE_INFORMATION_TAG = rand_range(0, 10000);
        newNode->data.RNTI = rand_range(0, 10000);
        for (int j = 0; j < 4; ++j) {
            newNode->data.CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }

        // Randomly set CRCFLAG
        unsigned char *CRCFLAG = &newNode->data.CRC_INDICATION_REL8_TAG[3];
        *CRCFLAG = (*CRCFLAG & 0x7F) | ((rand() % 2) << 7);

        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

// Function to free the linked list
void free_crc_indication_list(ListNode* head) {
    ListNode *temp;

    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

