#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define INITIAL_SIZE 10

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void init_dynamic_list(DynamicList *list, size_t initial_size) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_size;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resize_dynamic_list(list);
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
}

void free_dynamic_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

int read_from_socket(int sockfd, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate reading data from a socket
    if (recv(sockfd, pdu, sizeof(*pdu), 0) != sizeof(*pdu)) {
        perror("Failed to read from socket");
        return -1;
    }
    return 0;
}

void process_network_data(int sockfd, DynamicList *list) {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (1) {
        if (read_from_socket(sockfd, &pdu) < 0) {
            fprintf(stderr, "Error reading from socket\n");
            continue; // Graceful degradation
        }

        // Perform data validation and handle corruption scenarios
        if (!pdu.RX_UE_INFORMATION_TAG || !pdu.RNTI) {
            fprintf(stderr, "Invalid data format detected\n");
            continue;
        }

        add_pdu(list, pdu);
    }
}

void log_processing_info(size_t processed_count, size_t error_count) {
    printf("Processed PDUs: %zu, Errors encountered: %zu\n", processed_count, error_count);
}

void cleanup(DynamicList *list) {
    free_dynamic_list(list);
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return EXIT_FAILURE;
    }

    // Set up server address and connect
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to connect");
        return EXIT_FAILURE;
    }

    DynamicList list;
    init_dynamic_list(&list, INITIAL_SIZE);

    process_network_data(sockfd, &list);

    cleanup(&list);

    close(sockfd);
    return EXIT_SUCCESS;
}
