    NFAPI_RX_MESSAGE_PDU_T* new_data = (NFAPI_RX_MESSAGE_PDU_T*)aligned_alloc(16, new_capacity * sizeof(NFAPI_RX_MESSAGE_PDU_T));

    for (size_t i = 0; i < list->count; ++i) {
        new_data[i] = list->data[i]; // Copy existing data
    }

    free(list->data);
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_pdu(DynamicList* list, unsigned long context_tag, unsigned short rnti, PHY_RX_STATS_TAG stats) {
