#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    uint32_t unique_rnti_count;
    uint64_t total_crcflag;
    pthread_mutex_t mutex;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    list->unique_rnti_count = 0;
    list->total_crcflag = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->mutex);

    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->data.RNTI == entry.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return 0; // RNTI already exists
        }
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed
    }

    memcpy(&new_node->data, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    list->unique_rnti_count++;
    list->total_crcflag += entry.crc_tag.CRCFLAG;

    pthread_mutex_unlock(&list->mutex);
    return 1; // Successfully added
}

int update_entry(CRCList* list, uint16_t rnti, CRC_INDICATION_REL8_TAG new_crc_flag) {
    pthread_mutex_lock(&list->mutex);

    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->data.RNTI == rnti) {
            list->total_crcflag -= node->data.crc_tag.CRCFLAG;
            node->data.crc_tag.CRCFLAG = new_crc_flag.CRCFLAG;
            list->total_crcflag += new_crc_flag.CRCFLAG;
            pthread_mutex_unlock(&list->mutex);
            return 1; // Successfully updated
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return 0; // RNTI not found
}

int remove_entry(CRCList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);

    Node **indirect = &list->head;
    while (*indirect) {
        if ((*indirect)->data.RNTI == rnti) {
            Node *to_delete = *indirect;
            *indirect = to_delete->next;
            list->count--;
            list->total_crcflag -= to_delete->data.crc_tag.CRCFLAG;

            free(to_delete);
            pthread_mutex_unlock(&list->mutex);
            return 1; // Successfully removed
        }
        indirect = &(*indirect)->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0; // RNTI not found
}

void report_statistics(CRCList* list) {
    pthread_mutex_lock(&list->mutex);

    float average_crcflag = (float)list->count ? (float)list->total_crcflag / list->count : 0.0f;

    printf("Total Entries: %zu\n", list->count);
    printf("Unique RNTIs: %u\n", list->unique_rnti_count);
    printf("Average CRCFLAG: %.2f\n", average_crcflag);

    pthread_mutex_unlock(&list->mutex);
}

int main() {
    // Example usage
    CRCList* crc_list = create_list();
    if (!crc_list) return -1;

    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = 12345;
    entry.RNTI = 6789;
    entry.crc_tag.CRCFLAG = rand() % 256; // Random CRC flag

    add_entry(crc_list, entry);
    report_statistics(crc_list);

    CRC_INDICATION_REL8_TAG new_crc_flag = { .CRCFLAG = rand() % 256 };
    update_entry(crc_list, entry.RNTI, new_crc_flag);
    report_statistics(crc_list);

    remove_entry(crc_list, entry.RNTI);
    report_statistics(crc_list);

    free_list(crc_list);
    return 0;
}
```

