int add_pdu(PDUList* list, int rx_tag, int rnti, int crc_tag, const char* crc_flag) {
    if (crc_flag == NULL || strlen(crc_flag) != 3) {
        fprintf(stderr, "Invalid CRCFLAG\n");
        return -1;
