['Below is a C++ implementation that addresses the requirements using modern C++ features such as `std::mutex`, `std::shared_mutex` for read-write locks, and concurrent data structures from the C++ standard library.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <optional>
#include <queue>
#include <condition_variable>

struct NetworkEvent {
    std::string sessionID;
    std::string clientIP;
    std::chrono::system_clock::time_point timestamp;

    bool operator==(const NetworkEvent& other) const {
        return sessionID == other.sessionID && clientIP == other.clientIP;
    }
};

namespace std {
    template <>
    struct hash<NetworkEvent> {
        size_t operator()(const NetworkEvent& event) const {
            return hash<std::string>()(event.sessionID) ^ hash<std::string>()(event.clientIP);
        }
    };
}

class EventManager {
public:
    void addEvent(const std::string& sessionID, const std::string& clientIP) {
        auto now = std::chrono::system_clock::now();
        NetworkEvent event{sessionID, clientIP, now};

        std::unique_lock lock(mutex_);
        events_.insert(event);
        logOperation("ADD", event);

        if (events_.size() > cacheLimit_) {
            flushCache();
        }
    }

    bool removeEvent(const std::string& sessionID) {
        NetworkEvent dummy{sessionID, "", {}};
        std::shared_lock lock(mutex_);
        auto it = events_.find(dummy);
        if (it != events_.end()) {
            logOperation("REMOVE", *it);
            std::unique_lock ulock(mutex_, std::adopt_lock);
            events_.erase(it);
            return true;
        }
        return false;
    }

    std::optional<NetworkEvent> getEvent(const std::string& sessionID) const {
        NetworkEvent dummy{sessionID, "", {}};
        std::shared_lock lock(mutex_);
        auto it = events_.find(dummy);
        if (it != events_.end()) {
            return *it;
        }
        return std::nullopt;
    }

private:
    void logOperation(const std::string& operation, const NetworkEvent& event) const {
        std::lock_guard<std::mutex> logLock(logMutex_);
        logs_.push_back({operation, event.sessionID, event.clientIP, std::chrono::system_clock::to_time_t(event.timestamp)});
        if (logs_.size() > logLimit_) {
            rotateLogs();
        }
    }

    void flushCache() {
        while (!cacheQueue_.empty()) {
            auto event = cacheQueue_.front();
            cacheQueue_.pop();
            std::unique_lock lock(mutex_);
            events_.insert(event);
        }
    }

    void rotateLogs() {
        logs_.erase(logs_.begin(), logs_.begin() + logLimit_ / 2);
    }

    mutable std::shared_mutex mutex_;
    std::unordered_map<NetworkEvent, bool> events_;
    std::vector<std::tuple<std::string, std::string, std::time_t>> logs_;
    mutable std::mutex logMutex_;

    const size_t cacheLimit_ = 100;
    const size_t logLimit_ = 1000;

    std::queue<NetworkEvent> cacheQueue_;
};

// Unit tests and stress testing can be implemented using a test framework like Google Test.
```

