typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RETRIES 3

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += *((unsigned int*)&data[i]);
    }
    return checksum % 256;
}

int validate_memory(NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    unsigned int original_checksum = calculate_checksum(data, count);
    for (size_t i = 0; i < count; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand(); // Simulate a small change
    }
    unsigned int new_checksum = calculate_checksum(data, count);
    return (original_checksum == new_checksum); // If same, corruption likely occurred
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pcu_indication_pdu(size_t N) {
    pthread_mutex_lock(&lock);

    size_t retries = 0;
    while (retries < MAX_RETRIES) {
        NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!array) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        for (size_t i = 0; i < N; ++i) {
            array[i].RX_UE_INFORMATION_TAG = rand(); // Assign a random valid value
            array[i].RNTI = rand();                  // Assign a random valid value
            array[i].crcTag.CRCFLAG = (i % 2 == 0) ? 1 : 0;
        }

        if (!validate_memory(array, N)) {
            free(array);
            fprintf(stderr, "Memory corruption detected. Retrying allocation...\n");
            retries++;
        } else {
            pthread_mutex_unlock(&lock);
            return array; // Successful allocation and validation
        }
    }

    pthread_mutex_unlock(&lock);

    fprintf(stderr, "Failed to allocate memory after %zu attempts\n", MAX_RETRIES);
    return NULL;
}

void free_nfa_pcu_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
