#include <pthread.h>
#include <unistd.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPIList;

#define MAX_THREADS 4

pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
int active_threads = 0;

void init_list(NFAPIList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    memcpy(new_node->data.CRC_INDICATION_REL8_TAG, data.CRC_INDICATION_REL8_TAG, 4);
    new_node->data.RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = data.RNTI;
    new_node->data.CRCFLAG = data.CRCFLAG;
    new_node->next = NULL;

    return new_node;
}

void add_to_list(NFAPIList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    while (active_threads >= MAX_THREADS) {
        pthread_cond_wait(&cond, &list->lock);
    }
    active_threads++;

    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&list->lock);

    // Notify callback (if implemented)
}

void* process_event(void* arg) {
    NFAPIList* list = (NFAPIList*)arg;

    // Simulate event processing
    usleep(100000);  // Sleep for simulation purposes

    pthread_mutex_lock(&list_lock);
    active_threads--;
    if (active_threads < MAX_THREADS && cond != PTHREAD_COND_INITIALIZER) {
        pthread_cond_signal(&cond);
    }
    pthread_mutex_unlock(&list_lock);

    return NULL;
}

void cleanup_list(NFAPIList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
}

int main() {
    NFAPIList nfa_list;
    init_list(&nfa_list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 2, {0x00, 0x01, 0x02, 0x03}, 12345};
    add_to_list(&nfa_list, example_pdu);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_event, &nfa_list);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_list(&nfa_list);

    return 0;
}
```

### Key Features:
- **Thread Safety:** Uses mutex and condition variables to handle concurrent access.
- **Dynamic Memory Management:** Gracefully handles memory allocation failures.
- **Concurrency Limitation:** Limits the number of active threads processing events.
- **Event Simulation:** Demonstrates how to process incoming events using threads.

This code provides a basic structure for managing the list, handling concurrency, and ensuring thread safety. You can expand it with serialization/deserialization, log integrity checks, and integration with external services as needed.']

