void init_crc_array_manager(CRCArrayManager *manager) {
    manager->data = NULL;
    manager->size = 0;
    manager->capacity = 0;
    memset(manager->used_tags, 0, sizeof(manager->used_tags));
}

int is_tag_used(CRCArrayManager *manager, uint8_t tag) {
    return manager->used_tags[tag] != 0;
}

void mark_tag_as_used(CRCArrayManager *manager, uint8_t tag) {
    if (tag < RX_UE_INFO_TAG_MAX) {
        manager->used_tags[tag] = 1;
    }
}

void unmark_tag_as_used(CRCArrayManager *manager, uint8_t tag) {
    if (tag < RX_UE_INFO_TAG_MAX) {
        manager->used_tags[tag] = 0;
    }
}

int add_crc_pdu(CRCArrayManager *manager) {
    if (manager->size >= MAX_ARRAY_SIZE) return -1;

    size_t new_capacity = manager->capacity == 0 ? 4 : manager->capacity * 2;
    if ((new_capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T) > 1024) {
        new_capacity = MAX_ARRAY_SIZE;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp_data = realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) return -1;

    manager->data = temp_data;
    manager->capacity = new_capacity;

    uint8_t tag;
    do {
        tag = rand() % RX_UE_INFO_TAG_MAX;
    } while (is_tag_used(manager, tag));

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->data[manager->size++];
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rand(); // Example RNTI value
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    mark_tag_as_used(manager, tag);

    return 0;
}

void clear_crc_array_manager(CRCArrayManager *manager) {
    free(manager->data);
    manager->data = NULL;
    manager->size = 0;
    manager->capacity = 0;
    memset(manager->used_tags, 0, sizeof(manager->used_tags));
}

void validate_crc_flags(const CRCArrayManager *manager) {
