```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCIndicationManager;

static uint32_t generate_random_uint32() {
    return rand();
}

CRCIndicationManager* create_manager(size_t initial_capacity) {
    CRCIndicationManager *manager = (CRCIndicationManager*)malloc(sizeof(CRCIndicationManager));
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_manager(CRCIndicationManager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_pdu(CRCIndicationManager *manager, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity || sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->capacity >= MAX_ARRAY_SIZE) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG ||
            manager->array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void clear_manager(CRCIndicationManager *manager) {
    pthread_mutex_lock(&manager->lock);
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
}

int merge_arrays(CRCIndicationManager *manager, NFAPI_CRC_INDICATION_PDU_T *new_array, size_t new_count) {
    pthread_mutex_lock(&manager->lock);

    if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * (manager->count + new_count) > MAX_ARRAY_SIZE) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < new_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = new_array[i];
        if (pdu.RX_UE_INFORMATION_TAG == 0 || pdu.RNTI == 0) continue;

        int exists = 0;
        for (size_t j = 0; j < manager->count; ++j) {
            if (manager->array[j].RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG ||
                manager->array[j].RNTI == pdu.RNTI) {
                exists = 1;
                break;
            }
        }

        if (!exists && add_pdu(manager, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI)) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int find_index_by_rnti(CRCIndicationManager *manager, uint16_t RNTI) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == RNTI) {
            pthread_mutex_unlock(&manager->lock);
            return i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int serialize_manager(CRCIndicationManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->count, file);

    fclose(file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int deserialize_manager(CRCIndicationManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);

    if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_count > MAX_ARRAY_SIZE) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_count);
    manager->capacity = new_count;
    fread(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_count, file);

    manager->count = new_count;

    fclose(file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}
```

