int resize_pdu_array(PDUArray* pdu_array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(pdu_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return -1;

    pdu_array->capacity = new_capacity;
    pdu_array->array = temp;
    return 0;
}

int populate_pdu_array(PDUArray* pdu_array, size_t N) {
    pthread_mutex_lock(&pdu_array->lock);

    if (N > pdu_array->capacity) {
        while (pdu_array->capacity < N) {
            size_t new_capacity = pdu_array->capacity * 2;
            int resize_result = resize_pdu_array(pdu_array, new_capacity);
            if (resize_result == -1) {
                log_message("Error: Insufficient memory during resizing.");
                pthread_mutex_unlock(&pdu_array->lock);
                return -1;
            }
        }
    }

    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        uint16_t unique_tag = rand() % UINT16_MAX + 1;

        while (unique_tag == pdu_array->array[i].RX_UE_INFORMATION_TAG) {
