    size_t count;
    pthread_mutex_t lock;
} DynamicList;

// Initialize the dynamic list
int init_dynamic_list(DynamicList *dl) {
    dl->list = NULL;
    dl->count = 0;
    if (pthread_mutex_init(&dl->lock, NULL) != 0) {
        return -1; // Mutex initialization failed
    }
    return 0;
}

// Destroy the dynamic list and free resources
void destroy_dynamic_list(DynamicList *dl) {
    pthread_mutex_lock(&dl->lock);
    if (dl->list != NULL) {
        free(dl->list);
        dl->list = NULL;
    }
    dl->count = 0;
    pthread_mutex_unlock(&dl->lock);
    pthread_mutex_destroy(&dl->lock);
}

// Add an element to the dynamic list
int add_element(DynamicList *dl, const LTE_PDCP_RX_SDU_INFO *info) {
    if (dl->count >= MAX_LIST_SIZE) {
        return -1; // List is full
    }

    pthread_mutex_lock(&dl->lock);

    if (dl->list == NULL) {
        dl->list = malloc(MAX_LIST_SIZE * sizeof(LTE_PDCP_RX_SDU_INFO));
        if (dl->list == NULL) {
            pthread_mutex_unlock(&dl->lock);
            return -2; // Memory allocation failed
        }
    }

    dl->list[dl->count++] = *info;

    pthread_mutex_unlock(&dl->lock);
    return 0;
}

// Retrieve an element from the dynamic list by index
int get_element(const DynamicList *dl, size_t index, LTE_PDCP_RX_SDU_INFO *out_info) {
