int allocate_and_populate_list(NFAPI_CRC_INDICATION_PDU_T **list, int max_size) {
    *list = NULL;
    int count = 0;

    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < max_size && count < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_pdu) {
            log_message("Memory allocation failed.");
            break;
