        new_pdu->RNTI = rand();
        new_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        NFAPI_CRC_INDICATION_PDU_T **temp_list = realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (count + 1));

        if (!temp_list) {
            log_message("Memory reallocation failed.");
            free(new_pdu);
            break;
        }

        *list = temp_list;
        (*list)[count] = new_pdu;
        count++;

        // Log successful allocation
        char log_buffer[LOG_BUFFER_SIZE];
        snprintf(log_buffer, sizeof(log_buffer), "Allocated PDU %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d",
                 count, new_pdu->RX_UE_INFORMATION_TAG, new_pdu->RNTI, new_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
        log_message(log_buffer);
    }

    pthread_mutex_unlock(&list_mutex);

    return count;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
    for (int i = 0; i < size; ++i) {
        free(list[i]);
    }
    free(list);
