NFAPI_RX_FRAME_T* initialize_nfa_frames(size_t n, size_t* actual_count) {
    if (n > MAX_FRAMES) {
        *actual_count = 0;
        log_error("Requested frame count exceeds maximum limit.");
        return NULL;
    }

    NFAPI_RX_FRAME_T* frames = malloc(n * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        log_error("Memory allocation failed for NFA frames.");
        *actual_count = 0;
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    int used_indices[MAX_FRAMES] = {0};
    size_t count = 0;

    for (size_t i = 0; i < n; ++i) {
        bool success = false;
        for (int attempt = 0; attempt < MAX_ATTEMPTS; ++attempt) {
            NFAPI_RX_FRAME_T* frame = &frames[i];
            int ts_index = rand() % MAX_FRAMES;

            // Check for uniqueness and retry if necessary
            for (size_t j = 0; j < count; ++j) {
                if (used_indices[j] == ts_index) {
                    ts_index += attempt + 1;
                    break;
                }
            }

            // Validate the index is unique in this context
            bool is_unique = true;
            for (size_t j = 0; j < count; ++j) {
                if (used_indices[j] == ts_index) {
                    is_unique = false;
                    break;
                }
            }

            if (is_unique) {
                frame->TS_INDEX = ts_index;
                used_indices[count++] = ts_index;

                // Populate with random RF_PATH_ID and RSSI
                frame->frame_data.RF_PATH_ID = rand() % 16; // Assuming 4-bit path ID
                frame->frame_data.RSSI = rand() % 101 - 100; // Random value between -100 and 0 dBm

                success = true;
                break;
            }
        }

        if (!success) {
            log_error("Failed to generate unique TS_INDEX after multiple attempts.");
            *actual_count = count;
            free(frames);
            return NULL;
        }
    }

    *actual_count = count;
    return frames;
}

int main() {
