#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_ENTRIES 10000

typedef struct {
    int rnti;
    char cellIdentity[20];
    struct {
        int signalStrength;
        time_t timestamp;
    } measurementReport;
} UEContext;

// Logging levels
typedef enum { LOG_NONE, LOG_INFO, LOG_DEBUG } LogLevel;
LogLevel currentLogLevel = LOG_INFO;

void logMessage(LogLevel level, const char *message) {
    if (level <= currentLogLevel) {
        printf("%s\n", message);
    }
}

pthread_mutex_t resize_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t cleanup_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct Node {
    UEContext context;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
} HashMap;

HashMap* hashMapCreate(size_t capacity) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    map->buckets = (Node**)calloc(capacity, sizeof(Node*));
    map->capacity = capacity;
    return map;
}

unsigned int hashFunction(int rnti, size_t capacity) {
    return (unsigned int)rnti % capacity;
}

void hashMapInsert(HashMap *map, UEContext context) {
    unsigned int index = hashFunction(context.rnti, map->capacity);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->context = context;
    newNode->next = map->buckets[index];
    map->buckets[index] = newNode;
}

UEContext* hashMapFind(HashMap *map, int rnti) {
    unsigned int index = hashFunction(rnti, map->capacity);
    Node* current = map->buckets[index];
    while (current != NULL) {
        if (current->context.rnti == rnti) {
            return &current->context;
        }
        current = current->next;
    }
    return NULL;
}

void hashMapDelete(HashMap *map, int rnti) {
    unsigned int index = hashFunction(rnti, map->capacity);
    Node* current = map->buckets[index];
    Node* prev = NULL;

    while (current != NULL) {
        if (current->context.rnti == rnti) {
            if (prev == NULL) {
                map->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void hashMapFree(HashMap *map) {
    for (size_t i = 0; i < map->capacity; ++i) {
        Node* current = map->buckets[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(map->buckets);
    free(map);
}

void resizeHashMap(HashMap *map, size_t newCapacity) {
    pthread_mutex_lock(&resize_lock);

    HashMap* newMap = hashMapCreate(newCapacity);
    for (size_t i = 0; i < map->capacity; ++i) {
        Node* current = map->buckets[i];
        while (current != NULL) {
            hashMapInsert(newMap, current->context);
            current = current->next;
        }
    }

    hashMapFree(map);

    *map = *newMap;

    pthread_mutex_unlock(&resize_lock);
}

void initializeUEContext(UEContext* context) {
    // Random RNTI
    context->rnti = rand() % 1000000;

    // Generate random Cell Identity
    snprintf(context->cellIdentity, sizeof(context->cellIdentity), "Cell-%06d", rand());

    // Assign randomized signal strength and current timestamp
    context->measurementReport.signalStrength = rand() % 100 + 1; // Random signal between 1 and 100
    context->measurementReport.timestamp = time(NULL);
}

void initializeUEContextArray(UEContext** array, size_t* capacity) {
    *capacity = 0;
    pthread_mutex_lock(&cleanup_lock);

    *array = (UEContext*)malloc(MAX_ENTRIES * sizeof(UEContext));
    if (*array == NULL) {
        logMessage(LOG_DEBUG, "Memory allocation failed for UEContext array.");
        return;
    }

    // Initialize hash map with initial capacity
