#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DEVICES 10000

typedef struct {
    char ip_address[16];
    char mac_address[18];
    int connection_stats;
} NetworkDevice;

typedef struct Node {
    NetworkDevice device;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DeviceList;

// Function prototypes
void init_device_list(DeviceList* list);
int add_device(DeviceList* list, const char* ip_address, const char* mac_address, int stats);
int remove_device(DeviceList* list, const char* ip_address);
void free_device_list(DeviceList* list);
Node* find_node_by_ip(Node* head, const char* ip_address);
int read_devices_from_file(const char* filename, DeviceList* list);
int write_devices_to_file(const char* filename, const DeviceList* list);
int handle_error(int code, const char* message);

// Initialize the device list
void init_device_list(DeviceList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Add a new network device to the list
int add_device(DeviceList* list, const char* ip_address, const char* mac_address, int stats) {
    if (pthread_mutex_lock(&list->lock)) return handle_error(1, "Mutex lock failed");

    Node* node = find_node_by_ip(list->head, ip_address);
    if (node != NULL) {
        pthread_mutex_unlock(&list->lock);
        return handle_error(2, "Device already exists");
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return handle_error(3, "Memory allocation failed");
    }

    strcpy(new_node->device.ip_address, ip_address);
    strcpy(new_node->device.mac_address, mac_address);
    new_node->device.connection_stats = stats;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove a network device from the list
int remove_device(DeviceList* list, const char* ip_address) {
    if (pthread_mutex_lock(&list->lock)) return handle_error(4, "Mutex lock failed");

    Node **indirect = &list->head;
    while (*indirect && strcmp((*indirect)->device.ip_address, ip_address)) {
        indirect = &(*indirect)->next;
    }

    if (!*indirect) {
        pthread_mutex_unlock(&list->lock);
        return handle_error(5, "Device not found");
    }

    Node* to_delete = *indirect;
    *indirect = (*indirect)->next;
    free(to_delete);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Free the device list
void free_device_list(DeviceList* list) {
    if (pthread_mutex_lock(&list->lock)) handle_error(6, "Mutex lock failed");

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Find a node by IP address
Node* find_node_by_ip(Node* head, const char* ip_address) {
    Node* current = head;
    while (current) {
        if (strcmp(current->device.ip_address, ip_address) == 0)
            return current;
        current = current->next;
    }
    return NULL;
}

// Read devices from a flat file
int read_devices_from_file(const char* filename, DeviceList* list) {
    FILE *file = fopen(filename, "r");
    if (!file) return handle_error(7, "File open failed");

    char ip[16], mac[18];
    int stats;
    while (fscanf(file, "%s %s %d\n", ip, mac, &stats) == 3) {
        add_device(list, ip, mac, stats);
    }

    fclose(file);
    return 0;
}

// Write devices to a flat file
int write_devices_to_file(const char* filename, const DeviceList* list) {
    FILE *file = fopen(filename, "w");
    if (!file) return handle_error(8, "File open failed");

    Node* current = list->head;
    while (current) {
        fprintf(file, "%s %s %d\n", current->device.ip_address,
                current->device.mac_address, current->device.connection_stats);
        current = current->next;
    }

    fclose(file);
    return 0;
}

// Handle errors
int handle_error(int code, const char* message) {
    fprintf(stderr, "Error %d: %s\n", code, message);
    return -1;
}
