    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_pdu_creation(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("PDU Created: RX_UE_INFO=%d, RNTI=%d, CRC_TAG=%d, CRC_FLAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
}

int generate_unique_rnti(int *used_rntis) {
    int rnti;
    while (1) {
        rnti = rand() % MAX_RNTI + 1;
        if (!used_rntis[rnti]) {
            used_rntis[rnti] = 1;
            break;
        }
    }
    return rnti;
}

NFAPI_CRC_INDICATION_PDU_T *create_pdus(int count, int *success_count) {
    if (count <= 0 || success_count == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int used_rx_info_tags[65536] = {0};
    int used_rntis[MAX_RNTI + 1] = {0};

    srand(time(NULL));

    *success_count = 0;

    for (int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        do {
            pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
        } while (used_rx_info_tags[pdu.RX_UE_INFORMATION_TAG]);
        used_rx_info_tags[pdu.RX_UE_INFORMATION_TAG] = 1;

        pdu.RNTI = generate_unique_rnti(used_rntis);

        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() & 0x01; // Random CRC flag

        pdus[i] = pdu;
        log_pdu_creation(&pdus[i]);

        (*success_count)++;
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}
