typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int data; // Example field
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *head;
    size_t node_count;
    pthread_mutex_t lock;
} LinkedList;

// Memory usage monitoring variables
size_t total_allocated_memory = 0;
const size_t MEMORY_THRESHOLD = 10 * 1024 * 1024; // 10 MB threshold for example

void init_linked_list(LinkedList *list) {
    list->head = NULL;
    list->node_count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int data) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->next = NULL;

    size_t node_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    total_allocated_memory += node_size;

    // Memory usage monitoring
    if (total_allocated_memory > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded!\n");
    }

    return new_node;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    size_t node_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    total_allocated_memory -= node_size;
    free(node);
}

void insert_head(LinkedList *list, int data) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
}

void delete_head(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = list->head;
    list->head = list->head->next;
    free_node(temp);
    list->node_count--;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free_node(current);
        current = next;
    }

    list->head = NULL;
    list->node_count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_linked_list(LinkedList *list) {
    cleanup_linked_list(list);
    pthread_mutex_destroy(&list->lock);
}
