        list[i].RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
        list[i].RNTI = data.RNTI;
        pthread_mutex_unlock(&lock);
    }

    *checksum = sum_checksum; // Set the running checksum

