#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure for LTE DL frame object
typedef struct {
    unsigned int validUEInfoTag;
    unsigned short RNTI;
    char *dlFrameMessageTag;
    unsigned char *downlinkDataBuffer;
    size_t bufferLength;
    unsigned char HARQProcessID; // Optional, set 0xFF if not used
} DLFrame;

// Structure for managing dynamic array of DL frames
typedef struct {
    DLFrame **frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    DLFrame **overflowFrames;
    size_t overflowCapacity;
    size_t overflowCount;
} DLFrameManager;

// Function to initialize the frame manager
void initDLFrameManager(DLFrameManager *manager, size_t initialCapacity) {
    manager->frames = malloc(initialCapacity * sizeof(DLFrame *));
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    // Initialize overflow queue
    manager->overflowFrames = malloc(initialCapacity * sizeof(DLFrame *));
    manager->overflowCapacity = initialCapacity;
    manager->overflowCount = 0;
}

// Function to resize the frame array dynamically
void resizeFrameArray(DLFrameManager *manager) {
    size_t newCapacity = manager->capacity * 2;
    DLFrame **newFrames = realloc(manager->frames, newCapacity * sizeof(DLFrame *));

    if (newFrames) {
        manager->frames = newFrames;
        manager->capacity = newCapacity;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Failed to resize frame array\n");
    }
}

// Function to add a DL frame to the manager
void addDLFrame(DLFrameManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        resizeFrameArray(manager);
    }

    // Allocate and initialize new DL frame with random data
    DLFrame *newFrame = malloc(sizeof(DLFrame));
    newFrame->validUEInfoTag = rand();
    newFrame->RNTI = rand() % 65536;
    newFrame->dlFrameMessageTag = strdup("DL Frame");

    // Random buffer length between 1 and 1024
    size_t randomBufferLength = (rand() % 1024) + 1;
    newFrame->downlinkDataBuffer = malloc(randomBufferLength);
    for (size_t i = 0; i < randomBufferLength; ++i) {
        newFrame->downlinkDataBuffer[i] = rand() % 256;
    }
    newFrame->bufferLength = randomBufferLength;

    // Random HARQ process ID, set to 0xFF if not used
    unsigned char harqID = (rand() % 10 == 0) ? 0xFF : rand() % 16;
    newFrame->HARQProcessID = harqID;

    manager->frames[manager->count++] = newFrame;

    pthread_mutex_unlock(&manager->mutex);
}

// Function to handle overflow frames
void handleOverflow(DLFrameManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->overflowCount >= manager->overflowCapacity) {
        // Resize overflow queue or discard oldest frame if necessary
        size_t newOverflowCapacity = manager->overflowCapacity * 2;
        DLFrame **newOverflowFrames = realloc(manager->overflowFrames, newOverflowCapacity * sizeof(DLFrame *));

        if (newOverflowFrames) {
            manager->overflowFrames = newOverflowFrames;
            manager->overflowCapacity = newOverflowCapacity;
        } else {
            // Discard oldest frame
            free(manager->overflowFrames[0]);
            memmove(manager->overflowFrames, manager->overflowFrames + 1, (--manager->overflowCount) * sizeof(DLFrame *));
        }
    }

    if (manager->count > manager->capacity) {
        // Move last frame to overflow queue
        DLFrame *lastFrame = manager->frames[--manager->count];
        manager->overflowFrames[manager->overflowCount++] = lastFrame;
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to clean up the frame manager
void cleanupDLFrameManager(DLFrameManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->downlinkDataBuffer);
        free(manager->frames[i]->dlFrameMessageTag);
        free(manager->frames[i]);
    }
    free(manager->frames);

    for (size_t i = 0; i < manager->overflowCount; ++i) {
        free(manager->overflowFrames[i]->downlinkDataBuffer);
        free(manager->overflowFrames[i]->dlFrameMessageTag);
        free(manager->overflowFrames[i]);
    }
    free(manager->overflowFrames);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

// Example usage
int main() {
    DLFrameManager manager;
    initDLFrameManager(&manager, 10);

    // Simulate adding frames
    for (int i = 0; i < 20; ++i) {
        addDLFrame(&manager);
    }

    handleOverflow(&manager);

    cleanupDLFrameManager(&manager);

    return 0;
}
