    if (!*nic_stats_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    int count = initial_size;
    for (int i = 0; i < count; ++i) {
        (*nic_stats_array)[i] = malloc(sizeof(NIC_Statistics));
        if (!(*nic_stats_array)[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
