        if (result != 0) {
            printf("Configuration service failure. Retrying...\n");
            sleep(1); // Graceful fallback with retry
        }

        pthread_mutex_unlock(&lock);
    } while (result != 0);

    *crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!*crc_indications) {
        fprintf(stderr, "Memory allocation failed for CRC indications.\n");
        // Free previously allocated NIC resources
        for (int i = 0; i < count; ++i) free((*nic_stats_array)[i]);
        free(*nic_stats_array);
        *nic_stats_array = NULL;
        return;
