use reqwest::Client;
use std::{sync::Arc, time::Duration};
use tokio::time::sleep;

#[derive(Debug)]
struct NetworkConfig {
    // Fields relevant to the network configuration update
}

async fn fetch_network_config(
    base_url: &str,
    enable_tls_validation: bool,
) -> Result<Vec<NetworkConfig>, reqwest::Error> {
    let client = Client::builder()
        .timeout(Duration::from_secs(10))
        .danger_accept_invalid_certs(!enable_tls_validation)
        .build()?;

    let mut response = client.get(format!("{}/config", base_url))
        .send()
        .await?;

    if response.status().is_success() {
        let configs: Vec<NetworkConfig> = response.json().await?;
        Ok(configs)
    } else {
        Err(response.error_for_status().unwrap_err())
    }
}

async fn fetch_with_retry(
    base_url: &str,
    enable_tls_validation: bool,
    retries: usize,
) -> Result<Vec<NetworkConfig>, reqwest::Error> {
    let mut attempts = 0;
    loop {
        match fetch_network_config(base_url, enable_tls_validation).await {
            Ok(configs) => return Ok(configs),
            Err(e) if attempts < retries => {
                eprintln!("Attempt {} failed: {}", attempts + 1, e);
                sleep(Duration::from_secs(2)).await;
                attempts += 1;
            }
            Err(e) => return Err(e),
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), reqwest::Error> {
    let base_url = "https://api.example.com";
    let enable_tls_validation = true; // Adjust as needed for environment
    let retries = 3;

    match fetch_with_retry(base_url, enable_tls_validation, retries).await {
        Ok(configs) => println!("Fetched configurations: {:?}", configs),
        Err(e) => eprintln!("Failed to fetch configurations: {}", e),
    }

    Ok(())
}
