#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} SlabAllocator;

void init_slab_allocator(SlabAllocator* allocator) {
    allocator->head = NULL;
    allocator->size = 0;
    pthread_mutex_init(&allocator->lock, NULL);
}

void destroy_slab_allocator(SlabAllocator* allocator) {
    Node* current = allocator->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&allocator->lock);
}

int add_pdu(SlabAllocator* allocator, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&allocator->lock);

    if (allocator->size >= MAX_ENTRIES) {
        pthread_mutex_unlock(&allocator->lock);
        fprintf(stderr, "Error: Maximum entries reached.\n");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&allocator->lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    memcpy(new_node->data.CRC_INDICATION_REL8_TAG, pdu.CRC_INDICATION_REL8_TAG, 16);
    new_node->data.RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = pdu.RNTI;

    new_node->next = allocator->head;
    allocator->head = new_node;
    allocator->size++;

    pthread_mutex_unlock(&allocator->lock);
    return 0;
}

void randomize_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->CRC_INDICATION_REL8_TAG[15] = rand() % 2; // Random CRCFLAG
}

int main() {
    SlabAllocator allocator;
    init_slab_allocator(&allocator);

    for (int i = 0; i < MAX_ENTRIES + 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i, .RNTI = i * 100 };
        randomize_crc_flag(&pdu);
        add_pdu(&allocator, pdu);
    }

    destroy_slab_allocator(&allocator);
    return 0;
}
```

