    if (!event_array) return NULL;

    event_array->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!event_array->events) {
        free(event_array);
        return NULL;
    }

    event_array->count = 0;
    event_array->capacity = initial_capacity;
    return event_array;
}

int add_network_event(EventArray *array, const char *src_ip, const char *dst_ip,
                      int protocol_type, size_t packet_size, unsigned long packet_id) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkEvent *new_events = realloc(array->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) return -1;

        array->events = new_events;
        array->capacity = new_capacity;
    }

    NetworkEvent event;
    time(&event.timestamp);
    strncpy(event.source_ip, src_ip, sizeof(event.source_ip) - 1);
    strncpy(event.destination_ip, dst_ip, sizeof(event.destination_ip) - 1);
    event.protocol_type = protocol_type;
    event.packet_size = packet_size;
    event.packet_id = packet_id;

    if (packet_size > PACKET_SIZE_THRESHOLD) {
        char log_message[LOG_BUFFER_SIZE];
        snprintf(log_message, LOG_BUFFER_SIZE,
                 "Large Packet Detected: ID=%lu, Size=%zu bytes", packet_id, packet_size);
        log_event(log_message);
    }

    array->events[array->count++] = event;
    return 0;
}

void free_event_array(EventArray *array) {
    if (array) {
        free(array->events);
        free(array);
    }
}
