        return NULL;
    }

    list->cells = (NFAPI_CELL_INFO_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CELL_INFO_PDU_T));
    if (!list->cells) {
        free(list);
        log_message(LOG_ERROR, "Failed to allocate memory for cells array");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;

    log_message(LOG_INFO, "Cell list initialized successfully");
    return list;
}

int add_cell(CellList *list, int cell_id, int tx_power_level, int rf_band) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CELL_INFO_PDU_T *new_cells = (NFAPI_CELL_INFO_PDU_T *)realloc(list->cells, new_capacity * sizeof(NFAPI_CELL_INFO_PDU_T));
        if (!new_cells) {
            log_message(LOG_ERROR, "Failed to reallocate memory for cells array");
            return -1;
        }

        list->cells = new_cells;
        list->capacity = new_capacity;
    }

    NFAPI_CELL_INFO_PDU_T *cell = &list->cells[list->count++];
    cell->cell_id = cell_id;
    cell->tx_power_level = tx_power_level;
    cell->rf_band = rf_band;

    log_message(LOG_DEBUG, "Cell added successfully");
    return 0;
}

void remove_cell(CellList *list, int index) {
    if (index < 0 || index >= list->count) {
        log_message(LOG_WARNING, "Invalid index for removing cell");
        return;
    }

    memmove(&list->cells[index], &list->cells[index + 1], (list->count - index - 1) * sizeof(NFAPI_CELL_INFO_PDU_T));
    list->count--;

    log_message(LOG_DEBUG, "Cell removed successfully");
}

void free_cell_list(CellList *list) {
    if (!list) return;

    free(list->cells);
    free(list);

    log_message(LOG_INFO, "Memory freed for cell list");
}

void log_message(LogLevel level, const char *message) {
    if (level <= current_log_level) {
        printf("[%s] %s\n", 
            (level == LOG_ERROR ? "ERROR" : 
             level == LOG_WARNING ? "WARNING" : 
             level == LOG_INFO ? "INFO" : "DEBUG"), message);
    }
}
