#define MAX_PACKETS 1024
#define PAYLOAD_SIZE 2048

typedef struct {
    int id;
    long timestamp;
    char payload[PAYLOAD_SIZE];
} LTE_Packet;

typedef struct PacketNode {
    LTE_Packet packet;
    struct PacketNode* next;
} PacketNode;

typedef struct {
    PacketNode* head;
    size_t count;
    pthread_mutex_t lock;
} PacketList;

PacketList* init_packet_list() {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_packet_node(PacketNode* node) {
    if (node) {
        free(node);
    }
}

LTE_Packet* add_packet(PacketList* list, LTE_Packet new_packet) {
    pthread_mutex_lock(&list->lock);

    PacketNode** current = &list->head;
    while (*current && (*current)->packet.id != new_packet.id) {
        current = &(*current)->next;
    }

    if (*current) { // Update existing packet
        memcpy(&(*current)->packet, &new_packet, sizeof(LTE_Packet));
    } else { // Add new packet
        PacketNode* node = (PacketNode*)malloc(sizeof(PacketNode));
        if (!node) {
            pthread_mutex_unlock(&list->lock);
            return NULL;
        }
        memcpy(&node->packet, &new_packet, sizeof(LTE_Packet));
        node->next = *current;
        *current = node;
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
    return (*current) ? &(*current)->packet : NULL;
}

LTE_Packet* get_packet(PacketList* list, int id) {
    pthread_mutex_lock(&list->lock);

    PacketNode* current = list->head;
    while (current && current->packet.id != id) {
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return current ? &current->packet : NULL;
}

void free_packet_list(PacketList* list) {
    pthread_mutex_lock(&list->lock);

    PacketNode* current = list->head;
    while (current) {
        PacketNode* next = current->next;
        free_packet_node(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    PacketList* packet_list = init_packet_list();

    LTE_Packet packet1 = {1, 1627894567, "Payload 1"};
    add_packet(packet_list, packet1);

    LTE_Packet packet2 = {2, 1627894570, "Payload 2"};
    add_packet(packet_list, packet2);

    LTE_Packet* retrieved_packet = get_packet(packet_list, 1);
    if (retrieved_packet) {
        printf("Packet ID: %d, Timestamp: %ld, Payload: %s\n", 
               retrieved_packet->id, retrieved_packet->timestamp, retrieved_packet->payload);
    }

    free_packet_list(packet_list);

    return 0;
}
