// Define the structure for CRC indication PDU.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the node of linked list.
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    bool crc_flag;  // Randomly generated CRC flag
    int sequence_number;  // Sequence number for tracking
    struct Node* next;
} Node;

// Define the head pointer and a mutex for thread safety.
Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the linked list with random data.
void initialize_list(int count) {
    pthread_mutex_lock(&list_mutex);
    Node *current = head, *prev = NULL;
    int i, sequence_number = 0;

    for (i = 0; i < count; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Failed to allocate memory");
            break;
        }

        // Randomly generate data
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        new_node->data.RNTI = rand() % 10000 + 1;
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 500 + 1;
        new_node->crc_flag = (rand() % 2) == 0; // Random boolean
        new_node->sequence_number = sequence_number++;
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        prev = current;
        current = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to iterate and process the list based on criteria.
void process_list(void (*process_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        if (current->crc_flag) {  // Example criterion
            process_func(&(current->data));
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Sample processing function for demonstration.
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
}

// Function to free the linked list.
void free_list() {
    pthread_mutex_lock(&list_mutex);

    Node* current = head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    head = NULL;

    pthread_mutex_unlock(&list_mutex);
}

// Example usage
int main() {
    initialize_list(10);  // Initialize list with 10 nodes
    process_list(print_pdu);  // Process and print each PDU
    free_list();  // Free the memory of the linked list

    return 0;
}
