    free(ptr);
}

void expand_capacity(PacketList *list) {
    size_t new_capacity = list->capacity * 2;
    LTE_Packet **new_packets = calloc(new_capacity, sizeof(LTE_Packet *));
    memcpy(new_packets, list->packets, list->count * sizeof(LTE_Packet *));
    custom_allocator_free(list->packets);
    list->packets = new_packets;
    list->capacity = new_capacity;
}

void add_packet(PacketList *list, LTE_Packet *packet) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        expand_capacity(list);
    }
    list->packets[list->count++] = packet;

    pthread_mutex_unlock(&list->lock);
}

LTE_Packet *get_packet(PacketList *list, int id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->id == id) {
            LTE_Packet *packet = list->packets[i];
            pthread_mutex_unlock(&list->lock);
            return packet;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void update_packet(PacketList *list, int id, LTE_Packet *new_data) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->packets[i]->id == id) {
            free(list->packets[i]->payload);
            list->packets[i]->payload_size = new_data->payload_size;
            list->packets[i]->payload = strdup(new_data->payload);
            list->packets[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void archive_old_packets(PacketList *list) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    for (size_t i = 0; i < list->count;) {
        if (difftime(current_time, list->packets[i]->timestamp) > ARCHIVE_AGE_THRESHOLD * 60) {
            free(list->packets[i]->payload);
            custom_allocator_free(list->packets[i]);
            memmove(&list->packets[i], &list->packets[i + 1],
                    (list->count - i - 1) * sizeof(LTE_Packet *));
            list->count--;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_packets(PacketList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        fprintf(file, "%d %ld %zu %s\n",
                list->packets[i]->id,
                list->packets[i]->timestamp,
                list->packets[i]->payload_size,
                list->packets[i]->payload);
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void memory_monitor(PacketList *list) {
    while (1) {
        sleep(MEMORY_MONITOR_INTERVAL);
        size_t used_memory = sizeof(PacketList) + list->capacity * sizeof(LTE_Packet *) +
                             list->count * (sizeof(LTE_Packet) + 1);

        printf("Memory usage: %zu bytes\n", used_memory);
    }
}

void persistent_flush(PacketList *list) {
    while (1) {
        sleep(FLUSH_INTERVAL);
        pthread_mutex_lock(&list->lock);

        // Implement logic to flush packets to persistent storage

        pthread_mutex_unlock(&list->lock);
    }
}

int main() {
    PacketList *packet_list = init_packet_list();

    pthread_t monitor_thread, flush_thread;
    pthread_create(&monitor_thread, NULL, (void *(*)(void *))memory_monitor, packet_list);
    pthread_create(&flush_thread, NULL, (void *(*)(void *))persistent_flush, packet_list);

    // Add more operations and logic as needed

    pthread_join(monitor_thread, NULL);
    pthread_join(flush_thread, NULL);

    // Cleanup
    for (size_t i = 0; i < packet_list->count; ++i) {
        free(packet_list->packets[i]->payload);
        custom_allocator_free(packet_list->packets[i]);
    }
    custom_allocator_free(packet_list->packets);
    pthread_mutex_destroy(&packet_list->lock);
    pthread_cond_destroy(&packet_list->cond);
    free(packet_list);

    return 0;
}
```

