        list->successful_transmissions++;

        double elapsed_time = (double)(clock() - start_time) / CLOCKS_PER_SEC;
        list->average_transmission_time = ((list->average_transmission_time * (list->successful_transmissions - 1)) + elapsed_time) / list->successful_transmissions;
    } else {
        list->failed_attempts++;
    }
}

