        ue_info[i].RNTI = rand() % 4096;
    }
    return 0; // Return success
}

// Memory allocation aligned to cache line boundaries
void *aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;  // Error handling for posix_memalign failure
    }
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);  // Normal free on non-Windows systems
#endif
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_crc_indication_list(size_t N, size_t *successful_allocations) {
    if (N == 0 || N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: N must be between 1 and %d\n", MAX_ELEMENTS);
        return NULL;
    }

    pthread_mutex_lock(&lock);

    UE_INFO *ue_info = aligned_malloc(N * sizeof(UE_INFO), CACHE_LINE_SIZE);
    if (!ue_info) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory allocation failed for RX_UE_INFORMATION_TAG array\n");
        return NULL;
    }

    int fetch_result = fetch_RX_UE_INFORMATION_TAG(ue_info, N);
    if (fetch_result != 0) {
        aligned_free(ue_info);
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Error fetching UE information\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = aligned_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T), CACHE_LINE_SIZE);
    if (!nfa_list) {
        aligned_free(ue_info);
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T list\n");
        return NULL;
    }

    *successful_allocations = 0;
    unsigned int checksum = 0;

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < N; ++i) {
        nfa_list[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        checksum += nfa_list[i].crc_indication_rel8_tag.CRCFLAG;
        nfa_list[i].crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG){.CRCFLAG = nfa_list[i].crc_indication_rel8_tag.CRCFLAG};

        // Here you can map or use the fetched RX_UE_INFORMATION_TAG and RNTI as required
    }

    if (*successful_allocations != N) {
        fprintf(stderr, "Allocation mismatch: expected %zu but got %zu\n", N, *successful_allocations);
        aligned_free(ue_info);
        aligned_free(nfa_list);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    printf("Checksum of all CRCFLAGS: %u\n", checksum);

    pthread_mutex_unlock(&lock);
    return nfa_list;  // Return the allocated list
}

