#define MAX_SEGMENTS 1024

typedef struct {
    int seq_num;
    char *payload;
    size_t payload_size;
    time_t timestamp; // External data source for timestamps
} SegmentHeader;

typedef struct {
    SegmentHeader header;
    int retransmitted:1;
    int dropped:1;
} TCP_Segment;

typedef struct {
    TCP_Segment segments[MAX_SEGMENTS];
    size_t count;
    size_t capacity;
    size_t successful_transmissions;
    size_t retransmissions;
    size_t dropped_packets;
} SegmentList;

SegmentList* create_segment_list(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_SEGMENTS) {
        return NULL;
    }

    SegmentList *list = (SegmentList *)malloc(sizeof(SegmentList));
    list->segments = (TCP_Segment *)calloc(initial_capacity, sizeof(TCP_Segment));
    list->count = 0;
    list->capacity = initial_capacity;
    list->successful_transmissions = 0;
    list->retransmissions = 0;
    list->dropped_packets = 0;

    return list;
}

void free_segment_list(SegmentList *list) {
    if (list == NULL) return;

    for (size_t i = 0; i < list->count; ++i) {
        free(list->segments[i].header.payload);
    }

    free(list->segments);
    free(list);
}

int add_segment(SegmentList *list, int seq_num, const char *payload_data, size_t payload_size) {
    if (list == NULL || payload_data == NULL || payload_size == 0) return -1;

    // Resize the list if needed
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_SEGMENTS) return -1;

        TCP_Segment *new_segments = (TCP_Segment *)realloc(list->segments, new_capacity * sizeof(TCP_Segment));
        if (new_segments == NULL) return -1;

        memset(new_segments + list->capacity, 0, (new_capacity - list->capacity) * sizeof(TCP_Segment));
        list->segments = new_segments;
        list->capacity = new_capacity;
    }

    // Add the segment
    TCP_Segment *segment = &list->segments[list->count++];
    segment->header.seq_num = seq_num;
    segment->header.payload = strdup(payload_data);
    segment->header.payload_size = payload_size;

    // Simulate timestamp retrieval delay handling
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts); 
    segment->header.timestamp = ts.tv_sec; 

    if (!segment->retransmitted && !segment->dropped) {
        list->successful_transmissions++;
    }

    return 0;
}

void handle_retransmission(SegmentList *list, int seq_num) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->segments[i].header.seq_num == seq_num) {
            list->retransmissions++;
            list->segments[i].retransmitted = 1;
            return;
        }
    }

    // If not found, simulate a packet drop
    list->dropped_packets++;
}

void handle_out_of_order(SegmentList *list, int expected_seq_num) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->segments[i].header.seq_num == expected_seq_num && !list->segments[i].retransmitted) {
            // Process the segment
            return;
        }
    }

    // If not found, simulate handling out-of-order packet scenario
}

void print_statistics(SegmentList *list) {
    if (list == NULL) return;

    printf("Successful Transmissions: %zu\n", list->successful_transmissions);
    printf("Retransmissions: %zu\n", list->retransmissions);
    printf("Dropped Packets: %zu\n", list->dropped_packets);
}

// Example usage
int main() {
    SegmentList *list = create_segment_list(10);

    add_segment(list, 1, "data1", strlen("data1"));
    handle_retransmission(list, 1);
    handle_out_of_order(list, 2); // Simulate out-of-order handling

    print_statistics(list);

    free_segment_list(list);

    return 0;
}
