#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <shared_mutex>
#include <chrono>

struct DataPoint {
    std::chrono::steady_clock::time_point timestamp;
    std::string deviceID;
    std::unordered_map<std::string, double> measurements;  // sensor name to measurement

    DataPoint(std::string id) : deviceID(std::move(id)) {}
};

class DataCollection {
private:
    using Timestamp = std::chrono::steady_clock::time_point;

    struct CustomAllocator {
        void* allocate(size_t size) { return ::operator new(size); }
        void deallocate(void* ptr, size_t size) { ::operator delete(ptr); }
    };

    CustomAllocator allocator;
    std::unordered_map<std::string, DataPoint> dataPoints;
    mutable std::shared_mutex mutex;

public:
    void addDataPoint(const std::string& deviceID, const std::unordered_map<std::string, double>& measurements) {
        std::unique_lock lock(mutex);
        auto it = dataPoints.find(deviceID);
        if (it == dataPoints.end()) {
            DataPoint dp(deviceID);
            dp.timestamp = std::chrono::steady_clock::now();
            dp.measurements = measurements;
            dataPoints[deviceID] = std::move(dp);
        } else {
            it->second.timestamp = std::chrono::steady_clock::now();
            it->second.measurements = measurements;
        }
    }

    void updateDataPoint(const std::string& deviceID, const std::unordered_map<std::string, double>& measurements) {
        std::unique_lock lock(mutex);
        auto it = dataPoints.find(deviceID);
        if (it != dataPoints.end()) {
            it->second.timestamp = std::chrono::steady_clock::now();
            it->second.measurements = measurements;
        }
    }

    std::vector<DataPoint> queryDataPoints(Timestamp start, Timestamp end) const {
        std::shared_lock lock(mutex);
        std::vector<DataPoint> result;

        for (const auto& pair : dataPoints) {
            if (pair.second.timestamp >= start && pair.second.timestamp <= end) {
                result.push_back(pair.second);
            }
        }

        return result;
    }
};

int main() {
    DataCollection collection;

    std::unordered_map<std::string, double> measurements = {{"sensor1", 23.4}, {"sensor2", 56.7}};
    collection.addDataPoint("device123", measurements);

    auto now = std::chrono::steady_clock::now();
    auto start = now - std::chrono::minutes(5);
    auto end = now + std::chrono::minutes(5);

    for (const auto& dp : collection.queryDataPoints(start, end)) {
        std::cout << "Device ID: " << dp.deviceID << ", Timestamp: " 
                  << std::chrono::duration_cast<std::chrono::seconds>(dp.timestamp.time_since_epoch()).count() 
                  << std::endl;
    }

    return 0;
}
```

This code implements a `DataCollection` class with methods to add, update, and query data points. It uses a custom allocator for memory management and a `std::shared_mutex` for thread-safe access. The class handles large-scale data ingestion by using an unordered map for fast lookups, which is suitable under high-load conditions.']

