#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set, for example purposes
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    pthread_mutex_t lock;
    size_t count;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_crc_list(CRCList* list) {
    struct Node* current = list->head;
    struct Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_crc_indication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) return;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    free(new_node); // Simulate handling in a larger context
}

size_t get_crc_count(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

int serialize_crc_list(const CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);
    struct Node* current = list->head;

    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

int deserialize_crc_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_crc_indication(list, pdu);
    }

    fclose(file);
    return 0;
}

int main() {
    CRCList* crc_list = create_crc_list();
    if (!crc_list) {
        fprintf(stderr, "Failed to initialize CRC list.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, rand() % 2};
    add_crc_indication(crc_list, pdu);

    printf("Total CRC indications: %zu\n", get_crc_count(crc_list));

    serialize_crc_list(crc_list, "crc_data.bin");
    destroy_crc_list(crc_list);
    crc_list = create_crc_list();

    deserialize_crc_list(crc_list, "crc_data.bin");
    printf("Deserialized total CRC indications: %zu\n", get_crc_count(crc_list));

    destroy_crc_list(crc_list);

    return EXIT_SUCCESS;
}
