    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure
int add_crc_pdu(Node** head, unsigned int rx_ue_tag, unsigned int rnti, CustomError* error) {
    if (!is_unique_RNTI(*head, rnti)) {
        error->error_code = 1;
        error->message = "Duplicate RNTI found.";
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        error->error_code = 2;
        error->message = "Memory allocation failed.";
        return -1;
    }

    srand(time(NULL)); // Seed for random CRCFLAG
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_DATA.CRCFLAG = rand() % 2;

    new_node->next = *head;
    *head = new_node;

    return 0;
}

// Function to free the linked list
void free_list(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

