        frames[i].rnti = rand() % 65536;    // Example range

        int num_subframes = (rand() % max_subframes) + 1;
        NFAPI_RX_SUBFRAME_PDU_T* subframes = malloc(num_subframes * sizeof(NFAPI_RX_SUBFRAME_PDU_T));
        if (!subframes) {
            perror("Failed to allocate memory for subframes");
            // Free previously allocated frames
            for (int j = 0; j < i; ++j) {
                free(frames[j].rnti); // Assuming rnti is dynamically allocated
            }
            free(frames);
            return NULL;
        }

        frames[i].subframes = subframes;

        for (int j = 0; j < num_subframes; ++j) {
            subframes[j].timestamp = time(NULL) + j; // Example timestamp

            // Populate with random data
            for (int k = 0; k < sizeof(subframes[j].data); ++k) {
                subframes[j].data[k] = rand() % 256;
            }
        }
    }

    return frames;
}

void free_nfa_rx_frames(NFAPI_RX_FRAME_PDU_T* frames, int num_frames) {
    if (!frames) return;

    for (int i = 0; i < num_frames; ++i) {
        if (frames[i].subframes) {
            free(frames[i].subframes);
        }
    }

    free(frames);
}

int main() {
    int num_frames = 5;
    int max_subframes = MAX_SUBFRAMES_PER_FRAME;

    NFAPI_RX_FRAME_PDU_T* frames = initialize_nfa_rx_frames(num_frames, max_subframes);
    if (frames) {
        // Use the frames for processing...

        free_nfa_rx_frames(frames, num_frames);
    }

    return 0;
}
