bool detect_cycle(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *slow = head;
    NFAPI_CRC_INDICATION_PDU_T *fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
