    return false;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_crc_list(size_t max_length, FILE *log_file) {
    pthread_mutex_lock(&list_mutex);

    NFAAPI_CRC_INDICATION_PDU_T *head = NULL, **tail = &head;
    ErrorT error;
    bool allocation_failed = false;

    srand(time(NULL));

    for (size_t i = 0; i < max_length && !allocation_failed; ++i) {
        unsigned int rnti = rand() % MAX_RNTI + 1;

        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            snprintf(error.message, sizeof(error.message), "Memory allocation failed for RNTI: %u", rnti);
            log_message(error.message, log_file);
            allocation_failed = true;
            break;
        }

        new_node->RX_UE_INFORMATION_TAG = rand();
        new_node->RNTI = rnti;
        new_node->CRC_INDICATION_REL8_TAG = rand();
        new_node->CRCFLAG = rand() % 2 == 0;
        new_node->next = NULL;

        if (!is_rnti_unique(head, rnti)) {
            snprintf(error.message, sizeof(error.message), "Duplicate RNTI detected: %u", rnti);
            log_message(error.message, log_file);
            free(new_node);
            continue;
        }

        *tail = new_node;
        tail = &new_node->next;

        if (detect_cycle(head)) {
            snprintf(error.message, sizeof(error.message), "Cycle detected in the list at insertion %zu", i + 1);
            log_message(error.message, log_file);
            allocation_failed = true;
            break;
        }
    }

    pthread_mutex_unlock(&list_mutex);

    if (allocation_failed) {
        while (head != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *temp = head;
            head = head->next;
            free(temp);
        }
    }

    return head;
}

void destroy_nfaapi_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    pthread_mutex_lock(&list_mutex);

    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}
```

### Key Features:

- **Thread Safety:** The function uses a mutex to ensure thread safety when accessing the linked list.
- **Unique RNTI Check:** Ensures that each `RNTI` is unique before insertion.
- **Cycle Detection:** Uses Floyd’s Cycle-Finding Algorithm to detect cycles in the list.
- **Error Handling:** Gracefully handles memory allocation failures and logs errors.
- **Logging:** Optional logging mechanism controlled by a preprocessor directive (`LOGGING_ENABLED`).
- **Memory Management:** Ensures all allocated memory is freed upon exit, even if an error occurs.']

