} DynamicArray;

// Initialize the dynamic array
DynamicArray* init_dynamic_array(int (*crcflag_func)(int)) {
    DynamicArray *da = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = MAX_ELEMENTS;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->get_crcflag = crcflag_func;
    return da;
}

// Add an element to the dynamic array
int add_element(DynamicArray *da, int rx_ue_info_tag, int rnti, int crc_indication_rel8_tag) {
    pthread_mutex_lock(&da->lock);

    if (da->size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Out of space
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &da->array[da->size++];
    element->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;

    // Get CRCFLAG from the external source, handle failure gracefully
    int crcflag = (da->get_crcflag) ? da->get_crcflag(crc_indication_rel8_tag) : 0;
    element->CRCFLAG = crcflag;

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Free the dynamic array resources
void free_dynamic_array(DynamicArray *da) {
    if (da) {
        if (da->array) free(da->array);
