#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define UE_CONTEXT structure
typedef struct {
    int UE_ID;
    int CELL_ID;
    time_t LAST_SEEN_TIMESTAMP;
} UE_CONTEXT;

// Custom error structure for memory allocation failures
typedef struct {
    const char *message;
} Error;

// Logging levels
typedef enum {
    LOG_NONE,
    LOG_ERROR,
    LOG_WARN,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;

// Logger configuration
LogLevel log_level = LOG_INFO;

void log_message(LogLevel level, const char* message) {
    if (level <= log_level) {
        printf("%s\n", message);
    }
}

// TreeNode structure for tree-based data structure
typedef struct TreeNode {
    UE_CONTEXT context;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode *root = NULL;
pthread_mutex_t tree_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Error* validate_ue_id(int ue_id);
UE_CONTEXT* allocate_ue_context(int ue_id, int cell_id, time_t timestamp);
void insert_ue_context(UE_CONTEXT *new_context);
void delete_tree(TreeNode *node);
TreeNode* find_node(TreeNode *root, int ue_id);

// Validate UE_ID uniqueness before insertion
Error* validate_ue_id(int ue_id) {
    pthread_mutex_lock(&tree_lock);
    TreeNode *current = root;
    while (current != NULL) {
        if (current->context.UE_ID == ue_id) {
            pthread_mutex_unlock(&tree_lock);
            Error *error = malloc(sizeof(Error));
            error->message = "UE_ID already exists";
            return error;
        }
        current = ue_id < current->context.UE_ID ? current->left : current->right;
    }
    pthread_mutex_unlock(&tree_lock);
    return NULL;
}

// Allocate memory for a new UE_CONTEXT
UE_CONTEXT* allocate_ue_context(int ue_id, int cell_id, time_t timestamp) {
    UE_CONTEXT *new_context = (UE_CONTEXT *)malloc(sizeof(UE_CONTEXT));
    if (!new_context) {
        log_message(LOG_ERROR, "Memory allocation failed for UE_CONTEXT");
        return NULL;
    }
    new_context->UE_ID = ue_id;
    new_context->CELL_ID = cell_id;
    new_context->LAST_SEEN_TIMESTAMP = timestamp;
    return new_context;
}

// Insert a new UE_CONTEXT into the tree
void insert_ue_context(UE_CONTEXT *new_context) {
    pthread_mutex_lock(&tree_lock);
    if (!root) {
        root = malloc(sizeof(TreeNode));
        if (!root) {
            log_message(LOG_ERROR, "Memory allocation failed for TreeNode");
            free(new_context);
            return;
        }
        root->context = *new_context;
        root->left = root->right = NULL;
    } else {
        TreeNode **current = &root;
        while (*current) {
            if ((*current)->context.UE_ID == new_context->UE_ID) {
                log_message(LOG_WARN, "Attempted to insert duplicate UE_ID");
                free(new_context);
                break;
            }
            current = (new_context->UE_ID < (*current)->context.UE_ID)
                      ? &((*current)->left)
                      : &((*current)->right);

            if (!(*current)) {
                *current = malloc(sizeof(TreeNode));
                if (!*current) {
                    log_message(LOG_ERROR, "Memory allocation failed for TreeNode");
                    free(new_context);
                    break;
                }
                (*current)->context = *new_context;
                (*current)->left = (*current)->right = NULL;
            }
        }
    }
    pthread_mutex_unlock(&tree_lock);
}

// Delete the entire tree and free memory
void delete_tree(TreeNode *node) {
    if (node) {
        delete_tree(node->left);
        delete_tree(node->right);
        free(node);
    }
}

// Main function to handle UE_CONTEXT updates
void update_ue_context(int ue_id, int cell_id, time_t timestamp) {
    Error *error = validate_ue_id(ue_id);
    if (error) {
        log_message(LOG_WARN, error->message);
        free(error);
        return;
    }

    UE_CONTEXT *new_context = allocate_ue_context(ue_id, cell_id, timestamp);
    if (!new_context) {
        return;
    }

    insert_ue_context(new_context);
}

// Function to simulate real-world conditions and handle updates
void* ue_update_handler(void *arg) {
    while (1) {
        // Simulate delay from NETWORK_ENTITY_MGMT service
        sleep(rand() % 3 + 1);

        int ue_id = rand() % 50000;
        int cell_id = rand() % 1000;
        time_t timestamp = time(NULL);

        update_ue_context(ue_id, cell_id, timestamp);
    }
}

int main() {
    // Set logging level for debugging
    log_level = LOG_DEBUG;

    // Create threads to simulate UE context updates
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, ue_update_handler, NULL)) {
            log_message(LOG_ERROR, "Failed to create thread");
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    delete_tree(root);

    return 0;
}
```

This implementation includes:

- A tree-based data structure for storing `UE_CONTEXT` objects with unique `UE_ID`.
- Memory management and error handling using a custom error structure.
- A logging system with configurable verbosity levels.
- Thread safety using mutex locks to handle concurrent updates.
- Simulated real-world conditions with variable delays in UE context updates.
- Cleanup of memory allocations upon program exit.']

