typedef struct {
    int packetID;
    char sourceAddress[16];
    char destinationAddress[16];
} DataPacket;

// Function to calculate checksum (simple example)
unsigned long calculate_checksum(const DataPacket* packet) {
    unsigned long checksum = 0;
    const char *data = (const char *)packet;
    size_t length = sizeof(DataPacket);

    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
        if (checksum > UINT32_MAX) { // Handle overflow
            checksum &= UINT32_MAX;
        }
    }

    return checksum;
}

// Initialize and populate the list of DataPackets
DataPacket* initialize_data_packets(int num_packets, const char** source_addrs, const char** dest_addrs) {
    if (num_packets > MAX_PACKETS || !source_addrs || !dest_addrs) {
        fprintf(stderr, "Invalid number of packets or addresses.\n");
        return NULL;
    }

    DataPacket* packets = malloc(num_packets * PACKET_SIZE);
    if (!packets) {
        perror("Failed to allocate memory for data packets");
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        DataPacket* packet = &packets[i];

        // Initialize packet
