#include <pthread.h>
#include <time.h>

#define MAX_CAPACITY 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        _Atomic int CRCFLAG; // Using atomic for thread-safe flag update
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t resize_lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *dyn_arr = malloc(sizeof(DynamicArray));
    if (!dyn_arr) return NULL;

    dyn_arr->capacity = 1000; // Initial capacity
    dyn_arr->count = 0;

    dyn_arr->array = calloc(dyn_arr->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_arr->array) {
        free(dyn_arr);
        return NULL;
    }

    pthread_mutex_init(&dyn_arr->resize_lock, NULL);
    return dyn_arr;
}

int resize_dynamic_array(DynamicArray *dyn_arr) {
    size_t new_capacity = (size_t)(1.5 * dyn_arr->capacity);

    if (new_capacity > MAX_CAPACITY) new_capacity = MAX_CAPACITY;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dyn_arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1; // Out of memory

    pthread_mutex_lock(&dyn_arr->resize_lock);
    dyn_arr->array = new_array;
    dyn_arr->capacity = new_capacity;
    pthread_mutex_unlock(&dyn_arr->resize_lock);

    return 0;
}

int add_element(DynamicArray *dyn_arr, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (dyn_arr->count >= dyn_arr->capacity * 0.75) {
        int resize_status = resize_dynamic_array(dyn_arr);
        if (resize_status == -1) return -1; // Out of memory
    }

    pthread_mutex_lock(&dyn_arr->resize_lock);

    NFAPI_CRC_INDICATION_PDU_T *element = &dyn_arr->array[dyn_arr->count++];

    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;

    // Set CRCFLAG to a random value for demonstration purposes
    srand(time(NULL) ^ (unsigned int)pthread_self());
    atomic_store(&element->CRC_INDICATION_REL8_TAG.CRCFLAG, rand() % 2);

    pthread_mutex_unlock(&dyn_arr->resize_lock);
    return 0;
}

void clear_dynamic_array(DynamicArray *dyn_arr) {
    pthread_mutex_lock(&dyn_arr->resize_lock);

    memset(dyn_arr->array, 0, dyn_arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dyn_arr->count = 0;

    pthread_mutex_unlock(&dyn_arr->resize_lock);
}

void free_dynamic_array(DynamicArray *dyn_arr) {
    if (dyn_arr) {
        if (dyn_arr->array) free(dyn_arr->array);
        pthread_mutex_destroy(&dyn_arr->resize_lock);
        free(dyn_arr);
    }
}
```

### Explanation of Key Points:
- **Atomic Operations:** Use `_Atomic` for thread-safe operations on individual elements' `CRCFLAG`.
- **Mutex Locking:** A mutex (`pthread_mutex_t`) is used to ensure thread safety during array resizing and element addition, minimizing contention.
- **Resize Logic:** The array resizes by 50% when it reaches 75% capacity, capped at a maximum of 10,000 elements. This avoids excessive memory allocation while maintaining performance.
- **Initialization and Clearing:** Elements are initialized with random `CRCFLAG` values using atomic operations for safe concurrent access. The entire array can be cleared to reset all elements.
- **Error Handling:** Returns `-1` when out of memory during resizing.

This approach balances thread safety, memory efficiency, and simplicity while accommodating up to 15 simultaneous threads."]

