#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 2

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PduList;

// Initialize a new list
PduList* create_pdu_list() {
    PduList* list = malloc(sizeof(PduList));
    if (!list) return NULL;

    list->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->array) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Resize the list when it's full
bool resize_pdu_list(PduList* list) {
    size_t new_capacity = list->capacity * RESIZE_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(list->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_array) return false;

    list->array = new_array;
    list->capacity = new_capacity;

    return true;
}

// Add a new element to the list
bool add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity && !resize_pdu_list(list)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->array[list->size] = pdu;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Generate a random CRC flag
bool generate_random_crc_flag() {
    return rand() % 2 == 0; // Randomly true or false
}

// Populate and add a new PDU structure to the list
bool populate_and_add_pdu(PduList* list, uint16_t rx_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();

    return add_pdu(list, pdu);
}

// Validate the integrity of a PDU structure
bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simple validation: just check if fields are not zero
    return pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0;
}

// Destroy and free the list resources
void destroy_pdu_list(PduList* list) {
    pthread_mutex_destroy(&list->lock);
    free(list->array);
    free(list);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    PduList* pdu_list = create_pdu_list();
    if (!pdu_list) {
        fprintf(stderr, "Failed to initialize list.\n");
        return EXIT_FAILURE;
    }

    for (uint16_t i = 0; i < 100; ++i) { // Example: adding 100 PDUs
        if (!populate_and_add_pdu(pdu_list, i + 1, rand() % 1024)) {
            fprintf(stderr, "Failed to add PDU.\n");
        }
    }

    for (size_t i = 0; i < pdu_list->size; ++i) {
        if (!validate_pdu(&pdu_list->array[i])) {
            fprintf(stderr, "PDU validation failed at index %zu.\n", i);
        } else {
            printf("PDU validated successfully at index %zu.\n", i);
        }
    }

    destroy_pdu_list(pdu_list);

    return EXIT_SUCCESS;
}
