#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MIN_ID 0
#define MAX_ID 65535

typedef struct DataPacket {
    uint16_t packetID;
    char sourceAddress[50];
    char destinationAddress[50];
    uint16_t checksum;
    struct DataPacket* next;
} DataPacket;

DataPacket* create_data_packet(uint16_t packetID) {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!packet) {
        perror("Failed to allocate memory for data packet");
        return NULL;
    }

    packet->packetID = (packetID < MIN_ID) ? MIN_ID : ((packetID > MAX_ID) ? MAX_ID : packetID);
    snprintf(packet->sourceAddress, sizeof(packet->sourceAddress), "Source_%u", packet->packetID);
    snprintf(packet->destinationAddress, sizeof(packet->destinationAddress), "Dest_%u", packet->packetID);

    // Simple polynomial checksum calculation
    packet->checksum = 0;
    for (int i = 0; i < 3; ++i) {
        uint16_t* addr = (uint16_t*)packet + i;
        *addr ^= 0xA001;  // XOR with polynomial constant as an example
        packet->checksum ^= *addr;
    }

    packet->next = NULL;
    return packet;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

DataPacket* initialize_and_populate_packets(uint16_t* packetIDs, size_t numPackets) {
    if (!packetIDs || numPackets == 0) {
        log_error("Invalid input parameters");
        return NULL;
    }

    DataPacket* head = NULL;
    DataPacket** current = &head;

    for (size_t i = 0; i < numPackets; ++i) {
        DataPacket* newPacket = create_data_packet(packetIDs[i]);
        if (!newPacket) {
            log_error("Memory allocation failed during packet creation");
            continue; // Attempt to proceed with partial results
        }

        *current = newPacket;
        current = &(*current)->next;
    }

    // Sort the list of packets by packetID using insertion sort for simplicity and stability on small datasets
    if (head != NULL) {
        DataPacket* sorted = NULL;

        while (head != NULL) {
            DataPacket* next = head->next;
            if (sorted == NULL || sorted->packetID >= head->packetID) {
                head->next = sorted;
                sorted = head;
            } else {
                DataPacket* current = sorted;
                while (current->next != NULL && current->next->packetID < head->packetID) {
                    current = current->next;
                }
                head->next = current->next;
                current->next = head;
            }
            head = next;
        }

        head = sorted;
    }

    return head;
}

void free_packet_list(DataPacket* head) {
    while (head != NULL) {
        DataPacket* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    uint16_t packetIDs[] = {100, 20000, 70000, 300}; // Example input
    size_t numPackets = sizeof(packetIDs) / sizeof(packetIDs[0]);

    DataPacket* packets = initialize_and_populate_packets(packetIDs, numPackets);

    if (packets) {
        for (DataPacket* current = packets; current != NULL; current = current->next) {
            printf("Packet ID: %u, Checksum: %u\n", current->packetID, current->checksum);
        }
    }

    free_packet_list(packets);
    return 0;
}
