#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_POOL_SIZE 1000
#define RNTI_MAX_VALUE 65535

typedef struct {
    uint32_t packetID;
    char sourceAddress[20];
    char destinationAddress[20];
} DataPacket;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRC_flag; // Assuming this is a flag for CRC indication
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_POOL_SIZE];
    size_t count;
    pthread_mutex_t mutex;
    uint32_t seed;
} PacketPool;

uint32_t calculate_checksum(const DataPacket *packet) {
    // Simplified checksum calculation
    uint32_t checksum = 0;
    checksum += packet->packetID;
    for (int i = 0; i < strlen(packet->sourceAddress); ++i) {
        checksum += packet->sourceAddress[i];
    }
    for (int i = 0; i < strlen(packet->destinationAddress); ++i) {
        checksum += packet->destinationAddress[i];
    }
    return checksum & 0xFFFFFFFF; // Ensure no overflow
}

void pseudo_random_crc_flag(uint32_t *seed, int *crc_flag) {
    uint32_t a = 1103515245;
    uint32_t c = 12345;
    *seed = (*seed * a + c);
    *crc_flag = (*seed & 1); // Simple random flag
}

void initialize_pool(PacketPool *packetPool, uint32_t seed) {
    packetPool->count = 0;
    pthread_mutex_init(&packetPool->mutex, NULL);
    packetPool->seed = seed;
}

int add_to_pool(PacketPool *packetPool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->RNTI > RNTI_MAX_VALUE || pdu->RX_UE_INFORMATION_TAG <= 0) {
        return -1; // Invalid RNTI or RX UE Information Tag
    }

    pthread_mutex_lock(&packetPool->mutex);
    if (packetPool->count >= MAX_POOL_SIZE) {
        fprintf(stderr, "Warning: Pool overflow. Cannot insert more elements.\n");
        pthread_mutex_unlock(&packetPool->mutex);
        return -2; // Overflow condition
    }

    pseudo_random_crc_flag(&packetPool->seed, &pdu->CRC_flag);

    packetPool->pool[packetPool->count++] = pdu;
    pthread_mutex_unlock(&packetPool->mutex);
    return 0;
}

void process_packet_stream(PacketPool *packetPool) {
    // Simulated incoming data packets processing
    for (int i = 0; i < 10000; ++i) { // Assuming a large number of packets to handle concurrency
        DataPacket packet;
        packet.packetID = rand(); // Random ID for simulation
        snprintf(packet.sourceAddress, sizeof(packet.sourceAddress), "Source%d", i);
        snprintf(packet.destinationAddress, sizeof(packet.destinationAddress), "Dest%d", i);

        uint32_t checksum = calculate_checksum(&packet);

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            fprintf(stderr, "Memory allocation failed for PDU.\n");
            continue;
        }

        pdu->RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Simulated tag
        pdu->RNTI = rand() % RNTI_MAX_VALUE + 1; // Random RNTI within valid range
        pdu->CRC_INDICATION_REL8_TAG = checksum;

        if (add_to_pool(packetPool, pdu) != 0) {
            free(pdu); // Clean up on failure to insert into pool
        }
    }
}

int main() {
    PacketPool packetPool;
    initialize_pool(&packetPool, time(NULL)); // Initialize with current timestamp as seed

    process_packet_stream(&packetPool);

    pthread_mutex_destroy(&packetPool.mutex);
    return 0;
}
```

