    Node* head;
    int size;
    pthread_mutex_t lock;
} DynamicList;

// Cipher modes enumeration and state structures
typedef enum { ECB, EDE, EDE3, CFB, NULL_CIPHER } CipherMode;

typedef struct {
    CipherMode mode;
    unsigned char key[16];
    pthread_mutex_t cipher_lock; // Mutex for thread-safe operations
} CipherState;

void log_message(LogLevel level, const char* message) {
    if (level > current_log_level) return;

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("[%s] %s\n", timestamp, message);
}

// Initialize a new dynamic list
void init_dynamic_list(DynamicList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add an item to the dynamic list in a thread-safe manner
bool add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T item) {
    if (list->size >= MAX_LIST_SIZE) return false;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;
    new_node->data = item;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    log_message(LOG_LEVEL_INFO, "Added item to list");
    return true;
}

// Initialize cipher state
void init_cipher_state(CipherState* state, CipherMode mode) {
    state->mode = mode;
    memset(state->key, 0, sizeof(state->key)); // Zero-initialize key
    pthread_mutex_init(&state->cipher_lock, NULL);
}

// Example function to simulate cryptographic operations (stub implementation)
void perform_crypto_operation(CipherState* cipher_state, const unsigned char* data_in,
                              unsigned char* data_out) {
    pthread_mutex_lock(&cipher_state->cipher_lock);

    // Simulate some crypto operation based on the mode
    switch(cipher_state->mode) {
        case ECB:
            log_message(LOG_LEVEL_DEBUG, "Performing ECB encryption");
            break;
        case EDE:
            log_message(LOG_LEVEL_DEBUG, "Performing EDE encryption");
            break;
        case EDE3:
            log_message(LOG_LEVEL_DEBUG, "Performing EDE3 encryption");
            break;
        case CFB:
            log_message(LOG_LEVEL_DEBUG, "Performing CFB encryption");
            break;
        case NULL_CIPHER:
            log_message(LOG_LEVEL_INFO, "Null encryption selected; no operation performed");
            memcpy(data_out, data_in, 16);
            break;
    }

    pthread_mutex_unlock(&cipher_state->cipher_lock);
}

int main() {
    // Example usage
    DynamicList crc_list;
    init_dynamic_list(&crc_list);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, {0}};
    add_to_list(&crc_list, pdu);

    CipherState cipher;
    init_cipher_state(&cipher, ECB);

    unsigned char data_in[16] = {0};
    unsigned char data_out[16];
    perform_crypto_operation(&cipher, data_in, data_out);

    // Clean up
    while (crc_list.size > 0) {
        pthread_mutex_lock(&crc_list.lock);
        Node* temp = crc_list.head;
        crc_list.head = temp->next;
        free(temp);
        crc_list.size--;
        pthread_mutex_unlock(&crc_list.lock);
    }

    pthread_mutex_destroy(&crc_list.lock);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The dynamic list and cipher state structures are protected using mutexes to ensure thread-safe operations.
- **Logging**: A simple logging mechanism with different verbosity levels is implemented for debugging and information purposes.
- **Modularity**: Different cipher modes are encapsulated within the `CipherState` structure, which can be extended to support more modes or configurations.
- **Data Management**: The dynamic list manages a fixed maximum size to prevent memory exhaustion, crucial for high-load scenarios.']

