#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RRC_MEASUREMENT_TAG;
    int RRC_MEASUREMENT_REPORT;
    int PHY_LAYER_INFORMATION;
} LTE_Uplink_NPDU_T;

typedef struct {
    LTE_Uplink_NPDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NPDU_Manager;

void init_npdu_manager(NPDU_Manager* manager) {
    manager->capacity = 10; // Initial capacity
    manager->size = 0;
    manager->array = malloc(manager->capacity * sizeof(LTE_Uplink_NPDU_T));
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_npdu_manager(NPDU_Manager* manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->lock);
}

int resize_array(NPDU_Manager* manager, size_t new_capacity) {
    LTE_Uplink_NPDU_T* new_array = realloc(manager->array, new_capacity * sizeof(LTE_Uplink_NPDU_T));
    if (!new_array) return -1;
    manager->capacity = new_capacity;
    manager->array = new_array;
    return 0;
}

int add_npdu(NPDU_Manager* manager, LTE_Uplink_NPDU_T npdu) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (resize_array(manager, new_capacity)) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
    }
    manager->array[manager->size++] = npdu;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_npdu(NPDU_Manager* manager, size_t index) {
    if (index >= manager->size) return -1; // Index out of bounds

    pthread_mutex_lock(&manager->lock);
    memmove(&manager->array[index], &manager->array[index + 1],
            (manager->size - index - 1) * sizeof(LTE_Uplink_NPDU_T));
    manager->size--;

    if (manager->size > 0 && manager->size == manager->capacity / 4) {
        size_t new_capacity = manager->capacity / 2;
        resize_array(manager, new_capacity);
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void iterate_npdus(NPDU_Manager* manager, void (*callback)(LTE_Uplink_NPDU_T*)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        callback(&manager->array[i]);
    }
    pthread_mutex_unlock(&manager->lock);
}

void example_callback(LTE_Uplink_NPDU_T* npdu) {
    printf("NPDU: TAG=%d, REPORT=%d, PHY_INFO=%d\n",
           npdu->RRC_MEASUREMENT_TAG,
           npdu->RRC_MEASUREMENT_REPORT,
           npdu->PHY_LAYER_INFORMATION);
}

int main() {
    NPDU_Manager manager;
    init_npdu_manager(&manager);

    LTE_Uplink_NPDU_T npdu1 = {1, 101, 201};
    add_npdu(&manager, npdu1);

    LTE_Uplink_NPDU_T npdu2 = {2, 102, 202};
    add_npdu(&manager, npdu2);

    iterate_npdus(&manager, example_callback);

    remove_npdu(&manager, 0);
    iterate_npdus(&manager, example_callback);

    destroy_npdu_manager(&manager);
    return 0;
}
```

