#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DNS_SERVERS 4

typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    char dns_servers[MAX_DNS_SERVERS][64];
} NetworkConfig;

typedef struct Node {
    NetworkConfig config;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;  // Read-write lock for better concurrency
} ConfigList;

// Initialize the configuration list
void init_config_list(ConfigList* list) {
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
}

// Add a new network configuration
int add_config(ConfigList* list, NetworkConfig config) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failure

    memcpy(&new_node->config, &config, sizeof(NetworkConfig));
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list->rwlock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->rwlock);

    return 0; // Success
}

// Remove a network configuration by IP address
int remove_config(ConfigList* list, const char* ip_address) {
    pthread_rwlock_wrlock(&list->rwlock);
    Node *prev = NULL, *current = list->head;

    while (current != NULL && strcmp(current->config.ip_address, ip_address) != 0) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Not found
        pthread_rwlock_unlock(&list->rwlock);
        return -1; // Failure
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_rwlock_unlock(&list->rwlock);

    return 0; // Success
}

// Update an existing network configuration by IP address
int update_config(ConfigList* list, const char* ip_address, NetworkConfig new_config) {
    pthread_rwlock_wrlock(&list->rwlock);
    Node *current = list->head;

    while (current != NULL && strcmp(current->config.ip_address, ip_address) != 0) {
        current = current->next;
    }

    if (!current) { // Not found
        pthread_rwlock_unlock(&list->rwlock);
        return -1; // Failure
    }

    memcpy(&current->config, &new_config, sizeof(NetworkConfig));
    pthread_rwlock_unlock(&list->rwlock);

    return 0; // Success
}

// Free the entire list of configurations
void free_config_list(ConfigList* list) {
    pthread_rwlock_wrlock(&list->rwlock);
    Node *current = list->head;

    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
}

// Utility function for printing configurations
void print_configs(ConfigList* list) {
    pthread_rwlock_rdlock(&list->rwlock);
    Node *current = list->head;

    while (current != NULL) {
        printf("IP: %s, Subnet: %s, Gateway: %s\n", current->config.ip_address,
               current->config.subnet_mask, current->config.gateway);

        for (int i = 0; i < MAX_DNS_SERVERS && strlen(current->config.dns_servers[i]) > 0; i++) {
            printf("DNS%d: %s\n", i + 1, current->config.dns_servers[i]);
        }

        printf("\n");
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

// Example usage
int main() {
    ConfigList list;
    init_config_list(&list);

    NetworkConfig config1 = {"192.168.1.2", "255.255.255.0", "192.168.1.1",
                             {"8.8.8.8", "8.8.4.4", "", ""}};

    add_config(&list, config1);

    NetworkConfig updated_config = {"192.168.1.2", "255.255.255.0", "192.168.1.254",
                                    {"9.9.9.9", "149.112.112.112", "", ""}};

    update_config(&list, "192.168.1.2", updated_config);

    print_configs(&list);

    remove_config(&list, "192.168.1.2");

    free_config_list(&list);
    return 0;
}
```

