LTE_RRC_MESSAGE* initialize_and_populate_messages(int num_messages, const char **contents) {
    LTE_RRC_MESSAGE *messages = (LTE_RRC_MESSAGE *)malloc(num_messages * sizeof(LTE_RRC_MESSAGE));

    if (!messages) return NULL; // Allocation failed

    for (int i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&mutex);

        messages[i].ue_id = rand() % 10000 + 1;
        messages[i].tag = (LTE_RRC_CU_UP_CU_DU_MESSAGE_TAG)(rand() % 2); // Random tag for demonstration

        if (!contents || !contents[i]) {
            messages[i].message_content = strdup("Default Placeholder Message");
        } else {
            size_t content_length = strlen(contents[i]);
            if (content_length > MAX_MESSAGE_SIZE) {
                messages[i].message_content = (char *)malloc(MAX_MESSAGE_SIZE + 1);
                strncpy(messages[i].message_content, contents[i], MAX_MESSAGE_SIZE);
                messages[i].message_content[MAX_MESSAGE_SIZE] = '\0'; // Ensure null-termination
            } else {
                messages[i].message_content = strdup(contents[i]);
            }
        }

        pthread_mutex_unlock(&mutex);

        if (!messages[i].message_content) {
            fprintf(stderr, "Failed to allocate memory for message content.\n");
            free(messages);
            return NULL;
        }
    }

    return messages;
}

void cleanup_messages(LTE_RRC_MESSAGE *messages, int num_messages) {
    for (int i = 0; i < num_messages; ++i) {
        if (messages[i].message_content) {
            free(messages[i].message_content);
        }
    }
    free(messages);
}
