#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>

#define MAX_MESSAGE_SIZE 1024
#define LIST_LIMIT 50000

typedef enum {
    LTE_RRC_CU_UP_CU_DU_MSG_1,
    LTE_RRC_CU_UP_CU_DU_MSG_2
    // Add other message types as needed
} LTE_RRC_CU_UP_CU_DU_MESSAGE_TAG;

typedef struct {
    LTE_RRC_CU_UP_CU_DU_MESSAGE_TAG tag;
    uint32_t UE_ID;
    char *message_content;
    size_t content_size;
} LTE_RRC_MESSAGE;

typedef struct Node {
    LTE_RRC_MESSAGE data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
} ThreadSafeList;

int init_list(ThreadSafeList *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return 0; // Success
}

void cleanup_node(Node* node) {
    if (node) {
        free(node->data.message_content);
        free(node);
    }
}

int add_message(ThreadSafeList *list, LTE_RRC_MESSAGE new_msg) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failure

    new_node->data = new_msg;
    new_node->prev = NULL;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);

    if (list->head) {
        list->head->prev = new_node;
    } else {
        list->tail = new_node; // First element
    }
    list->head = new_node;

    if (list->count >= LIST_LIMIT) {
        Node* old_tail = list->tail;
        cleanup_node(old_tail);
        list->tail = old_tail->prev;
        if (list->tail) {
            list->tail->next = NULL;
        } else {
            list->head = NULL; // List is now empty
        }
    } else {
        list->count++;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int get_message(ThreadSafeList *list, LTE_RRC_MESSAGE *msg) {
    if (!list || !msg) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->head) {
        Node* temp = list->tail;

        *msg = temp->data; // Copy the data

        if (temp == list->head && list->count == 1) { // Single element
            cleanup_node(temp);
            list->head = NULL;
            list->tail = NULL;
        } else {
            list->tail = temp->prev;
            list->tail->next = NULL;
            cleanup_node(temp);
        }

        list->count--;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void destroy_list(ThreadSafeList *list) {
    Node* current = list->head;

    while (current) {
        Node* next = current->next;
        cleanup_node(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
}
