    uint8_t pdcchIndication;
    uint8_t cqis[MAX_USERS_PER_FRAME];
} LTE_PHY_FRAME_PDU;

typedef struct MemoryPool {
    LTE_PHY_FRAME_PDU *frames;
    size_t frame_count;
    size_t user_count_per_frame;
} MemoryPool;

// Function prototypes
MemoryPool* initialize_memory_pool(size_t frames, size_t users);
void free_memory_pool(MemoryPool *pool);
uint8_t generate_cqi(uint32_t user_id, uint32_t seed);
void log_message(const char *message, int level);

MemoryPool* initialize_memory_pool(size_t frames, size_t users) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        log_message("Failed to allocate memory for MemoryPool", 1);
        return NULL;
    }

    pool->frames = (LTE_PHY_FRAME_PDU*)aligned_alloc(64, frames * sizeof(LTE_PHY_FRAME_PDU));
    if (!pool->frames) {
        free(pool);
        log_message("Failed to allocate aligned memory for frames", 1);
        return NULL;
    }

    memset(pool->frames, 0, frames * sizeof(LTE_PHY_FRAME_PDU));
    pool->frame_count = frames;
    pool->user_count_per_frame = users;

    int success_count = 0;
    for (size_t i = 0; i < frames && success_count < MAX_FRAMES; ++i) {
        uint32_t seed = 12345; // Example static seed, replace with dynamic source
        for (size_t j = 0; j < users && success_count < MAX_USERS_PER_FRAME; ++j) {
            pool->frames[i].cqis[j] = generate_cqi((uint32_t)(i * 100 + j), seed);
            success_count++;
        }
    }

    log_message("Memory Pool Initialized", 2);
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->frames);
        free(pool);
        log_message("Memory Pool Freed", 2);
    }
}

uint8_t generate_cqi(uint32_t user_id, uint32_t seed) {
    uint32_t hash = ((user_id << 5) ^ seed) & 0xFF; // Simple rolling hash
    return (uint8_t)(hash % 15 + 1); // CQI range 1 to 15
}

void log_message(const char *message, int level) {
    const char *levels[] = {"ERROR", "INFO", "DEBUG"};
    if (level < sizeof(levels) / sizeof(levels[0])) {
        printf("[%s] %s\n", levels[level], message);
    }
}
