['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int size;
    const int capacity;
} PriorityQueue;

unsigned char rolling_hash(unsigned int rnti, unsigned int seed) {
    // Simple hash function for demonstration
    return (rnti ^ seed) & 0xFF;
}

void init_priority_queue(PriorityQueue* pq, int capacity) {
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    pq->size = 0;
    pq->capacity = capacity;
}

int enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data) {
    if (pq->size >= pq->capacity) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&pq->lock);
    new_node->next = pq->head;
    pq->head = new_node;
    pq->size++;
    pthread_mutex_unlock(&pq->lock);

    return 0;
}

int dequeue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (pq->size == 0) return -1;

    pthread_mutex_lock(&pq->lock);
    Node* temp = pq->head;
    *data = temp->data;
    pq->head = temp->next;
    pq->size--;
    free(temp);
    pthread_mutex_unlock(&pq->lock);

    return 0;
}

void free_priority_queue(PriorityQueue* pq) {
    while (pq->head != NULL) {
        Node* temp = pq->head;
        pq->head = temp->next;
        free(temp);
    }
    pthread_mutex_destroy(&pq->lock);
}

int create_nfa_pi_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T** ppdus, int num_pdus, unsigned int seed) {
    if (num_pdus <= 0 || num_pdus > MAX_STRUCTS) return -1;

    *ppdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*ppdus) return -2;

    PriorityQueue pq;
    init_priority_queue(&pq, num_pdus);

    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Simulated value
        pdu.RNTI = rand(); // Simulated value
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;

        pdu.CRCFLAG = rolling_hash(pdu.RNTI, seed);

        if (enqueue(&pq, pdu) != 0) {
            free(*ppdus);
            free_priority_queue(&pq);
            return -3;
        }
    }

    int index = 0;
    while (dequeue(&pq, &((*ppdus)[index])) == 0) {
        ++index;
    }

    free_priority_queue(&pq);

    // Logging success
    printf("Successfully created %d NFAPI_CRC_INDICATION_PDU_T structures.\n", num_pdus);

    return 0;
}

int main() {
    unsigned int seed = 12345; // Example seed value

    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    if (create_nfa_pi_crc_indication_pdus(&pdus, 10000, seed) == 0 && pdus != NULL) {
        printf("Structures created successfully.\n");
        free(pdus);
    } else {
        printf("Failed to create structures.\n");
    }

    return 0;
}
