    int CRCFLAG;
    time_t timestamp;
    float reliability_metric;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    int size;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void add_to_list(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = create_node(data);
    if (!new_node) return;

    if (list->tail == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;
}

void free_list(DoublyLinkedList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

