#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

// Assuming these types are defined elsewhere
typedef struct {
    // RX_UE_INFORMATION_TAG;
    // RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// External memory manager functions
void* external_malloc(size_t size);
void external_free(void *ptr);

#define MAX_LIST_SIZE 1000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} CRCList;

// Initialize the list
int crc_list_init(CRCList *crc_list, size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_LIST_SIZE) {
        return -1; // Invalid capacity
    }

    crc_list->list = external_malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!crc_list->list) {
        return -2; // Memory allocation failed
    }

    crc_list->count = 0;
    crc_list->capacity = initial_capacity;

    pthread_mutex_init(&crc_list->mutex, NULL);
    pthread_cond_init(&crc_list->cond_var, NULL);

    return 0; // Success
}

// Destroy the list
void crc_list_destroy(CRCList *crc_list) {
    for (size_t i = 0; i < crc_list->count; ++i) {
        external_free(crc_list->list[i]);
    }
    external_free(crc_list->list);

    pthread_mutex_destroy(&crc_list->mutex);
    pthread_cond_destroy(&crc_list->cond_var);
}

// Add an element to the list
int crc_list_add(CRCList *crc_list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&crc_list->mutex);

    while (crc_list->count == crc_list->capacity) {
        if (crc_list->capacity < MAX_LIST_SIZE) {
            size_t new_capacity = crc_list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T **new_list = external_malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            if (!new_list) {
                pthread_mutex_unlock(&crc_list->mutex);
                return -3; // Memory allocation failed
            }

            for (size_t i = 0; i < crc_list->count; ++i) {
                new_list[i] = crc_list->list[i];
            }
            external_free(crc_list->list);

            crc_list->list = new_list;
            crc_list->capacity = new_capacity;
        } else {
            pthread_cond_wait(&crc_list->cond_var, &crc_list->mutex);
        }
    }

    if (crc_list->count < crc_list->capacity) {
        crc_list->list[crc_list->count++] = element;
    }

    pthread_mutex_unlock(&crc_list->mutex);

    return 0; // Success
}

// Remove an element from the list
int crc_list_remove(CRCList *crc_list, size_t index) {
    pthread_mutex_lock(&crc_list->mutex);

    if (index >= crc_list->count) {
        pthread_mutex_unlock(&crc_list->mutex);
        return -4; // Invalid index
    }

    external_free(crc_list->list[index]);

    for (size_t i = index; i < crc_list->count - 1; ++i) {
        crc_list->list[i] = crc_list->list[i + 1];
    }
    crc_list->count--;

    pthread_cond_signal(&crc_list->cond_var);

    pthread_mutex_unlock(&crc_list->mutex);

    return 0; // Success
}

// Get the current count of entries
size_t crc_list_count(CRCList *crc_list) {
    pthread_mutex_lock(&crc_list->mutex);
    size_t count = crc_list->count;
    pthread_mutex_unlock(&crc_list->mutex);
    return count;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex` and `pthread_cond` ensures safe concurrent access.
- **Dynamic Capacity Management**: List capacity doubles when full, up to a maximum size defined by `MAX_LIST_SIZE`.
- **Memory Management**: Relies on an external memory manager for allocation and deallocation (`external_malloc` and `external_free`).
- **Efficient Count Retrieval**: The current count is directly retrieved from the managed list structure.
- **Graceful Handling of Edge Cases**: Checks for invalid capacity during initialization and ensures safe access to elements.

This implementation provides a scalable and maintainable approach to managing dynamic lists in a concurrent environment.']

