#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define INITIAL_QUEUE_SIZE 10
#define MAX_PACKET_SIZE 1024

typedef struct {
    unsigned long timestamp;
    int priorityLevel;
    char sourceIdentifier[50];
    size_t payloadSize;
} Packet;

typedef struct {
    Packet *packets;
    size_t capacity;
    size_t front;
    size_t rear;
    size_t size;
} PriorityQueue;

bool validatePacket(const Packet *packet) {
    return packet->payloadSize > 0 && packet->payloadSize <= MAX_PACKET_SIZE &&
           strlen(packet->sourceIdentifier) < 50;
}

PriorityQueue* createQueue(size_t capacity) {
    PriorityQueue *queue = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    queue->packets = (Packet*)malloc(capacity * sizeof(Packet));
    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
    return queue;
}

void resizeQueue(PriorityQueue *queue) {
    size_t newCapacity = queue->capacity * 2;
    Packet *newPackets = (Packet*)malloc(newCapacity * sizeof(Packet));

    for (size_t i = 0; i < queue->size; ++i) {
        size_t index = (queue->front + i) % queue->capacity;
        newPackets[i] = queue->packets[index];
    }

    free(queue->packets);
    queue->packets = newPackets;
    queue->capacity = newCapacity;
    queue->front = 0;
    queue->rear = queue->size - 1;
}

void enqueue(PriorityQueue *queue, Packet packet) {
    if (validatePacket(&packet)) {
        if (queue->size == queue->capacity) {
            resizeQueue(queue);
        }

        queue->rear = (queue->rear + 1) % queue->capacity;
        queue->packets[queue->rear] = packet;
        queue->size++;
    }
}

bool dequeue(PriorityQueue *queue, Packet *packet) {
    if (queue->size == 0) return false;

    int highestPriorityIndex = -1;
    int highestPriority = INT_MIN;

    for (int i = 0; i < queue->size; ++i) {
        size_t index = (queue->front + i) % queue->capacity;
        if (queue->packets[index].priorityLevel > highestPriority) {
            highestPriority = queue->packets[index].priorityLevel;
            highestPriorityIndex = i;
        }
    }

    *packet = queue->packets[(queue->front + highestPriorityIndex) % queue->capacity];
    queue->front = (queue->front + highestPriorityIndex + 1) % queue->capacity;
    queue->size--;

    return true;
}

void freeQueue(PriorityQueue *queue) {
    free(queue->packets);
    free(queue);
}
