    int minInt, maxInt, minFloat, maxFloat;
    int (*generateRandomInt)(struct DynamicValueGenerator*);
    float (*generateRandomFloat)(struct DynamicValueGenerator*, int inclusive);
    void (*ReadAndAnalyzeValues)(struct DynamicValueGenerator*);
    const char* (*ToString)(struct DynamicValueGenerator*);
} DynamicValueGenerator;

int dynamicValueGenerateInt(DynamicValueGenerator* self) {
    return rand() % (self->maxInt - self->minInt + 1) + self->minInt;
}

float dynamicValueGenerateFloat(DynamicValueGenerator* self, int inclusive) {
    float range = inclusive ? (self->maxFloat - self->minFloat + 1.0f)
                            : (self->maxFloat - self->minFloat);
    return ((float)(rand() % (RAND_MAX + 1)) / RAND_MAX * range) + self->minFloat;
}

void dynamicValueReadAndAnalyzeValues(DynamicValueGenerator* self) {
    int num, largest = self->minInt;
