#define MAX_CONFIGS 100

typedef struct {
    int id;
    char name[50];
    int trafficVolume;
    int qosRequirement; // Quality of Service level
    int locationId;
    int historicalUsage;
    int priority;
} NetworkConfig;

typedef struct {
    NetworkConfig configs[MAX_CONFIGS];
    int count;
} ConfigManager;

// Function prototypes
void addConfiguration(ConfigManager *manager, NetworkConfig config);
void removeConfiguration(ConfigManager *manager, int id);
void updateConfiguration(ConfigManager *manager, NetworkConfig updatedConfig);
void prioritizeConfigs(ConfigManager *manager);
void adjustResourceAllocation(ConfigManager *manager);

void addConfiguration(ConfigManager *manager, NetworkConfig config) {
    if (manager->count >= MAX_CONFIGS) return;

    // Check for existing configuration
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i].id == config.id) {
            return; // Configuration already exists
        }
    }

    manager->configs[manager->count++] = config;
    prioritizeConfigs(manager);
}

void removeConfiguration(ConfigManager *manager, int id) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i].id == id) {
            memmove(&manager->configs[i], &manager->configs[i + 1], 
                    (manager->count - i - 1) * sizeof(NetworkConfig));
            --manager->count;
            return;
        }
    }
}

void updateConfiguration(ConfigManager *manager, NetworkConfig updatedConfig) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->configs[i].id == updatedConfig.id) {
            manager->configs[i] = updatedConfig;
            prioritizeConfigs(manager);
            return;
