int read_integers(int **array, int *size) {
    if (scanf("%d", size) != 1) return -1;

    int capacity = INITIAL_BUFFER_SIZE;
    *array = (int *)malloc(capacity * sizeof(int));
    if (*array == NULL) return -1;

    for (int i = 0; i < *size; ++i) {
        if (scanf("%d", &(*array)[i]) != 1) {
            free(*array);
            return -1;
        }
    }

    return 0;
}

void find_and_print_largest(const int *array, int size) {
    if (size == 0) {
        printf("Array is empty.\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

NFAPI_L2_RX_FRAME* initialize_frames(int numFrames) {
    NFAPI_L2_RX_FRAME *frames = (NFAPI_L2_RX_FRAME *)malloc(numFrames * sizeof(NFAPI_L2_RX_FRAME));
    if (frames == NULL) return NULL;

    for (int i = 0; i < numFrames; ++i) {
        frames[i].frame.buffer.data = (unsigned char *)malloc(INITIAL_BUFFER_SIZE);
        if (frames[i].frame.buffer.data == NULL) {
            cleanup_frames(frames, i); // Clean up already allocated frames
            return NULL;
        }
        frames[i].frame.buffer.length = INITIAL_BUFFER_SIZE;
    }

    return frames;
}

void fill_frames_with_random_data(NFAPI_L2_RX_FRAME *frames, int numFrames) {
    for (int i = 0; i < numFrames; ++i) {
        size_t length = rand() % INITIAL_BUFFER_SIZE + 1;
        if (length > frames[i].frame.buffer.length) {
            unsigned char *new_data = (unsigned char *)realloc(frames[i].frame.buffer.data, length);
            if (new_data == NULL) continue; // Skip frame in case of reallocation failure
            frames[i].frame.buffer.data = new_data;
            frames[i].frame.buffer.length = length;
        }

        for (size_t j = 0; j < length; ++j) {
            frames[i].frame.buffer.data[j] = rand() % 256;
        }
    }
}

void cleanup_frames(NFAPI_L2_RX_FRAME *frames, int numFrames) {
    if (frames == NULL) return;

    for (int i = 0; i < numFrames; ++i) {
        free(frames[i].frame.buffer.data);
    }

    free(frames);
}
