#define MAX_ENTRIES 10000
#define MAX_MEMORY_USAGE 50 * 1024 * 1024 // 50MB in bytes

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool structure
typedef struct {
    size_t entry_size;
    size_t num_entries;
    void *memory_pool;
    pthread_mutex_t lock;
    int available_indices[MAX_ENTRIES];
    int next_available_index;
} MemoryPool;

MemoryPool crc_pool = { sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_ENTRIES, NULL, PTHREAD_MUTEX_INITIALIZER, {}, 0 };

// Function prototypes
void initialize_memory_pool(MemoryPool *pool);
int allocate_entry(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T **entry);
void free_entry(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *entry);
uint16_t generate_unique_rnti();
void log_event(const char *message);

// Initialize memory pool
void initialize_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    pool->memory_pool = malloc(pool->num_entries * pool->entry_size);
    if (!pool->memory_pool) {
        log_event("Memory allocation failed");
        return;
    }

    for (int i = 0; i < pool->num_entries; ++i) {
        pool->available_indices[i] = i;
    }
    pool->next_available_index = 0;

    pthread_mutex_unlock(&pool->lock);
}

// Allocate an entry from the memory pool
int allocate_entry(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T **entry) {
    int index = -1;
    pthread_mutex_lock(&pool->lock);

    if (pool->next_available_index < pool->num_entries) {
        index = pool->available_indices[pool->next_available_index];
        pool->next_available_index++;
    }

    if (index != -1) {
        *entry = (NFAPI_CRC_INDICATION_PDU_T *)((uint8_t *)pool->memory_pool + index * pool->entry_size);
        (*entry)->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        log_event("Entry allocated");
    } else {
        log_event("No available entries for allocation");
    }

    pthread_mutex_unlock(&pool->lock);
    return index;
}

// Free an entry back to the memory pool
void free_entry(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *entry) {
    int index = (uint8_t *)entry - (uint8_t *)pool->memory_pool;
    pthread_mutex_lock(&pool->lock);

    if (index >= 0 && index < pool->num_entries) {
        pool->available_indices[--pool->next_available_index] = index;
        log_event("Entry freed");
    }

    pthread_mutex_unlock(&pool->lock);
}

// Generate a unique RNTI within a valid range
uint16_t generate_unique_rnti() {
    static uint16_t used_rntis[MAX_ENTRIES] = {0};
    srand(time(NULL));

    while (1) {
        uint16_t rnti = rand() % 65536; // Example range
        int is_unique = 1;

        for (int i = 0; i < MAX_ENTRIES && used_rntis[i]; ++i) {
            if (used_rntis[i] == rnti) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            for (int i = 0; i < MAX_ENTRIES; ++i) {
                if (!used_rntis[i]) {
                    used_rntis[i] = rnti;
                    log_event("Unique RNTI generated");
                    return rnti;
                }
            }
        }
    }
}

// Log an event
void log_event(const char *message) {
    printf("%s\n", message);
    // Implement further logging mechanisms if needed, e.g., to a file or monitoring system.
}

