['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTS 10000
#define RELIABILITY_THRESHOLD 0.05

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    time_t timestamp;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_node(Node* node) {
    free(node);
}

void add_to_list(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->data = data;
    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = new_node->next = NULL;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_from_list(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (node == list->head) list->head = node->next;
    if (node == list->tail) list->tail = node->prev;

    list->count--;

    pthread_mutex_unlock(&list->lock);
    destroy_node(node);
}

void garbage_collect(DoublyLinkedList* list, time_t age_limit) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        if (difftime(time(NULL), current->data.timestamp) > age_limit) {
            remove_from_list(list, current);
        }
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
}

void log_statistics(DoublyLinkedList* list, int* unreliable_count, int* gc_operations) {
    *unreliable_count = 0;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.crc_indication_rel8_tag.CRCFLAG > RELIABILITY_THRESHOLD) {
            (*unreliable_count)++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void manage_ue_information() {
    DoublyLinkedList list;
    init_list(&list);

    srand(time(NULL));

    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand();
        pdu.timestamp = time(NULL);
        pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 100 / 100.0;

        add_to_list(&list, pdu);
    }

    int unreliable_count = 0;
    int gc_operations = 0;

    while (1) {
        garbage_collect(&list, 60); // Adjust age limit as needed
        log_statistics(&list, &unreliable_count, &gc_operations);

        printf("Unreliable Indications: %d\n", unreliable_count);
        printf("Garbage Collection Operations: %d\n", gc_operations++);

        sleep(10); // Run garbage collection and logging periodically
    }

    // Clean up list before exiting (not reached in this infinite loop)
    pthread_mutex_lock(&list.lock);
    Node* current = list.head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    pthread_mutex_unlock(&list.lock);
    pthread_mutex_destroy(&list.lock);
}

int main() {
    manage_ue_information();
    return 0;
}
