        exit(EXIT_FAILURE);
    }

    context->ue_id = ue_id;
    context->measurement_result.UE_ID = ue_id;
    context->measurement_result.measurement_result = measurement_result;

    strncpy(context->dci_message.message_content, dci_content, sizeof(context->dci_message.message_content) - 1);

    context->next = NULL;
    return context;
}

