        fprintf(stderr, "Duplicate UE ID detected: %d\n", ue_id);
        exit(EXIT_FAILURE);
    }

    UE_Context* new_context = init_ue_context(ue_id, measurement_result, dci_content);

    // Append to the list
    if (*head == NULL) {
        *head = new_context;
    } else {
        UE_Context* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_context;
    }
}

