    public static int parseXmlAndCreateNfarb(string xmlFilePath, string xpathQuery, string resourceBundlePath, int n, int performanceBudget)
    {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.Start();

        // Parse XML
        XPathDocument doc = new XPathDocument(xmlFilePath);
        XPathNavigator nav = doc.CreateNavigator();
        XPathNodeIterator nodes = nav.Select(xpathQuery);

        if (nodes.Count == 0 || nodes.MoveNext() && nodes.MoveNext())
        {
            throw new InvalidOperationException("XPath query must match exactly one element.");
        }

        stopwatch.Stop();

        // Load resource bundle with retry logic
        int resourceBundleItemsCount = 0;
        bool loadedSuccessfully = false;
        int maxRetries = 3;
        int attempt = 0;

        while (!loadedSuccessfully && attempt < maxRetries)
        {
            try
            {
                stopwatch.Restart();
                // Simulate loading the resource bundle
                using (FileStream fs = new FileStream(resourceBundlePath, FileMode.Open))
                {
                    byte[] buffer = new byte[fs.Length];
                    fs.Read(buffer, 0, buffer.Length);
                    resourceBundleItemsCount = buffer.Length; // Example: count bytes as items
                }
                stopwatch.Stop();

                if (stopwatch.ElapsedMilliseconds > performanceBudget)
                {
                    throw new TimeoutException("Loading the resource bundle exceeded the performance budget.");
                }

                loadedSuccessfully = true;
            }
            catch (IOException ex) when (attempt < maxRetries - 1)
            {
                attempt++;
                System.Threading.Thread.Sleep(100); // Wait before retrying
            }
        }

        if (!loadedSuccessfully)
        {
            throw new Exception("Failed to load the resource bundle after multiple attempts.");
        }

        // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
        NFAPI_CRC_INDICATION_PDU_T[] nfaArray = new NFAPI_CRC_INDICATION_PDU_T[n];
        Random rand = new Random();

        for (int i = 0; i < n; i++)
        {
            nfaArray[i] = new NFAPI_CRC_INDICATION_PDU_T
            {
                RX_UE_INFORMATION_TAG = rand.Next(1, 100),
                RNTI = rand.Next(1, 100),
                CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG { CRCFLAG = rand.Next(2) == 0 }
            };
        }

        return resourceBundleItemsCount;
    }
}
