// Structure definition for LTE RRC connection setup request
typedef struct {
    int ue_id;
    int cell_id;
} LTE_RRC_CONNECTION_SETUP_REQUEST_T;

// Node structure for linked list of requests
typedef struct RequestNode {
    LTE_RRC_CONNECTION_SETUP_REQUEST_T request;
    struct RequestNode* next;
} RequestNode;

// Linked list management with mutex for thread safety
typedef struct {
    RequestNode* head;
    pthread_mutex_t lock;
} RequestList;

// Function to initialize the request list
void init_request_list(RequestList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to safely add a new request
int add_request(RequestList* list, LTE_RRC_CONNECTION_SETUP_REQUEST_T request) {
    RequestNode* node = (RequestNode*)malloc(sizeof(RequestNode));
    if (!node) return -1; // Error handling for memory allocation

    node->request = request;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = node;
    } else {
        RequestNode* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Function to safely retrieve and remove a request (for processing)
int get_request(RequestList* list, LTE_RRC_CONNECTION_SETUP_REQUEST_T* out_request) {
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return -1; // No requests available
    }

    RequestNode* node = list->head;
    *out_request = node->request;

    list->head = node->next;
    free(node);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to handle malformed PDUs and incomplete data gracefully
int validate_and_process_data(int ue_id, int cell_id, RequestList* list) {
    if (ue_id <= 0 || cell_id <= 0) { // Simplified validation check
        printf("Malformed PDU encountered. Skipping...\n");
        return -1;
    }

    LTE_RRC_CONNECTION_SETUP_REQUEST_T request = { .ue_id = ue_id, .cell_id = cell_id };
    return add_request(list, request);
}

// Function to simulate processing requests
void process_requests(RequestList* list) {
    while (1) {
        LTE_RRC_CONNECTION_SETUP_REQUEST_T request;
        if (get_request(list, &request) == 0) {
            // Simulate processing the request
            printf("Processing request for UE ID: %d on Cell ID: %d\n", request.ue_id, request.cell_id);
        }
    }
}

// Function to deinitialize and free resources
void cleanup_request_list(RequestList* list) {
    pthread_mutex_lock(&list->lock);
    RequestNode* current = list->head;
    while (current) {
        RequestNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example main function to demonstrate usage
int main() {
    RequestList request_list;
    init_request_list(&request_list);

    // Simulating adding requests (replace with actual data source)
    validate_and_process_data(1, 100, &request_list);
    validate_and_process_data(-1, 101, &request_list); // Malformed PDU
    validate_and_process_data(2, 102, &request_list);

    // Start processing requests in a separate thread (for demonstration)
    pthread_t processing_thread;
    pthread_create(&processing_thread, NULL, (void* (*)(void*))process_requests, &request_list);
    pthread_join(processing_thread, NULL);

    cleanup_request_list(&request_list);

    return 0;
}
