struct PriorityQueueNode {
    LTE_RRC_CONNECTION_SETUP_REQUEST_T request;
    int priority; // Higher value means higher priority
};

// Comparator for the priority queue
struct ComparePriority {
    bool operator()(const struct PriorityQueueNode& a, const struct PriorityQueueNode& b) {
        return a.priority < b.priority; // Min-heap based on priority
    }
};

// Priority queue to manage connection requests
std::priority_queue<struct PriorityQueueNode, std::vector<struct PriorityQueueNode>, ComparePriority> requestQueue;
std::mutex queueMutex;
std::condition_variable cv;

// Function prototypes
