// Function to initialize and configure network interface
void initializeNetworkInterface() {
    pthread_t threadID;
    if (pthread_create(&threadID, NULL, processRequests, NULL) != 0) {
        logMessage("Failed to create processing thread", 1);
    }
}

// Thread function to process connection requests
void* processRequests(void* arg) {
