        std::unique_lock<std::mutex> lock(queueMutex);
        cv.wait(lock, [] { return !requestQueue.empty(); });

        struct PriorityQueueNode node = requestQueue.top();
        requestQueue.pop();

        // Simulate processing the request
        LTE_RRC_CONNECTION_SETUP_REQUEST_T request = node.request;

        if (validateRequest(&request)) {
            distributeToInterface(request);
        } else {
            handleMalformedPDU(&request);
        }

        lock.unlock();
    }
    return NULL;
}

// Validate the incoming request data
int validateRequest(const LTE_RRC_CONNECTION_SETUP_REQUEST_T* request) {
    // Perform validation checks
    if (request->ue_id <= 0 || request->cell_id <= 0) {
        logMessage("Malformed PDU detected", 2);
        return 0;
    }
    return 1;
}

// Handle malformed or incomplete data gracefully
void handleMalformedPDU(const LTE_RRC_CONNECTION_SETUP_REQUEST_T* request) {
    // Log and ignore the malformed PDU
    logMessage("Ignoring malformed PDU for UE ID: ", 3);
    printf("%d\n", request->ue_id);
    retryCount++;
    if (retryCount > activeInterfaces) {
        // Attempt to recover or re-route requests
        redistributeRequests();
    }
}

// Distribute the connection request to an appropriate interface
void distributeToInterface(const LTE_RRC_CONNECTION_SETUP_REQUEST_T* request) {
    // Logic to distribute requests among available interfaces
    int selectedInterface = (request->ue_id % activeInterfaces);
    logMessage("Distributing request to Interface: ", 3);
    printf("%d\n", selectedInterface);

    // Simulate handling the request on the selected interface
}

// Redistribute requests in case of failure
void redistributeRequests() {
    // Logic to handle re-distribution after a failure
    logMessage("Redistributing requests due to interface failure", 1);
}

// Log messages with configurable verbosity
void logMessage(const char* message, int verbosityLevel) {
    static int currentVerbosity = 3; // Example verbosity level
    if (verbosityLevel <= currentVerbosity) {
        printf("%s\n", message);
    }
}

int main() {
