import <pthread.h>
#include <openssl/md5.h>

#define INITIAL_POOL_SIZE 10
#define MAX_RETRIES 3

typedef struct {
    // Example fields, adjust based on actual definition
    int dataRate;
    char *pduData;
    size_t pduLength;
} LTE_RRC_CONNECTION_SETUP_REQUEST_T;

typedef struct {
    LTE_RRC_CONNECTION_SETUP_REQUEST_T *requests;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} RequestPool;

void logError(const char *message) {
    fprintf(stderr, "%s\n", message);
}

size_t computeMD5Hash(const void *data, size_t length, unsigned char hash[16]) {
    MD5((unsigned char *) data, (unsigned int) length, hash);
    return 1;
}

void logMD5(unsigned char *hash) {
    for (int i = 0; i < 16; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

RequestPool* initializeRequestPool() {
    RequestPool *pool = malloc(sizeof(RequestPool));
    if (!pool) return NULL;

    pool->requests = malloc(INITIAL_POOL_SIZE * sizeof(LTE_RRC_CONNECTION_SETUP_REQUEST_T));
    if (!pool->requests) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond_var, NULL);

    pool->capacity = INITIAL_POOL_SIZE;
    pool->count = 0;

    return pool;
}

void resizePoolIfNeeded(RequestPool *pool) {
    if (pool->count >= pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        LTE_RRC_CONNECTION_SETUP_REQUEST_T *newRequests =
            realloc(pool->requests, newCapacity * sizeof(LTE_RRC_CONNECTION_SETUP_REQUEST_T));

        if (!newRequests) {
            logError("Failed to resize request pool.");
            return; // Handle error gracefully
        }

        pool->requests = newRequests;
        pool->capacity = newCapacity;
    }
}

int addRequest(RequestPool *pool, LTE_RRC_CONNECTION_SETUP_REQUEST_T *request) {
    pthread_mutex_lock(&pool->mutex);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (request->pduData == NULL || request->pduLength == 0) {
            logError("Malformed PDU encountered.");
            break;
        }

        resizePoolIfNeeded(pool);

        pool->requests[pool->count++] = *request;

        unsigned char hash[16];
        computeMD5Hash(request->pduData, request->pduLength, hash);

        pthread_mutex_unlock(&pool->mutex);
        logMD5(hash);  // Log the MD5 hash for performance analysis and debugging
        return 0;      // Success
    }

    pthread_mutex_unlock(&pool->mutex);
    return -1;       // Failed to add request after retries
}

void freeRequestPool(RequestPool *pool) {
    if (!pool) return;

    free(pool->requests);

    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond_var);

    free(pool);
}
