#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

// Define structures
typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Hash table entry
typedef struct HashEntry {
    uint16_t rnti;
    Node* node;
    struct HashEntry* next;
} HashEntry;

// Linked List and hash table management structure
typedef struct {
    Node* head;
    HashEntry** hash_table;
    size_t hash_size;
    pthread_mutex_t list_mutex;
    pthread_mutex_t hash_mutex;
} CRCListManager;

#define HASH_SIZE 1024

// Function to initialize the CRCListManager
void init_crc_list_manager(CRCListManager* manager) {
    manager->head = NULL;
    manager->hash_table = malloc(HASH_SIZE * sizeof(HashEntry*));
    for (size_t i = 0; i < HASH_SIZE; ++i) {
        manager->hash_table[i] = NULL;
    }
    pthread_mutex_init(&manager->list_mutex, NULL);
    pthread_mutex_init(&manager->hash_mutex, NULL);
}

// Hash function
unsigned int hash_rnti(uint16_t rnti) {
    return rnti % HASH_SIZE;
}

// Function to add a new node
bool add_crc_indication(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&manager->hash_mutex);

    unsigned int index = hash_rnti(pdu.ue_info_tag.RNTI);
    HashEntry* entry = manager->hash_table[index];

    while (entry != NULL) {
        if (entry->rnti == pdu.ue_info_tag.RNTI) {
            pthread_mutex_unlock(&manager->hash_mutex);
            return false; // RNTI already exists
        }
        entry = entry->next;
    }

    HashEntry* new_entry = malloc(sizeof(HashEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&manager->hash_mutex);
        return false; // Memory allocation failure
    }

    new_entry->rnti = pdu.ue_info_tag.RNTI;
    new_entry->node = malloc(sizeof(Node));
    if (!new_entry->node) {
        free(new_entry);
        pthread_mutex_unlock(&manager->hash_mutex);
        return false; // Memory allocation failure
    }
    new_entry->next = manager->hash_table[index];
    manager->hash_table[index] = new_entry;

    pthread_mutex_unlock(&manager->hash_mutex);

    pthread_mutex_lock(&manager->list_mutex);
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&manager->list_mutex);
        return false; // Memory allocation failure
    }
    new_node->data = pdu;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->list_mutex);

    // Probabilistic CRCFLAG setting algorithm
    new_entry->node->data.CRC_INDICATION_REL8_TAG = (rand() % 100 < 50) ? 1 : 0;

    return true;
}

// Function to cleanup the list
void cleanup_crc_list(CRCListManager* manager) {
    pthread_mutex_lock(&manager->list_mutex);
    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;

    pthread_mutex_unlock(&manager->list_mutex);

    pthread_mutex_lock(&manager->hash_mutex);
    for (size_t i = 0; i < HASH_SIZE; ++i) {
        HashEntry* entry = manager->hash_table[i];
        while (entry != NULL) {
            HashEntry* temp = entry;
            entry = entry->next;
            free(temp->node);
            free(temp);
        }
    }
    pthread_mutex_unlock(&manager->hash_mutex);
}

// Function to destroy the CRCListManager
void destroy_crc_list_manager(CRCListManager* manager) {
    cleanup_crc_list(manager);

    free(manager->hash_table);
    pthread_mutex_destroy(&manager->list_mutex);
    pthread_mutex_destroy(&manager->hash_mutex);
}
