#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define MAX_LIST_SIZE 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[3];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void initializeList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* createNode(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    memcpy(&newNode->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = NULL;
    return newNode;
}

int addPduToList(LinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL || (Node*)malloc(sizeof(Node)) != NULL) { // Simplified check for memory availability
        Node* newNode = createNode(pdu);
        if (!newNode) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        newNode->next = list->head;
        list->head = newNode;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serializeList(const LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void freeList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void generateRandomPdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
    pdu->RNTI = rand() % 0xFFFF;
    for (int i = 0; i < 3; ++i) {
        pdu->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }
    pdu->CRC_INDICATION_REL8_TAG[2] = (rand() % 2) ? 1 : 0; // Set CRCFLAG randomly
}

void populateList(LinkedList* list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generateRandomPdu(&pdu);
        addPduToList(list, &pdu);
    }
}

void monitorPerformance(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        pthread_mutex_lock(&list->lock);
        size_t count = 0;
        Node* current = list->head;
        while (current != NULL) {
            ++count;
            current = current->next;
        }
        printf("Current List Size: %zu\n", count);
        pthread_mutex_unlock(&list->lock);

        sleep(5); // Adjust monitoring frequency as needed
    }
}

int main() {
    LinkedList list;
    initializeList(&list);

    pthread_t monitorThread;
    if (pthread_create(&monitorThread, NULL, (void*)monitorPerformance, &list) != 0) {
        perror("Failed to create monitoring thread");
        freeList(&list);
        return EXIT_FAILURE;
    }

    populateList(&list, MAX_LIST_SIZE); // Adjust N as needed
    serializeList(&list, "nfa_list.bin");

    pthread_cancel(monitorThread);
    pthread_join(monitorThread, NULL);

    freeList(&list);
    return 0;
}
