    array->pdus[array->count++] = new_pdu;

    log_operation("Added a new MAC PDU successfully");
    pthread_mutex_unlock(&array->lock);

    return 0;
}

MAC_PDU* get_mac_pdu(MacPduArray *array, int index) {
    if (!array || index < 0 || index >= array->count) return NULL;

    pthread_mutex_lock(&array->lock);
    MAC_PDU *pdu = array->pdus[index];
    pthread_mutex_unlock(&array->lock);

    log_operation("Retrieved a MAC PDU by index");
    return pdu;
}

int update_mac_pdu_payload(MacPduArray *array, int index, const uint8_t *new_data, size_t length) {
    if (!array || index < 0 || index >= array->count || !new_data) return -1;

    pthread_mutex_lock(&array->lock);

    MAC_PDU *pdu = array->pdus[index];
    if (pdu->payload.data) free(pdu->payload.data);

    pdu->payload.data = malloc(length);
    if (!pdu->payload.data) {
        log_operation("Failed to allocate memory for new payload");
        pthread_mutex_unlock(&array->lock);
        return -2;
    }

    memcpy(pdu->payload.data, new_data, length);
    pdu->payload.length = length;

    log_operation("Updated MAC PDU payload successfully");
    pthread_mutex_unlock(&array->lock);

    return 0;
}
