int add_pdu(PDUManager *manager, MAC_PDU *pdu) {
    if (manager->count >= MAX_PDUS) {
        log_event("PDU array is full");
        return -1; // Array full
    }

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
