            manager->pdus[i]->header.version == pdu->header.version &&
            manager->pdus[i]->header.type == pdu->header.type &&
            memcmp(manager->pdus[i]->payload.data, pdu->payload.data, pdu->payload.length) == 0) {

            pthread_mutex_unlock(&manager->lock);
            log_event("Duplicate PDU detected");
            return -2; // Duplicate
        }
    }

    unsigned long hash = calculate_hash(pdu);
    if (hash != pdu->hash) {
        pthread_mutex_unlock(&manager->lock);
        log_event("Invalid PDU integrity");
        return -3; // Invalid integrity
    }

    manager->pdus[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

MAC_PDU* get_pdu(PDUManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        log_event("Invalid PDU index");
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);

    MAC_PDU *pdu = manager->pdus[index];

    pthread_mutex_unlock(&manager->lock);
    return pdu;
}

int update_pdu(PDUManager *manager, int index, MAC_PDU *new_pdu) {
    if (index < 0 || index >= manager->count) {
        log_event("Invalid PDU index");
        return -1; // Invalid index
    }

    pthread_mutex_lock(&manager->lock);

    unsigned long hash = calculate_hash(new_pdu);
    if (hash != new_pdu->hash) {
        pthread_mutex_unlock(&manager->lock);
        log_event("Invalid PDU integrity during update");
        return -2; // Invalid integrity
    }

    manager->pdus[index] = new_pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void periodic_check_and_revalidate(PDUManager *manager) {
    while (1) {
        sleep(10); // Check every 10 seconds

        pthread_mutex_lock(&manager->lock);

        for (int i = 0; i < manager->count; ++i) {
            if (!validate_pdu(manager->pdus[i])) {
                log_event("Corrupted PDU detected, revalidating...");
                unsigned long new_hash = calculate_hash(manager->pdus[i]);
                if (new_hash != manager->pdus[i]->hash) {
                    // Handle corruption: remove or mark as invalid
                    free(manager->pdus[i]->payload.data);
                    free(manager->pdus[i]);
                    manager->pdus[i] = NULL;
                    memmove(&manager->pdus[i], &manager->pdus[i + 1], sizeof(MAC_PDU*) * (manager->count - i - 1));
                    --manager->count;
                }
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }
}

void free_pdu_manager(PDUManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->pdus[i]) {
            free(manager->pdus[i]->payload.data);
            free(manager->pdus[i]);
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

