    manager->capacity = INITIAL_SIZE;
    manager->count = 0;

    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        pthread_mutex_destroy(&manager->lock);
        return -1;
    }

    return 0;
}

// Function to add a PDU
int add_pdu(PDU_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    manager->pdus[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to reset the PDU manager
void reset_pdu_manager(PDU_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->pdus);
    manager->pdus = NULL;
    manager->capacity = INITIAL_SIZE;
    manager->count = 0;

    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        pthread_mutex_unlock(&manager->lock);
        // Handle memory allocation failure
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to destroy the PDU manager
void destroy_pdu_manager(PDU_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->pdus);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

// Example usage
int main() {
    PDU_Manager manager;
    if (init_pdu_manager(&manager) != 0) {
        fprintf(stderr, "Failed to initialize PDU manager\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T example_pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 1234, .CRC_INDICATION_REL8_TAG = 5678, .crc_flag = 1 };
    add_pdu(&manager, example_pdu);

    reset_pdu_manager(&manager);
    destroy_pdu_manager(&manager);

    return 0;
}
