import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ConnectionManager {
    private static final Logger logger = Logger.getLogger(ConnectionManager.class.getName());
    private final List<ServerConnection> serverConnections;
    private final int maxRetries;
    private final long retryTimeoutMillis;

    public ConnectionManager(List<String> serverUrls, int maxRetries, long retryTimeoutMillis) {
        this.serverConnections = new ArrayList<>();
        this.maxRetries = maxRetries;
        this.retryTimeoutMillis = retryTimeoutMillis;
        initializeConnections(serverUrls);
    }

    private void initializeConnections(List<String> serverUrls) {
        for (String url : serverUrls) {
            ServerConnection connection = new ServerConnection(url, maxRetries, retryTimeoutMillis);
            serverConnections.add(connection);
            Executors.newSingleThreadExecutor().submit(() -> manageConnection(connection));
        }
    }

    private void manageConnection(ServerConnection connection) {
        try {
            while (true) {
                if (!connection.isConnected()) {
                    attemptReconnect(connection);
                }
                TimeUnit.MILLISECONDS.sleep(retryTimeoutMillis / 2); // Polling interval
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.warning("Connection management thread interrupted: " + e.getMessage());
        }
    }

    private void attemptReconnect(ServerConnection connection) {
        int attempts = 0;
        while (attempts < maxRetries && !connection.isConnected()) {
            try {
                if (connection.reconnect()) {
                    logger.info("Successfully reconnected to server: " + connection.getServerUrl());
                } else {
                    logger.warning("Failed to reconnect to server: " + connection.getServerUrl() +
                            ". Attempt " + attempts);
                }
            } catch (Exception e) {
                logger.severe("Error during reconnection attempt: " + e.getMessage());
            }
            attempts++;
            try {
                TimeUnit.MILLISECONDS.sleep(retryTimeoutMillis);
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public static class ServerConnection {
        private final String serverUrl;
        private final int maxRetries;
        private final long retryTimeoutMillis;
        private volatile boolean connected;

        public ServerConnection(String serverUrl, int maxRetries, long retryTimeoutMillis) {
