#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_STRUCTS 1000
#define INITIAL_BACKOFF_MS 100
#define MAX_RETRIES 5

typedef struct {
    int valid; // Placeholder for RX_UE_INFORMATION_TAG validation flag
    uint32_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int valid_tag;
    CRC_INDICATION_REL8_TAG crc_tag;
    double range_value;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

void init_dynamic_list(DynamicList *list) {
    list->data = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int allocate_structs(DynamicList *list, size_t n) {
    pthread_mutex_lock(&list->mutex);

    if (n > MAX_STRUCTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory limit exceeded
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Allocation failed
    }

    list->data = new_data;
    memset(new_data + list->count, 0, (n - list->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = n;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    if (list->data) {
        free(list->data);
        list->data = NULL;
    }
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int fetch_range_value(double *range, int retries, double backoff_ms) {
    for (int i = 0; i < retries; ++i) {
        // Simulate external data source fetching with random value
        *range = ((double)rand() / RAND_MAX) * 100.0;

        // Simulate possible failure
        if ((*range >= 50.0 && *range <= 70.0)) { 
            return 1; // Success
        }

        usleep(backoff_ms * 1000);
        backoff_ms *= 2;
    }
    return -1; // Failure after retries
}

void fill_dynamic_list(DynamicList *list, size_t n) {
    pthread_mutex_lock(&list->mutex);

    if (allocate_structs(list, n) != 0) {
        fprintf(stderr, "Failed to allocate memory for structures.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    double range_value = 0.0;
    int retry_count = 0;

    while (!fetch_range_value(&range_value, MAX_RETRIES, INITIAL_BACKOFF_MS)) {
        ++retry_count;
    }

    for (size_t i = 0; i < n; ++i) {
        list->data[i].valid_tag = 1; // Assume valid
        list->data[i].crc_tag.RNTI = rand();
        list->data[i].crc_tag.CRCFLAG = rand() % 2;
        list->data[i].range_value = range_value + ((double)rand() / RAND_MAX);
    }

    pthread_mutex_unlock(&list->mutex);
}

int main() {
    srand(time(NULL));

    DynamicList list;
    init_dynamic_list(&list);

    size_t num_structs = 500; // Example number
    fill_dynamic_list(&list, num_structs);

    for (size_t i = 0; i < list.count; ++i) {
        printf("Struct %zu: RNTI=%u, CRCFLAG=%d, Range Value=%.2f\n",
               i, list.data[i].crc_tag.RNTI, list.data[i].crc_tag.CRCFLAG, 
               list.data[i].range_value);
    }

    free_dynamic_list(&list);

    return 0;
}
