#include <iostream>
#include <vector>
#include <limits>
#include <cstdlib>
#include <ctime>
#include <string>

// Define structure as per requirement
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    float CRC_INDICATION_REL8_TAG;
};

class DynamicValueGenerator {
public:
    DynamicValueGenerator(int min_val, int max_val) 
        : min(min_val), max(max_val) {
        if (min > max) {
            throw std::invalid_argument("Minimum value cannot be greater than maximum.");
        }
    }

    float generateRandomFloat() const {
        return static_cast<float>(min + rand() % (max - min + 1)) 
             + static_cast<float>(rand()) / RAND_MAX;
    }

    int generateRandomIntInclusive() const {
        return min + rand() % (max - min + 1);
    }

    void validateAndFindMax(const std::vector<int>& numbers, int& max_valid) const {
        for (int num : numbers) {
            if (num >= min && num <= max) {
                if (num > max_valid) {
                    max_valid = num;
                }
            } else {
                std::cerr << "Warning: Number " << num 
                          << " is outside the valid range [" << min << ", " << max << "]" << std::endl;
            }
        }
    }

private:
    int min, max;
};

void GenerateNfarecIndications(std::vector<NFAPI_CRC_INDICATION_PDU_T>& indications, size_t count) {
    srand(static_cast<unsigned>(time(nullptr))); // Seed the random number generator

    DynamicValueGenerator valueGen(getMinFromEnv("CRCFLAG_MIN", 0), getMaxFromEnv("CRCFLAG_MAX", 100));

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 256;
        pdu.RNTI = rand() % 65536;
        pdu.CRC_INDICATION_REL8_TAG = valueGen.generateRandomFloat();
        indications.push_back(pdu);
    }
}

int getMinFromEnv(const std::string& var_name, int default_min) {
