#define LOGGING_RATE_LIMIT 1000000 // Max log entries per second

// Assuming these structures are defined elsewhere in your codebase
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    atomic_size_t current_usage;
    size_t peak_usage;
    pthread_mutex_t lock;
} MemoryUsageStats;

// External logging service integration placeholder
void async_log(const char* message);

static NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static atomic_size_t allocated_pdus = 0;
static size_t max_concurrent_threads = 10000;

// Memory usage statistics structure
MemoryUsageStats mem_stats = { .current_usage = 0, .peak_usage = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void initialize_memory_pool() {
    memory_pool = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, MEMORY_POOL_SIZE);
    if (!memory_pool) {
        async_log("Failed to allocate initial memory pool.");
        exit(EXIT_FAILURE);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pool_mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    size_t current_allocated = atomic_load_explicit(&allocated_pdus, memory_order_relaxed);

    if (current_allocated < MAX_PDU_COUNT) {
        pdu = &memory_pool[current_allocated];
        atomic_fetch_add_explicit(&allocated_pdus, 1, memory_order_release);

        // Update peak usage
        size_t current_usage = atomic_load_explicit(&mem_stats.current_usage, memory_order_relaxed);
        if (current_usage > mem_stats.peak_usage) {
            pthread_mutex_lock(&mem_stats.lock);
            mem_stats.peak_usage = current_usage;
            pthread_mutex_unlock(&mem_stats.lock);
        }

        // Populate the PDU
        pdu->RX_UE_INFORMATION_TAG = rand() % 65536; // Example randomization
        pdu->RNTI = rand(); // Example randomization
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    pthread_mutex_unlock(&pool_mutex);
    return pdu;
}

void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu >= memory_pool && pdu < &memory_pool[MAX_PDU_COUNT]) {
        size_t index = pdu - memory_pool;

        // Update current usage stats
        atomic_fetch_sub_explicit(&mem_stats.current_usage, 1, memory_order_release);
        pthread_mutex_lock(&pool_mutex);
        atomic_fetch_sub_explicit(&allocated_pdus, 1, memory_order_acquire);
        pthread_mutex_unlock(&pool_mutex);

        pdu->RX_UE_INFORMATION_TAG = 0;
        pdu->RNTI = 0;
        pdu->CRC_INDICATION_REL8_TAG = 0;
    }
}

void log_memory_usage() {
    size_t current_usage = atomic_load_explicit(&mem_stats.current_usage, memory_order_relaxed);

    // Asynchronously log the memory usage
    async_log(
        "Current Memory Usage: %zu, Peak Memory Usage: %zu",
        current_usage,
        mem_stats.peak_usage
    );
}

void report_memory_stats() {
    size_t current_usage = atomic_load_explicit(&mem_stats.current_usage, memory_order_relaxed);

    printf("Memory Stats - Current: %zu, Peak: %zu\n", current_usage, mem_stats.peak_usage);
}

int main() {
    initialize_memory_pool();
    atomic_store_explicit(&mem_stats.current_usage, 0, memory_order_relaxed);

    // Simulating allocation in a multithreaded environment
    pthread_t threads[100];
    for (size_t i = 0; i < 100; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))allocate_pdu, NULL) != 0) {
            async_log("Failed to create thread.");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for threads
    for (size_t i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_memory_usage();
    report_memory_stats();

    return 0;
}
