#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_PDUS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t mutex;
} PduManager;

// Error codes
#define SUCCESS 0
#define ALLOCATION_FAILURE -1
#define MAX_CAPACITY_REACHED -2
#define TIMEOUT_REACHED -3

// Function to initialize the PduManager
int initPduManager(PduManager *manager, size_t max_pdus) {
    if (max_pdus > MAX_PDUS) {
        return ALLOCATION_FAILURE;
    }

    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        return ALLOCATION_FAILURE;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return SUCCESS;
}

// Function to free the PduManager resources
void cleanupPduManager(PduManager *manager) {
    if (manager->pdus) {
        free(manager->pdus);
        manager->pdus = NULL;
    }
    pthread_mutex_destroy(&manager->mutex);
}

// Thread-safe function to create and populate PDUs
int createPDUs(PduManager *manager, size_t num_pdus, int timeout_ms) {
    if (num_pdus > MAX_PDUS - manager->count) {
        return MAX_CAPACITY_REACHED;
    }

    pthread_mutex_lock(&manager->mutex);

    time_t start_time = time(NULL);
    while (manager->count < num_pdus) {
        // Check for timeout
        if ((time(NULL) - start_time) * 1000 > timeout_ms) {
            pthread_mutex_unlock(&manager->mutex);
            return TIMEOUT_REACHED;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Generate a random tag
        pdu.RNTI = rand() % 65536; // Random RNTI within valid range
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC tag
