        manager->pdus[manager->count++] = pdu;
    }

    pthread_mutex_unlock(&manager->mutex);

    printf("Created %zu PDUs.\n", manager->count); // Log the number of PDUs created
    return SUCCESS;
}

int main() {
    PduManager manager;
    if (initPduManager(&manager, MAX_PDUS) != SUCCESS) {
        fprintf(stderr, "Failed to initialize PDU Manager.\n");
        return EXIT_FAILURE;
    }

    int result = createPDUs(&manager, 1000, 5000); // Attempt to create 1000 PDUs with a timeout of 5 seconds
    if (result == MAX_CAPACITY_REACHED) {
        fprintf(stderr, "Maximum capacity reached.\n");
    } else if (result == TIMEOUT_REACHED) {
        fprintf(stderr, "Operation timed out.\n");
    }

    cleanupPduManager(&manager);
    return EXIT_SUCCESS;
}
