#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} LinkedList;

void log_message(LogLevel level, const char* message) {
    switch (level) {
        case INFO:
            printf("[INFO]: %s\n", message);
            break;
        case WARNING:
            printf("[WARNING]: %s\n", message);
            break;
        case ERROR:
            printf("[ERROR]: %s\n", message);
            break;
    }
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_message(ERROR, "Failed to allocate memory for linked list.");
        return NULL;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int populate_nfa_pi_crc_indication_pdu_list(
    LinkedList* list,
    int num_entries,
    unsigned long max_rnti_value,
    unsigned long crc_threshold,
    LogLevel log_level) {

    if (list->count >= MAX_ENTRIES) {
        log_message(WARNING, "Maximum linked list size reached.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && num_entries > 0) {
        int duplicate_found = 0;

        if (current->data.RNTI >= max_rnti_value + 1) {
            log_message(ERROR, "RNTI value out of range.");
            // Move to next node
            current = current->next;
            continue;
        }

        unsigned long crc_sum = current->data.CRC_INDICATION_REL8_TAG;

        Node* check_node = list->head;
        while (check_node) {
            if (check_node != current && check_node->data.RNTI == current->data.RNTI) {
                duplicate_found = 1;
                crc_sum += check_node->data.CRC_INDICATION_REL8_TAG;
                // Remove the duplicate node
                Node* temp = check_node;
                if (check_node == list->head) {
                    list->head = check_node->next;
                } else {
                    Node* prev = list->head;
                    while (prev && prev->next != check_node) {
                        prev = prev->next;
                    }
                    prev->next = check_node->next;
                }
                free(temp);
                list->count--;
            }
            check_node = check_node->next;
        }

        if (!duplicate_found) {
            current->data.CRCFLAG = (crc_sum >= crc_threshold) ? 1 : 0;
            log_message(log_level, "Populated entry with valid RNTI and CRC.");
        } else {
            log_message(INFO, "Merged duplicate RNTI entries.");
        }

        num_entries--;
        if (num_entries == 0 || current->next == NULL) {
            break;
        }
        current = current->next;
    }

    while (num_entries > 0 && list->count < MAX_ENTRIES) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            log_message(ERROR, "Failed to allocate memory for new node.");
            break;
        }

        // Simulate data population
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        new_node->data.RNTI = (rand() % max_rnti_value) + 1;  // Within range
        new_node->data.CRC_INDICATION_REL8_TAG = rand() % 1000;

        if (new_node->data.RNTI >= max_rnti_value + 1) {
            log_message(ERROR, "RNTI value out of range for new node.");
            free(new_node);
            break;
        }

        unsigned long crc_sum = new_node->data.CRC_INDICATION_REL8_TAG;

        Node* check_node = list->head;
        while (check_node) {
            if (check_node->data.RNTI == new_node->data.RNTI) {
                crc_sum += check_node->data.CRC_INDICATION_REL8_TAG;
                free(new_node);
                check_node->data.CRCFLAG = (crc_sum >= crc_threshold) ? 1 : 0;
                log_message(log_level, "Merged duplicate RNTI entries.");
                num_entries--;
                break;
            }
            check_node = check_node->next;
        }

        if (!check_node) {
            new_node->data.CRCFLAG = (crc_sum >= crc_threshold) ? 1 : 0;
            new_node->next = list->head;
            list->head = new_node;
            list->count++;
            log_message(log_level, "Added new node.");
            num_entries--;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return (num_entries == 0) ? 0 : -1; // Return error if not all entries were added
}

// Example usage:
int main() {
    LinkedList* list = create_linked_list();
    int result = populate_nfa_pi_crc_indication_pdu_list(
        list, 
        500, // Number of entries to add
        1000, // Max RNTI value
        500, // CRC threshold
        INFO // Logging level
    );

    if (result == -1) {
        log_message(ERROR, "Failed to populate the linked list.");
    } else {
        log_message(INFO, "Linked list populated successfully.");
    }

    free_linked_list(list);
    return 0;
}
```

