    manager->max_double_value = -1.0;
    pthread_mutex_init(&manager->lock, NULL);
    return (Record*)manager;
}

void record_free(Record *record) {
    RecordManager *manager = (RecordManager *)record;
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NFAPIListManager* nfaapi_list_alloc(size_t capacity) {
    NFAPIListManager *list_manager = malloc(sizeof(NFAPIListManager));
    list_manager->list = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list_manager->size = 0;
    list_manager->capacity = capacity;
    pthread_mutex_init(&list_manager->lock, NULL);
    return list_manager;
}

void nfaapi_list_free(NFAPIListManager *list_manager) {
    free(list_manager->list);
    pthread_mutex_destroy(&list_manager->lock);
    free(list_manager);
}

void nfaapi_resize(NFAPIListManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(manager->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list) {
        manager->list = new_list;
        manager->capacity = new_capacity;
    } else {
        log_warning("Memory allocation failed during resize");
    }
}

void add_pdu(NFAPIListManager *manager, int rx_tag, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    if (rnti < 1 || rnti > 65535) {
        log_warning("RNTI out of range");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (manager->size >= manager->capacity) {
        nfaapi_resize(manager);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {rx_tag, rnti, generate_random_crcflag()};
    manager->list[manager->size++] = pdu;

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    srand(time(NULL));  // Seed random number generator

    NFAPIListManager *nfaapi_list = nfaapi_list_alloc(MAX_ENTRIES);

    for (int i = 0; i < 1200; ++i) { // Test adding more than initial capacity
        add_pdu(nfaapi_list, i, rand() % 70000); // Random RNTI, some out of range
    }

    nfaapi_list_free(nfaapi_list);

    Record *records = record_alloc(10);

    // Example usage of records
    for (size_t i = 0; i < records->capacity; ++i) {
        pthread_mutex_lock(&((RecordManager *)records)->lock);

        if (((RecordManager *)records)->count >= ((RecordManager *)records)->capacity) {
            break;
        }

        Record *rec = &(((RecordManager *)records)->records[((RecordManager *)records)->count]);
        rec->offset = rand();
        rec->key = rand();
        rec->value = (double)rand() / RAND_MAX;

        if (rec->value > ((RecordManager *)records)->max_double_value) {
            ((RecordManager *)records)->max_double_value = rec->value;
        }

        ((RecordManager *)records)->count++;

        pthread_mutex_unlock(&((RecordManager *)records)->lock);
    }

    record_free(records);

    return 0;
}
