    char CRCFLAG[2]; // Example size
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray* da) {
    pthread_mutex_init(&da->lock, NULL);
    da->size = 0;
    da->capacity = 100; // Initial capacity
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void freeDynamicArray(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    if (da->array) {
        free(da->array);
        da->array = NULL;
    }
    pthread_mutex_unlock(&da->lock);
    pthread_mutex_destroy(&da->lock);
}

int resizeDynamicArray(DynamicArray* da, size_t new_capacity) {
    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_array) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Memory allocation failed
    }
    da->array = temp_array;
    da->capacity = new_capacity;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int addNFAPI_CRC_INDICATION_PDU(DynamicArray* da, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, const char* CRCFLAG) {
    if (da->size >= MAX_UE_SESSIONS || da->capacity <= da->size) {
        size_t new_capacity = da->capacity * 2;
        if (new_capacity > MAX_UE_SESSIONS) new_capacity = MAX_UE_SESSIONS;
        if (resizeDynamicArray(da, new_capacity)) return -1; // Handle memory allocation failure
    }

    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T pdu = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG};
    strncpy(pdu.CRCFLAG, CRCFLAG, sizeof(pdu.CRCFLAG) - 1);
    da->array[da->size++] = pdu;
    pthread_mutex_unlock(&da->lock);

    return 0;
}

