    pthread_mutex_t lock;
} SafeList;

SafeList* create_safe_list() {
    SafeList* list = (SafeList*)custom_alloc(sizeof(SafeList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_to_list(SafeList *list, NFAPI_RX_FRAME_INFO info) {
    ListNode* new_node = (ListNode*)custom_alloc(sizeof(ListNode));
    new_node->info = info;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
    } else {
        ListNode *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

// Validation function for RRC_CONFIG
int validate_rrc_config(RRC_CONFIG *config, int threshold) {
    // Example: calculate completeness score
    config->completeness_score = (config->field1 != 0) + (config->field2 != 0);

    // Validate based on a predefined threshold
    return config->completeness_score >= threshold;
}

// Initialize list of NFAPI_RX_FRAME_INFO structures
void initialize_nfa_rx_frame_info(SafeList *nfa_list, int num_entries, int completeness_threshold) {
    pthread_t threads[10]; // Assume max 10 concurrent threads for this example

    void* thread_task(void* arg) {
        int index = *(int*)arg;
        NFAPI_RX_FRAME_INFO frame_info;

        // Generate a valid UE_ID and tag
        frame_info.ue_id.id = rand();
        frame_info.tag.tag = rand();

        RRC_CONFIG *rrc_config = (RRC_CONFIG*)custom_alloc(sizeof(RRC_CONFIG));

        if (!rrc_config) {
            fprintf(stderr, "Memory allocation failed for RRC_CONFIG\n");
            pthread_exit(NULL);
        }

        // Example initialization of fields
        rrc_config->field1 = rand() % 2;
        rrc_config->field2 = rand() % 2;

        if (validate_rrc_config(rrc_config, completeness_threshold)) {
            frame_info.rrc_config = rrc_config;
            add_to_list(nfa_list, frame_info);
        } else {
            fprintf(stderr, "RRC_CONFIG validation failed for UE_ID: %d\n", frame_info.ue_id.id);
            custom_free(rrc_config);
        }

        pthread_exit(NULL);
    }

    // Creating threads
    for (int i = 0; i < num_entries && i < 10; i++) {
        int *index_ptr = malloc(sizeof(int));
        *index_ptr = i;
        if (pthread_create(&threads[i], NULL, thread_task, index_ptr) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    // Joining threads
    for (int i = 0; i < num_entries && i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Periodic cleanup function (simplified)
void* periodic_cleanup(void* arg) {
    SafeList *list = (SafeList*)arg;
    while (1) {
        sleep(60); // Run every minute

        pthread_mutex_lock(&list->lock);
        ListNode **current = &list->head;
        while (*current) {
            if (/* some condition for cleanup */) {
                ListNode* to_delete = *current;
                *current = (*current)->next;
                custom_free(to_delete);
            } else {
                current = &(*current)->next;
            }
        }
        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

// Example function to export the list (simplified)
