#include <iostream>
#include <vector>
#include <random>
#include <algorithm>

struct NFAPI_STATISTICS_PDU_T {
    int RX_POWER_LEVEL;
    float SINR;
    int UE_RX_QUALITY;
};

class NFAPIDiagnostics {
public:
    std::vector<NFAPI_STATISTICS_PDU_T> initializeNFAPIStatistics(size_t count);

private:
    static constexpr int MIN_RX_POWER_LEVEL = -120;
    static constexpr int MAX_RX_POWER_LEVEL = -30;

    static constexpr float MIN_SINR = 0.0f;
    static constexpr float MAX_SINR = 30.0f;

    static constexpr int MIN_UE_RX_QUALITY = 1;
    static constexpr int MAX_UE_RX_QUALITY = 100;

    NFAPI_STATISTICS_PDU_T generateStatistics();

    bool validateMetrics(int rxPower, float sinr, int ueRxQuality);
};

std::vector<NFAPI_STATISTICS_PDU_T> NFAPIDiagnostics::initializeNFAPIStatistics(size_t count) {
    std::vector<NFAPI_STATISTICS_PDU_T> statistics;

    for (size_t i = 0; i < count; ++i) {
        NFAPI_STATISTICS_PDU_T stat = generateStatistics();

        if (validateMetrics(stat.RX_POWER_LEVEL, stat.SINR, stat.UE_RX_QUALITY)) {
            statistics.push_back(stat);
        } else {
            std::cerr << "Warning: Generated metrics out of range. Using default values.\n";
            NFAPI_STATISTICS_PDU_T defaultStat = {0, 0.0f, 0};
            statistics.push_back(defaultStat);
        }
    }

    return statistics;
}

NFAPI_STATISTICS_PDU_T NFAPIDiagnostics::generateStatistics() {
    std::random_device rd;
    std::mt19937 gen(rd());

    std::uniform_int_distribution<> rxPowerDist(MIN_RX_POWER_LEVEL, MAX_RX_POWER_LEVEL);
    std::uniform_real_distribution<float> sinrDist(MIN_SINR, MAX_SINR);
    std::uniform_int_distribution<> ueRxQualityDist(MIN_UE_RX_QUALITY, MAX_UE_RX_QUALITY);

    return {rxPowerDist(gen), sinrDist(gen), ueRxQualityDist(gen)};
}

bool NFAPIDiagnostics::validateMetrics(int rxPower, float sinr, int ueRxQuality) {
    return (rxPower >= MIN_RX_POWER_LEVEL && rxPower <= MAX_RX_POWER_LEVEL &&
            sinr >= MIN_SINR && sinr <= MAX_SINR &&
            ueRxQuality >= MIN_UE_RX_QUALITY && ueRxQuality <= MAX_UE_RX_QUALITY);
}

int main() {
    NFAPIDiagnostics diagnostics;
    std::vector<NFAPI_STATISTICS_PDU_T> stats = diagnostics.initializeNFAPIStatistics(10);

    for (const auto& stat : stats) {
        std::cout << "RX_POWER_LEVEL: " << stat.RX_POWER_LEVEL
                  << ", SINR: " << stat.SINR
                  << ", UE_RX_QUALITY: " << stat.UE_RX_QUALITY << "\n";
    }

    return 0;
}
