// Define the LTEPHYRRCALCUFDMETAG_T structure
typedef struct {
    int id;  // Unique identifier for each RF channel configuration
    float frequency;
    int bandwidth;
    // Add other relevant fields here as needed

} LTEPHYRRCALCUFDMETAG_T;

// Dynamic array management structure
typedef struct {
    LTEPHYRRCALCUFDMETAG_T *array;  // Pointer to dynamically allocated memory for structures
    size_t capacity;                // Current maximum number of elements the array can hold
    size_t size;                    // Current number of elements in the array
} LTEPHYArray;

// Function prototypes
int initializeLtePhyArray(LTEPHYArray *array);
int resizeArrayIfNeeded(LTEPHYArray *array, size_t newSize);
int addOrUpdateLtePhyTag(LTEPHYArray *array, int id, float frequency, int bandwidth);
LTEPHYRRCALCUFDMETAG_T* retrieveLtePhyTag(const LTEPHYArray *array, int id);
void freeLtePhyArray(LTEPHYArray *array);

// Initialize the dynamic array
int initializeLtePhyArray(LTEPHYArray *array) {
    if (!array) return -1;
    array->capacity = 10; // Initial capacity, can be adjusted based on expected load
    array->size = 0;

    array->array = (LTEPHYRRCALCUFDMETAG_T *)malloc(array->capacity * sizeof(LTEPHYRRCALCUFDMETAG_T));
    if (!array->array) return -1; // Memory allocation failed

    return 0;
}

// Resize the array if needed
int resizeArrayIfNeeded(LTEPHYArray *array, size_t newSize) {
    if (newSize > array->capacity) {
        LTEPHYRRCALCUFDMETAG_T *temp = realloc(array->array, newSize * sizeof(LTEPHYRRCALCUFDMETAG_T));
        if (!temp) return -1; // Memory allocation failed
        array->array = temp;
        array->capacity = newSize;
    }
    return 0;
}

// Add or update an LTEPHYRRCALCUFDMETAG_T instance in the dynamic array
int addOrUpdateLtePhyTag(LTEPHYArray *array, int id, float frequency, int bandwidth) {
    if (!array || !array->array) return -1;

    // Check for existing entry with same ID and update it
    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].id == id) {
            array->array[i].frequency = frequency;
            array->array[i].bandwidth = bandwidth;
            return 0;
        }
    }

    // If not found, add a new entry
    if (resizeArrayIfNeeded(array, array->size + 1) != 0) return -1;

    LTEPHYRRCALCUFDMETAG_T *newTag = &array->array[array->size];
    newTag->id = id;
    newTag->frequency = frequency;
    newTag->bandwidth = bandwidth;
    array->size++;

    return 0;
}

// Retrieve an LTEPHYRRCALCUFDMETAG_T instance by ID
LTEPHYRRCALCUFDMETAG_T* retrieveLtePhyTag(const LTEPHYArray *array, int id) {
    if (!array || !array->array) return NULL;

    for (size_t i = 0; i < array->size; ++i) {
        if (array->array[i].id == id) {
            return &array->array[i];
        }
    }

    return NULL;
}

// Free the dynamic array and its resources
void freeLtePhyArray(LTEPHYArray *array) {
    if (!array || !array->array) return;

    free(array->array);
    array->array = NULL;
    array->capacity = 0;
    array->size = 0;
}

// Example usage
int main() {
    LTEPHYArray ltePhyArray;

    initializeLtePhyArray(&ltePhyArray);

    addOrUpdateLtePhyTag(&ltePhyArray, 1, 1800.5, 20);
    addOrUpdateLtePhyTag(&ltePhyArray, 2, 2600.7, 15);

    LTEPHYRRCALCUFDMETAG_T *tag = retrieveLtePhyTag(&ltePhyArray, 1);
    if (tag) {
        printf("Retrieved Tag: ID=%d, Frequency=%.1f, Bandwidth=%d\n", tag->id, tag->frequency, tag->bandwidth);
    } else {
        printf("Tag not found.\n");
    }

    freeLtePhyArray(&ltePhyArray);

    return 0;
}
