// Define structures as per requirement.
typedef struct {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex and condition variable for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Dynamic array structure with metadata
typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data_array;
} CRC_INDICATION_ARRAY;

// Function prototypes
void initialize_crc_array(CRC_INDICATION_ARRAY* array, size_t initial_capacity);
void free_crc_array(CRC_INDICATION_ARRAY* array);
int add_to_crc_array(CRC_INDICATION_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T element);
void update_elements_from_source(CRC_INDICATION_ARRAY* array, int (*data_source)(int*, int*));
void serialize_data(const CRC_INDICATION_ARRAY* array, char** output_buffer, size_t* buffer_size);
CRC_INDICATION_ARRAY deserialize_data(const char* input_buffer);

// Function implementations
void initialize_crc_array(CRC_INDICATION_ARRAY* array, size_t initial_capacity) {
    pthread_mutex_lock(&lock);
    array->capacity = initial_capacity;
    array->count = 0;
    array->data_array = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data_array) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&lock);
}

void free_crc_array(CRC_INDICATION_ARRAY* array) {
    pthread_mutex_lock(&lock);
    free(array->data_array);
    pthread_mutex_unlock(&lock);
}

int add_to_crc_array(CRC_INDICATION_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T element) {
    int success = 0;
    pthread_mutex_lock(&lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data_array = realloc(array->data_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data_array) {
            fprintf(stderr, "Failed to reallocate memory\n");
            pthread_mutex_unlock(&lock);
            return 0;
        }
        array->data_array = new_data_array;
        array->capacity = new_capacity;
    }

    array->data_array[array->count++] = element;
    success = 1;

    pthread_mutex_unlock(&lock);
    return success;
}

void update_elements_from_source(CRC_INDICATION_ARRAY* array, int (*data_source)(int*, int*)) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < array->count; ++i) {
        int rx_ue_tag, rnti;
        if (data_source(&rx_ue_tag, &rnti)) {
            array->data_array[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
            array->data_array[i].RNTI = rnti;
            array->data_array[i].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        }
    }

    pthread_mutex_unlock(&lock);
}

void serialize_data(const CRC_INDICATION_ARRAY* array, char** output_buffer, size_t* buffer_size) {
    size_t total_length = sizeof(size_t) + array->count * (sizeof(int) + sizeof(int) + sizeof(uint32_t));

    *output_buffer = malloc(total_length);
    if (!*output_buffer) {
        fprintf(stderr, "Failed to allocate memory for serialization\n");
        exit(EXIT_FAILURE);
    }

    char* buffer_ptr = *output_buffer;
    memcpy(buffer_ptr, &(array->count), sizeof(size_t));
    buffer_ptr += sizeof(size_t);

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < array->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = array->data_array[i];
        memcpy(buffer_ptr, &(pdu.RX_UE_INFORMATION_TAG), sizeof(int));
        buffer_ptr += sizeof(int);

        memcpy(buffer_ptr, &(pdu.RNTI), sizeof(int));
        buffer_ptr += sizeof(int);

        memcpy(buffer_ptr, &(pdu.crc_tag.CRCFLAG), sizeof(uint32_t));
        buffer_ptr += sizeof(uint32_t);
    }
    pthread_mutex_unlock(&lock);

    *buffer_size = total_length;
}

CRC_INDICATION_ARRAY deserialize_data(const char* input_buffer) {
    CRC_INDICATION_ARRAY array;

    pthread_mutex_lock(&lock);
    size_t count;
    memcpy(&(count), input_buffer, sizeof(size_t));
    input_buffer += sizeof(size_t);

    initialize_crc_array(&array, count);

    for (size_t i = 0; i < count; ++i) {
        int rx_ue_tag, rnti;
        uint32_t crc_flag;

        memcpy(&(rx_ue_tag), input_buffer, sizeof(int));
        input_buffer += sizeof(int);

        memcpy(&(rnti), input_buffer, sizeof(int));
        input_buffer += sizeof(int);

        memcpy(&crc_flag, input_buffer, sizeof(uint32_t));
        input_buffer += sizeof(uint32_t);

        NFAPI_CRC_INDICATION_PDU_T pdu = {rx_ue_tag, rnti, {.CRCFLAG = crc_flag}};
        add_to_crc_array(&array, pdu);
    }
    pthread_mutex_unlock(&lock);

    return array;
}
