#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    time_t timestamp;
    double temperature;
    double humidity;
    int batteryLevel;
} SensorReading;

typedef struct Node {
    SensorReading data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t length;
    pthread_mutex_t lock;
} ReadingList;

// Function to create a new list
ReadingList* create_reading_list() {
    ReadingList* list = (ReadingList*)malloc(sizeof(ReadingList));
    if (!list) return NULL;
    list->head = NULL;
    list->length = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new reading
void add_reading(ReadingList* list, SensorReading reading) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->data = reading;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    list->length++;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove outdated entries
void remove_outdated_entries(ReadingList* list, time_t retentionPeriod) {
    Node *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > retentionPeriod) {
            Node* toDelete = current;
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            current = current->next;
            free(toDelete);
            list->length--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to compute average temperature and humidity within a time window
void compute_averages(ReadingList* list, time_t start, time_t end, double *avgTemp, double *avgHum) {
    size_t count = 0;
    double tempSum = 0.0, humSum = 0.0;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.timestamp >= start && current->data.timestamp <= end) {
            tempSum += current->data.temperature;
            humSum += current->data.humidity;
            count++;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    if (count > 0) {
        *avgTemp = tempSum / count;
        *avgHum = humSum / count;
    } else {
        *avgTemp = NAN;
        *avgHum = NAN;
    }
}

// Function to handle API calls with exponential backoff
int fetch_weather_data_with_retry(const char* url, int retries) {
    for (int i = 0; i < retries; ++i) {
        // Simulate an API call
        int success = rand() % 2;  // Randomly simulate success or failure
        if (success) return 1;

        sleep(1 << i);  // Exponential backoff: wait 1, 2, 4, ... seconds
    }
    return 0;  // Failed to fetch data after retries
}

// Function to free the list and its nodes
void destroy_reading_list(ReadingList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    ReadingList* sensorData = create_reading_list();

    // Add some example readings
    SensorReading reading1 = { time(NULL) - 3600, 25.5, 60.2, 85 };
    add_reading(sensorData, reading1);

    SensorReading reading2 = { time(NULL), 26.1, 58.4, 90 };
    add_reading(sensorData, reading2);

    // Remove outdated readings
    remove_outdated_entries(sensorData, 7200);  // Retain entries within last 2 hours

    // Compute averages over the past hour
    double avgTemp, avgHum;
    compute_averages(sensorData, time(NULL) - 3600, time(NULL), &avgTemp, &avgHum);

    printf("Average Temperature: %.2f\n", avgTemp);
    printf("Average Humidity: %.2f\n", avgHum);

    // Fetch weather data with retries
    if (fetch_weather_data_with_retry("http://example.com/weather_api", 3)) {
        printf("Weather data fetched successfully.\n");
    } else {
        printf("Failed to fetch weather data after multiple attempts.\n");
    }

    // Clean up
    destroy_reading_list(sensorData);

    return 0;
}
