    new_node->data.rnti = rnti;
    new_node->data.crc_flag = (rand() / (double)RAND_MAX < CRC_FLAG_SET_PROBABILITY) ? 1 : 0;

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    log_creation("Node created");

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(const CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    fclose(file);
}

int deserialize_list(CRCList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            destroy_list(list);
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -2;
        }

        new_node->data = data;
        new_node->next = current;
        current = new_node;
    }

    list->head = current;
    Node* temp = list->head;
    while (temp) {
        temp = temp->next;
        list->size++;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

void clear_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    destroy_list(list);
    list->head = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}
