// Function to initialize the manager
void initRrcPduManager(RrcPduManager* manager, double initial_memory_threshold) {
    manager->array = malloc(INITIAL_CAPACITY * sizeof(NFAPI_RRC_CU_UP_RX_PDU_T));
    if (!manager->array) exit(EXIT_FAILURE);
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->memory_threshold = initial_memory_threshold;
}

// Function to resize the array
void resizeRrcPduManager(RrcPduManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_RRC_CU_UP_RX_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_RRC_CU_UP_RX_PDU_T));
    if (!new_array) exit(EXIT_FAILURE);
    manager->array = new_array;
    manager->capacity = new_capacity;
}

// Function to add a new PDU
void addRrcPdu(RrcPduManager* manager, NFAPI_RRC_CU_UP_RX_PDU_T pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        resizeRrcPduManager(manager);
    }

    manager->array[manager->count++] = pdu;

    // Simulate random CRCFLAG
    for (size_t i = 0; i < pdu.tag_count; ++i) {
        pdu.context_tags[i].CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to update memory threshold dynamically
void setMemoryThreshold(RrcPduManager* manager, double new_threshold) {
    pthread_mutex_lock(&manager->mutex);
    manager->memory_threshold = new_threshold;
    pthread_mutex_unlock(&manager->mutex);
}

// Health monitoring function (stub)
