            temp = *current;
            *current = (*current)->next;
            free(temp->data.sessions);
            free(temp);
            pthread_mutex_unlock(&list->mutex);
            return 0; // Successfully removed
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&list->mutex);

    return -1; // Subscription not found
}

