} ContextManager;

int log_event(const char* event) {
    time_t now = time(NULL);
    return fprintf(stdout, "[%ld] %s\n", now, event); // Replace with actual logging
}

ContextManager* init_context_manager() {
    ContextManager *manager = (ContextManager*)malloc(sizeof(ContextManager));
    if (!manager) return NULL;

    manager->contexts = (LTE_UE_Context*)calloc(MAX_CONTEXT_COUNT, sizeof(LTE_UE_Context));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    log_event("ContextManager initialized");
    return manager;
}

int add_context(ContextManager *manager, unsigned short UEI, unsigned int ServingCellID) {
    if (UEI < 0x0001 || UEI > 0xFFFF) {
        log_event("Invalid UE Identifier");
        return -1; // Invalid UE Identifier
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_CONTEXT_COUNT) {
        pthread_mutex_unlock(&manager->lock);
        log_event("Context list full");
        return -2; // List is full
    }

    LTE_UE_Context *context = &manager->contexts[manager->count++];
    context->UEI = UEI;
    context->ServingCellID = ServingCellID;
    context->RRCState = (rand() % 100 < 75) ? 'E' : 'R';

    log_event("Context added");

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void clear_contexts(ContextManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        manager->contexts[i].UEI = 0;
        manager->contexts[i].ServingCellID = 0;
        manager->contexts[i].RRCState = '\0';
    }
    manager->count = 0;

    log_event("Context list cleared");

    pthread_mutex_unlock(&manager->lock);
}

void free_context_manager(ContextManager *manager) {
    if (manager) {
        clear_contexts(manager);
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
        log_event("ContextManager freed");
    }
}

int serialize_to_file(ContextManager *manager, const char* filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // File open failed
    }

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->contexts, sizeof(LTE_UE_Context), manager->count, file);

    fclose(file);
    log_event("Serialized to file");

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int deserialize_from_file(ContextManager *manager, const char* filename) {
    pthread_mutex_lock(&manager->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // File open failed
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > MAX_CONTEXT_COUNT || count != manager->count) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -2; // Invalid data or mismatch in context count
    }

    fread(manager->contexts, sizeof(LTE_UE_Context), count, file);

    manager->count = count;
    fclose(file);
    log_event("Deserialized from file");

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int main() {
    srand((unsigned int)time(NULL));

    ContextManager *manager = init_context_manager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize context manager\n");
        return -1;
    }

    add_context(manager, 0x000A, 12345);
    serialize_to_file(manager, "contexts.bin");
    deserialize_from_file(manager, "contexts.bin");

    free_context_manager(manager);

    return 0;
}
```

This implementation addresses memory management, logging with minimal overhead, thread safety, and lifecycle event recording. It includes serialization/deserialization for saving/restoring contexts while handling file I/O errors. The use of mutex ensures that the list remains consistent under concurrent access, which is crucial in high-load scenarios.']

