#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int protocol;
    char metadata[256];
} PacketHeader;

typedef struct {
    int FlowID;
    char SourceAddress[50];
    char DestinationAddress[50];
    PacketHeader *packetHeaders; // Dynamic array
    size_t packetCount;
} TrafficFlow;

typedef struct Node {
    TrafficFlow flow;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int currentID;
} TrafficManager;

TrafficManager* init_traffic_manager() {
    TrafficManager* manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->currentID = 0;
    return manager;
}

int add_flow(TrafficManager* manager, const char* sourceAddr, const char* destAddr, int protocol) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;

    TrafficFlow newFlow;
    newFlow.FlowID = manager->currentID++;
    strncpy(newFlow.SourceAddress, sourceAddr, sizeof(newFlow.SourceAddress));
    strncpy(newFlow.DestinationAddress, destAddr, sizeof(newFlow.DestinationAddress));
    newFlow.packetHeaders = NULL;
    newFlow.packetCount = 0;

    newNode->flow = newFlow;
    newNode->next = manager->head;
    manager->head = newNode;

    return newFlow.FlowID;
}

int add_packet_header(TrafficManager* manager, int flowID, const PacketHeader* header) {
    Node* current = manager->head;
    while (current) {
        if (current->flow.FlowID == flowID) {
            TrafficFlow* flow = &current->flow;
            flow->packetHeaders = realloc(flow->packetHeaders, 
                                          (flow->packetCount + 1) * sizeof(PacketHeader));
            if (!flow->packetHeaders) return -1;

            memcpy(&flow->packetHeaders[flow->packetCount], header, sizeof(PacketHeader));
            flow->packetCount++;
            return 0;
        }
        current = current->next;
    }
    return -2; // Flow not found
}

int remove_flow(TrafficManager* manager, int flowID) {
    Node *current = manager->head, *prev = NULL;

    while (current) {
        if (current->flow.FlowID == flowID) {
            if (prev)
                prev->next = current->next;
            else
                manager->head = current->next;

            free(current->flow.packetHeaders);
            free(current);

            return 0;
        }
        prev = current;
        current = current->next;
    }

    return -1; // Flow not found
}

void cleanup_traffic_manager(TrafficManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current->flow.packetHeaders);
        free(current);
        current = next;
    }
    free(manager);
}

// Unit tests
void test_traffic_manager() {
    TrafficManager* manager = init_traffic_manager();

    int flowID1 = add_flow(manager, "192.168.0.1", "192.168.0.2", 6);
    PacketHeader header = {6, "Some metadata"};
    add_packet_header(manager, flowID1, &header);

    // Check if packet was added
    Node* node = manager->head;
    if (node && strcmp(node->flow.SourceAddress, "192.168.0.1") == 0) {
        printf("Test passed: Flow and packet addition.\n");
    } else {
        printf("Test failed: Flow or packet not found.\n");
    }

    remove_flow(manager, flowID1);
    if (!manager->head) {
        printf("Test passed: Flow removal.\n");
    } else {
        printf("Test failed: Flow not removed properly.\n");
    }

    cleanup_traffic_manager(manager);
}

int main() {
    test_traffic_manager();
    return 0;
}
```

