    if (!manager) return NULL;

    manager->array = (LTE_RRC_MIB_INFO *)calloc(initial_capacity, sizeof(LTE_RRC_MIB_INFO));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    atomic_store(&manager->last_update_time, time(NULL));

    return manager;
}

// Resize the array if needed
bool resize_array(MIB_Manager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_RRC_MIB_INFO *new_array = (LTE_RRC_MIB_INFO *)realloc(manager->array, new_capacity * sizeof(LTE_RRC_MIB_INFO));

        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    pthread_mutex_unlock(&manager->lock);
    return true;
}

// Add or update MIB information
bool add_update_mib_info(MIB_Manager *manager, int RX_UE_INFORMATION_TAG, int RNTI, int crcflag) {
    if (!resize_array(manager)) return false;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            manager->array[i].RNTI = RNTI;
            manager->array[i].CRCFLAG = crcflag;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    manager->array[manager->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    manager->array[manager->count].RNTI = RNTI;
    manager->array[manager->count].CRCFLAG = crcflag;
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
    return true;
}

// Retrieve latest SIB content
LTE_RRC_MIB_INFO* get_latest_sib(MIB_Manager *manager, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            LTE_RRC_MIB_INFO *info = &manager->array[i];
            pthread_mutex_unlock(&manager->lock);
            return info;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Execute command and manage file
void execute_command_and_manage_file(const char* command, const char* args[], const char *filename) {
    struct stat buffer;
    if (stat(filename, &buffer) == 0) {
        remove(filename);
    }

    pid_t pid = fork();
    if (pid == 0) { // Child process
        execvp(command, (char* const*)args);
        exit(EXIT_FAILURE); // If exec fails
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);

        FILE *fp = fopen(filename, "r");
        if (!fp) return;

        char line[128];
        while (fgets(line, sizeof(line), fp)) {
            printf("%s", line);
        }
        fclose(fp);
    } else {
        perror("fork failed");
    }
}

// Periodic update handler
void *periodic_update_handler(void *arg) {
    MIB_Manager *manager = (MIB_Manager *)arg;

    while (true) {
        // Simulate external data source fetching and updating logic here

        atomic_store(&manager->last_update_time, time(NULL));
        sleep(5); // Periodically update every 5 seconds
    }
}

// Cleanup MIB Manager
void cleanup_mib_manager(MIB_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}
```

