typedef struct {
    unsigned int rx_ue_information_tag;
    unsigned int rnti;
    unsigned char crc_flag; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->capacity = initial_capacity;
    mp->count = 0;
    pthread_mutex_init(&mp->mutex, NULL);

    return mp;
}

int append_to_memory_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mp->mutex);

    if (mp->count >= mp->capacity) {
        size_t new_capacity = mp->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(mp->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->mutex);
            return -1; // Reallocation failed
        }
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }

    mp->pool[mp->count++] = pdu;

    pthread_mutex_unlock(&mp->mutex);
    return 0;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp) {
        pthread_mutex_destroy(&mp->mutex);
        free(mp->pool);
        free(mp);
    }
}

