typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with thread-safe management
typedef struct {
    Node* head;
    pthread_mutex_t lock;  // Mutex for synchronizing access to the list
} NFAPIList;

// Function prototypes
NFAPIList* create_list();
void destroy_list(NFAPIList* list);
int add_pdu(NFAPIList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu);
int validate_crc_tag(const unsigned char* tag);

// Create a new list with initialized mutex
NFAPIList* create_list() {
    NFAPIList* list = (NFAPIList*)malloc(sizeof(NFAPIList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free all allocated memory
void destroy_list(NFAPIList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the list
int add_pdu(NFAPIList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return -1;
    }

    // Validate the CRC indication tag
    if (!validate_crc_tag(pdu->CRC_INDICATION_REL8_TAG)) {
        free(new_node);
        fprintf(stderr, "Invalid CRC_INDICATION_REL8_TAG\n");
        return -1;
    }

    // Copy data to new node
    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;  // Insert at the head for O(1) insertion
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Validate CRC_INDICATION_REL8_TAG (example validation logic)
