#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data_array;
    size_t capacity;
    pthread_mutex_t lock;
    unsigned int allocation_count;
    time_t seed_time;
} DynamicArrayContext;

void initialize_context(DynamicArrayContext *context) {
    context->data_array = NULL;
    context->capacity = 0;
    pthread_mutex_init(&context->lock, NULL);
    context->allocation_count = 0;
    context->seed_time = time(NULL);
}

static uint8_t generate_crc_flag(void* seed_ptr) {
    srand((unsigned int)(uintptr_t)seed_ptr ^ (unsigned int)time(NULL));
    return rand() & 1; // Randomly generates 0 or 1
}

DynamicArrayContext* create_dynamic_array(size_t n, uint8_t *temp_buffer, int log_fd) {
    if (n <= 0) return NULL;

    DynamicArrayContext* context = malloc(sizeof(DynamicArrayContext));
    initialize_context(context);

    size_t required_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&context->lock);
    context->data_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_size);
    if (!context->data_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(context);
        return NULL;
    }
    context->capacity = n;

    for (size_t i = 0; i < n; ++i) {
        context->data_array[i].RX_UE_INFORMATION_TAG = (uint16_t)i + 1;
        context->data_array[i].RNTI = (uint32_t)(rand_r(&context->seed_time) % 10000);
        context->data_array[i].CRCFLAG = generate_crc_flag(temp_buffer);

        // Logging every 100th allocation
        if (++(context->allocation_count) % 100 == 0) {
            size_t current_usage = required_size;
            fprintf(log_fd, "Memory Usage: Peak=%zu, Current=%zu\n", context->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), current_usage);
        }
    }

    pthread_mutex_unlock(&context->lock);

    return context;
}

void free_dynamic_array(DynamicArrayContext* context) {
    if (context) {
        pthread_mutex_lock(&context->lock);
        if (context->data_array) {
            free(context->data_array);
            context->data_array = NULL;
        }
        context->capacity = 0;
        pthread_mutex_unlock(&context->lock);

        pthread_mutex_destroy(&context->lock);
        free(context);
    }
}

