            free(list);
            list = NULL;
        }
    }

    if (!list) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Failed after retries
    }

    *allocated_count = num_structures;
    pthread_mutex_unlock(&mutex);

    return list;
}

