    atomic_uint64_t total_processing_time; // For performance monitoring
} List;

// Function to initialize the list
void init_list(List *list, size_t initial_capacity) {
    pthread_mutex_init(&list->lock, NULL);
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(16, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    atomic_init(&list->total_memory_usage, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    atomic_init(&list->total_processing_time, 0);
}

// Function to validate CRC_INDICATION_REL8_TAG
