    return (crc & 0xFF00) == (crc >> 8); // Simple parity check for demonstration
}

// Function to add an element to the list
void add_element(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_LIST_SIZE) {
        printf("Maximum list size reached. Reducing update frequency.\n");
        // Implement logic to reduce update frequency or degrade performance
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (!validate_crc(element.CRC_INDICATION_REL8_TAG)) {
        fprintf(stderr, "CRC validation failed for element with RNTI %d\n", element.RNTI);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)aligned_realloc(list->elements, 16, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            perror("Memory reallocation failed");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->count++] = element;

    atomic_fetch_add(&list->total_memory_usage, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->lock);
}

// Function to sanitize input data
