        printf("%s\n", message);
    }
}

// Function to query the list state for NMS
void get_list_state(const List *list, size_t *current_count, size_t *memory_usage, uint64_t *average_processing_time) {
    pthread_mutex_lock(&list->lock);
    *current_count = list->count;
    *memory_usage = atomic_load(&list->total_memory_usage);
    if (list->count > 0) {
        *average_processing_time = atomic_load(&list->total_processing_time) / list->count;
    } else {
        *average_processing_time = 0;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to clean up the list
void free_list(List *list) {
