typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
} ImageInfo;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t mutex;
} PDUArray;

typedef struct {
    const char *file_path;
    PDUArray *pdu_array;
} ThreadArg;

void* process_image_file(void* arg) {
    ThreadArg *thread_arg = (ThreadArg *)arg;
    // Placeholder for image processing logic
    ImageInfo img_info = {8, 1}; // Example values

    // Extract RNTI and other necessary data from the file
    uint16_t rnti = rand() % 65536; // Randomly generated example value
    uint32_t crc_tag = rand(); // Randomly generated example value

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 65536;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = crc_tag;
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_lock(&thread_arg->pdu_array->mutex);
    thread_arg->pdu_array->pdus =
        realloc(thread_arg->pdu_array->pdus,
                (thread_arg->pdu_array->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!thread_arg->pdu_array->pdus) {
        pthread_mutex_unlock(&thread_arg->pdu_array->mutex);
        return NULL;
    }
    thread_arg->pdu_array->pdus[thread_arg->pdu_array->count++] = pdu;
    pthread_mutex_unlock(&thread_arg->pdu_array->mutex);

    return (void *)&img_info;
}

int compare_pdu(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return pdu_a->RNTI - pdu_b->RNTI;
}

NFAPI_CRC_INDICATION_PDU_T* process_tiff_images(const char **file_paths, size_t file_count) {
    if (!file_count) return NULL;

    PDUArray pdu_array = {NULL, 0};
    pthread_mutex_init(&pdu_array.mutex, NULL);

    pthread_t threads[MAX_THREADS];
    ThreadArg thread_args[MAX_THREADS];

    for (size_t i = 0; i < file_count && i < MAX_THREADS; ++i) {
        thread_args[i] = (ThreadArg){file_paths[i], &pdu_array};
        if (pthread_create(&threads[i], NULL, process_image_file, &thread_args[i])) {
            // Error handling
            free(pdu_array.pdus);
            pthread_mutex_destroy(&pdu_array.mutex);
            return NULL;
        }
    }

    for (size_t i = 0; i < file_count && i < MAX_THREADS; ++i) {
        void *result;
        if (pthread_join(threads[i], &result)) {
            // Error handling
            free(pdu_array.pdus);
            pthread_mutex_destroy(&pdu_array.mutex);
            return NULL;
        }
    }

    qsort(pdu_array.pdus, pdu_array.count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);

    pthread_mutex_destroy(&pdu_array.mutex);
    return pdu_array.pdus;
}
