#define THRESHOLD_CAPACITY 800

typedef enum { IDLE, ACTIVE, HANDOVER } UEState;

typedef struct {
    int timestamp;
    int signalStrength;
    int cellID;
} MeasurementReport;

typedef struct {
    unsigned long imsi;
    int rnti;
    UEState ueState;
    MeasurementReport* reports;
    int reportCount;
} UEContext;

void initializeUEContexts(UEContext contexts[], int numUes) {
    srand((unsigned int)time(NULL));

    for (int i = 0; i < numUes && i < MAX_UE; ++i) {
        contexts[i].imsi = rand() % 100000 + 1;
        contexts[i].rnti = rand() % 50000 + 1;
        contexts[i].ueState = (rand() % 3);

        // Simulate network data feed lag/failure with a 10% chance of failure
        if ((rand() % 10) < 2) {
            fprintf(stderr, "Data feed failure for UE %d\n", i);
            contexts[i].reportCount = rand() % MAX_REPORTS_PER_UE;
        } else {
            contexts[i].reportCount = rand() % MAX_REPORTS_PER_UE + 1; // At least one report
        }

        contexts[i].reports = (MeasurementReport*)malloc(contexts[i].reportCount * sizeof(MeasurementReport));

        if (!contexts[i].reports) {
            fprintf(stderr, "Memory allocation failed for UE %d\n", i);
            exit(EXIT_FAILURE);
        }

        int lastTimestamp = 0;
        for (int j = 0; j < contexts[i].reportCount; ++j) {
            do {
                contexts[i].reports[j].timestamp = rand() % 100000 + lastTimestamp + 1;
            } while (contexts[i].reports[j].timestamp <= lastTimestamp);
            lastTimestamp = contexts[i].reports[j].timestamp;

            contexts[i].reports[j].signalStrength = rand() % 101 - 50; // Range: -50 to 50
            contexts[i].reports[j].cellID = rand() % 1000 + 1;
        }
    }
}

void deferProcessingIfNecessary(int currentUECount) {
    if (currentUECount > THRESHOLD_CAPACITY) {
        printf("System load is high. Deferring processing...\n");
        while (currentUECount > THRESHOLD_CAPACITY) {
            sleep(1); // Sleep for 1 second and check again
            currentUECount = rand() % MAX_UE; // Simulated reduction in UE count
        }
    }
}

int main() {
    int numUes = 1000;

    deferProcessingIfNecessary(numUes);

    UEContext contexts[MAX_UE];
    initializeUEContexts(contexts, numUes);

    for (int i = 0; i < numUes && i < MAX_UE; ++i) {
        printf("UE %d: IMSI=%lu, RNTI=%d, State=%d\n", i, contexts[i].imsi, contexts[i].rnti, contexts[i].ueState);
        for (int j = 0; j < contexts[i].reportCount; ++j) {
            printf("Report %d: Timestamp=%d, SignalStrength=%d, CellID=%d\n",
                   j, contexts[i].reports[j].timestamp,
                   contexts[i].reports[j].signalStrength, 
                   contexts[i].reports[j].cellID);
        }
    }

    // Free dynamically allocated memory
    for (int i = 0; i < numUes && i < MAX_UE; ++i) {
        free(contexts[i].reports);
    }

    return 0;
}
