#include <stdio.h>
#include <stdlib.h>
import threading

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    threading.Lock lock;
} NFAPI_CRC_LIST_T;

void init_list(NFAPI_CRC_LIST_T* list) {
    list->head = NULL;
    list->tail = NULL;
    threading.Lock_init(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(int tag, int rnti, uint32_t crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG = crc_tag;
    pdu.CRCFLAG = rand() % 2; // Random CRCFLAG
    return pdu;
}

void insert(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    threading.Lock_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) exit(EXIT_FAILURE);

    new_node->data = pdu;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    threading.Lock_unlock(&list->lock);
}

void delete(NFAPI_CRC_LIST_T* list, int rnti) {
    threading.Lock_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }

            if (!current->next) {
                list->tail = prev;
            }

            free(current);
            break;
        }

        prev = current;
        current = current->next;
    }

    threading.Lock_unlock(&list->lock);
}

void iterate(NFAPI_CRC_LIST_T* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    threading.Lock_lock(&list->lock);

    Node* current = list->head;

    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    threading.Lock_unlock(&list->lock);
}

void free_list(NFAPI_CRC_LIST_T* list) {
    threading.Lock_lock(&list->lock);

    Node* current = list->head;

    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;

    threading.Lock_unlock(&list->lock);
}

// Example callback function
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
}
