#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_SIZE 128 * 1024 // 128KB
#define MAX_RETRIES 3
#define MAX_STRUCTURES 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int add_pdu(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu, int* allocated_count, int* retry_count, int* error_count) {
    for (Node* current = *head; current != NULL; current = current->next) {
        if (current->data.RNTI == pdu.RNTI) return 0;
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        (*retry_count)++;
        return -1;
    }

    new_node->next = *head;
    *head = new_node;
    (*allocated_count)++;
    return 1;
}

int manage_crc_list(Node** head, int* report) {
    srand(time(NULL));
    Node* current_head = NULL;
    int allocated_count = 0, retry_count = 0, error_count = 0;

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Simulated external data source
        do {
            pdu.RNTI = rand() % 10000 + 1; // Example RNTI range
        } while (pdu.RNTI == 0);

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0xFF;

        int success = add_pdu(&current_head, pdu, &allocated_count, &retry_count, &error_count);
        if (!success) {
            for (int retry = 0; retry < MAX_RETRIES; retry++) {
                Node* new_node = create_node(pdu);
                if (new_node) {
                    new_node->next = current_head;
                    current_head = new_node;
                    allocated_count++;
                    retry_count++;
                    success = 1;
                    break;
                }
            }
        }

        if (!success) {
            error_count++;
            break;
        }
    }

    *head = current_head;
    report[0] = allocated_count;
    report[1] = retry_count;
    report[2] = error_count;

    return (error_count > 0) ? -1 : 0;
}

int main() {
    Node* head = NULL;
    int report[3];
    int result = manage_crc_list(&head, report);

    printf("Allocated: %d, Retries: %d, Errors: %d\n", report[0], report[1], report[2]);

    if (result == -1) {
        printf("Failed to allocate all structures.\n");
    } else {
        printf("All structures allocated successfully.\n");
    }

    free_list(&head);
    return result;
}
