    const size_t max_memory_bytes = 150 * 1024;
    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (structure_size * n > max_memory_bytes) {
        *error_code = -1; // Memory allocation exceeds limit
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    uint16_t rnti_pool[MAX_RNTI];
    size_t pool_size = fetch_rnti_pool(rnti_pool, MAX_RNTI);
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;

    for (int attempt = 0; attempt < 3; ++attempt) {
        pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * structure_size);
        if (!pdu_list) {
            pthread_mutex_lock(&lock);
            *error_code = -2; // Memory allocation failure
            pthread_mutex_unlock(&lock);
            continue;
        }

        for (size_t i = 0; i < n; ++i) {
            pdu_list[i].RX_UE_INFORMATION_TAG = rand(); // Random value
            do {
                size_t index = rand() % pool_size;
                pdu_list[i].RNTI = rnti_pool[index];
            } while (/* Check for RNTI duplication in the current list */);

            pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Random CRCFLAG
        }

        *error_code = 0;
        break;
    }

    pthread_mutex_destroy(&lock);

    if (attempt == 3 && pdu_list) {
        free(pdu_list);
        *error_code = -3; // Max retries reached with duplicates or failure
        return NULL;
    }

    return pdu_list;
}

void free_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t n) {
    if (pdu_list) {
        free(pdu_list);
    }
