use std::env;
use std::fs;
use std::path::Path;

fn create_directory_with_env_variable(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var = format!("DIR_{}", dir_name.to_uppercase());
    if let Ok(dir_path) = env::var(&env_var) {
        println!("Using existing directory path from environment variable: {}", dir_path);
        return Ok(());
    }

    let new_dir_path = Path::new(dir_name);
    fs::create_dir_all(new_dir_path)?;

    // Set the environment variable for future reference
    std::env::set_var(&env_var, new_dir_path.to_str().unwrap());

    println!("Created and set environment variable for directory: {}", dir_path.display());

    Ok(())
}
