#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1000
#define MIN_UE_CONTEXTS 10

typedef struct {
    time_t timestamp;
    int signalStrength;
    int cellID;
} MeasurementReport;

typedef struct {
    char imsi[16];
    int rnti;
    int ueState;
    MeasurementReport *reports;
    size_t reportCount;
    pthread_mutex_t lock;
} UEContext;

typedef struct {
    UEContext *contexts;
    size_t contextCount;
    pthread_rwlock_t contextsLock;
} NetworkSimulation;

NetworkSimulation* initialize_simulation(size_t numUEs) {
    if (numUEs < MIN_UE_CONTEXTS || numUEs > MAX_UE_CONTEXTS) return NULL;

    NetworkSimulation *sim = malloc(sizeof(NetworkSimulation));
    sim->contexts = calloc(numUEs, sizeof(UEContext));
    pthread_rwlock_init(&sim->contextsLock, NULL);
    sim->contextCount = numUEs;

    for (size_t i = 0; i < numUEs; ++i) {
        snprintf(sim->contexts[i].imsi, sizeof(sim->contexts[i].imsi), "IMSI%zu", i + 1);
        sim->contexts[i].rnti = rand() % 10000;
        sim->contexts[i].ueState = rand() % 10;
        pthread_mutex_init(&sim->contexts[i].lock, NULL);

        // Simulating measurement reports
        size_t reportCount = rand() % 50 + 1;  // Each UE has between 1 and 50 reports.
        sim->contexts[i].reports = calloc(reportCount, sizeof(MeasurementReport));
        sim->contexts[i].reportCount = reportCount;

        for (size_t j = 0; j < reportCount; ++j) {
            sim->contexts[i].reports[j].timestamp = time(NULL) + rand() % 100;
            sim->contexts[i].reports[j].signalStrength = rand() % 101 - 50; // Random signal strength between -50 and 50
            sim->contexts[i].reports[j].cellID = rand() % 5000;
        }
    }

    printf("Initialized simulation with %zu UE contexts.\n", numUEs);
    return sim;
}

void cleanup_simulation(NetworkSimulation *sim) {
    pthread_rwlock_wrlock(&sim->contextsLock);

    for (size_t i = 0; i < sim->contextCount; ++i) {
        free(sim->contexts[i].reports);
        pthread_mutex_destroy(&sim->contexts[i].lock);
    }

    free(sim->contexts);
    pthread_rwlock_unlock(&sim->contextsLock);
    pthread_rwlock_destroy(&sim->contextsLock);

    printf("Cleaned up simulation.\n");
    free(sim);
}

void export_ue_contexts(const NetworkSimulation *sim, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < sim->contextCount; ++i) {
        fprintf(file, "UEContext %zu\n", i + 1);
        fprintf(file, "IMSI: %s\nRNTI: %d\nUEState: %d\n", sim->contexts[i].imsi,
                sim->contexts[i].rnti, sim->contexts[i].ueState);

        pthread_mutex_lock(&sim->contexts[i].lock);
        for (size_t j = 0; j < sim->contexts[i].reportCount; ++j) {
            fprintf(file, "Report %zu: Timestamp=%ld, SignalStrength=%d, CellID=%d\n", 
                    j + 1, sim->contexts[i].reports[j].timestamp,
                    sim->contexts[i].reports[j].signalStrength,
                    sim->contexts[i].reports[j].cellID);
        }
        pthread_mutex_unlock(&sim->contexts[i].lock);

        fprintf(file, "\n");
    }

    fclose(file);
}

void simulate_network_load(NetworkSimulation *sim) {
    pthread_t threads[MAX_UE_CONTEXTS];
    for (size_t i = 0; i < sim->contextCount; ++i) {
        pthread_create(&threads[i], NULL, [] (void* arg) -> void* {
            NetworkSimulation *sim = (NetworkSimulation*)arg;

            size_t ueIndex = rand() % sim->contextCount;

            pthread_mutex_lock(&sim->contexts[ueIndex].lock);
            // Simulate some network load processing
            for (size_t j = 0; j < sim->contexts[ueIndex].reportCount; ++j) {
                if (rand() % 10 == 0) {  // Randomly decide to "process" a report.
                    printf("Processing UEContext %zu Report %zu\n", ueIndex + 1, j + 1);
                }
            }
            pthread_mutex_unlock(&sim->contexts[ueIndex].lock);

            return NULL;
        }, (void*) sim);
    }

    for (size_t i = 0; i < sim->contextCount; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));
    size_t numUEs = rand() % (MAX_UE_CONTEXTS - MIN_UE_CONTEXTS + 1) + MIN_UE_CONTEXTS;

    NetworkSimulation *sim = initialize_simulation(numUEs);

    simulate_network_load(sim);
    export_ue_contexts(sim, "ue_contexts.txt");

    cleanup_simulation(sim);
    return 0;
}
