```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

// Initialize the list
int init_list(CRCList* list) {
    if (!list) return -1;
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        return -1;
    }
    return 0;
}

// Insert a new node into the list
int insert_node(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Delete a node from the list
int delete_node(CRCList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Node not found
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Iterate over the list and apply a function to each node
void iterate_list(CRCList* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        func(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the entire list
void free_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example function to process each node
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %u\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
}

// Main function to demonstrate usage
int main() {
    CRCList list;
    if (init_list(&list) != 0) {
        fprintf(stderr, "Failed to initialize list.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 2, rand() % 2};
    insert_node(&list, pdu);

    iterate_list(&list, print_pdu);

    free_list(&list);
    return EXIT_SUCCESS;
}
