#define INITIAL_POOL_SIZE 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t pool_size;
    size_t used_count;
} NFAPI_CRC_LIST;

NFAPI_CRC_LIST* create_list() {
    NFAPI_CRC_LIST* list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->pool_size = INITIAL_POOL_SIZE;
    list->used_count = 0;

    Node* current = (Node*)malloc(list->pool_size * sizeof(Node));
    if (!current) {
        free(list);
        return NULL;
    }
    list->head = current;

    for (size_t i = 1; i < list->pool_size; ++i) {
        current[i].next = &current[i + 1];
    }
    current[list->pool_size - 1].next = NULL;

    return list;
}

void destroy_list(NFAPI_CRC_LIST* list) {
    if (!list) return;

    pthread_mutex_destroy(&list->lock);
    free(list->head); // Free the entire pool
    free(list);
}

int append_pdu(NFAPI_CRC_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    if (list->used_count == list->pool_size) {
        size_t new_pool_size = list->pool_size * 2;
        Node* new_pool = (Node*)realloc(list->head, new_pool_size * sizeof(Node));

        if (!new_pool) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }

        list->head = new_pool;
        for (size_t i = list->pool_size; i < new_pool_size - 1; ++i) {
            new_pool[i].next = &new_pool[i + 1];
        }
        new_pool[new_pool_size - 1].next = NULL;

        list->pool_size = new_pool_size;
    }

    Node* node = &list->head[list->used_count++];
    memcpy(&node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = list->head ? list->head->next : NULL;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int set_default_crcflag(NFAPI_CRC_LIST* list, unsigned char default_flag) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->next) {
        current = current->next;
        current->data.CRCFLAG = default_flag;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void handle_overflow(NFAPI_CRC_LIST* list, int (*handler)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !handler) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current && current->next) {
        current = current->next;
        if (handler(&current->data.data) != 0) {
            // Handle overflow logic, e.g., log, alert, or discard
            printf("Overflow condition detected!\n");
        }
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    NFAPI_CRC_LIST* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, 0};
    append_pdu(list, pdu);

    set_default_crcflag(list, 1);

    handle_overflow(list, NULL);

    destroy_list(list);
    return EXIT_SUCCESS;
}
