#include <time.h>

// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logger function
void log_message(int verbosity, const char *message) {
    if (verbosity > 0) {
        printf("%s\n", message);
    }
}

// Error handling macro
#define HANDLE_ERROR(msg) do { perror(msg); exit(EXIT_FAILURE); } while(0)

// Function to initialize the list
NFAPI_CRC_INDICATION_PDU_T* init_list(size_t initial_size, int verbosity) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) HANDLE_ERROR("Memory allocation failed");
    log_message(verbosity, "List initialized");
    return list;
}

// Function to resize the list
void* resize_list(void *ptr, size_t current_size, size_t new_size, int verbosity) {
    NFAPI_CRC_INDICATION_PDU_T *new_ptr = (NFAPI_CRC_INDICATION_PDU_T *)realloc(ptr, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_ptr) HANDLE_ERROR("Memory reallocation failed");
    log_message(verbosity, "List resized");
    return new_ptr;
}

// Function to create and manage the list
NFAPI_CRC_INDICATION_PDU_T* manage_list(size_t N, size_t realloc_threshold, int threads, int verbosity) {
    size_t current_size = realloc_threshold;
    NFAPI_CRC_INDICATION_PDU_T *list = init_list(current_size, verbosity);
    pthread_t thread_ids[threads];

    // Function to populate the list
    auto fill_list = [&](size_t start, size_t end) {
        srand(time(NULL) + (unsigned int)pthread_self());
        for (size_t i = start; i < end; ++i) {
            pthread_mutex_lock(&list_mutex);
            list[i].RX_UE_INFORMATION_TAG = rand();
            list[i].RNTI = rand() % 65535;
            list[i].CRC_INDICATION_REL8_TAG = rand();
            list[i].CRCFLAG = rand() % 2;
            pthread_mutex_unlock(&list_mutex);
        }
    };

    // Create threads to fill the list
    size_t chunk_size = N / threads;
    for (int i = 0; i < threads; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == threads - 1) ? N : start + chunk_size;
        if (pthread_create(&thread_ids[i], NULL, (void* (*)(void*))fill_list, malloc(sizeof(size_t)*2))) {
            HANDLE_ERROR("Thread creation failed");
        }
    }

    // Join threads
    for (int i = 0; i < threads; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    return list;
}

// Function to sort the list based on a key
void sort_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t N, const char *key, int verbosity) {
    if (strcmp(key, "RNTI") == 0) {
        qsort(list, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), [](const void *a, const void *b) -> int {
            return ((NFAPI_CRC_INDICATION_PDU_T *)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T *)b)->RNTI;
        });
    } else if (strcmp(key, "CUSTOM") == 0) {
        // Custom sort logic
    } else {
        fprintf(stderr, "Invalid sort key\n");
        exit(EXIT_FAILURE);
    }
    log_message(verbosity, "List sorted");
}

// Function to serialize the list
void serialize_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t N, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) HANDLE_ERROR("File opening failed");
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);
}

// Function to deserialize the list
NFAPI_CRC_INDICATION_PDU_T* deserialize_list(size_t *N, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) HANDLE_ERROR("File opening failed");

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    size_t num_elements = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *N = num_elements;

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) HANDLE_ERROR("Memory allocation failed");

    fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, file);
    fclose(file);

    return list;
}

// Unit test function
void run_tests() {
    size_t N = 1000;
    size_t realloc_threshold = 500;
    int threads = 4;
    int verbosity = 1;

    NFAPI_CRC_INDICATION_PDU_T *list = manage_list(N, realloc_threshold, threads, verbosity);
    sort_list(list, N, "RNTI", verbosity);

    serialize_list(list, N, "test_data.bin");
    size_t deserialized_N;
    NFAPI_CRC_INDICATION_PDU_T *deserialized_list = deserialize_list(&deserialized_N, "test_data.bin");

    // Validate correctness
    for (size_t i = 0; i < N; ++i) {
        if (list[i].RNTI != deserialized_list[i].RNTI) {
            fprintf(stderr, "Data mismatch at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }

    free(list);
    free(deserialized_list);
}

int main() {
    run_tests();
    return 0;
}
