#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_MESSAGES 10000

typedef struct {
    int NAS_Message_Id;
    int MME_Ue_S1_Id;
    char *NAS_PDU; // Assuming NAS_PDU is a string for simplicity
} LTE_NAS_Message_Type;

typedef struct {
    LTE_NAS_Message_Type *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

// Function prototypes
MessageArray* initialize_message_array(size_t initial_capacity);
int append_message(MessageArray *msg_array, LTE_NAS_Message_Type message);
void compact_array_if_needed(MessageArray *msg_array);
void free_message_array(MessageArray *msg_array);
void process_messages_with_queue(MessageArray *msg_array);

// Initialize the dynamic array
MessageArray* initialize_message_array(size_t initial_capacity) {
    MessageArray *msg_array = malloc(sizeof(MessageArray));
    if (!msg_array) return NULL;

    msg_array->messages = malloc(initial_capacity * sizeof(LTE_NAS_Message_Type));
    if (!msg_array->messages) {
        free(msg_array);
        return NULL;
    }

    msg_array->capacity = initial_capacity;
    msg_array->count = 0;
    pthread_mutex_init(&msg_array->lock, NULL);

    // Populate with random messages
    for (size_t i = 0; i < initial_capacity; ++i) {
        LTE_NAS_Message_Type message;
        message.NAS_Message_Id = rand() % 100;
        message.MME_Ue_S1_Id = rand() % 1000;
        message.NAS_PDU = strdup("Random PDU");
        append_message(msg_array, message);
    }

    return msg_array;
}

// Append a message safely
int append_message(MessageArray *msg_array, LTE_NAS_Message_Type message) {
    pthread_mutex_lock(&msg_array->lock);

    if (msg_array->count >= msg_array->capacity || msg_array->count >= MAX_MESSAGES) {
        pthread_mutex_unlock(&msg_array->lock);
        return 0;
    }

    msg_array->messages[msg_array->count++] = message;

    compact_array_if_needed(msg_array);

    pthread_mutex_unlock(&msg_array->lock);
    return 1;
}

// Compact the array if needed
void compact_array_if_needed(MessageArray *msg_array) {
    if (msg_array->count < msg_array->capacity * 0.25 && msg_array->capacity > initial_capacity) {
        size_t new_capacity = msg_array->count + initial_capacity; // Ensure some buffer space
        LTE_NAS_Message_Type *new_messages = realloc(msg_array->messages, new_capacity * sizeof(LTE_NAS_Message_Type));
        if (new_messages) {
            memcpy(new_messages, msg_array->messages, msg_array->count * sizeof(LTE_NAS_Message_Type));
            free(msg_array->messages);
            msg_array->messages = new_messages;
            msg_array->capacity = new_capacity;
        }
    }
}

// Free the dynamic array
void free_message_array(MessageArray *msg_array) {
    pthread_mutex_lock(&msg_array->lock);

    for (size_t i = 0; i < msg_array->count; ++i) {
        free(msg_array->messages[i].NAS_PDU);
    }

    free(msg_array->messages);
    pthread_mutex_unlock(&msg_array->lock);
    pthread_mutex_destroy(&msg_array->lock);
    free(msg_array);
}

// Process messages with an external queue
void process_messages_with_queue(MessageArray *msg_array) {
    pthread_mutex_lock(&msg_array->lock);

    for (size_t i = 0; i < msg_array->count; ++i) {
        // Simulate sending to a message queue
        printf("Processing Message ID: %d\n", msg_array->messages[i].NAS_Message_Id);
    }

    pthread_mutex_unlock(&msg_array->lock);
}

int main() {
    size_t initial_capacity = 100;
    MessageArray *msg_array = initialize_message_array(initial_capacity);

    if (!msg_array) {
        fprintf(stderr, "Failed to initialize message array.\n");
        return EXIT_FAILURE;
    }

    // Simulate appending messages
    LTE_NAS_Message_Type new_message = {rand() % 100, rand() % 1000, strdup("New PDU")};
    int success = append_message(msg_array, new_message);
    printf("Append successful: %d\n", success);

    process_messages_with_queue(msg_array);

    free_message_array(msg_array);

    return EXIT_SUCCESS;
}
```

This code initializes a dynamic array of `LTE_NAS_Message_Type` structures, appends messages in a thread-safe manner, compacts the array when necessary, and integrates with an external message queue system. It handles memory allocation failures gracefully and provides feedback on operations performed.']

