#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int NAS_Message_Id;
    int MME_Ue_S1_Id;
    char *NAS_PDU;
} LTE_NAS_Message_Type;

#define MAX_POOL_SIZE 1024 // Define maximum pool size

// Memory Pool Structure
typedef struct {
    void *pool[MAX_POOL_SIZE];
    int count;
} MemoryPool;

MemoryPool messagePools[10]; // Example for different types of messages

void initialize_memory_pool(MemoryPool *mp) {
    mp->count = 0;
}

int allocate_from_pool(MemoryPool *mp, size_t size) {
    if (mp->count >= MAX_POOL_SIZE)
        return -1; // Out of memory

    void *ptr = malloc(size);
    if (!ptr)
        return -2; // Allocation failure

    mp->pool[mp->count++] = ptr;
    return 0;
}

void deallocate_from_pool(MemoryPool *mp, int index) {
    if (index >= 0 && index < mp->count) {
        free(mp->pool[index]);
        memmove(&mp->pool[index], &mp->pool[index + 1],
                (mp->count - index - 1) * sizeof(void *));
        mp->count--;
    }
}

void garbage_collect_memory_pools(MemoryPool *pools, int pool_count) {
    for (int i = 0; i < pool_count; ++i) {
        for (int j = 0; j < pools[i].count; ++j) {
            deallocate_from_pool(&pools[i], 0); // Repeatedly clear out memory
        }
    }
}

LTE_NAS_Message_Type *initialize_messages(int initial_size, int max_array_size) {
    LTE_NAS_Message_Type *messages = malloc(sizeof(LTE_NAS_Message_Type) * initial_size);
    if (!messages)
        return NULL;

    for (int i = 0; i < initial_size; ++i) {
        messages[i].NAS_Message_Id = rand() % 1000;
        messages[i].MME_Ue_S1_Id = rand() % 1000;
        size_t pdu_length = rand() % 256 + 1;
        messages[i].NAS_PDU = malloc(pdu_length);
        if (!messages[i].NAS_PDU) {
            fprintf(stderr, "Failed to allocate NAS PDU\n");
            return NULL; // Failed allocation
        }
        memset(messages[i].NAS_PDU, rand() % 256, pdu_length);
    }

    return messages;
}

int append_message(LTE_NAS_Message_Type **messages, int *current_size, int max_array_size) {
    if (*current_size >= max_array_size)
        return -1; // Maximum size reached

    LTE_NAS_Message_Type *new_messages = realloc(*messages,
                                                  sizeof(LTE_NAS_Message_Type) * (*current_size + 1));
    if (!new_messages)
        return -2; // Realloc failure

    int index = *current_size;
    new_messages[index].NAS_Message_Id = rand() % 1000;
    new_messages[index].MME_Ue_S1_Id = rand() % 1000;
    size_t pdu_length = rand() % 256 + 1;
    new_messages[index].NAS_PDU = malloc(pdu_length);
    if (!new_messages[index].NAS_PDU) {
        fprintf(stderr, "Failed to allocate NAS PDU\n");
        return -3; // Allocation failure
    }
    memset(new_messages[index].NAS_PDU, rand() % 256, pdu_length);

    *messages = new_messages;
    (*current_size)++;
    return 0;
}

void free_messages(LTE_NAS_Message_Type *messages, int size) {
    for (int i = 0; i < size; ++i)
        free(messages[i].NAS_PDU);
    free(messages);
}

void log_message_stats(int added, int failures) {
    printf("Messages successfully added: %d\n", added);
    printf("Failures encountered during addition: %d\n", failures);
}

int main() {
    srand(time(NULL));
    const int initial_size = 10;
    const int max_array_size = 100;

    LTE_NAS_Message_Type *messages = initialize_messages(initial_size, max_array_size);
    if (!messages) {
        fprintf(stderr, "Failed to initialize messages\n");
        return -1;
    }

    int current_size = initial_size;
    int added = 0, failures = 0;

    for (int i = 0; i < 20; ++i) { // Simulate appending additional messages
        int result = append_message(&messages, &current_size, max_array_size);
        if (result == 0)
            added++;
        else {
            failures++;
            fprintf(stderr, "Failed to append message: %d\n", result);
        }
    }

    log_message_stats(added, failures);

    garbage_collect_memory_pools(messagePools, sizeof(messagePools) / sizeof(MemoryPool));

    free_messages(messages, current_size);

    return 0;
}
```

This code example includes the initialization of a dynamic array with random values, custom memory pooling to handle allocations more efficiently, and a mechanism for appending messages without reallocating the entire array. It also provides basic error handling and logging mechanisms, alongside garbage collection to free up unused memory pools.']

