['Below is a C implementation for managing a thread-safe doubly linked list of `NFAPI_CRC_INDICATION_PDU_T` structures, incorporating the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Structure Definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Doubly Linked List Structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} ThreadSafeDoublyLinkedList;

// Function Prototypes
ThreadSafeDoublyLinkedList* create_list();
void destroy_list(ThreadSafeDoublyLinkedList* list);
int add_node(ThreadSafeDoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data);
Node* remove_node(ThreadSafeDoublyLinkedList* list, int index);
void log_message(const char* message);
NFAPI_CRC_INDICATION_PDU_T fetch_crc_indicator_values();
int parse_theme_settings_and_output(char* filename);

// Main Function
ThreadSafeDoublyLinkedList* create_list() {
    ThreadSafeDoublyLinkedList* list = (ThreadSafeDoublyLinkedList*)malloc(sizeof(ThreadSafeDoublyLinkedList));
    if (!list) {
        log_message("Memory allocation failed for list.");
        return NULL;
    }
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    log_message("List created successfully.");
    return list;
}

void destroy_list(ThreadSafeDoublyLinkedList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
    log_message("List destroyed successfully.");
}

int add_node(ThreadSafeDoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for node.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    new_node->data = fetch_crc_indicator_values(); // Fetch and set CRC values
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = NULL;
    }
    pthread_mutex_unlock(&list->lock);

    log_message("Node added successfully.");
    return 0;
}

Node* remove_node(ThreadSafeDoublyLinkedList* list, int index) {
    if (!list || !list->head) return NULL;

    Node* current = list->head;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        log_message("Index out of bounds.");
        return NULL;
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
    log_message("Node removed successfully.");
    return current;
}

void log_message(const char* message) {
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T fetch_crc_indicator_values() {
    // Simulate fetching real-time CRC indicator values
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand();
    pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

int parse_theme_settings_and_output(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int field1, field2, field3, avg;
        sscanf(line, "%d,%d,%d", &field1, &field2, &field3);
        avg = (field2 + field3) / 2;
        printf("%d,%d,%d,%d\n", field1, field2, field3, avg);
    }

    fclose(file);
    return 0;
}

// Unit and Stress Tests
void run_tests() {
    // Implement unit tests and stress tests here
}

int main() {
    ThreadSafeDoublyLinkedList* list = create_list();
    if (list) {
        add_node(list, (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG=1});
        remove_node(list, 0);
        destroy_list(list);
    }

    parse_theme_settings_and_output("theme_settings.txt");
    run_tests();
    return 0;
}
