['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_LIST_SIZE 1024
#define RETRY_LIMIT 3

typedef struct CRCINDICATIONREL8_PDU_T {
    // Define relevant fields here
} CRCINDICATIONREL8_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    CRCINDICATIONREL8_PDU_T pdu;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
    void (*threshold_callback)(size_t current_size, size_t threshold);
} LinkedList;

// Function prototypes
int validate_crc_tag(uint32_t tag);
void parse_theme_settings(const char* filename);

LinkedList* create_linked_list(void (*callback)(size_t, size_t), size_t threshold) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    list->threshold_callback = callback;

    return list;
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || list->size >= MAX_LIST_SIZE) return -1;

    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (validate_crc_tag(element.CRC_INDICATION_REL8_TAG)) break;

        if (attempt == RETRY_LIMIT - 1) {
            fprintf(stderr, "CRC validation failed after %d attempts\n", RETRY_LIMIT);
            return -2;
        }
    }

    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -3;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    ++(list->size);

    if (list->threshold_callback && list->size >= 0.8 * MAX_LIST_SIZE) {
        list->threshold_callback(list->size, MAX_LIST_SIZE);
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
