static NFAPI_CRC_INDICATION_PDU_T *pdu_array[MAX_CAPACITY];
static size_t count = 0;

void initialize_random_seed() {
    srand((unsigned int)time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t rx_ue_info_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    pdu->timestamp = time(NULL);

    return pdu;
}

void cleanup_unused_pdus() {
    pthread_mutex_lock(&lock);
    time_t current_time = time(NULL);
    for (size_t i = 0; i < count; ++i) {
        if ((current_time - pdu_array[i]->timestamp) > 60) { // Cleanup older than 1 minute
            free(pdu_array[i]);
            pdu_array[i] = NULL;
        }
    }
    pthread_mutex_unlock(&lock);
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (count >= MAX_CAPACITY) return;

    pthread_mutex_lock(&lock);
    pdu_array[count++] = pdu;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(size_t index) {
    if (index >= count) return NULL;

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_array[index];
    pthread_mutex_unlock(&lock);

    return pdu;
}

void populate_pdus(int num_pdus) {
    initialize_random_seed();
    for (int i = 0; i < num_pdus; ++i) {
        uint32_t rx_ue_info_tag = rand() % 100000;
        uint16_t rnti = rand() % 65535;

        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(rx_ue_info_tag, rnti);
        if (pdu) add_pdu(pdu);
    }
}

void free_resources() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        if (pdu_array[i]) {
            free(pdu_array[i]);
            pdu_array[i] = NULL;
        }
    }
    count = 0;
    pthread_mutex_unlock(&lock);

    pthread_mutex_destroy(&lock);
}

int main() {
    populate_pdus(100); // Example usage
    cleanup_unused_pdus();
    free_resources();

    return 0;
}
