    RRC_RX_SIGNALINFO signal_info;
    char *payload_data;
    size_t payload_length;
    struct NFAPI_RX_FRAME_INFO_T *prev;
    struct NFAPI_RX_FRAME_INFO_T *next;
} NFAPI_RX_FRAME_INFO_T;

typedef struct {
    NFAPI_RX_FRAME_INFO_T *head;
    pthread_mutex_t mutex;
} DoublyLinkedList;

void initialize_list(DoublyLinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_RX_FRAME_INFO_T* create_frame_info(size_t length) {
    NFAPI_RX_FRAME_INFO_T *frame = (NFAPI_RX_FRAME_INFO_T *)malloc(sizeof(NFAPI_RX_FRAME_INFO_T));
    frame->ue_info = {}; // Initialize RX_UE_INFO_T
    frame->signal_info = {}; // Initialize RRC_RX_SIGNALINFO
    frame->payload_data = (char *)malloc(length);
    frame->payload_length = length;
    frame->prev = NULL;
    frame->next = NULL;

    if (!frame || !frame->payload_data) {
        free(frame);
        return NULL;
    }

    return frame;
}

void add_frame(DoublyLinkedList *list, NFAPI_RX_FRAME_INFO_T *new_frame, size_t length) {
    pthread_mutex_lock(&list->mutex);

    new_frame = create_frame_info(length);
    if (!new_frame) {
        printf("Warning: Buffer allocation failed.\n");
        return;
    }

    if (length > new_frame->payload_length) {
        size_t original_size = new_frame->payload_length;
        char *temp_buffer = realloc(new_frame->payload_data, length);
        if (!temp_buffer) {
            printf("Warning: Truncating data due to buffer overflow.\n");
            memcpy(temp_buffer, new_frame->payload_data, original_size);
            free(new_frame->payload_data);
            new_frame->payload_data = temp_buffer;
        } else {
            new_frame->payload_length = length;
            new_frame->payload_data = temp_buffer;
        }
    }

    new_frame->next = list->head;
    if (list->head) {
        list->head->prev = new_frame;
    }
    list->head = new_frame;

    pthread_mutex_unlock(&list->mutex);
}

void free_list(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_RX_FRAME_INFO_T *current = list->head;
    while (current) {
        NFAPI_RX_FRAME_INFO_T *next = current->next;
        free(current->payload_data);
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
