typedef struct MemoryPool {
    void** free_list;
    size_t element_size;
    size_t pool_size;
    struct MemoryPool* next_pool;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t pool_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->element_size = element_size;
    pool->pool_size = pool_size;
    pool->free_list = (void**)malloc(pool_size * sizeof(void*));

    for (size_t i = 0; i < pool_size; ++i) {
        void* block = malloc(element_size);
        pool->free_list[i] = block;
    }

    pool->next_pool = NULL;
    return pool;
}

LTE_NAS_Message_Type* allocate_message(MemoryPool* pools[], size_t element_count) {
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        if (pools[i]->free_list[element_count] != NULL) {
            void** block = &pools[i]->free_list[element_count];
            *block = malloc(pools[i]->element_size);
            return (LTE_NAS_Message_Type*)*block;
        }
    }

    MemoryPool* new_pool = create_memory_pool(sizeof(LTE_NAS_Message_Type), INITIAL_POOL_SIZE);
    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        void** block = &new_pool->free_list[i];
