#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the structure as per your specifications.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // This should be set randomly
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables and mutex for synchronization.
NFAPI_CRC_INDICATION_PDU_T *array = NULL;
size_t count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Function to initialize the dynamically allocated array
void initialize_crc_array(size_t N) {
    if (N == 0) return;

    pthread_mutex_lock(&lock);

    // Free existing memory if any
    free(array);
    count = 0; 

    // Allocate memory for new structures
    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1;  // Example initialization
        array[i].RNTI = i * 10;
        array[i].CRC_INDICATION_REL8_TAG = i % 5;
        array[i].CRCFLAG = rand() % 2;  // Randomly set to 0 or 1
    }

    count = N;

    pthread_mutex_unlock(&lock);
}

// Thread-safe iteration function
void iterate_crc_array(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    if (!array || count == 0) return;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < count; ++i) {
        callback(&array[i]);
    }

    pthread_mutex_unlock(&lock);
}

// Function to free the allocated memory
void cleanup_crc_array() {
    pthread_mutex_lock(&lock);

    if (array != NULL) {
        free(array);
        array = NULL;
        count = 0;
    }

    pthread_mutex_unlock(&lock);
}
