} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_POOL_SIZE 10
#define POOL_INCREMENT 5

typedef struct MemoryPool {
    void *memory;
    size_t block_size;
    size_t pool_size;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

void initialize_memory_pool(MemoryPool *pool, size_t block_size) {
    pool->block_size = block_size;
    pool->pool_size = INITIAL_POOL_SIZE;
    pool->used_blocks = 0;
    pool->memory = malloc(block_size * pool->pool_size);
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_blocks == pool->pool_size) {
        void *new_memory = realloc(pool->memory, pool->block_size * (pool->pool_size + POOL_INCREMENT));
        if (!new_memory) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->memory = new_memory;
        pool->pool_size += POOL_INCREMENT;
    }

    void *ptr = ((char*)pool->memory) + (pool->used_blocks * pool->block_size);
    pool->used_blocks++;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
}

typedef struct DynamicArray {
    LTE_NAS_Message_Type **messages;
    size_t capacity;
    MemoryPool pool;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->messages = malloc(sizeof(LTE_NAS_Message_Type*) * initial_capacity);
    initialize_memory_pool(&array->pool, sizeof(LTE_NAS_Message_Type));
}

void append_message_to_array(DynamicArray *array, LTE_NAS_Message_Type *message) {
    if (array->capacity == 0) return;

    if (array->messages[0] == NULL) { // Assuming all null means not used
        array->messages[0] = message;
        return;
    }

    for (size_t i = 1; i < array->capacity; ++i) {
        if (array->messages[i - 1] != NULL && array->messages[i] == NULL) {
            array->messages[i] = message;
            return;
        }
    }

    // Add to pool instead
    LTE_NAS_Message_Type *pool_message = allocate_from_pool(&array->pool);
    if (pool_message) {
        memcpy(pool_message, message, sizeof(LTE_NAS_Message_Type));
    }
}

typedef struct List {
    NFAPI_CRC_INDICATION_PDU_T **items;
    size_t capacity;
    MemoryPool pool;
} List;

void init_list(List *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->items = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * initial_capacity);
    initialize_memory_pool(&list->pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void append_to_list(List *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    if (list->capacity == 0) return;

    for (size_t i = 0; i < list->capacity; ++i) {
