    if (pool_item) {
        memcpy(pool_item, item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool_item->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
}

void garbage_collect_memory_pools(DynamicArray *array, List *list) {
    free_memory_pool(&array->pool);
    free_memory_pool(&list->pool);
}

int main() {
