    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Function to initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to validate the structure before adding it to the linked list
int isValid(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!pdu.rx_info_tag || pdu.RNTI == 0) return 0; // Simple validation
    return 1;
}

// Function to add a node to the linked list
