    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Function to serialize the linked list to a binary file
void serializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Function to deserialize the linked list from a binary file
void deserializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    pthread_mutex_lock(&list->lock);

    freeLinkedList(list); // Clear existing list

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        addNode(list, pdu);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    LinkedList list;
    initLinkedList(&list);

    // Create and add nodes to the linked list
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.CRCFLAG = rand() % 2}, .RNTI = 12345, NULL};
    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{.CRCFLAG = rand() % 2}, .RNTI = 67890, NULL};

    addNode(&list, pdu1);
    addNode(&list, pdu2);

    // Serialize the list to a file
    serializeLinkedList(&list, "nfa_list.bin");

    // Clear and deserialize from the file
    LinkedList newList;
    initLinkedList(&newList);
    deserializeLinkedList(&newList, "nfa_list.bin");

    freeLinkedList(&list);
    freeLinkedList(&newList);

    return 0;
}
