import pthread.h

// Define the structure
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for managing the array of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread-safe operations
} NFAPI_CRC_MANAGER_T;

// Function to initialize the manager
NFAPI_CRC_MANAGER_T* nfa_crc_manager_init(size_t initial_capacity) {
    NFAPI_CRC_MANAGER_T* manager = (NFAPI_CRC_MANAGER_T*)malloc(sizeof(NFAPI_CRC_MANAGER_T));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

// Function to add a new PDU
int nfa_crc_manager_add_pdu(NFAPI_CRC_MANAGER_T* manager, unsigned int rx_info_tag, unsigned int rnti, unsigned int crc_rel8_tag) {
    if (!manager || !rx_info_tag || !rnti || !crc_rel8_tag) return -1;

    pthread_mutex_lock(&manager->lock);

    // Resize array if necessary
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    // Add the new PDU
    NFAPI_CRC_INDICATION_PDU_T* pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_info_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_rel8_tag;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to retrieve a PDU by RNTI
NFAPI_CRC_INDICATION_PDU_T* nfa_crc_manager_get_pdu_by_rnti(NFAPI_CRC_MANAGER_T* manager, unsigned int rnti) {
    if (!manager || !rnti) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return &manager->array[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Function to free the manager and its resources
void nfa_crc_manager_free(NFAPI_CRC_MANAGER_T* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

### Explanation of the Design:
