#define INITIAL_CAPACITY 10
#define MAX_UE_ID 1000

typedef struct {
    int UE_ID;
    int PCI;
    int MCS;
} LTE_DL_FRAMEINFO;

typedef struct {
    float signalStrength;
    float noiseLevel;
    // Add more metrics as needed
} PHY_STATS;

typedef struct {
    LTE_DL_FRAMEINFO *frames;
    size_t capacity;
    size_t count;
    PHY_STATS phyStats[MAX_UE_ID];
    pthread_mutex_t lock;
} FrameManager;

void initializeFrameManager(FrameManager *manager) {
    manager->frames = malloc(INITIAL_CAPACITY * sizeof(LTE_DL_FRAMEINFO));
    if (!manager->frames) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void resizeFrameManager(FrameManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_DL_FRAMEINFO *new_frames = realloc(manager->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (!new_frames) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    manager->frames = new_frames;
    manager->capacity = new_capacity;
}

void addFrame(FrameManager *manager, LTE_DL_FRAMEINFO frame) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        resizeFrameManager(manager);
    }
    manager->frames[manager->count++] = frame;
    pthread_mutex_unlock(&manager->lock);
}

void updatePHYStats(FrameManager *manager, int ueId, PHY_STATS stats) {
    pthread_mutex_lock(&manager->lock);
    if (ueId < 0 || ueId >= MAX_UE_ID) {
        fprintf(stderr, "Invalid UE ID\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->phyStats[ueId] = stats;
    pthread_mutex_unlock(&manager->lock);
}

void clearFrameManager(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->frames);
    manager->frames = NULL;
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void logPerformance(FrameManager *manager) {
    // Simple logging mechanism
    printf("Current frame count: %zu\n", manager->count);
    printf("Current capacity: %zu\n", manager->capacity);
}

// Example of a function that would be run by multiple threads to update PHY_STATS
void *updateStatsThread(void *arg) {
    FrameManager *manager = (FrameManager *)arg;
    for (int ueId = 0; ueId < MAX_UE_ID; ++ueId) {
        PHY_STATS stats = { .signalStrength = 10.0f, .noiseLevel = 1.0f }; // Example data
        updatePHYStats(manager, ueId, stats);
    }
    return NULL;
}

int main() {
