    initializeFrameManager(&manager);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, updateStatsThread, &manager);
    pthread_join(thread_id, NULL);

    logPerformance(&manager);
    clearFrameManager(&manager);

