#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define sort key types
typedef enum { SORT_RNTI, SORT_CUSTOM_INT, SORT_TIMESTAMP } SortKey;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    pthread_mutex_t mutex;
} NFAPIDataPool;

int generate_random_crcflag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Comparator function for qsort based on the sort key
int compare_sort_key(const void* a, const void* b, SortKey sort_key) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    switch (sort_key) {
        case SORT_RNTI:
            return (pdu_a->RNTI - pdu_b->RNTI);
        // Implement other cases for custom integer and timestamp
        default:
            return 0;
    }
}

// Thread-safe dynamic allocation and population of the array
NFAPIDataPool* create_nfa_data_pool(size_t n) {
    if (n > 10000) {
        fprintf(stderr, "Exceeded maximum allowed number of elements.\n");
        return NULL;
    }

    NFAPIDataPool* pool = malloc(sizeof(NFAPIDataPool));
    if (!pool) {
        perror("Failed to allocate memory for data pool.");
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);

    pool->data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        perror("Failed to allocate memory for NFAPIDataPool elements.");
        free(pool);
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&pool->mutex);

        pool->data[i].RX_UE_INFORMATION_TAG = rand(); // Example tag generation
        pool->data[i].RNTI = rand();
        pool->data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

        pthread_mutex_unlock(&pool->mutex);
    }

    pool->count = n;
    return pool;
}

// Sorting the array based on a specified key
void sort_nfa_data_pool(NFAPIDataPool* pool, SortKey sort_key) {
    if (!pool || !pool->data) return;

    pthread_mutex_lock(&pool->mutex);

    qsort_r(pool->data, pool->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_sort_key, sort_key);

    pthread_mutex_unlock(&pool->mutex);
}

// Clean up the data pool
void free_nfa_data_pool(NFAPIDataPool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->mutex);
    free(pool->data);
    free(pool);
}

int main() {
    // Example usage
    NFAPIDataPool* pool = create_nfa_data_pool(5000);
    if (pool) {
        sort_nfa_data_pool(pool, SORT_RNTI);
        free_nfa_data_pool(pool);
    }
    return 0;
}
