#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UEIdentifier;
    long NetworkTime;  // Assuming it's a timestamp
    float LinkQualityIndication;
} NetworkEntityStatus;

typedef struct Node {
    NetworkEntityStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} EntityList;

// Function prototypes
void initialize_list(EntityList* list);
void destroy_list(EntityList* list);
void insert_entity(EntityList* list, NetworkEntityStatus entity);
void remove_entity_by_ueid(EntityList* list, int ueIdentifier);
NetworkEntityStatus* retrieve_entity_by_ueid(EntityList* list, int ueIdentifier);
void prune_list(EntityList* list, size_t max_size);

// Initialize the list
void initialize_list(EntityList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Destroy the list and free memory
void destroy_list(EntityList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

// Insert a new entity into the list
void insert_entity(EntityList* list, NetworkEntityStatus entity) {
    pthread_mutex_lock(&list->lock);

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->data = entity;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    // Prune if necessary
    prune_list(list, 1000);  // Example max size

    pthread_mutex_unlock(&list->lock);
}

// Remove an entity by UEIdentifier
void remove_entity_by_ueid(EntityList* list, int ueIdentifier) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current != NULL && current->data.UEIdentifier != ueIdentifier) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->lock);
}

// Retrieve an entity by UEIdentifier
NetworkEntityStatus* retrieve_entity_by_ueid(EntityList* list, int ueIdentifier) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    NetworkEntityStatus* result = NULL;

    while (current != NULL && current->data.UEIdentifier != ueIdentifier) {
        current = current->next;
    }

    if (current != NULL) {
        result = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return result;
}

// Prune the list to maintain a specified maximum size
void prune_list(EntityList* list, size_t max_size) {
    while (list->size > max_size && list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->size--;
    }
}
