#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_array(size_t n) {
    if (n > MAX_ELEMENTS) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    srand(time(NULL));

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() & 0xFFFF;

        if (i == 0) {
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        } else {
            int crcFlag = rand() % 2;
            while (crcFlag == array[i - 1].CRC_INDICATION_REL8_TAG.CRCFLAG) {
                crcFlag = rand() % 2;
            }
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcFlag;
        }
    }

    pthread_mutex_unlock(&mutex);

    return array;
}

void cleanup_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
        pthread_mutex_destroy(&mutex);
    }
}
