    char FaultDiagnosis[256];
} DeviceLogEntry;

// Node for the linked list
typedef struct Node {
    DeviceLogEntry entry;
    struct Node* next;
} Node;

// Linked list structure for managing log entries
typedef struct {
    Node* head;
    int size;
} LogList;

// Function to create a new node
Node* create_node(DeviceLogEntry entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->entry = entry;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a log entry at the end of the list
void insert_entry(LogList* list, DeviceLogEntry entry) {
    Node* newNode = create_node(entry);
    if (!newNode) return;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    list->size++;
}

// Function to remove a log entry by DeviceID
void remove_entry(LogList* list, int deviceId) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->entry.DeviceID == deviceId) {
        list->head = current->next;
        free(current);
        current = list->head;
        list->size--;
    }

    while (current != NULL) {
        if (current->entry.DeviceID == deviceId) {
            prev->next = current->next;
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
}

// Function to aggregate data, e.g., average resource consumption
float aggregate_consumption(LogList* list) {
    if (list->size == 0) return 0.0;

    float totalConsumption = 0.0;
    Node* temp = list->head;

    while (temp != NULL) {
        totalConsumption += temp->entry.ResourceConsumption;
        temp = temp->next;
    }

    return totalConsumption / list->size;
}

// Function to archive old entries and clear memory
void archive_and_clear(LogList* list, time_t cutoffTime) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (current->entry.Timestamp < cutoffTime) {
            if (prev == NULL) {
                list->head = current->next;
                free(current);
                current = list->head;
            } else {
                prev->next = current->next;
                free(current);
                current = prev->next;
            }
            list->size--;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Function to initialize the log list
LogList* init_log_list() {
    LogList* newList = (LogList*)malloc(sizeof(LogList));
    if (!newList) return NULL;

    newList->head = NULL;
    newList->size = 0;
    return newList;
}

// Free all nodes in the list and free the list itself
void free_log_list(LogList* list) {
    Node *current = list->head, *nextNode;

    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    free(list);
}

