PDUListManager* createManager(int initialLogFileCount) {
    PDUListManager* manager = (PDUListManager*)malloc(sizeof(PDUListManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->lastRNTI = 0;

    manager->logFiles = (FILE**)malloc(initialLogFileCount * sizeof(FILE*));
    for (int i = 0; i < initialLogFileCount; ++i) {
        char filename[256];
        snprintf(filename, sizeof(filename), "audit_%d.log", i);
        manager->logFiles[i] = fopen(filename, "a");
        if (!manager->logFiles[i]) {
            // Handle file open error
        }
    }

    manager->logFileCount = initialLogFileCount;
    return manager;
}

void logPDU(PDUListManager* manager, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&manager->lock);

    char buffer[256];
    time_t now = time(NULL);
    snprintf(buffer, sizeof(buffer), "%s - RX_UE: %d, RNTI: %d, CRC_TAG: %d, CRCFLAG: %02x\n",
             ctime(&now), pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);

    for (int i = 0; i < manager->logFileCount; ++i) {
        fprintf(manager->logFiles[i], "%s", buffer);
        fflush(manager->logFiles[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void freeManager(PDUListManager* manager) {
    pthread_mutex_destroy(&manager->lock);

    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    for (int i = 0; i < manager->logFileCount; ++i) {
        if (manager->logFiles[i]) {
            fclose(manager->logFiles[i]);
        }
    }

    free(manager->logFiles);
    free(manager);
}

void addPDUs(PDUListManager* manager, int count) {
    pthread_mutex_lock(&manager->lock);

    Node** current = &(manager->head);

    for (int i = 0; i < count; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) break;

        newNode->data.RX_UE_INFORMATION_TAG = rand();
        do {
            newNode->data.RNTI = rand() % 10000;
        } while (newNode->data.RNTI == manager->lastRNTI);
        manager->lastRNTI = newNode->data.RNTI;

        newNode->data.CRC_INDICATION_REL8_TAG = rand();
        newNode->data.CRCFLAG = rand() & 0x1F; // Random CRCFLAG

        *current = newNode;
        current = &(newNode->next);
    }

    pthread_mutex_unlock(&manager->lock);

    Node* curr = manager->head;
    while (curr != NULL) {
        logPDU(manager, &(curr->data));
        curr = curr->next;
    }
}

void retrievePDUsAsJSON(PDUListManager* manager) {
    // Implement JSON retrieval logic
}

void compressAndArchiveLogs(PDUListManager* manager) {
    // Implement compression and archiving logic
}

int main() {
    PDUListManager* manager = createManager(3);

    addPDUs(manager, 10);
    retrievePDUsAsJSON(manager);
    compressAndArchiveLogs(manager);

    freeManager(manager);

    return 0;
}
