#include <stdbool.h>

typedef struct {
    // Define fields for RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG here.
    int exampleField1;
} RX_UE_INFORMATION_TAG;

typedef struct {
