} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_linked_list(int n) {
    if (n <= 0) return NULL;

    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) return NULL;

    Node* current = head;
    for (int i = 1; i < n; ++i) {
        current->next = (Node*)malloc(sizeof(Node));
        if (!current->next) {
            // Free allocated nodes in case of failure
            while (head != current) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            free(head);
            return NULL;
        }
        current = current->next;
    }

    for (int i = 0; i < n; ++i) {
        // Initialize the structure fields
        current->data.rxInfoTag.exampleField1 = rand() % 100;  // Example initialization
        current->data.rnti = rand() % 65536;
        current->data.crcRel8Tag.CRCFLAG = (rand() % 2 == 0);

        if (i < n - 1) {
            current = current->next;
        }
    }

    return head;
}
