```javascript
class ModuleLoader {
    constructor() {
        this.modules = new Map();
    }

    async loadModule(moduleId, modulePath) {
        try {
            const response = await fetch(`${modulePath}.js`);
            if (!response.ok) throw new Error(`Failed to load module: ${moduleId}`);

            const scriptContent = await response.text();
            const scriptBlob = new Blob([scriptContent], { type: 'application/javascript' });
            const scriptUrl = URL.createObjectURL(scriptBlob);

            return this.executeModule(moduleId, scriptUrl);
        } catch (error) {
            console.error(`Error loading module ${moduleId}:`, error.message);
            throw error;
        }
    }

    async executeModule(moduleId, scriptUrl) {
        try {
            if (this.modules.has(moduleId)) {
                console.warn(`Module ${moduleId} is already loaded.`);
                return this.modules.get(moduleId);
            }

            await import(scriptUrl).then((moduleExports) => {
                this.modules.set(moduleId, moduleExports.default || moduleExports);
            }).catch(error => {
                throw new Error(`Error executing module ${scriptId}: ${error.message}`);
            });

            console.log(`Module ${moduleId} loaded successfully.`);
        } catch (error) {
            console.error(`Execution error for module ${moduleId}:`, error.message);
        }
    }

    async loadAndExecuteModules(modules) {
        const promises = modules.map(([moduleId, modulePath]) => this.loadModule(moduleId, modulePath));

        try {
            await Promise.all(promises);
            console.log('All modules loaded and executed successfully.');
        } catch (error) {
            console.error('Error in loading modules:', error.message);
        }
    }

    getModuleExports(moduleId) {
        return this.modules.get(moduleId) || null;
    }
}

// Usage example:
const loader = new ModuleLoader();
loader.loadAndExecuteModules([
    ['module1', '/path/to/module1'],
    ['module2', '/path/to/module2']
]);
