#include <arpa/inet.h>  // For gethostbyname
#include <pthread.h>

#define MAX_DNS_RETRY 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int populate_list(Node** head, int num_entries) {
    pthread_mutex_lock(&list_mutex);

    for (int i = 0; i < num_entries; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list_mutex);
            return -1;
        }

        memset(new_node->data.CRC_INDICATION_REL8_TAG, 0, sizeof(new_node->data.CRC_INDICATION_REL8_TAG));

        new_node->data.RX_UE_INFORMATION_TAG = rand() % 100;  // Example data
        new_node->data.RNTI = rand() % 1000;
        new_node->data.CRC_INDICATION_REL8_TAG[9] = (rand() % 2);  // Random CRCFLAG

        new_node->next = *head;
        *head = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int resolve_dns(const char* hostname, u_char ip_array[4]) {
    struct hostent *host;
    int retries = 0;

    do {
        host = gethostbyname(hostname);
        if (host) {
            memcpy(ip_array, host->h_addr_list[0], sizeof(u_char) * 4);
            return 0;
        }
        ++retries;
    } while (retries < MAX_DNS_RETRY);

    fprintf(stderr, "DNS resolution failed\n");
    return -1;
}

```

