['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 10000
#define TIMEOUT_PERIOD 300 // Timeout in seconds

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    ACTIVE,
    EXPIRED,
    PENDING
} SessionStatus;

typedef struct {
    unsigned int sessionID;
    time_t expirationTime;
    time_t lastActivityTimestamp;
    SessionStatus status;
} SessionTimeoutRecord;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PduList;

typedef struct {
    SessionTimeoutRecord *sessions;
    size_t sessionCount;
    pthread_mutex_t mutex;
} SessionManager;

void log_session_state_change(unsigned int sessionId, SessionStatus status) {
    printf("Session %u changed to status %d\n", sessionId, status);
}

PduList* initialize_pdu_list() {
    PduList *list = malloc(sizeof(PduList));
    list->pdus = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void free_pdu_list(PduList *list) {
    pthread_mutex_lock(&list->mutex);
    free(list->pdus);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

SessionManager* initialize_session_manager() {
    SessionManager *manager = malloc(sizeof(SessionManager));
    manager->sessions = calloc(MAX_SESSIONS, sizeof(SessionTimeoutRecord));
    manager->sessionCount = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void free_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager->sessions);
    free(manager);
}

unsigned int find_or_create_session(SessionManager *manager, unsigned int rnti) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->sessionCount; ++i) {
        if (manager->sessions[i].expirationTime == 0 && manager->sessions[i].status == EXPIRED) {
            manager->sessions[i].sessionID = rnti;
            manager->sessions[i].lastActivityTimestamp = time(NULL);
            manager->sessions[i].expirationTime = manager->sessions[i].lastActivityTimestamp + TIMEOUT_PERIOD;
            manager->sessions[i].status = ACTIVE;
            log_session_state_change(rnti, ACTIVE);

            pthread_mutex_unlock(&manager->mutex);
            return rnti;
        }
    }

    if (manager->sessionCount < MAX_SESSIONS) {
        unsigned int sessionId = ++manager->sessionCount;
        manager->sessions[sessionId].sessionID = rnti;
        manager->sessions[sessionId].lastActivityTimestamp = time(NULL);
        manager->sessions[sessionId].expirationTime = manager->sessions[sessionId].lastActivityTimestamp + TIMEOUT_PERIOD;
        manager->sessions[sessionId].status = ACTIVE;
        log_session_state_change(rnti, ACTIVE);

        pthread_mutex_unlock(&manager->mutex);
        return sessionId;
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0; // No available session
}

void update_sessions(SessionManager *manager) {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 1; i <= manager->sessionCount; ++i) {
        if (manager->sessions[i].status == ACTIVE && currentTime > manager->sessions[i].expirationTime) {
            manager->sessions[i].status = EXPIRED;
            log_session_state_change(manager->sessions[i].sessionID, EXPIRED);
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void populateNfadSessionTimeouts(PduList *pdu_list, SessionManager *session_manager) {
    for (size_t i = 0; i < pdu_list->count; ++i) {
