// C Function: Task Management

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} Task;

typedef struct Node {
    Task task;
    struct Node* next;
} Node;

Node* createTaskList(int N) {
    if (N <= 0) return NULL;

    Node *head = NULL, **ptr = &head;

    for (int i = 0; i < N; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            // Free allocated memory in case of failure
            while (*ptr != NULL) {
                Node *temp = *ptr;
                *ptr = (*ptr)->next;
                free(temp);
            }
            return NULL;
        }

        // Initialize the task with random CRCFLAG and fixed values for other fields
        newNode->task.RX_UE_INFORMATION_TAG = i;  // Example tag value
        newNode->task.RNTI = i + 1;               // Example RNTI value
        newNode->task.CRC_INDICATION_REL8_TAG = i * 2; // Example CRC indication value
        newNode->task.CRCFLAG = rand() % 2;

        newNode->next = NULL;
        *ptr = newNode;
        ptr = &newNode->next;
    }

    return head;
}

void freeTaskList(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
