    pthread_mutex_init(&darr->resize_lock, NULL);
}

void free_dynamic_array(DynamicArray *darr) {
    if (darr->array) {
        free(darr->array);
    }
    pthread_mutex_destroy(&darr->resize_lock);
}

bool resize_if_needed(DynamicArray *darr) {
    size_t current_count = atomic_load(&darr->count);
    if (current_count >= RESIZE_THRESHOLD && darr->capacity < MAX_ELEMENTS) {
        pthread_mutex_lock(&darr->resize_lock);
        size_t new_capacity = darr->capacity * 2;
