        if (!new_array) {
            perror("Failed to resize memory");
            pthread_mutex_unlock(&darr->resize_lock);
            return false;
        }

        darr->array = new_array;
        darr->capacity = new_capacity;
        pthread_mutex_unlock(&darr->resize_lock);
    }
    return true;
}

