    NFAPI_CRC_INDICATION_PDU_T *element = &darr->array[index];
    element->RX_UE_INFORMATION_TAG = rx_tag;
    element->RNTI = rnti;

    // Randomly set CRCFLAG ensuring no two adjacent flags are the same
    bool last_crc_flag = (index > 0) ? darr->array[index - 1].tag.CRCFLAG : false;
    element->tag.CRCFLAG = rand() % 2 != last_crc_flag;
    element->tag.CRC_INDICATION_REL8_TAG = rand() % 256; // Example value
}

void validate_array(DynamicArray *darr) {
    size_t count = atomic_load(&darr->count);
    for (size_t i = 0; i < count - 1; ++i) {
