#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
    const int max_size; // Maximum size of the list
    pthread_mutex_t mutex;
} CRCList;

// Function to initialize the list
CRCList* create_list(int max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Function to free the list
void destroy_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Function to calculate CRC indication
int calculate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu, int param1, int param2) {
    // Example CRC calculation based on parameters (dummy implementation)
    return (pdu->RX_UE_INFORMATION_TAG & param1) == (pdu->RNTI & param2);
}

// Function to add a new entry to the list
int add_to_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu, int param1, int param2) {
    if (!list || !pdu) return -1;

    // Validate CRC indication
    if (!calculate_crc(pdu, param1, param2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    // Add to the list
    if (list->size < list->max_size) {
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;
    } else {
        // Remove the oldest entry and add the new one
        Node* temp = list->head;
        list->head = list->head->next;

        if (list->head == NULL) {
            list->tail = NULL;
        }

        free(temp);
        list->tail->next = new_node;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Example function to simulate packet retrieval and processing
void process_packets(CRCList* list, int param1, int param2) {
    while (1) {
        // Simulate packet retrieval
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), 
                                           .RNTI = rand(),
                                           .CRC_INDICATION_REL8_TAG = rand() % 256,
                                           .CRCFLAG = rand() % 2 };

        // Add to list
        if (add_to_list(list, &pdu, param1, param2) != 0) {
            fprintf(stderr, "Failed to add packet to list\n");
        }

        // Simulate processing delay
        usleep(100000); // 100 ms
    }
}

int main() {
    int max_size = 10;
    CRCList* crc_list = create_list(max_size);

    if (!crc_list) {
        fprintf(stderr, "Failed to create list\n");
        return -1;
    }

    pthread_t thread_id;
    int param1 = 0xFF; // Example parameter
    int param2 = 0x0F;

    // Start packet processing in a separate thread
    if (pthread_create(&thread_id, NULL, (void*)process_packets, crc_list) != 0) {
        fprintf(stderr, "Failed to create processing thread\n");
        destroy_list(crc_list);
        return -1;
    }

    pthread_join(thread_id, NULL);

    destroy_list(crc_list);
    return 0;
}
