    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    size_t max_size;
} CRCIndicationList;

CRCIndicationList* create_list(size_t max_size) {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->max_size = max_size;

    return list;
}

int is_rnti_unique(CRCIndicationList* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

int add_crc_indication(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Maximum size exceeded.\n");
        return -1;
    }

    if (!is_rnti_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Duplicate RNTI detected.\n");
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -3;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(CRCIndicationList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int export_to_file(const char* filename, CRCIndicationList* list, const char* format) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(format, "binary") == 0) {
            fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        } else if (strcmp(format, "text") == 0) {
            fprintf(file, "%u %u %u %u\n",
                    current->data.RX_UE_INFORMATION_TAG,
                    current->data.RNTI,
                    current->data.CRC_INDICATION_REL8_TAG,
                    current->data.CRCFLAG);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0;
}

void populate_and_export_crc_indications(size_t max_size, const char* filename, const char* format) {
    CRCIndicationList* list = create_list(max_size);
    if (!list) return;

    srand(time(NULL));

    for (size_t i = 0; i < max_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        do {
            pdu.RNTI = rand() % MAX_RNTI;
        } while (!is_rnti_unique(list, pdu.RNTI));
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() & 1;

        if (add_crc_indication(list, pdu) != 0) {
            fprintf(stderr, "Failed to add CRC indication.\n");
            break;
        }
    }

    if (export_to_file(filename, list, format) != 0) {
        fprintf(stderr, "Failed to export data to file.\n");
    }

    free_list(list);
}
```

