        exit(EXIT_FAILURE);
    }

    int *numbers = NULL;
    int num_elements = 0;

    if (read_integers_from_file(file, &numbers, &num_elements) != 0) {
        free(numbers);
        fclose(file);
        exit(EXIT_FAILURE);
