int read_integers_from_file(FILE *file, int **numbers, int *num_elements) {
    if (fscanf(file, "%d", num_elements) != 1 || *num_elements <= 0 || *num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid number of elements\n");
        return -1;
    }

    *numbers = malloc(*num_elements * sizeof(int));
    if (!*numbers) {
        perror("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < *num_elements; ++i) {
        if (fscanf(file, "%d", &((*numbers)[i])) != 1) {
            fprintf(stderr, "Error reading integer at position %d\n", i);
            free(*numbers);
            return -1;
