#define MAX_MEMORY_USAGE 150 * 1024 // 150KB
#define MAX_RETRIES 3

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        int CRCFLAG; // Assume size can vary based on this flag
    } CRC_INDICATION_REL8_TAG;
