    return current_rnti++;
}

pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;
void *memory_pool = NULL;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_circ_indications(size_t num_structs) {
    size_t total_memory_usage = 0;
    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T); // Base size
    int retries = MAX_RETRIES;
    unsigned short *allocated_rntis = NULL;

    while (retries--) {
        pthread_mutex_lock(&rnti_lock);

        allocated_rntis = malloc(num_structs * sizeof(unsigned short));
        if (!allocated_rntis) {
            fprintf(stderr, "Memory allocation for RNTI tracking failed\n");
            pthread_mutex_unlock(&rnti_lock);
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T* list = realloc(memory_pool, num_structs * structure_size);

        if (list && (!memory_pool || memcmp(list, memory_pool, total_memory_usage) != 0)) {
            memory_pool = list;

            for (size_t i = 0; i < num_structs; ++i) {
                unsigned short rnti = get_available_rnti();

                // Ensure no duplicate RNTI
                int is_unique = 1;
                for (size_t j = 0; j < i && is_unique; ++j) {
                    if (allocated_rntis[j] == rnti)
                        is_unique = 0;
                }
                if (!is_unique) continue;

                allocated_rntis[i] = rnti;

                NFAPI_CRC_INDICATION_PDU_T* struct_ptr = &list[i];

                struct_ptr->RX_UE_INFORMATION_TAG = rand(); // Example value
                struct_ptr->RNTI = rnti;
                struct_ptr->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

                total_memory_usage += structure_size;
            }

            if (total_memory_usage <= MAX_MEMORY_USAGE) {
                return list;
            } else {
                fprintf(stderr, "Memory usage exceeded limit\n");
                free(allocated_rntis);
                pthread_mutex_unlock(&rnti_lock);
                continue; // Retry with a smaller number of structs
            }
        }

        if (memory_pool) {
            free(memory_pool);
            memory_pool = NULL;
        }

        fprintf(stderr, "Memory allocation failed\n");
        free(allocated_rntis);
        pthread_mutex_unlock(&rnti_lock);
    }

    if (allocated_rntis)
        free(allocated_rntis);

    return NULL; // Allocation failed after retries
}

void free_nfa_circ_indications(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        free(list);
        memory_pool = NULL;
    }
}
