['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    unsigned int CRC_CHECK;
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int max_elements;
} DynamicList;

#define DEFAULT_MAX_ELEMENTS 1000
#define SUCCESS 0
#define ALLOCATION_FAILURE -1

DynamicList* create_list(int max_elements) {
    if (max_elements <= 0)
        max_elements = DEFAULT_MAX_ELEMENTS;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list)
        return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_elements = max_elements;
    return list;
}

void destroy_list(DynamicList* list) {
    if (list) {
        pthread_mutex_lock(&list->lock);

        Node *current = list->head;
        while (current) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }

        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int is_rnti_unique(DynamicList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.rnti == rnti)
            return 0;
        current = current->next;
    }
    return 1;
}

int add_pdu(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.rnti))
        return ALLOCATION_FAILURE;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    int count = 0;
    while (current && count < list->max_elements - 1) {
        current = current->next;
        count++;
    }

    if (count >= list->max_elements - 1) {
        pthread_mutex_unlock(&list->lock);
        return ALLOCATION_FAILURE;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return ALLOCATION_FAILURE;
    }

    pdu.crc_rel8_tag.CRCFLAG = (pdu.crc_rel8_tag.CRC_CHECK & 1);

    new_node->data = pdu;
    new_node->next = current ? current : list->head;
    if (!current) {
        list->head = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return SUCCESS;
}

void* thread_function(void* arg) {
    DynamicList* list = (DynamicList*)arg;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.ue_info_tag.RNTI = rand() % 10000; // Example RNTI
    pdu.rnti = pdu.ue_info_tag.RNTI;
    pdu.crc_rel8_tag.CRC_CHECK = rand();   // Random CRC check value

    int result = add_pdu(list, pdu);
    if (result == SUCCESS) {
        printf("PDU with RNTI %u added successfully.\n", pdu.rnti);
    } else {
        fprintf(stderr, "Failed to add PDU due to memory allocation failure or duplicate RNTI.\n");
    }

    return NULL;
}

int main() {
    const int num_threads = 10; // Example number of threads
    pthread_t threads[num_threads];
    DynamicList* list = create_list(DEFAULT_MAX_ELEMENTS);

    if (!list) {
        fprintf(stderr, "Failed to initialize dynamic list.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, list);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(list);

    return EXIT_SUCCESS;
}
```

### Justification
- **Thread Safety**: The use of `pthread_mutex_t` provides a coarse-grained lock, which is simple to implement and minimizes lock contention in this scenario where list operations are not extremely fine-grained.
- **Memory Management**: Each node is dynamically allocated and deallocated safely. If memory allocation fails, the function returns an error code without crashing or leaking memory.
- **Unique RNTI Validation**: Before insertion, the list checks for unique `RNTI` values to prevent duplicates.
- **CRCFLAG Logic**: The flag is set only if its corresponding bit in `CRC_CHECK` is set. This ensures correctness based on input data conditions.

This design balances efficiency and simplicity while being scalable enough for moderate levels of concurrency without excessive lock contention.']

