#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_EVENTS M

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Configuration structure fetched from an external data source
typedef struct {
    float crcThreshold; // Configurable threshold for CRC flag setting
} Config;

Config fetchConfiguration() {
    Config config = {0.5}; // Default value or fetch from an external source
    // Add error handling and retry logic here if fetching fails
    return config;
}

// Mutex for synchronizing access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe queue implementation for managing events
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *events[MAX_EVENTS];
    int front, rear, size;
} EventQueue;

EventQueue eventQueue = {NULL, 0, -1, 0};

bool isFull(EventQueue *q) {
    return q->size == MAX_EVENTS;
}

bool isEmpty(EventQueue *q) {
    return q->size == 0;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T *event, EventQueue *q) {
    pthread_mutex_lock(&mutex);
    if (isFull(q)) {
        printf("Queue is full. Dropping event.\n");
        free(event); // Free memory if queue is full
        pthread_mutex_unlock(&mutex);
        return;
    }
    q->rear = (q->rear + 1) % MAX_EVENTS;
    q->events[q->rear] = event;
    q->size++;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(EventQueue *q) {
    NFAPI_CRC_INDICATION_PDU_T *event = NULL;
    pthread_mutex_lock(&mutex);
    if (isEmpty(q)) {
        printf("Queue is empty.\n");
        pthread_mutex_unlock(&mutex);
    } else {
        event = q->events[q->front];
        q->front = (q->front + 1) % MAX_EVENTS;
        q->size--;
    }
    pthread_mutex_unlock(&mutex);
    return event;
}

void* processEvent(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *event = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    if (event != NULL) {
        // Simulate CRC flag setting based on a probabilistic threshold
        Config config = fetchConfiguration();
        float randomValue = (float)rand() / RAND_MAX;
        event->tag.crcFlag = (randomValue < config.crcThreshold) ? 1 : 0;

        printf("Processed event with crcFlag: %d\n", event->tag.crcFlag);

        free(event); // Deallocate memory after processing
    }
    return NULL;
}

void initializeNetworkInterface() {
    pthread_t threads[MAX_EVENTS];
    int i;

    for (i = 0; i < MAX_EVENTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *event = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!event) {
            perror("Failed to allocate memory for event");
            continue;
        }

        enqueue(event, &eventQueue);

        // Create a thread to process each event
        int rc = pthread_create(&threads[i], NULL, processEvent, dequeue(&eventQueue));
        if (rc) {
            printf("Error: unable to create thread, %d\n", rc);
            free(event);  // Handle memory allocation failure by freeing the event
            continue;
        }
    }

    for (i = 0; i < MAX_EVENTS; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    initializeNetworkInterface();

    return 0;
}
