CRCList* create_list() {
    CRCList* list = malloc(sizeof(CRCList));
    if (list) {
        list->head = NULL;
        list->size = 0;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_index(CRCList* list, size_t index) {
    if (index >= list->size) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* result = (current) ? &(current->data) : NULL;
    pthread_mutex_unlock(&list->lock);

    return result;
}

bool remove_element_by_index(CRCList* list, size_t index) {
    if (index >= list->size) return false;

    Node *current = list->head, *prev = NULL;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < index && current != NULL; i++) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return true;
}

void iterate_and_print(CRCList* list, int stop_crc_flag) {
    Node* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* element = &current->data;

        printf("RX_UE_INFORMATION_TAG: %lu, RNTI: %hu, CRCFLAG: %d\n",
               element->ue_info.RX_UE_INFORMATION_TAG,
               element->ue_info.RNTI,
               element->crc_tag.CRCFLAG);

        if (element->crc_tag.CRCFLAG == stop_crc_flag) {
            break;
        }

        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
