#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>

#define MAX_LOG_BUFFER_SIZE 1024

typedef struct {
    time_t timestamp;
    int severity_level;
    char message[256];
} log_entry_t;

typedef struct log_queue_node {
    log_entry_t entry;
    struct log_queue_node* next;
} log_queue_node_t;

typedef struct {
    log_queue_node_t* head;
    log_queue_node_t* tail;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} log_queue_t;

typedef struct {
    log_queue_t queue;
    int active_threads;
    int max_threads;
    bool stop_flag;
} worker_pool_t;

log_queue_t* create_log_queue() {
    log_queue_t* queue = (log_queue_t*)malloc(sizeof(log_queue_t));
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->head = queue->tail = NULL;
    queue->size = 0;
    return queue;
}

void destroy_log_queue(log_queue_t* queue) {
    log_queue_node_t* current = queue->head;
    while (current != NULL) {
        log_queue_node_t* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

void enqueue_log_entry(log_queue_t* queue, log_entry_t entry) {
    log_queue_node_t* new_node = (log_queue_node_t*)malloc(sizeof(log_queue_node_t));
    new_node->entry = entry;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->size < MAX_LOG_BUFFER_SIZE) {
        if (queue->tail != NULL) {
            queue->tail->next = new_node;
        } else {
            queue->head = new_node;
        }
        queue->tail = new_node;
        queue->size++;
        pthread_cond_signal(&queue->cond);
    } else {
        free(new_node);
    }
    pthread_mutex_unlock(&queue->mutex);
}

log_entry_t dequeue_log_entry(log_queue_t* queue) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->head == NULL && !queue->stop_flag) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    if (queue->head != NULL) {
        log_queue_node_t* node = queue->head;
        log_entry_t entry = node->entry;

        queue->head = node->next;
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
        queue->size--;

        pthread_mutex_unlock(&queue->mutex);
        free(node);

        return entry;
    }

    pthread_mutex_unlock(&queue->mutex);

    log_entry_t empty_entry = {0};
    return empty_entry;
}

void* worker_thread(void* arg) {
    worker_pool_t* pool = (worker_pool_t*)arg;

    while (!pool->stop_flag) {
        log_entry_t entry = dequeue_log_entry(&pool->queue);
        if (entry.message[0] != '\0') {
            // Process the log entry
            printf("Processing: %s\n", entry.message);
        }
    }

    return NULL;
}

void initialize_worker_pool(worker_pool_t* pool, int max_threads) {
    pthread_mutex_init(&pool->mutex, NULL);
    pool->queue = *create_log_queue();
    pool->active_threads = 0;
    pool->max_threads = max_threads;
    pool->stop_flag = false;

    for (int i = 0; i < max_threads; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, worker_thread, pool)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
        pthread_detach(thread);
        pool->active_threads++;
    }
}

void shutdown_worker_pool(worker_pool_t* pool) {
    pthread_mutex_lock(&pool->mutex);

    pool->stop_flag = true;
    pthread_cond_broadcast(&pool->queue.cond);

    pthread_mutex_unlock(&pool->mutex);

    while (pool->active_threads > 0) {
        // Allow threads to finish
    }

    destroy_log_queue(&pool->queue);
}

int main() {
    worker_pool_t pool;
    initialize_worker_pool(&pool, 4);

    log_entry_t entry = { .timestamp = time(NULL), .severity_level = 1, .message = "Test Log" };
    enqueue_log_entry(&pool.queue, entry);

    // Simulate processing
    sleep(2);

    shutdown_worker_pool(&pool);
    return 0;
}
