#define MAX_EVENTS 10 // Maximum concurrent events

typedef struct {
    int sensor_id;
    uint8_t *data;   // Pointer to dynamically allocated data
    size_t length;   // Length of the data
    uint32_t checksum;
} SensorDataPDU_T;

// Mutex for synchronizing access to shared resources
pthread_mutex_t event_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t event_cond = PTHREAD_COND_INITIALIZER;

// Queue structure for managing events
typedef struct {
    SensorDataPDU_T *events[MAX_EVENTS];
    int front, rear, count;
} EventQueue;

EventQueue queue = {.front = 0, .rear = -1, .count = 0};

// Function prototypes
void enqueue(SensorDataPDU_T *event);
SensorDataPDU_T* dequeue(void);
uint32_t calculate_checksum(uint8_t *data, size_t length);
void process_event(SensorDataPDU_T *event);

// Thread function to process events
void* event_processor(void *arg) {
    while (1) {
        pthread_mutex_lock(&event_lock);

        // Wait for events in the queue
        while (queue.count == 0) {
            pthread_cond_wait(&event_cond, &event_lock);
        }

        SensorDataPDU_T *event = dequeue();

        if (event != NULL) {
            process_event(event);
            free(event->data);   // Deallocate memory for event data
            free(event);         // Deallocate memory for the entire PDU
        }

        pthread_mutex_unlock(&event_lock);
    }

    return NULL;
}

// Enqueue an event into the queue
void enqueue(SensorDataPDU_T *event) {
    if (queue.count < MAX_EVENTS) {
        pthread_mutex_lock(&event_lock);

        if (queue.rear == MAX_EVENTS - 1) {
            queue.rear = -1; // Wrap around
        }

        queue.events[++queue.rear] = event;
        queue.count++;

        pthread_cond_signal(&event_cond);
        pthread_mutex_unlock(&event_lock);
    } else {
        // Handle overflow scenario (e.g., drop or log)
    }
}

// Dequeue an event from the queue
SensorDataPDU_T* dequeue(void) {
    SensorDataPDU_T *event = NULL;

    if (queue.count > 0) {
        event = queue.events[queue.front];
        if (++queue.front == MAX_EVENTS) {
            queue.front = 0; // Wrap around
        }
        queue.count--;
    }

    return event;
}

// Calculate a simple checksum for the data
uint32_t calculate_checksum(uint8_t *data, size_t length) {
    uint32_t checksum = 0;
    while (length--) {
        checksum += *data++;
    }
    return checksum;
}

// Process an individual sensor event
void process_event(SensorDataPDU_T *event) {
    // Example processing: calculate and validate checksum
    uint32_t calculated_checksum = calculate_checksum(event->data, event->length);

    if (calculated_checksum != event->checksum) {
        printf("Checksum mismatch for sensor %d\n", event->sensor_id);
        // Handle error (e.g., log or retry)
    } else {
        // Process data normally
        printf("Processing sensor %d data with checksum %u\n", 
               event->sensor_id, calculated_checksum);
    }
}

// Function to simulate adding a new event from the sensor network
void add_sensor_event(int sensor_id, uint8_t *data, size_t length) {
    SensorDataPDU_T *new_event = malloc(sizeof(SensorDataPDU_T));
    if (new_event == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_event->sensor_id = sensor_id;
    new_event->data = malloc(length);
    if (new_event->data == NULL) {
        free(new_event);  // Free allocated PDU structure
        fprintf(stderr, "Data memory allocation failed\n");
        return;
    }

    memcpy(new_event->data, data, length);
    new_event->length = length;
    new_event->checksum = calculate_checksum(data, length);

    enqueue(new_event);
}

int main() {
    pthread_t threads[MAX_EVENTS];

    // Create threads to process events
    for (int i = 0; i < MAX_EVENTS; ++i) {
        if (pthread_create(&threads[i], NULL, event_processor, NULL) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    // Simulate sensor events
    uint8_t sample_data[] = {1, 2, 3, 4, 5};
    add_sensor_event(101, sample_data, sizeof(sample_data));

    // Join threads (in real use case, you might not join)
    for (int i = 0; i < MAX_EVENTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
