// Global variables for resource management and thread safety
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
static size_t current_count = 0;

void reset_pdu_list() {
    pthread_mutex_lock(&list_mutex);
    free(pdu_list);
    pdu_list = NULL;
    current_count = 0;
    pthread_mutex_unlock(&list_mutex);
}

// Function to generate a random number based on a seed
int rand_r(unsigned int *seed) {
    *seed = (*seed * 1103515245 + 12345) & 0x7fffffff;
    return (int)(*seed / 65536) % 32768; // Simulate C's rand() behavior with range [0, 32767]
}

// Function to check if an RNTI is already in the list
int rnti_exists(RNTI rnti, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdu_list[i].rnti == rnti)
            return 1;
    }
    return 0;
}

// Function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
int manage_nfaapi_crc_indication_pdu(int N, int M, unsigned int seed) {
    pthread_mutex_lock(&list_mutex);

    if (pdu_list != NULL) {
        free(pdu_list);
        pdu_list = NULL;
        current_count = 0;
    }

    pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        return -1; // Allocation failure
    }

    int unique_rnti_count = 0;
    for (int i = 0; i < N && unique_rnti_count < M; ++i) {
        RNTI rnti;
        do {
            rnti = rand_r(&seed) % (MAX_RNTI + 1);
        } while (rnti_exists(rnti, i));

        pdu_list[i].RX_UE_INFORMATION_TAG = rand_r(&seed); // Randomly generate a tag
        pdu_list[i].rnti = rnti;
        pdu_list[i].crc_indication_rel8_tag.CRCFLAG = rand_r(&seed) % 2; // Set CRC flag to 0 or 1 randomly

        unique_rnti_count++;
    }

    current_count = N;
    pthread_mutex_unlock(&list_mutex);
    return 0; // Success
}

// Example usage:
int main() {
    unsigned int seed = 12345; // Seed for random number generation
    int result = manage_nfaapi_crc_indication_pdu(10, 5, seed); // Manage list with N=10 and M=5

    if (result == 0) {
        printf("NFAPI_CRC_INDICATION_PDU_T structures managed successfully.\n");
    } else {
        printf("Failed to manage NFAPI_CRC_INDICATION_PDU_T structures.\n");
    }

    reset_pdu_list(); // Clear and free resources
    return 0;
}
