void log_message(CRC_Indication_Manager *manager, int level, const char *message) {
    if (level >= manager->log_level) {
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file);
    }
}

int add_element(CRC_Indication_Manager *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        log_message(manager, WARNING, "Max capacity reached. Removing oldest element.");
        memmove(manager->array, manager->array + 1, (manager->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->size--;
    }

    manager->array[manager->size] = element;
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    log_message(manager, INFO, "Element added.");
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(CRC_Indication_Manager *manager, size_t index) {
    if (index >= manager->size) {
        log_message(manager, ERROR, "Index out of bounds.");
        return NULL;
    }
    return &manager->array[index];
}

int remove_element(CRC_Indication_Manager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= manager->size) {
        pthread_mutex_unlock(&manager->lock);
        log_message(manager, ERROR, "Index out of bounds.");
        return -1;
    }

    memmove(manager->array + index, manager->array + index + 1, (manager->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size--;

    pthread_mutex_unlock(&manager->lock);
    log_message(manager, INFO, "Element removed.");
    return 0;
}

void iterate_elements(CRC_Indication_Manager *manager, uint8_t stop_crc_flag) {
    for (size_t i = 0; i < manager->size; i++) {
        if (manager->array[i].crc_tag.CRCFLAG == stop_crc_flag) {
