}

void serialize_state(CRC_Indication_Manager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&manager->size, sizeof(size_t), 1, file);
    fwrite(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->size, file);

    fclose(file);
}

int deserialize_state(CRC_Indication_Manager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t new_size;
    fread(&new_size, sizeof(size_t), 1, file);

    if (new_size > manager->capacity) {
        free(manager->array);
        manager->array = malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->capacity = new_size;
    }

    fread(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_size, file);
    manager->size = new_size;

    fclose(file);
    return 0;
}

void cleanup_manager(CRC_Indication_Manager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->array);
    if (manager->log_file != stdout && manager->log_file) {
        fclose(manager->log_file);
    }
    free(manager);
}
