    for (size_t i = 0; i < MAX_TRANSACTIONS; ++i) {
        transactions[i] = (Transaction){.transaction_id = i,
                                        .timestamp = time(NULL),
                                        .weighted_sum = rand() % 100 + 1};
    }

    process_transactions(&window, &metric, &logging, transactions, MAX_TRANSACTIONS);

    cleanup(&window, &metric, &logging);
    return 0;
}
```

### Key Points:
- **Sliding Window**: Uses a dynamic array with mutex locks for thread-safe operations.
- **Rate Metric**: Calculates the average transaction rate over a 60-second window using a lock for thread safety.
- **Logging Threshold**: Dynamically adjustable threshold for logging transactions.
- **Concurrency**: Utilizes `pthread_mutex_t` to ensure thread safety across multiple threads.
- **Transaction Verification**: Simulates an external verification process.
- **Memory Management**: Efficiently manages memory with dynamic allocation and cleanup functions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures[MAX_STRUCTURES];
    size_t count;
    pthread_mutex_t lock;
    unsigned int seed; // for reproducibility
} NFACache;

NFACache cache = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

unsigned char calculate_crcflag(unsigned int sequence_number) {
    return (sequence_number % 2 == 0) ? 1 : 0;
}

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int create_and_populate_nfa_cri_indications(size_t num_packets) {
    if (num_packets > MAX_STRUCTURES - cache.count) {
        num_packets = MAX_STRUCTURES - cache.count;
    }

    pthread_mutex_lock(&cache.lock);

    for (size_t i = 0; i < num_packets; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_error("Memory allocation failed.");
            // Clean up any partially allocated resources
            while (cache.count > 0) {
                free(cache.structures[--cache.count]);
            }
            pthread_mutex_unlock(&cache.lock);
            return -1;
        }

        pdu->RX_UE_INFORMATION_TAG = i; // Simple increment for illustration
        pdu->RNTI = cache.seed + i; // Ensure uniqueness with seed offset
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = calculate_crcflag(i);

        cache.structures[cache.count++] = pdu;
    }

    pthread_mutex_unlock(&cache.lock);
    return 0;
}

void initialize_nf_cache(unsigned int seed) {
    cache.seed = seed;
}

int main() {
    initialize_nf_cache(42); // Example seed for reproducibility

    if (create_and_populate_nfa_cri_indications(10) == 0) {
        printf("Structures created successfully.\n");
    } else {
        printf("Failed to create structures.\n");
    }

    // Cleanup
    pthread_mutex_lock(&cache.lock);
    for (size_t i = 0; i < cache.count; ++i) {
        free(cache.structures[i]);
    }
    pthread_mutex_unlock(&cache.lock);

    return 0;
}
```

