```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

#define MAX_ELEMENTS 100000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG; // Randomly set
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} List;

List* list_create() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void list_destroy(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int list_insert_sorted(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node** iter = &list->head;
    while (*iter && (*iter)->data.RNTI < data.RNTI) {
        iter = &(*iter)->next;
    }

    if (*iter && (*iter)->data.RNTI == data.RNTI) {
        // Merge or overwrite logic here
        pthread_mutex_unlock(&list->lock);
        return 0; // Indicate duplicate found and handled
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = *iter;
    *iter = new_node;

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 1; // Indicate successful insertion
}

int list_remove(List* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    Node** iter = &list->head;
    while (*iter && (*iter)->data.RNTI != RNTI) {
        iter = &(*iter)->next;
    }

    if (!*iter) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Indicate element not found
    }

    Node* to_remove = *iter;
    *iter = (*iter)->next;
    free(to_remove);

    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 1; // Indicate successful removal
}

size_t list_count(const List* list) {
    size_t count;
    pthread_mutex_lock(&list->lock);
    count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

void randomize_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Randomly set CRCFLAG
    pdu->CRCFLAG = rand() % 2; // Example: Set to 0 or 1 randomly
}

// Usage example
int main() {
    List* list = list_create();

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % MAX_ELEMENTS;
        pdu.CRC_INDICATION_REL8_TAG = rand();

        randomize_crcflag(&pdu);

        list_insert_sorted(list, pdu);
    }

    printf("Total elements: %zu\n", list_count(list));

    // Cleanup
    list_destroy(list);

    return 0;
}
```

